    // case-contract: test_task_creation_rejects_worktree_assigned_to_active_task | Adding a repository branch already assigned to another active task is rejected in the new conversation, and the existing task and repository reservation remain unchanged.
    func test_task_creation_rejects_worktree_assigned_to_active_task() throws {
        launchApp(defaultParent: fixture.parent.path)
        let branch = "active-shared-\(UUID().uuidString.prefix(8).lowercased())"
        let owner = try XCTUnwrap(try runCLI(["task", "create", "--title", "Active owner", "--prompt", "Fixture task description.", "--repo", fixture.primary.path, "--branch", "\(fixture.primary.path)=\(branch)"])["result"] as? [String: Any])
        let ownerID = try XCTUnwrap(owner["id"] as? String)
        openNewTaskConversation()
        chooseRepositorySuggestion("primary")
        let newTask = try XCTUnwrap(tasksFromBoardList().first { $0["id"] as? String != ownerID })
        let newTaskID = try XCTUnwrap(newTask["id"] as? String)
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 5))
        badge.click()
        element("conversation-repository-branch-edit").click()
        let branchField = element("conversation-repository-branch")
        replaceText(branchField, with: branch)
        element("conversation-repository-branch-save").click()
        let error = element("codex-chat-error")
        XCTAssertTrue(error.waitForExistence(timeout: 10))
        let errorText = error.label + (error.value as? String ?? "")
        XCTAssertTrue(errorText.contains("is already used by task \"Active owner\""), errorText)
        XCTAssertTrue(errorText.contains("`\(branch)`"), errorText)
        XCTAssertTrue(branchField.exists, "The user should be able to choose another branch after the conflict.")
        XCTAssertEqual(try repositoryRecord(taskID: ownerID, repositoryPath: fixture.primary.path)?["branch"] as? String, branch)
        XCTAssertEqual(try repositoryRecord(taskID: newTaskID, repositoryPath: fixture.primary.path)?["branch"] as? String, "auto")
        attachScreenshot(named: "An assigned worktree conflict preserves the new conversation repository settings")
    }

    // case-contract: test_task_creation_serializes_repository_branch_reservations | Two concurrent CLI/XPC creates targeting the same explicit branch in one repository serialize through a shared cross-process lock, leaving exactly one persisted active task and rejecting the other.
    func test_task_creation_serializes_repository_branch_reservations() throws {
        launchApp(defaultParent: fixture.parent.path)
        let branch = "concurrent-reservation-\(UUID().uuidString.prefix(8).lowercased())"
        let barrier = try RepositoryAllocationLockBarrier(dataDirectory: dataDirectory, repositoryURL: fixture.primary)
        var barrierReleased = false
        var processes: [RunningCLIProcess] = []
        defer {
            if !barrierReleased { try? barrier.release() }
            for running in processes where running.process.isRunning {
                running.process.terminate()
                running.process.waitUntilExit()
            }
        }

        for title in ["Reservation contender one", "Reservation contender two"] {
            processes.append(try startCLIProcess([
                "task", "create", "--title", title, "--prompt", "Fixture task description.",
                "--repo", fixture.primary.path,
                "--branch", "\(fixture.primary.path)=\(branch)",
            ]))
        }
        Thread.sleep(forTimeInterval: 1)
        XCTAssertTrue(processes.allSatisfy { $0.process.isRunning }, "Both creates should wait on the held repository allocation lock.")
        try barrier.release()
        barrierReleased = true

        let responses = try processes.map { try finishCLIProcess($0, expectedStatus: nil) }
        XCTAssertEqual(processes.map(\.process.terminationStatus).sorted(), [0, 2])
        let successful = responses.filter { $0["ok"] as? Bool == true }
        let rejected = try XCTUnwrap(responses.first { $0["ok"] as? Bool == false })
        XCTAssertEqual(successful.count, 1)
        assertCLIError(rejected, code: "invalid_argument")
        XCTAssertTrue(((rejected["error"] as? [String: Any])?["message"] as? String ?? "").contains("is already used by task"))

        let tasks = try tasksFromBoardList()
        XCTAssertEqual(tasks.count, 1)
        let taskID = try XCTUnwrap(tasks.first?["id"] as? String)
        let record = try XCTUnwrap((taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(record["branch"] as? String, branch)
        XCTAssertEqual(record["isPending"] as? Bool, true)
        let card = element("task-card-\(taskID.uppercased())")
        XCTAssertTrue(waitUntil({ card.exists }, timeout: 10), "Exactly one reservation should appear on the visible board.")
        clickTaskCardTitle(card)
        XCTAssertTrue(element("task-view-title").waitForExistence(timeout: 10))
    }

    // case-contract: test_persistence_store_open_failure_records_detailed_error | A real ModelContainer open failure against an isolated invalid store path returns an error and durably logs the phase, exact underlying NSError domain/code/userInfo, resolved store path, file/sidecar snapshot, and read-only schema probe failure; the paired visible UI case keeps Playhouse open on its normal board while the same isolated CLI/XPC request fails and verifies the persisted diagnostic.
    func test_persistence_store_open_failure_records_detailed_error() throws {
        launchApp(defaultParent: fixture.parent.path)
        let failureDirectory = dataDirectory.appendingPathComponent("invalid-store-open", isDirectory: true)
        try FileManager.default.createDirectory(at: failureDirectory, withIntermediateDirectories: true)
        let store = failureDirectory.appendingPathComponent("Playhouse-v2.store", isDirectory: true)
        try FileManager.default.createDirectory(at: store, withIntermediateDirectories: false)

        let failedResponse = try runCLI(
            ["task", "list"],
            expectedStatus: 1,
            extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": failureDirectory.path]
        )
        XCTAssertEqual(failedResponse["ok"] as? Bool, false)
        let diagnosticPath = failureDirectory.appendingPathComponent("Diagnostics.jsonl")
        let log = try String(contentsOf: diagnosticPath, encoding: .utf8)
        let events = try log.split(whereSeparator: \.isNewline).compactMap {
            try JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any]
        }
        let failedOpen = try XCTUnwrap(events.first { $0["event"] as? String == "persistence.store.open.failed" })
        XCTAssertEqual(failedOpen["phase"] as? String, "model-container-open")
        XCTAssertEqual(failedOpen["storePath"] as? String, store.path)
        XCTAssertEqual(failedOpen["storeFileExists"] as? String, "true")
        XCTAssertNotNil(failedOpen["storeWALExists"] as? String)
        XCTAssertNotNil(failedOpen["storeSHMExists"] as? String)
        XCTAssertNotNil(failedOpen["errorDescription"] as? String)
        XCTAssertNotNil(failedOpen["error0Domain"] as? String)
        XCTAssertNotNil(failedOpen["error0Code"] as? String)
        XCTAssertNotNil(failedOpen["error0UserInfoKeys"] as? String)
        XCTAssertNotNil(failedOpen["error0UserInfoKeyCount"] as? String)
        XCTAssertNotNil(failedOpen["error0UserInfo"] as? String)
        XCTAssertEqual(failedOpen["schemaProbeResult"] as? String, "open-failed")
        XCTAssertNotNil(failedOpen["schemaProbeSQLiteMessage"] as? String)
        XCTAssertEqual(app.state, .runningForeground, "The normal Playhouse app should remain open after the isolated CLI failure.")
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5), "The normal board should remain visible after the isolated CLI failure.")
    }

    // case-contract: test_persistence_read_failure_records_detailed_error | A real SwiftData fetch failure against an isolated store with a missing task column returns an error and logs a correlated read ID, NSError domain/code/userInfo, store path, file/sidecar snapshot, and the exact missing-column message from a read-only schema probe before the CLI/XPC request completes; the paired visible UI case keeps the normal task board open and verifies the same isolated failure record.
    func test_persistence_read_failure_records_detailed_error() throws {
        launchApp(defaultParent: fixture.parent.path)
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        let failureDirectory = dataDirectory.appendingPathComponent("fetch-failure", isDirectory: true)
        try FileManager.default.createDirectory(at: failureDirectory, withIntermediateDirectories: true)
        _ = try runCLI(
            ["task", "create", "--title", "Missing column read failure", "--prompt", "Fixture task description.", "--root", fixture.primary.path],
            extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": failureDirectory.path]
        )
        let store = failureDirectory.appendingPathComponent("Playhouse-v2.store")
        let corrupt = Process()
        corrupt.executableURL = URL(fileURLWithPath: "/usr/bin/sqlite3")
        corrupt.arguments = [store.path, "ALTER TABLE ZBOARDTASK DROP COLUMN ZPROGRESSLABEL"]
        let corruptOutput = Pipe()
        corrupt.standardOutput = corruptOutput
        corrupt.standardError = corruptOutput
        try corrupt.run()
        corrupt.waitUntilExit()
        let corruptionDetails = String(
            data: corruptOutput.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8
        ) ?? ""
        XCTAssertEqual(corrupt.terminationStatus, 0, "The isolated test store should lose its progress label column: \(corruptionDetails)")

        let failedResponse = try runCLI(
            ["task", "list"],
            expectedStatus: 1,
            extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": failureDirectory.path]
        )
        XCTAssertEqual(failedResponse["ok"] as? Bool, false)
        let diagnosticPath = failureDirectory.appendingPathComponent("Diagnostics.jsonl")
        let log = try String(contentsOf: diagnosticPath, encoding: .utf8)
        let events = try log.split(whereSeparator: \.isNewline).compactMap {
            try JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any]
        }
        let failedRead = try XCTUnwrap(events.first {
            $0["event"] as? String == "persistence.read.failed"
                && $0["operation"] as? String == "BoardTaskManager.list"
        })
        let readID = try XCTUnwrap(failedRead["readID"] as? String)
        XCTAssertEqual(failedRead["storePath"] as? String, store.path)
        XCTAssertEqual(failedRead["storeFileExists"] as? String, "true")
        XCTAssertNotNil(failedRead["storeWALExists"] as? String)
        XCTAssertNotNil(failedRead["storeSHMExists"] as? String)
        XCTAssertNotNil(failedRead["errorDescription"] as? String)
        XCTAssertNotNil(failedRead["error0Domain"] as? String)
        XCTAssertNotNil(failedRead["error0Code"] as? String)
        XCTAssertNotNil(failedRead["error0UserInfoKeys"] as? String)
        XCTAssertNotNil(failedRead["error0UserInfoKeyCount"] as? String)
        XCTAssertNotNil(failedRead["error0UserInfo"] as? String)
        XCTAssertEqual(failedRead["schemaProbeResult"] as? String, "prepare-failed")
        XCTAssertEqual(failedRead["schemaProbeSQLiteCode"] as? String, "1")
        XCTAssertTrue((failedRead["schemaProbeSQLiteMessage"] as? String)?.contains("no such column: t0.ZPROGRESSLABEL") == true)
        XCTAssertTrue(events.contains {
            $0["event"] as? String == "persistence.read.started"
                && $0["readID"] as? String == readID
                && $0["storePath"] as? String == store.path
        }, "The error should correlate to its started store read.")
        XCTAssertEqual(app.state, .runningForeground, "The normal app should stay open while the isolated bridge store fails.")
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5), "The normal app board should stay available while the isolated bridge store fails.")
    }

    // case-contract: test_legacy_store_import_failure_preserves_original | An invalid legacy database fails import without changing the source or publishing a destination or partial snapshot; the normal isolated board remains usable.
    func test_legacy_store_import_failure_preserves_original() throws {
        launchApp(defaultParent: fixture.parent.path)
        let failure = dataDirectory.appendingPathComponent("invalid-legacy", isDirectory: true)
        try FileManager.default.createDirectory(at: failure, withIntermediateDirectories: true)
        let source = failure.appendingPathComponent("Playhouse.store")
        let contents = Data("Not a SQLite database".utf8)
        try contents.write(to: source)
        let response = try runCLI(["task", "list"], expectedStatus: 1, extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": failure.path])
        XCTAssertEqual(response["ok"] as? Bool, false)
        XCTAssertEqual(try Data(contentsOf: source), contents)
        XCTAssertFalse(FileManager.default.fileExists(atPath: failure.appendingPathComponent("Playhouse-v2.store").path))
        XCTAssertFalse(try FileManager.default.contentsOfDirectory(atPath: failure.path).contains { $0.hasPrefix(".store-import-") })
        XCTAssertEqual(app.state, .runningForeground)
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        openNewTaskConversation()
        chooseRepositorySuggestion("primary")
        saveNewTaskPromptAndReturnToBoard("Healthy board", prompt: "Still usable")
        openTask(named: "Healthy board")
        XCTAssertEqual(element("message-composer").value as? String, "Still usable")
    }

    // case-contract: test_task_store_repairs_missing_pending_prompt_column | A real legacy SwiftData task store with in-progress timing columns and no submitted-prompt column waits for the store-write lock while CLI/XPC reads concurrently; migration backs up before adding the missing VARCHAR prompt column as nullable with no default and preserves elapsed time at zero. The CLI preserves the task and draft, and the visible app opens the migrated store and preserves the draft through a subsequent restart with duration still zero; metadata advances and later opens create no additional backup. The store is imported once into the protected filename and the legacy database remains unchanged. Committed WAL-only draft data survives import, and a subsequent edited draft survives restart without reimport.
    func test_task_store_repairs_missing_pending_prompt_column() throws {
        let title = "Legacy pending prompt store"
        let draft = "Committed WAL draft must survive import."
        let seeder = WorkspaceFixture.root.appendingPathComponent("seed-legacy-task-store")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: seeder.path))
        let seed = Process()
        seed.executableURL = seeder
        seed.arguments = [dataDirectory.path]
        let seedOutput = Pipe()
        seed.standardOutput = seedOutput
        seed.standardError = seedOutput
        try seed.run()
        seed.waitUntilExit()
        let seeded = String(data: seedOutput.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        XCTAssertEqual(seed.terminationStatus, 0, seeded)
        let taskID = seeded.trimmingCharacters(in: .whitespacesAndNewlines)
        let store = dataDirectory.appendingPathComponent("Playhouse-v2.store")
        let legacyStore = dataDirectory.appendingPathComponent("Playhouse.store")
        func sqlite(_ statement: String, at databaseURL: URL) throws -> String {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/sqlite3")
            process.arguments = [databaseURL.path, statement]
            let output = Pipe()
            process.standardOutput = output
            process.standardError = output
            try process.run()
            process.waitUntilExit()
            let text = String(data: output.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            XCTAssertEqual(process.terminationStatus, 0, "SQLite fixture operation failed: \(text)")
            return text
        }
        let legacyColumns = try sqlite("PRAGMA table_info(ZBOARDTASK)", at: legacyStore)
        XCTAssertFalse(legacyColumns.contains("ZPENDINGSUBMITTEDPROMPT"))
        XCTAssertTrue(legacyColumns.contains("ZINPROGRESSSTARTEDAT"))
        XCTAssertTrue(legacyColumns.contains("ZTOTALINPROGRESSSECONDS"))
        XCTAssertEqual(try sqlite("SELECT count(*) FROM ZBOARDTASK", at: legacyStore).trimmingCharacters(in: .whitespacesAndNewlines), "1")
        let legacyMetadata = try sqlite("SELECT hex(Z_PLIST) FROM Z_METADATA", at: legacyStore)
        var wal: OpaquePointer?
        XCTAssertEqual(sqlite3_open(legacyStore.path, &wal), SQLITE_OK)
        defer { sqlite3_close(wal) }
        XCTAssertEqual(sqlite3_exec(wal, "PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0; UPDATE ZBOARDTASK SET ZSAVEDPROMPT='Committed WAL draft must survive import.'", nil, nil, nil), SQLITE_OK)
        XCTAssertGreaterThan(try Data(contentsOf: URL(fileURLWithPath: legacyStore.path + "-wal")).count, 0)
        let legacyBytes = try Data(contentsOf: legacyStore)

        let writeBarrier = try TaskStoreWriteLockBarrier(dataDirectory: dataDirectory)
        defer { try? writeBarrier.release() }
        let pendingRead = try startCLIProcess(["task", "get", taskID])
        XCTAssertTrue(waitUntil({
            guard let events = try? self.diagnosticEvents() else { return false }
            return events.contains { $0["event"] as? String == "persistence.store.schema_migration.waiting_for_write_lock" }
        }, timeout: 15), "The XPC opener should wait for the held store-write lock.")
        XCTAssertTrue(pendingRead.process.isRunning)
        XCTAssertTrue(pendingRead.process.isRunning)
        try writeBarrier.release()
        let concurrentRead = try finishCLIProcess(pendingRead)
        XCTAssertEqual((concurrentRead["result"] as? [String: Any])?["savedPrompt"] as? String, draft)
        launchApp(defaultParent: fixture.parent.path)
        assertTaskVisible(title, inColumn: "Backlog")
        let backups = try FileManager.default.contentsOfDirectory(at: dataDirectory, includingPropertiesForKeys: nil)
            .filter { $0.lastPathComponent.hasPrefix("Playhouse.store.before-pending-prompt-") && $0.pathExtension == "backup" }
        XCTAssertEqual(backups.count, 1)
        if let backup = backups.first {
            XCTAssertEqual(try sqlite("PRAGMA quick_check", at: backup).trimmingCharacters(in: .whitespacesAndNewlines), "ok")
            XCTAssertEqual(try sqlite("SELECT count(*) FROM ZBOARDTASK", at: backup).trimmingCharacters(in: .whitespacesAndNewlines), "1")
            let backupColumns = try sqlite("PRAGMA table_info(ZBOARDTASK)", at: backup)
            XCTAssertFalse(backupColumns.contains("ZPENDINGSUBMITTEDPROMPT"))
            XCTAssertTrue(backupColumns.contains("ZINPROGRESSSTARTEDAT"))
            XCTAssertTrue(backupColumns.contains("ZTOTALINPROGRESSSECONDS"))
        }
        let migratedColumns = try sqlite("PRAGMA table_info(ZBOARDTASK)", at: store)
        XCTAssertTrue(migratedColumns.contains("ZPENDINGSUBMITTEDPROMPT"))
        XCTAssertTrue(migratedColumns.contains("ZINPROGRESSSTARTEDAT"))
        XCTAssertTrue(migratedColumns.contains("ZTOTALINPROGRESSSECONDS"))
        let migratedColumnRows = migratedColumns
            .split(whereSeparator: \.isNewline)
            .map { $0.split(separator: "|", omittingEmptySubsequences: false).map(String.init) }
        let promptColumn = try XCTUnwrap(migratedColumnRows.first { $0.count >= 6 && $0[1] == "ZPENDINGSUBMITTEDPROMPT" })
        XCTAssertEqual(promptColumn[2], "VARCHAR")
        XCTAssertEqual(Double(promptColumn[3]), 0.0)
        XCTAssertEqual(promptColumn[4], "")
        let durationColumn = try XCTUnwrap(
            migratedColumnRows.first { $0.count >= 6 && $0[1] == "ZTOTALINPROGRESSSECONDS" }
        )
        XCTAssertEqual(durationColumn[2], "FLOAT")
        XCTAssertEqual(Double(durationColumn[3]), 0.0)
        XCTAssertEqual(durationColumn[4], "")
        XCTAssertEqual(
            Double(try sqlite("SELECT ZTOTALINPROGRESSSECONDS FROM ZBOARDTASK", at: store).trimmingCharacters(in: .whitespacesAndNewlines)),
            0.0
        )
        XCTAssertNotEqual(try sqlite("SELECT hex(Z_PLIST) FROM Z_METADATA", at: store), legacyMetadata)
        XCTAssertEqual(try Data(contentsOf: legacyStore), legacyBytes)
        let migrationEvents = try diagnosticEvents()
        XCTAssertTrue(migrationEvents.contains { $0["event"] as? String == "persistence.store.schema_migration.write_lock_acquired" })
        XCTAssertFalse(migrationEvents.contains {
            ["persistence.store.open.failed", "persistence.read.failed"].contains($0["event"] as? String ?? "")
        })
        XCTAssertEqual(try taskRecord(id: taskID)?["savedPrompt"] as? String, draft)
        openTask(named: title)
        XCTAssertEqual(element("message-composer").value as? String, draft)

        let composer = element("message-composer")
        composer.click()
        composer.typeKey("a", modifierFlags: .command)
        composer.typeText("Edited after import")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        XCTAssertEqual(try taskRecord(id: taskID)?["savedPrompt"] as? String, "Edited after import")
        XCTAssertTrue(terminateAppAndWait(app))
        launchApp(defaultParent: fixture.parent.path)
        assertTaskVisible(title, inColumn: "Backlog")
        openTask(named: title)
        XCTAssertEqual(element("message-composer").value as? String, "Edited after import")
        XCTAssertEqual(
            Double(try sqlite("SELECT ZTOTALINPROGRESSSECONDS FROM ZBOARDTASK", at: store).trimmingCharacters(in: .whitespacesAndNewlines)),
            0.0
        )
        XCTAssertEqual(try diagnosticEvents().filter { $0["event"] as? String == "persistence.store.legacy_imported" }.count, 1)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(at: dataDirectory, includingPropertiesForKeys: nil)
            .filter { $0.lastPathComponent.hasPrefix("Playhouse.store.before-pending-prompt-") && $0.pathExtension == "backup" }.count, 1)
    }

    // case-contract: test_test_bundle_rejects_unisolated_data_directory | A test-built Playhouse service rejects a data directory outside the temporary test area and a linked store inside it before creating or opening either store; the visible app remains on its isolated board and can still read its tasks.
    func test_test_bundle_rejects_unisolated_data_directory() throws {
        launchApp(defaultParent: fixture.parent.path)
        let title = "Isolated board remains available"
        let created = try runCLI(["task", "create", "--title", title, "--prompt", "Fixture task description."])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        assertTaskVisible(title, inColumn: "Backlog")

        let caches = try FileManager.default.url(for: .cachesDirectory, in: .userDomainMask, appropriateFor: nil, create: true)
        let unsafe = caches.appendingPathComponent("Playhouse-bridge-guard-\(UUID().uuidString)", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: unsafe.path))
        try FileManager.default.createDirectory(at: unsafe, withIntermediateDirectories: false)
        let marker = unsafe.appendingPathComponent(".playhouse-test-owner")
        try "Playhouse bridge guard test (v1).\n".write(to: marker, atomically: true, encoding: .utf8)
        defer {
            if (try? String(contentsOf: marker, encoding: .utf8)) == "Playhouse bridge guard test (v1).\n" {
                try? FileManager.default.removeItem(at: unsafe)
            } else {
                XCTFail("Refusing to remove a guard fixture without its ownership marker.")
            }
        }
        let denied = try runCLI(
            ["board", "list"], expectedStatus: 1,
            extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": unsafe.path]
        )
        XCTAssertEqual(denied["error"] as? [String: String], [
            "code": "operation_failed",
            "message": "A Playhouse test bundle requires an isolated temporary data directory."
        ])
        XCTAssertFalse(FileManager.default.fileExists(atPath: unsafe.appendingPathComponent("Playhouse-v2.store").path))
        let linked = dataDirectory.appendingPathComponent("linked-store", isDirectory: true)
        try FileManager.default.createDirectory(at: linked, withIntermediateDirectories: false)
        try FileManager.default.createSymbolicLink(
            at: linked.appendingPathComponent("Playhouse-v2.store"),
            withDestinationURL: unsafe.appendingPathComponent("Playhouse-v2.store")
        )
        let linkedDenied = try runCLI(
            ["board", "list"], expectedStatus: 1,
            extraEnvironment: ["PLAYHOUSE_DATA_DIRECTORY": linked.path]
        )
        XCTAssertEqual(linkedDenied["error"] as? [String: String], [
            "code": "operation_failed",
            "message": "A Playhouse test bundle cannot open a linked task store."
        ])
        XCTAssertFalse(FileManager.default.fileExists(atPath: unsafe.appendingPathComponent("Playhouse-v2.store").path))
        XCTAssertEqual(try taskRecord(id: taskID)?["title"] as? String, title)
        assertTaskVisible(title, inColumn: "Backlog")
    }

    // case-contract: test_task_store_serializes_cross_process_writes | If another process holds the shared task-store write lock when a Codex turn completes after an explicit completed outcome, final status persistence waits and then saves Review status and full history across fresh CLI/XPC reads. Correlated persistence diagnostics include task ID, store path, lock wait, attempts, and retry count; task reads correlate started and completed events by read ID and store path, while failed reads include store file and sidecar state. Reopening the conversation in the UI shows the saved exchange without a store error.
    func test_task_store_serializes_cross_process_writes() throws {
        let fixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-store-write-success-wait")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: fixtureExecutable.path))
        let ready = URL(fileURLWithPath: fixtureExecutable.path + ".resolve-ready")
        let continuation = URL(fileURLWithPath: fixtureExecutable.path + ".resolve-continue")
        try? FileManager.default.removeItem(at: ready)
        try? FileManager.default.removeItem(at: continuation)

        let title = "Store write contention"
        _ = try runCLI(["settings", "set-parent", fixture.parent.path])
        let created = try XCTUnwrap(
            try runCLI(["task", "create", "--title", title, "--prompt", "Fixture task description.", "--repo", fixture.primary.path])["result"] as? [String: Any]
        )
        let taskID = try XCTUnwrap(created["id"] as? String)
        codexFixtureExecutable = fixtureExecutable.path
        let prompt = "Persist this completed turn."
        let process = try startCLIProcess(
            ["conversation", "send", taskID, "--message", prompt],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": fixtureExecutable.path]
        )
        var barrier: TaskStoreWriteLockBarrier?
        var barrierReleased = false
        defer {
            if !barrierReleased { try? barrier?.release() }
            if process.process.isRunning {
                process.process.terminate()
                process.process.waitUntilExit()
            }
        }

        let fixturePaused = waitUntil({ FileManager.default.fileExists(atPath: ready.path) }, timeout: 25)
        let fixtureDiagnostics = (try? diagnosticEvents().filter { ($0["event"] as? String)?.hasPrefix("codex.") == true }) ?? []
        var cliFailureDetails = "CLI still running"
        if !process.process.isRunning {
            let output = String(data: process.stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let errorOutput = String(data: process.stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            cliFailureDetails = "exit=\(process.process.terminationStatus), stdout=\(output), stderr=\(errorOutput)"
        }
        XCTAssertTrue(fixturePaused, "The app-server fixture should pause during the active Codex turn. CLI: \(cliFailureDetails); Codex diagnostics: \(fixtureDiagnostics.suffix(12))")
        let outcome = try runCLI(["task", "outcome", taskID, "completed"])
        XCTAssertEqual((outcome["result"] as? [String: Any])?["outcome"] as? String, "completed")
        barrier = try TaskStoreWriteLockBarrier(dataDirectory: dataDirectory)
        try "Release the completed fixture turn.\n".write(to: continuation, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains {
                $0["event"] as? String == "codex.turn.ended"
                    && $0["threadID"] as? String == "00000000-0000-0000-0000-000000000001"
                    && $0["turnStatus"] as? String == "completed"
            }) == true
        }, timeout: 15), "Codex should finish before the task's final status save.")
        Thread.sleep(forTimeInterval: 0.2)
        XCTAssertTrue(process.process.isRunning, "Final task status persistence should wait for the shared store write lock.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress")

        try barrier?.release()
        barrierReleased = true
        let response = try finishCLIProcess(process)
        XCTAssertEqual(response["ok"] as? Bool, true)
        let finalTask = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(finalTask["status"] as? String, "Review")
        XCTAssertNil(finalTask["pendingSubmittedPrompt"] as? String)
        let history = try runCLI(
            ["conversation", "history", taskID],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": fixtureExecutable.path]
        )["result"] as? [String: Any]
        let messages = try XCTUnwrap(history?["messages"] as? [[String: Any]])
        XCTAssertTrue(messages.contains { $0["role"] as? String == "user" && $0["text"] as? String == prompt })
        XCTAssertTrue(messages.contains {
            $0["role"] as? String == "assistant" && $0["text"] as? String == "Answers received: Blue / fixture-secret."
        })
        let lockEvents = try diagnosticEvents().filter {
            $0["taskID"] as? String == taskID && $0["event"] as? String == "persistence.write.lock_acquired"
        }
        let waitedWrite = try XCTUnwrap(lockEvents.first {
            (Int($0["lockWaitMilliseconds"] as? String ?? "0") ?? 0) > 0
        }, "The final task write should log its wait for the shared store lock.")
        XCTAssertEqual(waitedWrite["storePath"] as? String, dataDirectory.appendingPathComponent("Playhouse-v2.store").path)
        let waitedWriteID = try XCTUnwrap(waitedWrite["writeID"] as? String)
        let matchingWrite = try XCTUnwrap(try diagnosticEvents().first {
            $0["taskID"] as? String == taskID
                && $0["event"] as? String == "persistence.write.succeeded"
                && $0["writeID"] as? String == waitedWriteID
        })
        XCTAssertEqual(matchingWrite["attemptCount"] as? String, "1")
        XCTAssertEqual(matchingWrite["retryCount"] as? String, "0")

        let readEvents = try diagnosticEvents().filter {
            $0["taskID"] as? String == taskID
                && $0["operation"] as? String == "BoardTaskManager.requireTask"
                && ["persistence.read.started", "persistence.read.succeeded"].contains($0["event"] as? String ?? "")
        }
        let successfulRead = try XCTUnwrap(readEvents.first { $0["event"] as? String == "persistence.read.succeeded" })
        let readID = try XCTUnwrap(successfulRead["readID"] as? String)
        let matchingReadStart = try XCTUnwrap(readEvents.first {
            $0["event"] as? String == "persistence.read.started" && $0["readID"] as? String == readID
        })
        let expectedStorePath = dataDirectory.appendingPathComponent("Playhouse-v2.store").path
        let snapshotPrefixes = ["storeDirectory", "storeFile", "storeWAL", "storeSHM"]
        for readEvent in [matchingReadStart, successfulRead] {
            XCTAssertEqual(readEvent["storePath"] as? String, expectedStorePath)
            for key in readEvent.keys {
                XCTAssertFalse(snapshotPrefixes.contains { key.hasPrefix($0) }, "Successful read events should omit filesystem snapshot field \(key).")
            }
        }
        XCTAssertNotNil(successfulRead["durationMilliseconds"] as? String)

        launchApp(defaultParent: fixture.parent.path)
        openTask(named: title)
        XCTAssertTrue(element("task-view-title").waitForExistence(timeout: 10))
        let savedPrompt = app.textViews.matching(NSPredicate(format: "value == %@", prompt)).firstMatch
        XCTAssertTrue(savedPrompt.waitForExistence(timeout: 10), "The saved user message should render after reopening the conversation.")
        let savedAnswer = app.descendants(matching: .any).matching(
            NSPredicate(
                format: "identifier BEGINSWITH %@ AND label == %@",
                "assistant-message-",
                "Answers received: Blue / fixture-secret."
            )
        ).firstMatch
        XCTAssertTrue(savedAnswer.waitForExistence(timeout: 10), "The saved assistant reply should render after reopening the conversation.")
        XCTAssertFalse(element("codex-chat-error").exists, "A recovered store write must not leave a conversation error banner.")
        attachScreenshot(named: "Conversation status and history persist after shared store contention")
    }

    // case-contract: test_task_worktree_preparation_serializes_auto_branch_claims | Tasks with the same automatic branch choice remain pending without creating a worktree before conversation start. When one task has claimed the generated branch, a send from the other (through the CLI) succeeds with its own suffixed branch and a separate worktree, leaving both tasks started; the opt-in live provider integration sends both turns concurrently and confirms each task gets a distinct branch and worktree.
    func test_task_worktree_preparation_serializes_auto_branch_claims() throws {
        launchApp(defaultParent: fixture.parent.path)
        let existingWorktreeCount = try runGitOutput(fixture.primary, "worktree", "list", "--porcelain")
            .components(separatedBy: "worktree ").count - 1
        let title = "Concurrent auto branch \(UUID().uuidString.prefix(8).lowercased())"
        var taskIDs: [String] = []
        for _ in 0..<2 {
            let created = try runCLI(["task", "create", "--title", title, "--prompt", "Fixture task description.", "--repo", fixture.primary.path])["result"] as? [String: Any]
            taskIDs.append(try XCTUnwrap(created?["id"] as? String))
        }

        if isLiveIntegration {
            for taskID in taskIDs { try useLiveProvider(taskID: taskID) }
            let barrier = try RepositoryAllocationLockBarrier(dataDirectory: dataDirectory, repositoryURL: fixture.primary)
            var barrierReleased = false
            var processes: [RunningCLIProcess] = []
            defer {
                if !barrierReleased { try? barrier.release() }
                for running in processes where running.process.isRunning {
                    running.process.terminate()
                    running.process.waitUntilExit()
                }
            }

            for taskID in taskIDs {
                processes.append(try startCLIProcess([
                    "conversation", "send", taskID, "--message",
                    "Inspect the repository and respond exactly READY. Do not change any files.", "--mode", "plan",
                ]))
            }
            Thread.sleep(forTimeInterval: 1)
            XCTAssertTrue(processes.allSatisfy { $0.process.isRunning }, "Both live Codex turns should wait before preparing their shared auto branch.")
            try barrier.release()
            barrierReleased = true

            let responses = try processes.map { try finishCLIProcess($0, expectedStatus: nil) }
            XCTAssertEqual(processes.map(\.process.terminationStatus).sorted(), [0, 0])
            XCTAssertTrue(responses.allSatisfy { $0["ok"] as? Bool == true }, "Both live turns should start with their own branch.")
        }

        let tasks = try taskIDs.map { try XCTUnwrap(taskRecord(id: $0)) }
        if !isLiveIntegration {
            XCTAssertTrue(tasks.allSatisfy { (($0["repositoryWorktrees"] as? [[String: Any]])?.first?["isPending"] as? Bool) == true })
            XCTAssertTrue(tasks.allSatisfy { ($0["repositoryWorktrees"] as? [[String: Any]])?.first?["branch"] as? String == "auto" })
            XCTAssertTrue(tasks.allSatisfy { ($0["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String == fixture.primary.path })
            XCTAssertTrue(tasks.allSatisfy { $0["status"] as? String == "Backlog" })
            XCTAssertEqual(
                try runGitOutput(fixture.primary, "worktree", "list", "--porcelain").components(separatedBy: "worktree ").count - 1,
                existingWorktreeCount,
                "Same-title pending tasks must not reserve a branch or create worktrees before their first conversation turn."
            )
            for taskID in taskIDs {
                let card = element("task-card-\(taskID.uppercased())")
                XCTAssertTrue(card.waitForExistence(timeout: 10), "Pending tasks should remain visible on the board before conversation start.")
            }

            // Materialize the first task's generated branch, then start the second:
            // it must get its own suffixed branch and worktree instead of a rejection.
            codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
            let winnerID = taskIDs[0]
            let loserID = taskIDs[1]
            _ = try runCLI(["conversation", "send", winnerID, "--message", "Claim the generated branch.", "--answer", "color=Blue", "--answer", "token=fixture-secret"])
            let claimed = try XCTUnwrap((try taskRecord(id: winnerID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            XCTAssertEqual(claimed["isPending"] as? Bool, false)
            let claimedCount = try runGitOutput(fixture.primary, "worktree", "list", "--porcelain").components(separatedBy: "worktree ").count - 1
            XCTAssertEqual(claimedCount, existingWorktreeCount + 1)
            _ = try runCLI(["conversation", "send", loserID, "--message", "Claim the same generated title.", "--answer", "color=Blue", "--answer", "token=fixture-secret"])
            let started = try XCTUnwrap((try taskRecord(id: loserID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            XCTAssertEqual(started["isPending"] as? Bool, false)
            XCTAssertNotEqual(started["branch"] as? String, claimed["branch"] as? String)
            XCTAssertNotEqual(started["worktreePath"] as? String, claimed["worktreePath"] as? String)
            XCTAssertEqual(try runGitOutput(fixture.primary, "worktree", "list", "--porcelain").components(separatedBy: "worktree ").count - 1, claimedCount + 1)
            return
        }
    }

    // case-contract: test_auto_branch_gets_suffix_when_name_is_taken | Two tasks with the same title and an automatic branch on one repository both start: the first gets the title slug, the second a fresh branch named like the slug plus a hyphen and four lowercase letters or digits, in a different worktree. An existing local branch named like the slug, with no task using it, is never checked out: a new automatic task gets a suffixed fresh branch started from its branch-from. The visible task conversation shows the resolved suffixed branch.
    func test_auto_branch_gets_suffix_when_name_is_taken() throws {
        launchApp(defaultParent: fixture.parent.path)
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let token = UUID().uuidString.prefix(8).lowercased()
        let title = "Suffix branch \(token)"
        let slug = "suffix-branch-\(token)"
        func startTask(_ title: String, branchFrom: String? = nil) throws -> (id: String, record: [String: Any]) {
            var command = ["task", "create", "--title", title, "--prompt", "Fixture task description.", "--repo", fixture.primary.path]
            if let branchFrom { command += ["--branch-from", "\(fixture.primary.path)=\(branchFrom)"] }
            let created = try XCTUnwrap(try runCLI(command)["result"] as? [String: Any])
            let id = try XCTUnwrap(created["id"] as? String)
            _ = try runCLI(["conversation", "send", id, "--message", "Start this task.", "--answer", "color=Blue", "--answer", "token=fixture-secret"])
            let record = try XCTUnwrap((try taskRecord(id: id)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            return (id, record)
        }
        func isSuffixed(_ branch: String, of slug: String) -> Bool {
            branch.range(of: "^\(NSRegularExpression.escapedPattern(for: slug))-[a-z0-9]{4}$", options: .regularExpression) != nil
        }

        let first = try startTask(title)
        let second = try startTask(title)
        XCTAssertEqual(first.record["branch"] as? String, slug)
        let secondBranch = try XCTUnwrap(second.record["branch"] as? String)
        XCTAssertTrue(isSuffixed(secondBranch, of: slug), "The second branch should be the slug plus a short suffix: \(secondBranch)")
        XCTAssertNotEqual(first.record["worktreePath"] as? String, second.record["worktreePath"] as? String)

        let staleSlug = "stale-branch-\(token)"
        try runGit(fixture.primary, "branch", staleSlug, "HEAD")
        let staleCommit = try runGitOutput(fixture.primary, "rev-parse", staleSlug)
        try runGit(fixture.primary, "branch", "branch-source-for-suffix", "HEAD")
        let third = try startTask("Stale branch \(token)", branchFrom: "branch-source-for-suffix")
        let thirdBranch = try XCTUnwrap(third.record["branch"] as? String)
        XCTAssertTrue(isSuffixed(thirdBranch, of: staleSlug), "An existing branch must not be reused: \(thirdBranch)")
        XCTAssertEqual(third.record["branchFrom"] as? String, "branch-source-for-suffix")
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", staleSlug), staleCommit)

        let secondCard = element("task-card-\(second.id.uppercased())")
        XCTAssertTrue(secondCard.waitForExistence(timeout: 10), "The second task should be on the board.")
        clickTaskCardTitle(secondCard)
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 10))
        badge.click()
        let branchValue = element("conversation-repository-branch-value")
        XCTAssertTrue(branchValue.waitForExistence(timeout: 5))
        XCTAssertEqual(accessibleLabelOrValue(of: branchValue), secondBranch, "The conversation should show the second task's suffixed branch.")
        attachScreenshot(named: "A task keeps its resolved branch when another task already used the slug")
    }

    // case-contract: test_task_done_removes_worktree_and_preserves_branch | Sending the first message derives an auto branch from the generated task title, with a prompt fallback when title generation fails. Every linked PR must be merged before the task can move to Done. App focus checks each linked PR no more than once per 20 seconds; rapid focus changes are coalesced into one refresh after the cooldown. An unmerged PR keeps its link and suppresses the completion button. PR links and the green completion button have hit targets of at least 30×30 points. After all PRs merge, a later focus check replaces their links with a green completion button; clicking it waits for the task lock and then trusts that already-confirmed merge state, moving the task to Done immediately without re-querying GitHub even if merge status changed while the lock was held. The CLI's task move command has no such cached state, so it always verifies merge status directly with GitHub before completing, including rechecking after waiting for a contended task lock, and reports unmerged pull requests instead of completing when a PR is not actually merged. Completion removes managed worktrees while preserving their branches, does not merge into the local target, retains conversation history, and exposes the task in the searchable read-only archive; the CLI searches matching local Codex JSONL session files, including current input_text and output_text message content, without loading conversation histories, while the visible archive searches both user input_text and assistant output_text, loads the newest 40 first, and reveals older tasks as the user scrolls. While only some linked PRs are merged, each merged PR's number shows in merged purple and the task offers no completion checkmark until all are merged.
    func test_task_done_removes_worktree_and_preserves_branch() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let ghEnvironment = try makeGitHubStateFixture().merging(Self.prCheckCooldownEnvironment) { $1 }
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        openNewTaskConversation()
        chooseRepositorySuggestion("primary")
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 10), "New Task should open the composer in its conversation.")
        let task = try XCTUnwrap(tasksFromBoardList().first)
        let record = try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first)
        var path = try XCTUnwrap(record["worktreePath"] as? String)
        var branch = try XCTUnwrap(record["branch"] as? String)
        let taskID = try XCTUnwrap(task["id"] as? String)
        _ = try runCLI(["task", "repository", "add-batch", taskID, "--repo", fixture.secondary.path])
        XCTAssertEqual((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.count, 2)
        XCTAssertEqual(branch, "auto")
        XCTAssertEqual(record["isPending"] as? Bool, true)
        XCTAssertEqual(path, fixture.primary.path)
        let taskPrompt = "Please update the README and add concise setup steps for first time contributors tomorrow."
        let generatedBranch = "generated-fixture-title"
        XCTAssertEqual(record["mergeTarget"] as? String, "main")
        let composer = element("message-composer")
        let composerIsAvailable = waitUntil({ composer.exists && composer.isHittable }, timeout: 15)
        if !composerIsAvailable {
            attachScreenshot(named: "Unavailable composer after repository selection")
        }
        XCTAssertTrue(composerIsAvailable, "The composer should become available after conversation history loads. enabled=\(composer.isEnabled), value=\(composer.value as? String ?? "<none>"), hittable=\(composer.isHittable), frame=\(composer.frame); \(app.debugDescription)")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Untitled task", prompt: taskPrompt)
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        let startedRecord = try XCTUnwrap((taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(startedRecord["isPending"] as? Bool, false)
        path = try XCTUnwrap(startedRecord["worktreePath"] as? String)
        branch = try XCTUnwrap(startedRecord["branch"] as? String)
        XCTAssertNotEqual(path, fixture.primary.path)
        let startedTask = try taskRecord(id: taskID) ?? [:]
        XCTAssertTrue(
            branch == generatedBranch || (branch.hasPrefix(generatedBranch + "-") && branch.count == generatedBranch.count + 5),
            "Auto branch must use the generated title (plus a suffix when taken); task=\(startedTask)"
        )
        let codexHistoryURL = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".history")
        let codexHistory = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: codexHistoryURL)) as? [String: Any])
        XCTAssertEqual(codexHistory["threadStartCwd"] as? String, path, "Codex thread startup must use the managed worktree as cwd.")
        let turnHistory = try XCTUnwrap((codexHistory["turns"] as? [[String: Any]])?.first)
        XCTAssertEqual(turnHistory["cwd"] as? String, path, "The user turn must use the managed worktree as cwd.")
        let activeWorktreePaths = try XCTUnwrap(taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]]).compactMap { $0["worktreePath"] as? String }
        XCTAssertEqual(turnHistory["runtimeWorkspaceRoots"] as? [String], activeWorktreePaths)
        let taskBranchHead = try runGitOutput(URL(fileURLWithPath: path), "rev-parse", "HEAD")
        let originalTargetHead = try runGitOutput(fixture.primary, "rev-parse", "main")
        XCTAssertEqual(taskBranchHead, originalTargetHead)
        try "Master advanced after this task branch was created.\n".write(
            to: fixture.primary.appendingPathComponent("target-only.txt"), atomically: true, encoding: .utf8
        )
        try runGit(fixture.primary, "add", "target-only.txt")
        try runGit(fixture.primary, "commit", "-m", "Advance merge target while task is under review")
        let targetHead = try runGitOutput(fixture.primary, "rev-parse", "main")
        element("back-to-board-button").click()
        let titleDeadline = Date().addingTimeInterval(20)
        var currentTitle = "Generating title…"
        while Date() < titleDeadline, currentTitle == "Generating title…" {
            currentTitle = try XCTUnwrap(taskRecord(id: taskID)?["title"] as? String)
            if currentTitle == "Generating title…" { RunLoop.current.run(until: Date().addingTimeInterval(0.4)) }
        }
        XCTAssertNotEqual(currentTitle, "Generating title…", "The title placeholder should eventually resolve.")
        XCTAssertTrue(terminateAppAndWait(app), "Close Playhouse before seeding the real SwiftData fixture.")
        try seedTaskPullRequest(
            taskID: taskID,
            number: 123,
            url: "https://github.com/playhouse-test/fixture/pull/123"
        )
        try seedTaskPullRequest(
            taskID: taskID,
            number: 456,
            url: "https://github.com/playhouse-test/fixture/pull/456",
            repositoryIndex: 1
        )
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let prLink = element("task-pr-link-\(taskID)-123")
        let secondPRLink = element("task-pr-link-\(taskID)-456")
        XCTAssertTrue(prLink.waitForExistence(timeout: 10), "The linked unmerged PR should remain available on the Review card.")
        XCTAssertTrue(secondPRLink.waitForExistence(timeout: 10), "The task's second linked PR should also be visible.")
        XCTAssertGreaterThanOrEqual(prLink.frame.width, 30, "A PR link should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(prLink.frame.height, 30, "A PR link should have a comfortable vertical hit target.")
        XCTAssertGreaterThanOrEqual(secondPRLink.frame.width, 30, "The second PR link should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(secondPRLink.frame.height, 30, "The second PR link should have a comfortable vertical hit target.")
        let completionButton = element("task-complete-merged-pr-\(taskID)")
        XCTAssertFalse(completionButton.exists)
        let ghCallsURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CALL_LOG"]))
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) >= 2
        }, timeout: 10), "Opening the board should check the linked PR.")
        XCTAssertEqual(Set(try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).suffix(2)), Set(["123", "456"]))
        XCTAssertTrue(prLink.exists, "An unmerged PR should stay as a link.")
        XCTAssertTrue(secondPRLink.exists, "A second unmerged PR should stay as a link.")
        Thread.sleep(forTimeInterval: Self.prCheckCooldown + 0.1)
        let ghStateURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_STATE_PATH"]))
        try "123=merged\n456=unmerged\n".write(to: ghStateURL, atomically: true, encoding: .utf8)
        let previousCheckCount = (try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count
        activateOtherAppThenReturn()
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) >= previousCheckCount + 2
        }, timeout: 25), "Regaining focus should refresh the PR merge state.")
        XCTAssertEqual(Set(try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).suffix(2)), Set(["123", "456"]))
        XCTAssertFalse(completionButton.exists, "The task should remain incomplete while any linked PR is unmerged.")
        XCTAssertTrue(prLink.exists)
        XCTAssertTrue(secondPRLink.exists)
        XCTAssertTrue(waitUntil({ (prLink.value as? String) == "merged" }, timeout: 10), "The merged PR number should turn purple while its sibling is open.")
        XCTAssertEqual(secondPRLink.value as? String, "green", "The open PR keeps its check colour.")
        attachScreenshot(named: "One of two PRs merged: its number is purple, no checkmark yet", fullScreen: true)
        let rapidFocusCheckCount = (try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count
        for _ in 0..<4 {
            activateOtherAppThenReturn()
        }
        Thread.sleep(forTimeInterval: 0.5)
        XCTAssertEqual((try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count, rapidFocusCheckCount, "Rapid focus changes should not repeat GitHub checks.")
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) == rapidFocusCheckCount + 2
        }, timeout: 25), "A focus check suppressed during cooldown should run once after the cooldown.")
        Thread.sleep(forTimeInterval: 0.5)
        XCTAssertEqual((try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count, rapidFocusCheckCount + 2, "Multiple cooldown focus changes should produce exactly one trailing refresh.")
        Thread.sleep(forTimeInterval: Self.prCheckCooldown + 0.1)
        try "123=unmerged\n456=merged\n".write(to: ghStateURL, atomically: true, encoding: .utf8)
        let thirdCheckCount = (try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count
        activateOtherAppThenReturn()
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) >= thirdCheckCount + 2
        }, timeout: 10), "Focus should query both PRs when the second PR is already merged.")
        XCTAssertEqual(Set(try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).suffix(2)), Set(["123", "456"]))
        XCTAssertFalse(completionButton.exists, "Either unmerged PR should suppress task completion.")
        XCTAssertTrue(prLink.exists)
        XCTAssertTrue(secondPRLink.exists)
        XCTAssertTrue(waitUntil({ (secondPRLink.value as? String) == "merged" }, timeout: 10), "Either merged PR number turns purple, whichever order they merge in.")
        Thread.sleep(forTimeInterval: Self.prCheckCooldown + 0.1)
        try "123=merged\n456=merged\n".write(to: ghStateURL, atomically: true, encoding: .utf8)
        let fourthCheckCount = (try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count
        activateOtherAppThenReturn()
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) >= fourthCheckCount + 2
        }, timeout: 10), "Regaining focus should refresh both PR merge states.")
        XCTAssertEqual(Set(try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).suffix(2)), Set(["123", "456"]))
        XCTAssertTrue(completionButton.waitForExistence(timeout: 10), "A merged PR should replace its link with the completion button.")
        revealOnBoard(completionButton)
        XCTAssertGreaterThanOrEqual(completionButton.frame.width, 30, "The completion action should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(completionButton.frame.height, 30, "The completion action should have a comfortable vertical hit target.")
        XCTAssertEqual(completionButton.label, "Green checkmark. Complete task, all linked pull requests merged")
        assertContainsGreenForeground(in: completionButton)
        XCTAssertFalse(prLink.exists)
        XCTAssertFalse(secondPRLink.exists)
        let moveLock = try TaskOperationLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var moveLockReleased = false
        defer { if !moveLockReleased { try? moveLock.release() } }
        let taskCard = element("task-card-\(taskID)")
        XCTAssertTrue(taskCard.waitForExistence(timeout: 5))
        completionButton.click()
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review", "The UI move should wait while another process owns the task operation lock.")
        try "123=merged\n456=unmerged\n".write(to: ghStateURL, atomically: true, encoding: .utf8)
        try moveLock.release()
        moveLockReleased = true
        XCTAssertTrue(waitUntil({ !element("task-card-\(taskID)").exists }, timeout: 15), "The completed task should disappear from the active board.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Done", "Completion should trust the already-confirmed merge state and complete without rechecking GitHub, even though merge status changed to unmerged while the click waited for the task lock.")
        // The sent prompt is history, not a draft, and completion keeps the conversation.
        let completedHistory = try XCTUnwrap(try runCLI(["conversation", "history", taskID])["result"] as? [String: Any])
        XCTAssertTrue((completedHistory["messages"] as? [[String: Any]] ?? []).contains { $0["role"] as? String == "user" && $0["text"] as? String == taskPrompt })
        XCTAssertEqual(try runCLI(["task", "move", taskID, "Done"])["ok"] as? Bool, true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: path), "Moving a task to Done must remove its managed worktree.")
        try runGit(fixture.primary, "show-ref", "--verify", "--quiet", "refs/heads/\(branch)")
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", "main"), targetHead, "Moving a task to Done must not merge into the local target.")
        XCTAssertEqual(try String(contentsOf: fixture.primary.appendingPathComponent("target-only.txt"), encoding: .utf8), "Master advanced after this task branch was created.\n")
        XCTAssertFalse(FileManager.default.fileExists(atPath: fixture.primary.appendingPathComponent("task-result.txt").path))
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Done")

        let archiveFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-title-archive-ui").path
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: archiveFixtureExecutable))
        for index in 1...39 {
            let filler = try XCTUnwrap(try runCLI(["task", "create", "--title", "Archive page filler \(index)", "--prompt", "Fixture task description.", "--root", fixture.custom.path])["result"] as? [String: Any])
            let fillerID = try XCTUnwrap(filler["id"] as? String)
            _ = try runCLI(
                ["conversation", "send", fillerID, "--message", "Echo the outcome command for \(fillerID).", "--answer", "color=Blue", "--answer", "token=fixture-secret"],
                extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": archiveFixtureExecutable]
            )
            XCTAssertEqual(try XCTUnwrap((try runCLI(["task", "move", fillerID, "Done"])["result"] as? [String: Any])?["status"] as? String), "Done")
        }
        let titleMatch = try XCTUnwrap(try runCLI(["task", "create", "--title", "fixture-secret title match", "--prompt", "Fixture task description.", "--root", fixture.custom.path])["result"] as? [String: Any])
        let titleMatchID = try XCTUnwrap(titleMatch["id"] as? String)
        _ = try runCLI(
            ["conversation", "send", titleMatchID, "--message", "Echo the outcome command for \(titleMatchID).", "--answer", "color=Blue", "--answer", "token=fixture-secret"],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": archiveFixtureExecutable]
        )
        XCTAssertEqual(try XCTUnwrap((try runCLI(["task", "move", titleMatchID, "Done"])["result"] as? [String: Any])?["status"] as? String), "Done")

        let threadID = try XCTUnwrap(taskRecord(id: taskID)?["codexThreadID"] as? String)
        let sessions = dataDirectory.appendingPathComponent("codex-home/sessions/2026/10/22", isDirectory: true)
        try FileManager.default.createDirectory(at: sessions, withIntermediateDirectories: true)
        let sessionFile = sessions.appendingPathComponent("rollout-2026-10-22T00-00-00-\(threadID).jsonl")
        let sessionLines: [[String: Any]] = [
            ["type": "response_item", "payload": ["type": "message", "role": "user", "content": [["type": "input_text", "text": "LOCAL-SESSION-ONLY-input-token"]]]],
            ["type": "response_item", "payload": ["type": "message", "role": "assistant", "content": [["type": "output_text", "text": "LOCAL-SESSION-ONLY-output-token"]]]]
        ]
        let sessionData = try sessionLines.map { try JSONSerialization.data(withJSONObject: $0) + Data([0x0A]) }.reduce(into: Data()) { $0.append($1) }
        try sessionData.write(to: sessionFile, options: .atomic)

        let archiveButton = element("done-archive-button")
        archiveButton.click()
        let archiveResult = element("done-archive-task-\(taskID)")
        XCTAssertTrue(element("done-archive-task-\(titleMatchID)").waitForExistence(timeout: 10), "The newest completed task should appear in the first archive page.")
        let archiveList = app.scrollViews["done-archive-list"]
        XCTAssertEqual(archiveList.value as? String, "40 tasks loaded", "The archive should fetch one 40-task page initially.")
        XCTAssertFalse(archiveResult.exists, "Older tasks should not be loaded into the first archive page.")
        for _ in 0..<8 where !archiveResult.isHittable { archiveList.swipeUp() }
        XCTAssertTrue(waitUntil({ archiveResult.isHittable && archiveList.frame.intersects(archiveResult.frame) }, timeout: 10), "Scrolling should load older completed tasks into the archive viewport.")
        let archiveSearch = element("done-archive-search")
        archiveSearch.click()
        archiveSearch.typeText("no-such-archive-task")
        XCTAssertTrue(element("done-archive-empty-state").waitForExistence(timeout: 10), "A search with no matches should show an empty state.")
        element("clear-archive-search-button").click()
        archiveSearch.typeText("FiXtUrE-SeCrEt")
        let titleMatchResult = element("done-archive-task-\(titleMatchID)")
        XCTAssertTrue(titleMatchResult.waitForExistence(timeout: 10), "A title match should appear in the archive search results.")
        element("clear-archive-search-button").click()
        archiveSearch.typeText("local-session-only-output-TOKEN")
        XCTAssertTrue(waitUntil({ archiveResult.exists && !titleMatchResult.exists }, timeout: 10), "Searching assistant output_text should show its conversation match and filter out unrelated title matches.")
        element("clear-archive-search-button").click()
        archiveSearch.typeText("local-session-only-input-TOKEN")
        XCTAssertTrue(waitUntil({ archiveResult.exists && !titleMatchResult.exists }, timeout: 10), "Searching user input_text should show its conversation match and filter out unrelated title matches.")
        element("clear-archive-search-button").click()
        archiveSearch.typeText(currentTitle)
        XCTAssertTrue(archiveResult.waitForExistence(timeout: 10))
        XCTAssertFalse(titleMatchResult.exists)
        archiveResult.click()
        XCTAssertTrue(element("archived-conversation-read-only").waitForExistence(timeout: 10))
        let archivedAnswer = app.descendants(matching: .any).matching(
            NSPredicate(format: "label == %@", "Answers received: Blue / fixture-secret.")
        ).firstMatch
        XCTAssertTrue(archivedAnswer.waitForExistence(timeout: 10))
        XCTAssertFalse(element("message-composer").exists, "Archived conversations must not expose the composer.")
        element("back-to-board-button").click()
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Done", "Leaving the read-only conversation must not alter the archived task.")
        attachScreenshot(named: "Completed task opens from the searchable read-only archive")
    }

    // case-contract: test_review_pr_conflicts_probe_and_verify | Separate Review task cards probe their linked pull requests concurrently on app focus, with refreshes limited to one per 20 seconds, with focus events during cooldown coalesced into one trailing refresh. A conflicting PR or a mergeable PR whose remote head is not pushed locally retains the imported conflict action with its indicator artwork beside its PR link; the UI renders the artwork inside the action, keeps it beside the PR link, and gives both controls hit targets of at least 30×30 points. Clicking the conflict action sends the corrected request in the task conversation. CLI and UI use the same GitHub mergeability and head checks, retry once when resolution remains unconfirmed, and clear the action only after GitHub confirms the pushed head.
    func test_review_pr_conflicts_probe_and_verify() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        var ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [123, 456]).merging(Self.prCheckCooldownEnvironment) { $1 }
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Review PR conflict UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        openTask(named: "Review PR conflict UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Review PR conflict UI")
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ element("task-card-\(taskID)").exists }, timeout: 10))
        let secondCreated = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Second Review PR conflict UI", "--prompt", "Fixture task description.", "--repo", fixture.secondary.path,
            "--merge-target", "\(fixture.secondary.path)=main",
        ])["result"] as? [String: Any])
        let secondTaskID = try XCTUnwrap(secondCreated["id"] as? String)
        openTask(named: "Second Review PR conflict UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Second Review PR conflict UI")
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ element("task-card-\(secondTaskID)").exists }, timeout: 10))
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: taskID, number: 123, url: "https://github.com/playhouse-test/fixture/pull/123")
        try seedTaskPullRequest(taskID: secondTaskID, number: 456, url: "https://github.com/playhouse-test/fixture/pull/456")
        let remote = runDirectory.appendingPathComponent("conflict-solver-origin.git", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remote.path), "Each UI case should use a fresh owned bare remote.")
        try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
        _ = try runGitOutput(remote, "init", "--bare")
        for (id, number) in [(taskID, 123), (secondTaskID, 456)] {
            let record = try XCTUnwrap((try taskRecord(id: id)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
            try runGit(worktree, "push", remote.path, "HEAD:refs/heads/pr-\(number)")
        }
        ghEnvironment["PLAYHOUSE_E2E_GH_REMOTE_REPOSITORY"] = remote.path

        let resolutionFixture = WorkspaceFixture.root.appendingPathComponent("codex-fixture-success-wait")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: resolutionFixture.path))
        codexFixtureExecutable = resolutionFixture.path
        let readyURL = URL(fileURLWithPath: resolutionFixture.path + ".resolve-ready")
        let continueURL = URL(fileURLWithPath: resolutionFixture.path + ".resolve-continue")
        let startCountURL = URL(fileURLWithPath: resolutionFixture.path + ".resolve-start-count")
        try? FileManager.default.removeItem(at: readyURL)
        try? FileManager.default.removeItem(at: continueURL)
        try? FileManager.default.removeItem(at: startCountURL)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)

        let link = element("task-pr-link-\(taskID)-123")
        let resolveButton = element("task-resolve-pr-conflicts-\(taskID)")
        XCTAssertTrue(link.waitForExistence(timeout: 10))
        let secondLink = element("task-pr-link-\(secondTaskID)-456")
        XCTAssertTrue(secondLink.waitForExistence(timeout: 10))
        XCTAssertGreaterThanOrEqual(secondLink.frame.width, 30, "The second task's PR link should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(secondLink.frame.height, 30, "The second task's PR link should have a comfortable vertical hit target.")
        let startedDirectory = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_STARTED_DIRECTORY"]))
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: startedDirectory.appendingPathComponent("123").path) }, timeout: 10))
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: startedDirectory.appendingPathComponent("456").path) }, timeout: 10), "Both Review task probes should overlap on focus.")
        XCTAssertFalse(resolveButton.exists, "A mergeable PR should not show the conflict action.")
        let stateURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_STATE_PATH"]))
        try "123=conflicting\n".write(to: stateURL, atomically: true, encoding: .utf8)
        for number in [123, 456] { try? FileManager.default.removeItem(at: startedDirectory.appendingPathComponent("\(number)")) }
        let ghCallsURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CALL_LOG"]))
        let callsBeforeCooldownFocus = (try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count
        for _ in 0..<4 {
            activateOtherAppThenReturn()
        }
        Thread.sleep(forTimeInterval: 0.5)
        XCTAssertFalse(FileManager.default.fileExists(atPath: startedDirectory.appendingPathComponent("123").path), "Cooldown focus events should not start an immediate GitHub probe.")
        XCTAssertTrue(waitUntil({
            ((try? String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) ?? 0) == callsBeforeCooldownFocus + 2
        }, timeout: 25), "Cooldown focus events should coalesce into one trailing probe after 20 seconds.")
        Thread.sleep(forTimeInterval: 0.5)
        XCTAssertEqual((try String(contentsOf: ghCallsURL, encoding: .utf8).split(whereSeparator: \.isNewline)).count, callsBeforeCooldownFocus + 2, "Four focus changes should produce exactly one probe per linked PR.")
        XCTAssertTrue(resolveButton.waitForExistence(timeout: 10), "Focus should discover the conflicting PR.")
        XCTAssertGreaterThanOrEqual(resolveButton.frame.width, 30, "The conflict action should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(resolveButton.frame.height, 30, "The conflict action should have a comfortable vertical hit target.")
        XCTAssertGreaterThanOrEqual(link.frame.width, 30, "A PR link should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(link.frame.height, 30, "A PR link should have a comfortable vertical hit target.")
        assertConflictIndicatorArtwork(resolveButton)
        XCTAssertLessThanOrEqual(resolveButton.frame.maxX, link.frame.minX + 1, "The conflict action should sit beside its PR link.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: startedDirectory.appendingPathComponent("123").path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: startedDirectory.appendingPathComponent("456").path), "Focus refresh should probe separate Review cards concurrently.")

        resolveButton.click()
        let initialPrompt = "The PR has conflicts. Fix them, commit, and push."
        let initialPromptElement = element("conversation-scroll-view").descendants(matching: .any)
            .matching(NSPredicate(format: "label == %@", initialPrompt)).firstMatch
        XCTAssertTrue(initialPromptElement.waitForExistence(timeout: 10), "The conflict action should send the corrected instruction into the task conversation.")
        XCTAssertTrue(initialPromptElement.identifier.hasPrefix("playhouse-message-"), "The conflict instruction renders as an automatic Playhouse message: \(initialPromptElement.identifier)")
        attachScreenshot(named: "Conflict instruction shown as an automatic Playhouse message")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: readyURL.path) }, timeout: 10), "Codex should start the conflict resolution turn.")
        try "Continue after first conflict attempt.\n".write(to: continueURL, atomically: true, encoding: .utf8)

        let retryPrompt = "The PR still has conflicts or your latest commit has not reached GitHub. Resolve the remaining conflicts, commit, and push. Verify the PR's merge status before finishing."
        let retryPromptElement = element("conversation-scroll-view").descendants(matching: .any)
            .matching(NSPredicate(format: "label == %@", retryPrompt)).firstMatch
        XCTAssertTrue(retryPromptElement.waitForExistence(timeout: 15), "A still-conflicting PR should receive one follow-up turn.")
        XCTAssertTrue(retryPromptElement.identifier.hasPrefix("playhouse-message-"), "The retry instruction renders as an automatic Playhouse message: \(retryPromptElement.identifier)")
        XCTAssertTrue(waitUntil({
            (try? String(contentsOf: startCountURL, encoding: .utf8).split(whereSeparator: \.isNewline).count) == 2
        }, timeout: 10), "Codex should start exactly two resolution turns.")
        let primaryRecord = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let primaryWorktree = URL(fileURLWithPath: try XCTUnwrap(primaryRecord["worktreePath"] as? String), isDirectory: true)
        try "Resolution from the conflict solver.\n".write(
            to: primaryWorktree.appendingPathComponent("conflict-solver-resolution.txt"), atomically: true, encoding: .utf8
        )
        try runGit(primaryWorktree, "add", "conflict-solver-resolution.txt")
        try runGit(primaryWorktree, "commit", "-m", "Resolve pull request conflicts")
        let resolvedLocalHead = try runGitOutput(primaryWorktree, "rev-parse", "HEAD")
        let staleRemoteHead = try runGitOutput(remote, "rev-parse", "refs/heads/pr-123")
        XCTAssertNotEqual(resolvedLocalHead, staleRemoteHead, "A local resolution commit must remain unconfirmed until it is pushed.")
        try "123=remote\n456=unmerged\n".write(to: stateURL, atomically: true, encoding: .utf8)
        _ = try runCLI(
            ["task", "outcome", taskID, "completed"],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": resolutionFixture.path]
        )
        try "Continue after verified conflict resolution.\n".write(to: continueURL, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ element("send-message-button").exists }, timeout: 15), "The second Codex turn should finish after the verified push.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        returnToBoard()
        XCTAssertTrue(resolveButton.exists, "A mergeable PR with a mismatched remote head must retain the conflict action.")
        try runGit(primaryWorktree, "push", remote.path, "HEAD:refs/heads/pr-123")
        XCTAssertEqual(try runGitOutput(remote, "rev-parse", "refs/heads/pr-123"), resolvedLocalHead)
        try "123=remote\n456=unmerged\n".write(to: stateURL, atomically: true, encoding: .utf8)
        for number in [123, 456] { try? FileManager.default.removeItem(at: startedDirectory.appendingPathComponent("\(number)")) }
        Thread.sleep(forTimeInterval: Self.prCheckCooldown + 0.1)
        activateOtherAppThenReturn()
        XCTAssertTrue(waitUntil({ !resolveButton.exists }, timeout: 10), "The action should disappear after GitHub confirms the pushed head.")
    }

    // case-contract: test_review_sync_pushes_unpushed_changes_on_completion | A completed turn outcome on a task with a PR-linked repository and a configured remote commits local work, merges new remote pull request commits, and pushes the branch before the task reaches Review, so the reviewed worktree holds no local-only changes. A linked repository without a publishing remote is left untouched and still reaches Review. When the sync cannot complete, the task moves to Blocked with the sync failure message instead of resting in Review, and a later successful sync pushes the stranded commits and returns the task to Review. While a provider turn holds the task's worktree, the sync command skips it untouched and reports turn-active.
    func test_review_sync_pushes_unpushed_changes_on_completion() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [123]).merging(Self.prCheckCooldownEnvironment) { $1 }
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Review sync push UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        openTask(named: "Review sync push UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Review sync push UI")
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ element("task-card-\(taskID)").exists }, timeout: 10))
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: taskID, number: 123, url: "https://github.com/playhouse-test/fixture/pull/123")

        let record = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
        let branch = try XCTUnwrap(record["branch"] as? String)
        let remote = runDirectory.appendingPathComponent("review-sync-push-origin.git", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remote.path), "Each UI case should use a fresh owned bare remote.")
        try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
        _ = try runGitOutput(remote, "init", "--bare")
        try runGit(fixture.primary, "remote", "add", "origin", remote.path)
        addTeardownBlock { [self] in try? runGit(fixture.primary, "remote", "remove", "origin") }
        try runGit(worktree, "push", "--set-upstream", "origin", branch)

        // A reviewer commit on the remote PR branch the local branch has not seen.
        let clone = runDirectory.appendingPathComponent("review-sync-push-clone", isDirectory: true)
        _ = try runGitOutput(runDirectory, "clone", "--branch", branch, remote.path, clone.path)
        try "Remote reviewer commit.\n".write(to: clone.appendingPathComponent("remote-side.txt"), atomically: true, encoding: .utf8)
        try runGit(clone, "add", "remote-side.txt")
        try runGit(clone, "commit", "-m", "Remote PR commit")
        try runGit(clone, "push", "origin", branch)
        let reviewerHead = try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)")

        // Local uncommitted work the completed turn leaves behind.
        try "Local turn output.\n".write(to: worktree.appendingPathComponent("local-side.txt"), atomically: true, encoding: .utf8)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        openTask(named: "Review sync push UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Review sync push UI", whileTurnHeld: {
            // While the provider turn owns the worktree, the sync skips it untouched.
            let skipped = try self.runCLI(["task", "pr", "sync", taskID])
            let result = try XCTUnwrap(skipped["result"] as? [String: Any])
            XCTAssertEqual(result["skipped"] as? String, "turn-active")
            XCTAssertEqual((result["records"] as? [Any])?.isEmpty, true)
        })
        assertTaskVisible("Review sync push UI", inColumn: "Review")
        XCTAssertEqual(try runGitOutput(worktree, "status", "--porcelain", "--untracked-files=all"), "", "A reviewed worktree must hold no local-only changes.")
        let localHead = try runGitOutput(worktree, "rev-parse", "HEAD")
        XCTAssertEqual(try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)"), localHead)
        XCTAssertNotEqual(localHead, reviewerHead, "The sync should push a merge of the reviewer commit and the local work.")
        XCTAssertEqual(
            try String(contentsOf: worktree.appendingPathComponent("remote-side.txt"), encoding: .utf8),
            "Remote reviewer commit.\n"
        )
        XCTAssertEqual(try runGitOutput(remote, "show", "refs/heads/\(branch):local-side.txt"), "Local turn output.")

        // A sync the daemon cannot complete blocks the task instead of resting in Review.
        try runGit(fixture.primary, "remote", "set-url", "origin", runDirectory.appendingPathComponent("missing-remote.git").path)
        try "Unpushable local change.\n".write(to: worktree.appendingPathComponent("local-side.txt"), atomically: true, encoding: .utf8)
        openTask(named: "Review sync push UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Review sync push UI", expectedFinalStatus: "Blocked")
        assertTaskVisible("Review sync push UI", inColumn: "Blocked")
        let blockedMessage = try taskRecord(id: taskID)?["statusMessage"] as? String
        XCTAssertTrue((blockedMessage ?? "").contains("couldn't sync this task's changes with its pull request"), blockedMessage ?? "nil")

        // A later successful sync pushes the stranded commit and returns the task to Review.
        try runGit(fixture.primary, "remote", "set-url", "origin", remote.path)
        _ = try runCLI(["task", "pr", "sync", taskID])
        assertTaskVisible("Review sync push UI", inColumn: "Review")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        XCTAssertEqual(try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)"), try runGitOutput(worktree, "rev-parse", "HEAD"))
    }

    // case-contract: test_review_sync_resolves_conflicts_with_provider_or_blocks | When the remote pull request branch conflicts with local task commits, the review sync merges the remote branch and instructs the task's provider to resolve every conflict; if conflicts remain after the provider turn, the sync fails, the task moves to Blocked with the sync failure message, the merge stays in progress for manual resolution, and the remote branch is unchanged. A rerun with the conflicts staged commits the resolution, pushes the merged branch, and returns the task to Review. The board triggers the same sync automatically when a mergeable pull request's remote head diverges from the local head.
    func test_review_sync_resolves_conflicts_with_provider_or_blocks() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        var ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [123]).merging(Self.prCheckCooldownEnvironment) { $1 }
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Review sync conflict UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        openTask(named: "Review sync conflict UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Review sync conflict UI")
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ element("task-card-\(taskID)").exists }, timeout: 10))
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: taskID, number: 123, url: "https://github.com/playhouse-test/fixture/pull/123")

        let record = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
        let branch = try XCTUnwrap(record["branch"] as? String)
        let remote = runDirectory.appendingPathComponent("review-sync-conflict-origin.git", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remote.path), "Each UI case should use a fresh owned bare remote.")
        try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
        _ = try runGitOutput(remote, "init", "--bare")
        try runGit(fixture.primary, "remote", "add", "origin", remote.path)
        addTeardownBlock { [self] in try? runGit(fixture.primary, "remote", "remove", "origin") }
        try runGit(worktree, "push", "--set-upstream", "origin", branch)
        try runGit(worktree, "push", "origin", "HEAD:refs/heads/pr-123")
        ghEnvironment["PLAYHOUSE_E2E_GH_REMOTE_REPOSITORY"] = remote.path

        // The board pushes a diverged local head automatically, with no conflict action.
        try "Local unpushed change.\n".write(to: worktree.appendingPathComponent("review-sync-local.txt"), atomically: true, encoding: .utf8)
        try runGit(worktree, "add", "review-sync-local.txt")
        try runGit(worktree, "commit", "-m", "Local unpushed commit")
        let localHead = try runGitOutput(worktree, "rev-parse", "HEAD")
        XCTAssertNotEqual(try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)"), localHead)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        XCTAssertTrue(element("task-card-\(taskID)").waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({
            (try? self.runGitOutput(remote, "rev-parse", "refs/heads/\(branch)")) == localHead
        }, timeout: 30), "The board should push the diverged local head automatically.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        // Once the PR head reports the pushed commit, no conflict action remains.
        try runGit(worktree, "push", "origin", "HEAD:refs/heads/pr-123")
        Thread.sleep(forTimeInterval: Self.prCheckCooldown + 0.1)
        activateOtherAppThenReturn()
        let resolveButton = element("task-resolve-pr-conflicts-\(taskID)")
        XCTAssertTrue(waitUntil({ !resolveButton.exists }, timeout: 10), "A synced PR should not keep the conflict action.")
        XCTAssertTrue(terminateAppAndWait(app))

        // Conflicting local and remote PR commits: the provider turn resolves nothing,
        // so the sync fails closed and the task blocks instead of resting in Review.
        let conflictPath = "review-sync-conflict.txt"
        try "base version\n".write(to: worktree.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(worktree, "add", conflictPath)
        try runGit(worktree, "commit", "-m", "Base for sync conflict")
        try runGit(worktree, "push", "origin", branch)
        try runGit(worktree, "push", "origin", "HEAD:refs/heads/pr-123")
        let clone = runDirectory.appendingPathComponent("review-sync-conflict-clone", isDirectory: true)
        _ = try runGitOutput(runDirectory, "clone", "--branch", branch, remote.path, clone.path)
        try "remote version\n".write(to: clone.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(clone, "add", conflictPath)
        try runGit(clone, "commit", "-m", "Remote conflicting commit")
        try runGit(clone, "push", "origin", branch)
        try runGit(clone, "push", "origin", "HEAD:refs/heads/pr-123")
        let remoteHead = try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)")
        try "local version\n".write(to: worktree.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(worktree, "add", conflictPath)
        try runGit(worktree, "commit", "-m", "Local conflicting commit")

        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: taskID)?["status"] as? String) == "Blocked"
        }, timeout: 30), "An unresolvable sync conflict should move the task to Blocked.")
        assertTaskVisible("Review sync conflict UI", inColumn: "Blocked")
        let blockedMessage = try taskRecord(id: taskID)?["statusMessage"] as? String
        XCTAssertTrue((blockedMessage ?? "").contains("couldn't sync this task's changes with its pull request"), blockedMessage ?? "nil")
        XCTAssertEqual(try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)"), remoteHead, "A failed sync must leave the remote branch unchanged.")
        XCTAssertEqual(try runGitOutput(worktree, "diff", "--name-only", "--diff-filter=U"), conflictPath, "The merge should stay in progress for manual resolution.")

        // Staging the resolution lets the shared sync command finish the merge,
        // push the merged branch, and return the task to Review.
        try "resolved local and remote versions\n".write(to: worktree.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(worktree, "add", conflictPath)
        _ = try runCLI(["task", "pr", "sync", taskID])
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        assertTaskVisible("Review sync conflict UI", inColumn: "Review")
        XCTAssertEqual(try runGitOutput(remote, "rev-parse", "refs/heads/\(branch)"), try runGitOutput(worktree, "rev-parse", "HEAD"))
        XCTAssertEqual(try runGitOutput(remote, "show", "refs/heads/\(branch):\(conflictPath)"), "resolved local and remote versions")
    }

    // case-contract: test_task_done_preserves_dirty_worktree | Moving a reviewed task to Done removes its managed worktree and keeps its branch and target commit without committing or merging. When the worktree holds uncommitted changes the move is refused until the user confirms discarding them: declining keeps the task in Review with its files intact, and confirming removes them. A reviewed task stays in Review until it is moved; in the UI the Done drawer rests as a thin sliver beside, not over, the board columns, opens only while a reviewed card is dragged, and returns to rest both after a card is dropped on Done and when a card is dropped back in place without moving the task.
    func test_task_done_preserves_dirty_worktree() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        _ = try runCLI(["task", "create", "--title", "Dirty done UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path])
        openTask(named: "Dirty done UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Dirty done UI")
        element("back-to-board-button").click()
        let record = try XCTUnwrap((taskRecord(named: "Dirty done UI")?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let path = try XCTUnwrap(record["worktreePath"] as? String)
        let branch = try XCTUnwrap(record["branch"] as? String)
        try "Edited after review\n".write(to: URL(fileURLWithPath: path).appendingPathComponent("playhouse-primary.txt"), atomically: true, encoding: .utf8)
        try "New unsaved work\n".write(to: URL(fileURLWithPath: path).appendingPathComponent("unsaved.txt"), atomically: true, encoding: .utf8)
        let targetBefore = try runGitOutput(fixture.primary, "rev-parse", "main")
        let branchHead = try runGitOutput(URL(fileURLWithPath: path), "rev-parse", "HEAD")
        let card = app.buttons["Dirty done UI"].firstMatch
        XCTAssertTrue(card.waitForExistence(timeout: 5))
        assertDoneDrawerResting("before any drag")
        attachScreenshot(named: "Done drawer peeks at the board edge while resting", fullScreen: true)
        // Dropping a card back in its own column hits no drop target; the drawer must still close.
        let reviewColumn = element("column-review")
        XCTAssertTrue(reviewColumn.waitForExistence(timeout: 5))
        card.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).press(
            forDuration: 0.5,
            thenDragTo: reviewColumn.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.92)),
            withVelocity: .default,
            thenHoldForDuration: 0.5
        )
        assertDoneDrawerResting("after a card is dropped back in place")
        XCTAssertEqual(try taskRecord(named: "Dirty done UI")?["status"] as? String, "Review", "Dropping a card in place must not move the task.")
        attachScreenshot(named: "Done drawer closes again after a drop in place", fullScreen: true)
        let openDrawerCapture = startDelayedScreenCapture(afterSeconds: 2)
        dragTaskToDone(card)
        attachScreenCapture(openDrawerCapture, named: "Done drawer slides open while a card is dragged")
        // Scoped to the dialog sheet: a bare "Cancel" button also matches a Touch Bar element.
        let discardButton = app.sheets.buttons["Discard Changes and Mark Done"].firstMatch
        let keepButton = app.sheets.buttons["Cancel"].firstMatch
        XCTAssertTrue(discardButton.waitForExistence(timeout: 10), "A worktree with uncommitted changes must ask before Done discards them.")
        attachScreenshot(named: "Done asks before discarding uncommitted changes")
        // Declining leaves the task and its files exactly as they were.
        keepButton.click()
        XCTAssertTrue(waitUntil({ !discardButton.exists }, timeout: 5), "Cancel should dismiss the confirmation.")
        assertDoneDrawerResting("after declining to discard changes")
        XCTAssertEqual(try taskRecord(named: "Dirty done UI")?["status"] as? String, "Review", "Declining must leave the task in Review.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: path), "Declining must keep the task worktree.")
        XCTAssertEqual(try String(contentsOf: URL(fileURLWithPath: path).appendingPathComponent("unsaved.txt"), encoding: .utf8), "New unsaved work\n")
        dragTaskToDone(card)
        XCTAssertTrue(discardButton.waitForExistence(timeout: 10))
        discardButton.click()
        XCTAssertTrue(waitUntil({
            do { return try taskRecord(named: "Dirty done UI")?["status"] as? String == "Done" }
            catch { return false }
        }, timeout: 15), "Confirming should persist the Done status.")
        assertDoneDrawerResting("after a card is dropped on Done")
        attachScreenshot(named: "Done drawer closes after a drop on Done", fullScreen: true)
        try assertTaskArchived("Dirty done UI")
        XCTAssertFalse(FileManager.default.fileExists(atPath: path), "Confirmed Done must remove the task worktree with its uncommitted changes.")
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", "main"), targetBefore)
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", branch), branchHead)
        try runGit(fixture.primary, "show-ref", "--verify", "--quiet", "refs/heads/\(branch)")
        attachScreenshot(named: "Done removes the worktree and keeps the branch")
    }

    // case-contract: test_task_pr_create_reports_real_gh_failure | The CLI confirms a new repository-backed task persists in Backlog; the UI shows no PR control there, then shows the active-card PR action after the conversation completes with a minimum 30-point hit target, on its own last row below the card title and time row and on the right, with that row absent while the task sits in Backlog. The active-card PR control visibly presents its native help on hover, while hovering the card itself shows no tooltip and the card remains an openable control; the Done archive PR action remains available with its completed-task label and visibly presents its native help on hover, then waits for the task lock before a real GitHub CLI or branch publication failure without saving a PR link or changing Done status.
    func test_task_pr_create_reports_real_gh_failure() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "PR failure UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        XCTAssertEqual(created["status"] as? String, "Backlog")
        XCTAssertTrue(element("task-card-\(taskID)").waitForExistence(timeout: 5), "The backlog task card should render before checking its PR controls.")
        XCTAssertFalse(element("task-create-pr-\(taskID)").exists, "Backlog cards must not expose a PR action.")
        let createdRecord = try XCTUnwrap((created["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(createdRecord["mergeTarget"] as? String, "main")
        XCTAssertEqual((try runCLI(["task", "pr", "conflicts", taskID])["result"] as? [String: Any])?["repositories"] as? [String], [])
        openTask(named: "PR failure UI")
        element("conversation-repository-badge-primary").click()
        let mergeTargetValue = element("conversation-repository-merge-target-value")
        XCTAssertTrue(mergeTargetValue.waitForExistence(timeout: 5))
        XCTAssertEqual(accessibleLabelOrValue(of: mergeTargetValue), "main")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "PR failure UI")
        element("back-to-board-button").click()
        let activeCreateButton = element("task-create-pr-\(taskID)")
        XCTAssertTrue(activeCreateButton.waitForExistence(timeout: 5), "An active repository task should expose its PR action on the card.")
        revealOnBoard(activeCreateButton)
        XCTAssertGreaterThanOrEqual(activeCreateButton.frame.width, 30, "The PR action should have a comfortable horizontal hit target.")
        XCTAssertGreaterThanOrEqual(activeCreateButton.frame.height, 30, "The PR action should have a comfortable vertical hit target.")
        // The control sits on its own last row, below the title and the time row, on the right; Backlog had no such row.
        XCTAssertGreaterThanOrEqual(activeCreateButton.frame.minY, element("task-title-\(taskID)").frame.maxY, "The pull-request row should sit below the title.")
        XCTAssertGreaterThanOrEqual(activeCreateButton.frame.minY, element("task-token-usage-counter-\(taskID)").frame.maxY, "The pull-request row should sit below the time row.")
        XCTAssertLessThanOrEqual(activeCreateButton.frame.maxY, element("task-card-\(taskID)").frame.maxY + 1, "The pull-request row should be the card's last row.")
        XCTAssertGreaterThan(activeCreateButton.frame.midX, element("task-card-\(taskID)").frame.midX, "The pull-request control should sit on the right.")
        assertHoverEmphasis(for: activeCreateButton)
        XCTAssertEqual(activeCreateButton.label, "PR. Create a pull request for each repository linked to this task")
        assertNativeHelpText(for: activeCreateButton, equals: "Create a pull request for each repository linked to this task")
        attachScreenshot(named: "Active task PR control shows its help text", fullScreen: true)
        dismissNativeHelpText(named: "Create a pull request for each repository linked to this task")
        assertNoNativeHelpText(whileHovering: element("task-title-\(taskID)"), containing: "Open task")
        XCTAssertTrue(element("task-card-\(taskID)").isHittable, "The card should still be a clickable control without its tooltip.")
        XCTAssertEqual(element("task-card-\(taskID)").label, "PR failure UI", "The card keeps its accessibility label.")
        attachScreenshot(named: "Hovering a task card shows no tooltip", fullScreen: true)
        moveTaskToDone(taskID: taskID)
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Done")
        element("done-archive-button").click()
        let archiveTask = element("done-archive-task-\(taskID)")
        XCTAssertTrue(archiveTask.waitForExistence(timeout: 10), "The completed task should be listed in the archive.")
        let createButton = element("done-archive-create-pr-\(taskID)")
        XCTAssertTrue(createButton.waitForExistence(timeout: 5))
        assertHoverEmphasis(for: createButton)
        XCTAssertEqual(createButton.label, "PR. Create a pull request for each repository linked to this completed task")
        assertNativeHelpText(for: createButton, equals: "Create a pull request for each repository linked to this completed task")
        attachScreenshot(named: "Completed task PR action shows its help text in the archive", fullScreen: true)
        dismissNativeHelpText(named: "Create a pull request for each repository linked to this completed task")
        let operationLock = try TaskOperationLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var operationLockReleased = false
        defer { if !operationLockReleased { try? operationLock.release() } }
        createButton.click()
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertFalse(app.sheets.firstMatch.exists, "The UI should wait on the task operation lock before starting the real gh lookup.")
        let waitingTask = try XCTUnwrap(taskRecord(id: taskID))
        let waitingRecord = try XCTUnwrap((waitingTask["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(waitingTask["status"] as? String, "Done")
        XCTAssertNil(waitingRecord["pullRequestNumber"])
        XCTAssertNil(waitingRecord["pullRequestURL"])
        try operationLock.release()
        operationLockReleased = true
        let alertSheet = app.sheets.firstMatch
        XCTAssertTrue(alertSheet.waitForExistence(timeout: 20), "The archived task should report gh's inability to create a PR.")
        XCTAssertTrue(waitUntil({
            self.element(containingAccessibilityText: "gh auth login").exists
                || self.element(containingAccessibilityText: "publish the task branch").exists
        }, timeout: 5), app.debugDescription)
        alertSheet.buttons["OK"].click()
        let current = try XCTUnwrap(taskRecord(id: taskID))
        let record = try XCTUnwrap((current["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertNil(record["pullRequestNumber"])
        XCTAssertNil(record["pullRequestURL"])
        XCTAssertEqual(record["mergeTarget"] as? String, "main")
        XCTAssertEqual(current["status"] as? String, "Done")
    }

    // case-contract: test_task_auto_pr_toggle_creates_pull_request_on_review | A working-state task card (In Progress, Blocked, or Waiting Response) with no linked pull request shows a compact pull request mode pill in place of the manual PR button, closed on its current mode and defaulting to Manual; clicking it slides out Manual, PR, Green, and Merge, and choosing one selects it and folds the pill back onto it. The pill stays beside linked pull requests so autopilot and merge remain switchable. Selecting PR persists as mode pr with Auto PR on and is reflected across a fresh read; `task pr mode` accepts manual, pr, autopilot, and merge (autopilot and merge also turn Auto PR on) and rejects an unknown mode without changing the task. When a turn completes while Auto PR is on, Playhouse creates the task's pull request itself on the way to Review with no user click, exactly once. When Auto PR stays off, the task still reaches Review with no pull request, and the existing manual PR button still creates it afterward unchanged. The last switch choice is remembered: tasks created after turning it on start on, and tasks created after turning it off start off. Toggling Auto PR for an unknown task is rejected.
    func test_task_auto_pr_toggle_creates_pull_request_on_review() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [])
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Auto PR toggle UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        XCTAssertTrue(element("task-card-\(taskID)").waitForExistence(timeout: 5))
        XCTAssertFalse(element("task-pr-mode-\(taskID)").exists, "A Backlog task has no working-state PR controls yet.")
        // A worktree shares its source repository's git config, so the origin remotes this
        // case adds through its worktrees must not leak into later cases. A teardown block,
        // not `defer`: with continueAfterFailure off, a failed assertion stops the case
        // without running its defers.
        addTeardownBlock { [self] in
            for repository in [fixture.primary, fixture.secondary] {
                try? runGit(repository, "remote", "remove", "origin")
            }
        }

        openTask(named: "Auto PR toggle UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Auto PR toggle UI", whileTurnHeld: {
            self.element("back-to-board-button").click()
            let pill = self.element("task-pr-mode-\(taskID)")
            XCTAssertTrue(pill.waitForExistence(timeout: 5), "An in-progress task with no linked PR should show the PR mode pill.")
            XCTAssertFalse(self.element("task-create-pr-\(taskID)").exists, "The mode pill replaces the manual PR button while the task is in progress.")
            XCTAssertGreaterThanOrEqual(pill.frame.height, 30, "The closed pill should keep a comfortable hit target.")
            XCTAssertGreaterThanOrEqual(pill.frame.minY, self.element("task-working-duration-\(taskID)").frame.maxY, "The mode pill should sit below the working-duration time row.")
            XCTAssertEqual(pill.value as? String, "manual", "The closed pill shows the current mode, defaulting to Manual.")
            XCTAssertFalse(self.element("task-pr-mode-merge-\(taskID)").exists, "A closed pill shows only the current mode.")
            XCTAssertFalse(try XCTUnwrap(self.taskRecord(id: taskID)?["autoCreatePullRequestOnReview"] as? Bool), "Auto PR must default to off.")
            XCTAssertEqual(try self.taskRecord(id: taskID)?["pullRequestMode"] as? String, "manual")
            self.attachScreenshot(named: "Working task shows the closed mode pill on Manual", fullScreen: true)

            pill.click()
            for mode in ["manual", "pr", "autopilot", "merge"] {
                let option = self.element("task-pr-mode-\(mode)-\(taskID)")
                XCTAssertTrue(option.waitForExistence(timeout: 5), "The open pill should offer \(mode).")
                XCTAssertGreaterThanOrEqual(option.frame.height, 30, "Each mode should keep a comfortable hit target.")
            }
            XCTAssertEqual(self.element("task-pr-mode-manual-\(taskID)").value as? String, "selected")
            _ = self.settledPillOption("merge", taskID: taskID)
            self.attachScreenshot(named: "Clicking the pill slides out Manual, PR, Green, and Merge", fullScreen: true)
            // Choosing the current mode again just folds the pill.
            self.settledPillOption("manual", taskID: taskID).click()
            XCTAssertTrue(self.waitUntil({ pill.exists && (pill.value as? String) == "manual" && !self.element("task-pr-mode-merge-\(taskID)").exists }, timeout: 5), "Choosing the current mode should fold the pill.")
            XCTAssertEqual(try self.taskRecord(id: taskID)?["pullRequestMode"] as? String, "manual")

            pill.click()
            self.settledPillOption("autopilot", taskID: taskID).click()
            XCTAssertTrue(self.waitUntil({
                (try? self.taskRecord(id: taskID)?["pullRequestMode"] as? String) == "autopilot"
            }, timeout: 5), "Choosing Green should persist immediately.")
            XCTAssertTrue(self.waitUntil({ pill.exists && (pill.value as? String) == "autopilot" && !self.element("task-pr-mode-merge-\(taskID)").exists }, timeout: 5), "Choosing a mode should fold the pill back onto it.")
            self.attachScreenshot(named: "Choosing Green folds the pill back onto Green", fullScreen: true)
            try self.selectPullRequestMode("pr", taskID: taskID)
            XCTAssertTrue(self.waitUntil({
                (try? self.taskRecord(id: taskID)?["autoCreatePullRequestOnReview"] as? Bool) == true
                    && (try? self.taskRecord(id: taskID)?["pullRequestMode"] as? String) == "pr"
            }, timeout: 5), "Choosing PR should persist immediately.")
            self.attachScreenshot(named: "Choosing PR in the mode control persists", fullScreen: true)

            let record = try XCTUnwrap((self.taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
            let remoteRoot = self.dataDirectory.appendingPathComponent("auto-pr-remotes", isDirectory: true)
            XCTAssertFalse(FileManager.default.fileExists(atPath: remoteRoot.path), "Each UI case should start with an isolated bare remote fixture.")
            try FileManager.default.createDirectory(at: remoteRoot, withIntermediateDirectories: true)
            try WorkspaceFixture.ownerContents.write(to: remoteRoot.appendingPathComponent(WorkspaceFixture.ownerMarker), atomically: true, encoding: .utf8)
            let remote = remoteRoot.appendingPathComponent("repository-0.git", isDirectory: true)
            try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
            try self.runGit(remote, "init", "--bare")
            try self.runGit(worktree, "remote", "add", "origin", remote.path)
            try self.runGit(worktree, "push", "origin", "main")
            // GitHub rejects a pull request whose branch has no commits.
            try "Auto PR task change.\n".write(to: worktree.appendingPathComponent("task-change.txt"), atomically: true, encoding: .utf8)

            self.openTask(named: "Auto PR toggle UI")
        })
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first?["pullRequestNumber"] != nil
        }, timeout: 15), "Auto PR should create the pull request itself once the task reaches Review.")
        element("back-to-board-button").click()
        let prLink = app.links["task-pr-link-\(taskID)-501"]
        XCTAssertTrue(prLink.waitForExistence(timeout: 10), "The auto-created PR number should appear on the card without the user clicking the PR button.")
        XCTAssertTrue(element("task-pr-mode-\(taskID)").exists, "The mode pill stays beside the linked PR so autopilot and merge remain switchable.")
        XCTAssertEqual(element("task-pr-mode-\(taskID)").value as? String, "pr")
        attachScreenshot(named: "Auto PR created the pull request automatically once the task reached Review", fullScreen: true)

        let stickyOn = try XCTUnwrap(try runCLI(["task", "create", "--title", "Sticky Auto PR on UI", "--prompt", "Fixture task description.", "--root", fixture.primary.path])["result"] as? [String: Any])
        XCTAssertEqual(stickyOn["autoCreatePullRequestOnReview"] as? Bool, true, "A task created after turning the switch on in the UI should start on.")
        let stickyOnID = try XCTUnwrap(stickyOn["id"] as? String)
        let autopilot = try XCTUnwrap(try runCLI(["task", "pr", "mode", stickyOnID, "autopilot"])["result"] as? [String: Any])
        XCTAssertEqual(autopilot["pullRequestMode"] as? String, "autopilot")
        XCTAssertEqual(autopilot["autoCreatePullRequestOnReview"] as? Bool, true, "Autopilot opens the pull request too.")
        let invalidMode = try runCLI(["task", "pr", "mode", stickyOnID, "sometimes"], expectedStatus: 2)
        XCTAssertEqual((invalidMode["error"] as? [String: Any])?["code"] as? String, "invalid_argument")
        XCTAssertEqual(try taskRecord(id: stickyOnID)?["pullRequestMode"] as? String, "autopilot", "A rejected mode must not change the task.")
        _ = try runCLI(["task", "pr", "auto", stickyOnID, "off"])
        let stickyOff = try XCTUnwrap(try runCLI(["task", "create", "--title", "Sticky Auto PR off UI", "--prompt", "Fixture task description.", "--root", fixture.primary.path])["result"] as? [String: Any])
        XCTAssertEqual(stickyOff["autoCreatePullRequestOnReview"] as? Bool, false, "A task created after turning the switch off should start off.")

        let manualCreated = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Manual PR toggle default UI", "--prompt", "Fixture task description.", "--repo", fixture.secondary.path,
            "--merge-target", "\(fixture.secondary.path)=main",
        ])["result"] as? [String: Any])
        let manualTaskID = try XCTUnwrap(manualCreated["id"] as? String)
        XCTAssertFalse(manualCreated["autoCreatePullRequestOnReview"] as? Bool ?? true, "Auto PR must default to off so existing manual tasks are unaffected.")
        let missing = try runCLI(["task", "pr", "auto", "00000000-0000-0000-0000-000000000000", "on"], expectedStatus: 3)
        XCTAssertEqual((missing["error"] as? [String: Any])?["code"] as? String, "not_found")
        openTask(named: "Manual PR toggle default UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Manual PR toggle default UI")
        element("back-to-board-button").click()
        XCTAssertEqual(try taskRecord(id: manualTaskID)?["status"] as? String, "Review")
        XCTAssertNil((try taskRecord(id: manualTaskID)?["repositoryWorktrees"] as? [[String: Any]])?.first?["pullRequestNumber"], "With Auto PR off, reaching Review must not create a pull request by itself.")
        let manualButton = element("task-create-pr-\(manualTaskID)")
        XCTAssertTrue(manualButton.waitForExistence(timeout: 5), "Auto PR off must leave the existing manual PR button in place.")
        let manualRecord = try XCTUnwrap((try taskRecord(id: manualTaskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let manualWorktree = URL(fileURLWithPath: try XCTUnwrap(manualRecord["worktreePath"] as? String), isDirectory: true)
        let manualRemoteRoot = dataDirectory.appendingPathComponent("manual-pr-remotes", isDirectory: true)
        try FileManager.default.createDirectory(at: manualRemoteRoot, withIntermediateDirectories: true)
        try WorkspaceFixture.ownerContents.write(to: manualRemoteRoot.appendingPathComponent(WorkspaceFixture.ownerMarker), atomically: true, encoding: .utf8)
        let manualRemote = manualRemoteRoot.appendingPathComponent("repository-0.git", isDirectory: true)
        try FileManager.default.createDirectory(at: manualRemote, withIntermediateDirectories: true)
        try runGit(manualRemote, "init", "--bare")
        try runGit(manualWorktree, "remote", "add", "origin", manualRemote.path)
        try runGit(manualWorktree, "push", "origin", "main")
        try "Manual PR task change.\n".write(to: manualWorktree.appendingPathComponent("task-change.txt"), atomically: true, encoding: .utf8)
        revealOnBoard(manualButton)
        manualButton.click()
        let manualPRLink = app.links["task-pr-link-\(manualTaskID)-502"]
        XCTAssertTrue(manualPRLink.waitForExistence(timeout: 10), "The manual PR flow must still work unchanged when Auto PR stays off.")
    }

    // case-contract: test_task_pr_autopilot_fixes_red_pull_request_until_green | `task pr status` reports each linked PR's check state, failing check names, and a green, red, or pending health, and reads unresolved review threads only for an autopilot task; the board colours each linked PR number green, red, or blue by that health and keeps the mode pill beside linked PRs. Autopilot leaves a task inactive unless its mode is autopilot and it sits in Review. With checks still running it sends no turn, and the board re-probes only those autopilot PRs on a slow poll until they settle. When checks fail or review threads are unresolved it sends one visible Playhouse autopilot fix turn through the task's provider that names the failing checks and unresolved threads, asks the model to judge every comment critically and to reply to and resolve each thread whether or not it changes code, and allows waiting-response for blockers it cannot fix (such as a GitHub outage or a Jira ticket the user must add); the task is In Progress during that turn and returns to Review when it reports completed. Once the PR is green autopilot sends nothing, never merges it, and resets its loop guard, so the same red state returning later (picked up by the focus probe) is fixed again. A fix turn that reports waiting-response stops the loop until the user sends the task back to Review, after which autopilot may try the red PR once more; a red state unchanged since the last fix moves the task to Waiting Response with a reason instead of being sent again, and the CLI case also drives the five-attempt cap to its Waiting Response stop.
    func test_task_pr_autopilot_fixes_red_pull_request_until_green() throws {
        let executable = try makeCodexFixture(emptyQuestions: false)
        codexFixtureExecutable = executable.path
        var ghEnvironment = try makeGitHubStateFixture(expectedNumbers: []).merging(Self.prCheckCooldownEnvironment) { $1 }
        ghEnvironment["PLAYHOUSE_E2E_PR_AUTOPILOT_POLL_SECONDS"] = "2"
        let stateURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_STATE_PATH"]))
        let callLogURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CALL_LOG"]))
        func setPullRequest(_ checks: String, threads: Int = 0) throws {
            try "801=unmerged\n801.checks=\(checks)\n801.threads=\(threads)\n".write(to: stateURL, atomically: true, encoding: .utf8)
        }
        let holdRelease = URL(fileURLWithPath: executable.path + ".hold-release")
        let turnActive = URL(fileURLWithPath: executable.path + ".turn-active")
        let turnRelease = URL(fileURLWithPath: executable.path + ".turn-release")
        defer {
            try? "Release the fixture turn.\n".write(to: turnRelease, atomically: true, encoding: .utf8)
            try? FileManager.default.removeItem(at: holdRelease)
        }
        try setPullRequest("pending")

        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "PR autopilot UI", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main", "--prompt", Self.fixtureTaskPrompt,
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        /// Holds the next autopilot fix turn, checks the task while it runs, then reports `outcome`.
        func driveAutopilotFixTurn(outcome: String, whileHeld: () throws -> Void) throws {
            XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: turnActive.path) }, timeout: 20), "Autopilot should send a fix turn for the red pull request.")
            try whileHeld()
            let reported = try runCLI(["task", "outcome", taskID, outcome])
            XCTAssertEqual((reported["result"] as? [String: Any])?["outcome"] as? String, outcome)
            try "Release the fixture turn.\n".write(to: turnRelease, atomically: true, encoding: .utf8)
            XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: turnActive.path) }, timeout: 10))
        }
        func lastUserMessage() throws -> String {
            let history = try XCTUnwrap(try runCLI(["conversation", "history", taskID])["result"] as? [String: Any])
            let messages = try XCTUnwrap(history["messages"] as? [[String: Any]])
            return try XCTUnwrap(messages.last(where: { $0["role"] as? String == "user" })?["text"] as? String)
        }
        let missing = try runCLI(["task", "pr", "autopilot", "00000000-0000-0000-0000-000000000000"], expectedStatus: 3)
        XCTAssertEqual((missing["error"] as? [String: Any])?["code"] as? String, "not_found")
        openTask(named: "PR autopilot UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "PR autopilot UI")
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ element("task-card-\(taskID)").exists }, timeout: 10))
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: taskID, number: 801, url: "https://github.com/playhouse-test/fixture/pull/801")
        let inactive = try XCTUnwrap(try runCLI(["task", "pr", "autopilot", taskID])["result"] as? [String: Any])
        XCTAssertEqual(inactive["action"] as? String, "inactive", "Autopilot must not act on a task whose mode is not autopilot.")

        // Pending checks: the PR number turns blue, and no fix turn is sent.
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let prLink = app.links["task-pr-link-\(taskID)-801"]
        XCTAssertTrue(prLink.waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({ (prLink.value as? String) == "pending" }, timeout: 15), "Running checks should colour the PR number blue.")
        XCTAssertFalse((try? String(contentsOf: callLogURL, encoding: .utf8))?.contains("threads 801") ?? false, "Only autopilot tasks read review threads.")
        let modePill = element("task-pr-mode-\(taskID)")
        XCTAssertTrue(modePill.waitForExistence(timeout: 5), "A linked PR keeps the mode pill beside it.")
        XCTAssertEqual(modePill.value as? String, "manual")
        XCTAssertGreaterThanOrEqual(modePill.frame.height, 30)
        attachScreenshot(named: "Pending checks colour the PR number blue", fullScreen: true)

        // Autopilot on while checks run: no fix turn, only the slow poll.
        try selectPullRequestMode("autopilot", taskID: taskID)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["pullRequestMode"] as? String) == "autopilot" }, timeout: 5), "Turning autopilot on should persist.")
        XCTAssertTrue(waitUntil({ (try? String(contentsOf: callLogURL, encoding: .utf8))?.contains("threads 801") ?? false }, timeout: 15), "Autopilot reads the PR's review threads.")
        try Data().write(to: holdRelease, options: .atomic)
        XCTAssertFalse(waitUntil({ FileManager.default.fileExists(atPath: turnActive.path) }, timeout: 5), "Pending checks must not start a fix turn.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        XCTAssertFalse(try lastUserMessage().hasPrefix("Playhouse autopilot:"))

        // Red: failing checks and unresolved threads, found by the poll, make autopilot send a fix turn.
        try setPullRequest("failure", threads: 2)
        try driveAutopilotFixTurn(outcome: "completed") {
            XCTAssertTrue(self.waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "In Progress" }, timeout: 10), "A fix turn brings the task back to In Progress.")
            XCTAssertTrue(self.waitUntil({ (prLink.value as? String) == "red" }, timeout: 10), "Failing checks should colour the PR number red.")
            let prompt = try lastUserMessage()
            XCTAssertTrue(prompt.hasPrefix("Playhouse autopilot:"), prompt)
            for expected in ["#801", "failing checks: fixture-ci", "2 unresolved review threads", "critically", "reply", "resolve", "waiting-response", "Jira"] {
                XCTAssertTrue(prompt.contains(expected), "The fix prompt should mention \(expected): \(prompt)")
            }
            self.attachScreenshot(named: "Autopilot moved the red PR's task back to In Progress with a fix turn", fullScreen: true)
            // The fix is pushed: the threads are answered and resolved, and CI reruns.
            try setPullRequest("pending")
        }
        assertTaskVisible("PR autopilot UI", inColumn: "Review")
        XCTAssertTrue(waitUntil({ (prLink.value as? String) == "pending" }, timeout: 20), "Rerunning checks after the fix should show blue.")
        // CI passes; the poll, not a focus change, notices. Two review-thread reads follow:
        // the poll's probe that finds green, then the daemon pass that resets the loop guard.
        let threadReads = { (try? String(contentsOf: callLogURL, encoding: .utf8))?.components(separatedBy: "\n").filter { $0 == "threads 801" }.count ?? 0 }
        let readsBeforeGreen = threadReads()
        try setPullRequest("success")
        XCTAssertTrue(waitUntil({ (prLink.value as? String) == "green" }, timeout: 20), "Passing checks should colour the PR number green.")
        let fixPromptCount = { () throws -> Int in
            try XCTUnwrap((try self.runCLI(["conversation", "history", taskID])["result"] as? [String: Any])?["messages"] as? [[String: Any]])
                .filter { ($0["text"] as? String)?.hasPrefix("Playhouse autopilot:") == true }.count
        }
        let fixPrompts = try fixPromptCount()
        attachScreenshot(named: "Autopilot fixed the PR and its number turned green", fullScreen: true)

        // The same red state as the first fix returns after green; the focus probe picks it
        // up, green reset the loop guard so it is fixed again, and the model stops the loop.
        // The guard reset is a daemon pass that reads review threads; let it finish first.
        XCTAssertTrue(waitUntil({ threadReads() >= readsBeforeGreen + 2 }, timeout: 15), "Green should run the daemon pass that resets the loop guard.")
        try setPullRequest("failure", threads: 2)
        activateOtherAppThenReturn()
        try driveAutopilotFixTurn(outcome: "waiting-response") {
            XCTAssertEqual(try lastUserMessage().hasPrefix("Playhouse autopilot:"), true)
        }
        try FileManager.default.removeItem(at: holdRelease)
        assertTaskVisible("PR autopilot UI", inColumn: "Waiting Response")
        XCTAssertEqual(try fixPromptCount(), fixPrompts + 1, "A green PR needs no fix turn; only the red-again state sends one.")
        attachScreenshot(named: "A fix turn that reports waiting-response stops the autopilot loop", fullScreen: true)

        // The user sends the task back to Review: autopilot tries the still-red PR once
        // more, and when that fix changes nothing it stops with a reason.
        openTask(named: "PR autopilot UI")
        try assertAutomaticMessageBubble(taskID: taskID, containing: "Playhouse autopilot:")
        attachScreenshot(named: "Autopilot fix prompt shown as an automatic Playhouse message")
        // The task passes through Review only until the board runs autopilot again, so the
        // fix-turn wait below, not this status, proves autopilot picked it back up.
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "PR autopilot UI", expectedFinalStatus: "In Progress", whileTurnHeld: {
            try Data().write(to: holdRelease, options: .atomic)
        })
        element("back-to-board-button").click()
        try driveAutopilotFixTurn(outcome: "completed") {}
        try FileManager.default.removeItem(at: holdRelease)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Waiting Response" }, timeout: 30), "An unchanged red state should stop autopilot in Waiting Response.")
        let reason = try taskRecord(id: taskID)?["statusMessage"] as? String
        XCTAssertTrue((reason ?? "").contains("nothing changed"), reason ?? "nil")
        XCTAssertEqual(try fixPromptCount(), fixPrompts + 2)
        assertTaskVisible("PR autopilot UI", inColumn: "Waiting Response")
        attachScreenshot(named: "Autopilot stops with a reason when nothing changed since its last fix", fullScreen: true)
    }

    // case-contract: test_task_pr_merge_mode_merges_green_pull_request | Merge mode does everything autopilot does (it reads review threads, and red pull requests take the same autopilot fix path covered by the autopilot case) and also merges each linked pull request once it is green: with checks still running, or no checks reported yet on a freshly pushed head, it merges nothing and the task stays in Review; once checks pass (or the head has had no checks past the registration grace, as in a repository without CI) with no unresolved threads and GitHub reporting it mergeable, it merges the PR through GitHub CLI, pinned to the head commit it saw green, with the first merge method the repository allows (squash when allowed, otherwise a merge commit), exactly once; the PR reads as merged, the task stays in Review for the user to complete, and the card shows the merged completion action. A head that still has no checks after the registration grace is merged all the same. A merge GitHub refuses (for example a required review) moves the task to Waiting Response with GitHub's reason instead of retrying.
    func test_task_pr_merge_mode_merges_green_pull_request() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        var ghEnvironment = try makeGitHubStateFixture(expectedNumbers: []).merging(Self.prCheckCooldownEnvironment) { $1 }
        ghEnvironment["PLAYHOUSE_E2E_PR_AUTOPILOT_POLL_SECONDS"] = "2"
        let stateURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_STATE_PATH"]))
        let callLogURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CALL_LOG"]))
        let mergeLogURL = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CREATE_LOG"]))
        func merges() -> [String] {
            ((try? String(contentsOf: mergeLogURL, encoding: .utf8)) ?? "").components(separatedBy: "\n").filter { $0.hasPrefix("merge") }
        }
        try "811=unmerged\n811.checks=pending\n812=unmerged\n812.checks=none\n812.merge=Pull request is not mergeable: a review is required\n"
            .write(to: stateURL, atomically: true, encoding: .utf8)

        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        var taskIDs: [String] = []
        for (title, repository) in [("PR merge mode UI", fixture.primary), ("PR merge refused UI", fixture.secondary)] {
            let created = try XCTUnwrap(try runCLI([
                "task", "create", "--title", title, "--repo", repository.path, "--merge-target", "\(repository.path)=main",
                "--prompt", Self.fixtureTaskPrompt,
            ])["result"] as? [String: Any])
            taskIDs.append(try XCTUnwrap(created["id"] as? String))
            openTask(named: title)
            try completeCurrentTaskWithFixtureAnswers(taskTitle: title)
            element("back-to-board-button").click()
        }
        let (taskID, refusedID) = (taskIDs[0], taskIDs[1])
        /// The no-checks grace runs from the head's commit time; pin it either way.
        func commitHead(_ id: String, committedAt: String? = nil) throws {
            let record = try XCTUnwrap((try taskRecord(id: id)?["repositoryWorktrees"] as? [[String: Any]])?.first)
            let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
            let dates = committedAt.map { ["GIT_AUTHOR_DATE": $0, "GIT_COMMITTER_DATE": $0] } ?? [:]
            _ = try runGitOutput(worktree, ["commit", "--allow-empty", "-m", "Fixture head"], environment: dates)
        }
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: taskID, number: 811, url: "https://github.com/playhouse-test/fixture/pull/811")
        try seedTaskPullRequest(taskID: refusedID, number: 812, url: "https://github.com/playhouse-test/fixture/pull/812")
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)

        let prLink = app.links["task-pr-link-\(taskID)-811"]
        XCTAssertTrue(prLink.waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({ (prLink.value as? String) == "pending" }, timeout: 15))
        let pill = element("task-pr-mode-\(taskID)")
        XCTAssertTrue(pill.waitForExistence(timeout: 5))
        pill.click()
        let mergeOption = settledPillOption("merge", taskID: taskID)
        attachScreenshot(named: "The open mode pill offers Merge beside the linked PR", fullScreen: true)
        mergeOption.click()
        XCTAssertTrue(waitUntil({ pill.exists && (pill.value as? String) == "merge" }, timeout: 5), "Choosing Merge should fold the pill onto Merge.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["pullRequestMode"] as? String) == "merge" }, timeout: 5))
        XCTAssertTrue(waitUntil({ (try? String(contentsOf: callLogURL, encoding: .utf8))?.contains("threads 811") ?? false }, timeout: 15), "Merge mode reads review threads like autopilot.")
        XCTAssertFalse(waitUntil({ !merges().isEmpty }, timeout: 5), "Running checks must not be merged.")
        try commitHead(taskID)
        try (try String(contentsOf: stateURL, encoding: .utf8)).replacingOccurrences(of: "811.checks=pending", with: "811.checks=none")
            .write(to: stateURL, atomically: true, encoding: .utf8)
        XCTAssertFalse(waitUntil({ !merges().isEmpty }, timeout: 5), "A head with no checks reported yet must not be merged.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review", "A freshly pushed head may not have registered its checks yet.")
        try (try String(contentsOf: stateURL, encoding: .utf8)).replacingOccurrences(of: "811.checks=none", with: "811.checks=pending")
            .write(to: stateURL, atomically: true, encoding: .utf8)
        attachScreenshot(named: "Merge mode waits while checks run", fullScreen: true)

        try (try String(contentsOf: stateURL, encoding: .utf8)).replacingOccurrences(of: "811.checks=pending", with: "811.checks=success")
            .write(to: stateURL, atomically: true, encoding: .utf8)
        let completeButton = element("task-complete-merged-pr-\(taskID)")
        XCTAssertTrue(completeButton.waitForExistence(timeout: 20), "Once green, merge mode should merge the PR and the card should offer completion.")
        XCTAssertEqual(merges().filter { $0.contains("\t811\t") }, ["merged\t811\t--squash"], "The PR is merged once with the first allowed method.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review", "Merging leaves the task in Review for the user to complete.")
        attachScreenshot(named: "Merge mode merged the green PR and the card offers completion", fullScreen: true)

        // Long past the grace with still no checks (a repository without CI): merge mode
        // still attempts the merge; GitHub refuses it, so the task stops with GitHub's reason.
        try commitHead(refusedID, committedAt: "2020-01-01T00:00:00Z")
        try selectPullRequestMode("merge", taskID: refusedID)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: refusedID)?["status"] as? String) == "Waiting Response" }, timeout: 20), "A refused merge of a PR with no checks should stop merge mode in Waiting Response.")
        let noCIReason = try taskRecord(id: refusedID)?["statusMessage"] as? String ?? ""
        XCTAssertTrue(noCIReason.contains("couldn't merge pull request #812") && !noCIReason.contains("no checks"), noCIReason)
        XCTAssertEqual(merges().filter { $0.contains("\t812\t") }, ["merge-failed\t812\t--squash"], "No checks past the grace is still merged, with the first allowed method.")
        assertTaskVisible("PR merge refused UI", inColumn: "Waiting Response")
        attachScreenshot(named: "Merge mode attempts the merge when GitHub reports no checks", fullScreen: true)

        // The user sends it back to Review; GitHub still refuses the merge. The
        // `repo.methods` line, written after #811 merged, disallows squash from here on.
        try (try String(contentsOf: stateURL, encoding: .utf8))
            .appending("repo.methods=merge,rebase\n").write(to: stateURL, atomically: true, encoding: .utf8)
        openTask(named: "PR merge refused UI")
        // Settling covers Review, the probe, the daemon's merge attempt, and its refusal.
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "PR merge refused UI", expectedFinalStatus: "Waiting Response", settleTimeout: 30)
        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: refusedID)?["statusMessage"] as? String) ?? "").contains("couldn't merge pull request #812") }, timeout: 20), "A refused merge should stop in Waiting Response.")
        let reason = try taskRecord(id: refusedID)?["statusMessage"] as? String ?? ""
        XCTAssertTrue(reason.contains("couldn't merge pull request #812") && reason.contains("a review is required"), reason)
        assertTaskVisible("PR merge refused UI", inColumn: "Waiting Response")
        XCTAssertEqual(merges().filter { $0.contains("\t812\t") }, ["merge-failed\t812\t--squash", "merge-failed\t812\t--merge"], "A refused merge is not retried within a pass.")
        attachScreenshot(named: "A refused merge stops in Waiting Response with GitHub's reason", fullScreen: true)
    }

    // case-contract: test_task_pr_conflicts_detect_without_mutation | The real Git CLI detects merge conflicts without mutation, and PR creation still publishes the task branch and reaches the normal GitHub CLI path; conflicts do not block PR creation. CLI/XPC resolves staged conflicts locally without pushing and commits and pushes a staged resolution without changing the target. The paired UI confirms PR creation proceeds for a conflicted branch and the existing Fix Conflicts action still appears once the PR is linked.
    func test_task_pr_conflicts_detect_without_mutation() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "PR conflict choice UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        _ = try XCTUnwrap((created["repositoryWorktrees"] as? [[String: Any]])?.first)
        openTask(named: "PR conflict choice UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "PR conflict choice UI")
        let completedRecord = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(completedRecord["worktreePath"] as? String), isDirectory: true)

        let conflictPath = "playhouse-pr-conflict-fixture.txt"
        let originalTargetHead = try runGitOutput(fixture.primary, "rev-parse", "main")
        addTeardownBlock { [self] in
            try? runGit(fixture.primary, "remote", "remove", "origin")
            try? runGit(fixture.primary, "reset", "--hard", originalTargetHead)
        }
        try "target branch version\n".write(to: fixture.primary.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(fixture.primary, "add", conflictPath)
        try runGit(fixture.primary, "commit", "-m", "Update PR target fixture")
        try "task branch version\n".write(to: worktree.appendingPathComponent(conflictPath), atomically: true, encoding: .utf8)
        try runGit(worktree, "add", conflictPath)
        try runGit(worktree, "commit", "-m", "Update task branch fixture")
        let branchHead = try runGitOutput(worktree, "rev-parse", "HEAD")
        let targetHead = try runGitOutput(fixture.primary, "rev-parse", "main")
        let remote = runDirectory.appendingPathComponent("pr-conflict-origin.git", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remote.path), "Each UI case should start with an isolated bare remote fixture.")
        try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
        _ = try runGitOutput(remote, "init", "--bare")
        try runGit(fixture.primary, "remote", "add", "origin", remote.path)
        try runGit(fixture.primary, "push", "--set-upstream", "origin", "main")
        let conflictResult = try runCLI(["task", "pr", "conflicts", taskID])["result"] as? [String: Any]
        XCTAssertEqual(conflictResult?["repositories"] as? [String], [fixture.primary.path])
        XCTAssertEqual(try runGitOutput(worktree, "rev-parse", "HEAD"), branchHead, "Conflict detection must leave the task branch unchanged.")
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", "main"), targetHead, "Conflict detection must leave the target branch unchanged.")
        XCTAssertEqual(try String(contentsOf: worktree.appendingPathComponent(conflictPath), encoding: .utf8), "task branch version\n")
        XCTAssertEqual(try String(contentsOf: fixture.primary.appendingPathComponent(conflictPath), encoding: .utf8), "target branch version\n")

        element("back-to-board-button").click()
        let prButton = element("task-create-pr-\(taskID)")
        XCTAssertTrue(prButton.waitForExistence(timeout: 5))
        revealOnBoard(prButton)
        prButton.click()
        let failureAlert = app.sheets.matching(NSPredicate(format: "label == %@", "alert")).firstMatch
        XCTAssertTrue(failureAlert.waitForExistence(timeout: 10), "The local bare remote should reach the normal GitHub CLI failure after the task branch is published.")
        let conflictGuidance = failureAlert.staticTexts.matching(
            NSPredicate(format: "value BEGINSWITH %@", "Resolve conflicts")
        ).firstMatch
        XCTAssertFalse(conflictGuidance.exists, "Conflicts must no longer block PR creation.")
        let ghGuidance = failureAlert.staticTexts.matching(
            NSPredicate(format: "value CONTAINS %@", "GitHub CLI")
        ).firstMatch
        XCTAssertTrue(ghGuidance.exists, "The failure should come from the normal GitHub CLI path, not a conflict preflight.")
        failureAlert.buttons["OK"].click()
        XCTAssertEqual(try runGitOutput(worktree, "rev-parse", "HEAD"), branchHead)
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", "main"), targetHead)
        XCTAssertEqual(
            try runGitOutput(fixture.primary, "ls-remote", "--heads", "origin", try XCTUnwrap(completedRecord["branch"] as? String))
                .trimmingCharacters(in: .whitespacesAndNewlines),
            "\(branchHead)\trefs/heads/\(try XCTUnwrap(completedRecord["branch"] as? String))",
            "A conflicted task branch should still be published for PR creation."
        )
        XCTAssertTrue(waitUntil({ prButton.isEnabled }, timeout: 10))
        XCTAssertNil((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first?["pullRequestNumber"])
        let finalRecord = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertNil(finalRecord["pullRequestNumber"])
    }

    // case-contract: test_done_archive_displays_existing_pull_request_link | CLI/XPC creates PRs for two repositories, verifies the first PR persists when the second creation fails, retries only the missing repository, confirms each gh create call targets the corresponding repository worktree, and confirms both saved numbers on fresh reads. The UI labels active-card and Done-archive multi-repository creation actions PRs, clicks the active action, verifies the partial-success retry action, confirms the gh create calls target both repository worktrees and retry only the failed one, then shows exact PR numbers on the active task and Done archive, including four-digit values without grouping separators, each with a hit target at least 30 points wide and tall. Hovering the outer padded edge of each PR link triggers its feedback.
    func test_done_archive_displays_existing_pull_request_link() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        // The fixture `gh` handles list/create and merged-state calls without GitHub sign-in.
        let ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [])
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI(["task", "create", "--title", "Archived linked PR UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path, "--repo", fixture.secondary.path])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        openTask(named: "Archived linked PR UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Archived linked PR UI")
        element("back-to-board-button").click()
        moveTaskToDone(taskID: taskID)
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Done")
        element("done-archive-button").click()
        let archiveCreatePRButton = element("done-archive-create-pr-\(taskID)")
        XCTAssertTrue(archiveCreatePRButton.waitForExistence(timeout: 10))
        XCTAssertEqual(archiveCreatePRButton.label, "PRs. Create pull requests for each repository linked to this completed task")
        attachScreenshot(named: "Done archive labels its multi-repository action PRs")
        element("done-archive-button").click()

        let activeCreated = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Active linked PR UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path, "--repo", fixture.secondary.path,
        ])["result"] as? [String: Any])
        let activeTaskID = try XCTUnwrap(activeCreated["id"] as? String)
        openTask(named: "Active linked PR UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Active linked PR UI")
        element("back-to-board-button").click()
        XCTAssertEqual(try taskRecord(id: activeTaskID)?["status"] as? String, "Review")
        XCTAssertTrue(terminateAppAndWait(app), "Close Playhouse before clearing the fixture provider session.")
        try clearTaskProviderSession(taskID: activeTaskID)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let createPRButton = element("task-create-pr-\(activeTaskID)")
        XCTAssertTrue(createPRButton.waitForExistence(timeout: 5), "An active repository task should expose its Create PR button.")
        XCTAssertEqual(createPRButton.label, "PRs. Create pull requests for each repository linked to this task")
        revealOnBoard(createPRButton)
        assertHoverEmphasis(for: createPRButton)
        attachScreenshot(named: "Multi-repository task labels its action PRs")
        let records = try XCTUnwrap((try taskRecord(id: activeTaskID)?["repositoryWorktrees"] as? [[String: Any]]))
        let remoteRoot = dataDirectory.appendingPathComponent("multi-pr-remotes", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remoteRoot.path), "Each case must start with isolated PR remotes.")
        try FileManager.default.createDirectory(at: remoteRoot, withIntermediateDirectories: true)
        try WorkspaceFixture.ownerContents.write(to: remoteRoot.appendingPathComponent(WorkspaceFixture.ownerMarker), atomically: true, encoding: .utf8)
        for repository in [fixture.primary, fixture.secondary] {
            XCTAssertFalse(try runGitOutput(repository, "remote").split(whereSeparator: \.isNewline).contains("origin"), "The isolated source fixture must not already have an origin remote.")
        }
        addTeardownBlock { [self] in
            for repository in [fixture.primary, fixture.secondary] {
                try? runGit(repository, "remote", "remove", "origin")
            }
        }
        for (index, record) in records.enumerated() {
            let remote = remoteRoot.appendingPathComponent("repository-\(index).git", isDirectory: true)
            try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
            try runGit(remote, "init", "--bare")
            let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String))
            try runGit(worktree, "remote", "add", "origin", remote.path)
            try runGit(worktree, "push", "origin", "main")
            try "Repository \(index) task change.\n".write(to: worktree.appendingPathComponent("task-change.txt"), atomically: true, encoding: .utf8)
        }
        let failurePath = URL(fileURLWithPath: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CREATE_FAILURE_PATH"]))
        try "2\n".write(to: failurePath, atomically: true, encoding: .utf8)
        createPRButton.click()
        let partialFailure = app.sheets.firstMatch
        XCTAssertTrue(partialFailure.waitForExistence(timeout: 30), "The second repository's configured gh failure should surface in the task.")
        partialFailure.buttons["OK"].click()
        let firstCreatedLink = app.links["task-pr-link-\(activeTaskID)-501"]
        XCTAssertTrue(firstCreatedLink.waitForExistence(timeout: 10), "The first repository's successful PR should persist after the second fails.")
        XCTAssertEqual(firstCreatedLink.label, "#501")
        let retryPRButton = element("task-create-pr-\(activeTaskID)")
        XCTAssertTrue(retryPRButton.waitForExistence(timeout: 10), "The task should keep a PRs action while another repository has no PR.")
        XCTAssertEqual(retryPRButton.label, "PRs. Create pull requests for repositories without a linked pull request")
        attachScreenshot(named: "Task shows its PR and retry action after partial creation")
        try "\n".write(to: failurePath, atomically: true, encoding: .utf8)
        retryPRButton.click()
        let secondCreatedLink = app.links["task-pr-link-\(activeTaskID)-502"]
        XCTAssertTrue(secondCreatedLink.waitForExistence(timeout: 30), "Retry should create a PR for the repository still missing one.")
        XCTAssertEqual(secondCreatedLink.label, "#502")
        let createdTask = try XCTUnwrap(taskRecord(id: activeTaskID))
        let createdRecords = try XCTUnwrap(createdTask["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertEqual(createdRecords.compactMap { $0["pullRequestNumber"] as? Int }, [501, 502])
        let createLog = try String(contentsOfFile: try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CREATE_LOG"]), encoding: .utf8)
        XCTAssertEqual(createLog.components(separatedBy: "\n").filter { $0.hasPrefix("created\t") }.count, 2)
        XCTAssertEqual(createLog.components(separatedBy: "\n").filter { $0.hasPrefix("failed\t") }.count, 1)
        let createTargets = createLog.components(separatedBy: "\n")
            .filter { $0.hasPrefix("create\t") || $0.hasPrefix("failed\t") }
            .compactMap { $0.split(separator: "\t", maxSplits: 2).dropFirst().first.map(String.init) }
            .map { $0.replacingOccurrences(of: "/private/tmp/", with: "/tmp/") }
        let expectedCreateTargets = try [records[0], records[1], records[1]].map {
            URL(fileURLWithPath: try XCTUnwrap($0["worktreePath"] as? String))
                .resolvingSymlinksInPath().path.replacingOccurrences(of: "/private/tmp/", with: "/tmp/")
        }
        XCTAssertEqual(createTargets, expectedCreateTargets, "The action should create one PR per repository and retry only the repository whose first create failed.")
        attachScreenshot(named: "Task shows PR numbers for both repositories")

        app.terminate()
        XCTAssertTrue(waitUntil({ app.state == .notRunning }, timeout: 10), "The app must close its SwiftData container before seeding the archived store.")
        let activePRURL = "https://github.com/playhouse-test/fixture/pull/1234"
        try seedTaskPullRequest(taskID: activeTaskID, number: 1234, url: activePRURL)
        let prURL = "https://github.com/playhouse-test/fixture/pull/1234"
        let secondPRURL = "https://github.com/playhouse-test/fixture/pull/1235"
        try seedTaskPullRequest(taskID: taskID, number: 1234, url: prURL)
        try seedTaskPullRequest(taskID: taskID, number: 1235, url: secondPRURL, repositoryIndex: 1)
        let persisted = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(persisted["status"] as? String, "Done")
        let record = try XCTUnwrap((persisted["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(record["pullRequestNumber"] as? Int, 1234)
        XCTAssertEqual(record["pullRequestURL"] as? String, prURL)
        XCTAssertEqual((persisted["repositoryWorktrees"] as? [[String: Any]])?.count, 2)

        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let firstActiveLink = app.links["task-pr-link-\(activeTaskID)-1234"]
        let secondActiveLink = app.links["task-pr-link-\(activeTaskID)-502"]
        XCTAssertTrue(firstActiveLink.waitForExistence(timeout: 10))
        XCTAssertTrue(secondActiveLink.waitForExistence(timeout: 10), "The active task card should show each repository's created PR number.")
        XCTAssertEqual(firstActiveLink.label, "#1234")
        XCTAssertEqual(secondActiveLink.label, "#502")
        element("done-archive-button").click()
        XCTAssertTrue(element("done-archive-task-\(taskID)").waitForExistence(timeout: 10))
        let prLink = app.links["done-archive-pr-link-\(taskID)-1234"]
        XCTAssertTrue(prLink.waitForExistence(timeout: 10), "The Done archive should show the saved PR number as a link.")
        let secondPRLink = app.links["done-archive-pr-link-\(taskID)-1235"]
        XCTAssertTrue(secondPRLink.waitForExistence(timeout: 10), "The Done archive should show every repository's saved PR number.")
        XCTAssertEqual(prLink.label, "#1234")
        XCTAssertEqual(secondPRLink.label, "#1235")
        for link in [prLink, secondPRLink] {
            XCTAssertGreaterThanOrEqual(link.frame.width, 30, "A Done archive PR link should have a comfortable horizontal hit target.")
            XCTAssertGreaterThanOrEqual(link.frame.height, 30, "A Done archive PR link should have a comfortable vertical hit target.")
            XCTAssertTrue(link.isHittable, "A Done archive PR link must be reachable at its own position, not resolved to the board under the archive.")
        }
        assertHoverEmphasis(for: prLink)
        attachScreenshot(named: "Done archive shows the linked pull request")
    }

    // case-contract: test_task_pr_create_skips_unchanged_repositories | PR creation opens a pull request only for repositories whose task branch has commits its merge target lacks: in a two-repository task where only the primary worktree changed, gh create runs once, against the primary worktree, the primary saves its PR number on a fresh read, and the unchanged secondary keeps no PR link instead of failing the whole operation with GitHub's no-commits error. A task whose every repository is unchanged is rejected with a message saying no repository has changes to open a pull request for, with no gh create call and no PR link saved. The UI shows the primary's PR link after clicking the PRs action and reports the all-unchanged message in the failure alert.
    func test_task_pr_create_skips_unchanged_repositories() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [])
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Skip unchanged UI", "--prompt", "Fixture task description.", "--repo", fixture.primary.path, "--repo", fixture.secondary.path,
            "--merge-target", "\(fixture.primary.path)=main", "--merge-target", "\(fixture.secondary.path)=main",
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        openTask(named: "Skip unchanged UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Skip unchanged UI")
        element("back-to-board-button").click()
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review")
        XCTAssertTrue(terminateAppAndWait(app), "Close Playhouse before clearing the fixture provider session.")
        try clearTaskProviderSession(taskID: taskID)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)

        let records = try XCTUnwrap((try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]]))
        let remoteRoot = dataDirectory.appendingPathComponent("skip-unchanged-remotes", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remoteRoot.path), "Each case must start with isolated PR remotes.")
        try FileManager.default.createDirectory(at: remoteRoot, withIntermediateDirectories: true)
        try WorkspaceFixture.ownerContents.write(to: remoteRoot.appendingPathComponent(WorkspaceFixture.ownerMarker), atomically: true, encoding: .utf8)
        for repository in [fixture.primary, fixture.secondary] {
            XCTAssertFalse(try runGitOutput(repository, "remote").split(whereSeparator: \.isNewline).contains("origin"), "The isolated source fixture must not already have an origin remote.")
        }
        addTeardownBlock { [self] in
            for repository in [fixture.primary, fixture.secondary] {
                try? runGit(repository, "remote", "remove", "origin")
            }
        }
        for (index, record) in records.enumerated() {
            let remote = remoteRoot.appendingPathComponent("repository-\(index).git", isDirectory: true)
            try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
            try runGit(remote, "init", "--bare")
            let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String))
            try runGit(worktree, "remote", "add", "origin", remote.path)
            try runGit(worktree, "push", "origin", "main")
        }
        let primaryWorktree = URL(fileURLWithPath: try XCTUnwrap(records[0]["worktreePath"] as? String), isDirectory: true)
        try "Only the primary repository changed.\n".write(to: primaryWorktree.appendingPathComponent("task-change.txt"), atomically: true, encoding: .utf8)

        let createPRButton = element("task-create-pr-\(taskID)")
        XCTAssertTrue(createPRButton.waitForExistence(timeout: 5), "The two-repository task should expose its PRs action.")
        revealOnBoard(createPRButton)
        createPRButton.click()
        let primaryLink = app.links["task-pr-link-\(taskID)-501"]
        XCTAssertTrue(primaryLink.waitForExistence(timeout: 30), "The changed repository should get its pull request.")
        // The link can appear while the secondary repository is still being checked; wait for the operation to settle.
        let remainingPRButton = element("task-create-pr-\(taskID)")
        XCTAssertTrue(waitUntil({ remainingPRButton.exists && remainingPRButton.isEnabled }, timeout: 30), "The PR operation should finish for every repository.")
        XCTAssertEqual(remainingPRButton.label, "PRs. Create pull requests for repositories without a linked pull request")
        XCTAssertFalse(app.sheets.firstMatch.exists, "An unchanged repository must not fail the PR operation.")
        let createdRecords = try XCTUnwrap(taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertEqual(createdRecords[0]["pullRequestNumber"] as? Int, 501)
        XCTAssertNil(createdRecords[1]["pullRequestNumber"], "The unchanged repository must keep no PR link.")
        let createLogPath = try XCTUnwrap(ghEnvironment["PLAYHOUSE_E2E_GH_CREATE_LOG"])
        let createTargets = try String(contentsOfFile: createLogPath, encoding: .utf8).components(separatedBy: "\n")
            .filter { $0.hasPrefix("create\t") }
            .compactMap { $0.split(separator: "\t", maxSplits: 2).dropFirst().first.map(String.init) }
            .map { $0.replacingOccurrences(of: "/private/tmp/", with: "/tmp/") }
        XCTAssertEqual(createTargets, [primaryWorktree.resolvingSymlinksInPath().path.replacingOccurrences(of: "/private/tmp/", with: "/tmp/")], "gh create must run only for the changed repository.")
        attachScreenshot(named: "Only the changed repository gets a pull request")

        // The secondary source repository keeps the origin its first task worktree added.
        let unchanged = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Nothing to propose UI", "--prompt", "Fixture task description.", "--repo", fixture.secondary.path,
            "--merge-target", "\(fixture.secondary.path)=main",
        ])["result"] as? [String: Any])
        let unchangedID = try XCTUnwrap(unchanged["id"] as? String)
        openTask(named: "Nothing to propose UI")
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Nothing to propose UI")
        element("back-to-board-button").click()
        XCTAssertEqual(try taskRecord(id: unchangedID)?["status"] as? String, "Review")
        let unchangedButton = element("task-create-pr-\(unchangedID)")
        XCTAssertTrue(unchangedButton.waitForExistence(timeout: 5))
        revealOnBoard(unchangedButton)
        unchangedButton.click()
        let alertSheet = app.sheets.firstMatch
        XCTAssertTrue(alertSheet.waitForExistence(timeout: 30), "A task with no changes should report why no pull request was opened.")
        XCTAssertTrue(waitUntil({
            self.element(containingAccessibilityText: "No repository in this task has changes").exists
        }, timeout: 5), app.debugDescription)
        attachScreenshot(named: "A task with no changes explains why no pull request was opened")
        alertSheet.buttons["OK"].click()
        XCTAssertNil((try taskRecord(id: unchangedID)?["repositoryWorktrees"] as? [[String: Any]])?.first?["pullRequestNumber"])
        XCTAssertEqual(try String(contentsOfFile: createLogPath, encoding: .utf8).components(separatedBy: "\n").filter { $0.hasPrefix("create\t") }.count, 1, "An all-unchanged task must not call gh create.")
    }

    // case-contract: test_task_lifecycle_rollout_clears_records_and_clean_worktrees | The one-time lifecycle rollout clears task records and clean managed worktrees, preserves branches, and retains dirty managed worktrees with a notice.
    func test_task_lifecycle_rollout_clears_records_and_clean_worktrees() throws {
        _ = try runCLI(["settings", "set-parent", fixture.parent.path])
        let clean = try runCLI(["task", "create", "--title", "Rollout clean", "--prompt", "Fixture task description.", "--repo", fixture.primary.path])
        let dirty = try runCLI(["task", "create", "--title", "Rollout dirty", "--prompt", "Fixture task description.", "--repo", fixture.secondary.path])
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let cleanTaskID = try XCTUnwrap((clean["result"] as? [String: Any])?["id"] as? String)
        let dirtyTaskID = try XCTUnwrap((dirty["result"] as? [String: Any])?["id"] as? String)
        _ = try runCLI(["conversation", "send", cleanTaskID, "--message", "Materialize the clean worktree.", "--answer", "color=Blue", "--answer", "token=fixture-secret"])
        _ = try runCLI(["conversation", "send", dirtyTaskID, "--message", "Materialize the dirty worktree.", "--answer", "color=Blue", "--answer", "token=fixture-secret"])
        let cleanResult = try XCTUnwrap(try runCLI(["task", "get", cleanTaskID])["result"] as? [String: Any])
        let dirtyResult = try XCTUnwrap(try runCLI(["task", "get", dirtyTaskID])["result"] as? [String: Any])
        let cleanRecord = try XCTUnwrap((cleanResult["repositoryWorktrees"] as? [[String: Any]])?.first)
        let dirtyRecord = try XCTUnwrap((dirtyResult["repositoryWorktrees"] as? [[String: Any]])?.first)
        let cleanPath = try XCTUnwrap(cleanRecord["worktreePath"] as? String)
        let dirtyPath = try XCTUnwrap(dirtyRecord["worktreePath"] as? String)
        let cleanBranch = try XCTUnwrap(cleanRecord["branch"] as? String)
        let dirtyBranch = try XCTUnwrap(dirtyRecord["branch"] as? String)
        let retainedFile = URL(fileURLWithPath: dirtyPath).appendingPathComponent("playhouse-secondary.txt")
        try "Secondary baseline.\nKeep this worktree.\n".write(to: retainedFile, atomically: true, encoding: .utf8)
        try FileManager.default.removeItem(at: dataDirectory.appendingPathComponent("task-lifecycle-v2-reset"))

        launchApp(defaultParent: fixture.parent.path)
        let resetNotice = element("task-lifecycle-reset-notice")
        let resetDetails = element("task-lifecycle-reset-details")
        XCTAssertTrue(resetNotice.waitForExistence(timeout: 10), app.debugDescription)
        XCTAssertTrue(element("task-lifecycle-reset-title").exists)
        XCTAssertTrue(accessibleLabelOrValue(of: resetDetails).contains(dirtyPath), app.debugDescription)
        element("dismiss-task-lifecycle-reset-notice").click()
        XCTAssertNil(try taskRecord(named: "Rollout clean"))
        XCTAssertNil(try taskRecord(named: "Rollout dirty"))
        XCTAssertFalse(FileManager.default.fileExists(atPath: cleanPath))
        XCTAssertEqual(try String(contentsOf: retainedFile, encoding: .utf8), "Secondary baseline.\nKeep this worktree.\n")
        try runGit(fixture.primary, "show-ref", "--verify", "--quiet", "refs/heads/\(cleanBranch)")
        try runGit(fixture.secondary, "show-ref", "--verify", "--quiet", "refs/heads/\(dirtyBranch)")
        attachScreenshot(named: "Lifecycle rollout clears tasks and reports a retained dirty worktree")
    }

    // case-contract: test_task_status_transitions_and_rejects_unknown_status | With both pairs populated, the board keeps Blocked above Backlog and Waiting Response above In Progress, allows vertical scrolling to reach lower backlog tasks, leaves Review as its own column, hides empty status sections, removes Done from the columns, and rejects manual changes to Codex-owned task status; ⌘F reveals and focuses a prominent board search that filters task cards by title as text changes, while close restores all cards. Answering a question without an explicit completed outcome leaves the task in Waiting Response. Task card titles use slightly expanded letter spacing and line spacing. The board's columns stay centered and clickable where they draw after a sideways scroll followed by a new card, without needing a window resize.
    func test_task_status_transitions_and_rejects_unknown_status() throws {
        let waitingFixture = WorkspaceFixture.root.appendingPathComponent("codex-fixture-status-transition-ui")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: waitingFixture.path))
        codexFixtureExecutable = waitingFixture.path
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Status transitions", roots: [fixture.primary.path])
        try createTaskFixture(title: "Searchable board card", roots: [fixture.alternate.path])
        let titleElement = app.staticTexts["Searchable board card"]
        XCTAssertTrue(titleElement.waitForExistence(timeout: 5), "The task card should expose its rendered title text.")
        let titleFont = NSFont.systemFont(ofSize: 13, weight: .semibold)
        let untrackedWidth = ("Searchable board card" as NSString).size(withAttributes: [.font: titleFont]).width
        XCTAssertGreaterThan(
            titleElement.frame.width,
            untrackedWidth + 2,
            "The title's rendered width should reflect the added letter spacing."
        )
        let wrappedTitle = "Task card title spacing increases between wrapped lines"
        try createTaskFixture(title: wrappedTitle, roots: [fixture.alternate.path])
        let wrappedTitleElement = app.staticTexts[wrappedTitle]
        XCTAssertTrue(wrappedTitleElement.waitForExistence(timeout: 5))
        let wrappedTitleBaseline = NSAttributedString(
            string: wrappedTitle,
            attributes: [.font: titleFont, .kern: 0.35]
        ).boundingRect(
            with: CGSize(width: wrappedTitleElement.frame.width, height: .greatestFiniteMagnitude),
            options: [.usesLineFragmentOrigin, .usesFontLeading]
        ).height
        XCTAssertGreaterThan(
            wrappedTitleElement.frame.height,
            wrappedTitleBaseline + 1,
            "Wrapped task titles should have visible spacing between lines."
        )
        XCTAssertFalse(element("board-search-field").exists, "Board search should stay hidden until requested.")
        XCTAssertFalse(element("task-count").exists, "The top bar should not show a task counter.")
        XCTAssertFalse(element("board-search-button").exists, "The top bar should not show a search button; search is keyboard-only.")
        app.typeKey("f", modifierFlags: .command)
        let boardSearch = element("board-search-field")
        XCTAssertTrue(boardSearch.waitForExistence(timeout: 5), "Command+F should reveal the prominent board search.")
        XCTAssertLessThan(element("board-search-bar").frame.maxY, element("board-columns-scroll-view").frame.minY, "Board search should sit above the task columns.")
        boardSearch.typeText("Searchable")
        XCTAssertTrue(app.buttons["Searchable board card"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.buttons["Status transitions"].exists, "Nonmatching task cards should be filtered out.")
        element("close-board-search-button").click()
        XCTAssertFalse(element("board-search-field").exists)
        XCTAssertTrue(app.buttons["Status transitions"].exists)
        XCTAssertTrue(app.buttons["Searchable board card"].exists)
        let columns = ["backlog", "in-progress", "review"]
        for column in columns { XCTAssertTrue(element("column-heading-\(column)").exists, "Missing \(column) board column.") }
        XCTAssertFalse(element("column-heading-done").exists, "Done tasks should live in the archive, not a board column.")
        XCTAssertFalse(element("column-heading-waiting-response").exists, "Waiting Response should be hidden when no tasks are waiting.")
        let inProgressColumn = element("column-in-progress")
        let reviewColumn = element("column-review")
        let boardViewport = element("board-columns-scroll-view")
        XCTAssertLessThan(inProgressColumn.frame.maxX, reviewColumn.frame.minX, "Review should remain a separate column after the stacked pair.")
        XCTAssertLessThanOrEqual(inProgressColumn.frame.maxY, boardViewport.frame.maxY, "In Progress should fit inside the visible board area.")
        XCTAssertLessThanOrEqual(reviewColumn.frame.maxY, boardViewport.frame.maxY, "Review should fit inside the visible board area.")
        XCTAssertFalse(element("column-heading-blocked").exists, "The blocked section should be hidden when no tasks are blocked.")
        XCTAssertFalse(element("blocked-waiting-indicator").exists)
        XCTAssertFalse(element("column-heading-ready").exists)
        assertTaskVisible("Status transitions", inColumn: "Backlog")

        let statusTaskID = try taskID(named: "Status transitions")
        assertCLIError(try runCLI(["task", "move", statusTaskID, "Unknown"], expectedStatus: 2), code: "invalid_argument")
        for status in ["In Progress", "Blocked", "Waiting Response", "Review", "Done", "Backlog"] {
            assertCLIError(try runCLI(["task", "move", statusTaskID, status], expectedStatus: 2), code: "invalid_argument")
        }
        XCTAssertEqual(try taskRecord(named: "Status transitions")?["status"] as? String, "Backlog")
        assertTaskVisible("Status transitions", inColumn: "Backlog")

        let blockedTask = try runCLI(["task", "create", "--title", "Blocked layout", "--prompt", "Fixture task description.", "--root", fixture.secondary.path])
        let blockedTaskID = try XCTUnwrap((blockedTask["result"] as? [String: Any])?["id"] as? String)
        let emptyFixture = try makeCodexFixture(emptyQuestions: true)
        assertCLIError(
            try runCLI(
                ["conversation", "send", blockedTaskID, "--message", "Please ask your questions."],
                expectedStatus: 1,
                extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": emptyFixture.path]
            ),
            code: "operation_failed"
        )
        XCTAssertEqual(try taskRecord(id: blockedTaskID)?["status"] as? String, "Blocked")

        try createTaskFixture(title: "In Progress layout", roots: [fixture.alternate.path])
        let activeTaskID = try taskID(named: "In Progress layout")
        let activeExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-progress-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: activeExecutable.path))
        let activeTurn = try startProgressFixtureTurn(taskID: activeTaskID, executable: activeExecutable)
        defer {
            if activeTurn.process.isRunning {
                try? "Release the active turn.\n".write(to: activeTurn.releaseMarker, atomically: true, encoding: .utf8)
                activeTurn.process.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeTurn.activeMarker)
            try? FileManager.default.removeItem(at: activeTurn.releaseMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeTurn.activeMarker.path) }, timeout: 10))
        XCTAssertEqual(try taskRecord(id: activeTaskID)?["status"] as? String, "In Progress")

        try createTaskFixture(title: "Waiting layout", roots: [fixture.secondary.path])
        let waitingTaskID = try taskID(named: "Waiting layout")
        openTask(named: "Waiting layout")
        let modeMenu = element("conversation-mode-menu")
        XCTAssertTrue(modeMenu.waitForExistence(timeout: 5))
        modeMenu.click()
        app.menuItems["Plan mode"].click()
        XCTAssertTrue(modeMenu.label.contains("Plan mode"))
        element("message-composer").click()
        element("message-composer").typeText("Please share your plan.")
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        XCTAssertEqual(try taskRecord(id: waitingTaskID)?["status"] as? String, "Waiting Response")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))

        assertTaskVisible("Blocked layout", inColumn: "Blocked")
        assertTaskVisible("Status transitions", inColumn: "Backlog")
        assertTaskVisible("Waiting layout", inColumn: "Waiting Response")
        assertTaskVisible("In Progress layout", inColumn: "In Progress")
        XCTAssertTrue(element("column-heading-blocked").exists)
        XCTAssertTrue(element("column-heading-waiting-response").exists)
        XCTAssertTrue(element("blocked-waiting-indicator").exists)
        let blockedColumn = element("column-blocked")
        let backlogColumn = element("column-backlog")
        let waitingResponseColumn = element("column-waiting-response")
        XCTAssertLessThan(blockedColumn.frame.maxY, backlogColumn.frame.minY, "Blocked should remain stacked above Backlog.")
        XCTAssertLessThan(waitingResponseColumn.frame.maxY, inProgressColumn.frame.minY, "Waiting Response should remain stacked above In Progress.")
        for topColumn in [blockedColumn, waitingResponseColumn] {
            XCTAssertGreaterThanOrEqual(topColumn.frame.minY, boardViewport.frame.minY)
        }
        // Lower backlog tasks are reached by scrolling the board; each column starts in view.
        for bottomColumn in [backlogColumn, inProgressColumn, reviewColumn] {
            XCTAssertLessThan(bottomColumn.frame.minY, boardViewport.frame.maxY)
        }
        XCTAssertLessThan(inProgressColumn.frame.maxX, reviewColumn.frame.minX, "Review should remain a separate column after the stacked pair.")
        XCTAssertFalse(element("column-heading-done").exists, "Done tasks should remain outside the board columns.")
        XCTAssertEqual(try taskRecord(id: activeTaskID)?["status"] as? String, "In Progress")
        attachScreenshot(named: "Blocked and Waiting Response stacks fit with their active columns and Review")

        let blockedCard = element("task-card-\(blockedTaskID)")
        blockedCard.rightClick()
        XCTAssertTrue(element("rename-task-menu-item").waitForExistence(timeout: 5), "Stacked columns should retain full task-card actions.")
        XCTAssertTrue(element("delete-task-menu-item").exists)
        app.typeKey(.escape, modifierFlags: [])

        openTask(named: "Waiting layout")
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 5))
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10))
        XCTAssertEqual(try taskRecord(id: waitingTaskID)?["status"] as? String, "Waiting Response")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Waiting layout", inColumn: "Waiting Response")

        // This task exists for board layout, so it settles explicitly rather than
        // depending on the status-nudge fallback that other cases own.
        XCTAssertEqual(
            (try runCLI(["task", "outcome", activeTaskID, "waiting-response"])["result"] as? [String: Any])?["outcome"] as? String,
            "waiting-response"
        )
        try "Release the active turn.\n".write(to: activeTurn.releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !activeTurn.process.isRunning }, timeout: 30), "The In Progress fixture conversation should finish once released.")
        activeTurn.process.waitUntilExit()
        let activeOutput = String(data: activeTurn.stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        let activeError = String(data: activeTurn.stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        XCTAssertEqual(activeTurn.process.terminationStatus, 0, "The In Progress fixture turn should complete: \(activeOutput) \(activeError)")
        let activeResponseLine = try XCTUnwrap(activeOutput.split(whereSeparator: \.isNewline).last)
        let activeResponse = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(activeResponseLine.utf8)) as? [String: Any])
        XCTAssertTrue(activeResponse["ok"] as? Bool == true)
        XCTAssertEqual(try taskRecord(id: activeTaskID)?["status"] as? String, "Waiting Response")
        assertTaskVisible("In Progress layout", inColumn: "Waiting Response")

        for index in 1...12 {
            try createTaskFixture(title: "Backlog scroll \(index)", roots: [fixture.primary.path])
        }
        let lowestTask = app.buttons["Backlog scroll 1"]
        XCTAssertFalse(lowestTask.isHittable, "The final backlog task should begin below the board viewport.")
        for _ in 0..<20 where !lowestTask.isHittable {
            boardViewport.scroll(byDeltaX: 0, deltaY: -300)
        }
        XCTAssertTrue(waitUntil({ lowestTask.exists && lowestTask.isHittable }, timeout: 10), "Vertical board scrolling should make lower backlog tasks reachable.")

        // The columns are narrower than the window, so the board centers them. A sideways
        // scroll nudge followed by a content-height change used to leave hit testing flush
        // left while the columns still drew centered, so clicks missed every card and button
        // until the window was resized.
        // The newest card lands at the top, so start there; any later vertical scroll would
        // re-sync the stale geometry and hide the regression.
        let newestBacklogTask = app.buttons["Backlog scroll 12"]
        for _ in 0..<20 where !newestBacklogTask.isHittable {
            boardViewport.scroll(byDeltaX: 0, deltaY: 300)
        }
        XCTAssertTrue(waitUntil({ newestBacklogTask.isHittable }, timeout: 10), "Scrolling up should return to the top of the backlog.")
        let mainWindow = app.windows["main"]
        XCTAssertTrue(mainWindow.exists)
        let centeredBacklogMinX = backlogColumn.frame.minX
        XCTAssertGreaterThan(centeredBacklogMinX - mainWindow.frame.minX, 40, "The window is wider than the columns, so they should sit centered: backlog=\(backlogColumn.frame), window=\(mainWindow.frame).")
        boardViewport.scroll(byDeltaX: -120, deltaY: 0)
        boardViewport.scroll(byDeltaX: 120, deltaY: 0)
        try createTaskFixture(title: "Backlog after nudge", roots: [fixture.primary.path])
        let nudgedTask = app.buttons["Backlog after nudge"]
        XCTAssertTrue(waitUntil({ nudgedTask.exists && nudgedTask.isHittable }, timeout: 10), "The new backlog card should appear at the top of the column.")
        XCTAssertTrue(waitUntil({ abs(backlogColumn.frame.minX - centeredBacklogMinX) <= 4 }, timeout: 3), "A sideways nudge and a new card should not move the board's hit-test layout away from where it draws: backlog=\(backlogColumn.frame), expected minX=\(centeredBacklogMinX).")
        attachScreenshot(named: "Centered board after a sideways nudge and a new card: columns stay where they draw")
        // Click near the card's drawn trailing edge, derived from the centered layout
        // rather than its current accessibility frame, so a stale hit-test layout
        // (shifted toward the leading edge) would miss the card.
        let cardTrailingInset = nudgedTask.frame.maxX - backlogColumn.frame.minX
        let drawnCardPoint = CGPoint(x: centeredBacklogMinX + cardTrailingInset - 12, y: nudgedTask.frame.midY)
        mainWindow.coordinate(withNormalizedOffset: .zero)
            .withOffset(CGVector(dx: drawnCardPoint.x - mainWindow.frame.minX, dy: drawnCardPoint.y - mainWindow.frame.minY))
            .click()
        XCTAssertTrue(element("task-view-title").waitForExistence(timeout: 10), "Clicking the card where it draws should open the task.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
    }

    // case-contract: test_waiting_response_task_moves_to_review_manually | A task in Waiting Response moves to Review through the CLI and on the board, both from its card's Move to Review context-menu item, which only Waiting Response cards offer, and by dragging the card onto the Review column. The move runs the same review gate as a completed outcome: local changes on a PR-linked worktree are committed before the task reaches Review. It clears the waiting status, persists across a fresh CLI/XPC read, keeps the linked pull request, returns a task already in Review unchanged, and the moved task can still complete to Done. A Backlog task is rejected and keeps its status; a task whose turn is still running while it shows Waiting Response is rejected and keeps both its status and its uncommitted changes; and when the pull request sync fails, the move reports the error, shown on the board as an alert, and leaves the task in Waiting Response, so a retry after the fix moves it to Review.
    func test_waiting_response_task_moves_to_review_manually() throws {
        let questionFixture = WorkspaceFixture.root.appendingPathComponent("codex-fixture-status-transition-ui")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: questionFixture.path))
        codexFixtureExecutable = questionFixture.path
        let ghEnvironment = try makeGitHubStateFixture(expectedNumbers: [321]).merging(Self.prCheckCooldownEnvironment) { $1 }
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)

        // A PR-linked repository task that has already been worked on.
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Manual review menu", "--prompt", "Fixture task description.", "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any])
        let menuTaskID = try XCTUnwrap(created["id"] as? String)
        XCTAssertEqual(
            try runCLI([
                "conversation", "send", menuTaskID, "--message", "Please ask your questions.", "--mode", "plan",
                "--answer", "color=Blue", "--answer", "token=fixture-secret"
            ])["ok"] as? Bool,
            true
        )
        XCTAssertEqual(try taskRecord(id: menuTaskID)?["status"] as? String, "Waiting Response")
        XCTAssertTrue(terminateAppAndWait(app))
        try seedTaskPullRequest(taskID: menuTaskID, number: 321, url: "https://github.com/playhouse-test/fixture/pull/321")
        let record = try XCTUnwrap((try taskRecord(id: menuTaskID)?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: ghEnvironment)

        try createTaskFixture(title: "Manual review backlog", roots: [fixture.alternate.path])
        let backlogTaskID = try taskID(named: "Manual review backlog")
        assertCLIError(try runCLI(["task", "move", backlogTaskID, "Review"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try taskRecord(id: backlogTaskID)?["status"] as? String, "Backlog")
        element("task-card-\(backlogTaskID)").rightClick()
        XCTAssertTrue(element("rename-task-menu-item").waitForExistence(timeout: 5))
        XCTAssertFalse(element("move-task-to-review-menu-item").exists, "Only Waiting Response cards offer Move to Review.")
        app.typeKey(.escape, modifierFlags: [])

        // A pending blocking question shows Waiting Response while its turn still runs.
        openTask(named: "Manual review menu")
        let modeMenu = element("conversation-mode-menu")
        XCTAssertTrue(modeMenu.waitForExistence(timeout: 5))
        modeMenu.click()
        app.menuItems["Plan mode"].click()
        element("message-composer").click()
        element("message-composer").typeText("Please share your plan.")
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        XCTAssertEqual(try taskRecord(id: menuTaskID)?["status"] as? String, "Waiting Response")
        try "Waiting turn output.\n".write(to: worktree.appendingPathComponent("manual-review.txt"), atomically: true, encoding: .utf8)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Manual review menu", inColumn: "Waiting Response")

        let menuCard = element("task-card-\(menuTaskID)")
        let moveToReview = element("move-task-to-review-menu-item")
        let rejection = app.sheets.matching(NSPredicate(format: "label == %@", "alert")).firstMatch
        menuCard.rightClick()
        XCTAssertTrue(moveToReview.waitForExistence(timeout: 5), "A Waiting Response card should offer Move to Review.")
        moveToReview.click()
        XCTAssertTrue(rejection.waitForExistence(timeout: 10), "Moving a task whose turn is still running should explain the rejection.")
        XCTAssertTrue(rejection.staticTexts.matching(NSPredicate(format: "value == %@", "Couldn't move task to Review")).firstMatch.exists)
        XCTAssertTrue(rejection.staticTexts.matching(NSPredicate(format: "value CONTAINS %@", "still running")).firstMatch.exists)
        attachScreenshot(named: "Move to Review is rejected while the question's turn still runs")
        rejection.buttons["OK"].click()
        XCTAssertEqual(try taskRecord(id: menuTaskID)?["status"] as? String, "Waiting Response")
        XCTAssertTrue(try runGitOutput(worktree, "status", "--porcelain", "--untracked-files=all").contains("manual-review.txt"),
                      "A rejected move must leave the running turn's files untouched.")
        assertTaskVisible("Manual review menu", inColumn: "Waiting Response")

        openTask(named: "Manual review menu")
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 5))
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10))
        // The status reads Waiting Response before the turn releases the task, so wait for the daemon.
        let threadID = try XCTUnwrap(try taskRecord(id: menuTaskID)?["codexThreadID"] as? String)
        XCTAssertTrue(waitUntil({
            let runtime = (try? self.runCLI(["conversation", "runtime"]))?["result"] as? [String: Any]
            return runtime != nil && !((runtime?["activeThreadIDs"] as? [String] ?? []).contains(threadID))
                && (try? self.taskRecord(id: menuTaskID)?["status"] as? String) == "Waiting Response"
        }, timeout: 30), "The answered turn should finish in Waiting Response.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))

        // A pull request sync that fails reports the error and leaves the task waiting.
        let missingRemote = runDirectory.appendingPathComponent("manual-review-missing-origin.git", isDirectory: true)
        try runGit(fixture.primary, "remote", "add", "origin", missingRemote.path)
        addTeardownBlock { [self] in
            // The case removes it itself on success; only clean up after an early failure.
            if (try? runGitOutput(fixture.primary, "remote"))?.split(whereSeparator: \.isNewline).contains("origin") == true {
                try? runGit(fixture.primary, "remote", "remove", "origin")
            }
        }
        menuCard.rightClick()
        XCTAssertTrue(moveToReview.waitForExistence(timeout: 5))
        moveToReview.click()
        XCTAssertTrue(rejection.waitForExistence(timeout: 15), "A failed pull request sync should be shown to the user.")
        XCTAssertTrue(rejection.staticTexts.matching(NSPredicate(format: "value == %@", "Couldn't move task to Review")).firstMatch.exists)
        XCTAssertFalse(rejection.staticTexts.matching(NSPredicate(format: "value CONTAINS %@", "still running")).firstMatch.exists,
                       "This alert should report the sync failure, not the finished turn.")
        XCTAssertTrue(rejection.staticTexts.matching(NSPredicate(format: "value CONTAINS %@", "origin")).firstMatch.exists,
                      "The alert should carry the git error for the unreachable PR remote.")
        attachScreenshot(named: "A failed pull request sync keeps the task in Waiting Response")
        rejection.buttons["OK"].click()
        XCTAssertEqual(try taskRecord(id: menuTaskID)?["status"] as? String, "Waiting Response")
        assertTaskVisible("Manual review menu", inColumn: "Waiting Response")
        try runGit(fixture.primary, "remote", "remove", "origin")

        menuCard.rightClick()
        XCTAssertTrue(moveToReview.waitForExistence(timeout: 5))
        attachScreenshot(named: "Waiting Response card context menu offers Move to Review")
        moveToReview.click()
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: menuTaskID)?["status"] as? String) == "Review"
        }, timeout: 15), "Move to Review should persist the Review status.")
        assertTaskVisible("Manual review menu", inColumn: "Review")
        XCTAssertNil(try taskRecord(id: menuTaskID)?["statusMessage"] as? String)
        XCTAssertEqual(try runGitOutput(worktree, "status", "--porcelain", "--untracked-files=all"), "",
                       "Moving to Review should commit the PR-linked worktree's local changes like a completed turn.")
        XCTAssertTrue(try runGitOutput(worktree, "show", "--name-only", "--format=%s", "HEAD").contains("manual-review.txt"))
        XCTAssertEqual((try taskRecord(id: menuTaskID)?["repositoryWorktrees"] as? [[String: Any]])?.first?["pullRequestNumber"] as? Int, 321)

        // Drag and drop: a Waiting Response card dropped on the Review column.
        try createTaskFixture(title: "Manual review drag", roots: [fixture.secondary.path])
        let dragTaskID = try taskID(named: "Manual review drag")
        XCTAssertEqual(
            try runCLI([
                "conversation", "send", dragTaskID, "--message", "Please ask your questions.", "--mode", "plan",
                "--answer", "color=Blue", "--answer", "token=fixture-secret"
            ])["ok"] as? Bool,
            true
        )
        XCTAssertEqual(try taskRecord(id: dragTaskID)?["status"] as? String, "Waiting Response")
        assertTaskVisible("Manual review drag", inColumn: "Waiting Response")
        attachScreenshot(named: "Waiting Response card before dragging it to Review")
        let reviewColumn = element("column-review")
        XCTAssertTrue(reviewColumn.waitForExistence(timeout: 5))
        element("task-card-\(dragTaskID)").coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
            .press(forDuration: 0.5, thenDragTo: reviewColumn.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.6)))
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: dragTaskID)?["status"] as? String) == "Review"
        }, timeout: 15), "Dropping a Waiting Response card on Review should persist the Review status.")
        assertDoneDrawerResting("after a Waiting Response card is dropped on Review")
        assertTaskVisible("Manual review drag", inColumn: "Review")
        assertTaskVisible("Manual review menu", inColumn: "Review")
        XCTAssertFalse(element("column-heading-waiting-response").exists, "Waiting Response hides once both tasks moved to Review.")
        attachScreenshot(named: "Both manually moved tasks rest in Review")

        XCTAssertEqual(
            (try runCLI(["task", "move", dragTaskID, "Review"])["result"] as? [String: Any])?["status"] as? String,
            "Review",
            "A task already in Review is returned unchanged."
        )
        moveTaskToDone(taskID: dragTaskID)
        assertTaskVisible("Manual review menu", inColumn: "Review")
        XCTAssertEqual(try taskRecord(id: backlogTaskID)?["status"] as? String, "Backlog")
    }

    // case-contract: test_task_progress_reports_publish_persist_and_clear | The CLI publishes standard and custom progress only during an active task turn, persists each report across fresh CLI/XPC connections, rejects invalid reports, and clears explicitly. During an active turn the CLI accepts completed, in-progress, and waiting-response outcomes, rejects invalid or inactive outcomes, and persists the selected status; provider processes started from the CLI/XPC service or the app's composer inherit that app's bridge service name and store directory, and an outcome reported with exactly that inherited environment reaches the task. A successful turn without an outcome receives up to five private status nudges that each offer in-progress alongside completed and waiting-response; a completed report during a nudge moves the task to Review, a waiting-response report during a nudge stops the loop and leaves the task in Waiting Response, and no report after every nudge marks the task Blocked rather than Waiting Response, since the user was never asked anything. The board shows progress details and places completed tasks in Review and waiting outcomes in Waiting Response. New threads receive hidden progress and outcome instructions at thread start, and existing threads receive them on resume; turn requests do not repeat the instructions. Those instructions require updates at phase changes, around substantial tools, and at least every 30 seconds during long work. Only an explicit completed outcome reaches Review. When a final answer ends with the outcome command written as text instead of run, the final answer, fresh history, and transcript hide that command, and it counts as the turn's outcome only when it names this task. A status nudge Playhouse sent shows its prompt and the agent's reply in Codex history and the visible transcript, including after later ordinary turns. Fresh Codex history after those nudges also retains the latest ordinary-turn diff while showing the nudge replies.
    func test_task_progress_reports_publish_persist_and_clear() throws {
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Progress reports", roots: [fixture.primary.path])
        let taskID = try taskID(named: "Progress reports")
        let executable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-unique-turns-progress-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: executable.path))
        codexFixtureExecutable = executable.path
        let activeMarker = URL(fileURLWithPath: executable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: executable.path + ".turn-release")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)

        let process = Process()
        process.executableURL = cliURL
        process.arguments = ["conversation", "send", taskID, "--message", "Work on this task."]
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        environment["CODEX_HOME"] = dataDirectory.appendingPathComponent("codex-home").path
        environment["PLAYHOUSE_WORKTREE_LABEL"] = "Playhouse UI Test Worktree"
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = executable.path
        process.environment = environment
        let stdout = DrainingPipe()
        let stderr = DrainingPipe()
        process.standardOutput = stdout.pipe
        process.standardError = stderr.pipe
        try process.run()

        defer {
            if process.isRunning {
                try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                process.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The Codex fixture should hold the conversation turn open.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress")

        let built = try runCLI(["task", "progress", "publish", taskID, "--type", "building", "--detail", "Compiling the app"])
        XCTAssertEqual((built["result"] as? [String: Any])?["progressLabel"] as? String, "Building")
        let reportID = "task-progress-report-\(taskID.uppercased())"
        let report = element(reportID)
        let label = element("task-progress-label-\(taskID.uppercased())")
        let icon = element("task-progress-icon-\(taskID.uppercased())")
        XCTAssertTrue(waitUntil({
            report.exists && report.label.contains("Building") && report.label.contains("Compiling the app")
        }, timeout: 10), "The board card should expose the Building label and detail.")
        XCTAssertTrue(waitUntil({ icon.exists && icon.label == "hammer" }, timeout: 10), "The Building SF Symbol should be exposed as a visible, accessible image.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress", "Publishing progress must not change lifecycle state.")
        XCTAssertEqual(try taskRecord(id: taskID)?["progressDetail"] as? String, "Compiling the app", "A fresh CLI/XPC connection should read the persisted report.")

        let custom = try runCLI(["task", "progress", "custom", taskID, "--label", "Checking migration", "--detail", "Reading the stored task data"])
        let customRecord = try XCTUnwrap(custom["result"] as? [String: Any])
        XCTAssertNil(customRecord["progressType"] as? String)
        XCTAssertEqual(customRecord["progressLabel"] as? String, "Checking migration")
        XCTAssertTrue(waitUntil({
            report.exists && report.label.contains("Checking migration") && report.label.contains("Reading the stored task data")
        }, timeout: 10), "The task card should update to a custom report with its detail and generic icon.")
        XCTAssertTrue(waitUntil({ icon.exists && icon.label == "sparkle" }, timeout: 10), "The custom report should expose its generic SF Symbol as a visible, accessible image.")
        assertCLIError(try runCLI(["task", "progress", "publish", taskID, "--type", "unknown"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["task", "progress", "custom", taskID, "--label", " "], expectedStatus: 2), code: "invalid_argument")

        let cleared = try runCLI(["task", "progress", "clear", taskID])
        XCTAssertNil((cleared["result"] as? [String: Any])?["progressLabel"])
        relaunchApp()
        XCTAssertTrue(waitForDisappearance(label), "Clearing a report should remove its secondary row from the card.")
        _ = try runCLI(["task", "progress", "publish", taskID, "--type", "testing"])
        relaunchApp()
        let completedOutcome = try runCLI(["task", "outcome", taskID, "completed"])
        let completedOutcomeRecord = try XCTUnwrap(completedOutcome["result"] as? [String: Any])
        XCTAssertEqual(completedOutcomeRecord["outcome"] as? String, "completed")
        XCTAssertEqual(completedOutcomeRecord["taskStatus"] as? String, "In Progress", "Outcome should be applied only after the turn completes.")
        try "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        process.waitUntilExit()
        let output = stdout.drainedText()
        let errorOutput = stderr.drainedText()
        XCTAssertEqual(process.terminationStatus, 0, "The fixture conversation should finish successfully: \(output) \(errorOutput)")
        let responseLine = try XCTUnwrap(output.split(whereSeparator: \.isNewline).last)
        let response = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(responseLine.utf8)) as? [String: Any])
        XCTAssertTrue(response["ok"] as? Bool == true)
        assertTaskVisible("Progress reports", inColumn: "Review")

        let resumedProcess = Process()
        resumedProcess.executableURL = cliURL
        resumedProcess.arguments = ["conversation", "send", taskID, "--message", "Continue on this task."]
        resumedProcess.environment = environment
        let resumedStdout = DrainingPipe()
        let resumedStderr = DrainingPipe()
        resumedProcess.standardOutput = resumedStdout.pipe
        resumedProcess.standardError = resumedStderr.pipe
        try resumedProcess.run()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The follow-up should resume the existing fixture thread.")
        let waitingOutcome = try runCLI(["task", "outcome", taskID, "waiting-response"])
        let waitingOutcomeRecord = try XCTUnwrap(waitingOutcome["result"] as? [String: Any])
        XCTAssertEqual(waitingOutcomeRecord["outcome"] as? String, "waiting-response")
        XCTAssertEqual(waitingOutcomeRecord["taskStatus"] as? String, "In Progress")
        try "Release the resumed turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        resumedProcess.waitUntilExit()
        let resumedOutput = resumedStdout.drainedText()
        let resumedError = resumedStderr.drainedText()
        XCTAssertEqual(resumedProcess.terminationStatus, 0, "The resumed fixture conversation should finish successfully: \(resumedOutput) \(resumedError)")
        let resumedResponseLine = try XCTUnwrap(resumedOutput.split(whereSeparator: \.isNewline).last)
        let resumedResponse = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(resumedResponseLine.utf8)) as? [String: Any])
        XCTAssertTrue(resumedResponse["ok"] as? Bool == true)
        assertTaskVisible("Progress reports", inColumn: "Waiting Response")

        let omittedProcess = Process()
        omittedProcess.executableURL = cliURL
        omittedProcess.arguments = ["conversation", "send", taskID, "--message", "A turn without an outcome."]
        omittedProcess.environment = environment
        let omittedStdout = DrainingPipe()
        let omittedStderr = DrainingPipe()
        omittedProcess.standardOutput = omittedStdout.pipe
        omittedProcess.standardError = omittedStderr.pipe
        try omittedProcess.run()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The no-outcome turn should resume the existing fixture thread.")
        for nudgeIndex in 0...Self.maxOutcomeContinuations {
            XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress", "The fallback status should be deferred until every private nudge finishes.")
            try "Release turn \(nudgeIndex + 1).\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
            if nudgeIndex < Self.maxOutcomeContinuations {
                XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The fixture should finish the current unreported turn.")
                XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "Playhouse should send the next private status nudge.")
            }
        }
        omittedProcess.waitUntilExit()
        let omittedOutput = omittedStdout.drainedText()
        let omittedError = omittedStderr.drainedText()
        XCTAssertEqual(omittedProcess.terminationStatus, 0, "The no-outcome fixture conversation should finish successfully: \(omittedOutput) \(omittedError)")

        let finished = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(finished["status"] as? String, "Blocked", "Unanswered nudges never asked the user anything, so the task is Blocked rather than Waiting Response.")
        XCTAssertTrue((finished["statusMessage"] as? String)?.contains("nudges went unanswered") == true, "The Blocked reason should say the nudges went unanswered.")
        assertTaskVisible("Progress reports", inColumn: "Blocked")
        assertCLIError(try runCLI(["task", "progress", "publish", taskID, "--type", "testing"], expectedStatus: 1), code: "invalid_transition")
        assertCLIError(try runCLI(["task", "outcome", taskID, "completed"], expectedStatus: 1), code: "invalid_transition")
        XCTAssertNil(finished["progressLabel"], "Turn completion should clear the last live report.")
        XCTAssertTrue(waitForDisappearance(report), "Turn completion should remove the progress row from the board card.")
        let reminderHistory = try runCLI(["conversation", "history", taskID])
        let reminderHistoryRecord = try XCTUnwrap(reminderHistory["result"] as? [String: Any])
        let reminderMessages = try XCTUnwrap(reminderHistoryRecord["messages"] as? [[String: Any]])
        XCTAssertTrue(reminderMessages.contains { ($0["text"] as? String)?.contains("Fixture internal reminder reply.") == true }, "Replies to the nudges Playhouse sent stay in the refreshed history.")
        let reminderDiff = try XCTUnwrap(reminderHistoryRecord["diff"] as? [String: Any])
        XCTAssertTrue((reminderDiff["unifiedDiff"] as? String)?.contains("ordinary-turn-diff-after-reminders") == true, "The latest ordinary-turn diff should remain available after private reminders.")
        openTask(named: "Progress reports")
        XCTAssertTrue(transcriptContains("Fixture internal reminder reply."), "Replies to the nudges Playhouse sent appear in the visible transcript.")
        let recoveredProcess = Process()
        recoveredProcess.executableURL = cliURL
        recoveredProcess.arguments = ["conversation", "send", taskID, "--message", "Report the outcome after a reminder."]
        recoveredProcess.environment = environment
        let recoveredStdout = DrainingPipe()
        let recoveredStderr = DrainingPipe()
        recoveredProcess.standardOutput = recoveredStdout.pipe
        recoveredProcess.standardError = recoveredStderr.pipe
        try recoveredProcess.run()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The reminder recovery fixture turn should become active.")
        try "Release the initial unreported turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The initial unreported turn should finish before the reminder.")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "Playhouse should send a private reminder after the omitted outcome.")
        let bridgeEnvironmentURL = URL(fileURLWithPath: executable.path + ".bridge-environment")
        let bridgeEnvironment = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: bridgeEnvironmentURL)) as? [String: String]
        )
        let reminderOutcome = try runCLI(["task", "outcome", taskID, "completed"], extraEnvironment: bridgeEnvironment)
        XCTAssertEqual((reminderOutcome["result"] as? [String: Any])?["outcome"] as? String, "completed")
        try "Release the reminder after its outcome is reported.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        recoveredProcess.waitUntilExit()
        let recoveredOutput = recoveredStdout.drainedText()
        let recoveredError = recoveredStderr.drainedText()
        XCTAssertEqual(recoveredProcess.terminationStatus, 0, "The reminder recovery fixture conversation should finish successfully: \(recoveredOutput) \(recoveredError)")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Review", "A completed CLI outcome reported during a private reminder should be honored.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Progress reports", inColumn: "Review")
        openTask(named: "Progress reports")
        XCTAssertTrue(transcriptContains("ended without reporting a task outcome"), "The nudge Playhouse sent must appear in the visible transcript.")
        try assertAutomaticMessageBubble(taskID: taskID, containing: "ended without reporting a task outcome")
        XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse internal outcome nudge:")).count, 0, "The marker line that identifies a nudge is not shown.")
        attachScreenshot(named: "Playhouse status nudge shown as an automatic message")
        XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse private outcome reminder hidden")).count, 0, "Private reminder prompts should not be rendered in the transcript.")
        XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse private outcome response hidden")).count, 0, "Private reminder replies should not be rendered in the transcript.")
        let waitingReminderProcess = Process()
        waitingReminderProcess.executableURL = cliURL
        waitingReminderProcess.arguments = ["conversation", "send", taskID, "--message", "Report waiting after a reminder."]
        waitingReminderProcess.environment = environment
        let waitingReminderStdout = DrainingPipe()
        let waitingReminderStderr = DrainingPipe()
        waitingReminderProcess.standardOutput = waitingReminderStdout.pipe
        waitingReminderProcess.standardError = waitingReminderStderr.pipe
        try waitingReminderProcess.run()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The waiting outcome fixture turn should become active.")
        try "Release the initial unreported turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The initial turn should finish before asking for its outcome.")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "Playhouse should send a reminder before reporting a waiting outcome.")
        let waitingReminderOutcome = try runCLI(["task", "outcome", taskID, "waiting-response"], extraEnvironment: bridgeEnvironment)
        XCTAssertEqual((waitingReminderOutcome["result"] as? [String: Any])?["outcome"] as? String, "waiting-response")
        try "Release the reminder after its outcome is reported.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        waitingReminderProcess.waitUntilExit()
        let waitingReminderOutput = waitingReminderStdout.drainedText()
        let waitingReminderError = waitingReminderStderr.drainedText()
        XCTAssertEqual(waitingReminderProcess.terminationStatus, 0, "The waiting reminder fixture conversation should finish successfully: \(waitingReminderOutput) \(waitingReminderError)")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Waiting Response", "A waiting-response outcome reported during a private reminder should stop retries and be honored.")
        assertTaskVisible("Progress reports", inColumn: "Waiting Response")
        let turnData = try Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))
        let turn = try XCTUnwrap(try JSONSerialization.jsonObject(with: turnData) as? [String: Any])
        let hiddenTurns = try XCTUnwrap(turn["turns"] as? [[String: Any]])
        XCTAssertEqual(hiddenTurns.count, 12, "The omitted outcome should exhaust every nudge; reported outcomes should stop after one nudge.")
        let nudgeTurns = hiddenTurns.filter { ($0["userMessage"] as? String)?.contains("ended without reporting a task outcome") == true }
        XCTAssertEqual(nudgeTurns.count, Self.maxOutcomeContinuations + 2, "Only the missing-outcome sends should receive private status nudges.")
        XCTAssertTrue(nudgeTurns.allSatisfy { ($0["userMessage"] as? String)?.contains("task outcome") == true }, "Each nudge should explicitly direct the agent to report an outcome.")
        XCTAssertTrue(nudgeTurns.allSatisfy { ($0["userMessage"] as? String)?.contains("`in-progress`") == true }, "A nudge must offer in-progress alongside completed and waiting-response.")
        let visibleHistory = try runCLI(["conversation", "history", taskID])
        let visibleMessages = try XCTUnwrap((visibleHistory["result"] as? [String: Any])?["messages"] as? [[String: Any]])
        XCTAssertTrue(visibleMessages.contains { ($0["role"] as? String) == "user" && ($0["text"] as? String)?.contains("ended without reporting a task outcome") == true }, "The nudge Playhouse sent must appear in conversation history.")
        let instructions = try XCTUnwrap(turn["threadStartDeveloperInstructions"] as? String)
        XCTAssertTrue(instructions.contains(cliURL.path))
        XCTAssertTrue(instructions.contains("task progress publish"))
        XCTAssertTrue(instructions.contains("hidden from the conversation"))
        XCTAssertTrue(instructions.contains("at least every 30 seconds"))
        XCTAssertTrue(instructions.contains("starting or finishing a substantial tool call"))
        XCTAssertTrue(instructions.contains("active suite/case and position"))
        XCTAssertTrue(instructions.contains("CLI/XPC 3/8"))
        XCTAssertTrue(instructions.contains("under 80 characters"))
        XCTAssertTrue(instructions.contains("task outcome"))
        XCTAssertTrue(instructions.contains("<completed|in-progress|waiting-response>"))
        XCTAssertTrue(instructions.contains("Never end a turn mid-work without an outcome"))
        XCTAssertTrue(instructions.contains("waiting-response"))
        XCTAssertTrue(instructions.contains("final CLI action"))
        XCTAssertEqual(turn["threadStartCount"] as? Int, 1, "The follow-up should reuse the thread created with progress instructions.")
        XCTAssertGreaterThanOrEqual(turn["threadResumeCount"] as? Int ?? 0, 1)
        let turns = try XCTUnwrap(turn["turns"] as? [[String: Any]])
        XCTAssertEqual(turns.count, 12)
        XCTAssertTrue(turns.allSatisfy { $0["developerInstructions"] == nil || $0["developerInstructions"] is NSNull }, "Thread-scoped task instructions should not be repeated in turn requests.")
        let resumeInstructions = try XCTUnwrap(turn["threadResumeDeveloperInstructions"] as? [Any])
        XCTAssertFalse(resumeInstructions.isEmpty, "Resumed task threads should receive updated task instructions.")
        XCTAssertTrue(resumeInstructions.allSatisfy { ($0 as? String)?.contains("task outcome") == true })

        // The bridge daemon starts every provider, including the one a composer turn
        // uses, and must hand it this app's bridge service and store for in-turn outcomes.
        relaunchApp()
        openTask(named: "Progress reports")
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 15), "The composer should be available for a follow-up.")
        composer.click()
        composer.typeText("Finish this task from the app.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 15), "The composer turn should hold the fixture turn open.")
        let composerBridgeEnvironment = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: bridgeEnvironmentURL)) as? [String: String],
            "The provider process should receive the bridge service name and store directory."
        )
        XCTAssertEqual(composerBridgeEnvironment["PLAYHOUSE_BRIDGE_SERVICE_NAME"], serviceName)
        XCTAssertEqual(
            URL(fileURLWithPath: try XCTUnwrap(composerBridgeEnvironment["PLAYHOUSE_DATA_DIRECTORY"])).resolvingSymlinksInPath().path,
            dataDirectory.resolvingSymlinksInPath().path
        )
        let appOutcome = try runCLI(["task", "outcome", taskID, "completed"], extraEnvironment: composerBridgeEnvironment)
        XCTAssertEqual((appOutcome["result"] as? [String: Any])?["outcome"] as? String, "completed")
        try "Release the composer turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Review" }, timeout: 15), "An outcome reported with the provider's inherited environment should move the app-started turn to Review.")
        openTask(named: "Progress reports")
        // The reopened window starts at the newest question, so earlier nudges sit above it: check the history that feeds it.
        let laterNudgeHistory = try XCTUnwrap(try runCLI(["conversation", "history", taskID])["result"] as? [String: Any])
        XCTAssertTrue((laterNudgeHistory["messages"] as? [[String: Any]] ?? []).contains {
            ($0["role"] as? String) == "user" && (($0["text"] as? String) ?? "").contains("ended without reporting a task outcome")
        }, "A later composer history refresh must keep earlier nudges shown.")
        XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse private outcome reminder hidden")).count, 0, "Earlier private reminders should stay absent after a normal composer turn.")
        XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse private outcome response hidden")).count, 0, "Earlier private reminder replies should stay absent after a normal composer turn.")

        // A model can write its outcome command as answer text instead of running
        // it. The echo is hidden, and it counts only when it names this task.
        // Scoped to message containers: a reply's paragraphs are labelled groups too.
        let echoedAnswers = app.groups.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND label == %@", "assistant-message-", "Fixture answer with an echoed outcome."
        ))
        for (turnIndex, (echoedTaskID, expectedColumn)) in [(UUID().uuidString, "Blocked"), (taskID, "Review")].enumerated() {
            XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 15), "The composer should accept the echoed-outcome turn.")
            composer.click()
            composer.typeText("Echo the outcome command for \(echoedTaskID).")
            element("send-message-button").click()
            XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 15), "The echoed-outcome turn should hold the fixture turn open.")
            let heldTurns = turnIndex == 0 ? Self.maxOutcomeContinuations + 1 : 1
            for heldTurnIndex in 0..<heldTurns {
                try "Release echoed turn \(heldTurnIndex + 1).\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                if heldTurnIndex < heldTurns - 1 {
                    XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The current echoed turn should finish before a private nudge.")
                    XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "Playhouse should send a private nudge for an unreported echoed outcome.")
                }
            }
            XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == expectedColumn }, timeout: 15), "An echoed outcome for \(echoedTaskID) should leave the task in \(expectedColumn).")
            XCTAssertTrue(waitUntil({ echoedAnswers.count == turnIndex + 1 }, timeout: 10), "The transcript should show this turn's answer without the echoed command.")
            XCTAssertEqual(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "task outcome")).count, 0, "The transcript must not show the echoed outcome command.")
        }
        relaunchApp()
        assertTaskVisible("Progress reports", inColumn: "Review")
    }

    // case-contract: test_task_outcome_in_progress_drives_continuations_until_blocked | An in-progress outcome is accepted during an active turn, leaves the task In Progress, and makes Playhouse send a private continuation turn that names the in-progress report; a completed report during that continuation stops the loop at Review. When every turn reports in-progress, Playhouse sends exactly five continuation turns, keeps the task In Progress throughout, and then marks it Blocked with a continuation-limit reason instead of Waiting Response, since the user was never asked anything. Continuation prompts and replies appear in the conversation history as Playhouse-sent messages and their replies. The user taking the work back ends Playhouse's private driving: stopping a continuation keeps the Stop's Waiting Response with no failure reason, and a queued follow-up runs next instead of being buried under further continuations.
    func test_task_outcome_in_progress_drives_continuations_until_blocked() throws {
        let executable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-in-progress-continuation-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: executable.path))
        // The app reads each opened conversation through this fixture.
        codexFixtureExecutable = executable.path
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Continue in progress", roots: [fixture.primary.path])
        let taskID = try taskID(named: "Continue in progress")
        let activeMarker = URL(fileURLWithPath: executable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: executable.path + ".turn-release")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        environment["CODEX_HOME"] = dataDirectory.appendingPathComponent("codex-home").path
        environment["PLAYHOUSE_WORKTREE_LABEL"] = "Playhouse UI Test Worktree"
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = executable.path

        let process = Process()
        process.executableURL = cliURL
        process.arguments = ["conversation", "send", taskID, "--message", "Work on this task."]
        process.environment = environment
        let stdout = DrainingPipe()
        let stderr = DrainingPipe()
        process.standardOutput = stdout.pipe
        process.standardError = stderr.pipe
        try process.run()
        defer {
            if process.isRunning {
                try? "Release the turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                process.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 15), "The fixture should hold the first turn open.")
        let reported = try XCTUnwrap(try runCLI(["task", "outcome", taskID, "in-progress"])["result"] as? [String: Any])
        XCTAssertEqual(reported["outcome"] as? String, "in-progress")
        XCTAssertEqual(reported["taskStatus"] as? String, "In Progress", "The outcome is staged until the turn completes.")
        try "Release the in-progress turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 15), "The in-progress turn should finish before its continuation.")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 15), "Playhouse should send a continuation turn after an in-progress report.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress", "The task stays In Progress while Playhouse drives the continuation.")
        assertTaskVisible("Continue in progress", inColumn: "In Progress")
        XCTAssertEqual((try runCLI(["task", "outcome", taskID, "completed"])["result"] as? [String: Any])?["outcome"] as? String, "completed")
        try "Release the continuation turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        process.waitUntilExit()
        let output = stdout.drainedText()
        let errorOutput = stderr.drainedText()
        XCTAssertEqual(process.terminationStatus, 0, "The continuation conversation should finish successfully: \(output) \(errorOutput)")
        assertTaskVisible("Continue in progress", inColumn: "Review")
        let continuationHistory = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))) as? [String: Any]
        )
        let continuationTurns = try XCTUnwrap(continuationHistory["turns"] as? [[String: Any]])
            .filter { ($0["userMessage"] as? String)?.contains("You reported `in-progress`") == true }
        XCTAssertEqual(continuationTurns.count, 1, "One in-progress report earns exactly one continuation turn.")
        XCTAssertTrue(
            (continuationTurns[0]["userMessage"] as? String)?.contains("of \(Self.maxOutcomeContinuations)") == true,
            "The continuation prompt should name the remaining budget."
        )
        openTask(named: "Continue in progress")
        XCTAssertTrue(transcriptContains("You reported"), "Continuation prompts Playhouse sent must appear in the visible transcript.")
        try assertAutomaticMessageBubble(taskID: taskID, containing: "You reported")
        attachScreenshot(named: "Playhouse continuation prompt shown as an automatic message")
        for hidden in ["Playhouse private outcome reminder hidden", "Playhouse private outcome response hidden"] {
            XCTAssertEqual(
                app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", hidden)).count, 0,
                "No placeholder replaces a continuation or its reply."
            )
        }
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))

        // Every turn reports in-progress, so Playhouse runs out of continuations.
        try createTaskFixture(title: "Never settles", roots: [fixture.primary.path])
        let cappedID = try self.taskID(named: "Never settles")
        let cappedExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-in-progress-cap-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: cappedExecutable.path))
        codexFixtureExecutable = cappedExecutable.path
        let cappedActive = URL(fileURLWithPath: cappedExecutable.path + ".turn-active")
        let cappedRelease = URL(fileURLWithPath: cappedExecutable.path + ".turn-release")
        try? FileManager.default.removeItem(at: cappedActive)
        try? FileManager.default.removeItem(at: cappedRelease)
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = cappedExecutable.path
        let cappedProcess = Process()
        cappedProcess.executableURL = cliURL
        cappedProcess.arguments = ["conversation", "send", cappedID, "--message", "Work on this task."]
        cappedProcess.environment = environment
        let cappedStdout = DrainingPipe()
        let cappedStderr = DrainingPipe()
        cappedProcess.standardOutput = cappedStdout.pipe
        cappedProcess.standardError = cappedStderr.pipe
        try cappedProcess.run()
        defer {
            if cappedProcess.isRunning {
                try? "Release the capped turn.\n".write(to: cappedRelease, atomically: true, encoding: .utf8)
                cappedProcess.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: cappedActive)
            try? FileManager.default.removeItem(at: cappedRelease)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: cappedActive.path) }, timeout: 15), "The capped fixture should hold its first turn open.")
        for index in 0...Self.maxOutcomeContinuations {
            XCTAssertEqual(
                try taskRecord(id: cappedID)?["status"] as? String, "In Progress",
                "Every continuation keeps the task In Progress until the limit is reached."
            )
            XCTAssertEqual(
                (try runCLI(["task", "outcome", cappedID, "in-progress"])["result"] as? [String: Any])?["outcome"] as? String,
                "in-progress"
            )
            try "Release turn \(index + 1).\n".write(to: cappedRelease, atomically: true, encoding: .utf8)
            if index < Self.maxOutcomeContinuations {
                XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: cappedActive.path) }, timeout: 15), "The fixture should finish the current continuation turn.")
                XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: cappedActive.path) }, timeout: 15), "Playhouse should send the next continuation turn.")
            }
        }
        cappedProcess.waitUntilExit()
        let cappedOutput = cappedStdout.drainedText()
        let cappedError = cappedStderr.drainedText()
        XCTAssertEqual(cappedProcess.terminationStatus, 0, "The capped continuation conversation should finish successfully: \(cappedOutput) \(cappedError)")
        let cappedRecord = try XCTUnwrap(taskRecord(id: cappedID))
        XCTAssertEqual(cappedRecord["status"] as? String, "Blocked", "Running out of continuations is Blocked, not Waiting Response.")
        XCTAssertTrue(
            (cappedRecord["statusMessage"] as? String)?.contains("continuation turns") == true,
            "The Blocked reason should name the continuation limit."
        )
        assertTaskVisible("Never settles", inColumn: "Blocked")
        let cappedHistory = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: cappedExecutable.path + ".history"))) as? [String: Any]
        )
        XCTAssertEqual(
            try XCTUnwrap(cappedHistory["turns"] as? [[String: Any]])
                .filter { ($0["userMessage"] as? String)?.contains("You reported `in-progress`") == true }.count,
            Self.maxOutcomeContinuations,
            "Playhouse stops driving the work after the continuation limit."
        )

        // Stopping a private continuation is the user taking the work back.
        try createTaskFixture(title: "Stopped mid continuation", roots: [fixture.primary.path])
        let stopID = try self.taskID(named: "Stopped mid continuation")
        let stopExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-in-progress-stop-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: stopExecutable.path))
        codexFixtureExecutable = stopExecutable.path
        let stopActive = URL(fileURLWithPath: stopExecutable.path + ".turn-active")
        let stopRelease = URL(fileURLWithPath: stopExecutable.path + ".turn-release")
        try? FileManager.default.removeItem(at: stopActive)
        try? FileManager.default.removeItem(at: stopRelease)
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = stopExecutable.path
        let stopProcess = Process()
        stopProcess.executableURL = cliURL
        stopProcess.arguments = ["conversation", "send", stopID, "--message", "Work on this task."]
        stopProcess.environment = environment
        stopProcess.standardOutput = DrainingPipe().pipe
        stopProcess.standardError = DrainingPipe().pipe
        try stopProcess.run()
        defer {
            if stopProcess.isRunning {
                try? "Release the stopped continuation.\n".write(to: stopRelease, atomically: true, encoding: .utf8)
                stopProcess.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: stopActive)
            try? FileManager.default.removeItem(at: stopRelease)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: stopActive.path) }, timeout: 15), "The stop fixture should hold its first turn open.")
        XCTAssertEqual((try runCLI(["task", "outcome", stopID, "in-progress"])["result"] as? [String: Any])?["outcome"] as? String, "in-progress")
        try "Release the in-progress turn.\n".write(to: stopRelease, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: stopActive.path) }, timeout: 15), "The in-progress turn should finish before its continuation.")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: stopActive.path) }, timeout: 15), "Playhouse should send a continuation turn before the Stop.")
        // Stop persists the paused state before the provider answers, and the
        // held fixture turn only replies once released, so the Stop has to run
        // alongside the release rather than before it.
        let stopper = try startCLIProcess(["conversation", "stop", stopID])
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: stopID)?["status"] as? String) == "Waiting Response" }, timeout: 20),
                      "Stop should persist the paused state before the provider acknowledges it.")
        try "Release the stopped continuation.\n".write(to: stopRelease, atomically: true, encoding: .utf8)
        _ = try finishCLIProcess(stopper)
        stopProcess.waitUntilExit()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: stopID)?["status"] as? String) == "Waiting Response" }, timeout: 30),
                      "A Stop during a continuation keeps the user's paused state.")
        XCTAssertNil(try taskRecord(id: stopID)?["statusMessage"] as? String,
                     "A user-requested Stop must not be reported as a Playhouse failure.")
        assertTaskVisible("Stopped mid continuation", inColumn: "Waiting Response")
        let stopHistory = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: stopExecutable.path + ".history"))) as? [String: Any]
        )
        XCTAssertEqual(
            try XCTUnwrap(stopHistory["turns"] as? [[String: Any]])
                .filter { ($0["userMessage"] as? String)?.contains("You reported `in-progress`") == true }.count,
            1,
            "Playhouse must stop driving the work once the user stops it."
        )

        // A queued follow-up is the other way the user takes over.
        try createTaskFixture(title: "Queued over continuation", roots: [fixture.primary.path])
        let queuedID = try self.taskID(named: "Queued over continuation")
        let queuedExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-in-progress-queue-hold-release")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: queuedExecutable.path))
        codexFixtureExecutable = queuedExecutable.path
        let queuedActive = URL(fileURLWithPath: queuedExecutable.path + ".turn-active")
        let queuedRelease = URL(fileURLWithPath: queuedExecutable.path + ".turn-release")
        try? FileManager.default.removeItem(at: queuedActive)
        try? FileManager.default.removeItem(at: queuedRelease)
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = queuedExecutable.path
        let queuedProcess = Process()
        queuedProcess.executableURL = cliURL
        queuedProcess.arguments = ["conversation", "send", queuedID, "--message", "Work on this task."]
        queuedProcess.environment = environment
        queuedProcess.standardOutput = DrainingPipe().pipe
        queuedProcess.standardError = DrainingPipe().pipe
        try queuedProcess.run()
        defer {
            if queuedProcess.isRunning {
                try? "Release the next turn.\n".write(to: queuedRelease, atomically: true, encoding: .utf8)
                queuedProcess.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: queuedActive)
            try? FileManager.default.removeItem(at: queuedRelease)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: queuedActive.path) }, timeout: 15), "The queue fixture should hold its first turn open.")
        XCTAssertEqual((try runCLI(["task", "outcome", queuedID, "in-progress"])["result"] as? [String: Any])?["outcome"] as? String, "in-progress")
        _ = try runCLI(["conversation", "queue", queuedID, "--message", "Follow-up from the user."])
        XCTAssertTrue(waitUntil({
            try? "Release the next turn.\n".write(to: queuedRelease, atomically: true, encoding: .utf8)
            return !queuedProcess.isRunning
        }, timeout: 60), "The queued follow-up should run instead of further continuations.")
        queuedProcess.waitUntilExit()
        // The follow-up turn settles on its own terms; what matters here is that
        // it ran next instead of queueing behind Playhouse's continuations.
        let queuedHistory = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: queuedExecutable.path + ".history"))) as? [String: Any]
        )
        let queuedTurns = try XCTUnwrap(queuedHistory["turns"] as? [[String: Any]])
        XCTAssertEqual(
            queuedTurns.filter { ($0["userMessage"] as? String)?.contains("You reported `in-progress`") == true }.count, 0,
            "A queued follow-up must take precedence over Playhouse's private continuation."
        )
        XCTAssertTrue(
            queuedTurns.contains { ($0["userMessage"] as? String)?.contains("Follow-up from the user.") == true },
            "The queued follow-up should be the next turn the provider receives."
        )
        // This task's thread lives in the queue fixture; the app must read it there.
        relaunchApp()
        openTask(named: "Queued over continuation")
        XCTAssertTrue(transcriptMessage("Follow-up from the user.").waitForExistence(timeout: 15),
                      "The queued follow-up should be visible in the conversation it ran in.")
        XCTAssertEqual(
            app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "You reported")).count, 0,
            "No private continuation prompt should be visible ahead of the user's follow-up."
        )
    }

    // case-contract: test_task_progress_reports_clear_on_failed_turns_and_questions | Progress reports clear when turns fail or are interrupted and when Codex requests user input; a staged completed outcome is discarded if its turn fails, leaving the task Blocked. The task card removes the report while lifecycle states remain Blocked or In Progress. A blocking structured question appears inline and moves the task to Waiting Response; its answer resumes the active turn in In Progress, and the answered turn finishes in Waiting Response. First-thread instructions distinguish source repository paths from active task worktree paths, allow read-only inspection without attaching a repo, and reserve repository add APIs for changes that need a worktree.
    func test_task_progress_reports_clear_on_failed_turns_and_questions() throws {
        launchApp(defaultParent: fixture.parent.path)
        var heldTurns: [(Process, URL, URL)] = []
        defer {
            for (process, activeMarker, releaseMarker) in heldTurns {
                if process.isRunning {
                    try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                    process.waitUntilExit()
                }
                try? FileManager.default.removeItem(at: activeMarker)
                try? FileManager.default.removeItem(at: releaseMarker)
            }
        }
        for (fixtureName, expectedReason) in [
            ("codex-fixture-progress-hold-release-failed", "failed"),
            ("codex-fixture-progress-hold-release-interrupted", "interrupted"),
        ] {
            let title = "Progress \(expectedReason)"
            try createTaskFixture(title: title, roots: [fixture.primary.path])
            let taskID = try taskID(named: title)
            let executable = WorkspaceFixture.root.appendingPathComponent(fixtureName)
            let turn = try startProgressFixtureTurn(taskID: taskID, executable: executable)
            heldTurns.append((turn.process, turn.activeMarker, turn.releaseMarker))
            XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: turn.activeMarker.path) }, timeout: 10))
            let staged = try runCLI(["task", "outcome", taskID, "completed"])
            XCTAssertEqual((staged["result"] as? [String: Any])?["outcome"] as? String, "completed")
            XCTAssertEqual((staged["result"] as? [String: Any])?["taskStatus"] as? String, "In Progress")
            let report = element("task-progress-report-\(taskID.uppercased())")
            let label = element("task-progress-label-\(taskID.uppercased())")
            _ = try runCLI(["task", "progress", "publish", taskID, "--type", "testing", "--detail", "Waiting for the result"])
            XCTAssertEqual(try taskRecord(id: taskID)?["progressLabel"] as? String, "Testing")
            relaunchApp()
            XCTAssertTrue(element("task-card-\(taskID.uppercased())").waitForExistence(timeout: 5), "The active task should appear on the board.")
            XCTAssertEqual(try taskRecord(id: taskID)?["progressLabel"] as? String, "Testing", "Progress should remain persisted after the app relaunches.")
            XCTAssertTrue(waitUntil({ label.exists && (label.value as? String)?.contains("Testing") == true }, timeout: 20), "The active task card should show progress before a failed turn. \(app.debugDescription)")
            XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress")

            try "Release the active turn.\n".write(to: turn.releaseMarker, atomically: true, encoding: .utf8)
            turn.process.waitUntilExit()
            let output = String(data: turn.stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let finalLine = try XCTUnwrap(output.split(whereSeparator: \.isNewline).last)
            let finalResponse = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(finalLine.utf8)) as? [String: Any])
            XCTAssertFalse(finalResponse["ok"] as? Bool ?? true, "The fixture turn should end as \(expectedReason).")
            let stopped = try XCTUnwrap(taskRecord(id: taskID))
            XCTAssertEqual(stopped["status"] as? String, "Blocked")
            XCTAssertNil(stopped["progressLabel"] as? String)
            XCTAssertTrue(waitForDisappearance(report), "A failed or interrupted turn should remove its progress row from the card.")
            assertTaskVisible(title, inColumn: "Blocked")
        }

        let questionFixture = WorkspaceFixture.root.appendingPathComponent("codex-fixture-progress-user-question")
        codexFixtureExecutable = questionFixture.path
        app.launchEnvironment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = questionFixture.path
        relaunchApp()
        let questionTask = try runCLI([
            "task", "create", "--title", "Progress question", "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path, "--root", fixture.parent.path,
        ])["result"] as? [String: Any]
        let initialRepositories = try XCTUnwrap(questionTask?["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertEqual(initialRepositories.map { $0["repositoryPath"] as? String }, [fixture.primary.path])
        openTask(named: "Progress question")
        let questionTaskID = try taskID(named: "Progress question")
        let questionHistoryURL = URL(fileURLWithPath: questionFixture.path + ".history")
        let activeMarker = URL(fileURLWithPath: questionFixture.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: questionFixture.path + ".turn-release")
        let outcomeHold = URL(fileURLWithPath: questionFixture.path + ".outcome-hold")
        let outcomeActive = URL(fileURLWithPath: questionFixture.path + ".outcome-active")
        let outcomeRelease = URL(fileURLWithPath: questionFixture.path + ".outcome-release")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
        try? FileManager.default.removeItem(at: outcomeHold)
        try? FileManager.default.removeItem(at: outcomeActive)
        try? FileManager.default.removeItem(at: outcomeRelease)
        defer {
            try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
            try? "Release final turn completion.\n".write(to: outcomeRelease, atomically: true, encoding: .utf8)
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
            try? FileManager.default.removeItem(at: outcomeHold)
            try? FileManager.default.removeItem(at: outcomeActive)
            try? FileManager.default.removeItem(at: outcomeRelease)
        }
        element("message-composer").click()
        element("message-composer").typeText("Please share your plan.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The question fixture should hold the turn before asking for input.")
        let waitingReport = try runCLI(["task", "progress", "publish", questionTaskID, "--type", "reviewing", "--detail", "Preparing a question"])
        XCTAssertEqual((waitingReport["result"] as? [String: Any])?["progressLabel"] as? String, "Reviewing")
        try "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        XCTAssertTrue(element("conversation-user-input-request").waitForExistence(timeout: 10), "Structured questions should appear inline in the conversation.")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: questionHistoryURL.path) }, timeout: 5))
        let questionHistory = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: questionHistoryURL)) as? [String: Any])
        let threadInstructions = try XCTUnwrap(questionHistory["threadStartDeveloperInstructions"] as? String)
        XCTAssertTrue(threadInstructions.contains("Active task worktrees for edits"))
        XCTAssertTrue(threadInstructions.contains("workspace repos list"))
        XCTAssertTrue(threadInstructions.contains("task repository add"))
        XCTAssertTrue(threadInstructions.contains("read-only inspection of returned source paths"))
        XCTAssertTrue(threadInstructions.contains("Add a repository to this task only when you intend to create or commit changes in it"))
        XCTAssertTrue(threadInstructions.contains("workspace repos list"))
        XCTAssertTrue(threadInstructions.contains("task repository add"))
        XCTAssertTrue(threadInstructions.contains("Do not interrupt the user or ask them to confirm the selection merely because the task appears unrelated."))
        XCTAssertFalse(FileManager.default.fileExists(atPath: questionFixture.path + ".assessment.history"), "A question should not spawn a parallel repository-assessment thread.")
        XCTAssertTrue(element("ai-question-form-title").exists)
        XCTAssertEqual(try taskRecord(id: questionTaskID)?["status"] as? String, "Waiting Response")
        XCTAssertNil(try taskRecord(id: questionTaskID)?["progressLabel"] as? String, "Progress should clear as soon as Codex requests user input.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5), "The board should reopen after leaving the pending question.")
        let waitingReportLabel = element("task-progress-label-\(questionTaskID.uppercased())")
        XCTAssertTrue(waitForDisappearance(waitingReportLabel), "The active task card should not retain the agent's progress row.")
        openTask(named: "Progress question")
        XCTAssertTrue(element("conversation-user-input-request").waitForExistence(timeout: 5), "Reopening should restore the pending question inline.")
        XCTAssertTrue(app.buttons["Continue"].exists)
        app.buttons["Continue"].click()
        try "Hold final turn completion for answer status verification.\n".write(to: outcomeHold, atomically: true, encoding: .utf8)
        element("submit-ai-answers-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: outcomeActive.path) }, timeout: 10), "The fixture should acknowledge the answer and hold final completion.")
        XCTAssertEqual(try taskRecord(id: questionTaskID)?["status"] as? String, "In Progress", "Answering should leave the active turn In Progress until it finishes.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Progress question", inColumn: "In Progress")
        openTask(named: "Progress question")
        try "Release final turn completion.\n".write(to: outcomeRelease, atomically: true, encoding: .utf8)
        XCTAssertTrue(waitUntil({ !element("conversation-user-input-request").exists }, timeout: 5), "Submitting the answer should remove the inline question.")
        XCTAssertTrue(transcriptMessage("Answer received: Continue.").waitForExistence(timeout: 10), "The resumed turn should receive the submitted answer.")
        let completionDeadline = Date().addingTimeInterval(10)
        var completedStatus: String?
        while Date() < completionDeadline {
            completedStatus = try taskRecord(id: questionTaskID)?["status"] as? String
            if completedStatus == "Waiting Response" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(completedStatus, "Waiting Response", "An answered turn without an explicit completion outcome should return to Waiting Response.")
        XCTAssertNil(try taskRecord(id: questionTaskID)?["progressLabel"] as? String)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Progress question", inColumn: "Waiting Response")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
    }

    // case-contract: test_task_rename_persists_and_rejects_blank_title | A rename waits for the real per-task operation lock, then persists across fresh CLI/XPC reads; rejecting a blank rename preserves the last valid title.
    func test_task_rename_persists_and_rejects_blank_title() throws {
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Before rename", roots: [fixture.primary.path])
        let taskID = try taskID(named: "Before rename")
        let operationLock = try TaskOperationLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        let card = app.buttons.matching(NSPredicate(format: "label == %@", "Before rename")).firstMatch
        XCTAssertTrue(card.waitForExistence(timeout: 10))
        card.rightClick()
        let renameAction = element("rename-task-menu-item")
        XCTAssertTrue(renameAction.waitForExistence(timeout: 5), "The task context menu has no rename action.")
        renameAction.click()

        let titleField = element("rename-task-title-field")
        XCTAssertTrue(titleField.waitForExistence(timeout: 5))
        titleField.click()
        titleField.typeKey("a", modifierFlags: .command)
        titleField.typeText("After rename")
        element("save-task-rename-button").click()
        XCTAssertTrue(card.waitForExistence(timeout: 3), "The persisted title should remain unchanged while the task-operation lock is held.")
        try operationLock.release()
        XCTAssertTrue(app.buttons["After rename"].waitForExistence(timeout: 10))

        XCTAssertEqual(try taskRecord(named: "After rename")?["title"] as? String, "After rename")
        assertCLIError(
            try runCLI(["task", "rename", taskID, "--title", " "], expectedStatus: 2),
            code: "invalid_argument"
        )
        XCTAssertEqual(try taskRecord(named: "After rename")?["title"] as? String, "After rename")
        attachScreenshot(named: "Renamed task remains unchanged after rejected blank rename")
    }

    // case-contract: test_task_roots_set_get_order_deduplication_and_validation | Root editing preserves order, removes duplicates, rejects an empty list, and waits for an active conversation turn; a stale Git-folder validation is rejected after a newer folder edit, and the newer roots remain saved.
    func test_task_roots_set_get_order_deduplication_and_validation() throws {
        launchApp(defaultParent: fixture.parent.path)
        _ = try runCLI(["task", "create", "--title", "Edit roots", "--prompt", "Fixture task description.", "--repo", fixture.primary.path])
        openTask(named: "Edit roots")
        let taskID = try taskID(named: "Edit roots")

        let conversationReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var conversationReservationReleased = false
        defer {
            if !conversationReservationReleased { try? conversationReservation.release() }
        }
        let rootsEditProcess = try startCLIProcess([
            "task", "roots", "set", taskID,
            "--root", fixture.secondary.path,
            "--root", fixture.custom.path,
            "--root", fixture.primary.path,
        ])
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(
            try taskRecord(id: taskID)?["workspaceRoots"] as? [String],
            [fixture.primary.path],
            "Workspace roots should remain unchanged while a conversation turn holds its reservation."
        )
        try conversationReservation.release()
        conversationReservationReleased = true
        let rootsEditResult = try finishCLIProcess(rootsEditProcess)
        let expectedRoots = try XCTUnwrap((rootsEditResult["result"] as? [String: Any])?["workspaceRoots"] as? [String])
        let taskAfterEdit = try XCTUnwrap(taskRecord(named: "Edit roots"))
        XCTAssertEqual(taskAfterEdit["workspaceRoots"] as? [String], expectedRoots)
        assertOrderedRoots(expectedRoots)

        let duplicateRoots = try runCLI([
            "task", "roots", "set", taskID,
            "--root", fixture.secondary.path,
            "--root", fixture.secondary.path,
            "--root", fixture.custom.path,
            "--root", fixture.primary.path
        ])
        let rootsAfterCliEdit = try XCTUnwrap((duplicateRoots["result"] as? [String: Any])?["workspaceRoots"] as? [String])
        let result = try runCLI(["task", "roots", "get", taskID])["result"] as? [String: Any]
        XCTAssertEqual(result?["roots"] as? [String], rootsAfterCliEdit)
        assertCLIError(try runCLI(["task", "roots", "set", taskID], expectedStatus: 2), code: "invalid_argument")
        let unchanged = try runCLI(["task", "roots", "get", taskID])["result"] as? [String: Any]
        XCTAssertEqual(unchanged?["roots"] as? [String], rootsAfterCliEdit)

        let concurrentTitle = "Concurrent root edit"
        let concurrent = try runCLI([
            "task", "create", "--title", concurrentTitle, "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path,
        ])["result"] as? [String: Any]
        let concurrentID = try XCTUnwrap(concurrent?["id"] as? String)
        relaunchApp()
        let barrier = try GitConfigReadBarrier(repositoryURL: fixture.secondary)
        var staleProcess: RunningCLIProcess?
        var barrierReleased = false
        var continueStaleProcess = false
        defer {
            if !barrierReleased { try? barrier.release() }
            if !continueStaleProcess, let process = staleProcess?.process, process.isRunning {
                process.terminate()
                process.waitUntilExit()
            }
        }
        staleProcess = try startCLIProcess(["task", "roots", "set", concurrentID, "--root", fixture.secondary.path])
        try barrier.waitForReader()

        openTask(named: concurrentTitle)
        let newerRoots = try runCLI(["task", "roots", "set", concurrentID, "--root", fixture.custom.path])
        let newerRecord = try XCTUnwrap(newerRoots["result"] as? [String: Any])
        XCTAssertEqual(newerRecord["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(newerRecord["contextFolders"] as? [String], [fixture.custom.path])
        XCTAssertEqual((newerRecord["repositoryWorktrees"] as? [Any])?.isEmpty, true)
        assertOrderedRoots([fixture.custom.path])

        try barrier.release()
        barrierReleased = true
        continueStaleProcess = true
        let stale = try finishCLIProcess(try XCTUnwrap(staleProcess), expectedStatus: 1)
        XCTAssertEqual((stale["error"] as? [String: Any])?["code"] as? String, "invalid_transition")
        let fresh = try XCTUnwrap(taskRecord(id: concurrentID))
        XCTAssertEqual(fresh["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(fresh["contextFolders"] as? [String], [fixture.custom.path])
        XCTAssertEqual((fresh["repositoryWorktrees"] as? [Any])?.count, 0)
        attachScreenshot(named: "Edited ordered folders in task conversation")
    }

    // case-contract: test_conversation_repository_picker_adds_repository_worktree | Repository suggestions can be filtered and navigated with Up/Down, and Enter selects the highlighted repository; UI selection waits for an active turn and persists a pending auto branch. While the conversation is empty, a prominent theme-colored heading names all selected repositories and updates as repository APIs add or replace context; compact repository labels remain in the header without a duplicate repository summary. Dark and light themes use distinct prominent title colors, the supporting model prompt sits below with generous spacing, and the generic Start a conversation heading is absent. Additional context folders remain identifiable. The task repository API remains available during an active turn, prepares a managed worktree inside the app data directory's task-worktrees folder, updates saved repository selection, replaces repository context safely, and the paired UI shows API additions/removals. The main assistant is instructed to list repositories through Playhouse, inspect listed source paths read-only without attaching them, and add repositories only when it needs a task worktree for changes or commits.
    func test_conversation_repository_picker_adds_repository_worktree() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        let created = try runCLI(["task", "create", "--title", "Header repository picker", "--prompt", "Fixture task description.", "--root", fixture.primary.path])["result"] as? [String: Any]
        let taskID = try XCTUnwrap(created?["id"] as? String)
        openTask(named: "Header repository picker")
        element("add-conversation-repository-button").click()
        let search = element("conversation-repository-search")
        XCTAssertTrue(search.waitForExistence(timeout: 5))
        search.click()
        search.typeText("suggested-parent")
        XCTAssertTrue(element("conversation-repository-suggestion-alternate").waitForExistence(timeout: 10))
        XCTAssertTrue(element("conversation-repository-suggestion-changes").exists)
        XCTAssertTrue(element("conversation-repository-suggestion-secondary").exists)
        let suggestionResult = try runCLI(["workspace", "suggest", "--parent", fixture.parent.path])["result"] as? [String: Any]
        let suggestionPaths = try XCTUnwrap(suggestionResult?["repositories"] as? [String])
        let primarySuggestionIndex = try XCTUnwrap(suggestionPaths.firstIndex(of: fixture.primary.path))
        XCTAssertGreaterThan(primarySuggestionIndex, 0, "The primary repository should follow another suggestion so both arrow directions can be tested.")
        for _ in 0..<primarySuggestionIndex {
            search.typeKey(XCUIKeyboardKey.downArrow.rawValue, modifierFlags: [])
        }
        search.typeKey(XCUIKeyboardKey.upArrow.rawValue, modifierFlags: [])
        search.typeKey(XCUIKeyboardKey.downArrow.rawValue, modifierFlags: [])
        let suggestion = element("conversation-repository-suggestion-primary")
        XCTAssertTrue(suggestion.waitForExistence(timeout: 10))
        let conversationReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var conversationReservationReleased = false
        defer {
            if !conversationReservationReleased { try? conversationReservation.release() }
        }
        search.typeKey(XCUIKeyboardKey.return.rawValue, modifierFlags: [])
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(
            (try taskRecord(id: taskID)?["repositoryWorktrees"] as? [[String: Any]])?.count,
            0,
            "The selected repository should not be attached until the conversation turn releases its reservation."
        )
        XCTAssertEqual(
            accessibleLabelOrValue(of: repositoryTitle()),
            "primary",
            "A Git workspace root should name its repository before the pending worktree is attached."
        )
        try conversationReservation.release()
        conversationReservationReleased = true
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 10))
        let emptyTitle = repositoryTitle()
        XCTAssertEqual(accessibleLabelOrValue(of: emptyTitle), "primary", "The prominent empty-conversation title should identify the selected repository.")
        XCTAssertTrue(waitUntil({ repositoryTitleHasColor(emptyTitle, appearance: "dark") }, timeout: 5), "Dark appearance should render an orange repository title.")
        let conversationIcon = app.images["Conversation"]
        XCTAssertTrue(conversationIcon.waitForExistence(timeout: 5))
        XCTAssertGreaterThan(conversationIcon.frame.minY - emptyTitle.frame.maxY, 40, "The conversation prompt should have breathing room below the repository title.")
        XCTAssertFalse(app.staticTexts["Start a conversation"].exists, "The redundant Start a conversation heading should be removed.")
        XCTAssertFalse(element("working-folders-summary").exists, "Selected repositories already appear in the title and compact header labels.")
        _ = try runCLI(["settings", "set-appearance", "light"])
        XCTAssertTrue(waitUntil({ repositoryTitleHasColor(emptyTitle, appearance: "light") }, timeout: 5), "Light appearance should render an indigo repository title.")
        _ = try runCLI(["settings", "set-appearance", "dark"])
        XCTAssertTrue(waitUntil({ repositoryTitleHasColor(emptyTitle, appearance: "dark") }, timeout: 5), "Changing appearance should update the title color.")
        let title = element("task-view-title")
        XCTAssertTrue(title.waitForExistence(timeout: 5))
        XCTAssertGreaterThan(badge.frame.minX, title.frame.maxX, "Repository badges should appear to the right of the task title.")
        XCTAssertLessThan(abs(badge.frame.midY - title.frame.midY), 8, "Repository badges should share the title row.")
        let record = try XCTUnwrap(taskRecord(named: "Header repository picker"))
        let repositories = try XCTUnwrap(record["repositoryWorktrees"] as? [[String: Any]])
        let primary = try XCTUnwrap(repositories.first { ($0["repositoryPath"] as? String) == fixture.primary.path })
        let worktreePath = try XCTUnwrap(primary["worktreePath"] as? String)
        XCTAssertEqual(worktreePath, fixture.primary.path)
        XCTAssertEqual(primary["isPending"] as? Bool, true)
        XCTAssertEqual(primary["branch"] as? String, "auto")
        XCTAssertEqual(record["workspaceRoots"] as? [String], [fixture.primary.path])
        XCTAssertEqual(record["contextFolders"] as? [String], [])
        let branch = try XCTUnwrap(primary["branch"] as? String)
        let mergeFrom = try XCTUnwrap(primary["branchFrom"] as? String)
        let mergeTo = try XCTUnwrap(primary["mergeTarget"] as? String)
        badge.click()
        app.activate()
        let branchValue = element("conversation-repository-branch-value")
        let branchFromValue = element("conversation-repository-branch-from-value")
        let mergeTargetValue = element("conversation-repository-merge-target-value")
        XCTAssertTrue(branchValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(branchFromValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(mergeTargetValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: branchValue), branch, app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: branchFromValue), mergeFrom, app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: mergeTargetValue), mergeTo, app.debugDescription)
        XCTAssertTrue(app.staticTexts["Branch name"].exists)
        XCTAssertTrue(app.staticTexts["Branch from"].exists)
        XCTAssertTrue(app.staticTexts["Merge to"].exists)
        XCTAssertTrue(element("conversation-repository-branch-edit").exists)
        XCTAssertTrue(element("conversation-repository-branch-from-edit").exists)
        XCTAssertTrue(element("conversation-repository-merge-target-edit").exists)

        let apiReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var apiReservationReleased = false
        defer {
            if !apiReservationReleased { try? apiReservation.release() }
        }
        let apiAdded = try runCLI(["task", "repository", "add", taskID, "--repo", fixture.secondary.path])["result"] as? [String: Any]
        let apiRepositories = try XCTUnwrap(apiAdded?["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertEqual(apiRepositories.count, 2)
        let secondary = try XCTUnwrap(apiRepositories.first { ($0["repositoryPath"] as? String) == fixture.secondary.path })
        XCTAssertEqual(secondary["isPending"] as? Bool, false, "The AI-facing API should return an editable worktree.")
        let managedWorktree = try XCTUnwrap(secondary["worktreePath"] as? String)
        XCTAssertNotEqual(managedWorktree, fixture.secondary.path)
        XCTAssertTrue(managedWorktree.hasPrefix(dataDirectory.appendingPathComponent("task-worktrees", isDirectory: true).path))
        XCTAssertTrue(element("conversation-repository-badge-secondary").waitForExistence(timeout: 10), "Repository additions made through the AI API should appear in the open task header.")
        XCTAssertEqual(accessibleLabelOrValue(of: repositoryTitle()), "primary · secondary", "The prominent title should update when the API adds a repository.")
        XCTAssertFalse(element("working-folders-summary").exists, "Repository worktrees should not be repeated in a separate working-folders line.")
        let savedRepositories = try runCLI(["settings", "get"])["result"] as? [String: Any]
        XCTAssertEqual(savedRepositories?["lastSelectedRepositories"] as? [String], [fixture.primary.path, fixture.secondary.path])
        let replaced = try runCLI(["task", "repository", "replace", taskID, "--repo", fixture.secondary.path])["result"] as? [String: Any]
        XCTAssertEqual((replaced?["repositoryWorktrees"] as? [[String: Any]])?.compactMap { $0["repositoryPath"] as? String }, [fixture.secondary.path])
        XCTAssertTrue(element("conversation-repository-badge-secondary").exists)
        XCTAssertFalse(element("conversation-repository-badge-primary").exists, "API replacement should immediately remove the old repository badge.")
        XCTAssertEqual(accessibleLabelOrValue(of: repositoryTitle()), "secondary", "The title should track the active repository context.")
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String], [fixture.secondary.path])
        try apiReservation.release()
        apiReservationReleased = true

        let composer = element("message-composer")
        XCTAssertTrue(composer.waitForExistence(timeout: 5))
        composer.click()
        composer.typeText("Start working in the selected repositories.")
        element("send-message-button").click()
        let sentPrompt = app.textViews.matching(
            NSPredicate(format: "value == %@", "Start working in the selected repositories.")
        ).firstMatch
        XCTAssertTrue(sentPrompt.waitForExistence(timeout: 10))
        XCTAssertFalse(repositoryTitle().exists, "The prominent repository title should leave the timeline once the conversation has messages.")
        XCTAssertFalse(app.staticTexts["Start a conversation"].exists)
        let badgeAfterSend = element("conversation-repository-badge-secondary")
        XCTAssertTrue(badgeAfterSend.exists, "Compact repository badges should remain in the fixed task header after the timeline scrolls.")
        XCTAssertGreaterThan(badgeAfterSend.frame.minX, title.frame.maxX, "Repository badges should remain beside the task title after a message is sent.")
        XCTAssertLessThan(abs(badgeAfterSend.frame.midY - title.frame.midY), 8, "Repository badges should stay on the fixed title row after the timeline scrolls.")
    }

    // case-contract: test_task_repository_settings_validate_persist_and_lock_after_start | Pending repository branch, merge-from, and merge-to settings wait for an active conversation turn, then persist across fresh CLI/XPC reads; invalid settings leave prior values intact, and settings are locked after worktree creation. Each setting is edited in place: the pencil beside a value opens an inline field with a checkmark that saves only that field and keeps the editor open on the saved value, and clicking outside the field or pressing Escape dismisses the edit without saving. The settings popover is wider than before with a larger title, and the repository chip's remove button is a larger target.
    func test_task_repository_settings_validate_persist_and_lock_after_start() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        let title = "Repository settings through UI"
        let created = try runCLI([
            "task", "create", "--title", title, "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path,
        ])["result"] as? [String: Any]
        let taskID = try XCTUnwrap(created?["id"] as? String)
        openTask(named: title)
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 5))
        let removeBadgeButton = element("remove-conversation-repository-primary")
        XCTAssertGreaterThanOrEqual(removeBadgeButton.frame.width, 20, "The repository chip's remove button should be an easy target.")
        XCTAssertGreaterThanOrEqual(removeBadgeButton.frame.height, 20, "The repository chip's remove button should be an easy target.")
        attachScreenshot(named: "Repository chip with enlarged remove button", fullScreen: true)

        let initial = try XCTUnwrap(repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path))
        let initialBranch = try XCTUnwrap(initial["branch"] as? String)
        let initialBranchFrom = try XCTUnwrap(initial["branchFrom"] as? String)
        badge.click()
        let initialBranchValue = element("conversation-repository-branch-value")
        let branchEdit = element("conversation-repository-branch-edit")
        XCTAssertTrue(initialBranchValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(branchEdit.exists)
        let settingsTitle = element("conversation-repository-settings-title")
        XCTAssertGreaterThanOrEqual(app.popovers.firstMatch.frame.width, 340, "The repository settings popover should be roomier than before.")
        XCTAssertGreaterThanOrEqual(settingsTitle.frame.height, 17, "The repository settings title should use a larger font.")
        XCTAssertLessThan(branchEdit.frame.minX - initialBranchValue.frame.maxX, 6, "The edit pencil should sit right beside its value.")
        XCTAssertGreaterThanOrEqual(branchEdit.frame.width, 20, "The edit pencil should be an easy target.")
        XCTAssertFalse(element("save-conversation-repository-button").exists, "Per-field checkmarks replace the popover-wide Save button.")
        XCTAssertFalse(element("remove-conversation-repository-button").exists, "Removal moved from the popover to the repository chip badge.")
        attachScreenshot(named: "Repository settings popover with pencils beside each value", fullScreen: true)
        branchEdit.click()
        let branchField = element("conversation-repository-branch")
        let branchSave = element("conversation-repository-branch-save")
        XCTAssertTrue(branchField.waitForExistence(timeout: 5))
        XCTAssertTrue(branchSave.exists, "Editing a value should show a confirmation checkmark.")
        XCTAssertGreaterThan(branchSave.frame.minX, branchField.frame.minX, "The checkmark should sit inside the field's trailing edge.")
        XCTAssertLessThan(abs(branchSave.frame.midY - branchField.frame.midY), 6, "The checkmark should be inside the field.")
        XCTAssertFalse(element("conversation-repository-branch-from-save").exists, "Only the field being edited shows a checkmark.")
        replaceText(branchField, with: "invalid branch")
        attachScreenshot(named: "Inline branch edit with its confirmation checkmark", fullScreen: true)
        branchSave.click()
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 10), "Invalid branch settings should be shown in the conversation.")
        XCTAssertEqual(try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branch"] as? String, initialBranch)
        XCTAssertTrue(branchField.exists, "A rejected value should stay open for correction.")

        let conversationReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: taskID)
        var conversationReservationReleased = false
        defer {
            if !conversationReservationReleased { try? conversationReservation.release() }
        }
        replaceText(branchField, with: "conversation-edited")
        branchSave.click()
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(
            try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branch"] as? String,
            initialBranch,
            "Repository settings should remain unchanged while a conversation turn holds its reservation."
        )
        try conversationReservation.release()
        conversationReservationReleased = true
        XCTAssertTrue(waitForRepositoryValue(taskID: taskID, repositoryPath: fixture.primary.path, key: "branch", expected: "conversation-edited"))
        XCTAssertTrue(waitForDisappearance(branchField), "A confirmed value should leave edit mode.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("conversation-repository-branch-value")), "conversation-edited", "The editor should stay open on the saved value.")

        element("conversation-repository-branch-from-edit").click()
        let branchFromField = element("conversation-repository-branch-from")
        XCTAssertTrue(branchFromField.waitForExistence(timeout: 5))
        replaceText(branchFromField, with: "discarded-edit")
        settingsTitle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).click()
        XCTAssertTrue(waitForDisappearance(branchFromField), "Clicking outside the field should dismiss the edit.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("conversation-repository-branch-from-value")), initialBranchFrom, "A dismissed edit must not change the shown value.")
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branchFrom"] as? String, initialBranchFrom, "A dismissed edit must not be saved.")
        attachScreenshot(named: "Clicking outside the field dismisses the edit unsaved", fullScreen: true)

        element("conversation-repository-branch-from-edit").click()
        XCTAssertTrue(branchFromField.waitForExistence(timeout: 5))
        replaceText(branchFromField, with: "escaped-edit")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(waitForDisappearance(branchFromField), "Escape should dismiss the edit.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("conversation-repository-branch-from-value")), initialBranchFrom, "An escaped edit must not change the shown value.")
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branchFrom"] as? String, initialBranchFrom, "An escaped edit must not be saved.")
        attachScreenshot(named: "Escape dismisses the edit unsaved", fullScreen: true)

        element("conversation-repository-branch-from-edit").click()
        XCTAssertTrue(branchFromField.waitForExistence(timeout: 5))
        replaceText(branchFromField, with: "branch-source")
        element("conversation-repository-branch-from-save").click()
        XCTAssertTrue(waitForRepositoryValue(taskID: taskID, repositoryPath: fixture.primary.path, key: "branchFrom", expected: "branch-source"))
        XCTAssertEqual(try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branch"] as? String, "conversation-edited", "Saving one field must keep the others.")

        XCTAssertTrue(waitForDisappearance(branchFromField))
        element("conversation-repository-merge-target-edit").click()
        let mergeTargetField = element("conversation-repository-merge-target")
        let mergeTargetSave = element("conversation-repository-merge-target-save")
        XCTAssertTrue(mergeTargetField.waitForExistence(timeout: 5))
        replaceText(mergeTargetField, with: "branch-source")
        mergeTargetSave.click()
        XCTAssertTrue(waitForRepositoryValue(taskID: taskID, repositoryPath: fixture.primary.path, key: "mergeTarget", expected: "branch-source"))
        XCTAssertTrue(waitForDisappearance(mergeTargetField))
        element("conversation-repository-merge-target-edit").click()
        XCTAssertTrue(mergeTargetField.waitForExistence(timeout: 5))
        replaceText(mergeTargetField, with: "missing-local-branch")
        mergeTargetSave.click()
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 10), "An invalid merge target should be shown in the conversation.")
        XCTAssertEqual(
            try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["mergeTarget"] as? String,
            "branch-source",
            "Rejecting an invalid merge target must preserve the saved value."
        )
        replaceText(mergeTargetField, with: "branch-source")
        mergeTargetSave.click()
        XCTAssertTrue(waitForRepositoryValue(taskID: taskID, repositoryPath: fixture.primary.path, key: "mergeTarget", expected: "branch-source"))
        XCTAssertTrue(waitForDisappearance(mergeTargetField), "A successful save should leave edit mode.")
        attachScreenshot(named: "Saved repository settings stay visible in the open popover", fullScreen: true)
        // Reopen the popover so the values come from the saved record.
        element("task-view-title").coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).click()
        XCTAssertTrue(waitForDisappearance(element("conversation-repository-branch-value")), "Clicking outside the popover should close it.")
        badge.click()
        app.activate()
        let branchValue = element("conversation-repository-branch-value")
        let branchFromValue = element("conversation-repository-branch-from-value")
        let mergeTargetValue = element("conversation-repository-merge-target-value")
        XCTAssertTrue(branchValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(branchFromValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(mergeTargetValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: branchValue), "conversation-edited", app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: branchFromValue), "branch-source", app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: mergeTargetValue), "branch-source", app.debugDescription)
        XCTAssertEqual(try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["isPending"] as? Bool, true)

        try completeCurrentTaskWithFixtureAnswers(taskTitle: title)
        badge.click()
        XCTAssertTrue(element("conversation-repository-settings-locked").waitForExistence(timeout: 5))
        XCTAssertFalse(element("conversation-repository-branch-edit").exists)
        XCTAssertFalse(element("conversation-repository-branch-save").exists)
        assertCLIError(
            try runCLI([
                "task", "repository", "edit", taskID,
                "--repo", fixture.primary.path,
                "--branch", "changed-after-start",
                "--branch-from", "branch-source",
                "--merge-target", "branch-source",
            ], expectedStatus: 1),
            code: "invalid_transition"
        )
        let final = try XCTUnwrap(repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path))
        XCTAssertEqual(final["branch"] as? String, "conversation-edited")
        XCTAssertEqual(final["branchFrom"] as? String, "branch-source")
        XCTAssertEqual(final["mergeTarget"] as? String, "branch-source")
        XCTAssertEqual(final["isPending"] as? Bool, false)
    }

    // case-contract: test_task_repository_branch_from_fetches_remote_branch | A branch-from that exists only on a Git remote and was never fetched is fetched when repository settings are saved, and the pending record stores its remote-tracking branch; a branch-from missing locally and on every remote is rejected without changing the saved settings; a remote that can't be reached reports the fetch failure instead of a missing branch and also keeps the saved settings; starting the task creates its worktree from the fetched remote commit without making the remote branch the task branch's upstream.
    func test_task_repository_branch_from_fetches_remote_branch() throws {
        let remoteBranch = "remote-only/branch-from"
        let trackingRef = "refs/remotes/origin/\(remoteBranch)"
        let remote = runDirectory.appendingPathComponent("branch-from-origin.git", isDirectory: true)
        XCTAssertFalse(FileManager.default.fileExists(atPath: remote.path), "Each UI case should use a fresh owned bare remote.")
        try FileManager.default.createDirectory(at: remote, withIntermediateDirectories: true)
        try runGit(remote, "init", "--bare")
        let remoteCommit = try runGitOutput(
            fixture.primary, "commit-tree", "main^{tree}", "-p", "main", "-m", "Create remote-only branch-from fixture commit"
        ).trimmingCharacters(in: .whitespacesAndNewlines)
        try runGit(fixture.primary, "remote", "add", "origin", remote.path)
        addTeardownBlock { [self] in try? runGit(fixture.primary, "remote", "remove", "origin") }
        try runGit(fixture.primary, "push", "--quiet", "origin", "main", "\(remoteCommit):refs/heads/\(remoteBranch)")
        // Pushing records the remote-tracking ref; drop it so the branch exists only on the remote.
        try runGit(fixture.primary, "update-ref", "-d", trackingRef)
        let trackingRefs = try runGitOutput(fixture.primary, "for-each-ref", "--format=%(refname)", trackingRef)
        XCTAssertEqual(trackingRefs.trimmingCharacters(in: .whitespacesAndNewlines), "", "The remote branch must start unfetched.")

        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        let title = "Remote branch-from through UI"
        let created = try runCLI([
            "task", "create", "--title", title, "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path,
            "--merge-target", "\(fixture.primary.path)=main",
        ])["result"] as? [String: Any]
        let taskID = try XCTUnwrap(created?["id"] as? String)
        openTask(named: title)
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 5))

        badge.click()
        element("conversation-repository-branch-from-edit").click()
        let branchFromField = element("conversation-repository-branch-from")
        let branchFromSave = element("conversation-repository-branch-from-save")
        XCTAssertTrue(branchFromField.waitForExistence(timeout: 5))
        replaceText(branchFromField, with: remoteBranch)
        attachScreenshot(named: "Branch-from names a branch that exists only on the remote")
        branchFromSave.click()
        XCTAssertTrue(waitForRepositoryValue(taskID: taskID, repositoryPath: fixture.primary.path, key: "branchFrom", expected: "origin/\(remoteBranch)"))
        XCTAssertEqual(try runGitOutput(fixture.primary, "rev-parse", trackingRef).trimmingCharacters(in: .whitespacesAndNewlines), remoteCommit)
        let localBranches = try runGitOutput(fixture.primary, "for-each-ref", "--format=%(refname)", "refs/heads/\(remoteBranch)")
        XCTAssertEqual(localBranches.trimmingCharacters(in: .whitespacesAndNewlines), "", "Fetching must not create a local branch.")
        XCTAssertTrue(waitForDisappearance(branchFromField), "A successful save should leave edit mode.")

        let branchFromValue = element("conversation-repository-branch-from-value")
        XCTAssertTrue(branchFromValue.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertEqual(accessibleLabelOrValue(of: branchFromValue), "origin/\(remoteBranch)", app.debugDescription)
        attachScreenshot(named: "Remote branch-from is fetched and saved as its remote-tracking branch")

        element("conversation-repository-branch-from-edit").click()
        XCTAssertTrue(branchFromField.waitForExistence(timeout: 5))
        replaceText(branchFromField, with: "missing-everywhere/branch")
        branchFromSave.click()
        let error = element("codex-chat-error")
        XCTAssertTrue(error.waitForExistence(timeout: 10), "A branch-from missing locally and on the remote should be shown in the conversation.")
        XCTAssertTrue(error.label.contains("missing-everywhere/branch"), error.label)
        attachScreenshot(named: "Branch-from missing locally and on the remote is rejected")
        XCTAssertEqual(
            try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branchFrom"] as? String,
            "origin/\(remoteBranch)",
            "Rejecting a missing branch-from must preserve the saved value."
        )
        XCTAssertTrue(branchFromField.exists, "A rejected value should stay open for correction.")

        try runGit(fixture.primary, "remote", "set-url", "origin", runDirectory.appendingPathComponent("unreachable-origin.git").path)
        replaceText(branchFromField, with: "unfetched/branch")
        branchFromSave.click()
        XCTAssertTrue(
            waitUntil({ error.exists && error.label.contains("couldn't fetch 'unfetched/branch' from origin") }, timeout: 10),
            "A fetch failure should be reported as such, not as a missing branch: \(error.label)"
        )
        attachScreenshot(named: "Unreachable remote reports the fetch failure")
        try runGit(fixture.primary, "remote", "set-url", "origin", remote.path)
        XCTAssertEqual(
            try repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path)?["branchFrom"] as? String,
            "origin/\(remoteBranch)",
            "A failed fetch must preserve the saved value."
        )
        // Escape first cancels the open field edit (#173), then a second Escape closes the editor.
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(waitForDisappearance(branchFromField), "Escape should first cancel the open field edit.")
        XCTAssertTrue(branchFromValue.exists, "Cancelling the field edit should leave the editor open.")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(waitForDisappearance(branchFromValue), "Dismissing the editor should close it before the turn starts.")

        try completeCurrentTaskWithFixtureAnswers(taskTitle: title)
        let started = try XCTUnwrap(repositoryRecord(taskID: taskID, repositoryPath: fixture.primary.path))
        XCTAssertEqual(started["isPending"] as? Bool, false)
        XCTAssertEqual(started["branchFrom"] as? String, "origin/\(remoteBranch)")
        let worktree = URL(fileURLWithPath: try XCTUnwrap(started["worktreePath"] as? String), isDirectory: true)
        let taskBranch = try XCTUnwrap(started["branch"] as? String)
        XCTAssertEqual(try runGitOutput(worktree, "rev-parse", "HEAD").trimmingCharacters(in: .whitespacesAndNewlines), remoteCommit)
        let upstream = try runGitOutput(worktree, "config", "--default", "", "--get", "branch.\(taskBranch).remote")
        XCTAssertEqual(upstream.trimmingCharacters(in: .whitespacesAndNewlines), "", "The remote branch-from must not become the task branch's upstream.")
    }

    // case-contract: test_task_repository_edit_rejects_stale_validation_after_removal | If a pending repository is removed while its settings are being validated, the stale edit is rejected and the newer repository removal and context root remain saved.
    func test_task_repository_edit_rejects_stale_validation_after_removal() throws {
        // The window validates the edit with real Git; the staged wrapper parks that call
        // for this repository so the CLI removal can land first.
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: try makeGitHoldEnvironment())
        let title = "Concurrent repository edit"
        let created = try runCLI([
            "task", "create", "--title", title, "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path,
            "--root", fixture.custom.path,
        ])["result"] as? [String: Any]
        let taskID = try XCTUnwrap(created?["id"] as? String)
        openTask(named: title)
        let badge = element("conversation-repository-badge-primary")
        XCTAssertTrue(badge.waitForExistence(timeout: 5))
        badge.click()
        element("conversation-repository-branch-edit").click()
        replaceText(element("conversation-repository-branch"), with: "stale-ui-edit")

        let barrier = try GitHoldBarrier(repositoryURL: fixture.primary)
        element("conversation-repository-branch-save").click()
        var barrierReleased = false
        defer {
            if !barrierReleased { try? barrier.release() }
        }
        try barrier.waitForHeldCall()
        let removed = try runCLI(["task", "repository", "remove", taskID, "--repo", fixture.primary.path])
        let removedTask = try XCTUnwrap(removed["result"] as? [String: Any])
        XCTAssertEqual((removedTask["repositoryWorktrees"] as? [Any])?.count, 0)
        XCTAssertEqual(removedTask["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(removedTask["contextFolders"] as? [String], [fixture.custom.path])

        try barrier.release()
        barrierReleased = true
        let error = element("codex-chat-error")
        XCTAssertTrue(error.waitForExistence(timeout: 10), "The stale repository edit should be reported in the conversation.")
        XCTAssertTrue(error.label.localizedCaseInsensitiveContains("settings changed"), error.label)
        let fresh = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual((fresh["repositoryWorktrees"] as? [Any])?.count, 0)
        XCTAssertEqual(fresh["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(fresh["contextFolders"] as? [String], [fixture.custom.path])
        attachScreenshot(named: "Concurrent repository removal rejects a stale settings save")
    }

    // case-contract: test_task_repository_removal_preserves_state_on_dirty_worktree | Removing one of two pending repositories leaves the remaining repository in task context and remembered settings, while preserving the removed source repository; the next task restores only the remaining remembered repository. Removing a pending repository preserves other context folders; removing a clean managed worktree through the GUI waits for an active turn, while the task repository API removes it from context immediately and defers clean worktree deletion until the turn releases; a bridge service restart preserves the cleanup intent and a fresh request completes removal; if the active turn writes files before release, deferred cleanup preserves that worktree and its changes; a dirty worktree rejects removal and preserves its task record and files.
    func test_task_repository_removal_preserves_state_on_dirty_worktree() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)

        let soleTitle = "Two repository removal through UI"
        let sole = try runCLI(["task", "create", "--title", soleTitle, "--prompt", "Fixture task description.", "--repo", fixture.primary.path, "--repo", fixture.secondary.path])["result"] as? [String: Any]
        let soleID = try XCTUnwrap(sole?["id"] as? String)
        openTask(named: soleTitle)
        element("remove-conversation-repository-primary").click()
        XCTAssertTrue(waitUntil({
            guard let result = try? self.taskRecord(id: soleID),
                  let records = result["repositoryWorktrees"] as? [[String: Any]] else { return false }
            return records.count == 1 && records[0]["repositoryPath"] as? String == self.fixture.secondary.path
        }, timeout: 10), "Removing one pending repository should preserve the other attachment.")
        XCTAssertEqual(try taskRecord(id: soleID)?["workspaceRoots"] as? [String], [fixture.secondary.path])
        XCTAssertTrue(FileManager.default.fileExists(atPath: fixture.primary.path))
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String], [fixture.secondary.path])

        element("back-to-board-button").click()
        element("new-task-button").click()
        let restoredTitle = element("empty-conversation-repository-title")
        XCTAssertTrue(restoredTitle.waitForExistence(timeout: 5), "A new task should restore the remaining remembered repository.")
        XCTAssertEqual(accessibleLabelOrValue(of: restoredTitle), "secondary")
        XCTAssertTrue(element("conversation-repository-badge-secondary").exists)
        XCTAssertFalse(element("conversation-repository-badge-primary").exists)
        attachScreenshot(named: "New task restores only the repository that remains selected")

        element("back-to-board-button").click()
        let pendingTitle = "Pending repository removal through UI"
        let pending = try runCLI([
            "task", "create", "--title", pendingTitle, "--prompt", "Fixture task description.",
            "--repo", fixture.primary.path,
            "--root", fixture.custom.path,
        ])["result"] as? [String: Any]
        let pendingID = try XCTUnwrap(pending?["id"] as? String)
        openTask(named: pendingTitle)
        element("remove-conversation-repository-primary").click()
        XCTAssertTrue(waitUntil({
            guard let result = try? self.taskRecord(id: pendingID),
                  let records = result["repositoryWorktrees"] as? [[String: Any]] else { return false }
            return records.isEmpty
        }, timeout: 10), "Removing a pending repository should update the persisted task.")
        let pendingAfterRemoval = try XCTUnwrap(taskRecord(id: pendingID))
        XCTAssertEqual(pendingAfterRemoval["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(pendingAfterRemoval["contextFolders"] as? [String], [fixture.custom.path])
        XCTAssertTrue(FileManager.default.fileExists(atPath: fixture.primary.path), "The source repository must remain on disk.")

        element("back-to-board-button").click()
        let cleanTitle = "Clean active repository removal through API"
        let cleanActive = try runCLI([
            "task", "create", "--title", cleanTitle, "--prompt", "Fixture task description.",
            "--repo", fixture.alternate.path,
            "--root", fixture.custom.path,
        ])["result"] as? [String: Any]
        let cleanActiveID = try XCTUnwrap(cleanActive?["id"] as? String)
        openTask(named: cleanTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: cleanTitle)
        let cleanRecord = try XCTUnwrap(repositoryRecord(taskID: cleanActiveID, repositoryPath: fixture.alternate.path))
        let cleanWorktreePath = try XCTUnwrap(cleanRecord["worktreePath"] as? String)
        let cleanReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: cleanActiveID)
        var cleanReservationReleased = false
        defer {
            if !cleanReservationReleased { try? cleanReservation.release() }
        }
        _ = try runCLI(["task", "repository", "remove", cleanActiveID, "--repo", fixture.alternate.path])
        XCTAssertTrue(FileManager.default.fileExists(atPath: cleanWorktreePath))
        let cleanupScheduled = try XCTUnwrap(diagnosticEvents().first {
            $0["event"] as? String == "workspace.repository.deferred_removal_scheduled"
                && $0["taskID"] as? String == cleanActiveID
        })
        let bridgePIDText = try XCTUnwrap(cleanupScheduled["processID"] as? String)
        let bridgePID = pid_t(try XCTUnwrap(Int32(bridgePIDText)))
        if kill(bridgePID, SIGKILL) != 0 {
            XCTAssertEqual(errno, ESRCH, "The bridge service should either be killed here or already have exited.")
        }
        XCTAssertTrue(waitUntil({ kill(bridgePID, 0) != 0 && errno == ESRCH }, timeout: 5), "The isolated bridge service should exit before recovery is tested.")
        try cleanReservation.release()
        cleanReservationReleased = true
        _ = try taskRecord(id: cleanActiveID)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: cleanWorktreePath) }, timeout: 10),
                      "Deferred cleanup should remove an unchanged managed worktree after the turn releases.")

        element("back-to-board-button").click()
        let activeTitle = "Started repository removal through UI"
        let active = try runCLI([
            "task", "create", "--title", activeTitle, "--prompt", "Fixture task description.",
            "--repo", fixture.secondary.path,
            "--root", fixture.custom.path,
        ])["result"] as? [String: Any]
        let activeID = try XCTUnwrap(active?["id"] as? String)
        openTask(named: activeTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: activeTitle)
        let activeRecord = try XCTUnwrap(repositoryRecord(taskID: activeID, repositoryPath: fixture.secondary.path))
        let worktreePath = try XCTUnwrap(activeRecord["worktreePath"] as? String)
        let worktreeURL = URL(fileURLWithPath: worktreePath, isDirectory: true)
        let dirtyFile = worktreeURL.appendingPathComponent("repository-removal-dirty.txt")
        try Data("keep this worktree intact\n".utf8).write(to: dirtyFile)

        let removeButton = element("remove-conversation-repository-secondary")
        removeButton.click()
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 10), "Dirty worktree removal should report an error in the conversation.")
        XCTAssertTrue(element("codex-chat-error").label.contains("uncommitted changes"))
        XCTAssertEqual(try repositoryRecord(taskID: activeID, repositoryPath: fixture.secondary.path)?["worktreePath"] as? String, worktreePath)
        XCTAssertTrue(FileManager.default.fileExists(atPath: dirtyFile.path))

        try FileManager.default.removeItem(at: dirtyFile)
        XCTAssertTrue(removeButton.waitForExistence(timeout: 5), "The repository can be removed after its worktree is clean.")
        let conversationReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: activeID)
        var conversationReservationReleased = false
        defer {
            if !conversationReservationReleased { try? conversationReservation.release() }
        }
        removeButton.click()
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertNil(
            try repositoryRecord(taskID: activeID, repositoryPath: fixture.secondary.path),
            "Active-conversation removal should detach the repository immediately while deferring worktree cleanup."
        )
        XCTAssertTrue(FileManager.default.fileExists(atPath: worktreePath))
        let inFlightURL = worktreeURL.appendingPathComponent("written-during-removal.txt")
        try Data("preserve edits made before the turn ended\n".utf8).write(to: inFlightURL)
        try conversationReservation.release()
        conversationReservationReleased = true
        XCTAssertTrue(waitUntil({
            guard let result = try? self.taskRecord(id: activeID),
                  let records = result["repositoryWorktrees"] as? [[String: Any]] else { return false }
            return records.isEmpty
        }, timeout: 10), "Repository removal should update the persisted task.")
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains {
                $0["event"] as? String == "workspace.repository.deferred_removal_kept_dirty"
                    && $0["taskID"] as? String == activeID
            }) ?? false
        }, timeout: 10), "Deferred cleanup should report that active-turn edits were preserved.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: inFlightURL.path), "Deferred cleanup must preserve active-turn edits.")
        let activeAfterRemoval = try XCTUnwrap(taskRecord(id: activeID))
        XCTAssertEqual(activeAfterRemoval["workspaceRoots"] as? [String], [fixture.custom.path])
        XCTAssertEqual(activeAfterRemoval["contextFolders"] as? [String], [fixture.custom.path])
        XCTAssertTrue(FileManager.default.fileExists(atPath: worktreePath), "Deferred cleanup must preserve the worktree containing active-turn edits.")

        element("back-to-board-button").click()
        let apiTitle = "Active API repository removal through UI"
        let apiTask = try runCLI(["task", "create", "--title", apiTitle, "--prompt", "Fixture task description.", "--repo", fixture.primary.path])["result"] as? [String: Any]
        let apiTaskID = try XCTUnwrap(apiTask?["id"] as? String)
        openTask(named: apiTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: apiTitle)
        let apiRecord = try XCTUnwrap(repositoryRecord(taskID: apiTaskID, repositoryPath: fixture.primary.path))
        let apiWorktreePath = try XCTUnwrap(apiRecord["worktreePath"] as? String)
        let apiReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: apiTaskID)
        var apiReservationReleased = false
        defer {
            if !apiReservationReleased { try? apiReservation.release() }
        }
        let removed = try runCLI(["task", "repository", "remove", apiTaskID, "--repo", fixture.primary.path])["result"] as? [String: Any]
        XCTAssertEqual((removed?["repositoryWorktrees"] as? [Any])?.count, 0)
        XCTAssertFalse(element("conversation-repository-badge-primary").exists, "API removal should immediately update the visible repository badges.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: apiWorktreePath), "The active turn worktree must remain until its reservation releases.")
        try apiReservation.release()
        apiReservationReleased = true
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: apiWorktreePath) }, timeout: 10), "API removal should clean up the worktree after the active reservation releases.")
    }

    // case-contract: test_task_delete_removes_task_and_later_lookup_is_not_found | The task context menu offers deletion. Pending repository tasks delete without confirmation and preserve the source repository; confirmed deletion waits for an active conversation turn; clean started worktrees can be deleted; dirty started worktrees require confirmation, and canceling preserves the task and worktree. CLI delete-check derives and reports the confirmation requirement from saved task and worktree state without resuming the Codex thread; confirmed deletion removes the managed worktree. Deleting a task also removes its per-task preferences and any left by already-deleted tasks, while another task's preferences remain.
    func test_task_delete_removes_task_and_later_lookup_is_not_found() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        // Left by a task deleted before per-task preference cleanup existed.
        let orphanedPreference = "playhouse.codex.goal-generation.\(UUID().uuidString)"
        try PropertyListSerialization.data(fromPropertyList: [orphanedPreference: "plan"], format: .binary, options: 0)
            .write(to: isolatedPreferencesFile)
        launchApp(defaultParent: fixture.parent.path)

        let pendingTitle = "Pending delete"
        _ = try runCLI(["task", "create", "--title", pendingTitle, "--prompt", "Pending delete description.", "--repo", fixture.secondary.path])
        let pendingTask = try XCTUnwrap(taskRecord(named: pendingTitle))
        let pendingID = try XCTUnwrap(pendingTask["id"] as? String)
        let pendingRecord = try XCTUnwrap((pendingTask["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(pendingRecord["isPending"] as? Bool, true)
        XCTAssertEqual(pendingRecord["worktreePath"] as? String, fixture.secondary.path)
        let promptedCheck = try runCLI(["task", "delete-check", pendingID])
        XCTAssertEqual((promptedCheck["result"] as? [String: Any])?["requiresConfirmation"] as? Bool, true, "A task with a saved prompt holds user content, so deleting it must confirm.")
        _ = try runCLI(["task", "prompt", pendingID, "--text", ""])
        let pendingCheck = try runCLI(["task", "delete-check", pendingID])
        XCTAssertEqual((pendingCheck["result"] as? [String: Any])?["requiresConfirmation"] as? Bool, false)
        let keptTitle = "Kept preferences"
        try createTaskFixture(title: keptTitle, roots: [fixture.custom.path])
        let keptID = try taskID(named: keptTitle)
        let pendingPreference = "conversationMode.\(pendingID.uppercased())"
        let keptPreference = "conversationMode.\(keptID.uppercased())"
        for title in [pendingTitle, keptTitle] {
            openTask(named: title)
            let modeMenu = element("conversation-mode-menu")
            XCTAssertTrue(modeMenu.waitForExistence(timeout: 10))
            modeMenu.click()
            app.menuItems["Plan mode"].click()
            XCTAssertTrue(modeMenu.label.contains("Plan mode"))
            element("back-to-board-button").click()
        }
        XCTAssertTrue(waitUntil({
            self.isolatedPreferenceKeys().isSuperset(of: [pendingPreference, keptPreference, orphanedPreference])
        }, timeout: 10), "Choosing a conversation mode should save it in the isolated preferences.")
        deleteTaskFromContextMenu(pendingTitle)
        XCTAssertTrue(element("confirm-delete-task-button").waitForExistence(timeout: 5))
        let conversationReservation = try ConversationTurnLockBarrier(dataDirectory: dataDirectory, taskID: pendingID)
        var conversationReservationReleased = false
        defer {
            if !conversationReservationReleased { try? conversationReservation.release() }
        }
        element("confirm-delete-task-button").click()
        Thread.sleep(forTimeInterval: 0.25)
        XCTAssertEqual(try taskRecord(id: pendingID)?["id"] as? String, pendingID)
        try conversationReservation.release()
        conversationReservationReleased = true
        var pendingDeleteEvent: [String: Any]?
        XCTAssertTrue(waitUntil({
            guard let events = try? self.diagnosticEvents() else { return false }
            pendingDeleteEvent = events.first {
                $0["event"] as? String == "task.delete.succeeded" && $0["taskID"] as? String == pendingID
            }
            return pendingDeleteEvent != nil
        }, timeout: 5), "Deleting a task through the visible menu should leave a persistent diagnostic event.")
        let pendingDeleteEventValue = try XCTUnwrap(pendingDeleteEvent)
        XCTAssertEqual(pendingDeleteEventValue["taskStatus"] as? String, "Backlog")
        XCTAssertNotNil(pendingDeleteEventValue["processID"] as? String)
        XCTAssertNotNil(pendingDeleteEventValue["storePath"] as? String)
        assertCLIError(try runCLI(["task", "get", pendingID], expectedStatus: 3), code: "not_found")
        XCTAssertTrue(FileManager.default.fileExists(atPath: fixture.secondary.path), "Deleting a pending task must preserve its source repository.")
        XCTAssertTrue(waitUntil({
            let keys = self.isolatedPreferenceKeys()
            return !keys.contains(pendingPreference) && !keys.contains(orphanedPreference)
        }, timeout: 10), "Deleting a task must remove its preferences and those left by already-deleted tasks.")
        XCTAssertTrue(isolatedPreferenceKeys().contains(keptPreference), "Another task's preferences must survive a delete.")
        XCTAssertEqual((try runCLI(["task", "delete", keptID])["result"] as? [String: Any])?["deleted"] as? Bool, true)
        XCTAssertTrue(waitUntil({ !self.isolatedPreferenceKeys().contains(keptPreference) }, timeout: 10))

        let cleanTitle = "Clean delete \(String(UUID().uuidString.prefix(8)).lowercased())"
        _ = try runCLI(["task", "create", "--title", cleanTitle, "--prompt", "Fixture task description.", "--repo", fixture.primary.path])
        openTask(named: cleanTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: cleanTitle)
        element("back-to-board-button").click()
        let cleanTask = try XCTUnwrap(taskRecord(named: cleanTitle))
        let cleanID = try XCTUnwrap(cleanTask["id"] as? String)
        let cleanRecord = try XCTUnwrap((cleanTask["repositoryWorktrees"] as? [[String: Any]])?.first)
        let cleanPath = try XCTUnwrap(cleanRecord["worktreePath"] as? String)
        XCTAssertEqual(cleanRecord["isPending"] as? Bool, false)
        XCTAssertTrue(FileManager.default.fileExists(atPath: cleanPath))
        XCTAssertEqual(try runGitOutput(URL(fileURLWithPath: cleanPath), "status", "--porcelain").trimmingCharacters(in: .whitespacesAndNewlines), "")
        let cleanThreadID = try XCTUnwrap(cleanTask["codexThreadID"] as? String)
        let resumeEventsBeforeDeleteCheck = try diagnosticEvents().filter {
            $0["event"] as? String == "codex.thread.resume_started" && $0["threadID"] as? String == cleanThreadID
        }.count
        let cleanCheck = try runCLI(["task", "delete-check", cleanID])
        XCTAssertEqual((cleanCheck["result"] as? [String: Any])?["requiresConfirmation"] as? Bool, true)
        let resumeEventsAfterDeleteCheck = try diagnosticEvents().filter {
            $0["event"] as? String == "codex.thread.resume_started" && $0["threadID"] as? String == cleanThreadID
        }.count
        XCTAssertEqual(resumeEventsAfterDeleteCheck, resumeEventsBeforeDeleteCheck, "Delete-check must not resume a conversation thread already owned by the app.")
        deleteTaskFromContextMenu(cleanTitle)
        let cleanConfirmation = element("confirm-delete-task-button")
        XCTAssertTrue(cleanConfirmation.waitForExistence(timeout: 5))
        cleanConfirmation.click()
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains {
                $0["event"] as? String == "task.delete.succeeded" && $0["taskID"] as? String == cleanID
            }) ?? false
        }, timeout: 20), "The app should finish the confirmed delete and record success before the worktree check.")
        assertCLIError(try runCLI(["task", "get", cleanID], expectedStatus: 3), code: "not_found")
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: cleanPath) }, timeout: 10), "Deleting a clean started task must remove its managed worktree before the task record disappears.")

        let dirtyTitle = "Dirty delete \(String(UUID().uuidString.prefix(8)).lowercased())"
        _ = try runCLI(["task", "create", "--title", dirtyTitle, "--prompt", "Fixture task description.", "--repo", fixture.primary.path])
        let dirtyID = try taskID(named: dirtyTitle)
        openTask(named: dirtyTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: dirtyTitle, prompt: "Prepare a task for deletion.")
        XCTAssertEqual(try taskRecord(id: dirtyID)?["status"] as? String, "Review")
        element("back-to-board-button").click()
        let dirtyTask = try XCTUnwrap(taskRecord(id: dirtyID))
        let dirtyRecord = try XCTUnwrap((dirtyTask["repositoryWorktrees"] as? [[String: Any]])?.first)
        let dirtyPath = try XCTUnwrap(dirtyRecord["worktreePath"] as? String)
        XCTAssertTrue(FileManager.default.fileExists(atPath: dirtyPath))
        try "unsaved work\n".write(to: URL(fileURLWithPath: dirtyPath).appendingPathComponent("trash-test.txt"), atomically: true, encoding: .utf8)
        let dirtyCheck = try runCLI(["task", "delete-check", dirtyID])
        XCTAssertEqual((dirtyCheck["result"] as? [String: Any])?["requiresConfirmation"] as? Bool, true)

        deleteTaskFromContextMenu(dirtyTitle)
        let cancel = element("cancel-delete-task-button")
        XCTAssertTrue(cancel.waitForExistence(timeout: 5), "Dirty work dropped on trash must require confirmation.")
        cancel.click()
        XCTAssertTrue(app.buttons[dirtyTitle].exists, "Canceling deletion must preserve the task.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: dirtyPath), "Canceling deletion must preserve the worktree.")

        deleteTaskFromContextMenu(dirtyTitle)
        let confirmation = element("confirm-delete-task-button")
        XCTAssertTrue(confirmation.waitForExistence(timeout: 5))
        confirmation.click()
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains {
                $0["event"] as? String == "task.delete.succeeded" && $0["taskID"] as? String == dirtyID
            }) ?? false
        }, timeout: 20), "The app should finish the confirmed delete and record success before the worktree check.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: dirtyPath), "Confirmed deletion must remove the dirty managed worktree.")
        assertCLIError(try runCLI(["task", "get", dirtyID], expectedStatus: 3), code: "not_found")
        XCTAssertEqual(try tasksFromBoardList().count, 0)
        attachScreenshot(named: "Deleted task removed from the board")
    }

    // case-contract: test_task_delete_reports_real_worktree_failure_and_allows_retry | A real worktree-removal failure records the task title and task, thread, process, phase, and underlying error details, including bounded NSError user-info keys and values, without recording conversation text; the failed task and worktree remain available and deletion succeeds after the repository is restored.
    func test_task_delete_reports_real_worktree_failure_and_allows_retry() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)

        let brokenRepository = dataDirectory.appendingPathComponent("delete-failure-repository", isDirectory: true)
        try FileManager.default.createDirectory(at: brokenRepository, withIntermediateDirectories: true)
        try runGit(brokenRepository, "init", "--initial-branch=main")
        try runGit(brokenRepository, "config", "user.name", "Playhouse UI Test")
        try runGit(brokenRepository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try "owned diagnostic fixture\n".write(
            to: brokenRepository.appendingPathComponent("README.md"), atomically: true, encoding: .utf8
        )
        try runGit(brokenRepository, "add", "README.md")
        try runGit(brokenRepository, "commit", "-m", "Baseline")
        let failureTitle = "PRIVATE_DELETE_TITLE_\(String(UUID().uuidString.prefix(8)))"
        let failurePrompt = "PRIVATE_CONVERSATION_TEXT_\(String(UUID().uuidString.prefix(8)))"
        _ = try runCLI(["task", "create", "--title", failureTitle, "--prompt", "Fixture task description.", "--repo", brokenRepository.path])
        openTask(named: failureTitle)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: failureTitle, prompt: failurePrompt)
        element("back-to-board-button").click()
        let failureTask = try XCTUnwrap(taskRecord(named: failureTitle))
        let failureID = try XCTUnwrap(failureTask["id"] as? String)
        let failureRecord = try XCTUnwrap((failureTask["repositoryWorktrees"] as? [[String: Any]])?.first)
        let failureWorktree = try XCTUnwrap(failureRecord["worktreePath"] as? String)
        let movedRepository = dataDirectory.appendingPathComponent("delete-failure-repository-restored-after-error", isDirectory: true)
        try FileManager.default.moveItem(at: brokenRepository, to: movedRepository)
        deleteTaskFromContextMenu(failureTitle)
        XCTAssertTrue(element("confirm-delete-task-button").waitForExistence(timeout: 5))
        element("confirm-delete-task-button").click()
        let saveErrorAlert = app.sheets.firstMatch
        XCTAssertTrue(saveErrorAlert.waitForExistence(timeout: 10), "A worktree-removal failure should be visible to the user.")
        XCTAssertTrue(element(containingAccessibilityText: "Diagnostics.jsonl").waitForExistence(timeout: 5), app.debugDescription)
        let failureLog = try String(contentsOf: dataDirectory.appendingPathComponent("Diagnostics.jsonl"), encoding: .utf8)
        let failureEvents = try failureLog.split(whereSeparator: \.isNewline).compactMap {
            try JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any]
        }
        let failedDelete = try XCTUnwrap(failureEvents.first {
            $0["event"] as? String == "task.delete.failed" && $0["taskID"] as? String == failureID
        })
        XCTAssertEqual(failedDelete["phase"] as? String, "worktree-removal")
        XCTAssertEqual(failedDelete["taskStatus"] as? String, "Review")
        XCTAssertTrue((failedDelete["threadID"] as? String)?.isEmpty == false)
        XCTAssertNotNil(failedDelete["clientPID"] as? String)
        XCTAssertNotNil(failedDelete["codexPID"] as? String)
        XCTAssertNotNil(failedDelete["error0Domain"] as? String)
        XCTAssertNotNil(failedDelete["error0Code"] as? String)
        XCTAssertNotNil(failedDelete["error0UserInfoKeys"] as? String)
        XCTAssertNotNil(failedDelete["error0UserInfoKeyCount"] as? String)
        XCTAssertNotNil(failedDelete["error0UserInfo"] as? String)
        XCTAssertTrue(failureLog.contains(failureTitle), "Diagnostics should record the task title to help identify the affected task.")
        XCTAssertFalse(failureLog.contains(failurePrompt), "Diagnostics must not record conversation text.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: failureWorktree), "A failed deletion must preserve the worktree for retry.")
        XCTAssertEqual(try taskRecord(id: failureID)?["id"] as? String, failureID, "A failed deletion must preserve the task for retry.")
        saveErrorAlert.buttons["OK"].click()
        try FileManager.default.moveItem(at: movedRepository, to: brokenRepository)
        deleteTaskFromContextMenu(failureTitle)
        XCTAssertTrue(element("confirm-delete-task-button").waitForExistence(timeout: 5))
        element("confirm-delete-task-button").click()
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains {
                $0["event"] as? String == "task.delete.succeeded" && $0["taskID"] as? String == failureID
            }) ?? false
        }, timeout: 20), "Restoring the repository should allow the retry to complete and record success.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: failureWorktree), "Restoring the repository should allow deletion to be retried.")
        assertCLIError(try runCLI(["task", "get", failureID], expectedStatus: 3), code: "not_found")
        XCTAssertEqual(try tasksFromBoardList().count, 0)
        attachScreenshot(named: "Failed task deletion can be retried after repository recovery")
    }

    // case-contract: test_default_parent_settings_read_write_clear_and_validation | The default parent can be read, changed, cleared, and an unavailable path is rejected; a fresh CLI read and repository discovery use the persisted parent. Dark and Light appearance choices persist, the removed PR conflict preference is absent from CLI/XPC and Settings, and appearance changes update the open Settings picker. Clearing the default parent does not change roots already saved on a task.
    func test_default_parent_settings_read_write_clear_and_validation() throws {
        launchApp(defaultParent: nil)
        let initialSettings = try runCLI(["settings", "get"])["result"] as? [String: Any]
        XCTAssertNil(initialSettings?["defaultParentFolder"] as? String)
        openNewTaskConversation()
        XCTAssertEqual(try tasksFromBoardList().count, 1, "New Task should create its pending conversation before folder discovery.")
        XCTAssertTrue(element("repository-root-required-notice").exists)
        XCTAssertFalse(element("send-message-button").isEnabled)
        element("set-conversation-repository-root-button").click()
        let firstRunPanel = openFolderPanel
        XCTAssertTrue(firstRunPanel.waitForExistence(timeout: 10))
        firstRunPanel.buttons["Cancel"].click()
        XCTAssertFalse(element("conversation-repository-search").exists, "Canceling root setup should leave the direct-created task and picker closed.")
        XCTAssertEqual(try tasksFromBoardList().count, 1)

        element("set-conversation-repository-root-button").click()
        try chooseFolder(in: openFolderPanel, folder: fixture.parent, confirmationButton: "Use This Folder")
        XCTAssertFalse(element("repository-root-required-notice").exists)
        XCTAssertFalse(element("conversation-repository-search").exists, "Setting the root should leave the repo picker closed.")
        element("add-conversation-repository-button").click()
        XCTAssertTrue(element("conversation-repository-suggestion-primary").waitForExistence(timeout: 10), "Choosing a suggestion folder should populate the conversation picker.")
        let parentVisibleToBridge = waitUntil({
            guard let response = try? self.runCLI(["settings", "get"]),
                  let settings = response["result"] as? [String: Any] else { return false }
            return (settings["defaultParentFolder"] as? String) == self.fixture.parent.path
        }, timeout: 5)
        XCTAssertTrue(parentVisibleToBridge, "The selected parent folder should be visible through a fresh CLI/XPC read.")
        let changeSuggestionParent = element("choose-repository-suggestion-parent-button")
        XCTAssertTrue(changeSuggestionParent.waitForExistence(timeout: 5), "The picker should keep a Change parent action available after a valid parent has been selected.")
        XCTAssertTrue(changeSuggestionParent.label.localizedCaseInsensitiveContains("Change"))
        changeSuggestionParent.click()
        try chooseFolder(in: openFolderPanel, folder: fixture.alternateParent, confirmationButton: "Use This Folder")
        XCTAssertTrue(element("conversation-repository-suggestion-alternate").waitForExistence(timeout: 10), "Changing the parent should refresh the repository suggestions.")
        XCTAssertFalse(element("conversation-repository-suggestion-primary").exists, "Suggestions from the previous parent should be replaced.")
        XCTAssertTrue(waitUntil({
            guard let response = try? self.runCLI(["settings", "get"]),
                  let settings = response["result"] as? [String: Any] else { return false }
            return (settings["defaultParentFolder"] as? String) == self.fixture.alternateParent.path
        }, timeout: 5), "The changed parent folder should be visible through a fresh CLI/XPC read.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        XCTAssertEqual(try tasksFromBoardList().count, 0, "Backing out should discard the empty pending conversation.")

        app.typeKey(",", modifierFlags: .command)
        let preferencesWindow = settingsWindow
        XCTAssertTrue(preferencesWindow.waitForExistence(timeout: 10), "Workspace Settings did not open.")
        let appearancePicker = preferencesWindow.descendants(matching: .any)
            .matching(identifier: "appearance-picker").firstMatch
        XCTAssertTrue(appearancePicker.waitForExistence(timeout: 5), "Workspace Settings should expose the Dark and Light theme choices.")
        XCTAssertFalse(preferencesWindow.descendants(matching: .any).matching(identifier: "pr-conflict-action-picker").firstMatch.exists, "Workspace Settings should no longer expose automatic PR conflict behavior.")
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["appearance"] as? String, "dark")
        appearancePicker.click()
        let lightChoice = preferencesWindow.menuItems["Light"]
        if lightChoice.waitForExistence(timeout: 2) {
            lightChoice.click()
        } else {
            preferencesWindow.buttons["Light"].click()
        }
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["appearance"] as? String, "light")
        _ = try runCLI(["settings", "set-appearance", "dark"])
        // The pop-up button reports its visible title ("Dark") as its value.
        XCTAssertTrue(waitUntil({ (appearancePicker.value as? String)?.lowercased() == "dark" }, timeout: 5), "An external CLI write should update the open appearance picker.")
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["appearance"] as? String, "dark")
        app.typeKey("w", modifierFlags: .command)
        XCTAssertTrue(waitUntil({ !preferencesWindow.exists }, timeout: 5), "Settings should close before checking the workspace canvas.")
        let workspaceCanvas = element("board-columns-scroll-view")
        XCTAssertTrue(workspaceCanvas.waitForExistence(timeout: 5), "The board workspace should be visible.")
        assertPixel(workspaceCanvas.screenshot().image, normalizedX: 0.02, normalizedY: 0.5, rgb: (30, 30, 30), accuracy: 20)
        app.typeKey(",", modifierFlags: .command)
        let reopenedPreferences = settingsWindow
        XCTAssertTrue(reopenedPreferences.waitForExistence(timeout: 10), "Workspace Settings did not reopen.")
        let chooseParent = reopenedPreferences.descendants(matching: .any)
            .matching(identifier: "choose-default-parent-folder-button").firstMatch
        XCTAssertTrue(chooseParent.waitForExistence(timeout: 10))
        chooseParent.click()
        try chooseFolder(in: openFolderPanel, folder: fixture.parent, confirmationButton: "Use This Folder")
        assertText("default-parent-folder-path", equals: fixture.parent.path)
        let saved = try runCLI(["settings", "get"])["result"] as? [String: Any]
        XCTAssertEqual(saved?["defaultParentFolder"] as? String, fixture.parent.path)

        assertCLIError(
            try runCLI(["settings", "set-parent", fixture.missing.path], expectedStatus: 2),
            code: "invalid_argument"
        )
        assertText("default-parent-folder-path", equals: fixture.parent.path)
        try createTaskFixture(title: "Roots survive settings", roots: [fixture.primary.path, fixture.secondary.path])
        reopenedPreferences.descendants(matching: .any)
            .matching(identifier: "clear-default-parent-folder-button").firstMatch.click()
        let cleared = try runCLI(["settings", "get"])["result"] as? [String: Any]
        XCTAssertNil(cleared?["defaultParentFolder"] as? String)
        assertText("default-parent-folder-path", equals: "No default parent folder selected")
        attachScreenshot(named: "Workspace settings can be changed and cleared")
        app.typeKey("w", modifierFlags: .command)
        XCTAssertTrue(waitUntil({ !reopenedPreferences.exists }, timeout: 5), "Settings should close before the next UI case launches.")
        XCTAssertTrue(element("board-title").exists, "The main board should remain open when Settings closes.")
        // Roots already saved on a task survive clearing the default parent.
        openTask(named: "Roots survive settings")
        assertOrderedRoots([fixture.primary.path, fixture.secondary.path])
        let roots = try runCLI(["task", "roots", "get", try taskID(named: "Roots survive settings")])["result"] as? [String: Any]
        XCTAssertEqual(roots?["roots"] as? [String], [fixture.primary.path, fixture.secondary.path])
        element("back-to-board-button").click()
    }

    // case-contract: test_repository_suggestions_skip_nested_repositories_and_symlinks | The configured-root workspace repos list API returns top-level Git repositories while excluding nested repositories and symlink targets. The conversation picker shows those suggestions, filters by repository name or parent path, and reports no matches for non-repository folders.
    func test_repository_suggestions_skip_nested_repositories_and_symlinks() throws {
        launchApp(defaultParent: fixture.parent.path)
        let configuredRoot = fixture.parent
        _ = try runCLI(["settings", "set-parent", configuredRoot.path])
        let listed = try runCLI(["workspace", "repos", "list"])["result"] as? [String: Any]
        let expectedRepositories = [fixture.primary.path, fixture.secondary.path, fixture.alternate.path, fixture.changes.path].sorted()
        XCTAssertEqual(listed?["root"] as? String, configuredRoot.path)
        XCTAssertEqual(listed?["repositories"] as? [String], expectedRepositories)
        XCTAssertFalse((listed?["repositories"] as? [String] ?? []).contains(fixture.nested.path))
        XCTAssertFalse((listed?["repositories"] as? [String] ?? []).contains(fixture.linkedOutside.path))

        let result = try runCLI(["workspace", "suggest", "--parent", fixture.parent.path])["result"] as? [String: Any]
        XCTAssertEqual(result?["repositories"] as? [String], expectedRepositories)

        openNewTaskConversation()
        element("add-conversation-repository-button").click()
        let search = element("conversation-repository-search")
        XCTAssertTrue(element("conversation-repository-suggestion-primary").waitForExistence(timeout: 10))
        XCTAssertFalse(element("conversation-repository-suggestion-nested").exists, "Nested Git folders should not be suggested.")
        XCTAssertFalse(element("conversation-repository-suggestion-linked-outside").exists, "Symlink targets should not be suggested.")
        replaceText(search, with: "primary")
        XCTAssertTrue(element("conversation-repository-suggestion-primary").waitForExistence(timeout: 10))
        XCTAssertFalse(element("conversation-repository-suggestion-secondary").exists, "Search should filter suggestions by repository name.")
        replaceText(search, with: "linked-outside")
        XCTAssertTrue(app.staticTexts["No matching repositories."].waitForExistence(timeout: 5))
        replaceText(search, with: "group")
        XCTAssertTrue(element("conversation-repository-suggestion-secondary").waitForExistence(timeout: 5), "A path-only query should find a repository inside a matching parent folder.")
        XCTAssertFalse(element("conversation-repository-suggestion-primary").exists)
        replaceText(search, with: "changes")
        XCTAssertTrue(element("conversation-repository-suggestion-changes").exists)
        element("back-to-board-button").click()
        assertScreenshotIfVisible(named: "Repository suggestions exclude nested and symlinked folders")
    }

    // case-contract: test_new_task_remembers_last_selected_repositories | The CLI reads and writes ordered last-selected repositories across fresh XPC connections; repository batches prepare managed worktrees in order, use task-title-derived branches and main/main merge settings, and set the active task roots to those worktrees. The selected source repository list remains saved and applies to subsequent tasks. Invalid repository paths are rejected without changing the saved preference. In the UI, a new conversation automatically attaches saved repositories in order while the picker stays closed and the composer remains focused. Opening the picker and choosing another suggestion adds it to the ordered context and saved selection for subsequent conversations. Each saved selection also feeds a newest-first recent repository history of up to twenty repositories that keeps repositories after they are removed from the selection; the task repository recent command lists those that still exist and are not attached to the task, and rejects an unknown task. In the UI, attached repositories appear as large chips carrying a remove badge and the header shows no suggestion chips; removing a repository through its badge makes the add-repository picker list it under Recent before anything is typed, clicking it adds it back to the task and saved selection, and typing a query replaces the recent list with the regular search suggestions.
    func test_new_task_remembers_last_selected_repositories() throws {
        launchApp(defaultParent: fixture.parent.path)
        _ = try runCLI(["settings", "set-last-repositories", "--repo", fixture.secondary.path, "--repo", fixture.primary.path])

        openNewTaskConversation()
        XCTAssertFalse(element("conversation-repository-search").exists, "Saved repositories should apply without opening the picker.")
        XCTAssertTrue(element("conversation-repository-badge-secondary").waitForExistence(timeout: 10))
        XCTAssertTrue(element("conversation-repository-badge-primary").waitForExistence(timeout: 10))
        let firstTask = try XCTUnwrap(tasksFromBoardList().first)
        let firstTaskID = try XCTUnwrap(firstTask["id"] as? String)
        let firstRoots = try XCTUnwrap(firstTask["workspaceRoots"] as? [String])
        let firstRepositories = try XCTUnwrap(firstTask["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertEqual(firstRoots, [fixture.secondary.path, fixture.primary.path])
        XCTAssertEqual(firstRepositories.map { $0["repositoryPath"] as? String }, [fixture.secondary.path, fixture.primary.path])
        XCTAssertEqual(firstRepositories.map { $0["branch"] as? String }, ["auto", "auto"])
        XCTAssertEqual(firstRepositories.map { $0["branchFrom"] as? String }, ["main", "main"])
        XCTAssertEqual(firstRepositories.map { $0["mergeTarget"] as? String }, ["main", "main"])
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String], [fixture.secondary.path, fixture.primary.path])
        element("back-to-board-button").click()
        assertCLIError(try runCLI(["task", "get", firstTaskID], expectedStatus: 3), code: "not_found")

        openNewTaskConversation()
        XCTAssertTrue(element("conversation-repository-badge-secondary").waitForExistence(timeout: 10))
        XCTAssertTrue(element("conversation-repository-badge-primary").exists)
        element("add-conversation-repository-button").click()
        let overrideSearch = element("conversation-repository-search")
        XCTAssertTrue(overrideSearch.waitForExistence(timeout: 5))
        replaceText(overrideSearch, with: "alternate")
        XCTAssertTrue(element("conversation-repository-suggestion-alternate").waitForExistence(timeout: 10))
        overrideSearch.typeKey(.downArrow, modifierFlags: [])
        overrideSearch.typeKey(.return, modifierFlags: [])
        XCTAssertTrue(element("conversation-repository-badge-alternate").waitForExistence(timeout: 10))
        let expandedSelection = [fixture.secondary.path, fixture.primary.path, fixture.alternate.path]
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String], expandedSelection)

        let quickAddTaskID = try XCTUnwrap(tasksFromBoardList().first?["id"] as? String)
        let alternateBadge = element("conversation-repository-badge-alternate")
        let primaryBadge = element("conversation-repository-badge-primary")
        let alternateRemove = element("remove-conversation-repository-alternate")
        XCTAssertFalse(element("conversation-recent-repositories").exists, "The header should not show recent suggestion chips.")
        XCTAssertTrue(alternateRemove.exists, "Each attached repository chip should carry its own remove badge.")
        XCTAssertGreaterThanOrEqual(alternateBadge.frame.height, 28, "Attached repository chips should be prominent.")
        // #173 enlarged the badge to a 20 pt target; it is still a corner badge, not a full button.
        XCTAssertGreaterThanOrEqual(alternateRemove.frame.width, 20, "The remove badge should be an easy target.")
        XCTAssertLessThanOrEqual(alternateRemove.frame.width, 22, "The remove badge should stay a small corner badge.")
        XCTAssertGreaterThan(alternateRemove.frame.midX, alternateBadge.frame.midX, "The remove badge should sit on the chip's trailing corner.")
        XCTAssertLessThan(alternateRemove.frame.midY, alternateBadge.frame.midY, "The remove badge should sit on the chip's top corner.")
        attachScreenshot(named: "Attached repositories as large chips with remove badges")
        alternateRemove.click()
        XCTAssertTrue(waitForDisappearance(alternateBadge, timeout: 10), "The remove badge should detach the repository.")
        element("remove-conversation-repository-primary").click()
        XCTAssertTrue(waitForDisappearance(primaryBadge, timeout: 10))
        XCTAssertFalse(element("conversation-recent-repositories").exists, "Removed repositories should not reappear as header chips.")
        XCTAssertEqual((try runCLI(["settings", "get"])["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String], [fixture.secondary.path])
        XCTAssertEqual(
            (try runCLI(["task", "repository", "recent", quickAddTaskID])["result"] as? [String: Any])?["repositories"] as? [String],
            [fixture.primary.path, fixture.alternate.path]
        )

        element("add-conversation-repository-button").click()
        let recentSearch = element("conversation-repository-search")
        XCTAssertTrue(recentSearch.waitForExistence(timeout: 5))
        let recentHeader = element("conversation-repository-recent-header")
        let recentPrimary = element("conversation-repository-recent-primary")
        let recentAlternate = element("conversation-repository-recent-alternate")
        XCTAssertTrue(recentHeader.waitForExistence(timeout: 5), "Before typing, the picker should list recent repositories.")
        XCTAssertTrue(recentPrimary.exists)
        XCTAssertTrue(recentAlternate.exists)
        XCTAssertLessThan(recentPrimary.frame.minY, recentAlternate.frame.minY, "Recent repositories should be ordered newest first.")
        XCTAssertFalse(element("conversation-repository-recent-secondary").exists, "An attached repository is not offered again.")
        XCTAssertFalse(element("conversation-repository-suggestion-changes").exists, "The search suggestions wait until something is typed.")
        attachScreenshot(named: "Add repository picker lists recent repositories before typing", fullScreen: true)
        replaceText(recentSearch, with: "alt")
        XCTAssertTrue(element("conversation-repository-suggestion-alternate").waitForExistence(timeout: 5), "Typing should switch to the regular search suggestions.")
        XCTAssertFalse(recentHeader.exists, "Typing should replace the recent list.")
        XCTAssertFalse(recentAlternate.exists)
        attachScreenshot(named: "Typing switches the picker to search suggestions", fullScreen: true)
        recentSearch.typeKey("a", modifierFlags: .command)
        recentSearch.typeKey(XCUIKeyboardKey.delete.rawValue, modifierFlags: [])
        XCTAssertTrue(recentPrimary.waitForExistence(timeout: 5), "Clearing the search should bring the recent list back.")
        recentPrimary.click()
        XCTAssertTrue(primaryBadge.waitForExistence(timeout: 10), "Clicking a recent repository should add it immediately.")
        XCTAssertTrue(waitForDisappearance(recentSearch), "Adding a recent repository should close the picker.")
        element("add-conversation-repository-button").click()
        XCTAssertTrue(recentAlternate.waitForExistence(timeout: 5))
        XCTAssertFalse(recentPrimary.exists, "A re-added repository leaves the recent list.")
        recentAlternate.click()
        XCTAssertTrue(alternateBadge.waitForExistence(timeout: 10), "Clicking a recent repository should add it immediately.")
        attachScreenshot(named: "Recent repositories re-added as attached chips")
        // The badge appears before the saved selection is written, so wait for the write.
        XCTAssertTrue(waitUntil({
            ((try? self.runCLI(["settings", "get"]))?["result"] as? [String: Any])?["lastSelectedRepositories"] as? [String] == expandedSelection
        }, timeout: 10), "Re-adding recent repositories should restore the saved selection order.")
        XCTAssertEqual(try XCTUnwrap(tasksFromBoardList().first?["workspaceRoots"] as? [String]), expandedSelection)
        element("back-to-board-button").click()

        openNewTaskConversation()
        XCTAssertFalse(element("conversation-repository-search").exists)
        XCTAssertTrue(element("conversation-repository-badge-secondary").waitForExistence(timeout: 10))
        XCTAssertTrue(element("conversation-repository-badge-primary").exists)
        XCTAssertTrue(element("conversation-repository-badge-alternate").waitForExistence(timeout: 10))
        XCTAssertEqual(try XCTUnwrap(tasksFromBoardList().first?["workspaceRoots"] as? [String]), expandedSelection)
        element("back-to-board-button").click()
        assertScreenshotIfVisible(named: "New conversation restores and remembers repository choices")
    }

    // case-contract: test_new_task_repository_restore_is_atomic_on_invalid_default | Applying an ordered repository batch with a valid repository followed by an empty Git repository fails without mutation: the CLI reports invalid_argument and fresh reads show no repository attachments or workspace roots; New Task automatically applies saved repositories; an invalid batch shows an error, attaches neither repository, keeps roots empty, preserves the saved order, and leaves the picker closed by default.
    func test_new_task_repository_restore_is_atomic_on_invalid_default() throws {
        launchApp(defaultParent: fixture.parent.path)
        let savedDefaults = [fixture.primary.path, fixture.emptyGitRepository.path]
        let preferenceUpdate = try runCLI([
            "settings", "set-last-repositories",
            "--repo", savedDefaults[0],
            "--repo", savedDefaults[1],
        ])
        XCTAssertEqual(preferenceUpdate["ok"] as? Bool, true)

        openNewTaskConversation()
        let search = element("conversation-repository-search")
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 10), "The failed saved-repository batch should display an error.")
        XCTAssertFalse(search.exists, "A failed default restore should not open the repository picker.")
        XCTAssertFalse(element("conversation-repository-badge-primary").exists, "The first valid repository must not remain attached after the batch fails.")
        XCTAssertFalse(element("conversation-repository-badge-empty-git-repo").exists)

        let task = try XCTUnwrap(tasksFromBoardList().first, "New Task should create its empty conversation before restoring repositories.")
        let taskID = try XCTUnwrap(task["id"] as? String)
        let freshTask = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(freshTask["workspaceRoots"] as? [String], [], "The failed batch must leave the task without roots.")
        XCTAssertEqual((freshTask["repositoryWorktrees"] as? [[String: Any]])?.count, 0, "The failed batch must leave the task without repository attachments.")
        let settings = try runCLI(["settings", "get"])["result"] as? [String: Any]
        XCTAssertEqual(settings?["lastSelectedRepositories"] as? [String], savedDefaults, "A failed restore must preserve the user's ordered repository defaults.")

        element("back-to-board-button").click()
        assertScreenshotIfVisible(named: "Failed repository restore leaves the empty new conversation unchanged")
    }

    // case-contract: test_new_task_has_empty_conversation_history | The CLI creates an Untitled task with no roots, logs task.create.succeeded for its ID, verifies empty history, and deletes it cleanly. New Task logs start and completion events with the same attempt ID and created task ID, then opens one empty conversation with the repository picker closed, the composer focused, and no create sheet. With no selected repositories, the empty conversation prominently says no repository is selected; typing starts immediately and, with a configured repository root, the UI enables standalone Send. Adding folder-only context leaves history empty, and backing out deletes the pending task without confirmation.
    func test_new_task_has_empty_conversation_history() throws {
        launchApp(defaultParent: fixture.parent.path)
        openNewTaskConversation()
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains { $0["event"] as? String == "ui.new_task.started" }) ?? false
        }, timeout: 2), "The New Task start event should reach the diagnostics file promptly after the click.")
        XCTAssertEqual(app.windows.count, 1, "New Task should open one conversation window.")
        XCTAssertTrue(element("empty-conversation").waitForExistence(timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: repositoryTitle()), "No repository selected")
        let repositorySearch = element("conversation-repository-search")
        XCTAssertFalse(repositorySearch.exists, "The new conversation should keep the repository picker closed by default.")
        let composer = element("message-composer")
        XCTAssertTrue(composer.waitForExistence(timeout: 10))
        composer.typeText("Standalone draft")
        XCTAssertEqual(composer.value as? String, "Standalone draft", "The composer should receive typing immediately.")
        XCTAssertFalse(element("create-task-button").exists, "Direct task creation should not present a create sheet.")
        XCTAssertFalse(element("workspace-repository-search").exists, "The sheet repository search should not appear.")
        XCTAssertTrue(element("send-message-button").isEnabled, "A configured root allows a standalone message even when no repository is selected.")
        let shell = try XCTUnwrap(tasksFromBoardList().first)
        XCTAssertTrue((shell["workspaceRoots"] as? [String] ?? []).isEmpty, "New Task should persist an empty pending task before repository selection.")
        let shellID = try XCTUnwrap(shell["id"] as? String)

        _ = try runCLI(["task", "roots", "set", shellID, "--root", fixture.custom.path])
        XCTAssertTrue(element("empty-conversation").waitForExistence(timeout: 10))
        XCTAssertTrue(app.staticTexts["Untitled task"].exists, "An empty conversation should keep its untitled title until the first prompt is added.")
        XCTAssertFalse(element("task-title-generating-loader").exists, "Title generation should not start before the first prompt.")
        XCTAssertFalse(element("pause-response-button").exists)
        XCTAssertFalse(element("continue-response-button").exists)

        let createdTask = try XCTUnwrap(tasksFromBoardList().first)
        let createdTaskID = try XCTUnwrap(createdTask["id"] as? String)
        let newTaskEvents = try diagnosticEvents().filter {
            ["ui.new_task.started", "ui.new_task.succeeded"].contains($0["event"] as? String ?? "")
        }
        let newTaskStarted = try XCTUnwrap(newTaskEvents.first { $0["event"] as? String == "ui.new_task.started" })
        let newTaskSucceeded = try XCTUnwrap(newTaskEvents.first { $0["event"] as? String == "ui.new_task.succeeded" })
        let successAttemptID = try XCTUnwrap(newTaskStarted["attemptID"] as? String)
        XCTAssertFalse(successAttemptID.isEmpty)
        XCTAssertEqual(newTaskSucceeded["attemptID"] as? String, successAttemptID)
        XCTAssertEqual(newTaskSucceeded["taskID"] as? String, createdTaskID)
        XCTAssertNotNil(newTaskSucceeded["durationMilliseconds"] as? String)
        XCTAssertEqual(createdTask["contextFolders"] as? [String], [fixture.custom.path])
        XCTAssertEqual(createdTask["workspaceRoots"] as? [String], [fixture.custom.path])
        let history = try runCLI(["conversation", "history", createdTaskID])["result"] as? [String: Any]
        XCTAssertEqual((history?["activities"] as? [Any])?.count, 0)
        XCTAssertEqual((history?["messages"] as? [Any])?.count, 0)
        XCTAssertNil(history?["diff"])

        // A typed draft keeps the task; back out of an empty pending conversation.
        composer.typeKey("a", modifierFlags: .command)
        composer.typeKey(.delete, modifierFlags: [])
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        XCTAssertFalse(element("confirm-discard-empty-task-button").exists, "An empty new conversation should return to the board without a discard confirmation.")
        let deleted = try runCLI(["task", "get", createdTaskID], expectedStatus: 3)
        XCTAssertEqual((deleted["error"] as? [String: Any])?["code"] as? String, "not_found")
        attachScreenshot(named: "New conversation shows its empty state")
    }

    // case-contract: test_new_task_failure_diagnostics | A real directory at the task-store write-lock path makes CLI task creation fail with operation_failed and leaves no task persisted; the paired New Task button shows the save error and writes correlated start and failure diagnostics with the same attempt ID, error domain, and code.
    func test_new_task_failure_diagnostics() throws {
        launchApp(defaultParent: fixture.parent.path)
        let writeLock = dataDirectory.appendingPathComponent("store-write.lock", isDirectory: true)
        let missingLockTarget = dataDirectory.appendingPathComponent("missing-lock-parent/store-write.lock")
        try FileManager.default.createSymbolicLink(at: writeLock, withDestinationURL: missingLockTarget)

        element("new-task-button").click()
        let saveAlert = app.sheets.matching(NSPredicate(format: "label == %@", "alert")).firstMatch
        XCTAssertTrue(saveAlert.waitForExistence(timeout: 10), "A real store-lock open failure should be shown to the user.")
        let alertTitle = saveAlert.staticTexts.matching(
            NSPredicate(format: "value == %@", "Couldn't save changes")
        ).firstMatch
        XCTAssertTrue(alertTitle.exists, "The store-lock failure sheet should identify the failed save.")
        let alertMessage = saveAlert.staticTexts.matching(
            NSPredicate(format: "value BEGINSWITH %@", "Couldn't open the")
        ).firstMatch
        XCTAssertTrue(alertMessage.exists, "The store-lock failure sheet should explain the real lock-open error.")
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains { $0["event"] as? String == "ui.new_task.failed" }) ?? false
        }, timeout: 2), "The New Task failure should reach the diagnostics file promptly.")
        let events = try diagnosticEvents()
        let failure = try XCTUnwrap(events.last { $0["event"] as? String == "ui.new_task.failed" })
        let starts = events.filter { $0["event"] as? String == "ui.new_task.started" }
        let start = try XCTUnwrap(starts.last)
        let failureAttemptID = try XCTUnwrap(start["attemptID"] as? String)
        XCTAssertFalse(failureAttemptID.isEmpty)
        XCTAssertEqual(failure["attemptID"] as? String, failureAttemptID)
        XCTAssertFalse((failure["errorDomain"] as? String ?? "").isEmpty)
        XCTAssertFalse((failure["errorCode"] as? String ?? "").isEmpty)
        XCTAssertNotNil(failure["durationMilliseconds"] as? String)

        saveAlert.buttons["OK"].click()
        try FileManager.default.removeItem(at: writeLock)
        XCTAssertTrue(try tasksFromBoardList().isEmpty, "A failed create must not leave a persisted task.")
    }

    // case-contract: test_standalone_chat_legacy_hidden_task_migrates | A standalone chat left in the store as a hidden board task is converted once into its own model: it keeps its ID so the existing conversation transcript stays attached, keeps its provider session, carries its in-flight turn state across with the status message and progress report that explain it, is removed from the board so it never lists or resolves as a task, and reopening the chat returns that same migrated chat rather than creating a second one.
    func test_standalone_chat_legacy_hidden_task_migrates() throws {
        let legacyID = try seedLegacyStandaloneChatTask()
        launchApp(defaultParent: fixture.parent.path)

        // The board renders from its own SwiftData query, so this is where a leftover hidden
        // task would actually surface as a card.
        XCTAssertFalse(
            element("task-card-\(legacyID)").waitForExistence(timeout: 3),
            "A chat migrated off the board must not render as a card."
        )
        XCTAssertTrue(try tasksFromBoardList().isEmpty, "The migrated chat must no longer be a board task.")
        assertCLIError(try runCLI(["task", "get", legacyID], expectedStatus: 3), code: "not_found")

        let opened = try runCLI(["chat", "open"])["result"] as? [String: Any]
        XCTAssertEqual(
            opened?["id"] as? String, legacyID,
            "The migrated chat must keep its ID so its existing transcript stays attached."
        )
        XCTAssertEqual(opened?["claudeSessionID"] as? String, "legacy-chat-session", "The chat's provider session must survive migration.")
        // The turn state must arrive with its explanation, not just the raw status.
        XCTAssertEqual(opened?["status"] as? String, "In Progress")
        XCTAssertEqual(opened?["statusMessage"] as? String, "Carried from the legacy chat task.")
        XCTAssertEqual(opened?["progressType"] as? String, "searching")
        XCTAssertEqual(opened?["progressLabel"] as? String, "Searching")
        XCTAssertEqual(opened?["progressDetail"] as? String, "Looking into volcanoes")

        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10), "The migrated chat should still open in the sidebar.")
        attachScreenshot(named: "Migrated standalone chat")

        let reopened = try runCLI(["chat", "open"])["result"] as? [String: Any]
        XCTAssertEqual(reopened?["id"] as? String, legacyID, "Migration must run once, not create a second chat.")
    }

    // case-contract: test_standalone_chat_separate_model_and_pages_round_trip | The Chat button opens the standalone chat — its own model rather than a board task — in a sliding sidebar that never appears on the board, task commands cannot reach it by ID, and the bridge rejects any attempt to add a repository or worktree root to it. The GUI composer works without a configured repository parent and omits task status, repository controls, the Changes sidebar, and the no-repository-selected banner. Its CLI page close-turn signal keeps a continuing reply on the active page and starts a new titled page on a topic change, a completed turn's user and assistant messages persist onto the active page without leaking onto other pages, and pages are findable by search. Each page is also stored in a separate atomic JSON file in a discoverable archive directory; pages already present before file archiving are backfilled once, and each file tracks current metadata and messages. A turn that omits close-turn is tracked as missed, then a background low-effort Luna fallback rejects one malformed classification and retries, moves both messages to its correctly titled page, keeps page evaluation visually quiet while the primary answer remains usable, then updates the transcript separator with the title when classification completes; a following send waits for that decision, and preserves chronological order on a later append. An explicit page start during a pending fallback cancels its stale result, keeps the missed turn on its original page, and clears the warning. If all helper results are invalid, the pending decision remains durable, blocks the next provider send, and retries after the helper recovers; the UI keeps the unresolved state visually quiet and sends successfully once recovery completes. Earlier pages stay visible in the transcript after their page session rotates, and a board task conversation rejects a chat page as turn context. While a chat turn is held active, queuing a follow-up on the chat resolves the chat rather than a board task and the queued message can be removed, and selecting the provider the chat already uses returns the chat unchanged instead of failing. The chat's own turn state changes (In Progress, then Waiting Response) during a send, and it never renders as a card on the visible Kanban board in any state. A chat turn never triggers the private task-outcome reminders, because the chat is told not to report an outcome; its developer instructions teach it that task language means Playhouse's own board and give it the Playhouse task CLI, and they never ask it to write the page title into its visible answer. Opening a board task while the chat sidebar is showing replaces it with that task's conversation view instead of showing both at once, and returning to the board reveals the chat sidebar again, with the chat's own model left untouched by the unrelated task. The visible chat panel opens at full board-content height, overlaps the logo header and narrow board sidebar, and hides the covered branding and sidebar controls from accessibility navigation while open; it raises the board's minimum width by the chat panel width, so the window grows to keep the shifted columns visible; it pushes the columns to the panel’s right edge; closing chat reveals the sidebar and moves the columns back beside it while the window keeps its grown width. Dragging the chat sidebar's right border resizes it, between a 320-point minimum and the larger of its default width and the screen width the board's minimum width leaves free, and reopening the sidebar, even after an app relaunch, keeps the dragged width. The border's grab strip extends only out over the board, never over the transcript's scroller along its inner side, so pressing and dragging just inside the border leaves the width unchanged. While the edge moves, the chat keeps the width it was last laid out at, clipped to the panel, and its transcript reflows to the panel's width when the drag ends.
    func test_standalone_chat_separate_model_and_pages_round_trip() throws {
        let fixtureSource = WorkspaceFixture.root.appendingPathComponent("codex-fixture-success")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: fixtureSource.path), "The prepared Codex fixture is missing or not executable.")
        // The `.hold-release` marker holds the one turn that needs it; a `-hold-release` name
        // would hold every later turn too, including the GUI send the classifier waits on.
        let chatFixtureExecutable = dataDirectory.appendingPathComponent("codex-fixture-chat-unique-turns-success")
        try FileManager.default.copyItem(at: fixtureSource, to: chatFixtureExecutable)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: chatFixtureExecutable.path)
        // Without the owner marker the app ignores this copy and falls back to the installed Codex CLI.
        try Data("Playhouse test owns this Codex protocol fixture (v1).\n".utf8)
            .write(to: dataDirectory.appendingPathComponent(".playhouse-codex-fixture-owner"))
        codexFixtureExecutable = chatFixtureExecutable.path
        launchApp(defaultParent: fixture.parent.path)
        XCTAssertTrue(element("chat-sidebar-button").exists, "The board header should offer a Chat button next to New Task.")
        XCTAssertFalse(element("chat-sidebar").exists, "The chat sidebar should be closed by default.")

        let boardHeader = element(withAccessibilityLabel: "Kanban header")
        let boardSidebar = element(withAccessibilityLabel: "Kanban sidebar")
        let backlogColumn = element("column-backlog")
        let reviewColumn = element("column-review")
        let mainWindow = app.windows.firstMatch
        let windowFrameBeforeOpeningChat = mainWindow.frame
        let headerFrameBeforeOpeningChat = boardHeader.frame
        let sidebarFrameBeforeOpeningChat = boardSidebar.frame
        let backlogColumnFrameBeforeOpeningChat = backlogColumn.frame

        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10), "Clicking Chat should slide in the sidebar.")
        XCTAssertTrue(
            waitUntil({ mainWindow.frame.width > windowFrameBeforeOpeningChat.width + 1 }, timeout: 5),
            "Opening chat should grow the window to fit the columns beside the chat."
        )
        XCTAssertTrue(reviewColumn.waitForExistence(timeout: 5), "The rightmost review column should remain present after the window grows.")
        let columnsViewport = element("board-columns-scroll-view")
        // Read the geometry once the slide-in and window growth have settled.
        XCTAssertTrue(
            waitUntil({
                let review = reviewColumn.frame
                let viewport = columnsViewport.frame
                return review.width >= 260 && review.minX >= viewport.minX
                    && review.maxX <= viewport.maxX && review.maxX <= mainWindow.frame.maxX
            }, timeout: 5),
            "Growing the window should keep the rightmost board column fully inside the board viewport and window."
        )
        let chatFrame = element("chat-sidebar").frame
        XCTAssertLessThanOrEqual(chatFrame.minY, headerFrameBeforeOpeningChat.minY, "The full-height chat panel should begin at the top of the logo header.")
        XCTAssertEqual(chatFrame.maxY, sidebarFrameBeforeOpeningChat.maxY, accuracy: 1, "The chat panel should extend to the bottom of the board content.")
        XCTAssertFalse(element(withAccessibilityLabel: "Kanban sidebar").exists, "The covered board sidebar should not remain in accessibility navigation while chat is open.")
        XCTAssertFalse(app.images["Playhouse logo"].exists, "The covered logo should not remain in accessibility navigation while chat is open.")
        XCTAssertTrue(chatFrame.contains(sidebarFrameBeforeOpeningChat), "The open chat panel should cover the board sidebar.")
        XCTAssertGreaterThan(
            backlogColumn.frame.minX,
            backlogColumnFrameBeforeOpeningChat.minX,
            "Opening chat should push the board columns to the right."
        )
        XCTAssertGreaterThanOrEqual(
            backlogColumn.frame.minX,
            chatFrame.maxX,
            "The board columns should begin at or to the right of the chat panel."
        )
        let backlogColumnFrameWhileChatOpen = backlogColumn.frame
        let reviewColumnFrame = reviewColumn.frame
        let columnsViewportFrame = columnsViewport.frame
        XCTAssertGreaterThanOrEqual(reviewColumnFrame.width, 260, "The review column should be fully visible rather than clipped by the scroll viewport.")
        XCTAssertGreaterThanOrEqual(reviewColumnFrame.minX, columnsViewportFrame.minX, "The review column should begin within the board viewport.")
        XCTAssertLessThanOrEqual(reviewColumnFrame.maxX, columnsViewportFrame.maxX, "The review column should end within the board viewport.")
        XCTAssertLessThanOrEqual(
            reviewColumnFrame.maxX,
            mainWindow.frame.maxX,
            "Growing the window should keep the rightmost board column inside the visible window."
        )
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 10), "The sidebar should reuse the standard chat composer.")
        XCTAssertFalse(element("task-status-message").exists, "Standalone chat must not show task status.")
        XCTAssertFalse(app.staticTexts["Backlog"].exists, "Standalone chat must not show a board status label.")
        XCTAssertFalse(element("conversation-repository-search").exists, "Standalone chat must not show repository controls.")
        XCTAssertFalse(element("add-conversation-repository-button").exists, "Standalone chat must not expose Add repository.")
        XCTAssertEqual(app.buttons.matching(NSPredicate(format: "identifier BEGINSWITH %@", "conversation-repository-badge-")).count, 0, "Standalone chat must not show repository badges.")
        XCTAssertFalse(element("workspace-changes-list").exists, "Standalone chat must not mount the task Changes sidebar.")
        XCTAssertFalse(element("workspace-changes-empty").exists, "Standalone chat must not show task workspace changes.")
        // Anchor on the rendered placeholder first: while history loads neither it nor the
        // title exists, so an unanchored absence check would pass even without the fix.
        XCTAssertTrue(element("empty-conversation").waitForExistence(timeout: 10), "The standalone chat should show its empty-conversation placeholder.")
        XCTAssertTrue(element("model-prompt").exists, "The placeholder should keep its send-a-message prompt.")
        XCTAssertFalse(element("empty-conversation-repository-title").exists, "Standalone chat must not show the no-repository-selected banner.")
        attachScreenshot(named: "Standalone chat sidebar opened")

        // Dragging the sidebar's right border resizes it, within limits, and the width is remembered.
        let chatSidebar = element("chat-sidebar")
        let chatHandle = element("chat-sidebar-resize-handle")
        XCTAssertTrue(chatHandle.waitForExistence(timeout: 5))
        // The handle's grab strip starts at the sidebar's 1-point border and extends out over the board.
        let chatWidth = { chatHandle.frame.minX + 1 - chatSidebar.frame.minX }
        XCTAssertEqual(chatWidth(), 460, accuracy: 2, "The resize handle is the sidebar's right border.")
        let chatWidthBefore = chatWidth()
        // The transcript's scroller runs along the border's inner side, so the grab strip must not reach inside the
        // chat: pressing there and dragging leaves the width alone (and the pointer is not a resize pointer).
        let chatTranscript = chatSidebar.descendants(matching: .any).matching(identifier: "conversation-scroll-view").firstMatch
        XCTAssertTrue(chatTranscript.exists, "The chat transcript should be present beside its resize border.")
        XCTAssertGreaterThanOrEqual(chatHandle.frame.minX, chatTranscript.frame.maxX - 1, "The resize strip must not overlap the transcript's scroller: handle=\(chatHandle.frame), transcript=\(chatTranscript.frame)")
        let insideBorder = chatHandle.coordinate(withNormalizedOffset: CGVector(dx: 0, dy: 0.5)).withOffset(CGVector(dx: -5, dy: 0))
        insideBorder.press(forDuration: 0.2, thenDragTo: insideBorder.withOffset(CGVector(dx: -60, dy: 0)))
        XCTAssertFalse(waitUntil({ abs(chatWidth() - chatWidthBefore) > 1 }, timeout: 0.5), "Dragging over the transcript's scroller must not resize the chat: \(chatWidth())")
        // While the edge moves, the chat keeps the width it was last laid out at and the panel clips it; once a drag
        // ends, the transcript must have reflowed to the panel, ending the same distance from the border as before.
        let transcriptGapToBorder = { chatHandle.frame.minX + 1 - chatTranscript.frame.maxX }
        let restingTranscriptGap = transcriptGapToBorder()
        let chatContentFillsPanel = { chatTranscript.exists && abs(transcriptGapToBorder() - restingTranscriptGap) <= 2 }
        attachScreenshot(named: "Standalone chat keeps its width after a drag over the transcript scroller")
        let chatHandleCenter = { chatHandle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)) }
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: -60, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(chatWidth() - (chatWidthBefore - 60)) <= 6 }, timeout: 5), "Dragging left narrows the chat: \(chatWidth())")
        let chatNarrowed = chatWidth()
        attachScreenshot(named: "Standalone chat narrowed by dragging its right border")
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: -900, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(chatWidth() - 320) <= 3 }, timeout: 5), "The chat stops at its minimum width: \(chatWidth())")
        XCTAssertTrue(waitUntil(chatContentFillsPanel, timeout: 5), "The narrowed chat's transcript reflows to the panel once the drag ends: transcript=\(chatTranscript.frame), handle=\(chatHandle.frame)")
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: chatNarrowed - 320, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(chatWidth() - chatNarrowed) <= 6 }, timeout: 5), "Dragging right widens the chat again: \(chatWidth())")
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: 900, dy: 0)))
        // The chat widens only until it and the board's 980-point minimum fill the screen, and never below its 460-point default.
        let screenWidth = app.menuBars.firstMatch.frame.width
        let expectedMaximum = max(460, screenWidth - 980)
        XCTAssertTrue(waitUntil({ abs(chatWidth() - expectedMaximum) <= 6 }, timeout: 5), "Dragging far right stops at \(expectedMaximum) on a \(screenWidth)-point screen: \(chatWidth())")
        XCTAssertTrue(waitUntil(chatContentFillsPanel, timeout: 5), "The widened chat's transcript reflows to the panel once the drag ends: transcript=\(chatTranscript.frame), handle=\(chatHandle.frame)")
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: chatNarrowed - expectedMaximum, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(chatWidth() - chatNarrowed) <= 6 }, timeout: 5), "Dragging back narrows the chat again: \(chatWidth())")
        refreshStandaloneChatSidebar()
        XCTAssertTrue(waitUntil({ chatSidebar.exists && abs(chatWidth() - chatNarrowed) <= 6 }, timeout: 5), "Reopening after a relaunch keeps the dragged width: \(chatWidth())")
        XCTAssertTrue(waitUntil(chatContentFillsPanel, timeout: 5), "The reopened chat's transcript fills its remembered width: transcript=\(chatTranscript.frame), handle=\(chatHandle.frame)")
        attachScreenshot(named: "Standalone chat reopened at its dragged width with the transcript reflowed")
        // The rest of the case asserts exact header positions at the default width. Dragging to the far right clamps to the
        // cap, which is exactly the default when the screen has no spare width; a hand-measured drag would leave a fractional width.
        chatHandleCenter().press(forDuration: 0.2, thenDragTo: chatHandleCenter().withOffset(CGVector(dx: 900, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(chatWidth() - expectedMaximum) <= 6 }, timeout: 5), "Dragging far right again stops at the cap: \(chatWidth())")

        XCTAssertTrue(try tasksFromBoardList().isEmpty, "The standalone chat must never appear on the board.")

        let coveringTask = try runCLI(
            ["task", "create", "--title", "Covers standalone chat", "--prompt", "Fixture task description.", "--repo", fixture.primary.path]
        )["result"] as? [String: Any]
        let coveringTaskID = try XCTUnwrap(coveringTask?["id"] as? String)
        let coveringCard = element("task-card-\(coveringTaskID.uppercased())")
        XCTAssertTrue(waitUntil({ coveringCard.exists }, timeout: 10), "The new task should appear on the board behind the open chat sidebar.")
        clickTaskCardTitle(coveringCard)
        XCTAssertTrue(element("task-view-title").waitForExistence(timeout: 10), "Opening a task should show its conversation view.")
        XCTAssertFalse(element("chat-sidebar").exists, "Entering a task must cover the standalone chat, not show both at once.")
        attachScreenshot(named: "Task view covers standalone chat sidebar")

        element("back-to-board-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10), "Leaving the task should reveal the standalone chat sidebar again.")

        let opened = try runCLI(["chat", "open"])["result"] as? [String: Any]
        let chatTaskID = try XCTUnwrap(opened?["id"] as? String)
        XCTAssertEqual(opened?["title"] as? String, "Chat")
        XCTAssertEqual((opened?["repositoryWorktrees"] as? [Any])?.count, 0)

        // The chat is its own model, not a task, so task commands cannot reach it by ID.
        assertCLIError(try runCLI(["task", "get", chatTaskID], expectedStatus: 3), code: "not_found")
        assertCLIError(try runCLI(["task", "move", chatTaskID, "Done"], expectedStatus: 3), code: "not_found")

        let kyoto = try XCTUnwrap(
            (try runCLI(["chat", "page", "new", "--title", "Trip to Kyoto"])["result"] as? [String: Any])?["page"] as? [String: Any]
        )
        let continued = try XCTUnwrap(
            (try runCLI(["chat", "page", "close-turn", chatTaskID, "--continues", "true"])["result"] as? [String: Any])?["page"] as? [String: Any]
        )
        XCTAssertEqual(continued["id"] as? String, kyoto["id"] as? String, "Continuing must append to the already-active page.")

        let recipes = try XCTUnwrap(
            (try runCLI(["chat", "page", "close-turn", chatTaskID, "--continues", "false", "--new-title", "Dinner recipes"])["result"] as? [String: Any])?["page"] as? [String: Any]
        )
        XCTAssertNotEqual(recipes["id"] as? String, kyoto["id"] as? String, "A topic change must start a new page.")

        _ = try runCLI(["chat", "page", "close-turn", chatTaskID, "--continues", "false"], expectedStatus: 2)

        let pageListing = try XCTUnwrap(try runCLI(["chat", "page", "list"])["result"] as? [String: Any])
        let archiveDirectory = URL(fileURLWithPath: try XCTUnwrap(pageListing["archiveDirectory"] as? String))
        XCTAssertEqual(archiveDirectory.standardizedFileURL, dataDirectory.appendingPathComponent("StandaloneChat-Pages", isDirectory: true).standardizedFileURL)
        let kyotoFile = archiveDirectory.appendingPathComponent("\(try XCTUnwrap(kyoto["id"] as? String)).json")
        let recipesFile = archiveDirectory.appendingPathComponent("\(try XCTUnwrap(recipes["id"] as? String)).json")
        XCTAssertNotEqual(kyotoFile, recipesFile, "Each page must have its own filesystem file.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: kyotoFile.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: recipesFile.path))
        // Recreate the pre-archive database state so opening the manager proves
        // it backfills pages that existed before the one-time file migration.
        var archiveDatabase: OpaquePointer?
        XCTAssertEqual(sqlite3_open(dataDirectory.appendingPathComponent("StandaloneChat-v1.sqlite").path, &archiveDatabase), SQLITE_OK)
        guard let archiveDatabase else { XCTFail("Could not open the standalone chat database for migration setup."); return }
        let markerStatus = sqlite3_exec(archiveDatabase, "DELETE FROM chat_archive_migrations WHERE version = 1;", nil, nil, nil)
        sqlite3_close(archiveDatabase)
        XCTAssertEqual(markerStatus, SQLITE_OK, "Could not reset the page archive migration marker.")
        try FileManager.default.removeItem(at: kyotoFile)
        _ = try runCLI(["chat", "page", "list"])
        XCTAssertTrue(FileManager.default.fileExists(atPath: kyotoFile.path), "Opening a pre-archive database should backfill missing page files once.")
        let matches = try XCTUnwrap(
            (try runCLI(["chat", "page", "search", "Kyoto"])["result"] as? [String: Any])?["matches"] as? [[String: Any]]
        )
        XCTAssertTrue(
            matches.contains { (($0["page"] as? [String: Any])?["id"] as? String) == kyoto["id"] as? String },
            "Searching the old page's title should find it even after a newer page is active."
        )

        // Drive one real provider turn and verify the user/assistant text actually lands on
        // the active page via chat page read, and does not leak onto an unrelated page.
        try Data().write(to: URL(fileURLWithPath: chatFixtureExecutable.path + ".hold-release"))
        let holdMarker = URL(fileURLWithPath: chatFixtureExecutable.path + ".hold-release")
        let activeMarker = URL(fileURLWithPath: chatFixtureExecutable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: chatFixtureExecutable.path + ".turn-release")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)

        let sendProcess = Process()
        sendProcess.executableURL = cliURL
        sendProcess.arguments = ["conversation", "send", chatTaskID, "--message", "What's a good side dish?"]
        var sendEnvironment = ProcessInfo.processInfo.environment
        sendEnvironment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        sendEnvironment["CODEX_HOME"] = dataDirectory.appendingPathComponent("codex-home").path
        sendEnvironment["PLAYHOUSE_WORKTREE_LABEL"] = "Playhouse UI Test Worktree"
        sendEnvironment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        sendEnvironment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        sendEnvironment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = chatFixtureExecutable.path
        sendProcess.environment = sendEnvironment
        let sendStdout = Pipe()
        let sendStderr = Pipe()
        sendProcess.standardOutput = sendStdout
        sendProcess.standardError = sendStderr
        try sendProcess.run()
        defer {
            if sendProcess.isRunning {
                try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                sendProcess.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The fixture should hold the standalone chat turn open for a close-turn report.")
        // Queuing is a conversation action, so it must resolve the chat rather than look for a
        // board task. The turn is held active here, which is exactly when a follow-up queues.
        let queuedInChat = try XCTUnwrap(
            try runCLI(["conversation", "queue", chatTaskID, "--message", "Queue this for after the chat turn."])["result"] as? [String: Any]
        )
        XCTAssertEqual(queuedInChat["text"] as? String, "Queue this for after the chat turn.")
        XCTAssertEqual(queuedInChat["taskID"] as? String, chatTaskID)
        _ = try runCLI(["conversation", "queue-remove", chatTaskID, try XCTUnwrap(queuedInChat["id"] as? String)])
        // Selecting the provider the chat already uses is a no-op that must return the chat.
        let unchangedProvider = try XCTUnwrap(
            try runCLI(["conversation", "provider", chatTaskID, "set", "codex"])["result"] as? [String: Any]
        )
        XCTAssertEqual(unchangedProvider["id"] as? String, chatTaskID)
        XCTAssertEqual(unchangedProvider["conversationProvider"] as? String, "codex")
        _ = try runCLI(["chat", "page", "close-turn", chatTaskID, "--continues", "true"])
        try "Release the completed fixture turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        sendProcess.waitUntilExit()
        XCTAssertEqual(sendProcess.terminationStatus, 0, "The standalone chat turn should complete successfully.")
        try? FileManager.default.removeItem(at: holdMarker)

        // A send moves the chat's own turn state away from Backlog (In Progress, then Waiting
        // Response). That state used to live on a hidden BoardTask, which is how the chat leaked
        // onto the board: it renders from SwiftUI's own @Query over BoardTask, not the board.list
        // CLI path that tasksFromBoardList() checks. The chat is no longer a BoardTask at all, so
        // confirm the rendered board still has no card for it in that state.
        XCTAssertFalse(
            element("task-card-\(chatTaskID)").exists,
            "The standalone chat must never render as a card on the visible Kanban board."
        )

        // The chat is told never to report a task outcome, so chasing one with private
        // reminders can only spend extra provider turns and bury the user's next message in
        // a reminder turn that answers nobody.
        let chatFixtureHistory = try XCTUnwrap(
            try JSONSerialization.jsonObject(
                with: Data(contentsOf: URL(fileURLWithPath: chatFixtureExecutable.path + ".history"))
            ) as? [String: Any]
        )
        let chatFixtureTurns = try XCTUnwrap(chatFixtureHistory["turns"] as? [[String: Any]])
        XCTAssertFalse(chatFixtureTurns.isEmpty, "The chat fixture should have recorded its turns.")
        XCTAssertFalse(
            chatFixtureTurns.contains { (($0["userMessage"] as? String) ?? "").lowercased().contains("outcome reminder") },
            "A standalone chat turn must not trigger the private task-outcome reminders."
        )
        // The chat must know it is Playhouse's own chat and own the board through the CLI,
        // instead of reaching for an unrelated task tool that the user can never see.
        let chatInstructions = (chatFixtureHistory["threadStartDeveloperInstructions"] as? String) ?? ""
        XCTAssertTrue(chatInstructions.contains("task create"), "The chat must be taught the Playhouse task CLI.")
        XCTAssertTrue(chatInstructions.contains("they always mean Playhouse"))
        XCTAssertTrue(chatInstructions.contains("task create --title \"<title>\" --prompt"), "The chat must create tasks with a full description.")
        // Page titles reach the user as transcript separators, parsed from close-turn.
        // Assert the prohibition positively too: pinning only the old wording would let the
        // instruction come back phrased differently.
        XCTAssertTrue(chatInstructions.contains("never write the page name"))
        XCTAssertFalse(chatInstructions.contains("Page: <current page title>"))

        let recipesArchive = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: recipesFile)) as? [String: Any]
        )
        XCTAssertEqual((recipesArchive["page"] as? [String: Any])?["title"] as? String, "Dinner recipes")
        XCTAssertTrue(
            (recipesArchive["messages"] as? [[String: Any]])?.contains {
                ($0["role"] as? String) == "user" && ($0["text"] as? String) == "What's a good side dish?"
            } == true,
            "The completed user turn should be written to its page file before any later page read."
        )
        let recipesMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(recipes["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertTrue(
            recipesMessages.contains { ($0["role"] as? String) == "user" && ($0["text"] as? String) == "What's a good side dish?" },
            "The user's message should be persisted on the page the agent's close-turn call selected."
        )
        XCTAssertTrue(
            recipesMessages.contains { ($0["role"] as? String) == "assistant" && !(($0["text"] as? String) ?? "").isEmpty },
            "The assistant's reply should also be persisted on that page."
        )
        let recipesRead = try XCTUnwrap(try runCLI(["chat", "page", "read", try XCTUnwrap(recipes["id"] as? String)])["result"] as? [String: Any])
        XCTAssertEqual(recipesRead["filePath"] as? String, recipesFile.path)
        XCTAssertEqual(
            (recipesArchive["messages"] as? [[String: Any]])?.compactMap { $0["text"] as? String },
            recipesMessages.compactMap { $0["text"] as? String },
            "The page file should stay synchronized with its persisted transcript."
        )
        let kyotoMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(kyoto["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertTrue(kyotoMessages.isEmpty, "Messages from the recipes turn must not leak onto an unrelated page.")

        let compliantStatus = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        XCTAssertEqual(compliantStatus["missedPreviousPageSignal"] as? Bool, false, "A turn that called close-turn must not be flagged as missed.")

        assertCLIError(
            try runCLI(["task", "repository", "add", chatTaskID, "--repo", fixture.primary.path], expectedStatus: 2),
            code: "invalid_argument"
        )
        _ = try runCLI(["settings", "clear-parent"])
        XCTAssertNil((try runCLI(["settings", "get"])["result"] as? [String: Any])?["defaultParentFolder"] as? String)

        // Exercise the actual sidebar composer without a default repository root. The
        // background fallback must update the visible page title after the GUI send returns.
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
        let classifierHold = URL(fileURLWithPath: chatFixtureExecutable.path + ".hold-classifier")
        let classifierActive = URL(fileURLWithPath: chatFixtureExecutable.path + ".classifier-active")
        let classifierRelease = URL(fileURLWithPath: chatFixtureExecutable.path + ".classifier-release")
        try Data().write(to: classifierHold)
        element("message-composer").click()
        element("message-composer").typeText("Tell me about Saturn's rings")
        XCTAssertTrue(element("send-message-button").isEnabled, "Standalone chat should send without a configured repository root.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: classifierActive.path) }, timeout: 15), "The fallback classifier should run after the primary answer and be held independently.")
        XCTAssertFalse(element("chat-active-page-title").exists, "Page titles should appear in transcript separators, not the header.")
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists, "Page evaluation should stay visually quiet while pending.")
        XCTAssertEqual(element("chat-sidebar").descendants(matching: .progressIndicator).count, 0, "Page evaluation should not show a loader in the chat sidebar.")
        XCTAssertTrue(transcriptMessage("Answers received: Blue / fixture-secret.").waitForExistence(timeout: 10), "The primary answer should render before the background classifier is released.")
        XCTAssertTrue(waitUntil({ self.noTurnIsRunning() }, timeout: 10), "The background classifier must not keep the chat turn running.")
        XCTAssertTrue(chatPageSeparatorIsVisible("Dinner recipes"), "The current title should remain in its transcript separator until classification completes.")
        element("message-composer").click()
        element("message-composer").typeText("One more thought about Saturn")
        element("send-message-button").click()
        XCTAssertFalse(
            waitUntil({ self.fixtureTurnCount(chatFixtureExecutable, containing: "One more thought about Saturn") > 0 }, timeout: 3),
            "A new send should queue behind the held fallback decision."
        )
        try Data("Release classifier.\n".utf8).write(to: classifierRelease)
        let fallbackReady = waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  status["missedPreviousPageSignal"] as? Bool == false,
                  let page = status["activePage"] as? [String: Any],
                  page["title"] as? String == "Saturn Rings",
                  let pageID = page["id"] as? String,
                  let messages = (try? self.runCLI(["chat", "page", "read", pageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]] else { return false }
            return self.chatPageSeparatorIsVisible("Saturn Rings")
                && messages.compactMap { $0["text"] as? String } == [
                    "Tell me about Saturn's rings", "Answers received: Blue / fixture-secret.",
                    "One more thought about Saturn", "Answers received: Blue / fixture-secret.",
                ]
        }, timeout: 30)
        XCTAssertTrue(fallbackReady, "The background fallback should update the active page title and clear the missed-signal warning.")
        XCTAssertFalse(element("chat-active-page-title").exists, "The page title should remain in the transcript, not the header.")
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists, "The warning should disappear after the fallback persists its result.")
        let fallbackStatus = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        let fallbackPage = try XCTUnwrap(fallbackStatus["activePage"] as? [String: Any])
        let fallbackMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(fallbackPage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertTrue(
            fallbackMessages.contains { ($0["role"] as? String) == "user" && ($0["text"] as? String) == "Tell me about Saturn's rings" },
            "The fallback-classified turn's messages should be moved onto its new page."
        )
        XCTAssertTrue(
            fallbackMessages.contains { ($0["role"] as? String) == "assistant" && ($0["text"] as? String) == "Answers received: Blue / fixture-secret." },
            "The assistant reply must move with its user message onto the new page."
        )
        let priorPageMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(recipes["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        // The fixture answers every turn with the same text, so the moved turn is identified
        // by its turn ID: none of its messages, user or assistant, may remain on the prior page.
        let movedTurnID = try XCTUnwrap(
            fallbackMessages.first { ($0["role"] as? String) == "user" && ($0["text"] as? String) == "Tell me about Saturn's rings" }?["turnID"] as? String
        )
        XCTAssertFalse(
            priorPageMessages.contains { ($0["turnID"] as? String) == movedTurnID },
            "The fallback-classified turn must not remain duplicated on the prior page."
        )

        // A later turn was queued while the first fallback was held; both turns must
        // now appear in order on the fallback-selected page.
        let orderedMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(fallbackPage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertEqual(orderedMessages.map { $0["text"] as? String }, [
            "Tell me about Saturn's rings", "Answers received: Blue / fixture-secret.",
            "One more thought about Saturn", "Answers received: Blue / fixture-secret.",
        ], "A later appended turn must follow the moved messages in chronological order.")
        let fixtureHistory = try Data(contentsOf: URL(fileURLWithPath: chatFixtureExecutable.path + ".history"))
        let fixtureTurns = try XCTUnwrap((try JSONSerialization.jsonObject(with: fixtureHistory) as? [String: Any])?["turns"] as? [[String: Any]])
        let classifierTurns = fixtureTurns.filter { ($0["userMessage"] as? String)?.hasPrefix("Classify the latest user message for Playhouse's continuous chat page index.") == true }
        XCTAssertEqual(classifierTurns.count, 3, "The fallback should reject one malformed result, retry once, then classify the later turn.")
        let classifierTurn = try XCTUnwrap(classifierTurns.last)
        XCTAssertEqual(classifierTurn["modelID"] as? String, "gpt-6-luna", "The Codex fallback should use Luna.")
        XCTAssertEqual(classifierTurn["reasoningEffort"] as? String, "low", "The background classifier should use low effort.")

        // An explicit page start supersedes a held classifier. Reopen the sidebar
        // to refresh its persisted status, then ensure the late result stays stale.
        let priorPageID = try XCTUnwrap(fallbackPage["id"] as? String)
        try? FileManager.default.removeItem(at: classifierActive)
        try? FileManager.default.removeItem(at: classifierRelease)
        // Hold only Neptune's classifier: a generic hold is taken by whichever classifier runs
        // next, which can be the previous turn's still-running decision.
        try Data().write(to: URL(fileURLWithPath: chatFixtureExecutable.path + ".hold-neptune-classifier"))
        element("message-composer").click()
        element("message-composer").typeText("Tell me about Neptune")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: classifierActive.path) }, timeout: 15))
        let explicitPage = try XCTUnwrap((try runCLI(["chat", "page", "new", "--title", "Explicit topic"])["result"] as? [String: Any])?["page"] as? [String: Any])
        refreshStandaloneChatSidebar()
        // A page's title separator is drawn before its first message, so the new page shows
        // once a turn lands on it (asserted after the Mars send below).
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists)
        try Data("Release classifier.\n".utf8).write(to: classifierRelease)
        XCTAssertTrue(waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  let page = status["activePage"] as? [String: Any] else { return false }
            return (page["id"] as? String) == (explicitPage["id"] as? String)
        }, timeout: 30), "The late classifier must not replace the explicit page.")
        let explicitMessages = try XCTUnwrap((try runCLI(["chat", "page", "read", try XCTUnwrap(explicitPage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]])
        XCTAssertTrue(explicitMessages.isEmpty)
        let oldPageMessages = try XCTUnwrap((try runCLI(["chat", "page", "read", priorPageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]])
        XCTAssertTrue(oldPageMessages.contains { ($0["text"] as? String) == "Tell me about Neptune" })
        XCTAssertTrue(oldPageMessages.contains { ($0["role"] as? String) == "assistant" && ($0["text"] as? String) == "Answers received: Blue / fixture-secret." })

        let classifierFailure = URL(fileURLWithPath: chatFixtureExecutable.path + ".fail-classifier")
        try Data().write(to: classifierFailure)
        element("message-composer").click()
        element("message-composer").typeText("Tell me about Mars")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            (try? self.runCLI(["chat", "status"])["result"] as? [String: Any])?["missedPreviousPageSignal"] as? Bool == true
        }, timeout: 30), "Malformed helper results should keep the pending decision visible and durable.")
        XCTAssertTrue(waitUntil({ self.chatPageSeparatorIsVisible("Explicit topic") }, timeout: 10), "The explicit page's title should appear with its first message.")
        XCTAssertFalse(element("chat-active-page-title").exists, "Unresolved classification should not add a page title to the header.")
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists, "Unresolved classification should remain visually quiet.")
        XCTAssertEqual(element("chat-sidebar").descendants(matching: .progressIndicator).count, 0, "Unresolved classification should not show a loader.")
        XCTAssertTrue(waitUntil({ self.noTurnIsRunning() }, timeout: 10), "The Mars turn should finish before the next send.")
        element("message-composer").click()
        element("message-composer").typeText("Do not overtake Mars")
        element("send-message-button").click()
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 15), "A later send should explain that the prior page decision is still pending.")
        let failedHistory = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: chatFixtureExecutable.path + ".history"))) as? [String: Any]
        let failedTurns = try XCTUnwrap(failedHistory?["turns"] as? [[String: Any]])
        XCTAssertFalse(failedTurns.contains { ($0["userMessage"] as? String) == "Do not overtake Mars" }, "The blocked follow-up must not reach the provider.")
        try FileManager.default.removeItem(at: classifierFailure)
        _ = try runCLI(["chat", "status"])
        let retryStatus = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        XCTAssertFalse(retryStatus["missedPreviousPageSignal"] as? Bool ?? true)
        XCTAssertEqual((retryStatus["activePage"] as? [String: Any])?["title"] as? String, "Mars")
        refreshStandaloneChatSidebar()
        XCTAssertTrue(waitUntil({ self.chatPageSeparatorIsVisible("Mars") }, timeout: 10))
        XCTAssertFalse(element("chat-active-page-title").exists, "The resolved title should remain in the transcript, not the header.")
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists)
        element("message-composer").click()
        element("message-composer").typeKey("a", modifierFlags: .command)
        element("message-composer").typeText("Another thought about Mars")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  status["missedPreviousPageSignal"] as? Bool == false,
                  let page = status["activePage"] as? [String: Any],
                  page["title"] as? String == "Mars",
                  let pageID = page["id"] as? String,
                  let messages = (try? self.runCLI(["chat", "page", "read", pageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]] else { return false }
            return messages.contains { ($0["text"] as? String) == "Another thought about Mars" }
        }, timeout: 30), "A new send should work once the pending page decision has recovered.")

        // Page sessions rotate, so earlier pages must stay visible rather than disappearing.
        XCTAssertTrue(revealWholeTranscript(), "The reopened chat should load its earlier pages as the reader scrolls up.")
        XCTAssertTrue(chatPageSeparatorIsVisible("Dinner recipes"), "An earlier page stays visible after its session rotated.")
        XCTAssertTrue(
            element("chat-sidebar").groups["What's a good side dish?"].exists,
            "An earlier page keeps its messages in the chat transcript."
        )
        let boardTask = try XCTUnwrap(
            (try runCLI(["task", "create", "--title", "Context page rejection", "--prompt", "Fixture task description."])["result"] as? [String: Any])?["id"] as? String
        )
        let activePageID = try XCTUnwrap(
            ((try runCLI(["chat", "status"])["result"] as? [String: Any])?["activePage"] as? [String: Any])?["id"] as? String
        )
        assertCLIError(
            try runCLI(["conversation", "send", boardTask, "--message", "Hello", "--context-page", activePageID], expectedStatus: 2),
            code: "invalid_argument"
        )

        element("back-to-board-button").click()
        XCTAssertTrue(waitUntil({ !element("chat-sidebar").exists }, timeout: 5), "Returning to the board should slide the chat sidebar away.")
        // As before the board sidebar existed, the window keeps the width it grew to.
        XCTAssertGreaterThan(mainWindow.frame.width, windowFrameBeforeOpeningChat.width + 1, "Closing chat should keep the window's grown width.")
        XCTAssertEqual(boardHeader.frame.origin, headerFrameBeforeOpeningChat.origin, "Closing chat should leave the logo header in place.")
        XCTAssertEqual(boardHeader.frame.height, headerFrameBeforeOpeningChat.height, "Closing chat should leave the logo header's height unchanged.")
        XCTAssertTrue(element(withAccessibilityLabel: "Kanban sidebar").waitForExistence(timeout: 5), "Closing chat should restore the board sidebar to accessibility navigation.")
        XCTAssertTrue(app.images["Playhouse logo"].exists, "Closing chat should restore the logo to accessibility navigation.")
        XCTAssertEqual(boardSidebar.frame, sidebarFrameBeforeOpeningChat, "Closing chat should reveal the sidebar in its original position.")
        // The kept width can leave room to spare, so the columns return beside the sidebar
        // rather than to their exact original x.
        XCTAssertTrue(
            waitUntil({
                let backlog = backlogColumn.frame
                return backlog.minX < backlogColumnFrameWhileChatOpen.minX - 1
                    && backlog.minX >= boardSidebar.frame.maxX
                    && reviewColumn.frame.maxX <= columnsViewport.frame.maxX
            }, timeout: 5),
            "Closing chat should move the board columns back beside the sidebar, still fully inside the board viewport."
        )
        attachScreenshot(named: "Board layout restored after closing chat")
    }

    // case-contract: test_standalone_chat_page_sessions_isolate_context | Each standalone chat page is its own provider session: the first turn of a page starts a fresh session carrying the system prompt plus only that page's own turns, later turns on that page resume it without repeating the page context, and a different page never shares it, so an earlier page's turns never reach a later page. An annotation that quotes an earlier page carries just that page into the current turn, and rotating sessions still leaves every page's messages visible in the transcript.
    func test_standalone_chat_page_sessions_isolate_context() throws {
        let executable = dataDirectory.appendingPathComponent("claude-fixture-chat-page-sessions")
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        _ = try runCLI(["settings", "set-default-provider", "claude"])
        _ = try runCLI(["settings", "clear-parent"])
        launchApp(defaultParent: nil)
        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10))
        let chatID = try XCTUnwrap((try runCLI(["chat", "open"])["result"] as? [String: Any])?["id"] as? String)

        func waitForPage(_ title: String) throws -> [String: Any] {
            var active: [String: Any] = [:]
            let settled = waitUntil({
                guard let response = try? self.runCLI(["chat", "status"]),
                      let status = response["result"] as? [String: Any],
                      let page = status["activePage"] as? [String: Any],
                      (status["missedPreviousPageSignal"] as? Bool) == false,
                      page["title"] as? String == title else { return false }
                active = page
                return true
            }, timeout: 30)
            XCTAssertTrue(settled, "The chat never settled on page \(title).")
            return active
        }

        func sendFromSidebar(_ prompt: String) {
            let composer = element("message-composer")
            XCTAssertTrue(composer.waitForExistence(timeout: 10))
            let receivedBefore = fixtureTurnCount(executable, containing: prompt)
            composer.click()
            composer.typeText(prompt)
            element("send-message-button").click()
            XCTAssertTrue(waitUntil({
                self.fixtureTurnCount(executable, containing: prompt) > receivedBefore && self.noTurnIsRunning()
            }, timeout: 30), "The turn should finish.")
        }

        func answerTurns() throws -> [[String: Any]] {
            let data = try Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))
            let history = try XCTUnwrap(try JSONSerialization.jsonObject(with: data) as? [String: Any])
            let turns = try XCTUnwrap(history["turns"] as? [[String: Any]])
            return turns.filter { !(($0["userText"] as? String) ?? "").hasPrefix("Classify the latest user message") }
        }

        func turn(endingWith message: String) throws -> [String: Any] {
            let match = try answerTurns().last { (($0["userText"] as? String) ?? "").hasSuffix(message) }
            return try XCTUnwrap(match, "The fixture never received a turn ending with \(message).")
        }

        sendFromSidebar("Tell me about volcanoes")
        let volcanoes = try waitForPage("Volcanoes")
        sendFromSidebar("Tell me about Saturn's rings")
        _ = try waitForPage("Saturn Rings")
        sendFromSidebar("One more thought about Saturn")
        _ = try waitForPage("Saturn Rings")

        let first = try turn(endingWith: "Tell me about volcanoes")
        let second = try turn(endingWith: "Tell me about Saturn's rings")
        let third = try turn(endingWith: "One more thought about Saturn")
        // The turn that opens a page still answers in the page it was sent into; only once the
        // classifier moves it does the next turn get that new page's own session.
        XCTAssertEqual(first["sessionID"] as? String, second["sessionID"] as? String, "One page answers in one session.")
        XCTAssertNotEqual(
            third["sessionID"] as? String, first["sessionID"] as? String,
            "A different page must never share another page's provider session."
        )
        for pageTurn in [first, third] {
            XCTAssertEqual(pageTurn["resumed"] as? Bool, false, "A page's first turn starts that page's own session.")
            let arguments = try XCTUnwrap(pageTurn["arguments"] as? [String])
            let promptIndex = try XCTUnwrap(arguments.firstIndex(of: "--append-system-prompt"))
            XCTAssertTrue(
                arguments[promptIndex + 1].contains("chat page close-turn"),
                "Every page session must carry the standalone chat system prompt."
            )
        }
        XCTAssertEqual(second["resumed"] as? Bool, true, "A turn sent into an existing page resumes its session.")
        let thirdText = try XCTUnwrap(third["userText"] as? String)
        XCTAssertTrue(thirdText.contains("Tell me about Saturn's rings"), "A fresh page session is seeded with its own page's turns.")
        XCTAssertFalse(thirdText.contains("Tell me about volcanoes"), "An earlier page must never be sent as context for a later page.")

        sendFromSidebar("Another thought about Mars")
        _ = try waitForPage("Saturn Rings")
        let fourth = try turn(endingWith: "Another thought about Mars")
        XCTAssertEqual(fourth["sessionID"] as? String, third["sessionID"] as? String, "The same page keeps one session.")
        XCTAssertEqual(fourth["resumed"] as? Bool, true, "A continuing turn resumes the page's session.")
        XCTAssertFalse(
            try XCTUnwrap(fourth["userText"] as? String).contains("<playhouse-handoff-context>"),
            "A resumed page session must not repeat its page context."
        )

        // Commenting on a message from an earlier page must carry that page into this turn.
        // Driven through the visible select -> Add comment -> send flow, not the CLI flag, so
        // the composer's own annotation-to-page mapping is what is exercised.
        let volcanoesID = try XCTUnwrap(volcanoes["id"] as? String)
        let archived = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", volcanoesID])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertFalse(archived.isEmpty, "The earlier page should still hold its own turns.")
        let historyMessages = try XCTUnwrap(
            (try runCLI(["conversation", "history", chatID])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        let volcanoMessage = try XCTUnwrap(
            historyMessages.first { ($0["text"] as? String) == "Tell me about volcanoes" },
            "The earlier page's message should still be in the visible transcript."
        )
        let volcanoMessageID = try XCTUnwrap(volcanoMessage["id"] as? String)
        let volcanoView = element("user-message-\(volcanoMessageID)")
        XCTAssertTrue(volcanoView.waitForExistence(timeout: 10), "An earlier page's message stays visible after rotation.")
        volcanoView.click()
        volcanoView.typeKey("a", modifierFlags: .command)
        let addComment = app.buttons.matching(NSPredicate(format: "label == %@", "Add comment")).firstMatch
        XCTAssertTrue(addComment.waitForExistence(timeout: 5), "Selecting transcript text should expose Add comment.")
        addComment.click()
        let commentField = element("comment-input-field")
        XCTAssertTrue(commentField.waitForExistence(timeout: 5))
        assertCommentFieldBesideHint(commentField)
        commentField.typeText("What did we say before?")
        // Clicking the arrow submits a comment on a user message (it once did nothing there).
        element("add-comment-button").click()
        XCTAssertTrue(waitUntil({ !commentField.exists }, timeout: 5), "Submitting the comment should close its popover.")
        XCTAssertTrue(waitUntil({ element("send-message-button").isEnabled }, timeout: 5), "A comment alone should be sendable.")
        XCTAssertTrue(waitUntil({
            self.accessibleLabelOrValue(of: self.element("pending-comment-count")).contains("1 comment")
        }, timeout: 5), "The arrow adds exactly one comment on a user message.")
        let annotatedBefore = fixtureTurnCount(executable, containing: "What did we say before?")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            self.fixtureTurnCount(executable, containing: "What did we say before?") > annotatedBefore && self.noTurnIsRunning()
        }, timeout: 30), "The annotated turn should finish.")
        _ = try waitForPage("Saturn Rings")
        let annotated = try XCTUnwrap(
            try answerTurns().last { (($0["userText"] as? String) ?? "").contains("What did we say before?") },
            "The annotated turn never reached the provider."
        )
        XCTAssertTrue(
            try XCTUnwrap(annotated["userText"] as? String).contains("Tell me about volcanoes"),
            "A page quoted by a comment travels with the turn that quotes it."
        )

        XCTAssertTrue(chatPageSeparatorIsVisible("Volcanoes"), "Rotating sessions must not hide earlier pages.")
        XCTAssertTrue(chatPageSeparatorIsVisible("Saturn Rings"))
        XCTAssertTrue(
            element("chat-sidebar").groups["Tell me about volcanoes"].exists,
            "Earlier pages stay visible in the chat transcript."
        )
        attachScreenshot(named: "Standalone chat pages keep separate sessions")
    }

    // case-contract: test_standalone_chat_answer_stays_final_around_close_turn | A standalone chat reports no task outcome, so it ends every turn with Playhouse's own chat page close-turn signal, which Claude runs after its answer and before its closing line. That answer and closing line form one final answer, not commentary, in the streamed final answer, fresh CLI/XPC history, and the visible transcript, so the response is never left buried inside the collapsed Worked for disclosure; text written before an ordinary tool earlier in the same turn still stays commentary there, and the close-turn command really runs and succeeds. This classification is Claude-specific because Playhouse derives each message's phase from Claude's tool stream, while Codex reports the phase in its own protocol and so cannot mis-file an answer on the same turn shape.
    func test_standalone_chat_answer_stays_final_around_close_turn() throws {
        let executable = dataDirectory.appendingPathComponent("claude-fixture-chat-close-turn")
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        _ = try runCLI(["settings", "set-default-provider", "claude"])
        _ = try runCLI(["settings", "clear-parent"])
        launchApp(defaultParent: nil)
        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10))
        _ = try runCLI(["chat", "open"])

        let intent = "Let me check the newer release first."
        let answer = "Confirmed: 2.1.309 registers the new model and 2.1.308 does not."
        let closing = "Tell me if you want the upgrade command."
        let prompt = "Summarize the release notes."
        // Transcript messages are labeled groups.
        func visibleTexts(containing text: String) -> XCUIElementQuery {
            app.groups.matching(NSPredicate(format: "label CONTAINS %@", text))
        }

        let composer = element("message-composer")
        XCTAssertTrue(composer.waitForExistence(timeout: 10))
        composer.click()
        composer.typeText(prompt)
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            self.fixtureTurnCount(executable, containing: prompt) > 0 && self.noTurnIsRunning()
        }, timeout: 30), "The chat turn should finish.")
        XCTAssertTrue(waitUntil({
            self.element("codex-activity-disclosure").exists
                && self.element("codex-activity-disclosure").label.hasPrefix("Worked for")
        }, timeout: 20), "The settled chat turn should show its Worked for summary.")

        // Settling re-renders the transcript (commentary folds into Worked for), so the answer can briefly be mid-layout.
        XCTAssertTrue(visibleTexts(containing: answer).firstMatch.waitForExistence(timeout: 10),
                      "The answer written before the close-turn signal must be the visible response, not collapsed commentary.")
        XCTAssertTrue(visibleTexts(containing: closing).firstMatch.waitForExistence(timeout: 5),
                      "The closing line Claude adds after the signal belongs to the same answer.")
        XCTAssertEqual(visibleTexts(containing: intent).count, 0,
                       "Text written before an ordinary tool stays collapsed commentary.")
        attachScreenshot(named: "standalone-chat-answer-is-the-response")

        element("codex-activity-disclosure").click()
        let activityDetails = element("codex-activity-details")
        XCTAssertTrue(activityDetails.waitForExistence(timeout: 5), "Worked for should expand.")
        // A progress bubble carries its text as the element's value, not its label, so it is
        // identified by the provider message it was built from.
        func progressBubbles(forMessageID messageID: String) -> XCUIElementQuery {
            activityDetails.staticTexts.matching(
                NSPredicate(format: "identifier BEGINSWITH %@", "codex-progress-message-\(messageID)")
            )
        }
        XCTAssertEqual(progressBubbles(forMessageID: "msg_chat_answer").count, 0,
                       "The answer must never be demoted into a Worked for progress entry.")
        let intentBubble = progressBubbles(forMessageID: "msg_chat_intent")
        XCTAssertTrue(intentBubble.count > 0,
                      "The text written before an ordinary tool belongs inside Worked for.")
        XCTAssertTrue((intentBubble.firstMatch.value as? String ?? "").contains(intent),
                      "The Worked for progress entry should carry the commentary Claude wrote before its tool call.")
        attachScreenshot(named: "standalone-chat-worked-for-holds-only-commentary")
        element("codex-activity-disclosure").click()

        let status = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        XCTAssertEqual(status["missedPreviousPageSignal"] as? Bool, false,
                       "A close-turn signal that really ran must satisfy the page signal instead of falling back to the classifier.")
    }

    // case-contract: test_standalone_chat_recalls_loaded_pages | When a standalone chat's agent loads an earlier page into its context with `chat page read`, the conversation renders one deterministic "Recalling <page title>" line per loaded page, titled from the page archive rather than from anything the agent wrote, in the order the pages were read. The lines are visible in the turn that read them without opening the Worked for disclosure, stay once the turn settles and after a later turn and a reopen, and the read commands really run and succeed so the history carries each call and the page's own title. The line is derived from Playhouse's own provider-neutral command activity (a shell call titled "Running <command>" for both Claude and Codex) and the page store, so provider selection cannot change it; one representative provider (Claude) covers the shared path.
    func test_standalone_chat_recalls_loaded_pages() throws {
        let executable = dataDirectory.appendingPathComponent("claude-fixture-chat-recall")
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        _ = try runCLI(["settings", "set-default-provider", "claude"])
        _ = try runCLI(["settings", "clear-parent"])
        launchApp(defaultParent: nil)
        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10))
        _ = try runCLI(["chat", "open"])
        let titles = ["Volcano research", "Saturn notes"]
        var pageIDs: [String] = []
        for title in titles {
            let page = try XCTUnwrap(
                (try runCLI(["chat", "page", "new", "--title", title])["result"] as? [String: Any])?["page"] as? [String: Any]
            )
            pageIDs.append(try XCTUnwrap(page["id"] as? String))
        }
        _ = try runCLI(["chat", "page", "new", "--title", "Current topic"])

        func recallRow(_ index: Int) -> XCUIElement { element("conversation-chat-page-recall-toolu_recall_\(index)") }
        func send(_ prompt: String) {
            let composer = element("message-composer")
            XCTAssertTrue(composer.waitForExistence(timeout: 10))
            composer.click()
            composer.typeText(prompt)
            element("send-message-button").click()
        }

        func waitForRecallLabel(_ index: Int, _ title: String) -> Bool {
            waitUntil({ recallRow(index).exists && recallRow(index).label == "Recalling \(title)" }, timeout: 10)
        }
        let hold = URL(fileURLWithPath: executable.path + ".recall-hold")
        let ready = URL(fileURLWithPath: executable.path + ".recall-ready")
        let release = URL(fileURLWithPath: executable.path + ".recall-release")
        try Data().write(to: hold)
        let prompt = "recall-earlier-pages " + pageIDs.map { "page-id:\($0)" }.joined(separator: " ")
        send(prompt)
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: ready.path) }, timeout: 30),
                      "The recalling turn should be held open after its reads.")
        XCTAssertFalse(self.noTurnIsRunning(), "The turn is still running while the lines are checked.")
        for (index, title) in titles.enumerated() {
            XCTAssertTrue(waitForRecallLabel(index, title), "A Recalling line for \(title) should render the moment its read is seen, while the turn runs.")
        }
        XCTAssertLessThan(recallRow(0).frame.minY, recallRow(1).frame.minY, "Lines render in the order the pages were read.")
        XCTAssertEqual(app.descendants(matching: .any).matching(identifier: "conversation-chat-page-recall-toolu_recall_0").count, 1,
                       "A live page read renders as one Recalling line, not again as a command row in the work list.")
        XCTAssertEqual(element("codex-activity-details").descendants(matching: .any)
            .matching(identifier: "conversation-chat-page-recall-toolu_recall_0").count, 0,
                       "The line stands on its own rather than inside the work disclosure.")
        attachScreenshot(named: "standalone-chat-recalling-lines-live")
        try Data().write(to: release)
        XCTAssertTrue(waitUntil({
            self.fixtureTurnCount(executable, containing: "recall-earlier-pages") > 0 && self.noTurnIsRunning()
        }, timeout: 30), "The recalling turn should finish.")
        for (index, title) in titles.enumerated() {
            XCTAssertTrue(waitForRecallLabel(index, title), "The line for \(title) stays once the turn settles.")
        }
        let disclosure = element("codex-activity-disclosure")
        XCTAssertTrue(disclosure.waitForExistence(timeout: 20), "The settled turn shows its Worked for summary.")
        XCTAssertTrue((disclosure.value as? String ?? "").hasPrefix("Collapsed"), "Worked for stays collapsed while the lines are visible.")
        attachScreenshot(named: "standalone-chat-recalling-lines")

        send("recall-earlier-pages")
        XCTAssertTrue(waitUntil({
            self.fixtureTurnCount(executable, containing: "recall-earlier-pages") > 1 && self.noTurnIsRunning()
        }, timeout: 30), "A later turn should finish.")
        XCTAssertTrue(revealWholeTranscript(), "The earlier turn should load as the reader scrolls up.")
        for (index, title) in titles.enumerated() {
            XCTAssertTrue(waitForRecallLabel(index, title), "The Recalling line for \(title) should stay after a later turn.")
        }
        attachScreenshot(named: "standalone-chat-recalling-lines-after-later-turn")

        refreshStandaloneChatSidebar()
        XCTAssertTrue(revealWholeTranscript(), "The reopened chat should load its earlier turn as the reader scrolls up.")
        for (index, title) in titles.enumerated() {
            XCTAssertTrue(waitForRecallLabel(index, title), "The Recalling line for \(title) should survive reopening the chat.")
        }
    }

    // case-contract: test_standalone_chat_claude_fallback_classifier | When a standalone chat uses Claude, a missed page signal invokes the Haiku helper at low effort; a malformed result is rejected and retried, an unrelated later question and its assistant reply move to a new titled page, the UI keeps page evaluation visually quiet without blocking the primary answer, updates the transcript separator when classification completes, and holds a following send until the decision resolves, and appends the related follow-up in chronological order. The Claude-specific model and effort arguments are verified through the real CLI/XPC path. An explicit page start during a pending fallback cancels its stale result, keeps the missed turn on its original page, and clears the warning. If all helper results are invalid, the pending decision remains durable, blocks the next provider send, and retries after the helper recovers; the UI keeps the unresolved state visually quiet and sends successfully once recovery completes.
    func test_standalone_chat_claude_fallback_classifier() throws {
        let executable = dataDirectory.appendingPathComponent("claude-fixture-chat-page-fallback")
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        _ = try runCLI(["settings", "set-default-provider", "claude"])
        _ = try runCLI(["settings", "clear-parent"])
        launchApp(defaultParent: nil)
        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10))
        let opened = try XCTUnwrap((try runCLI(["chat", "open"])["result"] as? [String: Any]))
        XCTAssertNotNil(opened["id"] as? String)
        XCTAssertEqual(opened["conversationProvider"] as? String, "claude")
        let firstPage = try XCTUnwrap(
            (try runCLI(["chat", "page", "new", "--title", "General chat"])["result"] as? [String: Any])?["page"] as? [String: Any]
        )

        func sendFromSidebar(_ prompt: String, expectedTitle: String) throws {
            let composer = element("message-composer")
            XCTAssertTrue(composer.waitForExistence(timeout: 10))
            let hold = URL(fileURLWithPath: executable.path + ".hold-classifier")
            let active = URL(fileURLWithPath: executable.path + ".classifier-active")
            let release = URL(fileURLWithPath: executable.path + ".classifier-release")
            if prompt == "Tell me about volcanoes" { try Data().write(to: hold) }
            composer.click()
            composer.typeText(prompt)
            XCTAssertTrue(element("send-message-button").isEnabled, "Standalone chat should remain sendable without a repository parent.")
            element("send-message-button").click()
            if prompt == "Tell me about volcanoes" {
                XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: active.path) }, timeout: 15), "The Haiku fallback should remain held after the primary Claude turn finishes.")
                XCTAssertFalse(element("chat-active-page-title").exists, "Page titles should appear in transcript separators, not the header.")
                XCTAssertFalse(element("chat-missed-page-signal-notice").exists, "Page evaluation should stay visually quiet while pending.")
                XCTAssertEqual(element("chat-sidebar").descendants(matching: .progressIndicator).count, 0, "Page evaluation should not show a loader in the chat sidebar.")
                XCTAssertTrue(transcriptMessage("OK.").waitForExistence(timeout: 10), "The primary Claude answer should be visible while fallback classification is pending.")
                XCTAssertTrue(waitUntil({ self.noTurnIsRunning() }, timeout: 10), "A background classifier must not keep the chat turn running.")
                XCTAssertTrue(chatPageSeparatorIsVisible("General chat"))
                return
            }
            if prompt == "Tell me about Saturn's rings" {
                XCTAssertFalse(
                    waitUntil({ self.fixtureTurnCount(executable, containing: prompt) > 0 }, timeout: 3),
                    "The queued Claude turn should wait for the prior page decision."
                )
                try Data("Release classifier.\n".utf8).write(to: release)
            }
            XCTAssertTrue(waitUntil({
                guard self.chatPageSeparatorIsVisible(expectedTitle),
                      let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any] else { return false }
                return status["missedPreviousPageSignal"] as? Bool == false
            }, timeout: 30), "The Haiku fallback should persist and visibly show the title \(expectedTitle).")
            XCTAssertFalse(element("chat-missed-page-signal-notice").exists)
        }

        try sendFromSidebar("Tell me about volcanoes", expectedTitle: "Volcanoes")
        try sendFromSidebar("Tell me about Saturn's rings", expectedTitle: "Saturn Rings")
        try sendFromSidebar("One more thought about Saturn", expectedTitle: "Saturn Rings")

        XCTAssertTrue(waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  status["missedPreviousPageSignal"] as? Bool == false,
                  let page = status["activePage"] as? [String: Any],
                  page["title"] as? String == "Saturn Rings",
                  let pageID = page["id"] as? String,
                  let messages = (try? self.runCLI(["chat", "page", "read", pageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]] else { return false }
            return messages.compactMap { $0["text"] as? String } == [
                "Tell me about Saturn's rings", "OK.", "One more thought about Saturn", "OK.",
            ]
        }, timeout: 30), "The related follow-up must finish on the selected page in transcript order.")

        let status = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        let activePage = try XCTUnwrap(status["activePage"] as? [String: Any])
        XCTAssertNotEqual(activePage["id"] as? String, firstPage["id"] as? String)
        let firstMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(firstPage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        let activeMessages = try XCTUnwrap(
            (try runCLI(["chat", "page", "read", try XCTUnwrap(activePage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]]
        )
        XCTAssertTrue(firstMessages.contains { ($0["role"] as? String) == "user" && ($0["text"] as? String) == "Tell me about volcanoes" })
        XCTAssertTrue(firstMessages.contains { ($0["role"] as? String) == "assistant" && ($0["text"] as? String) == "OK." })
        XCTAssertEqual(firstMessages.filter { ($0["role"] as? String) == "assistant" && ($0["text"] as? String) == "OK." }.count, 1, "The Saturn assistant reply must not remain duplicated on the Volcanoes page.")
        XCTAssertEqual(activeMessages.map { $0["text"] as? String }, [
            "Tell me about Saturn's rings", "OK.", "One more thought about Saturn", "OK.",
        ], "A related turn after fallback must append in chronological order.")
        XCTAssertFalse(firstMessages.contains { ($0["text"] as? String) == "Tell me about Saturn's rings" })
        let pages = try XCTUnwrap((try runCLI(["chat", "page", "list"])["result"] as? [String: Any])?["pages"] as? [[String: Any]])
        XCTAssertEqual(pages.count, 2)
        XCTAssertEqual(Set(pages.compactMap { $0["title"] as? String }), Set(["Volcanoes", "Saturn Rings"]))
        let history = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))) as? [String: Any]
        let turns = try XCTUnwrap(history?["turns"] as? [[String: Any]])
        let classifications = turns.filter { ($0["userText"] as? String)?.hasPrefix("Classify the latest user message for Playhouse's continuous chat page index.") == true }
        XCTAssertEqual(classifications.count, 4, "The fallback should retry one malformed result and classify a later follow-up.")
        for turn in classifications {
            XCTAssertEqual(turn["effort"] as? String, "low")
            let arguments = try XCTUnwrap(turn["arguments"] as? [String])
            let modelArgumentIndex = try XCTUnwrap(arguments.firstIndex(of: "--model"))
            XCTAssertEqual(arguments[modelArgumentIndex + 1], "haiku")
        }

        let priorPageID = try XCTUnwrap(activePage["id"] as? String)
        let hold = URL(fileURLWithPath: executable.path + ".hold-classifier")
        let active = URL(fileURLWithPath: executable.path + ".classifier-active")
        let release = URL(fileURLWithPath: executable.path + ".classifier-release")
        try? FileManager.default.removeItem(at: active)
        try? FileManager.default.removeItem(at: release)
        try Data().write(to: hold)
        let composer = element("message-composer")
        composer.click()
        composer.typeText("Tell me about Neptune")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: active.path) }, timeout: 15))
        let explicitPage = try XCTUnwrap((try runCLI(["chat", "page", "new", "--title", "Explicit topic"])["result"] as? [String: Any])?["page"] as? [String: Any])
        refreshStandaloneChatSidebar()
        // A page's title separator is drawn before its first message, so the new page shows
        // once a turn lands on it (asserted after the Mars send below).
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists)
        try Data("Release classifier.\n".utf8).write(to: release)
        XCTAssertTrue(waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  let page = status["activePage"] as? [String: Any] else { return false }
            return (page["id"] as? String) == (explicitPage["id"] as? String)
        }, timeout: 30))
        let explicitMessages = try XCTUnwrap((try runCLI(["chat", "page", "read", try XCTUnwrap(explicitPage["id"] as? String)])["result"] as? [String: Any])?["messages"] as? [[String: Any]])
        XCTAssertTrue(explicitMessages.isEmpty)
        let oldPageMessages = try XCTUnwrap((try runCLI(["chat", "page", "read", priorPageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]])
        XCTAssertTrue(oldPageMessages.contains { ($0["text"] as? String) == "Tell me about Neptune" })
        XCTAssertTrue(oldPageMessages.contains { ($0["role"] as? String) == "assistant" && ($0["text"] as? String) == "OK." })

        let classifierFailure = URL(fileURLWithPath: executable.path + ".fail-classifier")
        try Data().write(to: classifierFailure)
        composer.click()
        composer.typeText("Tell me about Mars")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            (try? self.runCLI(["chat", "status"])["result"] as? [String: Any])?["missedPreviousPageSignal"] as? Bool == true
        }, timeout: 30))
        XCTAssertTrue(waitUntil({ self.chatPageSeparatorIsVisible("Explicit topic") }, timeout: 10), "The explicit page's title should appear with its first message.")
        XCTAssertTrue(waitUntil({ self.noTurnIsRunning() }, timeout: 10), "The Mars turn should finish before the next send.")
        composer.click()
        composer.typeText("Do not overtake Mars")
        element("send-message-button").click()
        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 15), "Claude chat should explain when a prior page decision is still unresolved.")
        let failedHistory = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))) as? [String: Any]
        let failedTurns = try XCTUnwrap(failedHistory?["turns"] as? [[String: Any]])
        XCTAssertFalse(failedTurns.contains { ($0["userText"] as? String) == "Do not overtake Mars" })
        try FileManager.default.removeItem(at: classifierFailure)
        _ = try runCLI(["chat", "status"])
        let retryStatus = try XCTUnwrap(try runCLI(["chat", "status"])["result"] as? [String: Any])
        XCTAssertFalse(retryStatus["missedPreviousPageSignal"] as? Bool ?? true)
        XCTAssertEqual((retryStatus["activePage"] as? [String: Any])?["title"] as? String, "Mars")
        refreshStandaloneChatSidebar()
        XCTAssertTrue(waitUntil({ self.chatPageSeparatorIsVisible("Mars") }, timeout: 10))
        XCTAssertFalse(element("chat-missed-page-signal-notice").exists)
        composer.click()
        composer.typeKey("a", modifierFlags: .command)
        composer.typeText("Another thought about Mars")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            guard let status = try? self.runCLI(["chat", "status"])["result"] as? [String: Any],
                  status["missedPreviousPageSignal"] as? Bool == false,
                  let page = status["activePage"] as? [String: Any],
                  page["title"] as? String == "Mars",
                  let pageID = page["id"] as? String,
                  let messages = (try? self.runCLI(["chat", "page", "read", pageID])["result"] as? [String: Any])?["messages"] as? [[String: Any]] else { return false }
            return messages.contains { ($0["text"] as? String) == "Another thought about Mars" }
        }, timeout: 30))
    }

    // case-contract: test_task_prompt_draft_persists_after_back | Creating a repository task leaves its selected branch pending while the composer automatically saves an unsent prompt as it is typed; clearing the composer clears the stored draft, backing out needs no Save button, and reopening restores the draft without creating a branch or worktree. Blank drafts cannot be stored, and invalid status changes are rejected without mutation. If the title is renamed while delayed title generation is in flight, the late result is skipped, the renamed title persists, and diagnostics record the skip reason without prompt or title text.
    func test_task_prompt_draft_persists_after_back() throws {
        codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-title-success-wait").path
        launchApp(defaultParent: fixture.parent.path)
        openNewTaskConversation()
        chooseRepositorySuggestion("primary")
        let composer = element("message-composer")
        XCTAssertTrue(composer.waitForExistence(timeout: 10), "Task creation should open its conversation immediately.")
        XCTAssertFalse(element("save-task-prompt-button").exists, "Drafts should save automatically without a separate Save button.")
        let initialTask = try XCTUnwrap(tasksFromBoardList().first)
        let selectedRepository = try XCTUnwrap((initialTask["repositoryWorktrees"] as? [[String: Any]])?.first?["repositoryPath"] as? String)
        XCTAssertEqual(selectedRepository, fixture.primary.path)
        let initialBranch = try XCTUnwrap((initialTask["repositoryWorktrees"] as? [[String: Any]])?.first?["branch"] as? String)
        XCTAssertEqual(initialBranch, "auto")
        XCTAssertEqual((initialTask["repositoryWorktrees"] as? [[String: Any]])?.first?["isPending"] as? Bool, true)
        XCTAssertEqual((initialTask["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String, fixture.primary.path)
        let prompt = "Please update the README and explain the change."
        composer.click()
        composer.typeText(prompt)
        let taskID = try XCTUnwrap(initialTask["id"] as? String)
        XCTAssertTrue(waitUntil({
            ((try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) ?? nil) == prompt
        }, timeout: 10), "The draft should persist while it is being typed.")
        composer.typeKey("a", modifierFlags: .command)
        composer.typeKey(.delete, modifierFlags: [])
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) == nil
        }, timeout: 10), "Clearing the composer should clear the persisted draft.")
        composer.typeText(prompt)
        XCTAssertTrue(waitUntil({
            ((try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) ?? nil) == prompt
        }, timeout: 10), "Typing again should autosave the replacement draft.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        let titleGenerationReady = URL(fileURLWithPath: codexFixtureExecutable! + ".resolve-ready")
        let titleGenerationContinue = URL(fileURLWithPath: codexFixtureExecutable! + ".resolve-continue")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: titleGenerationReady.path) }, timeout: 10), "The real app-server fixture should confirm that title generation is in flight.")
        let tasks = try tasksFromBoardList()
        let task = try XCTUnwrap(tasks.first)
        XCTAssertEqual(task["id"] as? String, taskID)
        let response = try runCLI(["task", "get", taskID])["result"] as? [String: Any]
        XCTAssertEqual(response?["savedPrompt"] as? String, prompt)
        XCTAssertEqual(response?["status"] as? String, "Backlog")
        let invalid = try runCLI(["task", "prompt", taskID, "--text", "Changed", "--status", "Not a status"], expectedStatus: 2)
        XCTAssertEqual((invalid["error"] as? [String: Any])?["code"] as? String, "invalid_argument")
        let doneTransition = try runCLI(["task", "prompt", taskID, "--text", "Changed", "--status", "Done"], expectedStatus: 2)
        XCTAssertEqual((doneTransition["error"] as? [String: Any])?["code"] as? String, "invalid_argument")
        let unchanged = try runCLI(["task", "get", taskID])["result"] as? [String: Any]
        XCTAssertEqual(unchanged?["savedPrompt"] as? String, prompt)
        XCTAssertEqual(unchanged?["status"] as? String, "Backlog")

        _ = try runCLI(["task", "rename", taskID, "--title", "Stable draft title"])
        try Data("continue\n".utf8).write(to: titleGenerationContinue)
        XCTAssertTrue(waitUntil({ !FileManager.default.fileExists(atPath: titleGenerationReady.path) }, timeout: 10), "The fixture should finish the delayed title turn.")
        XCTAssertTrue(waitUntil({
            ((try? self.taskRecord(id: taskID)?["title"] as? String) ?? nil) == "Stable draft title"
        }, timeout: 10), "A late title response must not overwrite a title that was renamed while generation was pending.")
        XCTAssertTrue(waitUntil({
            (try? self.diagnosticEvents().contains { $0["taskID"] as? String == taskID && $0["event"] as? String == "task.title_apply.skipped" }) == true
        }, timeout: 10), "The late result should be logged as skipped after the user renames the task.")
        let titleEvents = try diagnosticEvents().filter { $0["taskID"] as? String == taskID }
        let skippedTitle = try XCTUnwrap(titleEvents.first { $0["event"] as? String == "task.title_apply.skipped" })
        XCTAssertEqual(skippedTitle["reason"] as? String, "title_changed")
        XCTAssertEqual(skippedTitle["currentTitleState"] as? String, "custom")
        XCTAssertEqual(skippedTitle["titleSource"] as? String, "codex")
        let serializedTitleEvents = String(data: try JSONSerialization.data(withJSONObject: titleEvents), encoding: .utf8) ?? ""
        XCTAssertFalse(serializedTitleEvents.contains(prompt), "Title diagnostics must not include conversation text.")
        XCTAssertFalse(serializedTitleEvents.contains("Stable draft title"), "Title diagnostics must not include a user-renamed title.")
        openTask(named: "Stable draft title")
        XCTAssertEqual(composer.value as? String, prompt, "Reopening should restore an unsent draft.")
        element("back-to-board-button").click()
        let stableTitle = try runCLI(["task", "get", taskID])["result"] as? [String: Any]
        XCTAssertEqual(stableTitle?["title"] as? String, "Stable draft title", "Returning with the saved draft should not restart title generation.")
        attachScreenshot(named: "Unsent task prompt is saved after returning to backlog")
    }

    // case-contract: test_composer_draft_autosaves_during_active_turn | Composer text typed while the agent responds is autosaved as an unsent draft together with its attached image, without ending the turn's submitted prompt or changing its status, and malformed draft images fail validation without changing the draft. A follow-up queued from elsewhere and dispatched after the turn does not replace the draft, which stays saved after the turn ends and is restored to the composer with its image after navigating away and after an app restart. Text steered or queued from the composer leaves the saved draft and does not reappear after the turn, and sending the draft clears it, its images leaving once the turn starts. A submitted prompt whose turn never started returns to the composer with its images, together with the draft typed after it.
    func test_composer_draft_autosaves_during_active_turn() throws {
        let sharedFixture = WorkspaceFixture.root.appendingPathComponent("codex-fixture-draft-serial-success-wait")
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: sharedFixture.path), "The draft active-turn fixture should be prepared as an executable by the UI runner.")
        for suffix in ["resolve-ready", "resolve-continue", "serial-first-turn", "serial-second-turn-started", "history", "reject-next-steer"] {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: sharedFixture.path + ".\(suffix)"))
        }
        codexFixtureExecutable = sharedFixture.path
        launchApp(defaultParent: fixture.parent.path)
        let title = "Draft beside an active turn"
        try createTaskFixture(title: title, roots: [fixture.primary.path])
        let taskID = try taskID(named: title)
        openTask(named: title)
        XCTAssertTrue(modelPrompt().waitForExistence(timeout: 15), "Conversation history should finish loading before the composer is used.")
        let composer = app.textViews.matching(identifier: "message-composer").firstMatch
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 15))
        let firstPrompt = "Start the turn the draft is typed beside."
        let steeredText = "Steer this into the running turn."
        let queuedText = "Queue this follow-up for after the turn."
        let typedDraft = "Typed while the agent responds; keep me after the turn."
        composer.click()
        composer.typeKey("a", modifierFlags: .command)
        composer.typeKey(.delete, modifierFlags: [])
        composer.typeText(firstPrompt)
        element("send-message-button").click()
        let ready = URL(fileURLWithPath: sharedFixture.path + ".resolve-ready")
        let release = URL(fileURLWithPath: sharedFixture.path + ".resolve-continue")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: ready.path) }, timeout: 15), "The fixture should hold the turn active while the draft is typed.")
        defer { try? Data("release\n".utf8).write(to: release) }

        // Steered and queued text leaves the composer and the saved draft at once.
        composer.click()
        composer.typeText(steeredText)
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) ?? nil) == steeredText }, timeout: 10), "Text typed during a turn should autosave.")
        composer.typeKey(.return, modifierFlags: .command)
        XCTAssertTrue(transcriptMessage(steeredText).waitForExistence(timeout: 10), "Command-Return should steer the running turn.")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "" }, timeout: 10))
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) == nil }, timeout: 10), "A steered draft should leave the saved draft.")
        composer.typeText(queuedText)
        composer.typeKey(.return, modifierFlags: [])
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "" }, timeout: 10), "Return should queue the follow-up and clear the composer.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) == nil }, timeout: 10), "A queued draft should leave the saved draft.")

        let bitmap = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: 1, pixelsHigh: 1, bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)!
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setData(try XCTUnwrap(bitmap.representation(using: .png, properties: [:])), forType: .png)
        composer.typeText(typedDraft)
        composer.typeKey("v", modifierFlags: .command)
        XCTAssertTrue(element("pending-chat-images").waitForExistence(timeout: 5))
        XCTAssertTrue(waitUntil({
            guard let record = try? self.taskRecord(id: taskID) else { return false }
            return record["savedPrompt"] as? String == typedDraft
                && record["hasUnsentDraft"] as? Bool == true
                && (record["draftImageDataURLs"] as? [String])?.count == 1
        }, timeout: 10), "Text and image typed while the agent responds should autosave together.")
        let running = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(running["status"] as? String, "In Progress", "Autosaving a draft must not change the running task's status.")
        XCTAssertEqual(running["pendingSubmittedPrompt"] as? String, firstPrompt, "Autosaving a draft must not end the turn's submitted prompt.")
        let invalidImage = dataDirectory.appendingPathComponent("invalid-draft.png")
        try Data("not an image".utf8).write(to: invalidImage)
        assertCLIError(try runCLI(["task", "draft", taskID, "--text", "Bad image", "--image", invalidImage.path], expectedStatus: 2), code: "invalid_argument")
        let validImage = dataDirectory.appendingPathComponent("valid-draft.png")
        try XCTUnwrap(bitmap.representation(using: .png, properties: [:])).write(to: validImage)
        let excessImages = Array(repeating: ["--image", validImage.path], count: 9).flatMap { $0 }
        assertCLIError(try runCLI(["task", "draft", taskID, "--text", "Too many images"] + excessImages, expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try taskRecord(id: taskID)?["savedPrompt"] as? String, typedDraft, "A rejected draft must leave the saved draft unchanged.")
        attachScreenshot(named: "Draft and image typed while the agent responds")

        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: title)
        XCTAssertTrue(waitUntil({ (composer.value as? String) == typedDraft }, timeout: 10), "Reopening during the turn should restore the draft typed beside it.")
        XCTAssertTrue(element("pending-chat-images").waitForExistence(timeout: 5), "Reopening during the turn should restore the draft image.")
        // Leaving right after typing, before the autosave delay, must still save the text.
        let fullDraft = typedDraft + " Added just before leaving."
        composer.click()
        composer.typeKey(.downArrow, modifierFlags: .command)
        composer.typeText(" Added just before leaving.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: taskID)?["savedPrompt"] as? String) ?? nil) == fullDraft }, timeout: 10), "Going back mid-turn should save text typed just before leaving.")
        openTask(named: title)
        XCTAssertTrue(waitUntil({ (composer.value as? String) == fullDraft }, timeout: 10), "Reopening should restore text typed just before leaving.")

        // The turn ends and the queued follow-up dispatches while the task is closed.
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        try Data("release\n".utf8).write(to: release)
        XCTAssertTrue(waitUntil({
            guard let record = try? self.taskRecord(id: taskID) else { return false }
            let queue = (try? self.runCLI(["conversation", "queue-list", taskID])["result"] as? [[String: Any]]) ?? nil
            return record["status"] as? String != "In Progress" && record["pendingSubmittedPrompt"] == nil && queue?.isEmpty == true
        }, timeout: 30), "The turn and its queued follow-up should finish.")
        let settled = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(settled["savedPrompt"] as? String, fullDraft, "A dispatched follow-up must not replace the unsent draft.")
        XCTAssertEqual((settled["draftImageDataURLs"] as? [String])?.count, 1)
        openTask(named: title)
        XCTAssertTrue(transcriptMessage(queuedText).waitForExistence(timeout: 15), "The queued follow-up should have run as its own turn.")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == fullDraft }, timeout: 10), "Reopening after the turn must restore the draft, not an empty or steered one.")
        XCTAssertTrue(element("pending-chat-images").exists, "Reopening after the turn should restore the draft image.")
        attachScreenshot(named: "Draft restored after the turn ends")

        app.terminate()
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: title)
        XCTAssertTrue(waitUntil({ (composer.value as? String) == fullDraft }, timeout: 15), "The draft typed during the turn should survive an app restart.")
        XCTAssertTrue(element("pending-chat-images").waitForExistence(timeout: 5), "The draft image should survive an app restart.")
        attachScreenshot(named: "Draft restored after restarting the app")

        XCTAssertTrue(waitUntil({ self.element("send-message-button").isEnabled }, timeout: 10))
        element("send-message-button").click()
        XCTAssertTrue(transcriptMessage(fullDraft).waitForExistence(timeout: 15), "Sending should deliver the restored draft.")
        XCTAssertTrue(waitUntil({
            guard let record = try? self.taskRecord(id: taskID) else { return false }
            return record["hasUnsentDraft"] as? Bool == false && (record["draftImageDataURLs"] as? [String])?.isEmpty == true
        }, timeout: 15), "Sending the draft should clear the saved draft.")
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: taskID)?["status"] as? String) ?? nil) != "In Progress" }, timeout: 30))
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: title)
        XCTAssertTrue(transcriptMessage(fullDraft).waitForExistence(timeout: 15))
        XCTAssertEqual(composer.value as? String, "", "A sent draft must not return to the composer.")
        XCTAssertFalse(element("pending-chat-images").exists, "A sent draft image must not return to the composer.")
        attachScreenshot(named: "Sent draft leaves the composer empty")

        // An image-only send leaves the composer and the saved draft too.
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setData(try XCTUnwrap(bitmap.representation(using: .png, properties: [:])), forType: .png)
        composer.click()
        composer.typeKey("v", modifierFlags: .command)
        XCTAssertTrue(element("pending-chat-images").waitForExistence(timeout: 5))
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: taskID)?["draftImageDataURLs"] as? [String]) ?? nil)?.count == 1 }, timeout: 10), "An attached image should autosave.")
        XCTAssertTrue(waitUntil({ self.element("send-message-button").isEnabled }, timeout: 10))
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({
            guard let record = try? self.taskRecord(id: taskID) else { return false }
            return record["hasUnsentDraft"] as? Bool == false && (record["draftImageDataURLs"] as? [String])?.isEmpty == true
                && record["status"] as? String != "In Progress"
        }, timeout: 30), "An image-only send should clear its image from the saved draft.")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: title)
        // The reopened transcript pins the latest turn, the image-only send.
        let transcriptImages = app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH %@", "chat-image-"))
        XCTAssertTrue(transcriptImages.firstMatch.waitForExistence(timeout: 15), "The image-only send should appear in the transcript.")
        XCTAssertEqual(composer.value as? String, "")
        XCTAssertFalse(element("pending-chat-images").exists, "A sent image-only draft must not return to the composer.")

        let neverStarted = "Draft beside a turn that never started"
        try createTaskFixture(title: neverStarted, roots: [fixture.primary.path])
        let neverStartedID = try self.taskID(named: neverStarted)
        let submitted = "Submitted before Playhouse restarted."
        let laterDraft = "Typed after sending, before the restart."
        _ = try runCLI(["task", "prompt", neverStartedID, "--text", submitted, "--status", "In Progress", "--submitted", "true"])
        _ = try runCLI(["task", "draft", neverStartedID, "--text", laterDraft])
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: neverStarted)
        XCTAssertTrue(waitUntil({ (composer.value as? String) == submitted + "\n\n" + laterDraft }, timeout: 15), "A prompt whose turn never started should return to the composer with the draft typed after it.")
        XCTAssertEqual(try taskRecord(id: neverStartedID)?["status"] as? String, "Waiting Response")
        attachScreenshot(named: "Never-started prompt returns with the later draft")

        let neverStartedImage = "Image prompt whose turn never started"
        try createTaskFixture(title: neverStartedImage, roots: [fixture.primary.path])
        let neverStartedImageID = try self.taskID(named: neverStartedImage)
        _ = try runCLI(["task", "prompt", neverStartedImageID, "--text", submitted, "--image", validImage.path, "--status", "In Progress", "--submitted", "true"])
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: neverStartedImage)
        XCTAssertTrue(waitUntil({ (composer.value as? String) == submitted }, timeout: 15), "A never-started prompt should return to the composer.")
        XCTAssertTrue(element("pending-chat-images").waitForExistence(timeout: 5), "A never-started prompt should return with its image.")
        attachScreenshot(named: "Never-started prompt returns with its image")
    }

    // case-contract: test_conversation_composer_rejects_blank_and_supports_live_turn_controls | Shift+Enter inserts a newline at the caret without sending and Return submits; multiline drafts persist, expand to the editor limit, remain scrollable and editable across reopening, and submitted prompts persist in history. As content is typed in short increments through successive wrapped lines after a line break, the newest insertion remains inside the visible composer viewport while its internal document follows the caret without scrolling backward. Typed straight quotes, apostrophes, and double hyphens stay literal rather than being substituted. Blank drafts cannot be sent or stored. Sending requires a configured repository root, while a task with no selected repository can still be sent as standalone. If a submitted prompt has no Codex thread or active send reservation after restart, the task returns to Waiting Response, clears its pending marker, preserves the draft, and returns it to the composer. Sending to an Untitled auto-branch task derives its branch from the generated title or prompt fallback before preparing the worktree and starting the conversation; if it is concurrently renamed while title generation is pending, the custom title determines the auto branch. A standalone Untitled task starts and persists its provider thread while background title generation is still pending. Pause remains disabled until the turn is interruptible. Diagnostics correlate title generation with the task and thread while excluding prompt and title text. Queued follow-ups persist with task and thread identity, dispatch after a completed turn, and remain visible for explicit retry after interruption. During an active turn, Return queues a follow-up and queued rows offer Steer. The obsolete footer Queue and Steer buttons are absent.
    func test_conversation_composer_rejects_blank_and_supports_live_turn_controls() throws {
        executionTimeAllowance = 360 // This long case covers several restarts and title-generation flows.
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Blank message", roots: [fixture.primary.path])
        let longDraftTaskID = try taskID(named: "Blank message")
        let longDraft = "# Inspect subagents\n" + String(repeating: "Review child activity and preserve the complete result.\n", count: 160)
        _ = try runCLI(["task", "prompt", longDraftTaskID, "--text", longDraft])
        app.terminate()
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Blank message")
        let draftEditor = element("message-composer")
        let editorViewport = element("message-composer-scroll-view")
        XCTAssertTrue(draftEditor.waitForExistence(timeout: 5))
        XCTAssertEqual(draftEditor.elementType, .textView, "The composer should use a native multiline text area.")
        XCTAssertEqual(draftEditor.value as? String, longDraft)
        XCTAssertTrue(waitUntil({ editorViewport.frame.height >= 205 }, timeout: 5), "Opening a saved long draft must expand to the 12-line viewport immediately, before typing.")
        XCTAssertLessThanOrEqual(editorViewport.frame.height, 216, "A long draft must not expand the editor beyond its 12-line viewport cap.")
        attachScreenshot(named: "Long saved draft expands the native composer")
        let draftTopPosition = draftEditor.frame.minY
        editorViewport.swipeUp()
        XCTAssertTrue(editorViewport.scrollBars.firstMatch.waitForExistence(timeout: 5), "Scrolling overflow must expose the composer's own native scrollbar.")
        XCTAssertTrue(waitUntil({ draftEditor.frame.minY < draftTopPosition - 20 }, timeout: 5), "Scrolling down must reveal later draft content.")
        let draftLowerPosition = draftEditor.frame.minY
        editorViewport.swipeDown()
        XCTAssertTrue(waitUntil({ draftEditor.frame.minY > draftLowerPosition + 20 }, timeout: 5), "Scrolling up must reveal earlier draft content.")
        draftEditor.click()
        draftEditor.typeKey(.downArrow, modifierFlags: .command)
        draftEditor.typeText("Edited after reopening.")
        let editedDraft = longDraft + "Edited after reopening."
        XCTAssertTrue(waitUntil({ draftEditor.value as? String == editedDraft }, timeout: 5), "The reopened long draft must respond to editing.")
        let documentTopBeforeLineBreak = draftEditor.frame.minY
        draftEditor.typeKey(.return, modifierFlags: .shift)
        var typedAfterLineBreak = ""
        var previousDocumentTop = documentTopBeforeLineBreak
        // No trailing space: autosave trims the draft, as it does to tell a blank draft apart.
        let wrapText = String(repeating: "First characters stay visible across wrapped lines. ", count: 3).trimmingCharacters(in: .whitespaces)
        let wrapChunks = stride(from: 0, to: wrapText.count, by: 2).map { String(wrapText.dropFirst($0).prefix(2)) }
        for chunk in wrapChunks {
            draftEditor.typeText(chunk)
            typedAfterLineBreak += chunk
            XCTAssertTrue(waitUntil({ (draftEditor.value as? String ?? "").hasSuffix(typedAfterLineBreak) }, timeout: 5), "Each increment after a line break must remain present in the composer.")
            let currentDocumentTop = draftEditor.frame.minY
            XCTAssertLessThanOrEqual(currentDocumentTop, previousDocumentTop + 2, "Typing through successive wrapped lines must not scroll the document back and hide the newest characters.")
            let insertionPointY = draftEditor.frame.maxY - 5
            XCTAssertGreaterThanOrEqual(insertionPointY, editorViewport.frame.minY, "The newest insertion must remain below the visible viewport’s top edge at every wrap checkpoint.")
            XCTAssertLessThanOrEqual(insertionPointY, editorViewport.frame.maxY + 2, "The newest insertion must remain inside the visible viewport at every wrap checkpoint.")
            previousDocumentTop = currentDocumentTop
        }
        XCTAssertLessThan(previousDocumentTop, documentTopBeforeLineBreak - 20, "The composer’s internal document must follow the caret as wrapped content grows.")
        let lineBreakDraft = editedDraft + "\n" + typedAfterLineBreak
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: longDraftTaskID)?["savedPrompt"] as? String) == lineBreakDraft }, timeout: 10))
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5), "Back must remain responsive after editing a long draft.")
        app.terminate()
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Blank message")
        XCTAssertEqual(draftEditor.value as? String, lineBreakDraft)
        XCTAssertTrue(waitUntil({ editorViewport.frame.height >= 205 }, timeout: 5), "The editor must also expand to its 12-line viewport after restarting with a saved draft.")
        draftEditor.click()
        draftEditor.typeKey("a", modifierFlags: .command)
        draftEditor.typeText("Short")
        let shortenedEditor = waitUntil({ editorViewport.frame.height < 60 }, timeout: 5)
        if !shortenedEditor {
            attachScreenshot(named: "Composer after shortening a saved long draft")
        }
        XCTAssertTrue(shortenedEditor, "Shortening the draft should shrink the editor; viewport=\(editorViewport.frame), document=\(draftEditor.frame), text=\(draftEditor.value ?? "")")
        let shortHeight = editorViewport.frame.height
        draftEditor.typeKey("a", modifierFlags: .command)
        // Pasted rather than typed: typing 960 characters takes most of the case's time budget.
        pasteText(String(repeating: "Wrapped text without a newline. ", count: 30), into: draftEditor)
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > shortHeight + 20 }, timeout: 5), "Wrapping must grow the editor without explicit newlines.")
        draftEditor.typeKey("a", modifierFlags: .command)
        draftEditor.typeKey(.delete, modifierFlags: [])
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: longDraftTaskID)?["savedPrompt"] as? String) == nil }, timeout: 10))
        let composer = element("message-composer")
        let sendButton = element("send-message-button")
        let modelPicker = element("model-picker-menu")
        XCTAssertTrue(composer.waitForExistence(timeout: 10))
        XCTAssertTrue(modelPicker.waitForExistence(timeout: 10), "The composer should show the selected model next to its send controls.")
        let modelTaskID = try taskID(named: "Blank message")
        let modelResult = try runCLI(["conversation", "models", modelTaskID])["result"] as? [String: Any]
        let availableModels = try XCTUnwrap(modelResult?["models"] as? [[String: Any]])
        let modelLabel = modelPicker.value as? String ?? modelPicker.label
        let selectedModelValue = modelLabel.components(separatedBy: ", effort:").first?
            .replacingOccurrences(of: "Model: ", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? modelLabel
        XCTAssertTrue(availableModels.contains(where: {
            selectedModelValue.caseInsensitiveCompare($0["name"] as? String ?? "") == .orderedSame
                || selectedModelValue.caseInsensitiveCompare($0["id"] as? String ?? "") == .orderedSame
        }), "The selected composer model '\(selectedModelValue)' should match an available Codex model: \(availableModels).")
        XCTAssertFalse(sendButton.isEnabled)
        composer.click()
        // Typed punctuation must reach the draft literally: smart quotes or an em dash would
        // change the prompt the provider receives. This detects substitution only while the
        // VM's "Use smart quotes and dashes" preference is on, as it is on a fresh macOS image.
        let literalPunctuation = "Use \"straight\" quotes -- it's literal"
        composer.typeText(literalPunctuation)
        XCTAssertEqual(composer.value as? String, literalPunctuation, "The composer must not substitute smart quotes or dashes for typed punctuation.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: longDraftTaskID)?["savedPrompt"] as? String) == literalPunctuation }, timeout: 10),
                      "The saved draft must keep the typed punctuation literal.")
        composer.typeKey("a", modifierFlags: .command)
        composer.typeKey(.delete, modifierFlags: [])
        XCTAssertTrue(waitUntil({ (composer.value as? String ?? "").isEmpty }, timeout: 5))
        composer.typeText("First line")
        composer.typeKey(.return, modifierFlags: .shift)
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > shortHeight }, timeout: 5), "The composer should reserve the empty caret line immediately after a trailing newline.")
        XCTAssertEqual(composer.value as? String, "First line\n", "The trailing newline should remain in the editor before text is entered on the next line.")
        composer.typeText("Second line")
        XCTAssertEqual(composer.value as? String, "First line\nSecond line", "Shift+Enter should add a line without submitting the composer.")
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > shortHeight }, timeout: 5))
        let twoLineHeight = editorViewport.frame.height
        for index in 3...5 {
            composer.typeKey(.return, modifierFlags: .shift)
            composer.typeText("Line \(index)")
        }
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > twoLineHeight }, timeout: 5))
        let fiveLineHeight = editorViewport.frame.height
        for index in 6...9 {
            composer.typeKey(.return, modifierFlags: .shift)
            composer.typeText("Line \(index)")
        }
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > twoLineHeight }, timeout: 5), "The visible composer should grow as a draft gains lines.")
        XCTAssertTrue(waitUntil({ editorViewport.frame.height > fiveLineHeight }, timeout: 5), "The visible composer should expand beyond the previous five-line limit.")
        for index in 10...12 {
            composer.typeKey(.return, modifierFlags: .shift)
            composer.typeText("Line \(index)")
        }
        let twelveLineHeight = editorViewport.frame.height
        for index in 13...15 {
            composer.typeKey(.return, modifierFlags: .shift)
            composer.typeText("Line \(index)")
        }
        let expectedLongDraft = (["First line", "Second line"] + (3...15).map { "Line \($0)" }).joined(separator: "\n")
        XCTAssertLessThanOrEqual(editorViewport.frame.height, twelveLineHeight + 2, "The composer should stop growing at its 12-line limit and scroll the remaining draft.")
        XCTAssertEqual(composer.value as? String, expectedLongDraft, "The composer should retain all lines after reaching its scroll limit.")
        XCTAssertTrue(element("conversation-scroll-view").exists, "The transcript should expose its scroll view for reading the full conversation.")
        XCTAssertTrue(sendButton.isEnabled)
        XCTAssertEqual(((try runCLI(["conversation", "history", taskID(named: "Blank message")])["result"] as? [String: Any])?["messages"] as? [Any])?.count, 0, "Adding a line must not send a conversation message.")
        composer.typeKey("a", modifierFlags: .command)
        composer.typeText("BeforeAfter")
        composer.typeKey(.leftArrow, modifierFlags: .command)
        for _ in 0..<6 { composer.typeKey(.rightArrow, modifierFlags: []) }
        composer.typeKey(.return, modifierFlags: .shift)
        XCTAssertEqual(composer.value as? String, "Before\nAfter", "Shift+Return must insert at the caret, not append to the draft.")
        XCTAssertEqual(((try runCLI(["conversation", "history", modelTaskID])["result"] as? [String: Any])?["messages"] as? [Any])?.count, 0)
        composer.typeKey("a", modifierFlags: .command)
        composer.typeText("   ")
        XCTAssertFalse(sendButton.isEnabled, "Whitespace-only messages must not be sent.")

        let taskID = try taskID(named: "Blank message")
        assertCLIError(
            try runCLI(["task", "prompt", taskID, "--text", "Invalid submitted prompt", "--submitted", "true"], expectedStatus: 2),
            code: "invalid_argument"
        )
        assertCLIError(
            try runCLI(["task", "prompt", taskID, "--text", " ", "--status", "In Progress", "--submitted", "true"], expectedStatus: 2),
            code: "invalid_argument"
        )
        assertCLIError(
            try runCLI(["conversation", "send", taskID, "--message", " "], expectedStatus: 2),
            code: "invalid_argument"
        )
        let history = try runCLI(["conversation", "history", taskID])["result"] as? [String: Any]
        XCTAssertEqual((history?["activities"] as? [Any])?.count, 0)
        XCTAssertEqual((history?["messages"] as? [Any])?.count, 0)
        if !isLiveIntegration {
            app.terminate()
            codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-title-success-wait").path
            let titleFixtureExecutable = try XCTUnwrap(codexFixtureExecutable)
            launchApp(defaultParent: fixture.parent.path)
            let titleTask = try XCTUnwrap(
                (try runCLI(["task", "create", "--title", "Untitled task", "--prompt", "Fixture task description.", "--repo", fixture.primary.path])["result"] as? [String: Any])
            )
            let titleTaskID = try XCTUnwrap(titleTask["id"] as? String)
            XCTAssertEqual(try repositoryRecord(taskID: titleTaskID, repositoryPath: fixture.primary.path)?["branch"] as? String, "auto")
            XCTAssertEqual(try repositoryRecord(taskID: titleTaskID, repositoryPath: fixture.primary.path)?["isPending"] as? Bool, true)
            openTask(named: "Untitled task")
            let titleComposer = element("message-composer")
            XCTAssertTrue(titleComposer.waitForExistence(timeout: 10))
            let titlePrompt = "Transcript entry " + String(repeating: "Readable chat content for scrolling. ", count: 40)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            titleComposer.click()
            pasteText(titlePrompt, into: titleComposer) // Typing 1,500 characters exceeds the case budget.
            titleComposer.typeKey(.return, modifierFlags: [])
            let titleFixtureReady = URL(fileURLWithPath: titleFixtureExecutable + ".resolve-ready")
            XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: titleFixtureReady.path) }, timeout: 15), "The title fixture should hold the task in its title-pending state.")
            XCTAssertEqual(try taskRecord(id: titleTaskID)?["title"] as? String, "Generating title…")
            XCTAssertEqual(try taskRecord(id: titleTaskID)?["savedPrompt"] as? String, titlePrompt)
            XCTAssertEqual(try taskRecord(id: titleTaskID)?["pendingSubmittedPrompt"] as? String, titlePrompt)
            let backButton = element("back-to-board-button")
            XCTAssertTrue(waitUntil({ backButton.isEnabled }, timeout: 5), "Back should become available after the submitted prompt and title placeholder are persisted.")
            backButton.click()
            let titleTaskCard = element("task-card-\(titleTaskID.uppercased())")
            XCTAssertTrue(titleTaskCard.waitForExistence(timeout: 10))
            XCTAssertEqual(try taskRecord(id: titleTaskID)?["title"] as? String, "Generating title…", "The board should retain the title placeholder while title generation is pending.")
            clickTaskCardTitle(titleTaskCard)
            XCTAssertTrue(waitUntil({
                element("task-view-title").exists || element("task-title-generating").exists
            }, timeout: 10), "The active title-pending task should reopen from the board. UI: \(app.debugDescription)")
            XCTAssertEqual(element("message-composer").value as? String, "", "A submitted prompt must not reappear as a draft after returning during title generation.")
            let submittedPromptMessage = app.groups.matching(NSPredicate(format: "identifier BEGINSWITH %@", "user-message-")).firstMatch
            XCTAssertTrue(submittedPromptMessage.waitForExistence(timeout: 5), "The submitted prompt should remain visible as a conversation message after reopening.")
            XCTAssertTrue(element("pause-response-button").exists, "The reopened task should retain its active-send controls while the Codex thread is being prepared.")
            XCTAssertFalse(element("pause-response-button").isEnabled, "Pause must stay disabled until this task has an interruptible Codex turn.")
            XCTAssertFalse(element("send-message-button").exists, "A second message must not be sent while the submitted prompt is still active.")
            try Data("continue\n".utf8).write(to: URL(fileURLWithPath: titleFixtureExecutable + ".resolve-continue"))
            XCTAssertTrue(waitUntil({
                ((try? self.taskRecord(id: titleTaskID)?["title"] as? String) ?? nil) == "Generated fixture title"
            }, timeout: 20), "Sending a prompt from an empty task should persist the Codex-generated title.")
            XCTAssertTrue(waitUntil({
                guard let repository = try? self.repositoryRecord(taskID: titleTaskID, repositoryPath: self.fixture.primary.path) else { return false }
                return (repository["branch"] as? String)?.hasPrefix("generated-fixture-title") == true && repository["isPending"] as? Bool == false
            }, timeout: 20), "The auto worktree should use the generated task title.")
            let generatedTitleBranch = try XCTUnwrap(repositoryRecord(taskID: titleTaskID, repositoryPath: fixture.primary.path)?["branch"] as? String)
            try runGit(fixture.primary, "show-ref", "--verify", "--quiet", "refs/heads/\(generatedTitleBranch)")
            XCTAssertTrue(waitUntil({
                (try? self.diagnosticEvents().contains { $0["taskID"] as? String == titleTaskID && $0["event"] as? String == "task.title_apply.succeeded" }) == true
            }, timeout: 10), "The generated title application should be logged.")
            XCTAssertEqual(try taskRecord(id: titleTaskID)?["savedPrompt"] as? String, titlePrompt)
            let titleEvents = try diagnosticEvents().filter { $0["taskID"] as? String == titleTaskID }
            let generationStarted = try XCTUnwrap(titleEvents.first { $0["event"] as? String == "task.title_generation.started" })
            let generationSucceeded = try XCTUnwrap(titleEvents.first { $0["event"] as? String == "task.title_generation.succeeded" })
            let titleApplied = try XCTUnwrap(titleEvents.first { $0["event"] as? String == "task.title_apply.succeeded" })
            XCTAssertEqual(generationStarted["threadID"] as? String, generationSucceeded["threadID"] as? String)
            XCTAssertTrue((generationStarted["threadID"] as? String)?.isEmpty == false)
            XCTAssertTrue((generationSucceeded["threadID"] as? String)?.isEmpty == false)
            XCTAssertEqual(titleApplied["titleSource"] as? String, "codex")
            let serializedTitleEvents = String(data: try JSONSerialization.data(withJSONObject: titleEvents), encoding: .utf8) ?? ""
            XCTAssertFalse(serializedTitleEvents.contains(titlePrompt), "Title diagnostics must not include conversation text.")
            XCTAssertFalse(serializedTitleEvents.contains("Generated fixture title"), "Title diagnostics must not include generated title text.")
            let transcriptScrollView = element("conversation-scroll-view")
            let longPromptMessage = app.textViews.matching(
