    // case-contract: test_claude_outcome_reminder_rejects_user_questions | A successful Claude turn with an unanswered AskUserQuestion stays In Progress without outcome nudges; after the user answers, the next successful turn receives a hidden CLI status nudge. A question raised during that nudge is rejected through Claude's control protocol with completed, in-progress, and waiting-response instructions, which fails the private turn; both the question and the private rejection instructions stay out of the transcript. Playhouse then stops driving the work and marks the task Blocked naming that reason, rather than spending the remaining nudges.

    func test_claude_outcome_reminder_rejects_user_questions() throws {
        let executable = dataDirectory.appendingPathComponent("claude-fixture-outcome-reminder-question")
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try "Playhouse test owns this Claude Code protocol fixture (v1).\n".write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner"),
            atomically: true,
            encoding: .utf8
        )
        claudeFixtureExecutable = executable.path
        let created = try XCTUnwrap(try runCLI([
            "task", "create", "--title", "Claude reminder question", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude"
        ])["result"] as? [String: Any])
        let taskID = try XCTUnwrap(created["id"] as? String)
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Claude reminder question")
        element("message-composer").click()
        element("message-composer").typeText("Finish while a structured question remains pending.")
        element("send-message-button").click()
        XCTAssertTrue(element("conversation-user-input-request").waitForExistence(timeout: 10))
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "In Progress")
        let pendingHistory = try runCLI(["conversation", "history", taskID])
        XCTAssertNotNil((pendingHistory["result"] as? [String: Any])?["pendingUserInputRequest"])
        let pendingFixtureHistory = try Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))
        let pendingTurns = try XCTUnwrap((try JSONSerialization.jsonObject(with: pendingFixtureHistory) as? [String: Any])?["turns"] as? [[String: Any]])
        XCTAssertEqual(pendingTurns.count, 1)
        XCTAssertFalse(pendingTurns.contains { ($0["userText"] as? String)?.contains("Playhouse internal outcome nudge:") == true }, "A successful turn with a pending question must not receive outcome nudges.")
        element("ai-question-option-question-1-Blue").click()
        element("submit-ai-answers-button").click()
        // The answered turn already finished, so the answer may arrive as a recovery turn.
        XCTAssertTrue(waitUntil({
            self.transcriptMessage("Answer received: Blue.").exists || self.transcriptMessage("Recovered answer: Blue.").exists
        }, timeout: 10))
        XCTAssertTrue(waitUntil({ !element("conversation-user-input-request").exists }, timeout: 5))
        element("message-composer").click()
        element("message-composer").typeText("Continue after answering.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Blocked" }, timeout: 60), "A failed private nudge should stop Playhouse driving and settle the task in Blocked.")
        XCTAssertTrue(
            (try taskRecord(id: taskID)?["statusMessage"] as? String)?.contains("couldn't run the private turn") == true,
            "The Blocked reason must name why Playhouse stopped driving the work."
        )

        let fixtureTurnsData = try Data(contentsOf: URL(fileURLWithPath: executable.path + ".history"))
        let fixtureHistory = try XCTUnwrap(try JSONSerialization.jsonObject(with: fixtureTurnsData) as? [String: Any])
        let turns = try XCTUnwrap(fixtureHistory["turns"] as? [[String: Any]])
        let nudges = turns.filter { ($0["userText"] as? String)?.contains("Playhouse internal outcome nudge:") == true }
        XCTAssertEqual(nudges.count, 1, "Rejecting the question fails the private turn, so Playhouse stops driving instead of spending every nudge.")
        XCTAssertTrue(nudges.allSatisfy { ($0["userText"] as? String)?.contains("task outcome command") == true })
        let rejectionText = try String(contentsOfFile: executable.path + ".private-reminder-question-rejection", encoding: .utf8)
        let rejections = rejectionText.split(whereSeparator: \.isNewline)
        XCTAssertEqual(rejections.count, 1)
        XCTAssertTrue(rejections.allSatisfy { $0.contains("completed") && $0.contains("in-progress") && $0.contains("waiting-response") })
        XCTAssertFalse(element("conversation-user-input-request").exists, "Nudge questions must not become visible answer cards.")
        XCTAssertFalse(app.staticTexts["Which color should I use?"].exists)
        XCTAssertFalse(app.descendants(matching: .any).matching(NSPredicate(
            format: "label CONTAINS %@", "This is a private Playhouse status nudge."
        )).firstMatch.exists, "Claude's private rejection instructions must not appear in the visible transcript.")
        XCTAssertFalse(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse internal outcome nudge:")).firstMatch.exists)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Claude reminder question", inColumn: "Blocked")
    }

    // case-contract: test_pending_question_repair_restores_thread_owner | A misplaced pending question can be repaired through CLI/XPC only into its owning conversation. Repair rejects a wrong owner and a conflicting destination without mutation, applies both tasks' state atomically, preserves request identity and mode, clears only the misplaced source, and is retryable. Fresh history and the visible UI restore the question only on the original task; answering it clears pending state and the safe response survives reopening. Retrying an interrupted repair after the destination question was answered rejects the stale source without resurrecting the question.
    func test_pending_question_repair_restores_thread_owner() throws {
        let restartFixture = dataDirectory.appendingPathComponent("codex-fixture-restart-question")
        try FileManager.default.copyItem(at: WorkspaceFixture.root.appendingPathComponent("codex-fixture-restart-question"), to: restartFixture)
        codexFixtureExecutable = restartFixture.path
        try "Playhouse test owns this Codex protocol fixture (v1).\n".write(to: dataDirectory.appendingPathComponent(".playhouse-codex-fixture-owner"), atomically: true, encoding: .utf8)
        let target = try XCTUnwrap((try runCLI(["task", "create", "--title", "Repair original question", "--prompt", "Fixture task description.", "--root", fixture.primary.path])["result"] as? [String: Any])?["id"] as? String)
        let source = try XCTUnwrap((try runCLI(["task", "create", "--title", "Repair misplaced question", "--prompt", "Fixture task description.", "--root", fixture.secondary.path])["result"] as? [String: Any])?["id"] as? String)
        let stranger = try XCTUnwrap((try runCLI(["task", "create", "--title", "Repair wrong destination", "--prompt", "Fixture task description.", "--root", fixture.alternate.path])["result"] as? [String: Any])?["id"] as? String)
        _ = try runCLI(["conversation", "send", target, "--message", "Ask a restart-safe question.", "--mode", "plan"], expectedStatus: 1)
        let strangerFixture = dataDirectory.appendingPathComponent("codex-fixture-title-success")
        try FileManager.default.copyItem(at: restartFixture, to: strangerFixture)
        _ = try runCLI(["conversation", "send", stranger, "--message", "Start another real conversation."], extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": strangerFixture.path])
        var original = try XCTUnwrap(try conversationState(target))
        let request = try XCTUnwrap(original.removeValue(forKey: "pendingUserInputRequest") as? [String: Any])
        try writeConversationState(target, original)
        let displaced: [String: Any] = ["version": 1, "segments": [], "turns": [], "pendingUserInputRequest": request]
        try writeConversationState(source, displaced)
        let originalState = try XCTUnwrap(try conversationState(target)) as NSDictionary
        let misplacedState = try XCTUnwrap(try conversationState(source)) as NSDictionary
        let wrong = try runCLI(["conversation", "repair-user-input", stranger, "--from-task", source], expectedStatus: 1)
        XCTAssertEqual((wrong["error"] as? [String: Any])?["code"] as? String, "invalid_transition")
        XCTAssertEqual(try XCTUnwrap(try conversationState(target)) as NSDictionary, originalState)
        XCTAssertEqual(try XCTUnwrap(try conversationState(source)) as NSDictionary, misplacedState)
        var conflict = request
        conflict["id"] = "a-different-pending-request"
        original["pendingUserInputRequest"] = conflict
        try writeConversationState(target, original)
        let conflictState = try XCTUnwrap(try conversationState(target)) as NSDictionary
        _ = try runCLI(["conversation", "repair-user-input", target, "--from-task", source], expectedStatus: 1)
        XCTAssertEqual(try XCTUnwrap(try conversationState(target)) as NSDictionary, conflictState)
        XCTAssertEqual(try XCTUnwrap(try conversationState(source)) as NSDictionary, misplacedState, "A rejected repair leaves both tasks' state untouched.")
        original.removeValue(forKey: "pendingUserInputRequest")
        try writeConversationState(target, original)
        let repaired = try runCLI(["conversation", "repair-user-input", target, "--from-task", source])
        XCTAssertEqual((repaired["result"] as? [String: Any])?["id"] as? String, request["id"] as? String)
        XCTAssertEqual((repaired["result"] as? [String: Any])?["mode"] as? String, "plan")
        XCTAssertNil(try XCTUnwrap(try conversationState(source))["pendingUserInputRequest"])
        let repairedTarget = try XCTUnwrap(try conversationState(target))
        XCTAssertEqual((repairedTarget["pendingUserInputRequest"] as? [String: Any])?["id"] as? String, request["id"] as? String)
        let receipts = try XCTUnwrap(repairedTarget["userInputRepairs"] as? [[String: Any]])
        XCTAssertEqual(receipts.count, 1, "The destination records a receipt of the repair in the same transaction.")
        XCTAssertEqual(receipts.first?["sourceTaskID"] as? String, source.uppercased())
        XCTAssertFalse(FileManager.default.fileExists(atPath: dataDirectory.appendingPathComponent("conversation-transcripts").path), "Repairs no longer write JSON transcript backups; SQLite applies both tasks atomically.")
        _ = try runCLI(["conversation", "repair-user-input", target, "--from-task", source])
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Repair misplaced question")
        XCTAssertFalse(element("conversation-user-input-request").exists)
        element("back-to-board-button").click()
        openTask(named: "Repair original question")
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        XCTAssertTrue(app.staticTexts["Which color should I use?"].exists)
        element("ai-question-option-color-Green").click()
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        XCTAssertTrue(transcriptMessage("Recovered answer: Green; private token [redacted secret answer] was applied.").waitForExistence(timeout: 15))
        relaunchApp()
        openTask(named: "Repair original question")
        XCTAssertFalse(element("ai-question-form-title").exists)
        XCTAssertTrue(transcriptMessage("[Response to private answer hidden]").waitForExistence(timeout: 10))
        let history = try runCLI(["conversation", "history", target])["result"]
        let historyBytes = try JSONSerialization.data(withJSONObject: try XCTUnwrap(history))
        XCTAssertFalse(String(decoding: historyBytes, as: UTF8.self).contains("fixture-secret"))
        XCTAssertFalse(String(decoding: historyBytes, as: UTF8.self).contains("Continue this conversation by applying"))
        try writeConversationState(source, displaced)
        _ = try runCLI(["conversation", "repair-user-input", target, "--from-task", source], expectedStatus: 1)
        XCTAssertNil(try XCTUnwrap(try conversationState(target))["pendingUserInputRequest"])
    }

    // case-contract: test_codex_questions_can_be_answered_over_cli_xpc | MCP tool/requestUserInput structured questions raised in Plan mode remain in the conversation and move the task to Waiting Response while unanswered; leaving and reopening the conversation preserves the pending question, keyed answers resume the provider turn in In Progress, and the answered turn reports no outcome, so Playhouse drives a private status nudge; when that private turn cannot complete, the task settles in Blocked naming that reason instead of Waiting Response. A parallel conversation retains its own question and thread; the original conversation receives and answers a second question in its original Plan mode, and completing either conversation preserves the other pending request.
    func test_codex_questions_can_be_answered_over_cli_xpc() throws {
        let created = try runCLI(["task", "create", "--title", "Codex questions", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        XCTAssertEqual(created["ok"] as? Bool, true)
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let parallel = try runCLI(["task", "create", "--title", "Another conversation", "--prompt", "Fixture task description.", "--root", fixture.secondary.path])
        let parallelID = try XCTUnwrap((parallel["result"] as? [String: Any])?["id"] as? String)
        codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-question-isolation-plan-slow").path
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Codex questions")
        let modeMenu = element("conversation-mode-menu")
        XCTAssertTrue(modeMenu.waitForExistence(timeout: 5))
        modeMenu.click()
        app.menuItems["Plan mode"].click()
        XCTAssertTrue(modeMenu.label.contains("Plan mode"))
        element("message-composer").click()
        element("message-composer").typeText("Please share your plan.")
        element("send-message-button").click()

        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        XCTAssertTrue(app.staticTexts["Which color should I use?"].exists)
        XCTAssertTrue(element("conversation-user-input-request").exists, "The question should appear inline in the conversation.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Waiting Response")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(waitUntil({ !element("ai-question-confirmation-sheet").exists }, timeout: 5))
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Waiting Response")
        assertTaskVisible("Codex questions", inColumn: "Waiting Response")
        attachScreenshot(named: "Pending question remains part of its active conversation")
        openTask(named: "Another conversation")
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 5), "A different conversation should open while the question is pending.")
        element("message-composer").click()
        element("message-composer").typeText("Please ask parallel questions.")
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        let parallelThread = try XCTUnwrap(taskRecord(id: parallelID)?["codexThreadID"] as? String)
        let originalThread = try XCTUnwrap(taskRecord(id: taskID)?["codexThreadID"] as? String)
        XCTAssertNotEqual(parallelThread, originalThread)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        openTask(named: "Codex questions")
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 5), "Returning should restore the pending question inline.")
        XCTAssertEqual(try taskRecord(id: taskID)?["status"] as? String, "Waiting Response")
        XCTAssertFalse(element("submit-ai-answers-button").isEnabled, "Blank answers must not be submitted.")
        let greenOption = element("ai-question-option-color-Green")
        let blueOption = element("ai-question-option-color-Blue")
        greenOption.click()
        XCTAssertEqual(greenOption.value as? String, "selected")
        XCTAssertEqual(blueOption.value as? String, "not selected")
        blueOption.click()
        XCTAssertEqual(blueOption.value as? String, "selected", "Selecting another option must switch the answer like a radio button instead of adding to it.")
        XCTAssertEqual(greenOption.value as? String, "not selected", "Options must behave as a single-select radio group, not independently toggled checkboxes.")
        let secretAnswer = element("ai-question-answer-token")
        XCTAssertTrue(secretAnswer.exists)
        typeIntoField(secretAnswer, text: "fixture-secret")
        attachScreenshot(named: "Codex structured questions with option and private answer fields")
        element("submit-ai-answers-button").click()

        let resumeDeadline = Date().addingTimeInterval(5)
        var resumedStatus: String?
        while Date() < resumeDeadline {
            resumedStatus = try taskRecord(id: taskID)?["status"] as? String
            if resumedStatus == "In Progress" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(resumedStatus, "In Progress", "The unanswered question must not move the active task out of In Progress.")

        XCTAssertTrue(app.staticTexts["Which color should I use next?"].waitForExistence(timeout: 10), "A second question must return to the original task after the other task replaced the shared callback.")
        func pendingQuestion(_ owner: String) throws -> [String: Any] {
            let transcript = try XCTUnwrap(try conversationState(owner))
            return try XCTUnwrap(transcript["pendingUserInputRequest"] as? [String: Any])
        }
        XCTAssertEqual(try pendingQuestion(taskID)["threadID"] as? String, originalThread)
        XCTAssertEqual(try pendingQuestion(taskID)["mode"] as? String, "plan")
        XCTAssertEqual(try pendingQuestion(parallelID)["threadID"] as? String, parallelThread)
        XCTAssertEqual(try pendingQuestion(parallelID)["mode"] as? String, "default")
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()

        let completionDeadline = Date().addingTimeInterval(90)
        var completedStatus: String?
        while Date() < completionDeadline {
            completedStatus = try taskRecord(id: taskID)?["status"] as? String
            if completedStatus == "Blocked" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(completedStatus, "Blocked", "Without any reported outcome, the submitted answer settles the task in Blocked.")
        XCTAssertTrue(
            (try taskRecord(id: taskID)?["statusMessage"] as? String)?.contains("couldn't run the private turn") == true,
            "The Blocked reason must name why Playhouse stopped driving the work."
        )
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10), "Wait for A's completed provider response before checking B still owns its question.")
        XCTAssertNil(try XCTUnwrap(try conversationState(taskID))["pendingUserInputRequest"])
        XCTAssertFalse(element("ai-question-form-title").exists)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Codex questions", inColumn: "Blocked")
        openTask(named: "Another conversation")
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 5), "Finishing the first task must preserve the parallel question.")
        element("ai-question-option-color-Blue").click()
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        let parallelDeadline = Date().addingTimeInterval(90)
        while Date() < parallelDeadline, try taskRecord(id: parallelID)?["status"] as? String != "Blocked" {
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(try taskRecord(id: parallelID)?["status"] as? String, "Blocked")
        XCTAssertTrue(
            (try taskRecord(id: parallelID)?["statusMessage"] as? String)?.contains("couldn't run the private turn") == true,
            "The parallel conversation records the same Blocked reason."
        )
        XCTAssertTrue(waitUntil({ !self.element("ai-question-form-title").exists }, timeout: 10))
        XCTAssertNil(try XCTUnwrap(try conversationState(parallelID))["pendingUserInputRequest"])
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10))
        element("back-to-board-button").click()
        openTask(named: "Another conversation")
        XCTAssertFalse(element("ai-question-form-title").exists)
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10))
    }

    // case-contract: test_codex_empty_question_request_is_rejected | A failed turn preserves its blocked reason and appears in the compact Blocked section above Backlog with a user-intervention indication; retrying clears that section, and the successful retry returns to Waiting Response without an explicit completed outcome.
    func test_codex_empty_question_request_is_rejected() throws {
        let created = try runCLI(["task", "create", "--title", "Empty Codex questions", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let emptyFixture = try makeCodexFixture(emptyQuestions: true).path
        let failedTurn = try runCLI(
            ["conversation", "send", taskID, "--message", "Please ask your questions."],
            expectedStatus: 1,
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": emptyFixture]
        )
        XCTAssertFalse(failedTurn["ok"] as? Bool ?? true)
        XCTAssertEqual(try taskRecord(named: "Empty Codex questions")?["status"] as? String, "Blocked")
        launchApp(defaultParent: fixture.parent.path)
        XCTAssertTrue(element("column-heading-blocked").waitForExistence(timeout: 5))
        XCTAssertTrue(element("blocked-waiting-indicator").exists)
        assertTaskVisible("Empty Codex questions", inColumn: "Blocked")
        let boardViewport = element("board-columns-scroll-view")
        let blockedColumn = element("column-blocked")
        let backlogColumn = element("column-backlog")
        XCTAssertLessThan(blockedColumn.frame.maxY, backlogColumn.frame.minY)
        XCTAssertGreaterThanOrEqual(blockedColumn.frame.minY, boardViewport.frame.minY)
        XCTAssertLessThanOrEqual(backlogColumn.frame.maxY, boardViewport.frame.maxY)
        attachScreenshot(named: "Blocked task appears above Backlog while waiting for user intervention")
        let retryFixture = try makeCodexFixture(emptyQuestions: false).path
        _ = try runCLI(
            ["conversation", "send", taskID, "--message", "Retry this task.", "--answer", "color=Blue", "--answer", "token=fixture-secret"],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": retryFixture]
        )
        XCTAssertEqual(try taskRecord(named: "Empty Codex questions")?["status"] as? String, "Waiting Response")
        XCTAssertTrue(waitForDisappearance(element("column-heading-blocked")), "The blocked section should disappear after the task is unblocked.")
        XCTAssertFalse(element("blocked-waiting-indicator").exists)
        assertTaskVisible("Empty Codex questions", inColumn: "Waiting Response")
    }

    // case-contract: test_codex_nonblocking_question_keeps_task_in_progress | Non-blocking structured questions render inline, remain pending after switching to another conversation, and keep the task In Progress through fresh CLI/XPC history reconciliation after provider exit until answered. Free-text questions expose a selectable Other choice, select it when text is entered, keep it exclusive of listed answers, and deliver the free-text answer through CLI/XPC and visible UI. Answering resumes the provider turn without status nudges while its own pending question is still being resolved; the resumed turn returns to Waiting Response once the pending question clears, and the recovered secret answer stays redacted everywhere.
    func test_codex_nonblocking_question_keeps_task_in_progress() throws {
        _ = try runCLI(["task", "create", "--title", "Non-blocking question", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        _ = try runCLI(["task", "create", "--title", "Another non-blocking conversation", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-nonblocking-restart-question").path
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Non-blocking question")
        element("message-composer").click()
        element("message-composer").typeText("Ask non-blocking questions.")
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        XCTAssertTrue(element("conversation-user-input-request").exists, "The non-blocking question should be inline, not presented in a modal.")
        XCTAssertEqual(try taskRecord(named: "Non-blocking question")?["status"] as? String, "In Progress")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Non-blocking question", inColumn: "In Progress")
        openTask(named: "Another non-blocking conversation")
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 5))
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Non-blocking question", inColumn: "In Progress")
        openTask(named: "Non-blocking question")
        XCTAssertTrue(element("conversation-user-input-request").waitForExistence(timeout: 5), "Returning should restore the pending question inline.")
        XCTAssertEqual(try taskRecord(named: "Non-blocking question")?["status"] as? String, "In Progress")
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Non-blocking question", inColumn: "In Progress")
        openTask(named: "Non-blocking question")
        XCTAssertTrue(element("conversation-user-input-request").waitForExistence(timeout: 5))
        let otherOption = app.buttons["Other"]
        XCTAssertTrue(otherOption.exists, "An allowed free-text answer must have an explicit Other radio choice.")
        otherOption.click()
        XCTAssertEqual(otherOption.value as? String, "selected")
        let blueOption = element("ai-question-option-color-Blue")
        blueOption.click()
        XCTAssertEqual(blueOption.value as? String, "selected", "Selecting a listed choice must replace Other.")
        XCTAssertEqual(otherOption.value as? String, "not selected")
        let otherAnswer = app.textFields["Other answer"]
        otherAnswer.click()
        otherAnswer.typeText("Custom approach")
        XCTAssertEqual(otherOption.value as? String, "selected", "Typing an Other answer must select the Other choice.")
        XCTAssertEqual(blueOption.value as? String, "not selected", "Typing an Other answer must clear listed choices.")
        let secretAnswer = element("ai-question-answer-token")
        secretAnswer.click()
        secretAnswer.typeText("fixture-secret")
        element("submit-ai-answers-button").click()
        let nonblockingDeadline = Date().addingTimeInterval(5)
        var nonblockingStatus: String?
        while Date() < nonblockingDeadline {
            nonblockingStatus = try taskRecord(named: "Non-blocking question")?["status"] as? String
            if nonblockingStatus == "In Progress" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(nonblockingStatus, "In Progress", "A non-blocking recovery answer should leave the task active until the resumed turn completes.")
        // The recovered turn carried a secret answer, so its reply stays hidden, as in CLI/XPC history.
        XCTAssertTrue(transcriptMessage("[Response to private answer hidden]").waitForExistence(timeout: 10))
        XCTAssertFalse(app.groups.matching(NSPredicate(format: "label CONTAINS %@", "fixture-secret")).firstMatch.exists, "The secret answer must not appear in the transcript.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(named: "Non-blocking question")?["status"] as? String) == "Waiting Response" }, timeout: 20))
        let fixturePath = try XCTUnwrap(codexFixtureExecutable)
        let fixtureHistoryData = try Data(contentsOf: URL(fileURLWithPath: fixturePath + ".history"))
        let fixtureHistory = try XCTUnwrap(try JSONSerialization.jsonObject(with: fixtureHistoryData) as? [String: Any])
        let fixtureTurns = try XCTUnwrap(fixtureHistory["turns"] as? [[String: Any]])
        let reminders = fixtureTurns.filter { ($0["userMessage"] as? String)?.contains("Playhouse internal outcome nudge:") == true }
        XCTAssertEqual(reminders.count, 0, "A pending question still being resolved during the recovered turn must suppress private outcome reminders.")
        XCTAssertFalse(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Playhouse internal outcome nudge:")).firstMatch.exists)
        XCTAssertFalse(element("conversation-user-input-request").exists)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        assertTaskVisible("Non-blocking question", inColumn: "Waiting Response")
    }

    // case-contract: test_codex_async_questions_render_and_reply_as_followup | Async agentMessage questions retain choices and a free-text prompt in live updates and fresh CLI/XPC history, retain accepted-turn model attribution during an active history reload, stay separate from later assistant text, and receive validated answers through the shared manager during and after an active turn. The UI shows inline answer cards instead of raw bullet text, blocks incomplete answers, preserves answered cards across reopening, and displays both submitted answers and responses.
    func test_codex_async_questions_render_and_reply_as_followup() throws {
        let created = try runCLI(["task", "create", "--title", "Async Codex question", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-async-question").path
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Async Codex question")
        element("message-composer").click()
        element("message-composer").typeText("Ask an async question.")
        element("send-message-button").click()

        let card = element("async-question-item_playhouse_async_question")
        XCTAssertTrue(card.waitForExistence(timeout: 10))
        let yesOption = element("async-question-option-item_playhouse_async_question-0-0")
        let noOption = element("async-question-option-item_playhouse_async_question-0-1")
        XCTAssertEqual(yesOption.label, "Yes, update paired tests and run required verification")
        XCTAssertEqual(noOption.label, "No, leave tests and verification for later")
        XCTAssertTrue(element("async-question-answer-item_playhouse_async_question-1").exists)
        XCTAssertFalse(element("assistant-message-item_playhouse_async_question").exists,
                       "Structured choices should appear in an answer card instead of a Markdown bubble.")
        XCTAssertFalse(element("submit-async-questions-item_playhouse_async_question").isEnabled)
        XCTAssertTrue(app.staticTexts["I can continue while you decide."].waitForExistence(timeout: 10),
                      "The assistant message after the question must remain separate.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: WorkspaceFixture.root.appendingPathComponent("codex-fixture-async-question.question-ready").path),
                      "The question fixture must still have an active turn.")
        element("back-to-board-button").click()
        openTask(named: "Async Codex question")
        XCTAssertTrue(app.staticTexts["I can continue while you decide."].waitForExistence(timeout: 10),
                      "Reopening during the active turn must load Codex history, not only restore the pending question request.")
        XCTAssertTrue(app.staticTexts["Codex · Luna"].exists,
                      "The reopened active history message must retain its accepted-turn model label.")
        XCTAssertTrue(element("async-question-item_playhouse_async_question").exists,
                      "The pending question remains visible after the active history reload.")
        yesOption.click()
        XCTAssertFalse(element("submit-async-questions-item_playhouse_async_question").isEnabled,
                       "Every async question needs an answer before submission.")
        let detail = element("async-question-answer-item_playhouse_async_question-1")
        detail.click()
        detail.typeText("Keep the draft intact.")
        let composer = element("message-composer")
        composer.click()
        composer.typeText("An unsent draft stays here.")
        element("submit-async-questions-item_playhouse_async_question").click()

        XCTAssertTrue(waitUntil({ self.transcriptContains("Additional detail: Keep the draft intact.") }, timeout: 10), "The full two-answer reply must be sent.")
        let response = element("assistant-message-item_playhouse_async_answer_steered")
        XCTAssertTrue(response.waitForExistence(timeout: 10))
        XCTAssertTrue(response.label.contains("Answers received: Test and verify: Yes, update paired tests and run required verification"))
        XCTAssertTrue(response.label.contains("Additional detail: Keep the draft intact."))
        XCTAssertTrue(card.exists)
        XCTAssertTrue(app.staticTexts["Answered"].exists)
        XCTAssertEqual(composer.value as? String, "An unsent draft stays here.")
        let laterCard = element("async-question-item_playhouse_async_later_question")
        XCTAssertTrue(laterCard.waitForExistence(timeout: 10))
        let idleDeadline = Date().addingTimeInterval(10)
        while !element("send-message-button").isEnabled && Date() < idleDeadline {
            RunLoop.current.run(until: Date().addingTimeInterval(0.05))
        }
        XCTAssertTrue(element("send-message-button").isEnabled, "The later answer must be submitted after the first turn completes.")
        let laterAnswer = element("async-question-answer-item_playhouse_async_later_question-0")
        laterAnswer.click()
        laterAnswer.typeText("Finish after the turn.")
        element("submit-async-questions-item_playhouse_async_later_question").click()
        // Hidden outcome reminders take turn numbers, so match the reply by its answer.
        let completedResponse = app.groups.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND label CONTAINS %@", "assistant-message-item_playhouse_async_answer_", "Finish after the turn."
        )).firstMatch
        XCTAssertTrue(completedResponse.waitForExistence(timeout: 10),
                      "A question answered after its original turn must refresh the visible conversation.")
        XCTAssertTrue(completedResponse.label.contains("Answers received: One more check: Finish after the turn."))
        XCTAssertEqual(composer.value as? String, "An unsent draft stays here.")
        element("back-to-board-button").click()
        openTask(named: "Async Codex question")
        XCTAssertTrue(revealWholeTranscript(), "The reopened conversation should load its earlier turns as the reader scrolls up.")
        XCTAssertTrue(card.waitForExistence(timeout: 5))
        XCTAssertTrue(app.staticTexts["Answered"].exists)
        XCTAssertTrue(laterCard.exists)
        XCTAssertTrue(laterCard.staticTexts["Answered"].exists, "The later question must stay answered after reopening.")
        XCTAssertEqual(element("message-composer").value as? String, "An unsent draft stays here.")
    }

    // case-contract: test_codex_async_question_queued_answer_retries | An async question answered after its turn ends stays Pending when the first follow-up fails, rejects duplicate answers across fresh CLI/XPC connections, and becomes Answered only after an explicit queued retry succeeds. The paired UI keeps the card and queue action visible across reopening and then displays the delivered response. A fresh `conversation answered-async` read lists no answered questions while the answer is pending and lists the question once it is delivered.
    func test_codex_async_question_queued_answer_retries() throws {
        let created = try runCLI(["task", "create", "--title", "Queued async question", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let executable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-async-question-queued")
        codexFixtureExecutable = executable.path
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Queued async question")
        element("message-composer").click()
        element("message-composer").typeText("Ask a queued async question.")
        element("send-message-button").click()
        let card = element("async-question-item_playhouse_async_question")
        XCTAssertTrue(card.waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({
            ((try? self.taskRecord(id: taskID))?["status"] as? String) == "Waiting Response"
        }, timeout: 10), "The first turn must finish before queueing the answer.")
        _ = FileManager.default.createFile(atPath: executable.path + ".fail-next-turn-start", contents: Data())
        element("async-question-option-item_playhouse_async_question-0-0").click()
        element("async-question-answer-item_playhouse_async_question-1").click()
        element("async-question-answer-item_playhouse_async_question-1").typeText("Retry this answer.")
        element("submit-async-questions-item_playhouse_async_question").click()
        XCTAssertTrue(card.staticTexts["Pending"].waitForExistence(timeout: 10))
        let queueResult = try runCLI(["conversation", "queue-list", taskID])
        let queued = try XCTUnwrap((queueResult["result"] as? [[String: Any]])?.first)
        XCTAssertEqual(queued["asyncQuestionItemID"] as? String, "item_playhouse_async_question")
        let queuedID = try XCTUnwrap(queued["id"] as? String)
        XCTAssertEqual(queued["state"] as? String, "needsAction")
        let pendingAnswered = try XCTUnwrap(try runCLI(["conversation", "answered-async", taskID])["result"] as? [String: Any])
        XCTAssertEqual(pendingAnswered["itemIDs"] as? [String], [], "A pending async answer is not answered yet.")
        element("back-to-board-button").click()
        openTask(named: "Queued async question")
        XCTAssertTrue(card.waitForExistence(timeout: 5))
        XCTAssertTrue(card.staticTexts["Pending"].exists)
        let retry = element("retry-queued-message-\(queuedID.uppercased())")
        XCTAssertTrue(retry.waitForExistence(timeout: 5))
        retry.click()
        // The fixture numbers answer items per turn, so find the answer by content.
        let response = app.descendants(matching: .any)
            .matching(NSPredicate(format: "identifier BEGINSWITH %@ AND label CONTAINS %@", "assistant-message-item_playhouse_async_answer_", "Answers received: Test and verify"))
            .firstMatch
        XCTAssertTrue(response.waitForExistence(timeout: 10))
        XCTAssertTrue(response.label.contains("Answers received: Test and verify: Yes, update paired tests and run required verification"))
        XCTAssertTrue(response.label.contains("Additional detail: Retry this answer."))
        XCTAssertTrue(card.staticTexts["Answered"].exists)
        let deliveredAnswered = try XCTUnwrap(try runCLI(["conversation", "answered-async", taskID])["result"] as? [String: Any])
        XCTAssertEqual(deliveredAnswered["itemIDs"] as? [String], ["item_playhouse_async_question"], "The delivered async answer should be recorded as answered.")
    }

    // case-contract: test_codex_interrupted_turn_blocks_with_reason_and_can_retry | Turn start persists In Progress; a genuine interrupted outcome remains Blocked with its reason, while restart recovery returns stale In Progress work to Waiting Response with its prompt and conversation available. A saved prompt whose turn never started returns to Waiting Response with its draft intact and can be continued; a turn running when the window quits cleanly or is killed keeps running in the bridge daemon, stays In Progress with its prompt visible after relaunch, finishes, and allows a follow-up. Interrupted outcomes and diagnostics persist across connections; a new prompt can finish in Review. The live turn's activity section renders open and folds away when the interrupted turn settles without an answer, on the conversation that stayed open; the interrupted turn adds no final answer and keeps the activity it reported. A queued follow-up remains visible as needing action after interruption, survives reopening, and is dispatched only after an explicit retry; the completed retry becomes the task's latest saved prompt.
    func test_codex_interrupted_turn_blocks_with_reason_and_can_retry() throws {
        _ = try runCLI(["task", "create", "--title", "Interrupted turn", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        codexFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-interrupted").path
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Interrupted turn")
        element("message-composer").click()
        element("message-composer").typeText("Start work that will be interrupted.")
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        let interruptedActivity = element("codex-activity-disclosure")
        XCTAssertTrue(interruptedActivity.waitForExistence(timeout: 10), "A live turn should surface its activity section.")
        XCTAssertTrue(waitUntil({ interruptedActivity.value as? String == "Expanded, down chevron" }, timeout: 10),
                      "A turn in flight should show its work instead of hiding it behind Working for.")
        // The lone reported activity is still running, so it occupies the live slot
        // outside the section; the open section itself has nothing inside it yet.
        XCTAssertTrue(element("codex-activity-row-item_fixture_interrupted_command").waitForExistence(timeout: 10),
                      "The live turn should render its reported activity without a click.")
        let interruptedID = try taskID(named: "Interrupted turn")
        let queuedText = "Follow up after I review the interrupted turn."
        let queued = try runCLI(["conversation", "queue", interruptedID, "--message", queuedText])["result"] as? [String: Any]
        let queuedID = try XCTUnwrap(queued?["id"] as? String)
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()

        XCTAssertTrue(element("codex-chat-error").waitForExistence(timeout: 10))
        // The turn settles with no answer. Its reported activity keeps the section
        // mounted on the same conversation, so it must be folded rather than gone:
        // asserting the section still exists is what makes the collapse meaningful.
        XCTAssertTrue(waitUntil({ interruptedActivity.value as? String == "Collapsed, right chevron" }, timeout: 10),
                      "An interrupted turn should fold its activity section away instead of resting open.")
        XCTAssertTrue(interruptedActivity.exists, "The interrupted turn's activity section should stay available, just folded.")
        XCTAssertFalse(element("codex-activity-details").exists, "A settled interrupted turn should not rest on expanded activity details.")
        XCTAssertFalse(element("pause-response-button").exists, "The interrupted turn should no longer be responding.")
        attachScreenshot(named: "Activity folds away when an interrupted turn settles")
        XCTAssertTrue(app.staticTexts["Follow-up needs your action"].waitForExistence(timeout: 10), "An interrupted turn must retain its queued message for an explicit retry.")
        let blocked = try XCTUnwrap(taskRecord(named: "Interrupted turn"))
        XCTAssertEqual(blocked["status"] as? String, "Blocked")
        XCTAssertTrue((blocked["statusMessage"] as? String)?.localizedCaseInsensitiveContains("interrupted") == true)
        let sendFailure = try XCTUnwrap(diagnosticEvents().first {
            $0["event"] as? String == "conversation.send.failed" && $0["taskID"] as? String == interruptedID
        })
        XCTAssertEqual(sendFailure["phase"] as? String, "codex-turn")
        XCTAssertEqual(sendFailure["storePath"] as? String, dataDirectory.appendingPathComponent("Playhouse-v2.store").path)

        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        app.launchEnvironment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = codexFixtureExecutable
        relaunchApp()
        openTask(named: "Interrupted turn")
        let reopened = try XCTUnwrap(taskRecord(named: "Interrupted turn"))
        XCTAssertEqual(reopened["status"] as? String, "Blocked")
        XCTAssertTrue((reopened["statusMessage"] as? String)?.localizedCaseInsensitiveContains("interrupted") == true)
        try completeCurrentTaskWithFixtureAnswers(taskTitle: "Interrupted turn", prompt: "Retry the interrupted task.")
        XCTAssertEqual(try taskRecord(named: "Interrupted turn")?["status"] as? String, "Review")
        let retryQueuedButton = element("retry-queued-message-\(queuedID.uppercased())")
        XCTAssertTrue(retryQueuedButton.waitForExistence(timeout: 10), "The retained follow-up should remain explicitly retryable after reopening and completing a new turn.")
        retryQueuedButton.click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10), "Explicit retry should submit the queued message to Codex.")
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        XCTAssertTrue(app.staticTexts["Answers received: Blue / fixture-secret."].waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({
            (((try? self.runCLI(["conversation", "queue-list", interruptedID])["result"] as? [[String: Any]]) ?? [])).isEmpty
        }, timeout: 10), "A completed explicit retry should remove the queued item.")
        XCTAssertEqual(try taskRecord(id: interruptedID)?["savedPrompt"] as? String, queuedText, "The successfully retried follow-up should become the latest saved prompt.")

        _ = try runCLI(["task", "create", "--title", "Reopen active turn", "--prompt", "Fixture task description.", "--root", fixture.primary.path])
        let cleanRestartFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-hold").path
        codexFixtureExecutable = cleanRestartFixtureExecutable
        try? FileManager.default.removeItem(atPath: cleanRestartFixtureExecutable + ".hold-used")
        app.launchEnvironment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = cleanRestartFixtureExecutable
        relaunchApp()
        openTask(named: "Reopen active turn")
        element("message-composer").click()
        element("message-composer").typeText("Leave this turn active while Playhouse closes.")
        element("send-message-button").click()
        let activeDeadline = Date().addingTimeInterval(10)
        var activeStatus: String?
        while Date() < activeDeadline {
            activeStatus = try taskRecord(named: "Reopen active turn")?["status"] as? String
            if activeStatus == "In Progress" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(activeStatus, "In Progress")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: cleanRestartFixtureExecutable + ".hold-used") }, timeout: 10), "Codex should reach the deliberate held turn before the app closes.")
        attachScreenshot(named: "Task remains In Progress while the Codex turn is active")

        relaunchApp()
        openTask(named: "Reopen active turn")
        // The bridge daemon owns the turn, so quitting the window leaves it running.
        XCTAssertEqual(try taskRecord(named: "Reopen active turn")?["status"] as? String, "In Progress", "A clean quit should leave the daemon-owned turn running.")
        XCTAssertTrue(transcriptMessage("Leave this turn active while Playhouse closes.").waitForExistence(timeout: 10), "The visible transcript should restore the prompt after a clean quit.")
        XCTAssertTrue(app.staticTexts["In Progress"].waitForExistence(timeout: 10), "The reopened window should show the still-running turn.")
        let interruptedHistory = try runCLI(["conversation", "history", try taskID(named: "Reopen active turn")])["result"] as? [String: Any]
        XCTAssertTrue(
            ((interruptedHistory?["messages"] as? [[String: Any]]) ?? []).contains {
                $0["role"] as? String == "user" && $0["text"] as? String == "Leave this turn active while Playhouse closes."
            },
            "The running turn's prompt should be in the saved conversation after a clean quit."
        )
        try Data("Finish the turn that outlived the window.\n".utf8).write(to: URL(fileURLWithPath: cleanRestartFixtureExecutable + ".turn-release"), options: .atomic)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(named: "Reopen active turn")?["status"] as? String) != "In Progress" }, timeout: 15), "The turn that outlived the window should finish.")
        XCTAssertTrue(waitUntil({ self.element("send-message-button").exists }, timeout: 10), "The reopened window should follow the finished turn.")
        try completeCurrentTaskWithFixtureAnswers(
            taskTitle: "Reopen active turn",
            prompt: "Continue the saved work after relaunch.",
            reportCompletedOutcome: false
        )
        XCTAssertEqual(try taskRecord(named: "Reopen active turn")?["status"] as? String, "Waiting Response")
        attachScreenshot(named: "Playhouse resumes the saved conversation after a clean quit")

        let unexpectedTask = try XCTUnwrap(
            (try runCLI(["task", "create", "--title", "Unexpected restart", "--prompt", "Fixture task description.", "--root", fixture.primary.path])["result"] as? [String: Any])
        )
        let unexpectedTaskID = try XCTUnwrap(unexpectedTask["id"] as? String)
        let unexpectedRestartFixtureExecutable = WorkspaceFixture.root.appendingPathComponent("codex-fixture-hold").path
        codexFixtureExecutable = unexpectedRestartFixtureExecutable
        try? FileManager.default.removeItem(atPath: unexpectedRestartFixtureExecutable + ".hold-used")
        app.launchEnvironment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = unexpectedRestartFixtureExecutable
        relaunchApp()
        openTask(named: "Unexpected restart")
        let unexpectedPrompt = "Keep this work available after an unexpected restart."
        element("message-composer").click()
        element("message-composer").typeText(unexpectedPrompt)
        element("send-message-button").click()
        let unexpectedDeadline = Date().addingTimeInterval(10)
        var unexpectedStatus: String?
        while Date() < unexpectedDeadline {
            unexpectedStatus = try taskRecord(id: unexpectedTaskID)?["status"] as? String
            if unexpectedStatus == "In Progress" { break }
            Thread.sleep(forTimeInterval: 0.05)
        }
        XCTAssertEqual(unexpectedStatus, "In Progress")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: unexpectedRestartFixtureExecutable + ".hold-used") }, timeout: 10), "Codex should reach the deliberate held turn before simulated process loss.")
        let appBundleIdentifier = try XCTUnwrap(Bundle(url: appBundle)?.bundleIdentifier)
        let appProcessID = try XCTUnwrap(
            NSRunningApplication.runningApplications(withBundleIdentifier: appBundleIdentifier).first,
            "The app process should be visible before simulating unexpected termination."
        ).processIdentifier
        XCTAssertGreaterThan(appProcessID, 0)
        XCTAssertEqual(Darwin.kill(appProcessID, SIGKILL), 0, "The fixture app should be terminated without running its quit cleanup.")
        XCTAssertTrue(waitUntil({ app.state == .notRunning }, timeout: 10), "Playhouse should stop after the simulated unexpected termination.")

        launchAppWithOpen()
        waitForBoardOrAbortSuite()
        openTask(named: "Unexpected restart")
        XCTAssertEqual(try taskRecord(id: unexpectedTaskID)?["status"] as? String, "In Progress", "The daemon-owned turn should survive the window's unexpected termination.")
        XCTAssertTrue(transcriptMessage(unexpectedPrompt).waitForExistence(timeout: 10), "The visible transcript should restore the prompt after unexpected termination.")
        let unexpectedHistory = try runCLI(["conversation", "history", unexpectedTaskID])["result"] as? [String: Any]
        XCTAssertTrue(
            ((unexpectedHistory?["messages"] as? [[String: Any]]) ?? []).contains {
                $0["role"] as? String == "user" && $0["text"] as? String == unexpectedPrompt
            },
            "The unexpected restart should preserve the last submitted message in conversation history."
        )
        let survivingTurnRelease = URL(fileURLWithPath: unexpectedRestartFixtureExecutable + ".turn-release")
        try Data("Finish the turn that survived the window.\n".utf8).write(to: survivingTurnRelease, options: .atomic)
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: unexpectedTaskID)?["status"] as? String) != "In Progress" }, timeout: 15), "The turn that survived the window should finish.")
        XCTAssertTrue(waitUntil({ self.element("send-message-button").exists }, timeout: 10))
        try completeCurrentTaskWithFixtureAnswers(
            taskTitle: "Unexpected restart",
            prompt: "Continue after an unexpected restart.",
            reportCompletedOutcome: false
        )
        XCTAssertEqual(try taskRecord(id: unexpectedTaskID)?["status"] as? String, "Waiting Response")
        attachScreenshot(named: "Playhouse recovers and continues work after an unexpected restart")
    }

    // case-contract: test_task_workspace_changes_group_staged_and_unstaged_diffs | The task view lists every file changed from the task branch's recorded base in a Changes section below a collapsed Viewed section, including committed branch changes and current staged, unstaged, and untracked edits, and excluding commits unique to the base branch. Marking a file viewed saves its current contents, stages the file in Git, and adds a Viewed entry that keeps showing the reviewed work from the branch base to that snapshot. Work done after that review is listed again under Changes and diffed against the saved snapshot, so one file can appear in both sections at once; a path with no content in the branch base and no current file is zero net change and is hidden entirely, even with a stale viewed snapshot, rather than showing a ghost entry. Selecting text or JSON files opens a calculated side-by-side diff whose header names the baseline used. Viewed snapshots persist across fresh CLI/XPC connections. Files that aren't current Changes entries, including already-viewed and unknown paths, are rejected by the mark-viewed CLI operation, and the UI offers that action only for Changes entries. Uncommitted filenames are green. Opening one diff after another serves each file's own content from the side-by-side editor the app loads once per session, so a later diff reuses that warm editor instead of starting Monaco again. Diagnostics record inventory and file-read outcomes without logging file contents.
    func test_task_workspace_changes_group_staged_and_unstaged_diffs() throws {
        _ = try runCLI([
            "task", "create", "--title", "Git changes", "--prompt", "Fixture task description.", "--root", fixture.changes.path
        ])
        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Git changes")

        XCTAssertTrue(element("unviewed-changes-section").waitForExistence(timeout: 10))
        assertText("unviewed-changes-title", equals: "Changes")
        assertText("viewed-changes-title", equals: "Viewed")
        XCTAssertTrue(element("viewed-changes-section").exists)
        XCTAssertLessThan(element("viewed-changes-section").frame.minY, element("unviewed-changes-section").frame.minY)
        XCTAssertTrue(element("workspace-change-unviewed-shared.txt").exists)
        XCTAssertTrue(element("workspace-change-unviewed-untracked.txt").exists)
        XCTAssertTrue(element("workspace-change-unviewed-deleted.txt").exists)
        XCTAssertTrue(element("workspace-change-unviewed-syntax.json").exists)
        XCTAssertTrue(element("mark-viewed-shared.txt").exists)
        XCTAssertTrue(element("mark-viewed-deleted.txt").exists)
        XCTAssertFalse(element("mark-viewed-stale.txt").exists)
        XCTAssertEqual(app.buttons.matching(identifier: "workspace-change-unviewed-shared.txt").count, 1)

        let taskID = try taskID(named: "Git changes")
        let inventory = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((inventory?["unviewed"] as? [[String: Any]])?.count, 7)
        XCTAssertEqual((inventory?["viewed"] as? [[String: Any]])?.count, 0)
        let shared = try runCLI([
            "task", "changes", "diff", taskID,
            "--repository", fixture.changes.path,
            "--path", "shared.txt",
            "--group", "unviewed"
        ])["result"] as? [String: Any]
        XCTAssertEqual(shared?["original"] as? String, "Shared baseline.\n")
        XCTAssertEqual(shared?["modified"] as? String, "Shared working version.\n")
        assertCLIError(
            try runCLI([
                "task", "changes", "diff", taskID,
                "--repository", fixture.changes.path,
                "--path", "stale.txt",
                "--group", "unviewed",
            ], expectedStatus: 3),
            code: "not_found"
        )

        element("workspace-change-unviewed-shared.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        assertText("workspace-diff-title", equals: "shared.txt")
        assertText("workspace-diff-source", equals: "suggested-parent/changes · Since branch base")
        assertText("workspace-diff-editor-status", equals: "Side-by-side")
        let firstEditorStatus = monacoEditorStatus()
        XCTAssertTrue(
            firstEditorStatus.hasPrefix("Editor 1 ") && firstEditorStatus.hasSuffix(", showing shared.txt"),
            "The first diff must render in Monaco's first load. The editor reported ‘\(firstEditorStatus)’."
        )
        attachScreenshot(named: "The first diff opens in the side-by-side editor")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(element("workspace-diff-overlay").waitForNonExistence(timeout: 2))

        element("mark-viewed-shared.txt").click()
        // Marking saves a snapshot and stages the file asynchronously.
        var marked: [String: Any]?
        XCTAssertTrue(waitUntil({
            marked = try? self.runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
            return ((marked?["viewed"] as? [[String: Any]]) ?? []).contains { $0["path"] as? String == "shared.txt" }
        }, timeout: 10), "Marking a file viewed should persist its Viewed entry.")
        XCTAssertFalse(((marked?["unviewed"] as? [[String: Any]]) ?? []).contains { $0["path"] as? String == "shared.txt" })
        element("viewed-changes-section").click()
        XCTAssertTrue(element("workspace-change-viewed-shared.txt").waitForExistence(timeout: 10))
        XCTAssertFalse(element("mark-viewed-shared.txt").exists, "Viewed entries must not offer the mark-viewed action.")
        try "Edited after viewing.\n".write(to: fixture.changes.appendingPathComponent("shared.txt"), atomically: true, encoding: .utf8)
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(
            element("workspace-change-unviewed-shared.txt").waitForExistence(timeout: 10),
            "A later edit should be listed as a change still to review."
        )
        XCTAssertTrue(
            element("workspace-change-viewed-shared.txt").exists,
            "The already-reviewed work should stay listed under Viewed."
        )
        element("workspace-change-viewed-shared.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        assertText("workspace-diff-source", equals: "suggested-parent/changes · Since branch base")
        let reviewedMonacoValue = renderedDiffValue()
        XCTAssertTrue(reviewedMonacoValue.contains("Original:\nShared baseline.\n"))
        XCTAssertTrue(
            reviewedMonacoValue.contains("Modified:\nShared working version.\n"),
            "The viewed diff must stay at the reviewed snapshot, not follow later edits."
        )
        app.typeKey(.escape, modifierFlags: [])
        element("workspace-change-unviewed-shared.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        assertText("workspace-diff-source", equals: "suggested-parent/changes · Since last viewed")
        assertText("workspace-diff-editor-status", equals: "Side-by-side")
        assertText("workspace-diff-highlight-status", equals: "1 change highlighted")
        let viewedMonacoValue = renderedDiffValue()
        XCTAssertTrue(viewedMonacoValue.contains("Original:\nShared working version.\n"))
        XCTAssertTrue(viewedMonacoValue.contains("Modified:\nEdited after viewing.\n"))
        XCTAssertEqual(element("workspace-change-unviewed-shared.txt").value as? String, "Uncommitted, green")
        XCTAssertEqual(element("workspace-change-viewed-shared.txt").value as? String, "Uncommitted, green")
        app.typeKey(.escape, modifierFlags: [])
        attachScreenshot(named: "A re-edited file is listed under both Viewed and Changes")

        element("mark-viewed-untracked.txt").click()
        XCTAssertTrue(element("workspace-change-viewed-untracked.txt").waitForExistence(timeout: 10))
        let stagedStatus = try runGitOutput(fixture.changes, "status", "--porcelain", "--", "untracked.txt")
        XCTAssertEqual(
            stagedStatus.trimmingCharacters(in: .whitespacesAndNewlines),
            "A  untracked.txt",
            "Marking a new file viewed should stage it so later edits are detected."
        )
        try "Untracked file, edited after viewing.\n".write(to: fixture.changes.appendingPathComponent("untracked.txt"), atomically: true, encoding: .utf8)
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(element("workspace-change-unviewed-untracked.txt").waitForExistence(timeout: 10))
        XCTAssertTrue(element("workspace-change-viewed-untracked.txt").exists)
        element("workspace-change-unviewed-untracked.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        let recreatedUntrackedValue = renderedDiffValue()
        XCTAssertTrue(recreatedUntrackedValue.contains("Original:\nUntracked file.\n"))
        XCTAssertTrue(recreatedUntrackedValue.contains("Modified:\nUntracked file, edited after viewing.\n"))
        app.typeKey(.escape, modifierFlags: [])

        element("mark-viewed-deleted.txt").click()
        // The viewed snapshot is saved asynchronously; recreating the file first would be reviewed too.
        XCTAssertTrue(waitUntil({
            let inventory = try? self.runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
            return ((inventory?["viewed"] as? [[String: Any]]) ?? []).contains { $0["path"] as? String == "deleted.txt" }
        }, timeout: 10), "Marking the deletion viewed should persist before the file is recreated.")
        try "Recreated after viewing.\n".write(to: fixture.changes.appendingPathComponent("deleted.txt"), atomically: true, encoding: .utf8)
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(element("workspace-change-unviewed-deleted.txt").waitForExistence(timeout: 10))
        XCTAssertTrue(element("workspace-change-viewed-deleted.txt").exists)
        assertText("workspace-change-viewed-deleted.txt", equals: "deleted.txt, deleted, reviewed")
        assertText("workspace-change-unviewed-deleted.txt", equals: "deleted.txt, added, pending")
        element("workspace-change-unviewed-deleted.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        let recreatedMonacoValue = renderedDiffValue()
        XCTAssertTrue(recreatedMonacoValue.contains("Original:\n\nModified:\nRecreated after viewing.\n"))
        app.typeKey(.escape, modifierFlags: [])
        assertCLIError(
            try runCLI(["task", "changes", "mark-viewed", taskID, "--repository", fixture.changes.path, "--path", "stale.txt"], expectedStatus: 3),
            code: "not_found"
        )

        // A file that never existed in the branch base, created then renamed away by two
        // separate file operations (not `git mv`, which Git would recognize as one rename),
        // nets to zero change once both the deletion and the replacement are reviewed.
        try "Ephemeral content.\n".write(to: fixture.changes.appendingPathComponent("ephemeral.txt"), atomically: true, encoding: .utf8)
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(element("mark-viewed-ephemeral.txt").waitForExistence(timeout: 10))
        element("mark-viewed-ephemeral.txt").click()
        XCTAssertTrue(element("workspace-change-viewed-ephemeral.txt").waitForExistence(timeout: 10))
        try FileManager.default.removeItem(at: fixture.changes.appendingPathComponent("ephemeral.txt"))
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(
            element("workspace-change-unviewed-ephemeral.txt").waitForExistence(timeout: 10),
            "Deleting a reviewed new file lists the deletion as a change still to review."
        )
        element("mark-viewed-ephemeral.txt").click()
        // The viewed snapshot is saved asynchronously; a refresh started before it lands still lists the old entry.
        XCTAssertTrue(waitUntil({
            let inventory = try? self.runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
            let listed = ((inventory?["viewed"] as? [[String: Any]]) ?? []) + ((inventory?["unviewed"] as? [[String: Any]]) ?? [])
            return inventory != nil && !listed.contains { $0["path"] as? String == "ephemeral.txt" }
        }, timeout: 10), "Reviewing the deletion of a never-committed file should leave it out of the persisted inventory.")
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(
            element("workspace-change-viewed-ephemeral.txt").waitForNonExistence(timeout: 10),
            "A reviewed file with no base content and no current file is zero net change, not a ghost entry."
        )
        XCTAssertFalse(element("workspace-change-unviewed-ephemeral.txt").exists)
        try "Reborn content.\n".write(to: fixture.changes.appendingPathComponent("ephemeral.txt"), atomically: true, encoding: .utf8)
        element("refresh-workspace-changes-button").click()
        XCTAssertTrue(
            element("workspace-change-unviewed-ephemeral.txt").waitForExistence(timeout: 10),
            "Recreating the file afterward surfaces it as a fresh change to review."
        )

        element("workspace-change-unviewed-untracked.txt").click()
        assertText("workspace-diff-title", equals: "untracked.txt")
        assertText("workspace-diff-editor-status", equals: "Side-by-side")
        XCTAssertEqual(
            monacoEditorStatus(),
            "Editor 1 reused, showing untracked.txt",
            "Reopening a diff must reuse Monaco's first load instead of loading the editor again."
        )
        element("workspace-change-unviewed-syntax.json").click()
        XCTAssertNotEqual(
            element("workspace-diff-editor-status").value as? String,
            "Editor 1 reused, showing untracked.txt",
            "The warm editor must stop presenting the previous file as soon as another one is opened."
        )
        assertText("workspace-diff-title", equals: "syntax.json")
        assertText("workspace-diff-editor-status", equals: "Side-by-side")
        XCTAssertEqual(
            monacoEditorStatus(),
            "Editor 1 reused, showing syntax.json",
            "Switching files keeps rendering in the same warm editor."
        )
        let reusedEditorValue = renderedDiffValue()
        XCTAssertTrue(
            reusedEditorValue.contains("Modified:\n{\"value\":\"working version\"}"),
            "The reused editor must show the newly opened file, not the previous diff."
        )
        assertText("workspace-diff-highlight-status", equals: "1 change highlighted")
        attachScreenshot(named: "A later diff opens in the already-loaded side-by-side editor")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(element("empty-conversation").exists, "Closing the diff should reveal the conversation again.")

        let changeDiagnostics = try diagnosticEvents()
        XCTAssertTrue(changeDiagnostics.contains {
            $0["event"] as? String == "workspace.files.inventory.succeeded" && Int($0["unviewedCount"] as? String ?? "0") ?? 0 > 0
        })
        XCTAssertTrue(changeDiagnostics.contains { $0["event"] as? String == "workspace.file.read.succeeded" })
        XCTAssertFalse(
            String(describing: changeDiagnostics).contains("Shared working version."),
            "Diagnostics must not log changed file contents."
        )
    }

    // case-contract: test_task_workspace_changes_mark_all_viewed_and_unview | The Changes section header offers Mark all as viewed while it lists files: one action saves a viewed snapshot of every current Changes entry and stages each in Git, so Changes empties and every file is listed under Viewed, and the operation reports how many files it marked, zero when nothing is pending. Each Viewed entry offers Mark as unviewed, which drops that file's snapshot without touching the Git index, so its whole change from the branch base is listed under Changes again; unviewing a file that isn't a current Viewed entry, including one already unviewed and an unknown path, is rejected. These results persist across fresh CLI/XPC connections. The Changes section collapses inside the task sidebar, hiding its Viewed and Changes lists while its header and pending count stay visible and the sidebar stays open for other sections; separately, the whole sidebar hides to a narrow rail that still shows how many files are pending. Each collapsed or expanded state is its own global preference, so opening another task keeps it. Once loaded, refreshing a task with no changes keeps its No changes state on screen instead of flashing the loading placeholder.
    func test_task_workspace_changes_mark_all_viewed_and_unview() throws {
        let cleanRepository = runDirectory.appendingPathComponent("clean-changes", isDirectory: true)
        try FileManager.default.createDirectory(at: cleanRepository, withIntermediateDirectories: true)
        try "Baseline.\n".write(to: cleanRepository.appendingPathComponent("tracked.txt"), atomically: true, encoding: .utf8)
        try runGit(cleanRepository, "init", "--initial-branch=main")
        try runGit(cleanRepository, "config", "user.name", "Playhouse UI Test")
        try runGit(cleanRepository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(cleanRepository, "add", "tracked.txt")
        try runGit(cleanRepository, "commit", "-m", "Baseline")
        // This case builds its own changed repository: the shared fixture is prepared only for
        // the staged/unstaged case and is left modified by it within a batch.
        let changes = runDirectory.appendingPathComponent("review-parent/changes", isDirectory: true)
        try FileManager.default.createDirectory(at: changes, withIntermediateDirectories: true)
        let baseline = [
            "staged.txt": "Staged baseline.\n",
            "shared.txt": "Shared baseline.\n",
            "working.txt": "Working baseline.\n",
            "deleted.txt": "Deleted baseline.\n",
            "staged-deleted.txt": "Staged deletion baseline.\n",
            "syntax.json": "{\"value\":\"baseline\"}\n",
        ]
        for (path, contents) in baseline {
            try contents.write(to: changes.appendingPathComponent(path), atomically: true, encoding: .utf8)
        }
        try runGit(changes, "init", "--initial-branch=main")
        try runGit(changes, "config", "user.name", "Playhouse UI Test")
        try runGit(changes, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(changes, "add", ".")
        try runGit(changes, "commit", "-m", "Baseline")
        try "Staged index version.\n".write(to: changes.appendingPathComponent("staged.txt"), atomically: true, encoding: .utf8)
        try "Shared index version.\n".write(to: changes.appendingPathComponent("shared.txt"), atomically: true, encoding: .utf8)
        try "{\"value\":\"working version\"}\n".write(to: changes.appendingPathComponent("syntax.json"), atomically: true, encoding: .utf8)
        try runGit(changes, "add", "staged.txt", "shared.txt")
        try "Shared working version.\n".write(to: changes.appendingPathComponent("shared.txt"), atomically: true, encoding: .utf8)
        try "Working tree version.\n".write(to: changes.appendingPathComponent("working.txt"), atomically: true, encoding: .utf8)
        try FileManager.default.removeItem(at: changes.appendingPathComponent("deleted.txt"))
        try "Untracked file.\n".write(to: changes.appendingPathComponent("untracked.txt"), atomically: true, encoding: .utf8)
        try runGit(changes, "rm", "--quiet", "staged-deleted.txt")
        _ = try runCLI(["task", "create", "--title", "Mark all viewed", "--prompt", "Fixture task description.", "--root", changes.path])
        _ = try runCLI(["task", "create", "--title", "Clean changes", "--prompt", "Fixture task description.", "--root", cleanRepository.path])
        let taskID = try taskID(named: "Mark all viewed")
        let pendingPaths: Set<String> = ["deleted.txt", "shared.txt", "staged-deleted.txt", "staged.txt", "syntax.json", "untracked.txt", "working.txt"]

        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Mark all viewed")
        XCTAssertTrue(element("workspace-change-unviewed-shared.txt").waitForExistence(timeout: 10))
        XCTAssertTrue(element("mark-all-viewed-button").exists, "The Changes header offers Mark all as viewed while it lists files.")
        XCTAssertFalse(element("mark-unviewed-shared.txt").exists, "Changes entries offer mark-viewed, not unview.")
        attachScreenshot(named: "The Changes header offers Mark all as viewed")

        element("mark-all-viewed-button").click()
        var inventory: [String: Any]?
        XCTAssertTrue(waitUntil({
            inventory = try? self.runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
            return (inventory?["unviewed"] as? [[String: Any]])?.isEmpty == true
        }, timeout: 15), "Mark all as viewed should leave nothing pending.")
        XCTAssertEqual(Set(((inventory?["viewed"] as? [[String: Any]]) ?? []).compactMap { $0["path"] as? String }), pendingPaths)
        XCTAssertEqual(
            try runGitOutput(changes, "status", "--porcelain", "--", "untracked.txt").trimmingCharacters(in: .whitespacesAndNewlines),
            "A  untracked.txt",
            "Mark all as viewed should stage each file."
        )
        XCTAssertEqual(
            try runGitOutput(changes, "status", "--porcelain", "--", "staged-deleted.txt").trimmingCharacters(in: .whitespacesAndNewlines),
            "D  staged-deleted.txt",
            "An already staged deletion is accepted and stays staged."
        )
        XCTAssertTrue(element("workspace-change-unviewed-shared.txt").waitForNonExistence(timeout: 10))
        XCTAssertFalse(element("mark-all-viewed-button").exists, "With nothing pending, the header no longer offers Mark all as viewed.")
        element("viewed-changes-section").click()
        XCTAssertTrue(element("workspace-change-viewed-shared.txt").waitForExistence(timeout: 10))
        for path in pendingPaths {
            XCTAssertTrue(element("workspace-change-viewed-\(path)").exists, "\(path) should be listed under Viewed.")
            XCTAssertTrue(element("mark-unviewed-\(path)").exists, "Each Viewed entry offers Mark as unviewed.")
        }
        XCTAssertFalse(element("mark-viewed-shared.txt").exists)
        attachScreenshot(named: "Every file is listed under Viewed with an unview action")

        element("mark-unviewed-shared.txt").click()
        XCTAssertTrue(element("workspace-change-unviewed-shared.txt").waitForExistence(timeout: 10), "Unviewing lists the file under Changes again.")
        XCTAssertTrue(element("workspace-change-viewed-shared.txt").waitForNonExistence(timeout: 10))
        XCTAssertTrue(element("mark-viewed-shared.txt").exists)
        XCTAssertTrue(element("mark-all-viewed-button").exists)
        let afterUnview = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        let pendingAfterUnview = (afterUnview?["unviewed"] as? [[String: Any]]) ?? []
        XCTAssertEqual(pendingAfterUnview.compactMap { $0["path"] as? String }, ["shared.txt"])
        XCTAssertEqual(pendingAfterUnview.first?["hasViewedSnapshot"] as? Bool, false)
        XCTAssertEqual((afterUnview?["viewed"] as? [[String: Any]])?.count, pendingPaths.count - 1)
        XCTAssertEqual(
            try runGitOutput(changes, "status", "--porcelain", "--", "shared.txt").trimmingCharacters(in: .whitespacesAndNewlines),
            "M  shared.txt",
            "Unviewing leaves the Git index as it was."
        )
        element("workspace-change-unviewed-shared.txt").click()
        XCTAssertTrue(element("workspace-diff-overlay").waitForExistence(timeout: 10))
        assertText("workspace-diff-source", equals: "review-parent/changes · Since branch base")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertTrue(element("workspace-diff-overlay").waitForNonExistence(timeout: 2))
        attachScreenshot(named: "An unviewed file is listed under Changes again")
        assertCLIError(
            try runCLI(["task", "changes", "mark-unviewed", taskID, "--repository", changes.path, "--path", "shared.txt"], expectedStatus: 3),
            code: "not_found"
        )
        assertCLIError(
            try runCLI(["task", "changes", "mark-unviewed", taskID, "--repository", changes.path, "--path", "missing.txt"], expectedStatus: 3),
            code: "not_found"
        )

        // The Changes section collapses inside the sidebar, which stays open for other sections.
        assertText("toggle-workspace-changes-section-button", equals: "Expanded")
        element("toggle-workspace-changes-section-button").click()
        XCTAssertTrue(element("workspace-change-unviewed-shared.txt").waitForNonExistence(timeout: 5), "Collapsing the Changes section hides its lists.")
        XCTAssertFalse(element("unviewed-changes-section").exists)
        XCTAssertFalse(element("viewed-changes-section").exists)
        XCTAssertTrue(element("task-sidebar").exists, "Collapsing the section keeps the sidebar open.")
        XCTAssertFalse(element("task-sidebar-collapsed").exists)
        assertText("workspace-changes-title", equals: "Changes")
        assertText("toggle-workspace-changes-section-button", equals: "Collapsed")
        assertText("collapsed-workspace-changes-section-count", equals: "Changes to review: 1")
        XCTAssertGreaterThan(element("task-sidebar").frame.width, 200)
        attachScreenshot(named: "The collapsed Changes section keeps its header and pending count")

        openTask(named: "Clean changes")
        XCTAssertTrue(element("workspace-changes-title").waitForExistence(timeout: 10))
        assertText("toggle-workspace-changes-section-button", equals: "Collapsed")
        XCTAssertFalse(element("workspace-changes-empty").exists, "The collapsed section state is global, so another task opens with it collapsed.")
        XCTAssertFalse(element("collapsed-workspace-changes-section-count").exists, "A task with nothing pending shows no count.")
        element("workspace-changes-title").click()
        XCTAssertTrue(element("workspace-changes-empty").waitForExistence(timeout: 10), "Clicking the section title expands it.")
        assertText("toggle-workspace-changes-section-button", equals: "Expanded")

        // Every refresh used to swap No changes for the loading placeholder while Git ran.
        var sawLoadingPlaceholder = false
        for _ in 0..<3 {
            element("refresh-workspace-changes-button").click()
            let deadline = Date().addingTimeInterval(0.6)
            while Date() < deadline {
                if element("workspace-changes-loading").exists || !element("workspace-changes-empty").exists {
                    sawLoadingPlaceholder = true
                }
            }
        }
        XCTAssertFalse(sawLoadingPlaceholder, "Refreshing a loaded task must keep No changes on screen instead of flashing the loading placeholder.")
        attachScreenshot(named: "No changes stays on screen across refreshes")

        // Separately, the whole sidebar hides to a narrow rail.
        element("hide-task-sidebar-button").click()
        XCTAssertTrue(element("task-sidebar-collapsed").waitForExistence(timeout: 5), "The sidebar hides to a narrow rail.")
        XCTAssertFalse(element("workspace-changes-title").exists)
        XCTAssertFalse(element("collapsed-task-sidebar-count").exists, "A task with nothing pending shows no count.")
        XCTAssertLessThan(element("task-sidebar-collapsed").frame.width, 60)

        openTask(named: "Mark all viewed")
        XCTAssertTrue(element("task-sidebar-collapsed").waitForExistence(timeout: 10), "The hidden sidebar state is global, so another task opens with it hidden.")
        assertText("collapsed-task-sidebar-count", equals: "Changes to review: 1")
        attachScreenshot(named: "The hidden sidebar keeps the pending count")
        element("show-task-sidebar-button").click()
        XCTAssertTrue(element("workspace-changes-title").waitForExistence(timeout: 10))
        XCTAssertFalse(element("task-sidebar-collapsed").exists)
        assertText("toggle-workspace-changes-section-button", equals: "Expanded")
        XCTAssertTrue(
            element("workspace-change-unviewed-shared.txt").waitForExistence(timeout: 10),
            "Expanding the section in one task expands it everywhere."
        )
    }

    // case-contract: test_external_git_edits_and_commit_refresh_workspace_changes | A newly created task branch with no branch or worktree changes starts with empty Viewed and Changes sections. External Git commits unique to the task branch and staged, unstaged, or untracked edits update the open task's Changes sidebar automatically; commits unique to the base branch are excluded. Fresh CLI connections report the same per-file inventory. When the base branch's local copy is stale behind its origin remote-tracking branch and the task branch has merged the newer upstream commits, those commits are excluded as well, so the inventory matches the pull request instead of the stale local branch. A local base branch that is ahead of its remote-tracking branch stays the base, so unpushed base commits merged into the task branch are not listed as task changes. While a merge is still open in the task's worktree, its files are held back and the sidebar shows a 'Merge in progress' notice naming the repository instead of the files the merge staged; the CLI reports the repository under mergingRepositories with empty sections, and aborting the merge lists the task's changes again.
    func test_external_git_edits_and_commit_refresh_workspace_changes() throws {
        let repository = runDirectory.appendingPathComponent("external-git", isDirectory: true)
        try FileManager.default.createDirectory(at: repository, withIntermediateDirectories: true)
        let trackedFile = repository.appendingPathComponent("tracked.txt")
        try "Baseline.\n".write(to: trackedFile, atomically: true, encoding: .utf8)
        try runGit(repository, "init", "--initial-branch=main")
        try runGit(repository, "config", "user.name", "Playhouse UI Test")
        try runGit(repository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(repository, "add", "tracked.txt")
        try runGit(repository, "commit", "-m", "Baseline")

        let created = try runCLI(["task", "create", "--title", "External Git", "--prompt", "Fixture task description."])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let added = try runCLI(["task", "repository", "add", taskID, "--repo", repository.path])
        let record = try XCTUnwrap(((added["result"] as? [String: Any])?["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(record["branchFrom"] as? String, "main")
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)

        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "External Git")
        XCTAssertTrue(element("workspace-changes-empty").waitForExistence(timeout: 10))
        let initialInventory = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((initialInventory?["unviewed"] as? [[String: Any]])?.count, 0)
        XCTAssertEqual((initialInventory?["viewed"] as? [[String: Any]])?.count, 0)

        let branchFile = worktree.appendingPathComponent("tracked.txt")
        try "Branch commit.\n".write(to: branchFile, atomically: true, encoding: .utf8)
        try runGit(worktree, "add", "tracked.txt")
        try runGit(worktree, "commit", "-m", "Task branch commit")
        let baseOnlyFile = repository.appendingPathComponent("base-only.txt")
        try "Base-only commit.\n".write(to: baseOnlyFile, atomically: true, encoding: .utf8)
        try runGit(repository, "add", "base-only.txt")
        try runGit(repository, "commit", "-m", "Base-only commit")

        XCTAssertTrue(element("workspace-change-unviewed-tracked.txt").waitForExistence(timeout: 10))
        XCTAssertFalse(element("workspace-change-unviewed-base-only.txt").exists)
        let branchInventory = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        let branchEntries = branchInventory?["unviewed"] as? [[String: Any]] ?? []
        XCTAssertEqual(branchEntries.map { $0["path"] as? String }, ["tracked.txt"])
        XCTAssertEqual(branchEntries.first?["isUncommitted"] as? Bool, false)
        XCTAssertEqual(element("workspace-change-unviewed-tracked.txt").value as? String, "Committed, primary")

        try "Edited externally.\n".write(to: branchFile, atomically: true, encoding: .utf8)
        try "Untracked external file.\n".write(to: worktree.appendingPathComponent("untracked.txt"), atomically: true, encoding: .utf8)
        XCTAssertTrue(element("workspace-change-unviewed-untracked.txt").waitForExistence(timeout: 10))
        XCTAssertTrue(element("workspace-change-unviewed-tracked.txt").waitForExistence(timeout: 10))
        let dirty = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((dirty?["unviewed"] as? [[String: Any]])?.map { $0["path"] as? String }, ["tracked.txt", "untracked.txt"])
        XCTAssertTrue((dirty?["unviewed"] as? [[String: Any]])?.allSatisfy { $0["isUncommitted"] as? Bool == true } ?? false)
        XCTAssertEqual(element("workspace-change-unviewed-tracked.txt").value as? String, "Uncommitted, green")

        try runGit(worktree, "add", "tracked.txt", "untracked.txt")
        try runGit(worktree, "commit", "-m", "Second task branch commit")
        let committed = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        let committedEntries = committed?["unviewed"] as? [[String: Any]] ?? []
        XCTAssertEqual(committedEntries.map { $0["path"] as? String }, ["tracked.txt", "untracked.txt"])
        XCTAssertTrue(committedEntries.allSatisfy { $0["isUncommitted"] as? Bool == false })
        XCTAssertTrue(waitUntil({ self.element("workspace-change-unviewed-tracked.txt").value as? String == "Committed, primary" }, timeout: 10))
        XCTAssertFalse(committedEntries.contains { $0["path"] as? String == "base-only.txt" })
        attachScreenshot(named: "Branch changes exclude base-only commits and retain task commits")

        // Upstream moves ahead of a stale local base branch, and the task branch merges it.
        let origin = runDirectory.appendingPathComponent("external-git-origin.git", isDirectory: true)
        try FileManager.default.createDirectory(at: origin, withIntermediateDirectories: true)
        try runGit(origin, "init", "--bare", "--initial-branch=main")
        try runGit(repository, "remote", "add", "origin", origin.path)
        try runGit(repository, "push", "origin", "main")
        try "Upstream commit.\n".write(to: repository.appendingPathComponent("upstream-only.txt"), atomically: true, encoding: .utf8)
        try runGit(repository, "add", "upstream-only.txt")
        try runGit(repository, "commit", "-m", "Upstream commit")
        try runGit(repository, "push", "origin", "main")
        try runGit(repository, "reset", "--hard", "HEAD~1")
        try runGit(worktree, "merge", "--no-edit", "origin/main")
        // A file written after the merge only appears once the sidebar has rescanned the merged
        // branch, so waiting for its row proves the absence check below runs against fresh state.
        try "Written after the merge.\n".write(to: worktree.appendingPathComponent("post-merge.txt"), atomically: true, encoding: .utf8)
        XCTAssertTrue(element("workspace-change-unviewed-post-merge.txt").waitForExistence(timeout: 10))
        let staleBase = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        let staleBaseEntries = staleBase?["unviewed"] as? [[String: Any]] ?? []
        XCTAssertEqual(staleBaseEntries.map { $0["path"] as? String }, ["post-merge.txt", "tracked.txt", "untracked.txt"])
        XCTAssertFalse(element("workspace-change-unviewed-upstream-only.txt").exists)

        // A local base branch that is ahead of origin holds work the task was started from, so it stays the base.
        try runGit(repository, "merge", "--ff-only", "origin/main")
        try "Local only.\n".write(to: repository.appendingPathComponent("local-ahead.txt"), atomically: true, encoding: .utf8)
        try runGit(repository, "add", "local-ahead.txt")
        try runGit(repository, "commit", "-m", "Unpushed local base commit")
        try runGit(worktree, "merge", "--no-edit", "main")
        try "Written after the local merge.\n".write(to: worktree.appendingPathComponent("post-ahead.txt"), atomically: true, encoding: .utf8)
        XCTAssertTrue(element("workspace-change-unviewed-post-ahead.txt").waitForExistence(timeout: 10))
        let aheadBase = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        let aheadBaseEntries = aheadBase?["unviewed"] as? [[String: Any]] ?? []
        XCTAssertEqual(aheadBaseEntries.map { $0["path"] as? String }, ["post-ahead.txt", "post-merge.txt", "tracked.txt", "untracked.txt"])
        XCTAssertFalse(element("workspace-change-unviewed-local-ahead.txt").exists)
        XCTAssertTrue(element("workspace-change-unviewed-tracked.txt").exists)
        attachScreenshot(named: "Merged upstream commits are excluded when the local base branch is stale")

        // An open merge stages everything the merged branch brings in, so the repository's files are
        // held back until the merge is concluded rather than listed as task changes.
        let taskRepository = try XCTUnwrap(aheadBaseEntries.first?["repository"] as? String)
        try "Merged with the merge still open.\n".write(to: repository.appendingPathComponent("merging-in.txt"), atomically: true, encoding: .utf8)
        try runGit(repository, "add", "merging-in.txt")
        try runGit(repository, "commit", "-m", "Base commit merged without committing")
        try runGit(worktree, "merge", "--no-commit", "--no-ff", "main")
        let mergeNotice = element("workspace-changes-merge-in-progress")
        XCTAssertTrue(mergeNotice.waitForExistence(timeout: 10))
        let mergingRepositoryLabel = URL(fileURLWithPath: taskRepository).pathComponents.suffix(2).joined(separator: "/")
        XCTAssertTrue(mergeNotice.label.contains(mergingRepositoryLabel), "The merge notice should name the merging repository: \(mergeNotice.label)")
        XCTAssertFalse(element("workspace-change-unviewed-tracked.txt").exists)
        XCTAssertFalse(element("workspace-change-unviewed-merging-in.txt").exists)
        let merging = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((merging?["unviewed"] as? [[String: Any]])?.count, 0)
        XCTAssertEqual((merging?["viewed"] as? [[String: Any]])?.count, 0)
        XCTAssertEqual(merging?["mergingRepositories"] as? [String], [taskRepository])
        attachScreenshot(named: "An open merge hides the files it staged")

        try runGit(worktree, "merge", "--abort")
        XCTAssertTrue(element("workspace-change-unviewed-tracked.txt").waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({ !mergeNotice.exists }, timeout: 10))
        let aborted = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual(aborted?["mergingRepositories"] as? [String], [])
        XCTAssertEqual(Set((aborted?["unviewed"] as? [[String: Any]] ?? []).compactMap { $0["path"] as? String }), ["post-ahead.txt", "post-merge.txt", "tracked.txt", "untracked.txt"])
    }

    // case-contract: test_task_workspace_changes_over_limit_show_notice | A task whose worktree holds more than 1000 changed files still reports every one of them through fresh CLI connections, while the open task's Changes sidebar shows a 'Too many changes to list' notice naming the count instead of rendering the file list, so the window stays responsive. Bringing the count back under the limit lists the files again.
    func test_task_workspace_changes_over_limit_show_notice() throws {
        let repository = runDirectory.appendingPathComponent("many-changes", isDirectory: true)
        try FileManager.default.createDirectory(at: repository, withIntermediateDirectories: true)
        try "Baseline.\n".write(to: repository.appendingPathComponent("tracked.txt"), atomically: true, encoding: .utf8)
        try runGit(repository, "init", "--initial-branch=main")
        try runGit(repository, "config", "user.name", "Playhouse UI Test")
        try runGit(repository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(repository, "add", "tracked.txt")
        try runGit(repository, "commit", "-m", "Baseline")

        let created = try runCLI(["task", "create", "--title", "Many changes", "--prompt", "Fixture task description."])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let added = try runCLI(["task", "repository", "add", taskID, "--repo", repository.path])
        let record = try XCTUnwrap(((added["result"] as? [String: Any])?["repositoryWorktrees"] as? [[String: Any]])?.first)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
        let generated = worktree.appendingPathComponent("generated", isDirectory: true)
        try FileManager.default.createDirectory(at: generated, withIntermediateDirectories: true)
        for index in 0..<1001 {
            try "Generated \(index).\n".write(to: generated.appendingPathComponent(String(format: "file-%04d.txt", index)), atomically: true, encoding: .utf8)
        }

        launchApp(defaultParent: fixture.parent.path)
        openTask(named: "Many changes")
        let notice = element("workspace-changes-too-many")
        XCTAssertTrue(notice.waitForExistence(timeout: 15))
        XCTAssertTrue(notice.label.contains("1001 changed files"), "The notice should name the count: \(notice.label)")
        XCTAssertFalse(element("workspace-changes-list").exists, "The file list must not render over the limit.")
        let inventory = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((inventory?["unviewed"] as? [[String: Any]])?.count, 1001, "The limit only affects the sidebar; the CLI still reports every file.")
        XCTAssertEqual((inventory?["viewed"] as? [[String: Any]])?.count, 0)
        attachScreenshot(named: "Over 1000 changed files shows a notice instead of the list")

        try FileManager.default.removeItem(at: generated.appendingPathComponent("file-1000.txt"))
        XCTAssertTrue(element("workspace-changes-list").waitForExistence(timeout: 15))
        XCTAssertTrue(waitUntil({ !notice.exists }, timeout: 10))
        let underLimit = try runCLI(["task", "changes", "list", taskID])["result"] as? [String: Any]
        XCTAssertEqual((underLimit?["unviewed"] as? [[String: Any]])?.count, 1000)
        attachScreenshot(named: "At the limit the files are listed again")
    }

    // case-contract: test_task_terminal_opens_shell_in_task_worktree | Each task's sidebar ends in a command row whose buttons sit at its right edge; it holds a terminal button. The terminal only ever opens in the task's created repository worktree, never in its source repository or a context folder, and never creates a worktree itself: while the task's worktree is still pending, or the task has no repository, the button is disabled and the CLI reports terminal_unavailable without creating the worktree, and the button enables in the open conversation once the worktree is created. The CLI reports how the terminal starts: the account's executable login shell with -l in that worktree, with TERM=xterm-256color and PLAYHOUSE_TASK_ID set, and the same answer on a fresh CLI/XPC connection; running that shell in that folder prints the worktree path and the task ID. Clicking the button slides a terminal panel in from the window's right edge, floating over the conversation's right side without moving or resizing the conversation, whose shell runs in the task's worktree with the task ID in its environment and which uses macOS Terminal's Clear Dark ANSI palette (such as its blue, distinct from the emulator's own default) on a solid black background, switching to the Clear Light profile's white background and blue when the app's appearance turns light and back when it returns to dark; hiding the panel keeps the same shell, so reopening it reaches the same process. Dragging the panel's left border resizes it against the right edge, between a 320-point minimum and leaving 260 points of conversation uncovered, without resizing the conversation, and reopening the panel keeps the dragged width. Typing exit shows that the shell exited, and Restart starts a new shell, with a different process, in the same worktree. A task whose worktree no longer exists reports terminal_unavailable from the CLI, and the panel shows that error with a Try Again action that opens the shell once the worktree is back; an unknown task ID and the standalone chat's ID are not_found, and the standalone chat offers no terminal button.
    func test_task_terminal_opens_shell_in_task_worktree() throws {
        let repository = runDirectory.appendingPathComponent("terminal-repository", isDirectory: true)
        try FileManager.default.createDirectory(at: repository, withIntermediateDirectories: true)
        try "Terminal fixture.\n".write(to: repository.appendingPathComponent("README.md"), atomically: true, encoding: .utf8)
        try runGit(repository, "init", "--initial-branch=main")
        try runGit(repository, "config", "user.name", "Playhouse UI Test")
        try runGit(repository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(repository, "add", "README.md")
        try runGit(repository, "commit", "-m", "Baseline")
        let secondRepository = runDirectory.appendingPathComponent("terminal-second-repository", isDirectory: true)
        try FileManager.default.createDirectory(at: secondRepository, withIntermediateDirectories: true)
        try "Second fixture.\n".write(to: secondRepository.appendingPathComponent("README.md"), atomically: true, encoding: .utf8)
        try runGit(secondRepository, "init", "--initial-branch=main")
        try runGit(secondRepository, "config", "user.name", "Playhouse UI Test")
        try runGit(secondRepository, "config", "user.email", "playhouse-ui-test@example.invalid")
        try runGit(secondRepository, "add", "README.md")
        try runGit(secondRepository, "commit", "-m", "Baseline")

        // A task whose worktree is created: a titled task prepares it as soon as its repository is added.
        let created = try runCLI(["task", "create", "--title", "Terminal Task", "--prompt", "Fixture task description."])
        let taskID = try XCTUnwrap((created["result"] as? [String: Any])?["id"] as? String)
        let added = try runCLI(["task", "repository", "add", taskID, "--repo", repository.path])
        let record = try XCTUnwrap(((added["result"] as? [String: Any])?["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(record["isPending"] as? Bool, false)
        let worktree = URL(fileURLWithPath: try XCTUnwrap(record["worktreePath"] as? String), isDirectory: true)
        let launch = try XCTUnwrap(try runCLI(["task", "terminal", taskID])["result"] as? [String: Any])
        XCTAssertEqual(launch["directory"] as? String, worktree.standardizedFileURL.path)
        XCTAssertEqual((launch["environment"] as? [String: String])?["PLAYHOUSE_TASK_ID"], taskID)

        // A task whose worktree is still pending: named and created only when the task starts.
        let pendingCreated = try runCLI([
            "task", "create", "--title", "Pending Terminal Task", "--prompt", "Fixture task description.", "--repo", repository.path
        ])
        let pendingTaskID = try XCTUnwrap((pendingCreated["result"] as? [String: Any])?["id"] as? String)
        let folder = runDirectory.appendingPathComponent("terminal-folder", isDirectory: true)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        _ = try runCLI(["task", "create", "--title", "No Repository Terminal", "--prompt", "Fixture task description.", "--root", folder.path])

        launchApp(defaultParent: fixture.parent.path)
        let toggle = element("toggle-terminal-button")
        func worktreeRecord(_ id: String) throws -> [String: Any] {
            try XCTUnwrap(((try taskRecord(id: id))?["repositoryWorktrees"] as? [[String: Any]])?.first)
        }

        openTask(named: "Pending Terminal Task")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertFalse(toggle.isEnabled, "The terminal button stays disabled until the task's worktree is created.")
        toggle.click()
        XCTAssertFalse(element("task-terminal-panel").exists, "A disabled button opens no panel.")
        XCTAssertEqual(try worktreeRecord(pendingTaskID)["isPending"] as? Bool, true, "Clicking it does not create the worktree.")
        attachScreenshot(named: "Terminal button disabled until the task's worktree exists")
        // Creating the worktree, as a task's start does, enables the button in the open conversation.
        _ = try runCLI(["task", "repository", "add", pendingTaskID, "--repo", secondRepository.path])
        XCTAssertEqual(try worktreeRecord(pendingTaskID)["isPending"] as? Bool, false)
        XCTAssertTrue(waitUntil({ toggle.isEnabled }, timeout: 10), "The button enables once the worktree exists.")

        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: "No Repository Terminal")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertFalse(toggle.isEnabled, "A task with no repository has no worktree, so no terminal.")

        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        openTask(named: "Terminal Task")
        let sidebar = element("task-sidebar")
        let commandRow = element("sidebar-command-row")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertTrue(toggle.isEnabled)
        XCTAssertTrue(commandRow.exists)
        XCTAssertEqual(toggle.value as? String, "Hidden")
        XCTAssertFalse(element("task-terminal-panel").exists, "The terminal stays hidden until the button opens it.")
        // The row's accessibility frame spans only its buttons, so placement is measured against the sidebar.
        XCTAssertTrue(commandRow.buttons["toggle-terminal-button"].exists, "The terminal button belongs to the command row.")
        XCTAssertTrue(element("workspace-changes-empty").waitForExistence(timeout: 10))
        XCTAssertGreaterThan(toggle.frame.minY, element("workspace-changes-empty").frame.maxY, "The command row sits below the Changes list.")
        XCTAssertEqual(toggle.frame.maxY, sidebar.frame.maxY, accuracy: 10, "The command row is the sidebar's bottom row.")
        XCTAssertEqual(toggle.frame.maxX, sidebar.frame.maxX, accuracy: 14, "Command row buttons align to the right.")
        XCTAssertGreaterThan(toggle.frame.minX, sidebar.frame.midX, "The terminal button sits on the right half of the sidebar.")
        attachScreenshot(named: "Sidebar command row with the terminal button on the right")

        let window = app.windows.firstMatch
        let conversation = element("empty-conversation")
        XCTAssertTrue(conversation.exists)
        XCTAssertGreaterThan(conversation.frame.maxX, window.frame.maxX - 470, "Before the panel opens, the conversation reaches into the space the panel will take.")
        let conversationFrameBefore = conversation.frame
        toggle.click()
        let panel = element("task-terminal-panel")
        XCTAssertTrue(panel.waitForExistence(timeout: 5))
        XCTAssertTrue(waitUntil({ abs(panel.frame.maxX - window.frame.maxX) <= 2 }, timeout: 5), "The panel settles against the window's right edge.")
        XCTAssertGreaterThan(panel.frame.minX, sidebar.frame.maxX, "The panel opens on the right, leaving the sidebar in place.")
        XCTAssertLessThan(panel.frame.minX, conversation.frame.maxX, "The panel floats over the conversation's right side.")
        XCTAssertEqual(conversation.frame.minX, conversationFrameBefore.minX, accuracy: 1, "Opening the terminal does not move the conversation.")
        XCTAssertEqual(conversation.frame.width, conversationFrameBefore.width, accuracy: 1, "Opening the terminal does not resize the conversation.")
        XCTAssertEqual(toggle.value as? String, "Shown")
        assertText("task-terminal-title", equals: "Terminal")

        let terminal = element("task-terminal-view")
        XCTAssertTrue(terminal.waitForExistence(timeout: 10))
        XCTAssertNotEqual(worktree.standardizedFileURL.path, repository.standardizedFileURL.path, "The terminal never opens in the source repository.")
        terminal.click()
        // `pwd -P` keeps the /private prefix that Foundation's symlink resolution drops for /tmp.
        let resolvedWorktree = try XCTUnwrap(realpath(worktree.path, nil).map { pointer in
            defer { free(pointer) }
            return String(cString: pointer)
        })
        terminal.typeText("cd . && printf 'dir=%s task=%s pid=%s;\\n' \"$(pwd -P)\" \"$PLAYHOUSE_TASK_ID\" \"$$\"\n")
        let expectedPrefix = "dir=\(resolvedWorktree) task=\(taskID) pid="
        var shellPID = ""
        XCTAssertTrue(waitUntil({
            guard let pid = self.terminalNumber(after: expectedPrefix, in: terminal) else { return false }
            shellPID = pid
            return true
        }, timeout: 20), "The shell runs in the task worktree with the task ID: \(String(reflecting: terminal.value as? String ?? ""))")
        // Clear Dark's ANSI blue #6D96B4 (the emulator's own is #492EE1) on a solid black
        // background. Clear Light: blue #5685A8 on 93%-opaque white, within the pixel tolerance.
        terminal.typeText("printf '\\033[44m%24s\\033[0m\\n' ''\n")
        XCTAssertTrue(waitUntil({
            self.screenshotContains(srgb: (0x6D, 0x96, 0xB4), in: terminal)
        }, timeout: 10), "ANSI blue renders in Clear Dark's blue.")
        XCTAssertFalse(screenshotContains(srgb: (0x49, 0x2E, 0xE1), in: terminal), "The emulator's own default blue is replaced.")
        XCTAssertTrue(screenshotContains(srgb: (0x00, 0x00, 0x00), in: terminal, tolerance: 3), "The terminal uses a black background.")
        attachScreenshot(named: "Terminal slid in from the right, running in the task worktree")

        _ = try runCLI(["settings", "set-appearance", "light"])
        XCTAssertTrue(waitUntil({
            self.screenshotContains(srgb: (0x56, 0x85, 0xA8), in: terminal)
                && !self.screenshotContains(srgb: (0x00, 0x00, 0x00), in: terminal, tolerance: 3)
        }, timeout: 10), "Light appearance switches the terminal to Clear Light's colors.")
        XCTAssertTrue(screenshotContains(srgb: (0xFF, 0xFF, 0xFF), in: terminal), "Clear Light uses a white background.")
        attachScreenshot(named: "Terminal in light appearance uses the Clear Light profile")
        _ = try runCLI(["settings", "set-appearance", "dark"])
        XCTAssertTrue(waitUntil({
            self.screenshotContains(srgb: (0x00, 0x00, 0x00), in: terminal, tolerance: 3)
        }, timeout: 10), "Returning to dark appearance restores the black background.")
        terminal.click()

        element("close-terminal-button").click()
        XCTAssertTrue(waitUntil({ !panel.exists }, timeout: 5), "Hide slides the panel away.")
        XCTAssertEqual(toggle.value as? String, "Hidden")
        toggle.click()
        XCTAssertTrue(terminal.waitForExistence(timeout: 5))
        terminal.click()
        terminal.typeText("printf 'again=%s;\\n' \"$$\"\n")
        XCTAssertTrue(waitUntil({
            self.terminalNumber(after: "again=", in: terminal) == shellPID
        }, timeout: 20), "Reopening the panel reaches the same shell: \(String(reflecting: terminal.value as? String ?? ""))")
        attachScreenshot(named: "Reopened terminal keeps the same shell session")

        // Dragging the left border resizes the panel, within limits, and the width is remembered.
        let handle = element("terminal-resize-handle")
        XCTAssertTrue(handle.waitForExistence(timeout: 5))
        XCTAssertEqual(handle.frame.midX, panel.frame.minX, accuracy: 6, "The resize handle is the panel's left border.")
        let widthBefore = panel.frame.width
        let conversationBeforeResize = conversation.frame
        handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
            .press(forDuration: 0.2, thenDragTo: handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).withOffset(CGVector(dx: -50, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(panel.frame.width - (widthBefore + 50)) <= 6 }, timeout: 5), "Dragging left widens the panel: \(panel.frame.width)")
        XCTAssertEqual(abs(panel.frame.maxX - window.frame.maxX), 0, accuracy: 2, "The panel stays against the right edge.")
        XCTAssertEqual(conversation.frame.width, conversationBeforeResize.width, accuracy: 1, "Resizing does not resize the conversation.")
        let widened = panel.frame.width
        attachScreenshot(named: "Terminal widened by dragging its left border")
        element("close-terminal-button").click()
        XCTAssertTrue(waitUntil({ !panel.exists }, timeout: 5))
        toggle.click()
        XCTAssertTrue(waitUntil({ panel.exists && abs(panel.frame.width - widened) <= 2 }, timeout: 5), "Reopening keeps the dragged width.")
        handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
            .press(forDuration: 0.2, thenDragTo: handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).withOffset(CGVector(dx: 900, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(panel.frame.width - 320) <= 3 }, timeout: 5), "The panel stops at its minimum width: \(panel.frame.width)")
        handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
            .press(forDuration: 0.2, thenDragTo: handle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).withOffset(CGVector(dx: -3000, dy: 0)))
        XCTAssertTrue(waitUntil({ abs(panel.frame.minX - (sidebar.frame.maxX + 1 + 260)) <= 4 }, timeout: 5),
                      "The panel stops where 260 points of conversation stay uncovered: \(panel.frame.minX)")
        XCTAssertTrue(terminal.exists)
        terminal.click()

        terminal.typeText("exit\n")
        let exitStatus = element("task-terminal-exit-status")
        XCTAssertTrue(exitStatus.waitForExistence(timeout: 10), "Exiting the shell is reported in the panel.")
        let exitText = exitStatus.value as? String ?? exitStatus.label
        XCTAssertTrue(exitText.hasPrefix("Shell exited"), exitText)
        attachScreenshot(named: "Terminal reports the shell exited and offers Restart")
        element("restart-terminal-button").click()
        XCTAssertTrue(waitUntil({ !exitStatus.exists }, timeout: 5), "Restart clears the exit report.")
        XCTAssertTrue(terminal.waitForExistence(timeout: 5))
        terminal.click()
        terminal.typeText("printf 'dir=%s task=%s pid=%s;\\n' \"$(pwd -P)\" \"$PLAYHOUSE_TASK_ID\" \"$$\"\n")
        var restartedPID = ""
        XCTAssertTrue(waitUntil({
            guard let pid = self.terminalNumber(after: expectedPrefix, in: terminal) else { return false }
            restartedPID = pid
            return true
        }, timeout: 20), "The restarted shell runs in the task worktree: \(String(reflecting: terminal.value as? String ?? ""))")
        XCTAssertNotEqual(restartedPID, shellPID, "Restart starts a new shell process.")
        toggle.click()
        XCTAssertTrue(waitUntil({ !panel.exists }, timeout: 5), "The sidebar button also hides the panel.")

        // A worktree that is missing shows an error with Try Again, which recovers once it is back.
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        // The terminal falls back to a task's next existing worktree, so every one is moved aside.
        let pendingWorktrees = try XCTUnwrap(
            (try taskRecord(id: pendingTaskID))?["repositoryWorktrees"] as? [[String: Any]]
        ).compactMap { $0["worktreePath"] as? String }
        XCTAssertEqual(pendingWorktrees.count, 2)
        let pendingWorktree = try XCTUnwrap(pendingWorktrees.first)
        for path in pendingWorktrees {
            try FileManager.default.moveItem(at: URL(fileURLWithPath: path, isDirectory: true), to: URL(fileURLWithPath: path + "-moved", isDirectory: true))
        }
        openTask(named: "Pending Terminal Task")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertTrue(toggle.isEnabled)
        toggle.click()
        XCTAssertTrue(element("task-terminal-error").waitForExistence(timeout: 10))
        let errorMessage = element("task-terminal-error-message")
        let errorText = errorMessage.value as? String ?? errorMessage.label
        XCTAssertTrue(errorText.contains("no longer exists"), errorText)
        XCTAssertFalse(terminal.exists, "No shell starts without the worktree.")
        attachScreenshot(named: "Terminal panel reports a missing worktree and offers Try Again")
        for path in pendingWorktrees {
            try FileManager.default.moveItem(at: URL(fileURLWithPath: path + "-moved", isDirectory: true), to: URL(fileURLWithPath: path, isDirectory: true))
        }
        element("retry-terminal-button").click()
        XCTAssertTrue(terminal.waitForExistence(timeout: 10), "Try Again starts a shell once the worktree is back.")
        XCTAssertFalse(element("task-terminal-error").exists)
        XCTAssertNotEqual(pendingWorktree, repository.standardizedFileURL.path)
        let resolvedPendingWorktree = try XCTUnwrap(realpath(pendingWorktree, nil).map { pointer in
            defer { free(pointer) }
            return String(cString: pointer)
        })
        terminal.click()
        terminal.typeText("printf 'dir=%s pid=%s;\\n' \"$(pwd -P)\" \"$$\"\n")
        XCTAssertTrue(waitUntil({
            self.terminalNumber(after: "dir=\(resolvedPendingWorktree) pid=", in: terminal) != nil
        }, timeout: 20), "The retried shell runs in the task's worktree: \(String(reflecting: terminal.value as? String ?? ""))")
        attachScreenshot(named: "Try Again opens the shell once the worktree is back")

        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        element("chat-sidebar-button").click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10))
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 10))
        XCTAssertFalse(toggle.exists, "The standalone chat has no task sidebar, so no terminal button.")
    }

    // Scheduled tasks fire through ConversationManager.send, the path Send takes for both
    // providers, so the schedule behavior is provider-agnostic and Claude's fixture stands for both.
    private func scheduleISO(_ date: Date) -> String {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime]
        return formatter.string(from: date)
    }

    private func scheduleDate(_ text: String?) -> Date? {
        text.flatMap { ISO8601DateFormatter().date(from: $0) }
    }

    private func claudeFixturePrompts() -> [String] {
        guard let executable = claudeFixtureExecutable,
              let data = FileManager.default.contents(atPath: executable + ".history"),
              let history = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let turns = history["turns"] as? [[String: Any]] else { return [] }
        return turns.compactMap { $0["userText"] as? String }
    }

    private func replaceComposerText(with text: String) {
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 15), "The task should open its composer.")
        composer.click()
        composer.typeKey("a", modifierFlags: .command)
        composer.typeText(text)
    }

    private func openScheduleHint() -> XCUIElement {
        let button = element("schedule-task-button")
        XCTAssertTrue(waitUntil({ button.exists && button.isHittable }, timeout: 10), "The composer should offer the schedule button beside Send.")
        button.click()
        let hint = element("schedule-hint")
        XCTAssertTrue(hint.waitForExistence(timeout: 5), "The schedule button should open its hint.")
        return hint
    }

    private func clickScheduledTaskMenuItem(taskID: String, item identifier: String, title: String) {
        let actions = element("scheduled-task-actions-\(taskID)")
        XCTAssertTrue(actions.waitForExistence(timeout: 10), "The scheduled task row should have an actions menu.")
        actions.click()
        let byIdentifier = app.menuItems.matching(identifier: identifier).firstMatch
        let item = byIdentifier.waitForExistence(timeout: 3) ? byIdentifier : app.menuItems[title]
        XCTAssertTrue(item.waitForExistence(timeout: 3), "\(title) should be in the row's menu.")
        item.click()
    }

    // case-contract: test_schedule_one_time_task_fires_when_due | A task whose conversation hasn't started is scheduled once (the composer's schedule hint, or schedule set --once); scheduling saves the prompt as the schedule's own payload without starting a turn, keeps the task in Backlog with a clock badge, and lists it in schedule list. Removing the schedule in the hint before Send turns the clock button off and returns Send to sending. A time in the past or a blank prompt is rejected with invalid_argument. A tick before the time does nothing; a tick 30 minutes after it, inside the one-hour grace period, sends the scheduled prompt to the provider, clears the schedule, and the task follows the ordinary board lifecycle. A second tick doesn't run it again, and a task that has started can't be scheduled. The app bundle carries the scheduler LaunchAgent (<bundle-id>.scheduler.plist running playhouse-cli schedule tick every 60 seconds), and a plain tick on the real clock fires a schedule that has come due.
    func test_schedule_one_time_task_fires_when_due() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-schedule-once")
        launchApp(defaultParent: fixture.parent.path)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Scheduled once", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        openTask(named: "Scheduled once")
        replaceComposerText(with: "Tell me a story.")
        let send = element("send-message-button")
        XCTAssertEqual(send.label, "Send message", "Send sends until a schedule is set.")
        let scheduleButton = element("schedule-task-button")
        XCTAssertEqual(scheduleButton.value as? String, "Off")

        _ = openScheduleHint()
        XCTAssertTrue(element("schedule-date-picker").exists, "A one-time schedule picks a date and time.")
        XCTAssertFalse(element("schedule-title-field").exists, "Only a recurring schedule asks for a title.")
        attachScreenshot(named: "Schedule hint for a one-time run")
        element("schedule-done-button").click()
        XCTAssertTrue(waitForDisappearance(element("schedule-hint")))
        XCTAssertTrue(waitUntil({ send.label == "Schedule task" }, timeout: 5), "Send switches to schedule mode once the hint is done.")
        XCTAssertEqual(scheduleButton.value as? String, "On")
        XCTAssertNil(try taskRecord(id: taskID)?["schedule"] as? [String: Any], "Nothing is saved until Send confirms the schedule.")
        attachScreenshot(named: "Send in schedule mode with the schedule button on")

        _ = openScheduleHint()
        element("schedule-remove-button").click()
        XCTAssertTrue(waitForDisappearance(element("schedule-hint")))
        XCTAssertTrue(waitUntil({ send.label == "Send message" }, timeout: 5), "Removing the schedule returns Send to sending.")
        XCTAssertEqual(scheduleButton.value as? String, "Off")
        attachScreenshot(named: "Removing the schedule turns the clock off and Send back to sending")
        _ = openScheduleHint()
        element("schedule-done-button").click()
        XCTAssertTrue(waitUntil({ send.label == "Schedule task" }, timeout: 5))

        send.click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10), "Scheduling returns to the board.")
        let badge = element("task-schedule-badge-\(taskID)")
        XCTAssertTrue(badge.waitForExistence(timeout: 10), "A one-time scheduled task stays on the board with a clock badge.")
        let record = try XCTUnwrap(taskRecord(id: taskID))
        XCTAssertEqual(record["status"] as? String, "Backlog")
        let schedule = try XCTUnwrap(record["schedule"] as? [String: Any])
        XCTAssertEqual(schedule["kind"] as? String, "once")
        XCTAssertEqual(schedule["prompt"] as? String, "Tell me a story.")
        XCTAssertEqual(claudeFixturePrompts(), [], "Scheduling starts no turn.")
        attachScreenshot(named: "Board shows the scheduled task with its clock badge")

        assertCLIError(
            try runCLI(["schedule", "set", taskID, "--prompt", "Tell me a story.", "--once", scheduleISO(Date().addingTimeInterval(-300))], expectedStatus: 2),
            code: "invalid_argument"
        )
        assertCLIError(
            try runCLI(["schedule", "set", taskID, "--prompt", "  ", "--once", scheduleISO(Date().addingTimeInterval(7200))], expectedStatus: 2),
            code: "invalid_argument"
        )
        let fireAt = try XCTUnwrap(scheduleDate(schedule["scheduledAt"] as? String))
        let early = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(fireAt.addingTimeInterval(-600))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((early["fired"] as? [Any])?.count, 0, "Nothing runs before its time.")
        let due = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(fireAt.addingTimeInterval(1800))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((due["fired"] as? [[String: Any]])?.compactMap { $0["taskID"] as? String }, [taskID], "A run 30 minutes late is inside the grace period.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Review" }, timeout: 60), "The fired task follows the ordinary board lifecycle.")
        XCTAssertTrue(waitForDisappearance(badge, timeout: 10), "Firing clears the schedule badge.")
        XCTAssertTrue(claudeFixturePrompts().contains("Tell me a story."), "The scheduled prompt reaches the provider.")
        attachScreenshot(named: "The scheduled task ran and moved on the board")
        let again = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(fireAt.addingTimeInterval(2400))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((again["fired"] as? [Any])?.count, 0, "A run happens once.")
        assertCLIError(
            try runCLI(["schedule", "set", taskID, "--prompt", "Again", "--once", scheduleISO(fireAt.addingTimeInterval(86400))], expectedStatus: 1),
            code: "invalid_transition"
        )

        let bundleIdentifier = try XCTUnwrap(Bundle(url: appBundle)?.bundleIdentifier)
        let agentURL = appBundle.appendingPathComponent("Contents/Library/LaunchAgents/\(bundleIdentifier).scheduler.plist")
        let agent = try XCTUnwrap(try PropertyListSerialization.propertyList(from: Data(contentsOf: agentURL), format: nil) as? [String: Any])
        XCTAssertEqual(agent["Label"] as? String, "\(bundleIdentifier).scheduler")
        XCTAssertEqual(agent["BundleProgram"] as? String, "Contents/MacOS/playhouse-cli")
        XCTAssertEqual(agent["ProgramArguments"] as? [String], ["playhouse-cli", "schedule", "tick"])
        XCTAssertEqual(agent["StartInterval"] as? Int, 60, "The agent ticks every minute while the app is closed.")

        let soonID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Due on the real clock", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let soon = Date().addingTimeInterval(3)
        _ = try runCLI(["schedule", "set", soonID, "--prompt", "Tell me a story.", "--once", scheduleISO(soon)])
        Thread.sleep(forTimeInterval: max(0, soon.timeIntervalSinceNow) + 1)
        let real = try XCTUnwrap(try runCLI(["schedule", "tick"], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((real["fired"] as? [[String: Any]])?.compactMap { $0["taskID"] as? String }, [soonID], "A plain tick uses the real clock.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: soonID)?["status"] as? String) == "Review" }, timeout: 60))
    }

    // case-contract: test_schedule_missed_beyond_grace_is_blocked | A scheduled run more than one hour late is not started. A one-time task lands in Blocked with a 'Missed scheduled run' message and its prompt kept as an unsent draft, and sending that draft starts it. A recurring schedule ticked a week late creates exactly one Blocked run task linked to its schedule, skips the older missed occurrences, and moves its next run into the future. A due run whose provider can't start lands in Blocked saying the scheduled run couldn't start, with its prompt kept as the draft.
    func test_schedule_missed_beyond_grace_is_blocked() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-schedule-missed")
        launchApp(defaultParent: fixture.parent.path)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Missed once", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let fireAt = Date().addingTimeInterval(3600)
        _ = try runCLI(["schedule", "set", taskID, "--prompt", "Tell me a story.", "--once", scheduleISO(fireAt)])
        let late = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(fireAt.addingTimeInterval(7200))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((late["dropped"] as? [[String: Any]])?.compactMap { $0["taskID"] as? String }, [taskID])
        let message = element("task-status-message-\(taskID)")
        XCTAssertTrue(message.waitForExistence(timeout: 10), "The missed task shows why it's blocked.")
        XCTAssertTrue(accessibleLabelOrValue(of: message).hasPrefix("Missed scheduled run"))
        XCTAssertTrue(element("column-blocked").buttons["task-card-\(taskID)"].waitForExistence(timeout: 10), "A missed run lands in Blocked.")
        XCTAssertEqual(claudeFixturePrompts(), [], "A missed run starts no turn.")
        attachScreenshot(named: "A missed one-time run waits in Blocked")

        openTask(named: "Missed once")
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "Tell me a story." }, timeout: 10), "The missed prompt waits in the composer.")
        attachScreenshot(named: "The missed prompt waits in the composer")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Review" }, timeout: 60), "Sending the draft runs the task.")
        XCTAssertTrue(claudeFixturePrompts().contains("Tell me a story."))

        element("back-to-board-button").click()
        let templateID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Weekly template", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let template = try XCTUnwrap(try runCLI([
            "schedule", "set", templateID, "--prompt", "Tell me a story.", "--repeat", "weekly", "--weekday", "mon", "--time", "09:00", "--title", "Weekly report",
        ])["result"] as? [String: Any])
        let nextRun = try XCTUnwrap(scheduleDate((template["schedule"] as? [String: Any])?["scheduledAt"] as? String))
        let weekLate = nextRun.addingTimeInterval(7 * 86400 + 7200)
        let missed = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(weekLate)], extraEnvironment: environment)["result"] as? [String: Any])
        let dropped = try XCTUnwrap(missed["dropped"] as? [[String: Any]])
        XCTAssertEqual(dropped.count, 1, "Missed occurrences collapse into one run.")
        let runID = try XCTUnwrap(dropped.first?["taskID"] as? String)
        XCTAssertTrue(element("column-blocked").buttons["task-card-\(runID)"].waitForExistence(timeout: 10), "The missed recurring run is a Blocked board task.")
        let run = try XCTUnwrap(taskRecord(id: runID))
        XCTAssertEqual(run["title"] as? String, "Weekly report")
        XCTAssertEqual(run["scheduleSourceTaskID"] as? String, templateID)
        XCTAssertEqual(run["savedPrompt"] as? String, "Tell me a story.", "The missed run keeps the prompt as its draft.")
        XCTAssertEqual(run["hasUnsentDraft"] as? Bool, true)
        let refreshed = try XCTUnwrap(taskRecord(id: templateID)?["schedule"] as? [String: Any])
        XCTAssertGreaterThan(try XCTUnwrap(scheduleDate(refreshed["scheduledAt"] as? String)), weekLate, "The next run moves into the future.")
        attachScreenshot(named: "A recurring run missed by a week lands once in Blocked")

        let failingID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Provider missing", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let failingAt = Date().addingTimeInterval(3600)
        _ = try runCLI(["schedule", "set", failingID, "--prompt", "Tell me a story.", "--once", scheduleISO(failingAt)])
        let unstarted = try XCTUnwrap(try runCLI(
            ["schedule", "tick", "--now", scheduleISO(failingAt.addingTimeInterval(300))],
            extraEnvironment: ["PLAYHOUSE_E2E_CLAUDE_EXECUTABLE": "none"]
        )["result"] as? [String: Any])
        XCTAssertEqual((unstarted["fired"] as? [[String: Any]])?.compactMap { $0["taskID"] as? String }, [failingID])
        let failedMessage = element("task-status-message-\(failingID)")
        XCTAssertTrue(waitUntil({ failedMessage.exists && self.accessibleLabelOrValue(of: failedMessage).hasPrefix("The scheduled run couldn't start") }, timeout: 30),
                      "A run whose provider can't start says so on its Blocked card.")
        XCTAssertTrue(element("column-blocked").buttons["task-card-\(failingID)"].exists)
        let failed = try XCTUnwrap(taskRecord(id: failingID))
        XCTAssertEqual(failed["savedPrompt"] as? String, "Tell me a story.")
        XCTAssertEqual(failed["hasUnsentDraft"] as? Bool, true, "The prompt waits as the draft for a retry.")
        attachScreenshot(named: "A scheduled run that couldn't start waits in Blocked")
    }

    // case-contract: test_schedule_recurring_template_hidden_and_spawns_runs | A recurring schedule needs a title, and a weekday when it repeats weekly; once confirmed, its template is absent from the board and task list but listed by schedule list and on the Scheduled Tasks page. A due tick creates a new board task with the schedule's title and context folders, linked by scheduleSourceTaskID, sends the prompt, records the run on the template and advances its next run by one day. A paused schedule doesn't fire, Run now starts a run immediately, and clearing the schedule turns the template into an ordinary Backlog task.
    func test_schedule_recurring_template_hidden_and_spawns_runs() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-schedule-recurring")
        launchApp(defaultParent: fixture.parent.path)
        let templateID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Recurring template", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        openTask(named: "Recurring template")
        replaceComposerText(with: "Tell me a story.")
        _ = openScheduleHint()
        selectSkillsTab("Recurring", picker: "schedule-kind-picker")
        let title = element("schedule-title-field")
        XCTAssertTrue(title.waitForExistence(timeout: 5), "A recurring schedule asks for a title.")
        XCTAssertTrue(element("schedule-repeat-picker").exists)
        title.click()
        title.typeKey("a", modifierFlags: .command)
        title.typeKey(.delete, modifierFlags: [])
        XCTAssertFalse(element("schedule-done-button").isEnabled, "A recurring schedule needs a title.")
        title.typeText("Daily standup")
        XCTAssertTrue(waitUntil({ self.element("schedule-done-button").isEnabled }, timeout: 5))
        attachScreenshot(named: "Schedule hint for a recurring task with its title")
        element("schedule-done-button").click()
        let send = element("send-message-button")
        XCTAssertTrue(waitUntil({ send.label == "Schedule task" }, timeout: 5))
        send.click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10))
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: templateID)?["schedule"] as? [String: Any])?["kind"] as? String) == "recurring" }, timeout: 10))
        Thread.sleep(forTimeInterval: 1)
        XCTAssertFalse(element("task-card-\(templateID)").exists, "A recurring template isn't a board task.")
        let boardTasks = ((try runCLI(["task", "list"])["result"] as? [String: Any])?["tasks"] as? [[String: Any]]) ?? []
        XCTAssertFalse(boardTasks.contains { $0["id"] as? String == templateID }, "A recurring template isn't in task list.")
        attachScreenshot(named: "Board after scheduling a recurring task shows no template card")
        assertCLIError(
            try runCLI(["schedule", "set", templateID, "--prompt", "Tell me a story.", "--repeat", "weekly", "--title", "Standup"], expectedStatus: 2),
            code: "invalid_argument"
        )

        element("scheduled-tasks-button").click()
        XCTAssertTrue(element("scheduled-tasks-page").waitForExistence(timeout: 10), "The sidebar button opens the Scheduled Tasks page.")
        let row = element("scheduled-task-row-\(templateID)")
        XCTAssertTrue(row.waitForExistence(timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("scheduled-task-title-\(templateID)")), "Daily standup")
        XCTAssertTrue(accessibleLabelOrValue(of: element("scheduled-task-summary-\(templateID)")).hasPrefix("Every day at 09:00"))
        attachScreenshot(named: "Scheduled Tasks page lists the recurring task")

        let template = try XCTUnwrap(taskRecord(id: templateID)?["schedule"] as? [String: Any])
        let firstRun = try XCTUnwrap(scheduleDate(template["scheduledAt"] as? String))
        let fired = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(firstRun.addingTimeInterval(600))], extraEnvironment: environment)["result"] as? [String: Any])
        let runID = try XCTUnwrap((fired["fired"] as? [[String: Any]])?.first?["taskID"] as? String)
        XCTAssertNotEqual(runID, templateID, "Each run is a new task.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: runID)?["status"] as? String) == "Review" }, timeout: 60))
        let run = try XCTUnwrap(taskRecord(id: runID))
        XCTAssertEqual(run["title"] as? String, "Daily standup")
        XCTAssertEqual(run["scheduleSourceTaskID"] as? String, templateID)
        XCTAssertEqual(run["contextFolders"] as? [String], try taskRecord(id: templateID)?["contextFolders"] as? [String], "A run takes the schedule's context folders.")
        XCTAssertTrue(claudeFixturePrompts().contains("Tell me a story."))
        let advanced = try XCTUnwrap(scheduleDate((taskRecord(id: templateID)?["schedule"] as? [String: Any])?["scheduledAt"] as? String))
        XCTAssertEqual(advanced.timeIntervalSince(firstRun), 86400, accuracy: 3600, "A daily schedule advances by one day.")

        let active = element("scheduled-task-active-\(templateID)")
        XCTAssertTrue(active.waitForExistence(timeout: 5))
        active.click()
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: templateID)?["schedule"] as? [String: Any])?["paused"] as? Bool) == true }, timeout: 10), "The row's switch pauses the schedule.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("scheduled-task-summary-\(templateID)")).hasSuffix("Paused") }, timeout: 5))
        let nextRun = try XCTUnwrap(scheduleDate((taskRecord(id: templateID)?["schedule"] as? [String: Any])?["scheduledAt"] as? String))
        let quiet = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(nextRun.addingTimeInterval(600))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((quiet["fired"] as? [Any])?.count, 0, "A paused schedule doesn't fire.")
        active.click()
        XCTAssertTrue(waitUntil({ ((try? self.taskRecord(id: templateID)?["schedule"] as? [String: Any])?["paused"] as? Bool) == false }, timeout: 10))
        attachScreenshot(named: "Scheduled Tasks page after pausing and resuming")

        clickScheduledTaskMenuItem(taskID: templateID, item: "scheduled-task-run-now-\(templateID)", title: "Run Now")
        XCTAssertTrue(waitUntil({
            let runs = ((try? self.runCLI(["task", "list"])["result"] as? [String: Any])?["tasks"] as? [[String: Any]]) ?? []
            return runs.filter { $0["scheduleSourceTaskID"] as? String == templateID }.count == 2
        }, timeout: 20), "Run Now starts another run.")

        element("scheduled-tasks-back-button").click()
        XCTAssertTrue(waitForDisappearance(element("scheduled-tasks-page"), timeout: 5))
        XCTAssertTrue(element("task-card-\(runID)").waitForExistence(timeout: 10), "A run is followed on the board.")
        attachScreenshot(named: "Recurring runs appear on the board as ordinary tasks")
        _ = try runCLI(["schedule", "clear", templateID])
        XCTAssertTrue(element("task-card-\(templateID)").waitForExistence(timeout: 10), "Clearing the schedule puts the task on the board.")
    }

    // case-contract: test_scheduled_task_edit_and_page_management | The Scheduled Tasks sidebar button opens the Scheduled Tasks page, whose New Task opens a task conversation with the schedule hint already open on Recurring. Opening a scheduled task shows its confirmed prompt with the schedule button on and Send in schedule mode, and its hint shows the saved repeat, day and time; changing its title and repeat in the hint and confirming with Send persists across fresh CLI reads, keeps the time, and starts no turn. Deleting a schedule removes it from schedule list and from the page. Sending a one-time scheduled task by hand ends its schedule, so a later tick sends nothing more; a recurring template rejects a send with invalid_transition; and clearing a schedule keeps its prompt as the task's draft.
    func test_scheduled_task_edit_and_page_management() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-schedule-edit")
        launchApp(defaultParent: fixture.parent.path)
        element("scheduled-tasks-button").click()
        XCTAssertTrue(element("scheduled-tasks-page").waitForExistence(timeout: 10))
        XCTAssertTrue(element("scheduled-tasks-empty").exists, "An empty page says so plainly.")
        attachScreenshot(named: "Scheduled Tasks page with no schedules")

        element("scheduled-new-task-button").click()
        XCTAssertTrue(element("schedule-hint").waitForExistence(timeout: 10), "New Task opens the conversation with the schedule hint open.")
        let title = element("schedule-title-field")
        XCTAssertTrue(title.waitForExistence(timeout: 5), "The hint starts on Recurring.")
        attachScreenshot(named: "New Task from the page opens with the schedule hint")
        title.click()
        title.typeText("Morning summary")
        element("schedule-done-button").click()
        XCTAssertTrue(waitForDisappearance(element("schedule-hint")))
        replaceComposerText(with: "Summarize the week.")
        let send = element("send-message-button")
        XCTAssertTrue(waitUntil({ send.label == "Schedule task" }, timeout: 5))
        send.click()

        let row = app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH %@", "scheduled-task-row-")).firstMatch
        XCTAssertTrue(row.waitForExistence(timeout: 10), "Scheduling from the page returns to the page with the new row.")
        let listed = try XCTUnwrap((try runCLI(["schedule", "list"])["result"] as? [String: Any])?["tasks"] as? [[String: Any]])
        XCTAssertEqual(listed.count, 1)
        let taskID = try XCTUnwrap(listed.first?["id"] as? String)
        XCTAssertEqual(listed.first?["title"] as? String, "Morning summary")

        // A non-default schedule, so reopening proves the hint loads what was saved.
        _ = try runCLI(["schedule", "set", taskID, "--prompt", "Summarize the week.", "--repeat", "weekly", "--weekday", "fri", "--time", "17:15", "--title", "Morning summary"])
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("scheduled-task-summary-\(taskID)")).hasPrefix("Fridays at 17:15") }, timeout: 10))
        element("scheduled-task-open-\(taskID)").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "Summarize the week." }, timeout: 10), "Editing shows the confirmed prompt.")
        XCTAssertEqual(element("schedule-task-button").value as? String, "On")
        XCTAssertEqual(send.label, "Schedule task", "Send stays in schedule mode while editing.")
        attachScreenshot(named: "Editing a scheduled task keeps Send in schedule mode")
        _ = openScheduleHint()
        XCTAssertEqual(title.value as? String, "Morning summary")
        XCTAssertTrue(accessibleLabelOrValue(of: element("schedule-summary")).hasPrefix("Fridays at 17:15"), "The hint shows the saved repeat, day and time.")
        title.click()
        title.typeKey("a", modifierFlags: .command)
        title.typeText("Weekday summary")
        let repeatPicker = element("schedule-repeat-picker")
        repeatPicker.click()
        let weekdays = app.menuItems["Weekdays"]
        XCTAssertTrue(weekdays.waitForExistence(timeout: 5))
        weekdays.click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("schedule-summary")).hasPrefix("Weekdays at 17:15") }, timeout: 5))
        attachScreenshot(named: "Hint edited to a new title and repeat")
        element("schedule-done-button").click()
        XCTAssertTrue(waitForDisappearance(element("schedule-hint")))
        send.click()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["title"] as? String) == "Weekday summary" }, timeout: 10), "Confirming with Send saves the edit.")
        let edited = try XCTUnwrap(taskRecord(id: taskID))
        let recurrence = try XCTUnwrap((edited["schedule"] as? [String: Any])?["recurrence"] as? [String: Any])
        XCTAssertEqual(recurrence["preset"] as? String, "weekdays")
        XCTAssertEqual(recurrence["hour"] as? Int, 17, "The edit keeps the time.")
        XCTAssertEqual(recurrence["minute"] as? Int, 15)
        XCTAssertNil(edited["claudeSessionID"] as? String)
        XCTAssertNil(edited["codexThreadID"] as? String, "Editing a schedule starts no turn.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("scheduled-task-title-\(taskID)")) == "Weekday summary" }, timeout: 10))
        attachScreenshot(named: "Scheduled Tasks page after editing the title and repeat")

        assertCLIError(
            try runCLI(["conversation", "send", taskID, "--message", "Run the template."], expectedStatus: 1, extraEnvironment: environment),
            code: "invalid_transition"
        )
        XCTAssertEqual(claudeFixturePrompts(), [], "A recurring template never runs itself.")

        clickScheduledTaskMenuItem(taskID: taskID, item: "scheduled-task-delete-\(taskID)", title: "Delete…")
        let confirm = element("confirm-delete-scheduled-task-button")
        let confirmButton = confirm.waitForExistence(timeout: 5) ? confirm : app.buttons["Delete"]
        confirmButton.click()
        XCTAssertTrue(waitForDisappearance(element("scheduled-task-row-\(taskID)"), timeout: 10), "Deleting removes the row.")
        XCTAssertEqual(((try runCLI(["schedule", "list"])["result"] as? [String: Any])?["tasks"] as? [Any])?.count, 0)
        XCTAssertTrue(element("scheduled-tasks-empty").waitForExistence(timeout: 5))
        attachScreenshot(named: "Scheduled Tasks page after deleting the schedule")

        // A one-time schedule removed in the hint: Send runs the task now and ends the schedule.
        let onceID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Sent by hand", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let onceAt = Date().addingTimeInterval(3600)
        _ = try runCLI(["schedule", "set", onceID, "--prompt", "Tell me a story.", "--once", scheduleISO(onceAt)])
        let onceRow = element("scheduled-task-open-\(onceID)")
        XCTAssertTrue(onceRow.waitForExistence(timeout: 10), "The page lists the new one-time schedule.")
        onceRow.click()
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "Tell me a story." }, timeout: 10))
        _ = openScheduleHint()
        element("schedule-remove-button").click()
        XCTAssertTrue(waitUntil({ send.label == "Send message" }, timeout: 5))
        send.click()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: onceID)?["status"] as? String) == "Review" }, timeout: 60), "Send runs the task now.")
        XCTAssertNil(try taskRecord(id: onceID)?["schedule"] as? [String: Any], "Sending by hand ends a one-time schedule.")
        let sent = claudeFixturePrompts().count
        let later = try XCTUnwrap(try runCLI(["schedule", "tick", "--now", scheduleISO(onceAt.addingTimeInterval(300))], extraEnvironment: environment)["result"] as? [String: Any])
        XCTAssertEqual((later["fired"] as? [Any])?.count, 0, "A started task's schedule sends nothing more.")
        XCTAssertEqual(claudeFixturePrompts().count, sent)

        let clearedID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Cleared schedule", "--prompt", "Fixture task description.", "--root", fixture.primary.path,
        ])["result"] as? [String: Any])?["id"] as? String)
        _ = try runCLI(["schedule", "set", clearedID, "--prompt", "Keep this prompt.", "--once", scheduleISO(onceAt)])
        let cleared = try XCTUnwrap(try runCLI(["schedule", "clear", clearedID])["result"] as? [String: Any])
        XCTAssertEqual(cleared["savedPrompt"] as? String, "Keep this prompt.", "Clearing a schedule keeps its prompt as the draft.")
        XCTAssertEqual(cleared["hasUnsentDraft"] as? Bool, true)
    }

    // case-contract: test_task_token_usage_records_claude_turn_breakdown | A task starts with no recorded tokens, and its Token Stats modal says so plainly with no totals shown. Running a real Claude Code fixture turn parses that turn's reported usage into Playhouse's four buckets, adds them to the task's running totals, and records a per-turn row naming the provider and the tools, skills and MCP servers that ran in it. A second turn adds to the totals and appends its own row rather than replacing the first, and the per-tool rollup counts the turns each tool took part in. Call-level accounting spans the main agent and its subagents: an empty task's `callUsage` reports itself unavailable, and after a turn it reports exact model-call, total-sent, output and final-transcript figures read from the session files (counting each message ID once, ignoring repeated and zero-usage lines, and including the subagent's own file), which a second turn adds to rather than replaces. A Claude turn whose session files cannot be read still counts its calls live from the stream. The task card replaces its old dot with a compact live counter of total sent, which is hidden while that total is still zero, whose tooltip names the sent total, call count and final transcript size, and both the Token Stats context-menu item and a click on the counter itself, a button that highlights on hover, open a modal labelling 'Final transcript size' and 'Total sent (incl. subagents)' beside the call and output counts, the per-tool rollup and the per-turn breakdown. Excluding cache reads (uncached input + cache write + output, subagent included) is 855 per turn, doubling after a second turn, and also reaches the live stream when the session files cannot be read; an empty task reports it unavailable. A task saved before the cache split existed (call usage without the split, plus turn-level buckets) still loads, reports its call counts and total sent, omits the per-call excluding-cache figures, and falls back to the turn buckets minus cache reads (170 for 100 input, 50 output, 400 cache read and 20 cache write); its modal hides the Excluding cache reads headline. The modal also labels 'Excluding cache reads (incl. subagents)' with its main-agent and subagent split.
    func test_task_token_usage_records_claude_turn_breakdown() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-token-usage")
        launchApp(defaultParent: fixture.parent.path)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Token usage task", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let card = app.buttons["Token usage task"]
        XCTAssertTrue(card.waitForExistence(timeout: 10))
        let counter = element("task-token-usage-counter-\(taskID)")
        XCTAssertFalse(counter.exists, "A task with no recorded tokens should hide its card counter.")
        attachScreenshot(named: "Task card hides its counter before any tokens are recorded")
        let emptySummary = try XCTUnwrap(try runCLI(["task", "token-usage", taskID])["result"] as? [String: Any])
        XCTAssertEqual((emptySummary["callUsage"] as? [String: Any])?["available"] as? Bool, false)
        XCTAssertNil((emptySummary["callUsage"] as? [String: Any])?["totalTokensExcludingCacheReads"])
        XCTAssertEqual(emptySummary["tokensExcludingCacheReads"] as? Int, 0)

        card.rightClick()
        element("token-stats-task-menu-item").click()
        let emptyState = element("token-stats-empty")
        XCTAssertTrue(emptyState.waitForExistence(timeout: 10), "Token Stats should say plainly that nothing has been recorded yet.")
        XCTAssertFalse(element("token-stats-total").exists, "An empty task should show no totals.")
        attachScreenshot(named: "Token Stats modal before any turns have run")
        element("close-token-stats-button").click()
        XCTAssertTrue(waitUntil({ !emptyState.exists }, timeout: 5))

        // "Tell me a story." is one of the fixture's few branches that reports a
        // task outcome, ending in exactly one Claude result message; an
        // outcome-less prompt (like "inspect") makes Playhouse send several
        // internal nudge turns in the same session, each contributing its own
        // result and inflating this fixture's flat per-result usage.
        _ = try runCLI(
            ["conversation", "send", taskID, "--message", "Tell me a story."],
            extraEnvironment: environment
        )
        _ = try runCLI(
            ["conversation", "send", taskID, "--message", "Tell me a story."],
            extraEnvironment: environment
        )
        // Two fixture turns, each with two main-agent calls (sending 550 and 650)
        // and two subagent calls (300 and 340): 8 calls, 3,680 sent, final context 650.
        XCTAssertTrue(
            waitUntil({ counter.label == "3.7K tokens sent · 8 calls · 650 final transcript" }, timeout: 15),
            "The counter should report everything sent, subagents included, across both turns."
        )
        attachScreenshot(named: "Task card shows its live token counter beside the time")

        // The counter is a button: its hit area is padded well past the 10pt text,
        // hovering highlights it, and clicking its edge (not the text) opens Token Stats.
        XCTAssertGreaterThanOrEqual(counter.frame.height, 20, "The counter's hit area should be taller than its small text.")
        assertHoverEmphasis(for: counter)
        attachScreenshot(named: "Token counter highlights on hover")
        counter.coordinate(withNormalizedOffset: CGVector(dx: 0.06, dy: 0.5)).click()

        // The sheet's summary loads asynchronously (`.task`), so its text commits
        // a moment after the element appears; assertText waits on the content.
        // A SwiftUI Text reports its string as the accessibility value, not label.
        let total = element("token-stats-total")
        assertText("token-stats-total", equals: "3,200")
        assertText("token-stats-final-transcript", equals: "650")
        assertText("token-stats-total-sent", equals: "3,680")
        // Per turn, uncached input + cache write + output: 360 main + 495 subagent.
        assertText("token-stats-excluding-cache", equals: "1,710")
        assertText("token-stats-excluding-cache-split", equals: "Excluding cache reads: 720 main agent · 990 subagents")
        assertText("token-stats-total-calls", equals: "8 model calls · 4 main, 4 across 2 subagents")
        assertText("token-stats-output", equals: "Output 170")
        XCTAssertTrue(element("token-stats-tool-Bash").exists, "The rollup should name the tool the turns ran.")
        let turnRows = app.descendants(matching: .any).matching(NSPredicate(
            format: "identifier BEGINSWITH %@", "token-stats-turn-"
        ))
        XCTAssertEqual(turnRows.count, 2, "Each recorded turn should have its own row.")
        attachScreenshot(named: "Token Stats modal breaks usage down by tool and by turn")
        element("close-token-stats-button").click()
        XCTAssertTrue(waitUntil({ !total.exists }, timeout: 5), "Token Stats should close again.")

        let summary = try XCTUnwrap(try runCLI(["task", "token-usage", taskID])["result"] as? [String: Any])
        XCTAssertEqual(summary["totalTokens"] as? Int, 3_200)
        XCTAssertEqual((summary["turns"] as? [[String: Any]])?.count, 2)
        let calls = try XCTUnwrap(summary["callUsage"] as? [String: Any])
        XCTAssertEqual(calls["totalCalls"] as? Int, 8)
        XCTAssertEqual(calls["totalSentTokens"] as? Int, 3_680)
        XCTAssertEqual(calls["totalTokensExcludingCacheReads"] as? Int, 1_710)
        XCTAssertEqual(summary["tokensExcludingCacheReads"] as? Int, 1_710)

        // A task saved before the cache split existed: call usage without the split plus turn buckets.
        let legacyTitle = "Legacy token usage task"
        let legacyID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", legacyTitle, "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        let legacySnapshots = #"{"claude:legacy":{"provider":"claude","updatedAt":800000000,"main":{"calls":2,"sentTokens":1200,"outputTokens":60,"lastContextTokens":650},"subagents":{"old":{"calls":1,"sentTokens":300,"outputTokens":10,"lastContextTokens":300}}}}"#
        // The app holds its container open, so close it before seeding the store.
        app.terminate()
        XCTAssertTrue(waitUntil({ app.state == .notRunning }, timeout: 10), "The app must close its SwiftData container before seeding the pre-split task.")
        let seed = Process()
        seed.executableURL = URL(fileURLWithPath: "/usr/bin/sqlite3")
        seed.arguments = [
            dataDirectory.appendingPathComponent("Playhouse-v2.store").path,
            "UPDATE ZBOARDTASK SET ZCALLUSAGESNAPSHOTSDATA = CAST('\(legacySnapshots)' AS BLOB), ZTOTALINPUTTOKENS = 100, ZTOTALOUTPUTTOKENS = 50, ZTOTALCACHEREADTOKENS = 400, ZTOTALCACHECREATIONTOKENS = 20 WHERE ZTITLE = '\(legacyTitle)'",
        ]
        try seed.run()
        seed.waitUntilExit()
        XCTAssertEqual(seed.terminationStatus, 0, "Seeding the pre-split task should succeed.")
        // A fresh bridge daemon (its own service name, started by the relaunched app) reads the seeded row instead of a cached task.
        let freshDaemon = ["PLAYHOUSE_BRIDGE_SERVICE_NAME": "\(serviceName!).legacy-\(UUID().uuidString.prefix(8))"]
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: freshDaemon)
        let legacySummary = try XCTUnwrap(try runCLI(
            ["task", "token-usage", legacyID], extraEnvironment: freshDaemon
        )["result"] as? [String: Any])
        let legacyCalls = try XCTUnwrap(legacySummary["callUsage"] as? [String: Any])
        XCTAssertEqual(legacyCalls["available"] as? Bool, true)
        XCTAssertEqual(legacyCalls["totalSentTokens"] as? Int, 1_500)
        XCTAssertNil(legacyCalls["totalTokensExcludingCacheReads"], "Without the split there is no per-call figure.")
        XCTAssertEqual(legacySummary["tokensExcludingCacheReads"] as? Int, 170, "The fallback is the turn buckets minus cache reads.")
        let legacyCard = app.buttons[legacyTitle]
        XCTAssertTrue(legacyCard.waitForExistence(timeout: 10))
        legacyCard.rightClick()
        element("token-stats-task-menu-item").click()
        assertText("token-stats-total-sent", equals: "1,500")
        XCTAssertFalse(element("token-stats-excluding-cache").exists, "A pre-split task hides the Excluding cache reads headline.")
        attachScreenshot(named: "Token Stats modal for a task saved before the cache split")
        element("close-token-stats-button").click()
        XCTAssertEqual(calls["finalTranscriptTokens"] as? Int, 650)
        XCTAssertEqual((calls["subagents"] as? [String: Any])?["count"] as? Int, 2)
    }

    // case-contract: test_task_token_usage_records_codex_turn_breakdown | A Codex app-server fixture turn's usage reaches the same per-task totals and per-turn breakdown through Codex's own wire shape, mapping its cached-input bucket onto Playhouse's cache-read bucket and leaving cache-write at zero. The recorded turn row names Codex as its provider, Codex's input count includes its cached tokens, so the input bucket excludes them rather than counting them twice. Per-call usage notifications streamed before the turn ends, including those of a subagent thread that names its parent, reach the same call-level accounting once each (a repeated notification is ignored), and the Token Stats modal shows those Codex totals, call counts and final transcript size in the app. Excluding cache reads, the figure counts each call's uncached input plus cache write plus output, main thread and subagent alike (780), and the modal shows it with its main-agent and subagent split.
    func test_task_token_usage_records_codex_turn_breakdown() throws {
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Codex token usage", roots: [fixture.primary.path])
        let taskID = try taskID(named: "Codex token usage")
        let card = app.buttons["Codex token usage"]
        XCTAssertTrue(card.waitForExistence(timeout: 10))

        // A bare send only reports its usage once the terminal `turn/completed`
        // notification arrives, and the default fixture never emits one on its
        // own for an ordinary prompt — it waits for Playhouse to report an
        // outcome while the turn is held, exactly like `complete_fixture_turn`
        // drives it in the CLI/XPC suite. Reproduce that hold/outcome/release
        // dance here so the turn actually completes.
        let executable = dataDirectory.appendingPathComponent("codex-fixture-token-usage")
        try FileManager.default.copyItem(at: WorkspaceFixture.root.appendingPathComponent("codex-fixture-ui"), to: executable)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Codex protocol fixture (v1).\n".utf8)
            .write(to: dataDirectory.appendingPathComponent(".playhouse-codex-fixture-owner"))
        let holdMarker = URL(fileURLWithPath: executable.path + ".hold-release")
        let activeMarker = URL(fileURLWithPath: executable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: executable.path + ".turn-release")
        try Data().write(to: holdMarker)
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)

        let process = try startCLIProcess(
            ["conversation", "send", taskID, "--message", "Complete this task.", "--answer", "color=Blue", "--answer", "token=fixture-secret"],
            extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": executable.path]
        )
        defer {
            if process.process.isRunning {
                try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                process.process.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
            try? FileManager.default.removeItem(at: holdMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The fixture should hold the turn open for a CLI outcome report.")
        let outcome = try runCLI(["task", "outcome", taskID, "completed"])
        XCTAssertEqual((outcome["result"] as? [String: Any])?["outcome"] as? String, "completed")
        try "Release the completed fixture turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        _ = try finishCLIProcess(process)

        // One Codex fixture turn: 3 calls (two main sending 700 and 900, one subagent
        // sending 300), 1,900 sent, and a final transcript of 900.
        let counter = element("task-token-usage-counter-\(taskID)")
        XCTAssertTrue(
            waitUntil({ counter.exists && counter.label == "1.9K tokens sent · 3 calls · 900 final transcript" }, timeout: 15),
            "A Codex turn's per-call usage, subagent included, should reach the card's counter."
        )

        card.rightClick()
        element("token-stats-task-menu-item").click()
        assertText("token-stats-total", equals: "1,050")
        assertText("token-stats-final-transcript", equals: "900")
        assertText("token-stats-total-sent", equals: "1,900")
        // Codex's input includes cached tokens: main (200+30)+(300+40), subagent 200+10.
        assertText("token-stats-excluding-cache", equals: "780")
        assertText("token-stats-excluding-cache-split", equals: "Excluding cache reads: 570 main agent · 210 subagents")
        assertText("token-stats-total-calls", equals: "3 model calls · 2 main, 1 across 1 subagent")
        attachScreenshot(named: "Token Stats modal shows a Codex turn's usage")
        element("close-token-stats-button").click()

        let summary = try XCTUnwrap(try runCLI(["task", "token-usage", taskID])["result"] as? [String: Any])
        let usage = try XCTUnwrap(summary["usage"] as? [String: Any])
        XCTAssertEqual(usage["cacheReadTokens"] as? Int, 250, "Codex's cached input maps onto the cache-read bucket.")
        XCTAssertEqual(usage["cacheCreationTokens"] as? Int, 0, "Codex reports no cache-write bucket.")
        XCTAssertEqual((summary["turns"] as? [[String: Any]])?.first?["provider"] as? String, "codex")
        XCTAssertEqual(usage["inputTokens"] as? Int, 650, "Codex's input count includes its cached tokens, which are not counted twice.")
        let calls = try XCTUnwrap(summary["callUsage"] as? [String: Any])
        XCTAssertEqual(calls["totalCalls"] as? Int, 3)
        XCTAssertEqual(calls["totalSentTokens"] as? Int, 1_900)
        XCTAssertEqual(calls["totalTokensExcludingCacheReads"] as? Int, 780)
        XCTAssertEqual(summary["tokensExcludingCacheReads"] as? Int, 780)
        XCTAssertEqual(calls["totalOutputTokens"] as? Int, 80)
        XCTAssertEqual(calls["finalTranscriptTokens"] as? Int, 900)
        XCTAssertEqual((calls["subagents"] as? [String: Any])?["calls"] as? Int, 1)
    }

    /// The fixture log's size as the app formats it; the log is built the same
    /// way as WASTE_LOG in scripts/fixtures/claude-code-fixture.py.
    private enum WasteFixture {
        static var logLength: String {
            var length = 0
            for index in 1...1000 {
                let time = String(format: "2026-11-03T10:%02d:%02dZ", index / 60 % 60, index % 60)
                let marker = index == 900 ? "NEEDLE-42 " : ""
                let line = "\(time) INFO fixture log line \(String(format: "%04d", index)) \(marker)request ok path=/api/orc/builds/\(String(format: "%04d", index))\n"
                length += line.unicodeScalars.count
            }
            return length.formatted(IntegerFormatStyle<Int>().grouping(.automatic))
        }
    }

    /// Runs one Claude fixture turn whose session file logs every request (see
    /// write_waste_session in scripts/fixtures/claude-code-fixture.py), with the
    /// app reading the same Claude config directory the turn wrote to.
    private func runClaudeTokenWasteTurn(title: String) throws -> (taskID: String, environment: [String: String]) {
        var environment = try installClaudeFixture(named: "claude-fixture-ui-token-waste")
        // The CLI forwards CLAUDE_CONFIG_DIR with its requests; the window's own
        // bridge requests take the same directory from PLAYHOUSE_E2E_CLAUDE_CONFIG_DIR.
        let claudeConfig = dataDirectory.appendingPathComponent("claude-config").path
        environment["CLAUDE_CONFIG_DIR"] = claudeConfig
        environment["PLAYHOUSE_E2E_CLAUDE_CONFIG_DIR"] = claudeConfig
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: environment)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", title, "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        XCTAssertTrue(app.buttons[title].waitForExistence(timeout: 10))
        _ = try runCLI(["conversation", "send", taskID, "--message", "Show token waste."], extraEnvironment: environment)
        return (taskID, environment)
    }

    private func openTokenStats(of title: String) {
        app.buttons[title].rightClick()
        let statsAction = element("token-stats-task-menu-item")
        XCTAssertTrue(statsAction.waitForExistence(timeout: 5), "The task context menu should offer Token Stats.")
        statsAction.click()
        XCTAssertTrue(element("token-stats-section-overview").waitForExistence(timeout: 10), "Token Stats opens on its Overview section.")
    }

    /// `section` is the section's identifier suffix: wasters, tools, overhead or overview.
    private func showTokenStatsSection(_ section: String) {
        let tab = element("token-stats-section-\(section)")
        XCTAssertTrue(tab.waitForExistence(timeout: 5), "Token Stats should offer its \(section) section.")
        tab.click()
    }

    // case-contract: test_task_token_waste_ranks_claude_items_by_size | A task with no conversation reports its token map unavailable, with no wasters, tools or agents. After a Claude Code fixture turn whose session file logs every request (a shape, blobs, and transcript lines referenced by hash, including a parallel tool call sent as one message), the map reads the main agent and its subagent, and the main agent's final transcript tokens equal its last request's context exactly. The largest item is the MCP tool's 1,000-line log, ranked by the tokens it added, flagged as removed by the compaction, and sharing the tokens of the request it arrived in with its call by characters. The tools rollup ranks that MCP tool first by tokens added, the MCP server rollup counts its defined and called tools and what its definitions cost, the overhead lists the system prompt, each built-in tool definition and the server's definitions as sent with every request, the README read twice is one repeated result, the request that re-sent its context without the prompt cache is the one cache miss, and the compaction is counted. The Token Stats modal shows these in its Wasters, Tools & MCP and Overhead sections.
    func test_task_token_waste_ranks_claude_items_by_size() throws {
        let (taskID, environment) = try runClaudeTokenWasteTurn(title: "Claude token waste")
        _ = try runCLI(["task", "create", "--title", "No conversation yet", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude"])
        XCTAssertTrue(app.buttons["No conversation yet"].waitForExistence(timeout: 10))
        openTokenStats(of: "No conversation yet")
        showTokenStatsSection("wasters")
        XCTAssertTrue(element("token-stats-map-unavailable").waitForExistence(timeout: 10), "A task with no conversation has nothing to map.")
        XCTAssertFalse(element("token-stats-raw-input-button").isEnabled, "There is no raw input to open yet.")
        attachScreenshot(named: "A task with no conversation has no token map yet")
        element("close-token-stats-button").click()
        XCTAssertTrue(waitForDisappearance(element("token-stats-map-unavailable")))

        openTokenStats(of: "Claude token waste")

        showTokenStatsSection("wasters")
        assertText("token-stats-waster-0-label", equals: "fixturelogs/query_logs")
        XCTAssertTrue(element("token-stats-waster-0-removed").waitForExistence(timeout: 5), "The compaction removed the log.")
        assertText("token-stats-waster-0-requests", equals: "×63")
        let tokensPerCopy = try duplicateTokens(taskID: taskID, environment: environment)
        assertText("token-stats-duplicate-0-copies", equals: "2 copies of \(tokensPerCopy)")
        assertText("token-stats-cache-miss-0-request", equals: "Request 34")
        attachScreenshot(named: "Wasters rank the MCP log first, then show the repeated read and the cache miss")

        showTokenStatsSection("tools")
        assertText("token-stats-measured-tool-fixturelogs/query_logs-total", equals: "18,000")
        XCTAssertTrue(element("token-stats-measured-tool-Bash").exists, "Every tool that ran has its own row.")
        assertText("token-stats-server-fixturelogs-total", equals: "18,000")
        attachScreenshot(named: "Tools and MCP servers by the tokens they added")

        showTokenStatsSection("overhead")
        XCTAssertTrue(element(containingAccessibilityText: "MCP server fixturelogs · 2 tool definitions").waitForExistence(timeout: 5))
        XCTAssertTrue(element(containingAccessibilityText: "System prompt (part 1)").exists)
        XCTAssertTrue(element("token-stats-agent-claude/fxw").exists, "The subagent's file is its own agent.")
        attachScreenshot(named: "Overhead sent with every request, and each agent")
        element("close-token-stats-button").click()

        let report = try XCTUnwrap(try runCLI(["task", "token-waste", taskID], extraEnvironment: environment)["result"] as? [String: Any])
        let top = try XCTUnwrap((report["wasters"] as? [[String: Any]])?.first)
        XCTAssertEqual(top["label"] as? String, "fixturelogs/query_logs")
        XCTAssertEqual((report["tools"] as? [[String: Any]])?.first?["totalTokens"] as? Int, 18_000)
    }

    /// Rows of the raw input list are drawn lazily; scrolls the list until one is on screen.
    private func revealRawInputRow(_ identifier: String) {
        let row = element(identifier)
        let list = element("raw-input-list")
        XCTAssertTrue(list.waitForExistence(timeout: 10))
        for _ in 0..<20 where !row.exists {
            list.scroll(byDeltaX: 0, deltaY: -300)
        }
        XCTAssertTrue(row.waitForExistence(timeout: 5), "\(identifier) should be on screen after scrolling the list.")
    }

    private func duplicateTokens(taskID: String, environment: [String: String]) throws -> String {
        let report = try XCTUnwrap(try runCLI(["task", "token-waste", taskID], extraEnvironment: environment)["result"] as? [String: Any])
        let tokens = try XCTUnwrap((report["duplicates"] as? [[String: Any]])?.first?["tokensPerCopy"] as? Int)
        return tokens.formatted(IntegerFormatStyle<Int>().grouping(.automatic))
    }

    // case-contract: test_task_token_waste_ranks_codex_items_by_size | A Codex fixture turn whose thread and subagent have rollout files gives the same map from Codex's own format: a request was sent the instructions plus every item before its own output, the final transcript's tokens equal the last request's input exactly after a compaction replaced the history, Codex's unsaved tool definitions appear as one hidden-overhead item sent with every request, encrypted reasoning is shown by its size, the MCP tool's log is the largest item and was removed by the compaction, the repeated README read and the cache miss are reported, and the subagent's thread is its own agent. The raw input's final transcript lists the hidden overhead, the instructions and the replacement history once each without the removed log, and an item's full text, from a tool output or from the replacement history, reads back exactly as Codex saved it, in chunks, with its call named. The single-request scope rebuilds each Codex request from the rollout and labels it reconstructed: the latest request is the final transcript in order, request 4 flags both README reads and both of their outputs as exact duplicates, each request's items add up to the input Codex reported with its cached share as cache read and no cache write, and the JSON export holds the base instructions and the input items exactly as saved. The Token Stats modal shows the Codex wasters, the hidden overhead and the subagent, showing the log opens its full text, and the raw input's single request reads as reconstructed, with request 4's duplicates flagged.
    func test_task_token_waste_ranks_codex_items_by_size() throws {
        launchApp(defaultParent: fixture.parent.path)
        try createTaskFixture(title: "Codex token waste", roots: [fixture.primary.path])
        let taskID = try taskID(named: "Codex token waste")
        XCTAssertTrue(app.buttons["Codex token waste"].waitForExistence(timeout: 10))

        // As in the Codex token usage case, the fixture holds the turn open
        // until Playhouse reports its outcome, then completes it.
        let executable = dataDirectory.appendingPathComponent("codex-fixture-token-waste")
        try FileManager.default.copyItem(at: WorkspaceFixture.root.appendingPathComponent("codex-fixture-ui"), to: executable)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Codex protocol fixture (v1).\n".utf8)
            .write(to: dataDirectory.appendingPathComponent(".playhouse-codex-fixture-owner"))
        let holdMarker = URL(fileURLWithPath: executable.path + ".hold-release")
        let activeMarker = URL(fileURLWithPath: executable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: executable.path + ".turn-release")
        try Data().write(to: holdMarker)
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
        // The fixture writes its rollout under the Codex home the CLI forwards,
        // which must be the one the window reads its session files from.
        let process = try startCLIProcess(
            ["conversation", "send", taskID, "--message", "Show token waste.", "--answer", "color=Blue", "--answer", "token=fixture-secret"],
            extraEnvironment: [
                "PLAYHOUSE_E2E_CODEX_EXECUTABLE": executable.path,
                "CODEX_HOME": dataDirectory.appendingPathComponent("codex-home").path,
            ]
        )
        defer {
            if process.process.isRunning {
                try? "Release the active turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
                process.process.waitUntilExit()
            }
            try? FileManager.default.removeItem(at: activeMarker)
            try? FileManager.default.removeItem(at: releaseMarker)
            try? FileManager.default.removeItem(at: holdMarker)
        }
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: activeMarker.path) }, timeout: 10), "The fixture should hold the turn open for a CLI outcome report.")
        _ = try runCLI(["task", "outcome", taskID, "completed"])
        try "Release the completed fixture turn.\n".write(to: releaseMarker, atomically: true, encoding: .utf8)
        _ = try finishCLIProcess(process)
        let threadID = try XCTUnwrap((try runCLI(["task", "get", taskID])["result"] as? [String: Any])?["codexThreadID"] as? String)

        openTokenStats(of: "Codex token waste")
        showTokenStatsSection("wasters")
        assertText("token-stats-waster-0-label", equals: "fixturelogs/query_logs")
        XCTAssertTrue(element("token-stats-waster-0-removed").waitForExistence(timeout: 5), "The compaction removed the log.")
        assertText("token-stats-cache-miss-0-request", equals: "Request 4")
        attachScreenshot(named: "Codex wasters rank the MCP log first")
        element("token-stats-waster-0-show").click()
        assertText("raw-input-text-label", equals: "fixturelogs/query_logs")
        let firstLine = element("raw-input-text-line-1")
        XCTAssertTrue(firstLine.waitForExistence(timeout: 10), "The Codex log's full text opens from its waster row.")
        XCTAssertTrue(
            accessibleLabelOrValue(of: firstLine).contains("2026-11-03T10:00:01Z INFO fixture log line 0001"),
            "The first line is the log exactly as Codex saved it."
        )
        attachScreenshot(named: "Showing the Codex waster opens the log as Codex saved it")
        element("close-raw-input-button").click()
        showTokenStatsSection("overhead")
        XCTAssertTrue(
            element(containingAccessibilityText: "Tool definitions and other context Codex does not save").waitForExistence(timeout: 5),
            "Codex's unsaved tool definitions show as one hidden-overhead line."
        )
        XCTAssertTrue(element("token-stats-agent-codex/\(threadID)-subagent").exists, "The subagent thread is its own agent.")
        attachScreenshot(named: "Codex overhead includes the hidden tool definitions and the subagent")

        element("token-stats-raw-input-button").click()
        let requestScope = element("raw-input-scope-request")
        XCTAssertTrue(requestScope.waitForExistence(timeout: 10))
        requestScope.click()
        assertText("raw-input-request-number", equals: "Request 5 of 5")
        assertText("raw-input-request-exactness", equals: "Reconstructed")
        XCTAssertTrue(
            accessibleLabelOrValue(of: element("raw-input-request-note")).hasPrefix("Reconstructed: Codex resends the whole history"),
            "The view says how the Codex request was rebuilt."
        )
        assertText("raw-input-request-usage", equals: "Reported input 4,400 (uncached 500 · cache read 3,900) · items add up to 4,400 · 0 repeated")
        element("raw-input-request-previous").click()
        assertText("raw-input-request-number", equals: "Request 4 of 5")
        revealRawInputRow("raw-input-request-row-11")
        assertText("raw-input-request-row-9-repeat", equals: "Duplicate 1 of 2")
        assertText("raw-input-request-row-11-repeat", equals: "Duplicate 2 of 2 · first at #10")
        attachScreenshot(named: "A reconstructed Codex request flags the README read sent twice")
        element("close-raw-input-button").click()
        element("close-token-stats-button").click()

        let report = try XCTUnwrap(try runCLI(["task", "token-waste", taskID])["result"] as? [String: Any])
        let overhead = try XCTUnwrap(report["overhead"] as? [[String: Any]])
        XCTAssertTrue(overhead.contains { $0["kind"] as? String == "hiddenOverhead" && $0["everyRequest"] as? Bool == true })
        XCTAssertEqual((report["agents"] as? [[String: Any]])?.first?["finalTranscriptTokens"] as? Int, 4_400)
    }

    // case-contract: test_task_raw_input_pages_final_transcript_without_duplicates | A task with no conversation has no raw input: its page is empty and reading an item's text is not_found. After a Claude Code fixture turn, the raw input lists the final transcript with each item once across pages and without the log a compaction removed; the everything-sent scope adds what was removed, ordering by size lists the largest first, a search finds the log by a word only its full text contains, and a focus item reports its position. An item's full text reads back in chunks that end on a line break and join to the exact text, with the call that produced it named. An unknown agent or item is not_found, and an unknown order or a limit of zero is invalid_argument. In the app, View raw input opens the final transcript, scrolling loads the next page of rows, showing the largest waster opens it in the everything-sent scope with its full text, and scrolling that text reaches its last line.
    func test_task_raw_input_pages_final_transcript_without_duplicates() throws {
        let (taskID, environment) = try runClaudeTokenWasteTurn(title: "Claude raw input")
        let everything = try XCTUnwrap(try runCLI(
            ["task", "raw-input", taskID, "--scope", "all", "--limit", "1000"], extraEnvironment: environment
        )["result"] as? [String: Any])
        let allRows = try XCTUnwrap(everything["rows"] as? [[String: Any]])
        let lastRowID = try XCTUnwrap(allRows.last?["id"] as? Int)
        XCTAssertGreaterThan(allRows.count, 100, "Enough items that the list needs a second page.")

        openTokenStats(of: "Claude raw input")
        let rawInputButton = element("token-stats-raw-input-button")
        XCTAssertTrue(waitUntil({ rawInputButton.exists && rawInputButton.isEnabled }, timeout: 10), "The raw input opens once the map has loaded.")
        rawInputButton.click()
        assertText("raw-input-summary", equals: "10 items · 3,160 tokens")
        XCTAssertTrue(element("raw-input-no-selection").exists)
        attachScreenshot(named: "Raw input opens on the final transcript, each item once")

        element("raw-input-scope-all").click()
        let summary = element("raw-input-summary")
        XCTAssertTrue(
            waitUntil({ self.accessibleLabelOrValue(of: summary).hasPrefix("\(allRows.count) items") }, timeout: 10),
            "Everything sent adds what the compaction removed."
        )
        let loadedRows = element("raw-input-loaded-rows")
        assertText("raw-input-loaded-rows", equals: "100 of \(allRows.count) loaded")
        XCTAssertFalse(element("raw-input-row-\(lastRowID)").exists, "Rows past the first page are not loaded yet.")
        let list = element("raw-input-list")
        let lastRow = element("raw-input-row-\(lastRowID)")
        for _ in 0..<60 where !lastRow.exists {
            list.scroll(byDeltaX: 0, deltaY: -800)
        }
        XCTAssertTrue(lastRow.waitForExistence(timeout: 10), "Scrolling to the end loads the next page of rows.")
        XCTAssertTrue(
            waitUntil({ self.accessibleLabelOrValue(of: loadedRows) == "\(allRows.count) of \(allRows.count) loaded" }, timeout: 10),
            "The second page is fetched only once the list scrolls to its end."
        )
        attachScreenshot(named: "Scrolling the list loads the next page")
        element("close-raw-input-button").click()

        showTokenStatsSection("wasters")
        let show = element("token-stats-waster-0-show")
        XCTAssertTrue(show.waitForExistence(timeout: 5))
        show.click()
        assertText("raw-input-text-label", equals: "fixturelogs/query_logs")
        let call = element("raw-input-text-call")
        XCTAssertTrue(call.waitForExistence(timeout: 5), "A tool result names the call that produced it.")
        let callText = accessibleLabelOrValue(of: call)
        XCTAssertTrue(callText.contains("fixturelogs/query_logs") && callText.contains("5000"), "The call names the tool and its arguments: \(callText)")
        XCTAssertTrue(element("raw-input-text-line-1").waitForExistence(timeout: 5))
        XCTAssertTrue(
            waitUntil({ self.accessibleLabelOrValue(of: summary).hasPrefix("\(allRows.count) items") }, timeout: 10),
            "A removed waster opens in the everything-sent scope."
        )
        attachScreenshot(named: "Showing the largest waster opens its full text")
        let logLength = WasteFixture.logLength
        let loadedText = element("raw-input-text-loaded")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: loadedText).hasSuffix("of \(logLength) characters loaded") }, timeout: 10))
        XCTAssertFalse(
            accessibleLabelOrValue(of: loadedText).hasPrefix("\(logLength) of"),
            "Only the first chunk of the log is loaded before the text scrolls."
        )
        let text = element("raw-input-text")
        let lastLine = element("raw-input-text-line-1000")
        for _ in 0..<80 where !lastLine.exists {
            text.scroll(byDeltaX: 0, deltaY: -1500)
        }
        XCTAssertTrue(lastLine.waitForExistence(timeout: 10), "Scrolling the text loads its later chunks up to the last line.")
        assertText("raw-input-text-loaded", equals: "\(logLength) of \(logLength) characters loaded")
        attachScreenshot(named: "Scrolling the log reaches its last line")
        element("close-raw-input-button").click()
        element("close-token-stats-button").click()
    }

    // case-contract: test_task_raw_input_single_request_lists_resumed_instruction_copies_in_order | After a Claude Code fixture session that resumes once its AGENTS.md changed, the raw input's single-request scope lists every item one request sent, in order and with nothing merged, and shows the latest request by default. A request after the resume carries both instruction copies in order, which differ and so are not flagged, while the date reminder sent twice word for word is flagged as a duplicate; a request before the resume carries one copy and no duplicates, and a search keeps each row's position. Each request reports Claude's input with its cache-read and cache-write split, and its items' sizes add up to that input. The request is labelled exact; its text export gives every item's full text under a header naming any duplicate, and its JSON export is the request body with the logged parameters, cache markers, system prompt, tools and messages verbatim, an earlier request's messages being a prefix of a later one's. A request number past the last is not_found, and zero or an unknown export format is invalid_argument. In the app, choosing Single request shows the latest request with its usage, both instruction copies unflagged and the repeated date reminder flagged, stepping back to a request before the resume shows one copy and no flags, Latest returns to the last request, and Copy all copies the whole request as JSON.
    func test_task_raw_input_single_request_lists_resumed_instruction_copies_in_order() throws {
        var environment = try installClaudeFixture(named: "claude-fixture-ui-instruction-resume")
        let claudeConfig = dataDirectory.appendingPathComponent("claude-config").path
        environment["CLAUDE_CONFIG_DIR"] = claudeConfig
        environment["PLAYHOUSE_E2E_CLAUDE_CONFIG_DIR"] = claudeConfig
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: environment)
        let title = "Claude instruction resume"
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", title, "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        XCTAssertTrue(app.buttons[title].waitForExistence(timeout: 10))
        _ = try runCLI(["conversation", "send", taskID, "--message", "Show instruction resume."], extraEnvironment: environment)

        openTokenStats(of: title)
        let rawInputButton = element("token-stats-raw-input-button")
        XCTAssertTrue(waitUntil({ rawInputButton.exists && rawInputButton.isEnabled }, timeout: 10), "The raw input opens once the map has loaded.")
        rawInputButton.click()
        let requestScope = element("raw-input-scope-request")
        XCTAssertTrue(requestScope.waitForExistence(timeout: 10), "The raw input offers a single-request scope.")
        requestScope.click()
        assertText("raw-input-request-number", equals: "Request 5 of 5")
        assertText("raw-input-summary", equals: "16 items · 9,100 tokens")
        assertText("raw-input-request-exactness", equals: "Exact")
        assertText(
            "raw-input-request-usage",
            equals: "Reported input 9,100 (uncached 2 · cache read 9,000 · cache write 98) · items add up to 9,100 · 2 repeated · source sdk"
        )
        XCTAssertFalse(element("raw-input-request-next").isEnabled, "The latest request is the last one.")
        XCTAssertFalse(element("raw-input-request-latest").isEnabled)
        XCTAssertTrue(element("raw-input-request-time").exists, "The request shows when it was sent.")
        XCTAssertTrue(element("raw-input-request-row-3").exists)
        XCTAssertFalse(element("raw-input-request-row-3-repeat").exists, "The two AGENTS.md copies differ, so neither is flagged.")
        assertText("raw-input-request-row-4-repeat", equals: "Duplicate 1 of 2")
        revealRawInputRow("raw-input-request-row-13")
        XCTAssertTrue(element("raw-input-request-row-11").exists)
        XCTAssertFalse(element("raw-input-request-row-11-repeat").exists)
        assertText("raw-input-request-row-12-repeat", equals: "Duplicate 2 of 2 · first at #5")
        XCTAssertTrue(element("raw-input-request-row-13").exists)
        XCTAssertFalse(element("raw-input-request-row-13-repeat").exists, "The resumed prompt itself is not a repeat.")
        attachScreenshot(named: "The latest request lists both AGENTS.md copies in order and flags the date reminder sent twice")

        element("raw-input-request-row-11").click()
        let secondLine = element("raw-input-text-line-2")
        XCTAssertTrue(secondLine.waitForExistence(timeout: 10), "Selecting the second copy opens its full text.")
        XCTAssertTrue(
            accessibleLabelOrValue(of: secondLine).contains("Instruction files were re-read when this session started"),
            "The second copy is the instructions re-read on resume."
        )
        attachScreenshot(named: "The re-read AGENTS.md copy, selected in the request")

        let previous = element("raw-input-request-previous")
        previous.click()
        assertText("raw-input-request-number", equals: "Request 4 of 5")
        previous.click()
        assertText("raw-input-request-number", equals: "Request 3 of 5")
        assertText("raw-input-summary", equals: "10 items · 4,400 tokens")
        XCTAssertTrue(element("raw-input-request-row-3").waitForExistence(timeout: 5), "The first copy was already sent.")
        XCTAssertFalse(element("raw-input-request-row-3-repeat").exists, "Before the resume the instructions were sent once.")
        XCTAssertFalse(element("raw-input-request-row-11").exists, "Request 3 sent only ten items.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("raw-input-request-usage")).contains("items add up to 4,400 · 0 repeated"))
        attachScreenshot(named: "A request before the resume carries one AGENTS.md copy and no repeats")

        element("raw-input-request-latest").click()
        assertText("raw-input-request-number", equals: "Request 5 of 5")
        element("raw-input-export-format-json").click()
        NSPasteboard.general.clearContents()
        element("raw-input-request-copy-button").click()
        assertText("raw-input-request-export-status", equals: "Copied request 5 as JSON: 16 items")
        let copied = try XCTUnwrap(NSPasteboard.general.string(forType: .string), "Copy all puts the request on the pasteboard.")
        let body = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(copied.utf8)) as? [String: Any])
        let messages = try XCTUnwrap(body["messages"] as? [[String: Any]])
        XCTAssertEqual(messages.count, 9, "The whole request, every message it sent.")
        let resumed = try XCTUnwrap((messages[6]["content"] as? [[String: Any]])?.first?["text"] as? String)
        XCTAssertTrue(resumed.contains("Instruction files were re-read"))
        let original = try XCTUnwrap((messages[0]["content"] as? [[String: Any]])?.first?["text"] as? String)
        XCTAssertTrue(original.contains("Codebase and user instructions are shown below"))
        XCTAssertEqual(body["model"] as? String, "claude-fixture")
        attachScreenshot(named: "Copy all copies the whole request as JSON")
        element("close-raw-input-button").click()
        element("close-token-stats-button").click()

        let page = try XCTUnwrap(try runCLI(
            ["task", "raw-input", taskID, "--scope", "request", "--request", "3"], extraEnvironment: environment
        )["result"] as? [String: Any])
        XCTAssertEqual((page["request"] as? [String: Any])?["repeatedItems"] as? Int, 0)
    }

    // case-contract: test_settings_token_usage_color_max_round_trip | The token usage color maximum defaults to twenty million, round-trips through the CLI/XPC settings commands, and rejects a non-positive value as invalid_argument without changing the stored setting. The settings window shows the stored maximum and saves an edited one, and a task card's token counter re-colors when the maximum changes so the same usage reads hotter against a smaller ceiling.
    func test_settings_token_usage_color_max_round_trip() throws {
        let environment = try installClaudeFixture(named: "claude-fixture-ui-token-max")
        launchApp(defaultParent: fixture.parent.path)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Counter heat task", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        XCTAssertTrue(app.buttons["Counter heat task"].waitForExistence(timeout: 10))
        // "Tell me a story." reports a task outcome, so it ends in exactly one
        // Claude result message instead of the several internal nudge turns an
        // outcome-less prompt would trigger in the same session.
        _ = try runCLI(
            ["conversation", "send", taskID, "--message", "Tell me a story."],
            extraEnvironment: environment
        )
        let counter = element("task-token-usage-counter-\(taskID)")
        // One fixture turn sends 1,840 tokens over four calls (two of them a subagent's).
        XCTAssertTrue(waitUntil({ counter.exists && counter.label == "1.8K tokens sent · 4 calls · 650 final transcript" }, timeout: 15))

        XCTAssertEqual(
            (try runCLI(["settings", "get"])["result"] as? [String: Any])?["tokenUsageColorMax"] as? Int, 20_000_000,
            "The counter's scale tops out at twenty million tokens by default."
        )
        XCTAssertTrue(waitUntil({ self.isGreenDominant(counter) }, timeout: 10), "1,840 tokens of twenty million should still read as cool green.")
        attachScreenshot(named: "Token counter reads green against the default twenty-million ceiling")

        app.typeKey(",", modifierFlags: .command)
        let preferences = settingsWindow
        XCTAssertTrue(preferences.waitForExistence(timeout: 10), "Workspace Settings did not open.")
        let maxField = preferences.descendants(matching: .any)
            .matching(identifier: "token-usage-color-max-field").firstMatch
        XCTAssertTrue(maxField.waitForExistence(timeout: 5), "Settings should expose the token usage maximum.")
        XCTAssertEqual(maxField.value as? String, "20,000,000", "The field should show the stored maximum.")
        attachScreenshot(named: "Workspace Settings exposes the token usage color maximum")
        maxField.click()
        maxField.typeKey("a", modifierFlags: .command)
        maxField.typeText("1600\r")
        XCTAssertTrue(waitUntil({
            ((try? self.runCLI(["settings", "get"])["result"] as? [String: Any])?["tokenUsageColorMax"] as? Int) == 1_600
        }, timeout: 10), "An edited maximum should save through the same settings manager the CLI reads.")
        app.typeKey("w", modifierFlags: .command)
        XCTAssertTrue(waitUntil({ !preferences.exists }, timeout: 5))

        XCTAssertTrue(waitUntil({ self.isRedDominant(counter) }, timeout: 10), "The same usage should read hot once it reaches the ceiling.")
        attachScreenshot(named: "Token counter turns red once the ceiling drops to the task's own usage")

        assertCLIError(
            try runCLI(["settings", "set-token-usage-color-max", "0"], expectedStatus: 2),
            code: "invalid_argument"
        )
        XCTAssertEqual(
            (try runCLI(["settings", "get"])["result"] as? [String: Any])?["tokenUsageColorMax"] as? Int, 1_600,
            "A rejected maximum should leave the stored one alone."
        )
    }

    // case-contract: test_task_cpu_usage_reports_claude_process_tree_load | A newly created Claude task reports cpu-usage as not running before any turn starts. While a real Claude Code fixture turn burns CPU in a real child process, two successive `task cpu-usage` reads establish a baseline and then a plausible non-zero percentage for the task's process tree, the task card's CPU bar reads cool green against the default multi-core ceiling and hot red once the ceiling is lowered to match that load, and the reading returns to not-running once the turn completes.
    func test_task_cpu_usage_reports_claude_process_tree_load() throws {
        var environment = try installClaudeFixture(named: "claude-fixture-ui-cpu-usage")
        environment["PLAYHOUSE_E2E_CLAUDE_FIXTURE_BURN_CPU"] = "1"
        environment["PLAYHOUSE_E2E_CLAUDE_FIXTURE_BURN_CPU_SECONDS"] = "25"
        launchApp(defaultParent: fixture.parent.path)
        let taskID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Claude CPU usage", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "claude",
        ])["result"] as? [String: Any])?["id"] as? String)
        XCTAssertTrue(app.buttons["Claude CPU usage"].waitForExistence(timeout: 10))

        let bar = element("task-cpu-usage-bar-\(taskID)")
        let card = element("task-card-\(taskID)")
        XCTAssertFalse(bar.exists, "A task with no turn yet should show no CPU bar.")

        let process = try startCLIProcess(
            ["conversation", "send", taskID, "--message", "Tell me a story."],
            extraEnvironment: environment
        )
        defer {
            if process.process.isRunning {
                process.process.terminate()
                process.process.waitUntilExit()
            }
        }

        XCTAssertTrue(waitUntil({
            (try? self.runCLI(["task", "get", taskID])["result"] as? [String: Any])?["claudeSessionID"] != nil
        }, timeout: 10), "The Claude fixture turn should start a session while it burns CPU.")

        XCTAssertTrue(bar.waitForExistence(timeout: 10), "A busy Claude task should show its left-edge CPU bar.")
        attachScreenshot(named: "Task card shows a busy Claude task's CPU bar")
        // Against the default, core-count-scaled ceiling, one burning core is a
        // small fraction of the total, so the bar should still read cool green
        // — this is what the gradient-reveal fill must get right at low usage.
        // Sampled off the stable card (not the thin, continuously-animating bar
        // sub-view) restricted to its left edge, since the bar's own element
        // identity can transiently drop out of the accessibility tree between
        // an existence check and a screenshot fetch mid-animation.
        XCTAssertTrue(waitUntil({ self.isGreenDominant(card, leftEdgeFraction: 0.06) }, timeout: 10), "One burning core against the default multi-core ceiling should still read cool green.")
        attachScreenshot(named: "CPU bar reads green against the default multi-core ceiling")

        // A low ceiling guarantees the same load now reads clearly hot,
        // regardless of how many cores this machine has.
        _ = try runCLI(["settings", "set-cpu-usage-color-max", "50"])
        XCTAssertTrue(waitUntil({ self.isRedDominant(card, leftEdgeFraction: 0.06) }, timeout: 10), "A single burning core should read hot against a 50% ceiling.")
        attachScreenshot(named: "CPU bar reads hot once usage reaches the lowered ceiling")

        _ = try finishCLIProcess(process)
        XCTAssertTrue(waitUntil({ !bar.exists }, timeout: 15), "The bar should disappear once the turn completes.")
    }

    // case-contract: test_task_cpu_usage_attributes_codex_load_by_worktree | Two Codex tasks rooted in different repository folders share one real fixture app-server. Before any turn each reports cpu-usage as not running. While task A's turn runs a real CPU-burning child process in A's folder and task B's concurrent turn runs an idle child in B's folder, both children belong to the same app-server process; once a baseline is sampled, `task cpu-usage` attributes a plausible non-zero percentage to A and a near-zero one to B, and the task cards show A's CPU bar reading hot against a lowered ceiling beside B's visible but empty bar. Both readings return to not-running once the turns complete.
    func test_task_cpu_usage_attributes_codex_load_by_worktree() throws {
        let executable = dataDirectory.appendingPathComponent("codex-fixture-cpu-attribution")
        try FileManager.default.copyItem(at: WorkspaceFixture.root.appendingPathComponent("codex-fixture-ui"), to: executable)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Codex protocol fixture (v1).\n".utf8)
            .write(to: dataDirectory.appendingPathComponent(".playhouse-codex-fixture-owner"))
        let environment = ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": executable.path]
        launchApp(defaultParent: fixture.parent.path)
        let busyID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Codex busy worktree", "--prompt", "Fixture task description.", "--root", fixture.primary.path, "--provider", "codex",
        ])["result"] as? [String: Any])?["id"] as? String)
        let idleID = try XCTUnwrap((try runCLI([
            "task", "create", "--title", "Codex idle worktree", "--prompt", "Fixture task description.", "--root", fixture.secondary.path, "--provider", "codex",
        ])["result"] as? [String: Any])?["id"] as? String)
        XCTAssertTrue(app.buttons["Codex busy worktree"].waitForExistence(timeout: 10))
        XCTAssertTrue(app.buttons["Codex idle worktree"].waitForExistence(timeout: 10))

        let busyBar = element("task-cpu-usage-bar-\(busyID)")
        let idleBar = element("task-cpu-usage-bar-\(idleID)")
        let busyCard = element("task-card-\(busyID)")
        let idleCard = element("task-card-\(idleID)")
        for taskID in [busyID, idleID] {
            let before = try XCTUnwrap(try runCLI(["task", "cpu-usage", taskID])["result"] as? [String: Any])
            XCTAssertTrue(before["cpuPercent"] == nil || before["cpuPercent"] is NSNull, "A Codex task with no turn yet has nothing to sample.")
            XCTAssertEqual(before["reason"] as? String, "not_running")
        }
        XCTAssertFalse(busyBar.exists, "A Codex task with no turn yet should show no CPU bar.")
        XCTAssertFalse(idleBar.exists, "A Codex task with no turn yet should show no CPU bar.")

        let busy = try startCLIProcess(["conversation", "send", busyID, "--message", "Please burn cpu for 25 seconds."], extraEnvironment: environment)
        let idle = try startCLIProcess(["conversation", "send", idleID, "--message", "Please idle cpu for 25 seconds."], extraEnvironment: environment)
        defer {
            for running in [busy, idle] where running.process.isRunning {
                running.process.terminate()
                running.process.waitUntilExit()
            }
            // A failed assertion must not leave the daemon-side burn running into later cases.
            if let burner = cpuAttributionChild(executable: executable, kind: "burn") {
                kill(burner.pid, SIGTERM)
            }
        }

        var children: [String: (pid: Int32, parentPID: Int32, workingDirectory: String)] = [:]
        XCTAssertTrue(waitUntil({
            children = [:]
            for kind in ["burn", "idle"] {
                if let child = self.cpuAttributionChild(executable: executable, kind: kind) { children[kind] = child }
            }
            return children.count == 2
        }, timeout: 15), "Both tasks' turns should be running their command children.")
        XCTAssertEqual(children["burn"]?.parentPID, children["idle"]?.parentPID, "Both tasks' commands should run under one shared app-server.")
        XCTAssertEqual(children["burn"].map { URL(fileURLWithPath: $0.workingDirectory).resolvingSymlinksInPath().path },
                       fixture.primary.resolvingSymlinksInPath().path, "The busy command runs in its task's folder.")
        XCTAssertEqual(children["idle"].map { URL(fileURLWithPath: $0.workingDirectory).resolvingSymlinksInPath().path },
                       fixture.secondary.resolvingSymlinksInPath().path, "The idle command runs in its task's folder.")

        XCTAssertTrue(busyBar.waitForExistence(timeout: 15), "The busy Codex task should show its left-edge CPU bar.")
        XCTAssertTrue(idleBar.waitForExistence(timeout: 15), "A running Codex task with an idle command still shows its (empty) CPU bar.")
        attachScreenshot(named: "Busy and idle Codex task cards both show a CPU bar")

        var readings: [String: [String: Any]] = [:]
        XCTAssertTrue(waitUntil({
            for taskID in [busyID, idleID] {
                readings[taskID] = (try? self.runCLI(["task", "cpu-usage", taskID]))?["result"] as? [String: Any]
            }
            return [busyID, idleID].allSatisfy { readings[$0]?["cpuPercent"] is Double }
        }, timeout: 10), "Both running Codex tasks should be sampled: \(readings)")
        Thread.sleep(forTimeInterval: 1)
        let busyReading = try XCTUnwrap(try runCLI(["task", "cpu-usage", busyID])["result"] as? [String: Any])
        let idleReading = try XCTUnwrap(try runCLI(["task", "cpu-usage", idleID])["result"] as? [String: Any])
        let busyPercent = try XCTUnwrap(busyReading["cpuPercent"] as? Double, "\(busyReading)")
        let idlePercent = try XCTUnwrap(idleReading["cpuPercent"] as? Double, "A running Codex task with an idle command still reports a value: \(idleReading)")
        XCTAssertGreaterThan(busyPercent, 20, "The busy-looping command's CPU should be attributed to its own task.")
        XCTAssertLessThan(busyPercent, Double(ProcessInfo.processInfo.activeProcessorCount * 100 + 50), "One busy loop can't exceed every core.")
        XCTAssertLessThan(idlePercent, 5, "The other task's busy command must not leak into the idle task's reading.")
        // The bars' own labels carry the streamed reading: the idle card's
        // bar is present but empty, the busy card's is not.
        XCTAssertTrue(waitUntil({ idleBar.exists && idleBar.label == "CPU 0%" }, timeout: 10), "The idle Codex task's bar should read 0%, got \(idleBar.label)")
        XCTAssertTrue(waitUntil({
            busyBar.exists && busyBar.label.hasPrefix("CPU ") && busyBar.label != "CPU 0%"
        }, timeout: 10), "The busy Codex task's bar should report its load, got \(busyBar.label)")

        // A ceiling below one busy core makes the busy task's bar read
        // clearly hot while the idle task's bar stays empty. Sampled off each
        // stable card's left edge, as in the Claude case.
        _ = try runCLI(["settings", "set-cpu-usage-color-max", "50"])
        XCTAssertTrue(waitUntil({ self.isRedDominant(busyCard, leftEdgeFraction: 0.06) }, timeout: 10), "The busy Codex task should read hot against a 50% ceiling.")
        XCTAssertTrue(idleBar.exists, "The idle Codex task keeps its bar while its turn runs.")
        XCTAssertFalse(isRedDominant(idleCard, leftEdgeFraction: 0.06), "The idle Codex task's bar should stay empty, not inherit the busy task's load.")
        attachScreenshot(named: "Busy Codex task's bar reads hot beside the idle task's empty bar")

        _ = try finishCLIProcess(busy)
        _ = try finishCLIProcess(idle)
        XCTAssertTrue(waitUntil({ !busyBar.exists && !idleBar.exists }, timeout: 15), "Both bars should disappear once the turns complete.")
        for taskID in [busyID, idleID] {
            let finished = try XCTUnwrap(try runCLI(["task", "cpu-usage", taskID])["result"] as? [String: Any])
            XCTAssertTrue(finished["cpuPercent"] == nil || finished["cpuPercent"] is NSNull, "A finished Codex turn is no longer running.")
            XCTAssertEqual(finished["reason"] as? String, "not_running")
        }
        attachScreenshot(named: "Both Codex task cards drop their CPU bars once the turns finish")
    }

    /// The pid, parent pid and working directory a running CPU-attribution
    /// fixture child recorded for itself. The sandboxed UI runner can't list
    /// the daemon's descendants with `ps`, so the child reports them.
    private func cpuAttributionChild(executable: URL, kind: String) -> (pid: Int32, parentPID: Int32, workingDirectory: String)? {
        let record = URL(fileURLWithPath: executable.path + ".cpu-child-\(kind).json")
        guard let data = try? Data(contentsOf: record),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let pid = (object["pid"] as? NSNumber)?.int32Value,
              let parentPID = (object["parentPID"] as? NSNumber)?.int32Value,
              let workingDirectory = object["workingDirectory"] as? String else { return nil }
        return (pid, parentPID, workingDirectory)
    }

    // MARK: - Skills

    private var skillsHome: URL { dataDirectory.appendingPathComponent("skills-home", isDirectory: true) }
    private var skillsCodexHome: URL { dataDirectory.appendingPathComponent("codex-home", isDirectory: true) }

    private func skillManifest(_ name: String, _ description: String, body: String = "Follow these steps.") -> String {
        "---\nname: \(name)\ndescription: \(description)\n---\n\n\(body)\n"
    }

    private func writeSkill(in folder: URL, _ name: String, _ description: String) throws {
        let directory = folder.appendingPathComponent(name, isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try skillManifest(name, description).write(to: directory.appendingPathComponent("SKILL.md"), atomically: true, encoding: .utf8)
    }

    /// A committed repository in this case's data directory, so a task worktree
    /// checks its skills out without touching the shared fixture.
    private func makeSkillRepository(_ name: String, skills: [String: String], links: [String: String] = [:]) throws -> URL {
        let repository = dataDirectory.appendingPathComponent(name, isDirectory: true)
        try FileManager.default.createDirectory(at: repository, withIntermediateDirectories: true)
        try runGit(repository, "init", "-q", "-b", "main")
        try "# \(name)\n".write(to: repository.appendingPathComponent("README.md"), atomically: true, encoding: .utf8)
        for (relative, text) in skills {
            let file = repository.appendingPathComponent(relative)
            try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
            try text.write(to: file, atomically: true, encoding: .utf8)
        }
        for (relative, target) in links {
            let link = repository.appendingPathComponent(relative)
            try FileManager.default.createDirectory(at: link.deletingLastPathComponent(), withIntermediateDirectories: true)
            try FileManager.default.createSymbolicLink(atPath: link.path, withDestinationPath: target)
        }
        try runGit(repository, "add", "-A")
        try runGit(repository, "-c", "user.name=Playhouse Test", "-c", "user.email=playhouse@example.com", "commit", "-q", "-m", "Skills fixture")
        return repository
    }

    /// A task whose repositories already have their managed worktrees.
    private func createSkillsTask(_ title: String, repositories: [URL], provider: String? = nil) throws -> [String: Any] {
        var command = ["task", "create", "--title", title, "--prompt", "Fixture task description."]
        if let provider { command += ["--provider", provider] }
        let taskID = try XCTUnwrap((try runCLI(command)["result"] as? [String: Any])?["id"] as? String)
        let added = try XCTUnwrap(try runCLI(["task", "repository", "add-batch", taskID] + repositories.flatMap { ["--repo", $0.path] })["result"] as? [String: Any])
        let records = try XCTUnwrap(added["repositoryWorktrees"] as? [[String: Any]])
        XCTAssertTrue(records.allSatisfy { $0["isPending"] as? Bool == false })
        return added
    }

    private func installSkillsClaudeFixture(_ name: String) throws -> URL {
        let executable = dataDirectory.appendingPathComponent(name)
        try FileManager.default.copyItem(at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"), to: executable)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        return executable
    }

    private func skillCatalog(taskID: String? = nil, includeBundled: Bool = false) throws -> [String: Any] {
        var command = ["skills", "list"]
        if let taskID { command += ["--task", taskID] }
        if includeBundled { command += ["--include-bundled", "true"] }
        return try XCTUnwrap(try runCLI(command)["result"] as? [String: Any])
    }

    private func skillsByName(_ skills: Any?) -> [String: [String: Any]] {
        Dictionary(uniqueKeysWithValues: ((skills as? [[String: Any]]) ?? []).compactMap { skill in
            (skill["name"] as? String).map { ($0, skill) }
        })
    }

    private func realPath(_ path: String) -> String {
        URL(fileURLWithPath: path).resolvingSymlinksInPath().standardizedFileURL.path
    }

    private func openSkillsPage(file: StaticString = #filePath, line: UInt = #line) {
        let button = element("open-skills-button")
        XCTAssertTrue(waitUntil({ button.exists && button.isHittable }, timeout: 15), "The composer should show the Skills button.", file: file, line: line)
        button.click()
        XCTAssertTrue(element("skills-page").waitForExistence(timeout: 10), "The Skills button should open the Skills page.", file: file, line: line)
        XCTAssertFalse(element("skills-loading").waitForExistence(timeout: 0.5) && !waitUntil({ !self.element("skills-loading").exists }, timeout: 10),
                       "The Skills page should finish loading.", file: file, line: line)
    }

    private func selectSkillsTab(_ label: String, picker identifier: String = "skills-tab-picker", file: StaticString = #filePath, line: UInt = #line) {
        let picker = element(identifier)
        XCTAssertTrue(picker.waitForExistence(timeout: 5), file: file, line: line)
        let candidates = [picker.radioButtons[label], picker.buttons[label], picker.descendants(matching: .any)[label]]
        guard let segment = candidates.first(where: { $0.exists }) else {
            XCTFail("\(identifier) has no \(label) tab.", file: file, line: line)
            return
        }
        segment.click()
    }

    private func clickSkillMenuItem(skill: String, item identifier: String, title: String, file: StaticString = #filePath, line: UInt = #line) {
        let actions = element("skill-actions-\(skill)")
        XCTAssertTrue(actions.waitForExistence(timeout: 10), "\(skill) should have an actions menu.", file: file, line: line)
        actions.click()
        let byIdentifier = app.menuItems.matching(identifier: identifier).firstMatch
        let item = byIdentifier.waitForExistence(timeout: 3) ? byIdentifier : app.menuItems[title]
        XCTAssertTrue(item.waitForExistence(timeout: 5), "The actions menu should offer \(title).", file: file, line: line)
        item.click()
    }

    private func clickDialogButton(_ identifier: String, title: String, file: StaticString = #filePath, line: UInt = #line) {
        let byIdentifier = element(identifier)
        let button = byIdentifier.waitForExistence(timeout: 3) ? byIdentifier : app.buttons[title].firstMatch
        XCTAssertTrue(button.waitForExistence(timeout: 5), "The dialog should offer \(title).", file: file, line: line)
        button.click()
    }

    private func isOn(_ toggle: XCUIElement) -> Bool {
        if let number = toggle.value as? NSNumber { return number.boolValue }
        return (toggle.value as? String) == "1"
    }

    // case-contract: test_skills_catalog_lists_repo_global_and_builtin_skills | The Skills page, opened from the composer's Skills button that replaced the paperclip, is a full page that slides in from the side over the task and fills the window, and its back button returns to the conversation. It lists the task's repository skills per repository (from each worktree's .agents/skills and .claude/skills, keyed by the source repository), the user's global skills (~/.agents/skills, Claude's skills folder, and Codex's legacy skills folder), and built-in skills (Codex's bundled .system skills, claude.ai-synced skills, and Claude Code's built-ins read from a provider session). Each user skill is shown as usable by both Claude and Codex; a skill linked into both layouts is one Linked entry, two different skills with the same name in one repository are flagged as a conflict, a SKILL.md without valid frontmatter is flagged invalid and usable by neither provider, a repository without skills shows an empty state, and built-ins name only the provider they ship with. Reading a skill returns its SKILL.md, and an unknown skill is not_found.
    func test_skills_catalog_lists_repo_global_and_builtin_skills() throws {
        let repository = try makeSkillRepository("skills-catalog-repo", skills: [
            ".agents/skills/repo-agents/SKILL.md": skillManifest("repo-agents", "Agents layout repository skill"),
            ".claude/skills/repo-claude/SKILL.md": skillManifest("repo-claude", "Claude layout repository skill"),
            ".agents/skills/repo-shared/SKILL.md": skillManifest("repo-shared", "Shared into both layouts by a link"),
            ".agents/skills/repo-dup/SKILL.md": skillManifest("repo-dup", "The agents copy"),
            ".claude/skills/repo-dup/SKILL.md": skillManifest("repo-dup", "A different Claude copy"),
            ".agents/skills/repo-broken/SKILL.md": "This skill has no frontmatter.\n",
        ], links: [".claude/skills/repo-shared": "../../.agents/skills/repo-shared"])
        let empty = try makeSkillRepository("skills-empty-repo", skills: [:])
        try writeSkill(in: skillsHome.appendingPathComponent(".agents/skills"), "global-agents", "Global agents skill")
        try writeSkill(in: skillsHome.appendingPathComponent(".claude/skills"), "global-claude", "Global Claude skill")
        try writeSkill(in: skillsCodexHome.appendingPathComponent("skills"), "codex-legacy", "Codex legacy user skill")
        try writeSkill(in: skillsCodexHome.appendingPathComponent("skills/.system"), "codex-system-skill", "Bundled with Codex")
        try writeSkill(in: skillsHome.appendingPathComponent(".claude/skills/synced/bucket-one"), "synced-skill", "Synced from claude.ai")
        _ = try installSkillsClaudeFixture("claude-fixture-skills-catalog")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Skills catalog", repositories: [repository, empty])
        let taskID = try XCTUnwrap(task["id"] as? String)
        openTask(named: "Skills catalog")
        XCTAssertFalse(element("attach-chat-image-button").exists, "The Skills button replaces the composer's paperclip.")
        openSkillsPage()
        let window = app.windows.firstMatch.frame
        XCTAssertTrue(waitUntil({
            let page = self.element("skills-page").frame
            return abs(page.minX - window.minX) < 2 && abs(page.maxX - window.maxX) < 2 && abs(page.maxY - window.maxY) < 2
        }, timeout: 5), "The Skills page settles as a full page spanning the window's width down to its bottom edge, not an inset modal.")
        XCTAssertGreaterThan(element("skills-page").frame.height, window.height * 0.85, "The Skills page fills the window.")

        XCTAssertTrue(element("skills-repo-section-skills-catalog-repo").waitForExistence(timeout: 10))
        XCTAssertTrue(element("skills-repo-section-skills-empty-repo").exists)
        XCTAssertTrue(element("skills-empty-skills-empty-repo").exists, "A repository without skills shows an empty state.")
        for name in ["repo-agents", "repo-claude", "repo-shared"] {
            XCTAssertTrue(element("skill-row-\(name)").waitForExistence(timeout: 5), "\(name) should be listed.")
            XCTAssertTrue(element("skill-provider-\(name)-claude").exists, "\(name) should be usable by Claude.")
            XCTAssertTrue(element("skill-provider-\(name)-codex").exists, "\(name) should be usable by Codex.")
        }
        XCTAssertEqual(accessibleLabelOrValue(of: element("skill-description-repo-agents")), "Agents layout repository skill")
        XCTAssertTrue(element("skill-linked-repo-shared").exists, "A skill linked into both layouts is one Linked entry.")
        XCTAssertEqual(app.descendants(matching: .any).matching(identifier: "skill-row-repo-shared").count, 1,
                       "A skill in both layouts is listed once.")
        XCTAssertFalse(element("skill-linked-repo-agents").exists)
        XCTAssertTrue(element("skill-conflict-repo-dup").exists, "Two different skills with one name are a conflict.")
        XCTAssertTrue(element("skill-invalid-repo-broken").exists, "A SKILL.md without frontmatter is invalid.")
        XCTAssertFalse(element("skill-provider-repo-broken-claude").exists || element("skill-provider-repo-broken-codex").exists,
                       "An invalid skill is usable by neither provider.")
        attachScreenshot(named: "Skills page Repo tab lists each repository's skills")
        let search = element("skills-search")
        typeIntoField(search, text: "layout repository")
        XCTAssertTrue(waitUntil({ !self.element("skill-row-repo-shared").exists }, timeout: 5), "Search hides skills that don't match.")
        XCTAssertTrue(element("skill-row-repo-agents").exists && element("skill-row-repo-claude").exists, "Search keeps skills whose description matches.")
        search.typeKey("a", modifierFlags: .command)
        search.typeText("no-skill-matches-this")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("skills-empty-skills-catalog-repo")) == "No matching skills." }, timeout: 5),
                      "A search with no match shows its empty state.")
        attachScreenshot(named: "Skills search with no matching skill")
        search.typeKey("a", modifierFlags: .command)
        search.typeKey(.delete, modifierFlags: [])
        XCTAssertTrue(element("skill-row-repo-shared").waitForExistence(timeout: 5), "Clearing the search shows every skill again.")

        selectSkillsTab("Global")
        for name in ["global-agents", "global-claude", "codex-legacy"] {
            XCTAssertTrue(element("skill-row-\(name)").waitForExistence(timeout: 5), "\(name) should be a global skill.")
            XCTAssertTrue(element("skill-provider-\(name)-claude").exists && element("skill-provider-\(name)-codex").exists)
        }
        XCTAssertFalse(element("skill-row-synced-skill").exists, "claude.ai's synced skills are built-in, not global.")
        attachScreenshot(named: "Skills page Global tab")

        selectSkillsTab("Built-in")
        XCTAssertTrue(element("skill-row-codex-system-skill").waitForExistence(timeout: 5))
        XCTAssertTrue(element("skill-provider-codex-system-skill-codex").exists)
        XCTAssertFalse(element("skill-provider-codex-system-skill-claude").exists, "A built-in names only the provider it ships with.")
        XCTAssertTrue(element("skill-provider-synced-skill-claude").exists)
        XCTAssertTrue(element("skill-row-simplify").waitForExistence(timeout: 20), "Claude Code's built-ins load from its own session.")
        XCTAssertTrue(element("skill-provider-simplify-claude").exists)
        attachScreenshot(named: "Skills page Built-in tab")

        let catalog = try skillCatalog(taskID: taskID, includeBundled: true)
        let sections = try XCTUnwrap(catalog["repositories"] as? [[String: Any]])
        XCTAssertEqual(sections.map { $0["name"] as? String }, ["skills-catalog-repo", "skills-empty-repo"])
        XCTAssertEqual(sections[0]["repositoryPath"] as? String, repository.path, "Repository skills are keyed by the source repository.")
        XCTAssertNotEqual(realPath(sections[0]["rootPath"] as? String ?? ""), realPath(repository.path), "Skills are read from the task worktree.")
        let repoSkills = skillsByName(sections[0]["skills"])
        XCTAssertEqual(repoSkills["repo-dup"]?["conflict"] as? Bool, true)
        XCTAssertEqual(repoSkills["repo-shared"]?["availableOutsidePlayhouse"] as? Bool, true)
        XCTAssertEqual(repoSkills["repo-broken"]?["providers"] as? [String], [])
        XCTAssertEqual(skillsByName(catalog["builtin"])["simplify"]?["providers"] as? [String], ["claude"])
        let detail = try XCTUnwrap(try runCLI(["skills", "get", "--task", taskID, "--skill", "repo:\(repository.path)#repo-agents"])["result"] as? [String: Any])
        XCTAssertEqual(detail["content"] as? String, skillManifest("repo-agents", "Agents layout repository skill"))
        assertCLIError(try runCLI(["skills", "get", "--task", taskID, "--skill", "global:no-such-skill"], expectedStatus: 3), code: "not_found")

        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 5), "Back returns to the conversation.")
        XCTAssertTrue(element("message-composer").waitForExistence(timeout: 5))
    }

    // case-contract: test_skills_create_update_move_and_delete_on_disk | Creating a skill writes SKILL.md with name and description frontmatter into the open Agent Skills layout, ~/.agents/skills for a global skill or the chosen task worktree's .agents/skills for a repository skill; invalid names, a missing description, a duplicate name, and the built-in scope are rejected with nothing written. Editing saves the new SKILL.md exactly as written, keeping frontmatter Playhouse does not parse, and rejects a renamed or description-less frontmatter while keeping the file. Clicking a skill row opens the editor modal straight on its whole SKILL.md, frontmatter included, with no structured header form, and its Preview tab shows that Markdown rendered with the frontmatter as a table; saving there writes the edited file, a description-less edit is rejected in the editor while keeping the file, and after the editor closes the page still answers clicks. A structured CLI edit rewrites the header (reading a YAML list as one field), removes an emptied field, keeps frontmatter Playhouse does not edit, and rejects an unknown field or an empty description while keeping the file. Clicking a built-in skill with a folder opens it read-only, without Save. New Skill asks only for a name, a description, and instructions it can preview, and a header field given to the CLI's create is written into the new SKILL.md. Moving a skill between a repository and the global gallery moves its folder and rejects a move onto an existing name. Deleting removes the folder from disk, built-in skills are read-only, and every change is visible to a fresh CLI process and on the Skills page.
    func test_skills_create_update_move_and_delete_on_disk() throws {
        let repository = try makeSkillRepository("skills-manage-repo", skills: [:])
        // The Skills page reads Claude Code's built-ins from a provider session.
        _ = try installSkillsClaudeFixture("claude-fixture-skills-manage")
        try writeSkill(in: skillsCodexHome.appendingPathComponent("skills/.system"), "codex-system-skill", "Bundled with Codex")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Skills manage", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        let globalFolder = skillsHome.appendingPathComponent(".agents/skills")
        openTask(named: "Skills manage")
        openSkillsPage()

        element("new-skill-button").click()
        let name = element("new-skill-name")
        XCTAssertTrue(name.waitForExistence(timeout: 5), "New Skill should open its sheet.")
        typeIntoField(name, text: "Release Notes")
        typeIntoField(element("new-skill-description"), text: "Draft release notes")
        element("new-skill-create").click()
        XCTAssertTrue(element("new-skill-error").waitForExistence(timeout: 5), "An invalid name shows an error in the sheet.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.path), "A rejected skill writes nothing.")
        attachScreenshot(named: "New Skill sheet rejects an invalid name")
        name.click()
        name.typeKey("a", modifierFlags: .command)
        name.typeText("release-notes")
        typeIntoField(element("new-skill-body"), text: "Summarize merged changes.")
        element("new-skill-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-skill-name").exists }, timeout: 10), "Creating closes the sheet.")
        XCTAssertTrue(element("skill-row-release-notes").waitForExistence(timeout: 10), "The new skill shows on the Global tab.")
        let manifest = globalFolder.appendingPathComponent("release-notes/SKILL.md")
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8),
                       "---\nname: release-notes\ndescription: \"Draft release notes\"\n---\n\nSummarize merged changes.\n")
        assertCLIError(try runCLI(["skills", "create", "--task", taskID, "--scope", "global", "--name", "release-notes", "--description", "Again"], expectedStatus: 1), code: "already_exists")
        assertCLIError(try runCLI(["skills", "create", "--task", taskID, "--scope", "global", "--name", "release-notes"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["skills", "create", "--task", taskID, "--scope", "builtin", "--name", "other", "--description", "Built-in"], expectedStatus: 2), code: "invalid_argument")

        let row = element("skill-row-release-notes")
        row.click()
        let editor = element("skill-editor")
        XCTAssertTrue(element("skill-editor-panel").waitForExistence(timeout: 5), "Clicking a skill opens its editor modal.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("skill-editor-name")), "release-notes", "The editor is titled with the skill's name.")
        let created = "---\nname: release-notes\ndescription: \"Draft release notes\"\n---\n\nSummarize merged changes.\n"
        XCTAssertEqual(editor.value as? String, created, "The editor opens the whole SKILL.md, frontmatter included.")
        for structured in ["skill-editor-description", "skill-editor-field-license", "skill-editor-field-compatibility", "skill-editor-field-allowed-tools"] {
            XCTAssertFalse(element(structured).exists, "The editor has no structured header field \(structured).")
        }
        attachScreenshot(named: "The skill editor opens SKILL.md for editing")
        selectSkillsTab("Preview", picker: "skill-editor-tab-picker")
        let preview = element("skill-editor-preview")
        XCTAssertTrue(preview.waitForExistence(timeout: 5), "The Preview tab shows the Markdown rendered.")
        XCTAssertFalse(editor.exists, "The Preview tab replaces the text editor.")
        XCTAssertTrue(element("skill-editor-preview-frontmatter").staticTexts["release-notes"].exists, "The preview shows the frontmatter as a table of its entries.")
        XCTAssertTrue(preview.staticTexts["Summarize merged changes."].exists, "The preview renders the instructions.")
        XCTAssertFalse(preview.staticTexts["---"].exists, "The preview does not show the raw frontmatter fences.")
        attachScreenshot(named: "The skill editor's Preview tab renders the Markdown")
        selectSkillsTab("Edit", picker: "skill-editor-tab-picker")
        XCTAssertTrue(editor.waitForExistence(timeout: 5))
        editor.click()
        editor.typeKey("a", modifierFlags: .command)
        editor.typeText("---\nname: release-notes\n---\n\nNo description.\n")
        element("skill-editor-save").click()
        XCTAssertTrue(element("skill-editor-error").waitForExistence(timeout: 5), "A description-less SKILL.md is rejected in the editor.")
        attachScreenshot(named: "The skill editor rejects a SKILL.md without a description")
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8), created, "A rejected edit keeps the file.")

        // Cancel discards the edit, and the page still answers clicks once the editor is gone.
        element("skill-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("skill-editor-panel").exists }, timeout: 5), "Cancel closes the editor.")
        selectSkillsTab("Repo")
        XCTAssertTrue(element("skills-empty-skills-manage-repo").waitForExistence(timeout: 5), "After the editor closes, a click on the Repo tab still switches tabs.")
        selectSkillsTab("Global")
        XCTAssertTrue(row.waitForExistence(timeout: 5), "A click on the Global tab switches back.")
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8), created, "Cancel discards the edit.")
        row.click()
        XCTAssertTrue(element("skill-editor-panel").waitForExistence(timeout: 5), "A click on the skill row opens the editor again after it was closed.")
        XCTAssertEqual(editor.value as? String, created, "The reopened editor shows the file, not the discarded edit.")
        let edited = "---\nname: release-notes\ndescription: Draft concise release notes\nmetadata:\n  owner: docs\n---\n\n# Release notes\n\n- Group changes by area.\n"
        editor.click()
        editor.typeKey("a", modifierFlags: .command)
        editor.typeText(edited)
        selectSkillsTab("Preview", picker: "skill-editor-tab-picker")
        XCTAssertTrue(waitUntil({ self.element("skill-editor-preview").staticTexts["Release notes"].exists }, timeout: 5), "The preview renders a heading.")
        XCTAssertTrue(element("skill-editor-preview").staticTexts["Group changes by area."].exists, "The preview renders a list item.")
        attachScreenshot(named: "Previewing an edited skill before saving")
        element("skill-editor-save").click()
        XCTAssertTrue(waitUntil({ !self.element("skill-editor-panel").exists }, timeout: 10), "Saving closes the editor.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("skill-description-release-notes")) == "Draft concise release notes" }, timeout: 10))
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8), edited, "Saving writes the file exactly as edited, keeping frontmatter Playhouse does not parse.")
        let renamed = dataDirectory.appendingPathComponent("skill-edit-renamed.md")
        try skillManifest("other-name", "Renamed").write(to: renamed, atomically: true, encoding: .utf8)
        assertCLIError(try runCLI(["skills", "update", "--task", taskID, "--skill", "global:release-notes", "--content-file", renamed.path], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8), edited, "A rejected edit keeps the file.")

        // The CLI's structured edit still reads and rewrites the header fields.
        try "---\nname: release-notes\ndescription: Draft concise release notes\nallowed-tools:\n  - Read\n  - Bash\nmetadata:\n  owner: docs\n---\n\nGroup changes by area.\n"
            .write(to: manifest, atomically: true, encoding: .utf8)
        let parsed = try XCTUnwrap(try runCLI(["skills", "get", "--task", taskID, "--skill", "global:release-notes"])["result"] as? [String: Any])
        XCTAssertEqual((parsed["manifest"] as? [String: Any])?["fields"] as? [String: String], ["allowed-tools": "Read, Bash"], "A YAML list reads as one field.")
        _ = try runCLI(["skills", "update", "--task", taskID, "--skill", "global:release-notes", "--description", "Draft release notes by area",
                        "--field", "license=MIT", "--field", "allowed-tools=", "--body", "List each change under its area."])
        XCTAssertEqual(try String(contentsOf: manifest, encoding: .utf8),
                       "---\nname: release-notes\ndescription: \"Draft release notes by area\"\nlicense: \"MIT\"\nmetadata:\n  owner: docs\n---\n\nList each change under its area.\n",
                       "A structured edit rewrites the header, removes an emptied field, and keeps unknown keys.")
        assertCLIError(try runCLI(["skills", "update", "--task", taskID, "--skill", "global:release-notes", "--field", "model=opus"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["skills", "update", "--task", taskID, "--skill", "global:release-notes", "--description", "  "], expectedStatus: 2), code: "invalid_argument")
        XCTAssertTrue(try String(contentsOf: manifest, encoding: .utf8).contains("List each change under its area."), "A rejected structured edit keeps the file.")
        _ = try runCLI(["skills", "create", "--task", taskID, "--scope", "global", "--name", "fielded", "--description", "Has header fields",
                        "--field", "compatibility=Needs git", "--body", "Steps."])
        XCTAssertEqual(try String(contentsOf: globalFolder.appendingPathComponent("fielded/SKILL.md"), encoding: .utf8),
                       "---\nname: fielded\ndescription: \"Has header fields\"\ncompatibility: \"Needs git\"\n---\n\nSteps.\n",
                       "A header field given to the CLI's create is written into SKILL.md.")
        _ = try runCLI(["skills", "delete", "--task", taskID, "--skill", "global:fielded"])
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("fielded").path))
        row.click()
        XCTAssertTrue(waitUntil({ (self.element("skill-editor").value as? String)?.contains("license: \"MIT\"") == true }, timeout: 5),
                      "The editor shows a CLI edit as it is on disk.")
        element("skill-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("skill-editor-panel").exists }, timeout: 5))

        element("new-skill-button").click()
        XCTAssertTrue(element("new-skill-name").waitForExistence(timeout: 5))
        typeIntoField(element("new-skill-name"), text: "repo-new")
        typeIntoField(element("new-skill-description"), text: "Repository only")
        XCTAssertFalse(element("new-skill-field-compatibility").exists || element("new-skill-field-license").exists,
                       "New Skill has no structured header fields.")
        typeIntoField(element("new-skill-body"), text: "## Steps\n\n1. Check the repository.")
        selectSkillsTab("Preview", picker: "new-skill-tab-picker")
        XCTAssertTrue(waitUntil({ self.element("new-skill-preview").staticTexts["Steps"].exists }, timeout: 5), "New Skill previews its instructions as Markdown.")
        attachScreenshot(named: "New Skill asks for a name, a description, and instructions")
        let destination = element("new-skill-scope")
        destination.click()
        let repositoryOption = app.menuItems["skills-manage-repo"]
        XCTAssertTrue(repositoryOption.waitForExistence(timeout: 5), "Save to should offer the task's repository.")
        repositoryOption.click()
        element("new-skill-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-skill-name").exists }, timeout: 10))
        XCTAssertTrue(FileManager.default.fileExists(atPath: worktree.appendingPathComponent(".agents/skills/repo-new/SKILL.md").path),
                      "A repository skill is written into the chosen task worktree.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: repository.appendingPathComponent(".agents").path), "The source checkout is left alone.")
        XCTAssertEqual(try String(contentsOf: worktree.appendingPathComponent(".agents/skills/repo-new/SKILL.md"), encoding: .utf8),
                       "---\nname: repo-new\ndescription: \"Repository only\"\n---\n\n## Steps\n\n1. Check the repository.\n",
                       "New Skill writes the name, description, and instructions into SKILL.md.")
        selectSkillsTab("Repo")
        XCTAssertTrue(element("skill-row-repo-new").waitForExistence(timeout: 10))
        clickSkillMenuItem(skill: "repo-new", item: "skill-move-global-repo-new", title: "Move to Global")
        XCTAssertTrue(waitUntil({ !self.element("skill-row-repo-new").exists }, timeout: 10), "A moved skill leaves the Repo tab.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("repo-new/SKILL.md").path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: worktree.appendingPathComponent(".agents/skills/repo-new").path))
        assertCLIError(try runCLI(["skills", "move", "--task", taskID, "--skill", "global:repo-new", "--scope", "global"], expectedStatus: 2), code: "invalid_argument")
        selectSkillsTab("Global")
        clickSkillMenuItem(skill: "repo-new", item: "skill-move-repo-repo-new-skills-manage-repo", title: "Move to skills-manage-repo")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: worktree.appendingPathComponent(".agents/skills/repo-new/SKILL.md").path) }, timeout: 10),
                      "A global skill moves into the chosen worktree.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("repo-new").path))
        selectSkillsTab("Repo")
        clickSkillMenuItem(skill: "repo-new", item: "skill-move-global-repo-new", title: "Move to Global")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("repo-new/SKILL.md").path) }, timeout: 10))
        try writeSkill(in: worktree.appendingPathComponent(".claude/skills"), "release-notes", "A repository skill with the same name")
        assertCLIError(try runCLI(["skills", "move", "--task", taskID, "--skill", "global:release-notes", "--scope", "repo", "--root", repository.path], expectedStatus: 1), code: "already_exists")
        XCTAssertTrue(FileManager.default.fileExists(atPath: manifest.path), "A rejected move leaves the skill in place.")

        selectSkillsTab("Global")
        XCTAssertTrue(element("skill-row-repo-new").waitForExistence(timeout: 10))
        clickSkillMenuItem(skill: "repo-new", item: "skill-delete-repo-new", title: "Delete…")
        XCTAssertTrue(waitUntil({ self.element("confirm-delete-skill").exists || self.app.buttons["Delete"].exists }, timeout: 5))
        attachScreenshot(named: "Delete skill confirmation")
        clickDialogButton("confirm-delete-skill", title: "Delete")
        XCTAssertTrue(waitUntil({ !self.element("skill-row-repo-new").exists }, timeout: 10), "A deleted skill leaves the page.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("repo-new").path), "Deleting removes the folder from disk.")
        attachScreenshot(named: "Global tab after deleting a skill")
        let fresh = try skillCatalog(taskID: taskID)
        XCTAssertEqual(skillsByName(fresh["global"]).keys.sorted(), ["release-notes"])
        XCTAssertEqual(skillsByName(fresh["global"])["release-notes"]?["description"] as? String, "Draft release notes by area")

        selectSkillsTab("Built-in")
        XCTAssertTrue(element("skill-row-codex-system-skill").waitForExistence(timeout: 10))
        element("skill-actions-codex-system-skill").click()
        XCTAssertTrue(app.menuItems["Reveal in Finder"].waitForExistence(timeout: 5), "The built-in's actions menu should open.")
        for title in ["Edit…", "Delete…", "Move to Global"] {
            XCTAssertFalse(app.menuItems[title].exists, "A built-in skill is read-only, so its menu has no \(title).")
        }
        app.typeKey(.escape, modifierFlags: [])
        element("skill-row-codex-system-skill").click()
        XCTAssertTrue(element("skill-editor-panel").waitForExistence(timeout: 5), "Clicking a built-in skill shows it.")
        let builtinText = element("skill-editor").value as? String
        XCTAssertTrue(builtinText?.contains("Bundled with Codex") == true, "A built-in skill shows its SKILL.md.")
        element("skill-editor").click()
        element("skill-editor").typeText("typed")
        XCTAssertEqual(element("skill-editor").value as? String, builtinText, "A built-in skill's SKILL.md cannot be edited.")
        XCTAssertFalse(element("skill-editor-save").exists, "A built-in skill cannot be saved.")
        attachScreenshot(named: "A built-in skill opens read-only")
        element("skill-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("skill-editor-panel").exists }, timeout: 5))
        assertCLIError(try runCLI(["skills", "delete", "--task", taskID, "--skill", "builtin:codex:codex-system-skill"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertTrue(FileManager.default.fileExists(atPath: skillsCodexHome.appendingPathComponent("skills/.system/codex-system-skill").path))
    }

    // case-contract: test_skills_enable_state_and_outside_links_persist | Turning a skill off is stored by Playhouse rather than in either provider's settings, survives fresh CLI processes and reopening the Skills page, and can be turned back on. The small switch flips as soon as it is clicked, and turning a skill on disk on or off never starts a Claude Code session. Making a skill available outside Playhouse writes a real symlink into the other provider's layout (an absolute link in Claude's global skills folder, a relative link inside the repository), after which the skill shows as Linked; an existing file at the link path is left untouched and the request fails with already_exists, removing the outside link deletes only the symlink and keeps the skill, and a skill without a link cannot be unlinked.
    func test_skills_enable_state_and_outside_links_persist() throws {
        let repository = try makeSkillRepository("skills-link-repo", skills: [
            ".agents/skills/repo-agents/SKILL.md": skillManifest("repo-agents", "Repository agents skill"),
        ])
        try writeSkill(in: skillsHome.appendingPathComponent(".agents/skills"), "global-agents", "Global agents skill")
        try writeSkill(in: skillsHome.appendingPathComponent(".agents/skills"), "blocked", "Its link path is taken")
        // The Skills page reads Claude Code's built-ins from a provider session.
        let claudeExecutable = try installSkillsClaudeFixture("claude-fixture-skills-link")
        let sessionsURL = URL(fileURLWithPath: claudeExecutable.path + ".sessions")
        func claudeSessions() -> Int { ((try? String(contentsOf: sessionsURL, encoding: .utf8)) ?? "").split(separator: "\n").count }
        let claudeSkills = skillsHome.appendingPathComponent(".claude/skills")
        try FileManager.default.createDirectory(at: claudeSkills, withIntermediateDirectories: true)
        try "Not a skill, just a file in the way.\n".write(to: claudeSkills.appendingPathComponent("blocked"), atomically: true, encoding: .utf8)
        launchApp(defaultParent: fixture.parent.path)
        // The window reads Claude's plan usage once at launch, in a session of its own; count from after it.
        let usageReadsURL = URL(fileURLWithPath: claudeExecutable.path + ".usage-reads")
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: usageReadsURL.path) }, timeout: 30), "Launch reads Claude's plan usage.")
        let sessionsAtLaunch = claudeSessions()
        let task = try createSkillsTask("Skills links", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        func globalSkill(_ name: String) throws -> [String: Any]? { skillsByName(try skillCatalog(taskID: taskID)["global"])[name] }
        openTask(named: "Skills links")
        openSkillsPage()
        selectSkillsTab("Global")

        let toggle = element("skill-toggle-global-agents")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertTrue(isOn(toggle))
        // The page reads Claude Code's built-ins once when it opens.
        XCTAssertTrue(waitUntil({ claudeSessions() > sessionsAtLaunch }, timeout: 20), "Opening the Skills page reads Claude Code's built-ins.")
        let sessionsBeforeToggle = claudeSessions()
        toggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(toggle) }, timeout: 0.75), "The switch flips as soon as it is clicked.")
        XCTAssertTrue(waitUntil({ ((try? globalSkill("global-agents"))??["enabled"] as? Bool) == false }, timeout: 10),
                      "Turning a skill off is saved where a fresh CLI process reads it.")
        XCTAssertFalse(waitUntil({ claudeSessions() > sessionsBeforeToggle }, timeout: 3),
                       "Turning a skill on disk off must not start a Claude Code session.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: skillsCodexHome.appendingPathComponent("config.toml").path), "Codex's config is not written.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: skillsHome.appendingPathComponent(".claude/settings.json").path), "Claude's settings are not written.")
        element("skills-back-button").click()
        openSkillsPage()
        selectSkillsTab("Global")
        XCTAssertTrue(waitUntil({ self.element("skill-toggle-global-agents").exists && !self.isOn(self.element("skill-toggle-global-agents")) }, timeout: 10),
                      "The off state survives reopening the Skills page.")
        attachScreenshot(named: "A skill turned off on the Global tab")
        let sessionsBeforeTurningOn = claudeSessions()
        element("skill-toggle-global-agents").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("skill-toggle-global-agents")) }, timeout: 0.75), "The switch flips back at once.")
        XCTAssertTrue(waitUntil({ ((try? globalSkill("global-agents"))??["enabled"] as? Bool) == true }, timeout: 10))
        XCTAssertFalse(waitUntil({ claudeSessions() > sessionsBeforeTurningOn }, timeout: 3),
                       "Turning a skill on disk back on must not start a Claude Code session.")

        clickSkillMenuItem(skill: "global-agents", item: "skill-link-global-agents", title: "Make Available Outside Playhouse…")
        XCTAssertTrue(waitUntil({ self.element("confirm-link-skill").exists || self.app.buttons["Create Link"].exists }, timeout: 5))
        attachScreenshot(named: "Make available outside Playhouse confirmation")
        clickDialogButton("confirm-link-skill", title: "Create Link")
        XCTAssertTrue(element("skill-linked-global-agents").waitForExistence(timeout: 10), "A linked skill shows as Linked.")
        let link = claudeSkills.appendingPathComponent("global-agents")
        XCTAssertEqual(realPath(try FileManager.default.destinationOfSymbolicLink(atPath: link.path)),
                       realPath(skillsHome.appendingPathComponent(".agents/skills/global-agents").path))
        attachScreenshot(named: "A global skill linked for use outside Playhouse")

        clickSkillMenuItem(skill: "blocked", item: "skill-link-blocked", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-skill", title: "Create Link")
        XCTAssertTrue(element("skills-error").waitForExistence(timeout: 10), "A link onto an existing file shows an error.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("skills-error")).contains("already exists"), "The error names the existing file.")
        attachScreenshot(named: "A blocked outside link shows its error")
        XCTAssertEqual(try String(contentsOf: claudeSkills.appendingPathComponent("blocked"), encoding: .utf8), "Not a skill, just a file in the way.\n")
        assertCLIError(try runCLI(["skills", "link", "--task", taskID, "--skill", "global:blocked"], expectedStatus: 1), code: "already_exists")

        selectSkillsTab("Repo")
        clickSkillMenuItem(skill: "repo-agents", item: "skill-link-repo-agents", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-skill", title: "Create Link")
        XCTAssertTrue(element("skill-linked-repo-agents").waitForExistence(timeout: 10))
        XCTAssertEqual(try FileManager.default.destinationOfSymbolicLink(atPath: worktree.appendingPathComponent(".claude/skills/repo-agents").path),
                       "../../.agents/skills/repo-agents", "A repository link is relative, so it can be committed.")

        selectSkillsTab("Global")
        clickSkillMenuItem(skill: "global-agents", item: "skill-unlink-global-agents", title: "Remove Outside Link")
        XCTAssertTrue(waitUntil({ !self.element("skill-linked-global-agents").exists }, timeout: 10))
        XCTAssertNil(try? FileManager.default.destinationOfSymbolicLink(atPath: link.path), "Removing the outside link deletes only the symlink.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: skillsHome.appendingPathComponent(".agents/skills/global-agents/SKILL.md").path))
        assertCLIError(try runCLI(["skills", "unlink", "--task", taskID, "--skill", "global:global-agents"], expectedStatus: 2), code: "invalid_argument")
    }

    private func selectionCount() -> String { accessibleLabelOrValue(of: element("skills-selection-count")) }

    private func boardTaskRecords() throws -> [[String: Any]] {
        try XCTUnwrap((try runCLI(["board", "list"])["result"] as? [String: Any])?["tasks"] as? [[String: Any]])
    }

    // case-contract: test_skills_select_many_and_delete_together | Pressing and holding a skill row starts selecting skills, with no separate Select button: each editable row shows a checkbox that a click toggles, built-in skills show none and cannot be selected, and the header shows how many are selected with Fix with Agent, Delete, and Done. Deleting the selection after one confirmation removes every selected skill folder, repository and global alike, from disk, leaves unselected skills in place, forgets a deleted skill's off state, and ends selecting. A batch that includes a read-only or unknown skill deletes nothing and fails with invalid_argument or not_found.
    func test_skills_select_many_and_delete_together() throws {
        let repository = try makeSkillRepository("skills-select-repo", skills: [
            ".agents/skills/repo-one/SKILL.md": skillManifest("repo-one", "First repository skill"),
            ".agents/skills/repo-keep/SKILL.md": skillManifest("repo-keep", "Stays after the bulk delete"),
        ])
        let globalFolder = skillsHome.appendingPathComponent(".agents/skills")
        for name in ["global-one", "global-two"] { try writeSkill(in: globalFolder, name, "Global skill \(name)") }
        try writeSkill(in: skillsCodexHome.appendingPathComponent("skills/.system"), "codex-system-skill", "Bundled with Codex")
        _ = try installSkillsClaudeFixture("claude-fixture-skills-select")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Skills select", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        _ = try runCLI(["skills", "disable", "--task", taskID, "--skill", "global:global-two"])
        openTask(named: "Skills select")
        openSkillsPage()

        // There is no Select button: a press and hold is how selecting starts, and Done leaves it.
        XCTAssertTrue(element("new-skill-button").waitForExistence(timeout: 5))
        XCTAssertFalse(element("skills-select-button").exists, "The header has no Select button.")
        element("skill-actions-repo-one").click()
        XCTAssertTrue(app.menuItems["Delete…"].waitForExistence(timeout: 5), "The actions menu should open.")
        XCTAssertFalse(app.menuItems["Select"].exists, "The actions menu has no Select item.")
        app.typeKey(.escape, modifierFlags: [])
        element("skill-row-repo-one").press(forDuration: 1.0)
        XCTAssertTrue(element("skill-select-repo-one").waitForExistence(timeout: 5), "Selecting shows a checkbox on each row.")
        XCTAssertFalse(element("skill-editor-panel").exists, "A press and hold selects rather than opening the editor.")
        element("skills-selection-done").click()
        XCTAssertTrue(waitUntil({ !self.element("skill-select-repo-one").exists }, timeout: 5), "Done stops selecting.")
        XCTAssertTrue(element("skill-toggle-repo-one").exists, "Rows show their controls again.")

        // Press and hold a row to start selecting with it.
        element("skill-row-repo-one").press(forDuration: 1.0)
        XCTAssertTrue(waitUntil({ self.element("skills-selection-count").exists }, timeout: 5), "Pressing and holding a skill starts selecting.")
        XCTAssertEqual(selectionCount(), "1 selected", "The pressed skill is selected.")
        XCTAssertEqual(element("skill-select-repo-one").label, "Selected", "The pressed skill's checkbox is checked.")
        XCTAssertEqual(element("skill-select-repo-keep").label, "Not selected")
        XCTAssertFalse(element("skill-toggle-repo-one").exists, "Selecting hides a row's own controls.")
        selectSkillsTab("Global")
        element("skill-row-global-one").click()
        element("skill-row-global-two").click()
        XCTAssertTrue(waitUntil({ self.selectionCount() == "3 selected" }, timeout: 5), "A click selects a skill, across tabs.")
        attachScreenshot(named: "Several skills selected for one action")
        selectSkillsTab("Built-in")
        XCTAssertTrue(element("skill-row-codex-system-skill").waitForExistence(timeout: 10))
        XCTAssertFalse(element("skill-select-codex-system-skill").exists, "A built-in skill shows no checkbox.")
        element("skill-row-codex-system-skill").click()
        XCTAssertEqual(selectionCount(), "3 selected", "A built-in skill cannot be selected.")
        selectSkillsTab("Global")
        element("skill-row-global-two").click()
        XCTAssertTrue(waitUntil({ self.selectionCount() == "2 selected" }, timeout: 5), "Clicking a selected skill deselects it.")
        XCTAssertEqual(element("skill-select-global-two").label, "Not selected")
        element("skill-row-global-two").click()
        XCTAssertTrue(waitUntil({ self.selectionCount() == "3 selected" }, timeout: 5))

        assertCLIError(try runCLI(["skills", "delete", "--task", taskID, "--skill", "global:global-one", "--skill", "builtin:codex:codex-system-skill"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["skills", "delete", "--task", taskID, "--skill", "global:global-one", "--skill", "global:no-such-skill"], expectedStatus: 3), code: "not_found")
        XCTAssertTrue(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("global-one").path), "A rejected batch deletes nothing.")

        element("skills-delete-selected").click()
        XCTAssertTrue(waitUntil({ self.element("confirm-delete-skill").exists || self.app.buttons["Delete"].exists }, timeout: 5))
        attachScreenshot(named: "Delete several skills confirmation")
        clickDialogButton("confirm-delete-skill", title: "Delete")
        XCTAssertTrue(waitUntil({ !self.element("skill-row-global-one").exists && !self.element("skill-row-global-two").exists }, timeout: 10),
                      "Deleted skills leave the page.")
        XCTAssertTrue(element("new-skill-button").waitForExistence(timeout: 5), "Deleting the selection ends selecting.")
        attachScreenshot(named: "Global tab after deleting several skills")
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("global-one").path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: globalFolder.appendingPathComponent("global-two").path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: worktree.appendingPathComponent(".agents/skills/repo-one").path),
                       "A repository skill in the selection is deleted from the worktree.")
        XCTAssertTrue(FileManager.default.fileExists(atPath: worktree.appendingPathComponent(".agents/skills/repo-keep/SKILL.md").path), "Unselected skills stay.")
        selectSkillsTab("Repo")
        XCTAssertTrue(element("skill-row-repo-keep").waitForExistence(timeout: 5))
        XCTAssertFalse(element("skill-row-repo-one").exists)
        let fresh = try skillCatalog(taskID: taskID)
        XCTAssertEqual((fresh["global"] as? [Any])?.count, 0)
        XCTAssertEqual(skillsByName((fresh["repositories"] as? [[String: Any]])?.first?["skills"]).keys.sorted(), ["repo-keep"])
        try writeSkill(in: globalFolder, "global-two", "Recreated with the same name")
        XCTAssertEqual(skillsByName(try skillCatalog(taskID: taskID)["global"])["global-two"]?["enabled"] as? Bool, true,
                       "Deleting a skill forgets that it was turned off.")
    }

    // case-contract: test_skills_fix_with_agent_starts_task_for_repo_and_global_skills | A conflicting or invalid skill offers Fix with Agent, and several selected skills can be fixed in one task. Fixing creates a task, on the source task's provider, whose saved prompt teaches the agent the skill format and lists each skill with its problem: repository skills by repository-relative path, to be fixed in the new task's own worktree of the source repository and committed and pushed like any code change, and global skills by absolute path, to be fixed in place with nothing to commit; the global skill folders are opened to the agent as context folders, and fixing only global skills needs no repository. The view switches to the new task's conversation, which sends that prompt as its own composer draft, leaving the composer empty and no unsent draft behind, so the turn runs in the new task's worktree with the global folders reachable. A skill with no problem, a built-in skill, an unknown skill, and a request without a task are rejected without opening a task.
    func test_skills_fix_with_agent_starts_task_for_repo_and_global_skills() throws {
        let repository = try makeSkillRepository("skills-fix-repo", skills: [
            ".agents/skills/repo-dup/SKILL.md": skillManifest("repo-dup", "The agents copy"),
            ".claude/skills/repo-dup/SKILL.md": skillManifest("repo-dup", "A different Claude copy"),
            ".agents/skills/repo-ok/SKILL.md": skillManifest("repo-ok", "Nothing to fix"),
        ])
        try writeSkill(in: skillsHome.appendingPathComponent(".agents/skills"), "global-dup", "The global agents copy")
        try writeSkill(in: skillsHome.appendingPathComponent(".claude/skills"), "global-dup", "The global Claude copy")
        let broken = skillsHome.appendingPathComponent(".agents/skills/global-broken")
        try FileManager.default.createDirectory(at: broken, withIntermediateDirectories: true)
        try "No frontmatter here.\n".write(to: broken.appendingPathComponent("SKILL.md"), atomically: true, encoding: .utf8)
        try writeSkill(in: skillsCodexHome.appendingPathComponent("skills/.system"), "codex-system-skill", "Bundled with Codex")
        let executable = try installSkillsClaudeFixture("claude-fixture-skills-fix")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        func turns() -> [[String: Any]] {
            guard let data = try? Data(contentsOf: historyURL),
                  let history = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return [] }
            return (history["turns"] as? [[String: Any]] ?? []).filter { ($0["userText"] as? String)?.isEmpty == false }
        }
        launchApp(defaultParent: fixture.parent.path)
        let source = try createSkillsTask("Skills fix source", repositories: [repository], provider: "claude")
        let sourceID = try XCTUnwrap(source["id"] as? String)
        let sourceWorktree = try XCTUnwrap((source["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String)
        let tasksBefore = try boardTaskRecords().count
        assertCLIError(try runCLI(["skills", "fix", "--task", sourceID, "--skill", "repo:\(repository.path)#repo-ok"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["skills", "fix", "--task", sourceID, "--skill", "builtin:codex:codex-system-skill"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["skills", "fix", "--task", sourceID, "--skill", "global:no-such-skill"], expectedStatus: 3), code: "not_found")
        assertCLIError(try runCLI(["skills", "fix", "--skill", "global:global-dup"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try boardTaskRecords().count, tasksBefore, "A rejected fix opens no task.")

        openTask(named: "Skills fix source")
        openSkillsPage()
        XCTAssertTrue(element("skill-fix-repo-dup").waitForExistence(timeout: 10), "A conflicting skill offers Fix with Agent.")
        XCTAssertFalse(element("skill-fix-repo-ok").exists, "A skill without a problem has nothing to fix.")
        selectSkillsTab("Global")
        XCTAssertTrue(element("skill-fix-global-dup").waitForExistence(timeout: 5))
        XCTAssertTrue(element("skill-fix-global-broken").exists, "An invalid skill offers Fix with Agent too.")
        attachScreenshot(named: "Conflicting and invalid skills offer Fix with Agent")

        // One skill, from its row: a global skill is fixed in place, with no repository.
        element("skill-fix-global-dup").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 10), "Fixing closes the Skills page.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == "Fix skill global-dup" }, timeout: 15),
                      "The view switches to the fixing task's conversation.")
        let single = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == "Fix skill global-dup" })
        XCTAssertEqual((single["repositoryWorktrees"] as? [Any])?.count, 0, "Fixing only global skills needs no repository.")
        XCTAssertTrue(waitUntil({ turns().contains { ($0["userText"] as? String)?.contains("`global-dup`") == true } }, timeout: 20),
                      "The fixing task sends its prompt as soon as it opens.")
        XCTAssertFalse(try XCTUnwrap(single["savedPrompt"] as? String).contains("commit and push"))

        // Several skills, selected across tabs, fixed in one task.
        openTask(named: "Skills fix source")
        openSkillsPage()
        XCTAssertTrue(element("skill-row-repo-dup").waitForExistence(timeout: 10))
        element("skill-row-repo-dup").press(forDuration: 1.0)
        XCTAssertTrue(waitUntil({ self.selectionCount() == "1 selected" }, timeout: 5))
        selectSkillsTab("Global")
        element("skill-row-global-dup").click()
        element("skill-row-global-broken").click()
        XCTAssertTrue(waitUntil({ self.selectionCount() == "3 selected" }, timeout: 5))
        attachScreenshot(named: "Several broken skills selected to fix in one task")
        element("skills-fix-selected").click()
        // The selection is sent in the gallery's order: repositories, then global skills by name.
        let title = "Fix skills repo-dup, global-broken, global-dup"
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == title }, timeout: 15),
                      "The view switches to the new task's conversation.")
        let fixing = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == title })
        let fixingID = try XCTUnwrap(fixing["id"] as? String)
        let prompt = try XCTUnwrap(fixing["savedPrompt"] as? String)
        XCTAssertEqual(fixing["conversationProvider"] as? String, "claude", "The fixing task uses the source task's provider.")
        XCTAssertTrue(prompt.contains("commit and push"))
        XCTAssertTrue(prompt.contains("`repo-dup` in skills-fix-repo: `.agents/skills/repo-dup`, `.claude/skills/repo-dup`"))
        XCTAssertFalse(prompt.contains(sourceWorktree), "Repository paths are relative, so they point into the fixing task's worktree.")
        XCTAssertTrue(prompt.contains("not tracked by Git: fix them directly in place"))
        XCTAssertTrue(prompt.contains("`global-broken`"))
        XCTAssertFalse(prompt.contains("repo-ok"))
        XCTAssertEqual(Set(((fixing["contextFolders"] as? [String]) ?? []).map(realPath)),
                       Set([".agents/skills", ".claude/skills"].map { realPath(skillsHome.appendingPathComponent($0).path) }),
                       "Global skill folders are opened to the agent.")
        XCTAssertTrue(waitUntil({ turns().contains { $0["userText"] as? String == prompt } }, timeout: 20), "The conversation sends the fixing prompt.")
        XCTAssertTrue(app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'user-message-'")).firstMatch.waitForExistence(timeout: 10),
                      "The prompt shows in the new task's conversation.")
        XCTAssertTrue(waitUntil({ (self.element("message-composer").value as? String ?? "").isEmpty }, timeout: 10),
                      "The sent prompt leaves the composer, so it cannot be sent twice.")
        attachScreenshot(named: "The fixing task's conversation after Fix with Agent")
        let turn = try XCTUnwrap(turns().first { $0["userText"] as? String == prompt })
        let started = try XCTUnwrap(try taskRecord(id: fixingID))
        XCTAssertEqual(started["hasUnsentDraft"] as? Bool, false, "The sent prompt leaves no unsent draft behind.")
        XCTAssertEqual(turns().filter { $0["userText"] as? String == prompt }.count, 1, "The fixing prompt is sent exactly once.")
        let worktree = try XCTUnwrap((started["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(worktree["repositoryPath"] as? String, repository.path)
        XCTAssertEqual(worktree["isPending"] as? Bool, false, "Starting the fix creates the task's own worktree.")
        let worktreePath = try XCTUnwrap(worktree["worktreePath"] as? String)
        XCTAssertNotEqual(realPath(worktreePath), realPath(sourceWorktree))
        XCTAssertEqual(realPath(turn["cwd"] as? String ?? ""), realPath(worktreePath), "The turn runs in the fixing task's worktree.")
        let arguments = try XCTUnwrap(turn["arguments"] as? [String])
        let directories = Set(arguments.indices.filter { arguments[$0] == "--add-dir" }.map { realPath(arguments[$0 + 1]) })
        for folder in [".agents/skills", ".claude/skills"] {
            XCTAssertTrue(directories.contains(realPath(skillsHome.appendingPathComponent(folder).path)), "Claude Code can reach the global \(folder) folder.")
        }
    }

    // case-contract: test_skills_bridge_claude_launch_sees_agents_skills | A Claude turn sees the skills Claude Code does not read natively: Playhouse passes a Playhouse-owned --add-dir wrapper whose .claude/skills links to the task worktree's and the global .agents/skills folders, leaves skills Claude already reads out of the wrapper, and turns disabled skills off for that run with --settings skillOverrides, without writing to the repository or Claude's settings. Using a skill from the Skills page puts /skill-name at the start of the composer and the message reaches Claude Code unchanged. The resumed second turn gets the same wrapper, and turning the skill back on drops the override.
    func test_skills_bridge_claude_launch_sees_agents_skills() throws {
        let repository = try makeSkillRepository("skills-claude-repo", skills: [
            ".agents/skills/repo-agents/SKILL.md": skillManifest("repo-agents", "Bridged to Claude"),
            ".claude/skills/repo-claude/SKILL.md": skillManifest("repo-claude", "Claude reads this natively"),
            ".claude/skills/repo-off/SKILL.md": skillManifest("repo-off", "Turned off in Playhouse"),
        ])
        try writeSkill(in: skillsHome.appendingPathComponent(".agents/skills"), "global-agents", "Global skill bridged to Claude")
        let executable = try installSkillsClaudeFixture("claude-fixture-skills-bridge")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Claude skills", repositories: [repository], provider: "claude")
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        func turns() -> [[String: Any]] {
            guard let data = try? Data(contentsOf: historyURL),
                  let history = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return [] }
            return (history["turns"] as? [[String: Any]] ?? []).filter { ($0["userText"] as? String)?.isEmpty == false }
        }
        openTask(named: "Claude skills")
        openSkillsPage()
        let offToggle = element("skill-toggle-repo-off")
        XCTAssertTrue(offToggle.waitForExistence(timeout: 10))
        offToggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("skill-toggle-repo-off")) }, timeout: 10))
        selectSkillsTab("Built-in")
        let bundledToggle = element("skill-toggle-simplify")
        XCTAssertTrue(bundledToggle.waitForExistence(timeout: 20), "Claude Code's built-ins load on the Built-in tab.")
        bundledToggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("skill-toggle-simplify")) }, timeout: 10))
        selectSkillsTab("Repo")
        element("skill-use-repo-agents").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 5), "Use returns to the conversation.")
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "/repo-agents " }, timeout: 5), "Use puts /skill-name at the start of the composer.")
        composer.typeText("Tell me a story.")
        attachScreenshot(named: "Composer with a skill inserted from the Skills page")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ turns().contains { $0["userText"] as? String == "/repo-agents Tell me a story." } }, timeout: 20),
                      "The skill invocation reaches Claude Code unchanged.")
        let first = try XCTUnwrap(turns().first { $0["userText"] as? String == "/repo-agents Tell me a story." })
        let arguments = try XCTUnwrap(first["arguments"] as? [String])
        let directories = arguments.indices.filter { arguments[$0] == "--add-dir" }.map { arguments[$0 + 1] }
        XCTAssertEqual(directories.count, 1, "One Playhouse wrapper should be added: \(arguments)")
        let wrapper = URL(fileURLWithPath: try XCTUnwrap(directories.first))
        XCTAssertEqual(realPath(wrapper.deletingLastPathComponent().path), realPath(dataDirectory.appendingPathComponent("skill-bridge/claude").path))
        let links = wrapper.appendingPathComponent(".claude/skills")
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: links.path).sorted(), ["global-agents", "repo-agents"],
                       "Only skills Claude does not read natively are bridged.")
        XCTAssertEqual(realPath(links.appendingPathComponent("repo-agents").path), realPath(worktree.appendingPathComponent(".agents/skills/repo-agents").path))
        let settingsIndex = try XCTUnwrap(arguments.firstIndex(of: "--settings"))
        let settings = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(arguments[settingsIndex + 1].utf8)) as? [String: [String: String]])
        XCTAssertEqual(settings, ["skillOverrides": ["repo-off": "off", "simplify": "off"]],
                       "Disabled repository and Claude built-in skills are turned off for this run.")
        XCTAssertEqual((first["skills"] as? [String])?.sorted(), ["global-agents", "repo-agents", "repo-claude"])
        XCTAssertEqual(try runGitOutput(worktree, "status", "--porcelain"), "", "The worktree is not written to.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String) == "Review" }, timeout: 20))

        openSkillsPage()
        element("skill-toggle-repo-off").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("skill-toggle-repo-off")) }, timeout: 10))
        selectSkillsTab("Built-in")
        XCTAssertTrue(element("skill-toggle-simplify").waitForExistence(timeout: 20))
        element("skill-toggle-simplify").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("skill-toggle-simplify")) }, timeout: 10))
        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Tell me a story again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ turns().contains { $0["userText"] as? String == "Tell me a story again." } }, timeout: 20))
        let second = try XCTUnwrap(turns().last { $0["userText"] as? String == "Tell me a story again." })
        XCTAssertEqual(second["resumed"] as? Bool, true, "The second turn resumes the Claude session.")
        let resumedArguments = try XCTUnwrap(second["arguments"] as? [String])
        XCTAssertEqual(resumedArguments.indices.filter { resumedArguments[$0] == "--add-dir" }.map { realPath(resumedArguments[$0 + 1]) },
                       [realPath(wrapper.path)], "A resumed turn gets the same wrapper.")
        XCTAssertFalse(resumedArguments.contains("--settings"), "Turning the skill back on drops the override.")
        XCTAssertTrue((second["skills"] as? [String])?.contains("repo-off") == true)
    }

    // case-contract: test_skills_bridge_codex_thread_sees_claude_skills | A Codex turn sees the skills Codex does not read natively: Playhouse gives the shared app-server extra skill roots made of Playhouse-owned wrapper folders that link to the task worktree's and the global .claude/skills folders, leaves the cwd repository's .agents/skills to Codex, and starts the thread with a per-thread skills config that disables both the task's disabled skills and other tasks' bridged skills, without writing Codex's config.toml. Using a skill from the Skills page puts /skill-name in the composer, and the turn sends Codex a structured skill input naming that skill's SKILL.md alongside the text; a later turn without a skill sends none.
    func test_skills_bridge_codex_thread_sees_claude_skills() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let historyURL = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".history")
        let other = try makeSkillRepository("skills-other-repo", skills: [
            ".claude/skills/other-claude/SKILL.md": skillManifest("other-claude", "Belongs to another task"),
        ])
        let repository = try makeSkillRepository("skills-codex-repo", skills: [
            ".claude/skills/repo-claude/SKILL.md": skillManifest("repo-claude", "Bridged to Codex"),
            ".agents/skills/repo-agents/SKILL.md": skillManifest("repo-agents", "Codex reads this natively"),
            ".agents/skills/repo-off/SKILL.md": skillManifest("repo-off", "Turned off in Playhouse"),
        ])
        try writeSkill(in: skillsHome.appendingPathComponent(".claude/skills"), "global-claude", "Global skill bridged to Codex")
        // The Skills page reads Claude Code's built-ins from a provider session.
        _ = try installSkillsClaudeFixture("claude-fixture-skills-codex")
        // Its own daemon, so restarting it below leaves the UI runner's shared one alone.
        let daemonEnvironment = ["PLAYHOUSE_BRIDGE_SERVICE_NAME": "\(serviceName!).skills-codex-\(UUID().uuidString.prefix(8))"]
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: daemonEnvironment)
        try createTaskFixture(title: "Other skills task", roots: [other.path])
        let otherBridge = try XCTUnwrap(try runCLI(["skills", "bridge", "--task", try taskID(named: "Other skills task")])["result"] as? [String: Any])
        let otherLink = try XCTUnwrap((otherBridge["codexLinks"] as? [[String: Any]])?.first?["link"] as? String)
        let otherWrapper = URL(fileURLWithPath: otherLink).deletingLastPathComponent()
        let task = try createSkillsTask("Codex skills", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        func history() -> [String: Any] {
            guard let data = try? Data(contentsOf: historyURL) else { return [:] }
            return (try? JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
        }
        func answerQuestionIfAsked() {
            guard element("ai-question-form-title").waitForExistence(timeout: 10) else { return }
            selectQuestionOption("Blue")
            typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
            element("submit-ai-answers-button").click()
        }

        openTask(named: "Codex skills")
        openSkillsPage()
        let offToggle = element("skill-toggle-repo-off")
        XCTAssertTrue(offToggle.waitForExistence(timeout: 10))
        offToggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("skill-toggle-repo-off")) }, timeout: 10))
        element("skill-use-repo-claude").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ (composer.value as? String) == "/repo-claude " }, timeout: 5), "Use puts /skill-name in the composer.")
        composer.typeText("Complete this task.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "/repo-claude Complete this task." }, timeout: 20))
        let sent = history()
        let skillInputs = try XCTUnwrap(sent["skillInputs"] as? [[String: String]])
        XCTAssertEqual(skillInputs.count, 1)
        XCTAssertEqual(skillInputs.first?["type"], "skill")
        XCTAssertEqual(skillInputs.first?["name"], "repo-claude")
        XCTAssertEqual(realPath(skillInputs.first?["path"] ?? ""), realPath(worktree.appendingPathComponent(".claude/skills/repo-claude/SKILL.md").path),
                       "Codex receives a structured skill input naming the skill's SKILL.md.")
        let bridge = try XCTUnwrap(try runCLI(["skills", "bridge", "--task", taskID])["result"] as? [String: Any])
        let ownWrapper = URL(fileURLWithPath: try XCTUnwrap((bridge["codexLinks"] as? [[String: Any]])?.first?["link"] as? String)).deletingLastPathComponent()
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: ownWrapper.path).filter { !$0.hasPrefix(".") }.sorted(), ["global-claude", "repo-claude"],
                       "The cwd repository's .agents skills stay native to Codex.")
        XCTAssertEqual(Set((sent["skillExtraRoots"] as? [String] ?? []).map(realPath)), Set([ownWrapper.path, otherWrapper.path].map(realPath)),
                       "The shared app-server gets every task's wrapper as an extra root.")
        let config = (((sent["threadStartConfig"] as? [String: Any])?["skills"] as? [String: Any])?["config"] as? [[String: Any]]) ?? []
        let disabled = Set(config.filter { $0["enabled"] as? Bool == false }.compactMap { $0["path"] as? String }.map(realPath))
        XCTAssertTrue(disabled.contains(realPath(otherWrapper.appendingPathComponent("other-claude/SKILL.md").path)), "Another task's bridged skill is hidden.")
        XCTAssertTrue(disabled.contains(realPath(worktree.appendingPathComponent(".agents/skills/repo-off/SKILL.md").path)), "A disabled native skill is turned off.")
        XCTAssertFalse(disabled.contains { $0.hasPrefix(realPath(ownWrapper.path)) }, "The thread's own bridged skills stay on.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: skillsCodexHome.appendingPathComponent("config.toml").path), "Codex's config.toml is not written.")
        attachScreenshot(named: "Codex turn started with a skill from the Skills page")
        answerQuestionIfAsked()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String).map { $0 != "In Progress" } == true }, timeout: 30),
                      "The first turn should settle before the next message.")

        // A restarted app-server loads the thread again, and must get the bridge again.
        let callsBefore = history()["skillExtraRootsCalls"] as? Int ?? 0
        // Stopping the bridge daemon also ends its app-server; the next send starts both again.
        let daemonPID = try XCTUnwrap((try runCLI(["status"], extraEnvironment: daemonEnvironment)["result"] as? [String: Any])?["processID"] as? Int)
        XCTAssertEqual(kill(pid_t(daemonPID), SIGKILL), 0, "The bridge daemon should stop so its Codex app-server restarts.")
        XCTAssertTrue(waitUntil({ kill(pid_t(daemonPID), 0) != 0 }, timeout: 10), "The stopped daemon should exit.")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 20))
        composer.click()
        composer.typeText("Complete this task again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "Complete this task again." }, timeout: 20))
        let resumed = history()
        XCTAssertEqual((resumed["skillInputs"] as? [[String: String]])?.count, 0, "A turn that names no skill sends none.")
        XCTAssertGreaterThan(resumed["skillExtraRootsCalls"] as? Int ?? 0, callsBefore, "The fresh app-server gets the extra skill roots again.")
        let resumedConfig = (((resumed["threadResumeConfig"] as? [String: Any])?["skills"] as? [String: Any])?["config"] as? [[String: Any]]) ?? []
        XCTAssertEqual(Set(resumedConfig.filter { $0["enabled"] as? Bool == false }.compactMap { $0["path"] as? String }.map(realPath)), disabled,
                       "The resumed thread gets the same per-thread skill config.")
        answerQuestionIfAsked()
    }

    // MARK: - Rules

    private var rulesClaudeConfig: URL { skillsHome.appendingPathComponent(".claude", isDirectory: true) }
    private var rulesManaged: URL { skillsHome.appendingPathComponent("managed/ClaudeCode", isDirectory: true) }

    private func writeRuleFile(_ url: URL, _ text: String) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try text.write(to: url, atomically: true, encoding: .utf8)
    }

    private func ruleCatalog(taskID: String? = nil) throws -> [String: Any] {
        var command = ["rules", "list"]
        if let taskID { command += ["--task", taskID] }
        return try XCTUnwrap(try runCLI(command)["result"] as? [String: Any])
    }

    /// Every rule in the catalog by ID, across repositories, global and managed.
    private func rulesByID(_ catalog: [String: Any]) -> [String: [String: Any]] {
        let sections = (catalog["repositories"] as? [[String: Any]]) ?? []
        let rules = sections.flatMap { ($0["rules"] as? [[String: Any]]) ?? [] }
            + ((catalog["global"] as? [[String: Any]]) ?? []) + ((catalog["managed"] as? [[String: Any]]) ?? [])
        return Dictionary(uniqueKeysWithValues: rules.compactMap { rule in (rule["id"] as? String).map { ($0, rule) } })
    }

    private func openRulesPage(file: StaticString = #filePath, line: UInt = #line) {
        openSkillsPage(file: file, line: line)
        XCTAssertEqual(accessibleLabelOrValue(of: element("skills-title")), "Skills, Rules & MCP", "The page is titled Skills, Rules & MCP.", file: file, line: line)
        selectSkillsTab("Rules", picker: "skills-kind-picker", file: file, line: line)
        XCTAssertTrue(element("rules-page").waitForExistence(timeout: 10), "The Rules picker shows the rules.", file: file, line: line)
        XCTAssertTrue(waitUntil({ !self.element("rules-loading").exists }, timeout: 10), "The rules finish loading.", file: file, line: line)
    }

    /// Opens a rule's actions menu, waiting out a closing panel's animation and
    /// clicking again if the first click landed while it was still on screen.
    private func openRuleActions(_ key: String, file: StaticString = #filePath, line: UInt = #line) {
        let actions = element("rule-actions-\(key)")
        XCTAssertTrue(waitUntil({ actions.exists && actions.isHittable && !self.element("rule-editor-panel").exists && !self.element("new-rule-panel").exists }, timeout: 10),
                      "\(key) should have an actions menu.", file: file, line: line)
        actions.click()
        if !app.menuItems["Reveal in Finder"].waitForExistence(timeout: 3) { actions.click() }
        XCTAssertTrue(app.menuItems["Reveal in Finder"].waitForExistence(timeout: 5), "\(key)'s actions menu opens.", file: file, line: line)
    }

    private func clickRuleMenuItem(rule key: String, item identifier: String, title: String, file: StaticString = #filePath, line: UInt = #line) {
        openRuleActions(key, file: file, line: line)
        let byIdentifier = app.menuItems.matching(identifier: identifier).firstMatch
        let item = byIdentifier.waitForExistence(timeout: 3) ? byIdentifier : app.menuItems[title]
        XCTAssertTrue(item.waitForExistence(timeout: 5), "The actions menu should offer \(title).", file: file, line: line)
        item.click()
    }

    private func claudeTurns(_ historyURL: URL) -> [[String: Any]] {
        guard let data = try? Data(contentsOf: historyURL),
              let history = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return [] }
        return (history["turns"] as? [[String: Any]] ?? []).filter { ($0["userText"] as? String)?.isEmpty == false }
    }

    // case-contract: test_rules_catalog_lists_repo_global_and_managed_rules | The Skills page, titled Skills, Rules & MCP, switches to its Rules list with a Skills | Rules | MCP picker. Rules lists each task repository's instruction files from its worktree (AGENTS.override.md, AGENTS.md, CLAUDE.md, .claude/CLAUDE.md, CLAUDE.local.md, and every .md file under .claude/rules, keyed by the source repository and the file's path), the user's global rules (~/.agents/AGENTS.md, Codex's AGENTS.md, and Claude's CLAUDE.md and rules folder), and the organization's managed CLAUDE.md. Each rule names the agents that follow it in Playhouse sessions and the ones that read it natively: a repository AGENTS.md beside a CLAUDE.md is followed by both but read natively only by Codex, ~/.agents/AGENTS.md is read natively by neither yet shared with both, a CLAUDE.md symlinked to AGENTS.md is one Linked rule read natively by both, AGENTS.override.md is Codex's own and leaves the AGENTS.md beside it to Claude, a .claude/rules file shows its paths globs, the managed CLAUDE.md is Claude's only and read-only, and an @import of a missing file is flagged as a problem. A repository without rules shows an empty state. Reading a rule returns its file exactly, and an unknown rule is not_found.
    func test_rules_catalog_lists_repo_global_and_managed_rules() throws {
        let working = try makeSkillRepository("rules-catalog-repo", skills: [
            "AGENTS.md": "# Repository conventions\nUse tabs.\n",
            "CLAUDE.md": "# Claude notes\n@docs/missing.md\n",
            ".claude/CLAUDE.md": "Claude folder notes.\n",
            "CLAUDE.local.md": "My sandbox URL.\n",
            ".claude/rules/api.md": "---\npaths:\n  - \"src/api/**\"\n---\n\n# API rules\nValidate input.\n",
            ".claude/rules/style/naming.md": "Name things plainly.\n",
        ])
        let linked = try makeSkillRepository("rules-linked-repo", skills: ["AGENTS.md": "# Linked rules\nShared by both.\n"], links: ["CLAUDE.md": "AGENTS.md"])
        let override = try makeSkillRepository("rules-override-repo", skills: ["AGENTS.md": "# Team rules\n", "AGENTS.override.md": "# Codex override\n"])
        let empty = try makeSkillRepository("rules-empty-repo", skills: [:])
        try writeRuleFile(skillsHome.appendingPathComponent(".agents/AGENTS.md"), "# Personal rules\nBe brief.\n")
        try writeRuleFile(skillsCodexHome.appendingPathComponent("AGENTS.md"), "# Codex home rules\n")
        try writeRuleFile(rulesClaudeConfig.appendingPathComponent("CLAUDE.md"), "# Claude home rules\n")
        try writeRuleFile(rulesClaudeConfig.appendingPathComponent("rules/global-style.md"), "Prefer small functions.\n")
        try writeRuleFile(rulesManaged.appendingPathComponent("CLAUDE.md"), "# Company policy\n")
        _ = try installSkillsClaudeFixture("claude-fixture-rules-catalog")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Rules catalog", repositories: [working, linked, override, empty])
        let taskID = try XCTUnwrap(task["id"] as? String)
        openTask(named: "Rules catalog")
        openRulesPage()

        for name in ["rules-catalog-repo", "rules-linked-repo", "rules-override-repo", "rules-empty-repo"] {
            XCTAssertTrue(element("rules-repo-section-\(name)").waitForExistence(timeout: 10), "\(name) has a section.")
        }
        XCTAssertTrue(element("rules-empty-rules-empty-repo").exists, "A repository without rules shows an empty state.")
        for name in ["AGENTS.md", "CLAUDE.md", ".claude/CLAUDE.md", "CLAUDE.local.md", ".claude/rules/api.md", ".claude/rules/style/naming.md"] {
            XCTAssertTrue(element("rule-row-rules-catalog-repo:\(name)").exists, "\(name) is listed.")
        }
        let agents = "rules-catalog-repo:AGENTS.md"
        XCTAssertTrue(element("rule-provider-\(agents)-claude").exists && element("rule-provider-\(agents)-codex").exists,
                      "Both agents follow the repository's AGENTS.md.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-shared-\(agents)")), "Playhouse shares it with Claude.",
                       "Claude Code skips AGENTS.md beside a CLAUDE.md on its own, so Playhouse shares it.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-summary-\(agents)")), "Repository conventions")
        XCTAssertTrue(element("rule-problem-rules-catalog-repo:CLAUDE.md").exists, "An import of a missing file is a problem.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("rule-issue-rules-catalog-repo:CLAUDE.md")).contains("@docs/missing.md"))
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-paths-rules-catalog-repo:.claude/rules/api.md")), "src/api/**",
                       "A .claude/rules file shows its paths globs.")
        XCTAssertTrue(element("rule-linked-rules-linked-repo:AGENTS.md").exists, "A CLAUDE.md symlinked to AGENTS.md is one Linked rule.")
        XCTAssertFalse(element("rule-row-rules-linked-repo:CLAUDE.md").exists, "The symlink is not listed separately.")
        XCTAssertTrue(element("rule-provider-rules-override-repo:AGENTS.override.md-codex").exists)
        XCTAssertFalse(element("rule-provider-rules-override-repo:AGENTS.override.md-claude").exists, "AGENTS.override.md is Codex's own.")
        XCTAssertFalse(element("rule-provider-rules-override-repo:AGENTS.md-codex").exists, "Codex reads the override instead of AGENTS.md.")
        XCTAssertTrue(element("rule-provider-rules-override-repo:AGENTS.md-claude").exists, "The AGENTS.md beside the override is left to Claude.")
        attachScreenshot(named: "Rules tab lists each repository's rule files")

        selectSkillsTab("Global", picker: "rules-tab-picker")
        let shared = "~/.agents/AGENTS.md"
        XCTAssertTrue(element("rule-row-\(shared)").waitForExistence(timeout: 5))
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-shared-\(shared)")), "Playhouse shares it with Claude and Codex.",
                       "Neither CLI reads ~/.agents/AGENTS.md on its own.")
        for name in ["~/.claude/CLAUDE.md", "~/.claude/rules/global-style.md"] {
            XCTAssertTrue(element("rule-row-\(name)").exists, "\(name) is a global rule.")
            XCTAssertTrue(element("rule-provider-\(name)-claude").exists && element("rule-provider-\(name)-codex").exists)
        }
        let codexName = realPath(skillsCodexHome.appendingPathComponent("AGENTS.md").path)
        XCTAssertTrue(element("rule-row-global:codex/AGENTS.md").exists, "Codex's global AGENTS.md is listed (\(codexName)).")
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-shared-global:codex/AGENTS.md")), "Playhouse shares it with Claude.")
        attachScreenshot(named: "Rules Global tab")

        selectSkillsTab("Managed", picker: "rules-tab-picker")
        let managed = realPath(rulesManaged.appendingPathComponent("CLAUDE.md").path)
        let managedRow = element("rule-row-managed:claude/CLAUDE.md")
        XCTAssertTrue(managedRow.waitForExistence(timeout: 5), "The managed CLAUDE.md is listed (\(managed)).")
        XCTAssertFalse(app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'rule-toggle-'")).firstMatch.exists,
                       "The managed CLAUDE.md can't be turned off.")
        XCTAssertFalse(app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'rule-provider-' AND identifier ENDSWITH '-codex'")).firstMatch.exists,
                       "The managed CLAUDE.md is Claude's only.")
        XCTAssertTrue(app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'rule-provider-' AND identifier ENDSWITH '-claude'")).firstMatch.exists,
                      "Claude follows the managed CLAUDE.md.")
        attachScreenshot(named: "Rules Managed tab")

        let catalog = try ruleCatalog(taskID: taskID)
        let byID = rulesByID(catalog)
        XCTAssertEqual(byID["repo:\(working.path)#AGENTS.md"]?["nativeProviders"] as? [String], ["codex"])
        XCTAssertEqual(byID["global:agents/AGENTS.md"]?["nativeProviders"] as? [String], [])
        XCTAssertEqual(byID["global:agents/AGENTS.md"]?["providers"] as? [String], ["claude", "codex"])
        XCTAssertEqual(byID["repo:\(linked.path)#AGENTS.md"]?["availableOutsidePlayhouse"] as? Bool, true)
        XCTAssertEqual(byID["managed:claude/CLAUDE.md"]?["editable"] as? Bool, false)
        let detail = try XCTUnwrap(try runCLI(["rules", "get", "--task", taskID, "--rule", "repo:\(working.path)#AGENTS.md"])["result"] as? [String: Any])
        XCTAssertEqual(detail["content"] as? String, "# Repository conventions\nUse tabs.\n")
        assertCLIError(try runCLI(["rules", "get", "--task", taskID, "--rule", "global:no-such-rule"], expectedStatus: 3), code: "not_found")

        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 5), "Back returns to the conversation.")
    }

    // case-contract: test_rules_create_update_and_delete_on_disk | New Rule writes the shared AGENTS.md (the chosen task worktree's, or ~/.agents/AGENTS.md for a global rule) or, given a name, a topic file in .claude/rules (the worktree's, or Claude's global rules folder) whose paths frontmatter lists the globs given; empty instructions, an invalid name, globs without a name, the managed scope, and an existing file are rejected with nothing written, and the source checkout is left alone. Clicking a rule opens its editor on the whole file with a Markdown preview, and saving writes the file exactly as typed; empty instructions and a rules-folder file whose frontmatter never closes are rejected while keeping the file. The managed CLAUDE.md opens read-only without Save and can be neither edited nor deleted. Deleting a rule removes its file from disk, and every change is visible to a fresh CLI process and on the page.
    func test_rules_create_update_and_delete_on_disk() throws {
        let repository = try makeSkillRepository("rules-manage-repo", skills: [:])
        try writeRuleFile(rulesManaged.appendingPathComponent("CLAUDE.md"), "# Company policy\n")
        _ = try installSkillsClaudeFixture("claude-fixture-rules-manage")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Rules manage", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        let sharedFile = skillsHome.appendingPathComponent(".agents/AGENTS.md")
        openTask(named: "Rules manage")
        openRulesPage()

        element("new-rule-button").click()
        XCTAssertTrue(element("new-rule-panel").waitForExistence(timeout: 5), "New Rule opens its panel.")
        element("new-rule-create").click()
        XCTAssertTrue(element("new-rule-error").waitForExistence(timeout: 5), "Empty instructions are rejected in the panel.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: sharedFile.path), "A rejected rule writes nothing.")
        attachScreenshot(named: "New Rule rejects empty instructions")
        typeIntoField(element("new-rule-body"), text: "Answer briefly.")
        element("new-rule-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-rule-panel").exists }, timeout: 10), "Creating closes the panel.")
        XCTAssertTrue(element("rule-row-~/.agents/AGENTS.md").waitForExistence(timeout: 10), "The new global rule shows on the Global tab.")
        XCTAssertEqual(try String(contentsOf: sharedFile, encoding: .utf8), "Answer briefly.\n", "A global rule is ~/.agents/AGENTS.md.")

        element("new-rule-button").click()
        XCTAssertTrue(element("new-rule-panel").waitForExistence(timeout: 5))
        element("new-rule-scope").click()
        XCTAssertTrue(app.menuItems["rules-manage-repo"].waitForExistence(timeout: 5))
        app.menuItems["rules-manage-repo"].click()
        XCTAssertFalse(element("new-rule-name").exists, "Shared instructions need no name.")
        typeIntoField(element("new-rule-body"), text: "Run the linter.")
        element("new-rule-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-rule-panel").exists }, timeout: 10))
        XCTAssertTrue(element("rule-row-rules-manage-repo:AGENTS.md").waitForExistence(timeout: 10), "The repository's AGENTS.md shows on the Repo tab.")
        XCTAssertEqual(try String(contentsOf: worktree.appendingPathComponent("AGENTS.md"), encoding: .utf8), "Run the linter.\n",
                       "Shared instructions in a repository are its worktree's AGENTS.md.")

        element("new-rule-button").click()
        XCTAssertTrue(element("new-rule-panel").waitForExistence(timeout: 5))
        selectSkillsTab("Topic rule", picker: "new-rule-form")
        let scope = element("new-rule-scope")
        scope.click()
        let repoItem = app.menuItems["rules-manage-repo"]
        XCTAssertTrue(repoItem.waitForExistence(timeout: 5), "New Rule can save into the task's repository.")
        repoItem.click()
        typeIntoField(element("new-rule-name"), text: "api-style")
        typeIntoField(element("new-rule-paths"), text: "src/**/*.ts, lib/**")
        typeIntoField(element("new-rule-body"), text: "Validate every input.")
        attachScreenshot(named: "New Rule panel for a path-scoped topic rule")
        element("new-rule-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-rule-panel").exists }, timeout: 10))
        let topicKey = "rules-manage-repo:.claude/rules/api-style.md"
        XCTAssertTrue(element("rule-row-\(topicKey)").waitForExistence(timeout: 10), "The topic rule shows on the Repo tab.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-paths-\(topicKey)")), "src/**/*.ts, lib/**")
        attachScreenshot(named: "A new path-scoped topic rule shows its globs")
        let topicFile = worktree.appendingPathComponent(".claude/rules/api-style.md")
        XCTAssertEqual(try String(contentsOf: topicFile, encoding: .utf8), "---\npaths:\n  - \"src/**/*.ts\"\n  - \"lib/**\"\n---\n\nValidate every input.\n")
        XCTAssertFalse(FileManager.default.fileExists(atPath: repository.appendingPathComponent(".claude").path), "The source checkout is left alone.")

        element("new-rule-button").click()
        XCTAssertTrue(element("new-rule-panel").waitForExistence(timeout: 5))
        selectSkillsTab("Topic rule", picker: "new-rule-form")
        typeIntoField(element("new-rule-name"), text: "global-topic")
        typeIntoField(element("new-rule-body"), text: "Global topic.")
        element("new-rule-create").click()
        XCTAssertTrue(waitUntil({ !self.element("new-rule-panel").exists }, timeout: 10))
        XCTAssertTrue(element("rule-row-~/.claude/rules/global-topic.md").waitForExistence(timeout: 10), "A global topic rule shows on the Global tab.")
        XCTAssertEqual(try String(contentsOf: rulesClaudeConfig.appendingPathComponent("rules/global-topic.md"), encoding: .utf8), "Global topic.\n",
                       "A named global rule goes in Claude's rules folder.")
        XCTAssertFalse(element("rule-paths-~/.claude/rules/global-topic.md").exists, "A topic rule without globs always loads.")
        selectSkillsTab("Repo", picker: "rules-tab-picker")
        for arguments in [
            ["--scope", "repo", "--root", repository.path, "--name", "Bad Name", "--body", "Text."],
            ["--scope", "repo", "--root", repository.path, "--path", "src/**", "--body", "Scoped without a name."],
            ["--scope", "managed", "--body", "Not allowed."],
        ] {
            assertCLIError(try runCLI(["rules", "create", "--task", taskID] + arguments, expectedStatus: 2), code: "invalid_argument")
        }
        assertCLIError(try runCLI(["rules", "create", "--task", taskID, "--scope", "global", "--body", "Again."], expectedStatus: 1), code: "already_exists")
        XCTAssertEqual(try String(contentsOf: sharedFile, encoding: .utf8), "Answer briefly.\n", "An existing rule file is left alone.")

        selectSkillsTab("Global", picker: "rules-tab-picker")
        element("rule-row-~/.agents/AGENTS.md").click()
        XCTAssertTrue(element("rule-editor-panel").waitForExistence(timeout: 5), "Clicking a rule opens its editor.")
        let editor = element("rule-editor")
        XCTAssertEqual(editor.value as? String, "Answer briefly.\n", "The editor opens the whole file.")
        editor.click()
        editor.typeKey("a", modifierFlags: .command)
        editor.typeText("  \n")
        element("rule-editor-save").click()
        XCTAssertTrue(element("rule-editor-error").waitForExistence(timeout: 5), "Empty instructions are rejected in the editor.")
        XCTAssertEqual(try String(contentsOf: sharedFile, encoding: .utf8), "Answer briefly.\n", "A rejected edit keeps the file.")
        let edited = "# Personal rules\n\n- Answer briefly.\n- Cite files.\n"
        editor.click()
        editor.typeKey("a", modifierFlags: .command)
        editor.typeText(edited)
        selectSkillsTab("Preview", picker: "rule-editor-tab-picker")
        XCTAssertTrue(waitUntil({ self.element("rule-editor-preview").staticTexts["Personal rules"].exists }, timeout: 5), "The preview renders the heading.")
        attachScreenshot(named: "Rule editor previews the edited Markdown")
        element("rule-editor-save").click()
        XCTAssertTrue(waitUntil({ !self.element("rule-editor-panel").exists }, timeout: 10), "Saving closes the editor.")
        XCTAssertEqual(try String(contentsOf: sharedFile, encoding: .utf8), edited, "Saving writes the file exactly as typed.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("rule-summary-~/.agents/AGENTS.md")) == "Personal rules" }, timeout: 10))
        let unclosed = dataDirectory.appendingPathComponent("rule-unclosed.md")
        try "---\npaths:\n  - src/**\nNo closing line.\n".write(to: unclosed, atomically: true, encoding: .utf8)
        assertCLIError(try runCLI(["rules", "update", "--task", taskID, "--rule", "repo:\(repository.path)#.claude/rules/api-style.md", "--content-file", unclosed.path], expectedStatus: 2), code: "invalid_argument")
        XCTAssertTrue(try String(contentsOf: topicFile, encoding: .utf8).contains("Validate every input."), "A rejected edit keeps the file.")

        selectSkillsTab("Managed", picker: "rules-tab-picker")
        let managedRow = element("rule-row-managed:claude/CLAUDE.md")
        XCTAssertTrue(managedRow.waitForExistence(timeout: 5))
        managedRow.click()
        XCTAssertTrue(element("rule-editor-panel").waitForExistence(timeout: 5), "The managed CLAUDE.md opens to read.")
        XCTAssertFalse(element("rule-editor-save").exists, "The managed CLAUDE.md opens read-only, without Save.")
        let managedEditor = element("rule-editor")
        managedEditor.click()
        managedEditor.typeText("Typed into a read-only file.")
        XCTAssertEqual(managedEditor.value as? String, "# Company policy\n", "The managed CLAUDE.md can't be edited.")
        attachScreenshot(named: "The managed CLAUDE.md opens read-only")
        element("rule-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("rule-editor-panel").exists }, timeout: 5))
        let managedKey = "managed:claude/CLAUDE.md"
        openRuleActions(managedKey)
        XCTAssertFalse(app.menuItems["Delete…"].exists || app.menuItems.matching(identifier: "rule-delete-\(managedKey)").firstMatch.exists,
                       "The managed CLAUDE.md offers no Delete.")
        XCTAssertFalse(app.menuItems["Make Available Outside Playhouse…"].exists, "The managed CLAUDE.md offers no link.")
        app.typeKey(.escape, modifierFlags: [])
        assertCLIError(try runCLI(["rules", "delete", "--task", taskID, "--rule", "managed:claude/CLAUDE.md"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try String(contentsOf: rulesManaged.appendingPathComponent("CLAUDE.md"), encoding: .utf8), "# Company policy\n")

        selectSkillsTab("Repo", picker: "rules-tab-picker")
        clickRuleMenuItem(rule: topicKey, item: "rule-delete-\(topicKey)", title: "Delete…")
        clickDialogButton("confirm-delete-rule", title: "Delete")
        XCTAssertTrue(waitUntil({ !self.element("rule-row-\(topicKey)").exists }, timeout: 10), "Deleting removes the rule from the page.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: topicFile.path), "Deleting removes the rule file from disk.")
        XCTAssertTrue(element("rule-row-rules-manage-repo:AGENTS.md").exists, "Other rules stay.")
        let fresh = rulesByID(try ruleCatalog(taskID: taskID))
        XCTAssertNil(fresh["repo:\(repository.path)#.claude/rules/api-style.md"])
        XCTAssertNotNil(fresh["global:agents/AGENTS.md"])
    }

    // case-contract: test_rules_enable_state_and_outside_links_persist | A lone AGENTS.md that both CLIs already read on their own shows Both CLIs rather than Linked, since nothing links to it. Turning a rule off is stored by Playhouse rather than in either provider's settings, survives fresh CLI processes and reopening the page, and can be turned back on; the managed CLAUDE.md can't be turned off. A turned-off rule Codex reads itself, such as the working repository's AGENTS.md, still lists Codex and the page says Codex still reads it, while a rule only Playhouse shares, such as ~/.agents/AGENTS.md, reaches neither agent. Making ~/.agents/AGENTS.md available outside Playhouse writes absolute symlinks as Codex's AGENTS.md and Claude's CLAUDE.md, after which it is one Linked rule read natively by both; a repository CLAUDE.md gets a relative AGENTS.md symlink beside it. An existing file at a link path is left untouched and the request fails with already_exists without writing any link, a rule Codex has no place for can't be linked, and removing the outside link deletes only the symlinks.
    func test_rules_enable_state_and_outside_links_persist() throws {
        let working = try makeSkillRepository("rules-link-repo", skills: ["AGENTS.md": "# Working rules\n"])
        let other = try makeSkillRepository("rules-link-claude-repo", skills: ["CLAUDE.md": "# Claude-only rules\n", ".claude/rules/topic.md": "A topic rule.\n"])
        let sharedFile = skillsHome.appendingPathComponent(".agents/AGENTS.md")
        try writeRuleFile(sharedFile, "# Personal rules\n")
        try writeRuleFile(rulesManaged.appendingPathComponent("CLAUDE.md"), "# Company policy\n")
        let claudeFile = rulesClaudeConfig.appendingPathComponent("CLAUDE.md")
        try writeRuleFile(claudeFile, "Mine, in the way.\n")
        _ = try installSkillsClaudeFixture("claude-fixture-rules-link")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Rules links", repositories: [working, other])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let otherWorktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first { $0["repositoryPath"] as? String == other.path }?["worktreePath"] as? String))
        func rule(_ id: String) throws -> [String: Any]? { rulesByID(try ruleCatalog(taskID: taskID))[id] }
        openTask(named: "Rules links")
        openRulesPage()

        let agents = "rules-link-repo:AGENTS.md"
        let toggle = element("rule-toggle-\(agents)")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertTrue(element("rule-native-\(agents)").exists, "An AGENTS.md with no CLAUDE.md beside it is read by both CLIs on their own.")
        XCTAssertFalse(element("rule-linked-\(agents)").exists, "A file nothing links to is not shown as Linked.")
        XCTAssertTrue(isOn(toggle))
        toggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(toggle) }, timeout: 0.75), "The switch flips as soon as it is clicked.")
        XCTAssertTrue(waitUntil({ ((try? rule("repo:\(working.path)#AGENTS.md"))??["enabled"] as? Bool) == false }, timeout: 10),
                      "Turning a rule off is saved where a fresh CLI process reads it.")
        XCTAssertTrue(element("rule-always-on-\(agents)").waitForExistence(timeout: 5), "The page says Codex still reads the file itself.")
        XCTAssertTrue(element("rule-provider-\(agents)-codex").exists)
        XCTAssertFalse(element("rule-provider-\(agents)-claude").exists, "Turning it off stops Claude following it.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: skillsCodexHome.appendingPathComponent("config.toml").path), "Codex's config is not written.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: rulesClaudeConfig.appendingPathComponent("settings.json").path), "Claude's settings are not written.")
        attachScreenshot(named: "A rule Codex reads itself, turned off")
        element("skills-back-button").click()
        openRulesPage()
        XCTAssertTrue(waitUntil({ self.element("rule-toggle-\(agents)").exists && !self.isOn(self.element("rule-toggle-\(agents)")) }, timeout: 10),
                      "The off state survives reopening the page.")
        element("rule-toggle-\(agents)").click()
        XCTAssertTrue(waitUntil({ ((try? rule("repo:\(working.path)#AGENTS.md"))??["enabled"] as? Bool) == true }, timeout: 10))

        selectSkillsTab("Global", picker: "rules-tab-picker")
        let shared = "~/.agents/AGENTS.md"
        XCTAssertTrue(element("rule-toggle-\(shared)").waitForExistence(timeout: 5))
        element("rule-toggle-\(shared)").click()
        XCTAssertTrue(waitUntil({ !self.element("rule-provider-\(shared)-claude").exists && !self.element("rule-provider-\(shared)-codex").exists }, timeout: 10),
                      "A rule only Playhouse shares reaches neither agent once off.")
        XCTAssertFalse(element("rule-always-on-\(shared)").exists)
        element("rule-toggle-\(shared)").click()
        XCTAssertTrue(waitUntil({ self.element("rule-provider-\(shared)-codex").exists }, timeout: 10))
        assertCLIError(try runCLI(["rules", "disable", "--task", taskID, "--rule", "managed:claude/CLAUDE.md"], expectedStatus: 2), code: "invalid_argument")

        clickRuleMenuItem(rule: shared, item: "rule-link-\(shared)", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-rule", title: "Create Link")
        XCTAssertTrue(element("rules-error").waitForExistence(timeout: 10), "A link onto an existing file shows an error.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("rules-error")).contains("already exists"))
        attachScreenshot(named: "A blocked outside link shows its error")
        XCTAssertEqual(try String(contentsOf: claudeFile, encoding: .utf8), "Mine, in the way.\n", "An existing file is left untouched.")
        let codexLink = skillsCodexHome.appendingPathComponent("AGENTS.md")
        XCTAssertFalse(FileManager.default.fileExists(atPath: codexLink.path), "A blocked link writes no link at all.")
        _ = try runCLI(["rules", "delete", "--task", taskID, "--rule", "global:claude/CLAUDE.md"])

        clickRuleMenuItem(rule: shared, item: "rule-link-\(shared)", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-rule", title: "Create Link")
        XCTAssertTrue(element("rule-linked-\(shared)").waitForExistence(timeout: 10), "A linked rule shows as Linked.")
        for link in [codexLink, claudeFile] {
            let destination = try FileManager.default.destinationOfSymbolicLink(atPath: link.path)
            XCTAssertTrue(destination.hasPrefix("/"), "A global link is absolute.")
            XCTAssertEqual(realPath(destination), realPath(sharedFile.path))
        }
        XCTAssertEqual(app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'rule-row-'")).count, 1,
                       "The linked files are one rule.")
        XCTAssertFalse(element("rule-shared-\(shared)").exists, "Both CLIs read the linked rule natively, so Playhouse no longer shares it.")
        attachScreenshot(named: "~/.agents/AGENTS.md linked for both CLIs")

        selectSkillsTab("Repo", picker: "rules-tab-picker")
        let otherClaude = "rules-link-claude-repo:CLAUDE.md"
        clickRuleMenuItem(rule: otherClaude, item: "rule-link-\(otherClaude)", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-rule", title: "Create Link")
        XCTAssertTrue(element("rule-linked-\(otherClaude)").waitForExistence(timeout: 10))
        XCTAssertEqual(try FileManager.default.destinationOfSymbolicLink(atPath: otherWorktree.appendingPathComponent("AGENTS.md").path), "CLAUDE.md",
                       "A repository link is relative, so it can be committed.")
        attachScreenshot(named: "A repository CLAUDE.md linked as AGENTS.md")
        let topic = "rules-link-claude-repo:.claude/rules/topic.md"
        openRuleActions(topic)
        XCTAssertFalse(app.menuItems["Make Available Outside Playhouse…"].exists || app.menuItems.matching(identifier: "rule-link-\(topic)").firstMatch.exists,
                       "A rule Codex has no place for offers no link.")
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertFalse(FileManager.default.fileExists(atPath: otherWorktree.appendingPathComponent(".agents").path), "No link is written for it.")
        assertCLIError(try runCLI(["rules", "link", "--task", taskID, "--rule", "repo:\(other.path)#.claude/rules/topic.md"], expectedStatus: 2), code: "invalid_argument")

        selectSkillsTab("Global", picker: "rules-tab-picker")
        clickRuleMenuItem(rule: shared, item: "rule-unlink-\(shared)", title: "Remove Outside Link")
        XCTAssertTrue(waitUntil({ !self.element("rule-linked-\(shared)").exists }, timeout: 10))
        XCTAssertNil(try? FileManager.default.destinationOfSymbolicLink(atPath: codexLink.path), "Removing the outside link deletes the symlinks.")
        XCTAssertNil(try? FileManager.default.destinationOfSymbolicLink(atPath: claudeFile.path))
        XCTAssertEqual(try String(contentsOf: sharedFile, encoding: .utf8), "# Personal rules\n", "The rule itself stays.")
        assertCLIError(try runCLI(["rules", "unlink", "--task", taskID, "--rule", "global:agents/AGENTS.md"], expectedStatus: 2), code: "invalid_argument")
    }

    // case-contract: test_rules_fix_with_agent_starts_task_for_problem_rules | A rule with a problem offers Fix with Agent, which creates a task on the source task's provider whose saved prompt explains how both agents read rules and lists each rule with its problem: repository rules by repository-relative path, to be fixed in the new task's own worktree and committed and pushed, and global rules by absolute path, to be fixed in place with their folder opened as a context folder, and fixing only global rules needs no repository. The view switches to the new task's conversation, which sends that prompt once and leaves no unsent draft. A rule with no problem, the managed rule, an unknown rule, and a request without a task are rejected without opening a task.
    func test_rules_fix_with_agent_starts_task_for_problem_rules() throws {
        let repository = try makeSkillRepository("rules-fix-repo", skills: ["AGENTS.md": "# Fine rules\n", "CLAUDE.md": "# Claude notes\n@docs/missing.md\n"])
        let broken = rulesClaudeConfig.appendingPathComponent("rules/broken.md")
        try writeRuleFile(broken, "---\npaths:\n  - src/**\nThe frontmatter never closes.\n")
        try writeRuleFile(rulesManaged.appendingPathComponent("CLAUDE.md"), "# Company policy\n")
        let executable = try installSkillsClaudeFixture("claude-fixture-rules-fix")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        launchApp(defaultParent: fixture.parent.path)
        let source = try createSkillsTask("Rules fix source", repositories: [repository], provider: "claude")
        let sourceID = try XCTUnwrap(source["id"] as? String)
        let sourceWorktree = try XCTUnwrap((source["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String)
        let tasksBefore = try boardTaskRecords().count
        assertCLIError(try runCLI(["rules", "fix", "--task", sourceID, "--rule", "repo:\(repository.path)#AGENTS.md"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["rules", "fix", "--task", sourceID, "--rule", "managed:claude/CLAUDE.md"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["rules", "fix", "--task", sourceID, "--rule", "global:no-such-rule"], expectedStatus: 3), code: "not_found")
        assertCLIError(try runCLI(["rules", "fix", "--rule", "global:claude/rules/broken.md"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try boardTaskRecords().count, tasksBefore, "A rejected fix opens no task.")

        openTask(named: "Rules fix source")
        openRulesPage()
        XCTAssertTrue(element("rule-fix-rules-fix-repo:CLAUDE.md").waitForExistence(timeout: 10), "A rule with a problem offers Fix with Agent.")
        XCTAssertFalse(element("rule-fix-rules-fix-repo:AGENTS.md").exists, "A rule without a problem has nothing to fix.")
        selectSkillsTab("Global", picker: "rules-tab-picker")
        XCTAssertTrue(element("rule-fix-~/.claude/rules/broken.md").waitForExistence(timeout: 5))
        attachScreenshot(named: "A broken global rule offers Fix with Agent")

        element("rule-fix-~/.claude/rules/broken.md").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 10), "Fixing closes the page.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == "Fix rule ~/.claude/rules/broken.md" }, timeout: 15),
                      "The view switches to the fixing task's conversation.")
        let single = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == "Fix rule ~/.claude/rules/broken.md" })
        XCTAssertEqual((single["repositoryWorktrees"] as? [Any])?.count, 0, "Fixing only global rules needs no repository.")
        XCTAssertEqual(((single["contextFolders"] as? [String]) ?? []).map(realPath), [realPath(broken.deletingLastPathComponent().path)],
                       "The global rule's folder is opened to the agent.")
        let singlePrompt = try XCTUnwrap(single["savedPrompt"] as? String)
        XCTAssertTrue(singlePrompt.contains("not tracked by Git"))
        XCTAssertTrue(singlePrompt.contains(broken.path) || singlePrompt.contains(realPath(broken.path)), "A global rule is named by its absolute path.")
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == singlePrompt } }, timeout: 20),
                      "The fixing task sends its prompt as soon as it opens.")

        openTask(named: "Rules fix source")
        openRulesPage()
        XCTAssertTrue(element("rule-fix-rules-fix-repo:CLAUDE.md").waitForExistence(timeout: 10))
        element("rule-fix-rules-fix-repo:CLAUDE.md").click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == "Fix rule CLAUDE.md" }, timeout: 15))
        let fixing = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == "Fix rule CLAUDE.md" })
        let fixingID = try XCTUnwrap(fixing["id"] as? String)
        let prompt = try XCTUnwrap(fixing["savedPrompt"] as? String)
        XCTAssertEqual(fixing["conversationProvider"] as? String, "claude", "The fixing task uses the source task's provider.")
        XCTAssertTrue(prompt.contains("Codex reads AGENTS.md"), "The prompt explains how both agents read rules.")
        XCTAssertTrue(prompt.contains("commit and push"))
        XCTAssertTrue(prompt.contains("`CLAUDE.md` in rules-fix-repo"))
        XCTAssertTrue(prompt.contains("@docs/missing.md"))
        XCTAssertFalse(prompt.contains(sourceWorktree), "Repository paths are relative, so they point into the fixing task's worktree.")
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == prompt } }, timeout: 20), "The conversation sends the fixing prompt.")
        XCTAssertTrue(waitUntil({ (self.element("message-composer").value as? String ?? "").isEmpty }, timeout: 10),
                      "The sent prompt leaves the composer, so it cannot be sent twice.")
        attachScreenshot(named: "The rule-fixing task's conversation")
        XCTAssertEqual(claudeTurns(historyURL).filter { $0["userText"] as? String == prompt }.count, 1, "The fixing prompt is sent exactly once.")
        let started = try XCTUnwrap(try taskRecord(id: fixingID))
        XCTAssertEqual(started["hasUnsentDraft"] as? Bool, false)
        let worktree = try XCTUnwrap((started["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(worktree["repositoryPath"] as? String, repository.path)
        let turn = try XCTUnwrap(claudeTurns(historyURL).first { $0["userText"] as? String == prompt })
        XCTAssertEqual(realPath(turn["cwd"] as? String ?? ""), realPath(worktree["worktreePath"] as? String ?? ""), "The turn runs in the fixing task's worktree.")
        XCTAssertNotEqual(realPath(worktree["worktreePath"] as? String ?? ""), realPath(sourceWorktree))
    }

    // case-contract: test_rules_bridge_claude_launch_follows_shared_rules | A Claude turn follows the rules Claude Code does not read itself: after the task instructions, its appended system prompt carries ~/.agents/AGENTS.md with its @import of another file expanded inline, Codex's global AGENTS.md, and the AGENTS.md of the task's other repository, plus a pointer naming the globs and file of that repository's path-scoped rule; rules Claude reads itself, such as Claude's global CLAUDE.md and the working repository's CLAUDE.md and AGENTS.md, are not repeated. Because the working repository has both AGENTS.md and CLAUDE.md, --settings tells Claude Code to read both, and a rule turned off on the page is excluded for that run with claudeMdExcludes, without writing to the repository or Claude's settings. The resumed second turn carries the same rules, and turning the rule back on drops the exclusion.
    func test_rules_bridge_claude_launch_follows_shared_rules() throws {
        let repository = try makeSkillRepository("rules-claude-repo", skills: [
            "AGENTS.md": "# Repo agents\nRepo AGENTS text.\n",
            "CLAUDE.md": "# Claude repo notes\nClaude repo text.\n",
            "CLAUDE.local.md": "Local text turned off.\n",
        ])
        let extra = try makeSkillRepository("rules-claude-extra", skills: [
            "AGENTS.md": "Extra repo agents text.\n",
            ".claude/rules/extra.md": "---\npaths:\n  - \"lib/**\"\n---\n\nExtra scoped text.\n",
        ])
        try writeRuleFile(skillsHome.appendingPathComponent(".agents/AGENTS.md"), "# Personal rules\nShared global text.\n@~/notes/imported.md\n")
        try writeRuleFile(skillsHome.appendingPathComponent("notes/imported.md"), "Imported text.\n")
        try writeRuleFile(skillsCodexHome.appendingPathComponent("AGENTS.md"), "Codex global text.\n")
        try writeRuleFile(rulesClaudeConfig.appendingPathComponent("CLAUDE.md"), "Claude global text.\n")
        let executable = try installSkillsClaudeFixture("claude-fixture-rules-bridge")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Claude rules", repositories: [repository, extra], provider: "claude")
        let taskID = try XCTUnwrap(task["id"] as? String)
        let records = try XCTUnwrap(task["repositoryWorktrees"] as? [[String: Any]])
        let worktree = URL(fileURLWithPath: try XCTUnwrap(records.first { $0["repositoryPath"] as? String == repository.path }?["worktreePath"] as? String))
        let extraWorktree = URL(fileURLWithPath: try XCTUnwrap(records.first { $0["repositoryPath"] as? String == extra.path }?["worktreePath"] as? String))
        openTask(named: "Claude rules")
        openRulesPage()
        let local = "rules-claude-repo:CLAUDE.local.md"
        XCTAssertTrue(element("rule-toggle-\(local)").waitForExistence(timeout: 10))
        element("rule-toggle-\(local)").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("rule-toggle-\(local)")) }, timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-shared-rules-claude-extra:AGENTS.md")), "Playhouse shares it with Claude and Codex.",
                       "Neither agent loads another task repository's rules on its own.")
        attachScreenshot(named: "Rules a Claude turn will follow, with one turned off")
        element("skills-back-button").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Follow the rules.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == "Follow the rules." } }, timeout: 20))
        let first = try XCTUnwrap(claudeTurns(historyURL).first { $0["userText"] as? String == "Follow the rules." })
        let arguments = try XCTUnwrap(first["arguments"] as? [String])
        let prompt = arguments[try XCTUnwrap(arguments.firstIndex(of: "--append-system-prompt")) + 1]
        for text in ["Shared global text.", "Imported text.", "Codex global text.", "Extra repo agents text.", "`lib/**` in rules-claude-extra:"] {
            XCTAssertTrue(prompt.contains(text), "\(text) reaches Claude through the system prompt.")
        }
        let extraRule = extraWorktree.appendingPathComponent(".claude/rules/extra.md").path
        XCTAssertTrue(prompt.contains(extraRule) || prompt.contains(realPath(extraRule)), "The pointer names the path-scoped rule's file.")
        for text in ["Extra scoped text.", "Claude global text.", "Claude repo text.", "Repo AGENTS text.", "Local text turned off.", "@~/notes/imported.md"] {
            XCTAssertFalse(prompt.contains(text), "\(text) should not be added to Claude's system prompt.")
        }
        XCTAssertGreaterThan(try XCTUnwrap(prompt.range(of: "# Rules Playhouse shares with you")).lowerBound, prompt.startIndex, "Rules follow the task instructions.")
        let settings = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(arguments[try XCTUnwrap(arguments.firstIndex(of: "--settings")) + 1].utf8)) as? [String: Any])
        XCTAssertEqual(Set(((settings["claudeMdExcludes"] as? [String]) ?? []).map(realPath)), [realPath(worktree.appendingPathComponent("CLAUDE.local.md").path)],
                       "The turned-off rule is excluded for this run.")
        let plugin = ((settings["pluginConfigs"] as? [String: Any])?["cc-plugin-agents-md@builtin"] as? [String: Any])?["options"] as? [String: String]
        XCTAssertEqual(plugin, ["instructionFiles": "claude-md-and-agents-md"], "Claude Code reads AGENTS.md alongside CLAUDE.md.")
        XCTAssertEqual(try runGitOutput(worktree, "status", "--porcelain"), "", "The worktree is not written to.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: rulesClaudeConfig.appendingPathComponent("settings.json").path), "Claude's settings are not written.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String).map { $0 != "In Progress" } == true }, timeout: 30),
                      "The first turn should settle before the next message.")

        openRulesPage()
        element("rule-toggle-\(local)").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("rule-toggle-\(local)")) }, timeout: 10))
        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Follow them again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == "Follow them again." } }, timeout: 20))
        let second = try XCTUnwrap(claudeTurns(historyURL).last { $0["userText"] as? String == "Follow them again." })
        XCTAssertEqual(second["resumed"] as? Bool, true, "The second turn resumes the Claude session.")
        let resumed = try XCTUnwrap(second["arguments"] as? [String])
        XCTAssertTrue(resumed[try XCTUnwrap(resumed.firstIndex(of: "--append-system-prompt")) + 1].contains("Shared global text."), "A resumed turn carries the same rules.")
        let resumedSettings = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(resumed[try XCTUnwrap(resumed.firstIndex(of: "--settings")) + 1].utf8)) as? [String: Any])
        XCTAssertNil(resumedSettings["claudeMdExcludes"], "Turning the rule back on drops the exclusion.")
    }

    // case-contract: test_rules_bridge_codex_thread_follows_claude_rules | A Codex turn follows the rules Codex does not read itself: after the task instructions, the thread starts with developer instructions carrying ~/.agents/AGENTS.md, Claude's global CLAUDE.md, and the working repository's CLAUDE.md and always-on .claude/rules files, with CLAUDE.md's @AGENTS.md import left out because Codex already reads that file, and each path-scoped rule as a pointer naming its globs and file rather than its text. The working repository's AGENTS.md and Codex's global AGENTS.md are not repeated, a rule turned off on the page is left out, and Codex's config.toml is not written. A thread resumed on a fresh app-server gets the same rules.
    func test_rules_bridge_codex_thread_follows_claude_rules() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let historyURL = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".history")
        let repository = try makeSkillRepository("rules-codex-repo", skills: [
            "AGENTS.md": "Repo AGENTS text for Codex.\n",
            "CLAUDE.md": "# Claude repo notes\n@AGENTS.md\nClaude repo text for Codex.\n",
            ".claude/rules/testing.md": "Always run tests.\n",
            ".claude/rules/api.md": "---\npaths:\n  - \"src/api/**\"\n---\n\nAPI rule text.\n",
            ".claude/rules/off.md": "Turned off text.\n",
        ])
        try writeRuleFile(skillsHome.appendingPathComponent(".agents/AGENTS.md"), "Shared global text for Codex.\n")
        try writeRuleFile(rulesClaudeConfig.appendingPathComponent("CLAUDE.md"), "Claude global text for Codex.\n")
        try writeRuleFile(skillsCodexHome.appendingPathComponent("AGENTS.md"), "Codex global native text.\n")
        _ = try installSkillsClaudeFixture("claude-fixture-rules-codex")
        // Its own daemon, so restarting it below leaves the UI runner's shared one alone.
        let daemonEnvironment = ["PLAYHOUSE_BRIDGE_SERVICE_NAME": "\(serviceName!).rules-codex-\(UUID().uuidString.prefix(8))"]
        launchApp(defaultParent: fixture.parent.path, environmentOverrides: daemonEnvironment)
        let task = try createSkillsTask("Codex rules", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        func history() -> [String: Any] {
            guard let data = try? Data(contentsOf: historyURL) else { return [:] }
            return (try? JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
        }
        func answerQuestionIfAsked() {
            guard element("ai-question-form-title").waitForExistence(timeout: 10) else { return }
            selectQuestionOption("Blue")
            typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
            element("submit-ai-answers-button").click()
        }

        openTask(named: "Codex rules")
        openRulesPage()
        let off = "rules-codex-repo:.claude/rules/off.md"
        XCTAssertTrue(element("rule-toggle-\(off)").waitForExistence(timeout: 10))
        element("rule-toggle-\(off)").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("rule-toggle-\(off)")) }, timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("rule-shared-rules-codex-repo:CLAUDE.md")), "Playhouse shares it with Codex.",
                       "Codex doesn't read CLAUDE.md on its own, so Playhouse shares it.")
        attachScreenshot(named: "Rules a Codex turn will follow, with one turned off")
        element("skills-back-button").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Follow the rules.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "Follow the rules." }, timeout: 20))
        let instructions = try XCTUnwrap(history()["threadStartDeveloperInstructions"] as? String)
        for text in ["Shared global text for Codex.", "Claude global text for Codex.", "Claude repo text for Codex.", "Always run tests.", "`src/api/**` in rules-codex-repo:"] {
            XCTAssertTrue(instructions.contains(text), "\(text) reaches Codex through the thread's developer instructions.")
        }
        let apiRule = worktree.appendingPathComponent(".claude/rules/api.md").path
        XCTAssertTrue(instructions.contains(apiRule) || instructions.contains(realPath(apiRule)), "The pointer names the path-scoped rule's file.")
        for text in ["API rule text.", "Repo AGENTS text for Codex.", "Codex global native text.", "Turned off text.", "@AGENTS.md"] {
            XCTAssertFalse(instructions.contains(text), "\(text) should not be added to Codex's instructions.")
        }
        let rulesStart = try XCTUnwrap(instructions.range(of: "# Rules Playhouse shares with you"))
        XCTAssertGreaterThan(rulesStart.lowerBound, instructions.startIndex, "Rules follow the task instructions.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: skillsCodexHome.appendingPathComponent("config.toml").path), "Codex's config.toml is not written.")
        answerQuestionIfAsked()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String).map { $0 != "In Progress" } == true }, timeout: 30),
                      "The first turn should settle before the next message.")

        // Stopping the bridge daemon also ends its app-server; the next send resumes the thread on a fresh one.
        let daemonPID = try XCTUnwrap((try runCLI(["status"], extraEnvironment: daemonEnvironment)["result"] as? [String: Any])?["processID"] as? Int)
        XCTAssertEqual(kill(pid_t(daemonPID), SIGKILL), 0, "The bridge daemon should stop so its Codex app-server restarts.")
        XCTAssertTrue(waitUntil({ kill(pid_t(daemonPID), 0) != 0 }, timeout: 10), "The stopped daemon should exit.")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 20))
        composer.click()
        composer.typeText("Follow them again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "Follow them again." }, timeout: 20))
        let resumedAll = try XCTUnwrap(history()["threadResumeDeveloperInstructions"] as? [Any])
        let resumed = try XCTUnwrap(resumedAll.last as? String)
        let resumedStart = try XCTUnwrap(resumed.range(of: "# Rules Playhouse shares with you"))
        XCTAssertEqual(String(resumed[resumedStart.lowerBound...]), String(instructions[rulesStart.lowerBound...]), "The resumed thread gets the same rules.")
        answerQuestionIfAsked()
    }

    // MARK: - MCP servers

    private var mcpClaudeState: URL { skillsHome.appendingPathComponent(".claude.json") }
    private var mcpCodexConfig: URL { skillsCodexHome.appendingPathComponent("config.toml") }
    private var mcpManaged: URL { rulesManaged.appendingPathComponent("managed-mcp.json") }

    private func writeMcpJSON(_ url: URL, _ value: Any) throws {
        let data = try JSONSerialization.data(withJSONObject: value, options: [.prettyPrinted, .sortedKeys])
        try writeRuleFile(url, String(decoding: data, as: UTF8.self) + "\n")
    }

    private func readMcpJSON(_ url: URL) throws -> [String: Any] {
        try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    private func mcpCatalog(taskID: String? = nil) throws -> [String: Any] {
        var command = ["mcp", "list"]
        if let taskID { command += ["--task", taskID] }
        return try XCTUnwrap(try runCLI(command)["result"] as? [String: Any])
    }

    /// Every server in the catalog by ID, across repositories, global and managed.
    private func mcpServersByID(_ catalog: [String: Any]) -> [String: [String: Any]] {
        let sections = (catalog["repositories"] as? [[String: Any]]) ?? []
        let servers = sections.flatMap { ($0["servers"] as? [[String: Any]]) ?? [] }
            + ((catalog["global"] as? [[String: Any]]) ?? []) + ((catalog["managed"] as? [[String: Any]]) ?? [])
        return Dictionary(uniqueKeysWithValues: servers.compactMap { server in (server["id"] as? String).map { ($0, server) } })
    }

    private func openMcpPage(file: StaticString = #filePath, line: UInt = #line) {
        openSkillsPage(file: file, line: line)
        XCTAssertEqual(accessibleLabelOrValue(of: element("skills-title")), "Skills, Rules & MCP", "The page is titled Skills, Rules & MCP.", file: file, line: line)
        selectSkillsTab("MCP", picker: "skills-kind-picker", file: file, line: line)
        XCTAssertTrue(element("mcp-page").waitForExistence(timeout: 10), "The MCP picker shows the servers.", file: file, line: line)
        XCTAssertTrue(waitUntil({ !self.element("mcp-loading").exists }, timeout: 10), "The servers finish loading.", file: file, line: line)
    }

    /// Opens a server's actions menu, waiting out a closing panel's animation.
    private func clickMcpMenuItem(server key: String, item identifier: String, title: String, file: StaticString = #filePath, line: UInt = #line) {
        let actions = element("mcp-actions-\(key)")
        XCTAssertTrue(waitUntil({ actions.exists && actions.isHittable && !self.element("mcp-editor-panel").exists }, timeout: 10),
                      "\(key) should have an actions menu.", file: file, line: line)
        actions.click()
        let byIdentifier = app.menuItems.matching(identifier: identifier).firstMatch
        if !byIdentifier.waitForExistence(timeout: 3), !app.menuItems[title].exists { actions.click() }
        let item = byIdentifier.waitForExistence(timeout: 3) ? byIdentifier : app.menuItems[title]
        XCTAssertTrue(item.waitForExistence(timeout: 5), "The actions menu should offer \(title).", file: file, line: line)
        item.click()
    }

    private func replaceText(in field: XCUIElement, with text: String) {
        field.click()
        field.typeKey("a", modifierFlags: .command)
        field.typeKey(.delete, modifierFlags: [])
        if !text.isEmpty { field.typeText(text) }
    }

    // case-contract: test_mcp_catalog_lists_repo_global_and_managed_servers | The Skills page, titled Skills, Rules & MCP, switches to its MCP list with a Skills | Rules | MCP picker. MCP lists each task repository's servers from its worktree's .mcp.json and .codex/config.toml (keyed by the source repository and the server's name), the user's global servers from Claude Code's ~/.claude.json and Codex's config.toml, and the organization's managed-mcp.json. Each server shows its command or URL and only the names of its environment variables and headers, never their values, and names the agents that start it on their own and the ones Playhouse passes it to: a .mcp.json server is Claude's own and passed to Codex, a server defined the same way in both global files is one entry both CLIs start, a server only one CLI defines is passed to the other, an SSE server or one with a working folder reaches only the agent that can run it with the reason shown, a server Codex's config.toml turns off reaches neither, a server written inline in config.toml is listed but not editable, two global definitions that differ are flagged as a conflict, and the managed server is Claude's only and read-only. A repository without servers shows an empty state and an unreadable configuration file is reported. Reading a server returns its full definition, and an unknown server is not_found.
    func test_mcp_catalog_lists_repo_global_and_managed_servers() throws {
        let working = try makeSkillRepository("mcp-catalog-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"repo-docs": {"type": "stdio", "command": "node", "args": ["docs.js"], "env": {"DOCS_TOKEN": "${DOCS_TOKEN}", "DOCS_MODE": "secret-mode-value"}}, "repo-sse": {"type": "sse", "url": "https://sse.example.com/mcp"}}}"#,
            ".codex/config.toml": "[mcp_servers.repo-codex]\ncommand = \"python3\"\nargs = [\"serve.py\"]\n",
        ])
        let other = try makeSkillRepository("mcp-other-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"other-api": {"type": "http", "url": "https://api.example.com/mcp", "headers": {"Authorization": "Bearer ${API_TOKEN}"}}}}"#,
            ".codex/config.toml": "[mcp_servers.broken\ncommand = \n",
        ])
        let empty = try makeSkillRepository("mcp-empty-repo", skills: [:])
        try writeMcpJSON(mcpClaudeState, ["numStartups": 5, "mcpServers": [
            "shared": ["type": "stdio", "command": "npx", "args": ["-y", "shared-server"], "env": [:]],
            "claude-only": ["type": "http", "url": "https://claude.example.com/mcp", "headers": ["X-Team": "core-secret-team"]],
            "clash": ["type": "stdio", "command": "clash-a", "args": [], "env": [:]],
        ]])
        try writeRuleFile(mcpCodexConfig, [
            "model = \"gpt-6-luna\"", "",
            "[mcp_servers]", "inline-tool = { command = \"inline-tool\" }", "",
            "[mcp_servers.shared]", "command = \"npx\"", "args = [\"-y\", \"shared-server\"]", "",
            "[mcp_servers.codex-only]", "command = \"uvx\"", "args = [\"codex-tool\"]", "env_vars = [\"CODEX_TOOL_KEY\"]", "",
            "[mcp_servers.clash]", "command = \"clash-b\"", "",
            "[mcp_servers.folder-tool]", "command = \"./tool\"", "cwd = \".\"", "",
            "[mcp_servers.off-tool]", "command = \"off-tool\"", "enabled = false", "",
        ].joined(separator: "\n"))
        try writeMcpJSON(mcpManaged, ["mcpServers": ["company": ["type": "http", "url": "https://mcp.company.example/mcp"]]])
        _ = try installSkillsClaudeFixture("claude-fixture-mcp-catalog")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("MCP catalog", repositories: [working, other, empty])
        let taskID = try XCTUnwrap(task["id"] as? String)
        openTask(named: "MCP catalog")
        openMcpPage()

        for name in ["mcp-catalog-repo", "mcp-other-repo", "mcp-empty-repo"] {
            XCTAssertTrue(element("mcp-repo-section-\(name)").waitForExistence(timeout: 10), "\(name) has a section.")
        }
        XCTAssertTrue(element("mcp-empty-mcp-empty-repo").exists, "A repository without servers shows an empty state.")
        XCTAssertTrue(element("mcp-file-problem").exists, "An unreadable config file is reported.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-file-problem")).contains(".codex/config.toml"))
        let docs = "mcp-catalog-repo:repo-docs"
        XCTAssertTrue(element("mcp-row-\(docs)").exists)
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-summary-\(docs)")), "node docs.js", "A server shows its command.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-env-\(docs)")), "Environment: DOCS_MODE, DOCS_TOKEN",
                       "Only the names of its environment variables are shown.")
        XCTAssertFalse(app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'secret-mode-value'")).firstMatch.exists, "Values are never shown.")
        XCTAssertTrue(element("mcp-provider-\(docs)-claude").exists && element("mcp-provider-\(docs)-codex").exists)
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-\(docs)")), "Playhouse passes it to Codex.", ".mcp.json is Claude's own.")
        let sse = "mcp-catalog-repo:repo-sse"
        XCTAssertTrue(element("mcp-provider-\(sse)-claude").exists)
        XCTAssertFalse(element("mcp-provider-\(sse)-codex").exists, "Codex can't run an SSE server.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-limitation-\(sse)")).contains("SSE"))
        XCTAssertTrue(element("mcp-row-mcp-catalog-repo:repo-codex").exists, "The worktree's .codex/config.toml servers are listed.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-mcp-other-repo:other-api")), "Playhouse passes it to Claude and Codex.",
                       "Neither agent reads another task repository's servers on its own.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-env-mcp-other-repo:other-api")), "Headers: Authorization")
        attachScreenshot(named: "MCP Repo tab lists each repository's servers")

        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-row-shared").waitForExistence(timeout: 5))
        XCTAssertTrue(element("mcp-native-shared").exists, "A server both global files define the same way is one entry both CLIs start.")
        XCTAssertFalse(element("mcp-shared-shared").exists)
        XCTAssertTrue(element("mcp-conflict-clash").exists, "Two global definitions that differ are a conflict.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-issue-clash")).contains("differently"))
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-claude-only")), "Playhouse passes it to Codex.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-codex-only")), "Playhouse passes it to Claude.")
        XCTAssertFalse(element("mcp-provider-folder-tool-claude").exists, "Claude Code can't run a server with a working folder.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-limitation-folder-tool")).contains("working folder"))
        XCTAssertFalse(element("mcp-provider-off-tool-claude").exists || element("mcp-provider-off-tool-codex").exists,
                       "A server Codex's config turns off reaches neither agent.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-limitation-off-tool")).contains("enabled = false"))
        XCTAssertTrue(element("mcp-row-inline-tool").exists, "An inline config.toml server is listed.")
        attachScreenshot(named: "MCP Global tab")
        // The inline server is last on a long list, below the visible part of the page.
        XCTAssertTrue(scrollFullyIntoView(element("mcp-row-inline-tool"), in: element("mcp-list")), "The inline server scrolls into view.")
        element("mcp-row-inline-tool").click()
        XCTAssertTrue(element("mcp-editor-panel").waitForExistence(timeout: 5), "An inline server opens to read.")
        XCTAssertFalse(element("mcp-editor-save").exists, "An inline config.toml server opens without Save.")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-editor-read-only")).contains("inline"), "The editor says why it is read-only.")
        attachScreenshot(named: "An inline config.toml server opens read-only")
        element("mcp-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-editor-panel").exists }, timeout: 5))
        let inlineActions = element("mcp-actions-inline-tool")
        XCTAssertTrue(waitUntil({ inlineActions.isHittable }, timeout: 5))
        inlineActions.click()
        XCTAssertTrue(app.menuItems["View…"].waitForExistence(timeout: 5), "An inline server offers View rather than Edit.")
        XCTAssertFalse(app.menuItems["Delete…"].exists || app.menuItems["Make Available Outside Playhouse…"].exists,
                       "An inline server offers no Delete or link.")
        app.typeKey(.escape, modifierFlags: [])

        selectSkillsTab("Managed", picker: "mcp-tab-picker")
        let managed = "managed:company"
        XCTAssertTrue(element("mcp-row-\(managed)").waitForExistence(timeout: 5), "The managed server is listed.")
        XCTAssertTrue(element("mcp-provider-\(managed)-claude").exists)
        XCTAssertFalse(element("mcp-provider-\(managed)-codex").exists, "The managed server is Claude's only.")
        XCTAssertFalse(element("mcp-toggle-\(managed)").exists, "The managed server can't be turned off.")
        attachScreenshot(named: "MCP Managed tab")

        let byID = mcpServersByID(try mcpCatalog(taskID: taskID))
        XCTAssertEqual(byID["repo:\(working.path)#repo-docs"]?["nativeProviders"] as? [String], ["claude"])
        XCTAssertEqual(byID["global:shared"]?["availableOutsidePlayhouse"] as? Bool, true)
        XCTAssertEqual(((byID["global:inline-tool"]?["locations"] as? [[String: Any]])?.first)?["editable"] as? Bool, false,
                       "An inline config.toml server is not editable.")
        XCTAssertEqual(byID["managed:company"]?["editable"] as? Bool, false)
        let detail = try XCTUnwrap(try runCLI(["mcp", "get", "--task", taskID, "--server", "global:claude-only"])["result"] as? [String: Any])
        XCTAssertEqual((detail["config"] as? [String: Any])?["headers"] as? [String: String], ["X-Team": "core-secret-team"], "Reading a server returns its full definition.")
        assertCLIError(try runCLI(["mcp", "get", "--task", taskID, "--server", "global:no-such-server"], expectedStatus: 3), code: "not_found")

        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 5), "Back returns to the conversation.")
    }

    // case-contract: test_mcp_create_update_and_delete_in_both_configs | New Server writes a global server straight into both Claude Code's ~/.claude.json mcpServers and Codex's config.toml [mcp_servers] table, with ${NAME} environment references written as Codex env_vars and every other setting, comment and server in both files kept; a repository server goes into the chosen task worktree's .mcp.json and the source checkout is left alone. An invalid name, a missing command, an SSE server, a URL that is not http, an environment reference Codex can't pass through, the managed scope, and an existing name are rejected with nothing written. Clicking a server opens its editor, and saving rewrites it in every file that defines it while keeping each provider's own keys, such as Codex's startup_timeout_sec and Claude's oauth; an invalid edit and an edit to a server written inline in config.toml are rejected while keeping the files. Deleting a server removes it from every file that defines it, and every change is visible to a fresh CLI process and on the page.
    func test_mcp_create_update_and_delete_in_both_configs() throws {
        let repository = try makeSkillRepository("mcp-manage-repo", skills: [:])
        try writeMcpJSON(mcpClaudeState, ["numStartups": 7, "mcpServers": [
            "legacy": ["type": "http", "url": "https://legacy.example.com/mcp", "oauth": ["clientId": "abc"]],
        ]])
        try writeRuleFile(mcpCodexConfig, [
            "# my settings", "model = \"gpt-6-luna\"", "",
            "[mcp_servers]", "inline-tool = { command = \"inline-tool\" }", "",
            "[mcp_servers.legacy]", "url = \"https://legacy.example.com/mcp\"", "startup_timeout_sec = 45", "",
            "[profiles.fast]", "model = \"gpt-6-mini\"", "",
        ].joined(separator: "\n"))
        try writeMcpJSON(mcpManaged, ["mcpServers": ["company": ["type": "http", "url": "https://mcp.company.example/mcp"]]])
        _ = try installSkillsClaudeFixture("claude-fixture-mcp-manage")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("MCP manage", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        openTask(named: "MCP manage")
        openMcpPage()

        element("new-mcp-server-button").click()
        XCTAssertTrue(element("mcp-editor-panel").waitForExistence(timeout: 5), "New Server opens its panel.")
        typeIntoField(element("mcp-editor-name"), text: "bad name")
        typeIntoField(element("mcp-editor-command"), text: "npx")
        element("mcp-editor-save").click()
        XCTAssertTrue(element("mcp-editor-error").waitForExistence(timeout: 5), "An invalid name is rejected in the panel.")
        XCTAssertNil((try readMcpJSON(mcpClaudeState)["mcpServers"] as? [String: Any])?["bad name"], "A rejected server writes nothing.")
        attachScreenshot(named: "New Server rejects an invalid name")
        replaceText(in: element("mcp-editor-name"), with: "notes")
        replaceText(in: element("mcp-editor-command"), with: "")
        element("mcp-editor-save").click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("mcp-editor-error")).contains("command") }, timeout: 5),
                      "A missing command is rejected in the panel.")
        XCTAssertNil((try readMcpJSON(mcpClaudeState)["mcpServers"] as? [String: Any])?["notes"], "A rejected server writes nothing.")
        replaceText(in: element("mcp-editor-command"), with: "npx")
        typeIntoField(element("mcp-editor-args"), text: "-y\nnotes-server")
        typeIntoField(element("mcp-editor-env"), text: "NOTES_TOKEN=${NOTES_TOKEN}\nMODE=fast")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-editor-target")).contains("config.toml"), "A global server is saved for both CLIs.")
        attachScreenshot(named: "New Server panel for a global local command")
        element("mcp-editor-save").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-editor-panel").exists }, timeout: 10), "Creating closes the panel.")
        XCTAssertTrue(element("mcp-row-notes").waitForExistence(timeout: 10), "The new global server shows on the Global tab.")
        XCTAssertTrue(element("mcp-native-notes").exists, "A new global server is in both CLIs' configuration.")
        let state = try readMcpJSON(mcpClaudeState)
        let notes = try XCTUnwrap((state["mcpServers"] as? [String: Any])?["notes"] as? [String: Any])
        XCTAssertEqual(notes["command"] as? String, "npx")
        XCTAssertEqual(notes["args"] as? [String], ["-y", "notes-server"])
        XCTAssertEqual(notes["env"] as? [String: String], ["NOTES_TOKEN": "${NOTES_TOKEN}", "MODE": "fast"])
        XCTAssertEqual(state["numStartups"] as? Int, 7, "Claude Code's other state is kept.")
        let codexText = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        for line in ["# my settings", "[mcp_servers.notes]", "command = \"npx\"", "args = [\"-y\", \"notes-server\"]", "env_vars = [\"NOTES_TOKEN\"]",
                     "[mcp_servers.notes.env]", "MODE = \"fast\"", "[profiles.fast]"] {
            XCTAssertTrue(codexText.contains(line), "Codex's config.toml has \(line).")
        }
        attachScreenshot(named: "A new global server both CLIs start")

        element("new-mcp-server-button").click()
        XCTAssertTrue(element("mcp-editor-panel").waitForExistence(timeout: 5))
        element("mcp-editor-scope").click()
        XCTAssertTrue(app.menuItems["mcp-manage-repo"].waitForExistence(timeout: 5), "New Server can save into the task's repository.")
        app.menuItems["mcp-manage-repo"].click()
        selectSkillsTab("Remote HTTP", picker: "mcp-editor-kind")
        typeIntoField(element("mcp-editor-name"), text: "repo-search")
        typeIntoField(element("mcp-editor-url"), text: "https://search.example.com/mcp")
        XCTAssertTrue(accessibleLabelOrValue(of: element("mcp-editor-target")).contains(".mcp.json"))
        element("mcp-editor-save").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-editor-panel").exists }, timeout: 10))
        XCTAssertTrue(element("mcp-row-mcp-manage-repo:repo-search").waitForExistence(timeout: 10), "The repository server shows on the Repo tab.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-mcp-manage-repo:repo-search")), "Playhouse passes it to Codex.")
        let projectJSON = try readMcpJSON(worktree.appendingPathComponent(".mcp.json"))
        XCTAssertEqual(((projectJSON["mcpServers"] as? [String: Any])?["repo-search"] as? [String: Any])?["url"] as? String, "https://search.example.com/mcp")
        XCTAssertFalse(FileManager.default.fileExists(atPath: repository.appendingPathComponent(".mcp.json").path), "The source checkout is left alone.")

        let beforeRejected = (try String(contentsOf: mcpClaudeState, encoding: .utf8), try String(contentsOf: mcpCodexConfig, encoding: .utf8))
        for arguments in [
            ["--scope", "global", "--name", "no-command", "--command", ""],
            ["--scope", "global", "--name", "events", "--config-json", #"{"transport": "sse", "url": "https://sse.example.com"}"#],
            ["--scope", "global", "--name", "ftp-server", "--url", "ftp://files.example.com"],
            ["--scope", "global", "--name", "renamed-env", "--command", "npx", "--env", "TOKEN=${OTHER_TOKEN}"],
            ["--scope", "managed", "--name", "company-two", "--command", "npx"],
        ] {
            assertCLIError(try runCLI(["mcp", "create", "--task", taskID] + arguments, expectedStatus: 2), code: "invalid_argument")
        }
        assertCLIError(try runCLI(["mcp", "create", "--task", taskID, "--scope", "global", "--name", "notes", "--command", "npx"], expectedStatus: 1), code: "already_exists")
        XCTAssertEqual(try String(contentsOf: mcpClaudeState, encoding: .utf8), beforeRejected.0, "A rejected server writes nothing to Claude Code's file.")
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeRejected.1, "A rejected server writes nothing to Codex's file.")

        selectSkillsTab("Global", picker: "mcp-tab-picker")
        element("mcp-row-legacy").click()
        XCTAssertTrue(element("mcp-editor-panel").waitForExistence(timeout: 5), "Clicking a server opens its editor.")
        let url = element("mcp-editor-url")
        XCTAssertEqual(url.value as? String, "https://legacy.example.com/mcp", "The editor opens the server's definition.")
        replaceText(in: url, with: "ftp://legacy.example.com")
        element("mcp-editor-save").click()
        XCTAssertTrue(element("mcp-editor-error").waitForExistence(timeout: 5), "An invalid edit is rejected in the editor.")
        XCTAssertTrue(try String(contentsOf: mcpCodexConfig, encoding: .utf8).contains("url = \"https://legacy.example.com/mcp\""), "A rejected edit keeps the files.")
        replaceText(in: url, with: "https://legacy.example.com/v2")
        attachScreenshot(named: "Editing a global server")
        element("mcp-editor-save").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-editor-panel").exists }, timeout: 10), "Saving closes the editor.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("mcp-summary-legacy")) == "https://legacy.example.com/v2" }, timeout: 10))
        let legacy = try XCTUnwrap((try readMcpJSON(mcpClaudeState)["mcpServers"] as? [String: Any])?["legacy"] as? [String: Any])
        XCTAssertEqual(legacy["url"] as? String, "https://legacy.example.com/v2")
        XCTAssertEqual(legacy["oauth"] as? [String: String], ["clientId": "abc"], "Claude's own keys are kept.")
        let editedCodex = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        XCTAssertTrue(editedCodex.contains("url = \"https://legacy.example.com/v2\""), "An edit reaches Codex's config.toml.")
        XCTAssertTrue(editedCodex.contains("startup_timeout_sec = 45"), "Codex's own keys are kept.")
        let beforeInline = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        let inline = try runCLI(["mcp", "update", "--task", taskID, "--server", "global:inline-tool", "--command", "inline-tool-2"], expectedStatus: 2)
        assertCLIError(inline, code: "invalid_argument")
        XCTAssertTrue(((inline["error"] as? [String: Any])?["message"] as? String ?? "").contains("inline"))
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeInline, "An edit to an inline server keeps the file.")

        selectSkillsTab("Managed", picker: "mcp-tab-picker")
        element("mcp-row-managed:company").click()
        XCTAssertTrue(element("mcp-editor-panel").waitForExistence(timeout: 5), "The managed server opens to read.")
        XCTAssertFalse(element("mcp-editor-save").exists, "The managed server opens read-only, without Save.")
        element("mcp-editor-cancel").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-editor-panel").exists }, timeout: 5))

        selectSkillsTab("Global", picker: "mcp-tab-picker")
        clickMcpMenuItem(server: "notes", item: "mcp-delete-notes", title: "Delete…")
        clickDialogButton("confirm-delete-mcp", title: "Delete")
        XCTAssertTrue(waitUntil({ !self.element("mcp-row-notes").exists }, timeout: 10), "Deleting removes the server from the page.")
        XCTAssertNil((try readMcpJSON(mcpClaudeState)["mcpServers"] as? [String: Any])?["notes"], "Deleting removes the server from Claude Code's file.")
        let afterDelete = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        XCTAssertFalse(afterDelete.contains("[mcp_servers.notes"), "Deleting removes the server from Codex's file.")
        XCTAssertTrue(afterDelete.contains("# my settings"))
        attachScreenshot(named: "A deleted server is gone from both files")
        let fresh = mcpServersByID(try mcpCatalog(taskID: taskID))
        XCTAssertNil(fresh["global:notes"])
        XCTAssertNotNil(fresh["repo:\(repository.path)#repo-search"])
    }

    // case-contract: test_mcp_enable_state_and_link_persist | Turning a server off is stored by Playhouse rather than in either provider's configuration, survives fresh CLI processes and reopening the page, and can be turned back on; the managed server can't be turned off. A turned-off server in Claude Code's own configuration still lists Claude and the page says Claude still starts it, so turning it off applies to Codex only, while a turned-off server only Codex defines reaches neither agent. Make Available Outside Playhouse writes a Claude-only global server into Codex's config.toml, a Codex-only one into Claude Code's ~/.claude.json, and a repository .mcp.json server into the worktree's .codex/config.toml, after which each is one entry both CLIs start; a conflicting server can't be linked and nothing is written.
    func test_mcp_enable_state_and_link_persist() throws {
        let repository = try makeSkillRepository("mcp-link-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"repo-tool": {"type": "stdio", "command": "repo-tool", "args": [], "env": {}}}}"#,
        ])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": [
            "claude-tool": ["type": "stdio", "command": "claude-tool", "args": ["--serve"], "env": [:]],
            "clash": ["type": "stdio", "command": "clash-a", "args": [], "env": [:]],
        ]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.codex-tool]\ncommand = \"codex-tool\"\nenv_vars = [\"CODEX_KEY\"]\n\n[mcp_servers.clash]\ncommand = \"clash-b\"\n")
        try writeMcpJSON(mcpManaged, ["mcpServers": ["company": ["type": "http", "url": "https://mcp.company.example/mcp"]]])
        let beforeClaude = try String(contentsOf: mcpClaudeState, encoding: .utf8)
        let beforeCodex = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        _ = try installSkillsClaudeFixture("claude-fixture-mcp-link")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("MCP links", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String))
        func server(_ id: String) throws -> [String: Any]? { mcpServersByID(try mcpCatalog(taskID: taskID))[id] }
        openTask(named: "MCP links")
        openMcpPage()
        selectSkillsTab("Global", picker: "mcp-tab-picker")

        let toggle = element("mcp-toggle-claude-tool")
        XCTAssertTrue(toggle.waitForExistence(timeout: 10))
        XCTAssertTrue(isOn(toggle))
        toggle.click()
        XCTAssertTrue(waitUntil({ !self.isOn(toggle) }, timeout: 0.75), "The switch flips as soon as it is clicked.")
        XCTAssertTrue(waitUntil({ ((try? server("global:claude-tool"))??["enabled"] as? Bool) == false }, timeout: 10),
                      "Turning a server off is saved where a fresh CLI process reads it.")
        XCTAssertTrue(element("mcp-always-on-claude-tool").waitForExistence(timeout: 5), "The page says Claude still starts it itself.")
        XCTAssertTrue(element("mcp-provider-claude-tool-claude").exists)
        XCTAssertFalse(element("mcp-provider-claude-tool-codex").exists, "Turning it off stops Codex getting it.")
        XCTAssertEqual(try String(contentsOf: mcpClaudeState, encoding: .utf8), beforeClaude, "Claude Code's configuration is not written.")
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeCodex, "Codex's configuration is not written.")
        attachScreenshot(named: "A server Claude starts itself, turned off")
        element("skills-back-button").click()
        openMcpPage()
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(waitUntil({ self.element("mcp-toggle-claude-tool").exists && !self.isOn(self.element("mcp-toggle-claude-tool")) }, timeout: 10),
                      "The off state survives reopening the page.")
        element("mcp-toggle-claude-tool").click()
        XCTAssertTrue(waitUntil({ ((try? server("global:claude-tool"))??["enabled"] as? Bool) == true }, timeout: 10))

        element("mcp-toggle-codex-tool").click()
        XCTAssertTrue(waitUntil({ !self.element("mcp-provider-codex-tool-claude").exists && !self.element("mcp-provider-codex-tool-codex").exists }, timeout: 10),
                      "A server only Codex defines reaches neither agent once off.")
        XCTAssertFalse(element("mcp-always-on-codex-tool").exists)
        element("mcp-toggle-codex-tool").click()
        XCTAssertTrue(waitUntil({ self.element("mcp-provider-codex-tool-claude").exists }, timeout: 10))
        assertCLIError(try runCLI(["mcp", "disable", "--task", taskID, "--server", "managed:company"], expectedStatus: 2), code: "invalid_argument")

        let actions = element("mcp-actions-clash")
        XCTAssertTrue(waitUntil({ actions.exists && actions.isHittable }, timeout: 10))
        actions.click()
        XCTAssertTrue(app.menuItems["Reveal in Finder"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.menuItems["Make Available Outside Playhouse…"].exists, "A conflicting server can't be linked.")
        app.typeKey(.escape, modifierFlags: [])
        assertCLIError(try runCLI(["mcp", "link", "--task", taskID, "--server", "global:clash"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeCodex, "Nothing is written for it.")

        clickMcpMenuItem(server: "claude-tool", item: "mcp-link-claude-tool", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-mcp", title: "Add to Both CLIs")
        XCTAssertTrue(element("mcp-native-claude-tool").waitForExistence(timeout: 10), "A linked server is one entry both CLIs start.")
        let linkedCodex = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        XCTAssertTrue(linkedCodex.contains("[mcp_servers.claude-tool]") && linkedCodex.contains("args = [\"--serve\"]"),
                      "A Claude-only server is written into Codex's config.toml.")
        attachScreenshot(named: "A Claude server linked into Codex's config")
        clickMcpMenuItem(server: "codex-tool", item: "mcp-link-codex-tool", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-mcp", title: "Add to Both CLIs")
        XCTAssertTrue(element("mcp-native-codex-tool").waitForExistence(timeout: 10))
        let codexTool = try XCTUnwrap((try readMcpJSON(mcpClaudeState)["mcpServers"] as? [String: Any])?["codex-tool"] as? [String: Any])
        XCTAssertEqual(codexTool["env"] as? [String: String], ["CODEX_KEY": "${CODEX_KEY}"], "A Codex-only server is written into Claude Code's file.")

        selectSkillsTab("Repo", picker: "mcp-tab-picker")
        let repoTool = "mcp-link-repo:repo-tool"
        clickMcpMenuItem(server: repoTool, item: "mcp-link-\(repoTool)", title: "Make Available Outside Playhouse…")
        clickDialogButton("confirm-link-mcp", title: "Add to Both CLIs")
        XCTAssertTrue(element("mcp-native-\(repoTool)").waitForExistence(timeout: 10))
        XCTAssertTrue(try String(contentsOf: worktree.appendingPathComponent(".codex/config.toml"), encoding: .utf8).contains("[mcp_servers.repo-tool]"),
                      "A repository server is written into the worktree's .codex/config.toml.")
        XCTAssertFalse(FileManager.default.fileExists(atPath: repository.appendingPathComponent(".codex").path), "The source checkout is left alone.")
        attachScreenshot(named: "A repository server linked for both CLIs")
    }

    // case-contract: test_mcp_fix_with_agent_starts_task_for_conflicting_servers | A server whose definitions conflict offers Fix with Agent, which creates a task on the source task's provider whose saved prompt explains how both agents configure MCP servers and lists each server with its problem: repository servers by repository-relative file, to be fixed in the new task's own worktree and committed and pushed, and global servers by absolute file path, to be fixed in place with their folders opened as context folders. The view switches to the new task's conversation, which sends that prompt once and leaves no unsent draft. A server with no problem, a managed server, an unknown server, and a request without a task are rejected without opening a task.
    func test_mcp_fix_with_agent_starts_task_for_conflicting_servers() throws {
        let repository = try makeSkillRepository("mcp-fix-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"repo-clash": {"type": "stdio", "command": "clash-json", "args": [], "env": {}}, "fine": {"type": "stdio", "command": "fine", "args": [], "env": {}}}}"#,
            ".codex/config.toml": "[mcp_servers.repo-clash]\ncommand = \"clash-toml\"\n",
        ])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": ["clash": ["type": "stdio", "command": "clash-a", "args": [], "env": [:]]]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.clash]\ncommand = \"clash-b\"\n")
        try writeMcpJSON(mcpManaged, ["mcpServers": ["company": ["type": "http", "url": "https://mcp.company.example/mcp"]]])
        let executable = try installSkillsClaudeFixture("claude-fixture-mcp-fix")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        launchApp(defaultParent: fixture.parent.path)
        let source = try createSkillsTask("MCP fix source", repositories: [repository], provider: "claude")
        let sourceID = try XCTUnwrap(source["id"] as? String)
        let sourceWorktree = try XCTUnwrap((source["repositoryWorktrees"] as? [[String: Any]])?.first?["worktreePath"] as? String)
        let tasksBefore = try boardTaskRecords().count
        assertCLIError(try runCLI(["mcp", "fix", "--task", sourceID, "--server", "repo:\(repository.path)#fine"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["mcp", "fix", "--task", sourceID, "--server", "managed:company"], expectedStatus: 2), code: "invalid_argument")
        assertCLIError(try runCLI(["mcp", "fix", "--task", sourceID, "--server", "global:no-such-server"], expectedStatus: 3), code: "not_found")
        assertCLIError(try runCLI(["mcp", "fix", "--server", "global:clash"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertEqual(try boardTaskRecords().count, tasksBefore, "A rejected fix opens no task.")

        openTask(named: "MCP fix source")
        openMcpPage()
        XCTAssertTrue(element("mcp-fix-mcp-fix-repo:repo-clash").waitForExistence(timeout: 10), "A conflicting server offers Fix with Agent.")
        XCTAssertTrue(element("mcp-conflict-mcp-fix-repo:repo-clash").exists)
        XCTAssertFalse(element("mcp-fix-mcp-fix-repo:fine").exists, "A server without a problem has nothing to fix.")
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-fix-clash").waitForExistence(timeout: 5))
        attachScreenshot(named: "A conflicting global server offers Fix with Agent")

        element("mcp-fix-clash").click()
        XCTAssertTrue(waitUntil({ !self.element("skills-page").exists }, timeout: 10), "Fixing closes the page.")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == "Fix MCP server clash" }, timeout: 15),
                      "The view switches to the fixing task's conversation.")
        let single = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == "Fix MCP server clash" })
        XCTAssertEqual((single["repositoryWorktrees"] as? [Any])?.count, 0, "Fixing only global servers needs no repository.")
        XCTAssertEqual(Set(((single["contextFolders"] as? [String]) ?? []).map(realPath)), [realPath(skillsHome.path), realPath(skillsCodexHome.path)],
                       "The folders of the global files are opened to the agent.")
        let singlePrompt = try XCTUnwrap(single["savedPrompt"] as? String)
        XCTAssertTrue(singlePrompt.contains("not tracked by Git"))
        XCTAssertTrue(singlePrompt.contains(mcpClaudeState.path) || singlePrompt.contains(realPath(mcpClaudeState.path)), "A global server is named by its file's absolute path.")
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == singlePrompt } }, timeout: 20),
                      "The fixing task sends its prompt as soon as it opens.")

        openTask(named: "MCP fix source")
        openMcpPage()
        XCTAssertTrue(element("mcp-fix-mcp-fix-repo:repo-clash").waitForExistence(timeout: 10))
        element("mcp-fix-mcp-fix-repo:repo-clash").click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("task-view-title")) == "Fix MCP server repo-clash" }, timeout: 15))
        let fixing = try XCTUnwrap(try boardTaskRecords().first { $0["title"] as? String == "Fix MCP server repo-clash" })
        let fixingID = try XCTUnwrap(fixing["id"] as? String)
        let prompt = try XCTUnwrap(fixing["savedPrompt"] as? String)
        XCTAssertEqual(fixing["conversationProvider"] as? String, "claude", "The fixing task uses the source task's provider.")
        XCTAssertTrue(prompt.contains("Claude Code reads `mcpServers`"), "The prompt explains how both agents configure servers.")
        XCTAssertTrue(prompt.contains("[mcp_servers.<name>]"))
        XCTAssertTrue(prompt.contains("commit and push"))
        XCTAssertTrue(prompt.contains("`repo-clash` in mcp-fix-repo: `.mcp.json`, `.codex/config.toml`"))
        XCTAssertFalse(prompt.contains(sourceWorktree), "Repository files are relative, so they point into the fixing task's worktree.")
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == prompt } }, timeout: 20), "The conversation sends the fixing prompt.")
        XCTAssertTrue(waitUntil({ (self.element("message-composer").value as? String ?? "").isEmpty }, timeout: 10),
                      "The sent prompt leaves the composer, so it cannot be sent twice.")
        attachScreenshot(named: "The server-fixing task's conversation")
        XCTAssertEqual(claudeTurns(historyURL).filter { $0["userText"] as? String == prompt }.count, 1, "The fixing prompt is sent exactly once.")
        let started = try XCTUnwrap(try taskRecord(id: fixingID))
        XCTAssertEqual(started["hasUnsentDraft"] as? Bool, false)
        let worktree = try XCTUnwrap((started["repositoryWorktrees"] as? [[String: Any]])?.first)
        XCTAssertEqual(worktree["repositoryPath"] as? String, repository.path)
        XCTAssertNotEqual(realPath(worktree["worktreePath"] as? String ?? ""), realPath(sourceWorktree))
    }

    // case-contract: test_mcp_bridge_claude_launch_passes_shared_servers | A Claude turn starts the servers Claude Code does not read itself: its --mcp-config carries Codex's own global servers (with env_vars passed as ${NAME}), the working repository's .codex/config.toml servers, and the other task repository's .mcp.json servers, but not the servers Claude Code already reads or ones turned off on the page. Its --settings starts the working repository's .mcp.json servers that are on with enabledMcpjsonServers and skips turned-off ones with disabledMcpjsonServers, without writing to the repository or either provider's configuration. The resumed second turn carries the same servers, and turning a server back on adds it.
    func test_mcp_bridge_claude_launch_passes_shared_servers() throws {
        let repository = try makeSkillRepository("mcp-claude-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"repo-tool": {"type": "stdio", "command": "repo-tool", "args": [], "env": {}}, "repo-off": {"type": "stdio", "command": "repo-off", "args": [], "env": {}}}}"#,
            ".codex/config.toml": "[mcp_servers.repo-codex]\ncommand = \"repo-codex\"\nargs = [\"--serve\"]\n",
        ])
        let extra = try makeSkillRepository("mcp-claude-extra", skills: [
            ".mcp.json": #"{"mcpServers": {"extra-api": {"type": "http", "url": "https://extra.example.com/mcp"}}}"#,
        ])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": ["claude-tool": ["type": "stdio", "command": "claude-tool", "args": [], "env": [:]]]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.codex-tool]\ncommand = \"codex-tool\"\nenv_vars = [\"CODEX_KEY\"]\n\n[mcp_servers.codex-off]\ncommand = \"codex-off\"\n")
        let beforeClaude = try String(contentsOf: mcpClaudeState, encoding: .utf8)
        let beforeCodex = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        let executable = try installSkillsClaudeFixture("claude-fixture-mcp-bridge")
        let historyURL = URL(fileURLWithPath: executable.path + ".history")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Claude MCP", repositories: [repository, extra], provider: "claude")
        let taskID = try XCTUnwrap(task["id"] as? String)
        let worktree = URL(fileURLWithPath: try XCTUnwrap((task["repositoryWorktrees"] as? [[String: Any]])?.first { $0["repositoryPath"] as? String == repository.path }?["worktreePath"] as? String))
        openTask(named: "Claude MCP")
        openMcpPage()
        let repoOff = "mcp-claude-repo:repo-off"
        XCTAssertTrue(element("mcp-toggle-\(repoOff)").waitForExistence(timeout: 10))
        element("mcp-toggle-\(repoOff)").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("mcp-toggle-\(repoOff)")) }, timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-mcp-claude-extra:extra-api")), "Playhouse passes it to Claude and Codex.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-mcp-claude-repo:repo-codex")), "Playhouse passes it to Claude and Codex.")
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-toggle-codex-off").waitForExistence(timeout: 5))
        element("mcp-toggle-codex-off").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("mcp-toggle-codex-off")) }, timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-codex-tool")), "Playhouse passes it to Claude.")
        attachScreenshot(named: "Servers a Claude turn will start, with one turned off")
        element("skills-back-button").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Use the tools.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == "Use the tools." } }, timeout: 20))
        let first = try XCTUnwrap(claudeTurns(historyURL).first { $0["userText"] as? String == "Use the tools." })
        let arguments = try XCTUnwrap(first["arguments"] as? [String])
        let config = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(arguments[try XCTUnwrap(arguments.firstIndex(of: "--mcp-config")) + 1].utf8)) as? [String: Any])
        let servers = try XCTUnwrap(config["mcpServers"] as? [String: Any])
        XCTAssertEqual(Set(servers.keys), ["codex-tool", "extra-api", "repo-codex"],
                       "Claude gets the servers it does not read itself, without the ones it reads or ones turned off.")
        XCTAssertEqual((servers["codex-tool"] as? [String: Any])?["env"] as? [String: String], ["CODEX_KEY": "${CODEX_KEY}"])
        XCTAssertEqual((servers["extra-api"] as? [String: Any])?["url"] as? String, "https://extra.example.com/mcp")
        let settings = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(arguments[try XCTUnwrap(arguments.firstIndex(of: "--settings")) + 1].utf8)) as? [String: Any])
        XCTAssertEqual(settings["enabledMcpjsonServers"] as? [String], ["repo-tool"], "The working repository's .mcp.json server that is on starts.")
        XCTAssertEqual(settings["disabledMcpjsonServers"] as? [String], ["repo-off"], "A turned-off .mcp.json server is skipped for this run.")
        XCTAssertEqual(try String(contentsOf: mcpClaudeState, encoding: .utf8), beforeClaude, "Claude Code's configuration is not written.")
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeCodex, "Codex's configuration is not written.")
        XCTAssertEqual(try runGitOutput(worktree, "status", "--porcelain"), "", "The worktree is not written to.")
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String).map { $0 != "In Progress" } == true }, timeout: 30),
                      "The first turn should settle before the next message.")

        openMcpPage()
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-toggle-codex-off").waitForExistence(timeout: 5))
        element("mcp-toggle-codex-off").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("mcp-toggle-codex-off")) }, timeout: 10))
        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Use them again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ self.claudeTurns(historyURL).contains { $0["userText"] as? String == "Use them again." } }, timeout: 20))
        let second = try XCTUnwrap(claudeTurns(historyURL).last { $0["userText"] as? String == "Use them again." })
        XCTAssertEqual(second["resumed"] as? Bool, true, "The second turn resumes the Claude session.")
        let resumed = try XCTUnwrap(second["arguments"] as? [String])
        let resumedConfig = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(resumed[try XCTUnwrap(resumed.firstIndex(of: "--mcp-config")) + 1].utf8)) as? [String: Any])
        XCTAssertEqual(Set(((resumedConfig["mcpServers"] as? [String: Any]) ?? [:]).keys), ["codex-off", "codex-tool", "extra-api", "repo-codex"],
                       "Turning a server back on adds it.")
    }

    // case-contract: test_mcp_bridge_codex_thread_gets_shared_servers | A Codex turn starts the servers Codex does not read itself: the thread's mcp_servers config carries the working repository's .mcp.json servers and Claude Code's own global servers, translated so ${NAME} environment references become env_vars and an Authorization bearer token becomes bearer_token_env_var, leaves out an SSE server Codex can't run and the servers Codex already reads, and turns off a server Codex may read itself (from its config.toml or the working repository's .codex/config.toml) that is turned off on the page with enabled = false, without writing Codex's config.toml. Turning servers on or off on the page resumes the thread on its next turn with the new mcp_servers config.
    func test_mcp_bridge_codex_thread_gets_shared_servers() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let historyURL = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".history")
        let repository = try makeSkillRepository("mcp-codex-repo", skills: [
            ".mcp.json": #"{"mcpServers": {"repo-tool": {"type": "stdio", "command": "repo-tool", "args": ["--serve"], "env": {"REPO_TOKEN": "${REPO_TOKEN}", "MODE": "fast"}}, "repo-sse": {"type": "sse", "url": "https://sse.example.com/mcp"}}}"#,
            ".codex/config.toml": "[mcp_servers.repo-codex-off]\ncommand = \"repo-codex-off\"\n",
        ])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": [
            "claude-remote": ["type": "http", "url": "https://remote.example.com/mcp", "headers": ["Authorization": "Bearer ${REMOTE_TOKEN}", "X-Team": "core"]],
        ]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.codex-tool]\ncommand = \"codex-tool\"\n\n[mcp_servers.codex-off]\ncommand = \"codex-off\"\n")
        let beforeCodex = try String(contentsOf: mcpCodexConfig, encoding: .utf8)
        _ = try installSkillsClaudeFixture("claude-fixture-mcp-codex")
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("Codex MCP", repositories: [repository])
        let taskID = try XCTUnwrap(task["id"] as? String)
        func history() -> [String: Any] {
            guard let data = try? Data(contentsOf: historyURL) else { return [:] }
            return (try? JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
        }
        func answerQuestionIfAsked() {
            guard element("ai-question-form-title").waitForExistence(timeout: 10) else { return }
            selectQuestionOption("Blue")
            typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
            element("submit-ai-answers-button").click()
        }

        openTask(named: "Codex MCP")
        openMcpPage()
        let sse = "mcp-codex-repo:repo-sse"
        XCTAssertTrue(element("mcp-row-\(sse)").waitForExistence(timeout: 10))
        XCTAssertFalse(element("mcp-provider-\(sse)-codex").exists, "Codex can't run an SSE server.")
        let repoCodexOff = "mcp-codex-repo:repo-codex-off"
        XCTAssertTrue(element("mcp-toggle-\(repoCodexOff)").exists)
        element("mcp-toggle-\(repoCodexOff)").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("mcp-toggle-\(repoCodexOff)")) }, timeout: 10))
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-toggle-codex-off").waitForExistence(timeout: 5))
        element("mcp-toggle-codex-off").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("mcp-toggle-codex-off")) }, timeout: 10))
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-shared-claude-remote")), "Playhouse passes it to Codex.")
        attachScreenshot(named: "Servers a Codex turn will start, with one turned off")
        element("skills-back-button").click()
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 10))
        composer.click()
        composer.typeText("Use the tools.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "Use the tools." }, timeout: 20))
        let servers = try XCTUnwrap((history()["threadStartConfig"] as? [String: Any])?["mcp_servers"] as? [String: Any])
        XCTAssertEqual(Set(servers.keys), ["repo-tool", "claude-remote", "codex-off", "repo-codex-off"],
                       "Codex gets the servers it does not read itself, without an SSE server or the ones it reads.")
        let repoTool = try XCTUnwrap(servers["repo-tool"] as? [String: Any])
        XCTAssertEqual(repoTool["env_vars"] as? [String], ["REPO_TOKEN"], "${NAME} references become env_vars.")
        XCTAssertEqual(repoTool["env"] as? [String: String], ["MODE": "fast"])
        let remote = try XCTUnwrap(servers["claude-remote"] as? [String: Any])
        XCTAssertEqual(remote["bearer_token_env_var"] as? String, "REMOTE_TOKEN", "A bearer token becomes bearer_token_env_var.")
        XCTAssertEqual(remote["http_headers"] as? [String: String], ["X-Team": "core"])
        let off = try XCTUnwrap(servers["codex-off"] as? [String: Any])
        XCTAssertEqual(off["enabled"] as? Bool, false, "A Codex server turned off on the page is turned off for the thread.")
        XCTAssertEqual(off["command"] as? String, "codex-off")
        XCTAssertEqual((servers["repo-codex-off"] as? [String: Any])?["enabled"] as? Bool, false,
                       "A turned-off server in the working repository's .codex/config.toml is turned off for the thread.")
        XCTAssertEqual(try String(contentsOf: mcpCodexConfig, encoding: .utf8), beforeCodex, "Codex's config.toml is not written.")
        answerQuestionIfAsked()
        XCTAssertTrue(waitUntil({ (try? self.taskRecord(id: taskID)?["status"] as? String).map { $0 != "In Progress" } == true }, timeout: 30),
                      "The first turn should settle before the next message.")

        let resumesBefore = history()["threadResumeCount"] as? Int ?? 0
        openMcpPage()
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-toggle-codex-off").waitForExistence(timeout: 5))
        element("mcp-toggle-codex-off").click()
        XCTAssertTrue(waitUntil({ self.isOn(self.element("mcp-toggle-codex-off")) }, timeout: 10))
        selectSkillsTab("Repo", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-toggle-mcp-codex-repo:repo-tool").waitForExistence(timeout: 5))
        element("mcp-toggle-mcp-codex-repo:repo-tool").click()
        XCTAssertTrue(waitUntil({ !self.isOn(self.element("mcp-toggle-mcp-codex-repo:repo-tool")) }, timeout: 10))
        element("skills-back-button").click()
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 20))
        composer.click()
        composer.typeText("Use them again.")
        element("send-message-button").click()
        XCTAssertTrue(waitUntil({ history()["userMessage"] as? String == "Use them again." }, timeout: 20))
        XCTAssertGreaterThan(history()["threadResumeCount"] as? Int ?? 0, resumesBefore, "Changing the servers resumes the thread.")
        let resumed = try XCTUnwrap((history()["threadResumeConfig"] as? [String: Any])?["mcp_servers"] as? [String: Any])
        XCTAssertEqual(Set(resumed.keys), ["claude-remote", "repo-codex-off"], "The resumed thread gets the new servers.")
        answerQuestionIfAsked()
    }

    // case-contract: test_mcp_status_reports_sign_in_per_provider | Opening the MCP page asks both agents on its own, with no button to press, which servers they start and which need a sign-in, showing Checking sign-in… while they answer and asking again whenever the page is opened: Claude Code, asked with the task's own MCP bridge, reports each server including the ones Playhouse passes it, and Codex reports its own; a server that needs a sign-in shows a Sign in for Claude or Sign in for Codex badge on its row, and the claude.ai connectors and plugin servers Claude Code starts that no file defines are listed under Also started by Claude Code on the Managed tab, a connector that needs a sign-in with the same badge. Asking for one provider only asks that provider. An agent that can't be asked is reported by name on the page while the other agent's answer is still shown.
    func test_mcp_status_reports_sign_in_per_provider() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let codexStatus = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".mcp-status")
        let codexStatusFail = URL(fileURLWithPath: try XCTUnwrap(codexFixtureExecutable) + ".mcp-status-fail")
        try? FileManager.default.removeItem(at: codexStatusFail)
        addTeardownBlock {
            try? FileManager.default.removeItem(at: codexStatus)
            try? FileManager.default.removeItem(at: codexStatusFail)
        }
        let repository = try makeSkillRepository("mcp-status-repo", skills: [:])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": ["claude-remote": ["type": "http", "url": "https://remote.example.com/mcp"]]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.codex-remote]\nurl = \"https://codex.example.com/mcp\"\n\n[mcp_servers.codex-tool]\ncommand = \"codex-tool\"\n")
        let claude = try installSkillsClaudeFixture("claude-fixture-mcp-status")
        try writeMcpJSON(URL(fileURLWithPath: claude.path + ".mcp-status"), [
            ["name": "claude-remote", "status": "needs-auth"],
            ["name": "claude.ai Notes", "status": "needs-auth"],
            ["name": "plugin:kit:helper", "status": "connected"],
        ])
        try writeMcpJSON(codexStatus, [
            ["name": "codex-remote", "authStatus": "notLoggedIn", "tools": [:]],
            ["name": "codex-tool", "authStatus": "unsupported", "tools": [:]],
        ])
        // Claude Code answers slowly, so the page can be seen while it is still checking.
        let claudeDelay = URL(fileURLWithPath: claude.path + ".mcp-status-delay")
        try "4\n".write(to: claudeDelay, atomically: true, encoding: .utf8)
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("MCP status", repositories: [repository], provider: "claude")
        let taskID = try XCTUnwrap(task["id"] as? String)
        openTask(named: "MCP status")
        openMcpPage()
        XCTAssertTrue(element("mcp-checking-status").waitForExistence(timeout: 10), "The page shows it is checking as soon as it opens.")
        XCTAssertEqual(accessibleLabelOrValue(of: element("mcp-checking-status")), "Checking sign-in…")
        XCTAssertFalse(element("mcp-signin-claude-remote-claude").exists, "No badge shows before the agents have answered.")
        attachScreenshot(named: "Checking sign-in while the agents answer")
        XCTAssertFalse(element("mcp-check-status").exists, "There is no button to press: the page checks on its own.")
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-row-claude-remote").waitForExistence(timeout: 10))
        XCTAssertTrue(element("mcp-signin-claude-remote-claude").waitForExistence(timeout: 30),
                      "A server Claude can't start without a sign-in is marked as soon as the page has asked.")
        XCTAssertTrue(element("mcp-signin-codex-remote-codex").exists, "A server Codex can't start without a sign-in is marked.")
        XCTAssertFalse(element("mcp-signin-codex-tool-codex").exists, "A server that needs no sign-in is not marked.")
        XCTAssertTrue(waitUntil({ !self.element("mcp-checking-status").exists }, timeout: 30), "The check finishes.")
        XCTAssertFalse(element("mcp-error").exists, "Both agents answered.")
        attachScreenshot(named: "Opening the page marks servers that need a sign-in")
        selectSkillsTab("Managed", picker: "mcp-tab-picker")
        XCTAssertTrue(element("mcp-connector-claude.ai Notes").waitForExistence(timeout: 5), "A claude.ai connector is listed.")
        let connectorSignIn = element("mcp-connector-signin-claude.ai Notes")
        XCTAssertTrue(connectorSignIn.exists, "A connector that needs a sign-in has the same badge.")
        XCTAssertTrue(connectorSignIn.isEnabled && connectorSignIn.isHittable, "The badge is a button, not a label.")
        // A claude.ai connector is signed in to on claude.ai: the click opens its settings (a test build never opens a browser).
        connectorSignIn.click()
        XCTAssertFalse(element("mcp-error").exists, "Clicking a connector's badge starts no sign-in that could fail.")
        XCTAssertTrue(connectorSignIn.exists && connectorSignIn.isEnabled, "The badge stays: it signs in on claude.ai, not here.")
        XCTAssertTrue(element("mcp-connector-plugin:kit:helper").exists, "A plugin server is listed.")
        XCTAssertFalse(element("mcp-connector-signin-plugin:kit:helper").exists, "A signed-in plugin server has no sign-in badge.")
        XCTAssertFalse(element("mcp-connector-claude-remote").exists, "A server a file defines is not repeated.")
        attachScreenshot(named: "Servers Claude Code starts on its own")

        // Opening the page again asks again, now with Codex unable to answer.
        try "Fail the status request.\n".write(to: codexStatusFail, atomically: true, encoding: .utf8)
        selectSkillsTab("Skills", picker: "skills-kind-picker")
        selectSkillsTab("MCP", picker: "skills-kind-picker")
        XCTAssertTrue(element("mcp-page").waitForExistence(timeout: 10))
        XCTAssertTrue(element("mcp-checking-status").waitForExistence(timeout: 10), "Opening the page checks again.")
        selectSkillsTab("Global", picker: "mcp-tab-picker")
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: self.element("mcp-error")).contains("Codex") }, timeout: 30),
                      "An agent that can't be asked is reported by name.")
        XCTAssertTrue(element("mcp-signin-claude-remote-claude").exists, "The other agent's answer is still shown.")
        XCTAssertFalse(element("mcp-signin-codex-remote-codex").exists, "Codex's earlier answer is not kept as if it were current.")
        attachScreenshot(named: "Opening the page when Codex can't be asked")
        try FileManager.default.removeItem(at: codexStatusFail)
        try FileManager.default.removeItem(at: claudeDelay)

        let report = try XCTUnwrap(try runCLI(["mcp", "status", "--task", taskID])["result"] as? [String: Any])
        XCTAssertEqual((report["errors"] as? [String: Any])?.count, 0)
        let codexOnly = try XCTUnwrap(try runCLI(["mcp", "status", "--task", taskID, "--provider", "codex"])["result"] as? [String: Any])
        XCTAssertEqual((codexOnly["claude"] as? [Any])?.count, 0, "Asking for Codex alone doesn't ask Claude Code.")
        XCTAssertTrue(((codexOnly["codex"] as? [[String: Any]]) ?? []).contains { $0["name"] as? String == "codex-remote" && $0["needsSignIn"] as? Bool == true })
        let claudeOnly = try XCTUnwrap(try runCLI(["mcp", "status", "--task", taskID, "--provider", "claude"])["result"] as? [String: Any])
        XCTAssertEqual((claudeOnly["codex"] as? [Any])?.count, 0, "Asking for Claude alone doesn't ask Codex.")
        XCTAssertTrue(((claudeOnly["claude"] as? [[String: Any]]) ?? []).contains { $0["name"] as? String == "claude-remote" && $0["needsSignIn"] as? Bool == true })
        assertCLIError(try runCLI(["mcp", "status", "--provider", "gemini"], expectedStatus: 2), code: "invalid_argument")
        XCTAssertTrue(((report["claude"] as? [[String: Any]]) ?? []).contains { $0["name"] as? String == "codex-tool" && $0["status"] as? String == "connected" },
                      "Claude is asked with the servers Playhouse passes it.")
        try FileManager.default.removeItem(at: codexStatus)
        let noCodex = try XCTUnwrap(try runCLI(["mcp", "status", "--task", taskID], extraEnvironment: ["PLAYHOUSE_E2E_CODEX_EXECUTABLE": "none"])["result"] as? [String: Any])
        XCTAssertNotNil((noCodex["errors"] as? [String: Any])?["codex"], "An agent that can't be asked is reported by name.")
        XCTAssertTrue(((noCodex["claude"] as? [[String: Any]]) ?? []).contains { $0["name"] as? String == "claude-remote" }, "The other agent's answer is still shown.")
    }

    // case-contract: test_mcp_authenticate_signs_in_each_provider | The Sign in for Claude or Sign in for Codex badge on a server is the button that signs in: it asks that agent to start the OAuth sign-in of that one server (Claude Code's mcp_authenticate, Codex's mcpServer/oauth/login) and returns the authorization link, which the page opens in the browser (a test build only records it, and never opens one) while the badge reads Waiting for sign-in…. A server both agents have shows one Sign in button per agent on the same row: each starts only its own agent's sign-in, waiting on one leaves the other clickable, and each badge clears on its own once that agent is signed in. The agent finishes the sign-in when the browser redirects back to it, and the page then checks again by itself and the badge goes away; waiting for it through the CLI keeps the bridge running and returns signed in. Starting one agent's sign-in never asks the other agent, a sign-in nobody finishes times out with a message that names the server, and waiting for a sign-in that was never started or was already reported with either agent, an unknown provider, and a blank server name are rejected or reported without starting anything.
    func test_mcp_authenticate_signs_in_each_provider() throws {
        codexFixtureExecutable = try makeCodexFixture(emptyQuestions: false).path
        let codexPath = try XCTUnwrap(codexFixtureExecutable)
        let codexSidecars = [".mcp-status", ".mcp-callback", ".mcp-login"].map { URL(fileURLWithPath: codexPath + $0) }
        codexSidecars.forEach { try? FileManager.default.removeItem(at: $0) }
        addTeardownBlock { codexSidecars.forEach { try? FileManager.default.removeItem(at: $0) } }
        let repository = try makeSkillRepository("mcp-auth-repo", skills: [:])
        try writeMcpJSON(mcpClaudeState, ["mcpServers": [
            "shared-remote": ["type": "http", "url": "https://remote.example.com/mcp"],
            "claude-other": ["type": "http", "url": "https://other.example.com/mcp"],
        ]])
        try writeRuleFile(mcpCodexConfig, "[mcp_servers.shared-remote]\nurl = \"https://remote.example.com/mcp\"\n\n[mcp_servers.codex-remote]\nurl = \"https://codex.example.com/mcp\"\n\n[mcp_servers.codex-other]\nurl = \"https://codex-other.example.com/mcp\"\n")
        let claude = try installSkillsClaudeFixture("claude-fixture-mcp-auth")
        try writeMcpJSON(URL(fileURLWithPath: claude.path + ".mcp-status"), [
            ["name": "shared-remote", "status": "needs-auth"], ["name": "claude-other", "status": "needs-auth"],
        ])
        try writeMcpJSON(URL(fileURLWithPath: codexPath + ".mcp-status"), [
            ["name": "shared-remote", "authStatus": "notLoggedIn", "tools": [:]],
            ["name": "codex-remote", "authStatus": "notLoggedIn", "tools": [:]], ["name": "codex-other", "authStatus": "notLoggedIn", "tools": [:]],
        ])
        func logged(_ path: String) -> [[String: String]] {
            ((try? String(contentsOfFile: path, encoding: .utf8)) ?? "").split(separator: "\n").compactMap {
                (try? JSONSerialization.jsonObject(with: Data($0.utf8))) as? [String: String]
            }
        }
        /// The browser's redirect back to the agent, which the fixture reads from a file of server names.
        func redirect(_ name: String, to path: String) throws {
            let existing = (try? String(contentsOfFile: path, encoding: .utf8)) ?? ""
            try (existing + name + "\n").write(toFile: path, atomically: true, encoding: .utf8)
        }
        launchApp(defaultParent: fixture.parent.path)
        let task = try createSkillsTask("MCP authenticate", repositories: [repository], provider: "claude")
        let taskID = try XCTUnwrap(task["id"] as? String)
        openTask(named: "MCP authenticate")
        openMcpPage()
        selectSkillsTab("Global", picker: "mcp-tab-picker")

        let claudeBadge = element("mcp-signin-shared-remote-claude")
        XCTAssertTrue(claudeBadge.waitForExistence(timeout: 30), "The sign-in badges show up without pressing anything.")
        XCTAssertTrue(element("mcp-signin-codex-remote-codex").exists)
        let sharedCodexBadge = element("mcp-signin-shared-remote-codex")
        XCTAssertTrue(sharedCodexBadge.exists, "A server both agents have gets a sign-in button for each of them on the same row.")
        XCTAssertTrue(element("mcp-row-shared-remote").exists)
        attachScreenshot(named: "A server both agents have needs a sign-in for each of them")

        // A real click at the badge's position: it starts the sign-in rather than opening the server's editor.
        claudeBadge.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: claudeBadge).contains("Waiting for sign-in") }, timeout: 15),
                      "The badge reads Waiting for sign-in… while Claude Code waits for the browser.")
        XCTAssertFalse(element("mcp-editor-panel").exists, "Clicking the badge doesn't open the server's editor.")
        XCTAssertTrue(sharedCodexBadge.isEnabled && accessibleLabelOrValue(of: sharedCodexBadge).contains("Sign in for Codex"),
                      "Codex's button on the same server stays available while Claude's waits.")
        XCTAssertTrue(waitUntil({ logged(claude.path + ".mcp-authenticate") == [["serverName": "shared-remote"]] }, timeout: 20),
                      "Claude Code is asked to sign in to that server only.")
        XCTAssertTrue(logged(codexPath + ".mcp-login").isEmpty, "Claude's sign-in doesn't ask Codex.")
        XCTAssertTrue(element("mcp-signin-codex-remote-codex").exists, "The other agent's badge is unchanged.")
        XCTAssertFalse(claudeBadge.isEnabled, "A sign-in that is waiting can't be started twice.")
        attachScreenshot(named: "Claude sign-in waiting for the browser")
        try redirect("shared-remote", to: claude.path + ".mcp-callback")
        XCTAssertTrue(waitUntil({ !self.element("mcp-signin-shared-remote-claude").exists }, timeout: 30),
                      "Once the browser has redirected back, the badge goes away.")
        XCTAssertFalse(element("mcp-error").exists)
        XCTAssertTrue(element("mcp-signin-codex-remote-codex").exists)
        XCTAssertTrue(sharedCodexBadge.exists, "Signing in for Claude doesn't sign the same server in for Codex.")
        attachScreenshot(named: "Claude sign-in finished; the same server still needs Codex's")

        let codexBadge = element("mcp-signin-codex-remote-codex")
        codexBadge.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).click()
        XCTAssertTrue(waitUntil({ self.accessibleLabelOrValue(of: codexBadge).contains("Waiting for sign-in") }, timeout: 15))
        XCTAssertTrue(waitUntil({ logged(codexPath + ".mcp-login") == [["name": "codex-remote"]] }, timeout: 20), "Codex is asked to sign in to that server only.")
        XCTAssertEqual(logged(claude.path + ".mcp-authenticate"), [["serverName": "shared-remote"]], "Codex's sign-in doesn't ask Claude Code.")
        attachScreenshot(named: "Codex sign-in waiting for the browser")
        try redirect("codex-remote", to: codexPath + ".mcp-callback")
        XCTAssertTrue(waitUntil({ !self.element("mcp-signin-codex-remote-codex").exists }, timeout: 30), "The Codex badge goes away too.")
        XCTAssertFalse(element("mcp-error").exists)
        XCTAssertTrue(element("mcp-signin-claude-other-claude").exists && element("mcp-signin-codex-other-codex").exists, "Other servers still need theirs.")
        attachScreenshot(named: "Both sign-ins finished")

        func cli(_ command: [String], extra: [String: String] = [:], status: Int32 = 0) throws -> [String: Any] {
            try runCLI(["mcp"] + command + ["--task", taskID], expectedStatus: status, extraEnvironment: extra)
        }
        func result(_ response: [String: Any]) throws -> [String: Any] { try XCTUnwrap(response["result"] as? [String: Any]) }
        let started = try result(try cli(["authenticate", "--provider", "claude", "--name", "claude-other"], extra: ["PLAYHOUSE_E2E_MCP_LOGIN_TIMEOUT_SECONDS": "2"]))
        XCTAssertEqual(started["authorizationUrl"] as? String, "https://auth.example.test/claude/authorize?server=claude-other")
        let timedOut = try result(try cli(["authenticate-wait", "--provider", "claude", "--name", "claude-other"], extra: ["PLAYHOUSE_E2E_MCP_LOGIN_TIMEOUT_SECONDS": "2"]))
        XCTAssertEqual(timedOut["signedIn"] as? Bool, false, "A sign-in nobody finishes doesn't sign in.")
        XCTAssertTrue((timedOut["error"] as? String ?? "").contains("claude-other") && (timedOut["error"] as? String ?? "").contains("in time"))
        let codexStarted = try result(try cli(["authenticate", "--provider", "codex", "--name", "codex-other"]))
        XCTAssertEqual(codexStarted["authorizationUrl"] as? String, "https://auth.example.test/codex/authorize?server=codex-other")
        let codexTimedOut = try result(try cli(["authenticate-wait", "--provider", "codex", "--name", "codex-other"], extra: ["PLAYHOUSE_E2E_MCP_LOGIN_TIMEOUT_SECONDS": "2"]))
        XCTAssertEqual(codexTimedOut["signedIn"] as? Bool, false)
        XCTAssertTrue((codexTimedOut["error"] as? String ?? "").contains("codex-other"))
        let never = try result(try cli(["authenticate-wait", "--provider", "claude", "--name", "never-started"]))
        XCTAssertEqual(never["signedIn"] as? Bool, false, "Waiting for a sign-in that was never started reports it.")
        XCTAssertTrue((never["error"] as? String ?? "").contains("No sign-in"))
        for (provider, name) in [("claude", "shared-remote"), ("codex", "codex-remote")] {
            let reported = try result(try cli(["authenticate-wait", "--provider", provider, "--name", name]))
            XCTAssertEqual(reported["signedIn"] as? Bool, false, "A finished sign-in is reported once; waiting again finds none in progress.")
            XCTAssertTrue((reported["error"] as? String ?? "").contains("No sign-in"))
        }
        assertCLIError(try cli(["authenticate", "--provider", "gemini", "--name", "shared-remote"], status: 2), code: "invalid_argument")
        assertCLIError(try cli(["authenticate", "--provider", "claude", "--name", ""], status: 2), code: "invalid_argument")
        XCTAssertEqual(logged(claude.path + ".mcp-authenticate").last, ["serverName": "claude-other"], "A rejected request starts nothing.")
    }

    // case-contract: test_settings_cpu_usage_color_max_round_trip | The CPU usage color maximum defaults to one fully busy core per logical CPU, round-trips through the CLI/XPC settings commands, and rejects a non-positive value as invalid_argument without changing the stored setting.
    func test_settings_cpu_usage_color_max_round_trip() throws {
        launchApp(defaultParent: fixture.parent.path)
        let expectedDefault = ProcessInfo.processInfo.activeProcessorCount * 100
        XCTAssertEqual(
            (try runCLI(["settings", "get"])["result"] as? [String: Any])?["cpuUsageColorMax"] as? Int, expectedDefault,
            "The bar's scale tops out at one busy core per logical CPU by default."
        )

        app.typeKey(",", modifierFlags: .command)
        let preferences = settingsWindow
        XCTAssertTrue(preferences.waitForExistence(timeout: 10), "Workspace Settings did not open.")
        let maxField = preferences.descendants(matching: .any)
            .matching(identifier: "cpu-usage-color-max-field").firstMatch
        XCTAssertTrue(maxField.waitForExistence(timeout: 5), "Settings should expose the CPU usage maximum.")
        XCTAssertEqual(maxField.value as? String, expectedDefault.formatted(), "The field should show the stored maximum.")
        attachScreenshot(named: "Workspace Settings exposes the CPU usage color maximum")
        maxField.click()
        maxField.typeKey("a", modifierFlags: .command)
        maxField.typeText("250\r")
        XCTAssertTrue(waitUntil({
            ((try? self.runCLI(["settings", "get"])["result"] as? [String: Any])?["cpuUsageColorMax"] as? Int) == 250
        }, timeout: 10), "An edited maximum should save through the same settings manager the CLI reads.")
        app.typeKey("w", modifierFlags: .command)
        XCTAssertTrue(waitUntil({ !preferences.exists }, timeout: 5))

        assertCLIError(
            try runCLI(["settings", "set-cpu-usage-color-max", "0"], expectedStatus: 2),
            code: "invalid_argument"
        )
        XCTAssertEqual(
            (try runCLI(["settings", "get"])["result"] as? [String: Any])?["cpuUsageColorMax"] as? Int, 250,
            "A rejected maximum should leave the stored one alone."
        )
    }

    /// The real provider selected for opt-in live UI cases, or nil for the
    /// deterministic fixture suite. The runner writes it to the marker file.
    private var liveProvider: String? {
        let environment = ProcessInfo.processInfo.environment
        if let marker = try? String(contentsOfFile: "/tmp/playhouse-live-ui-integration", encoding: .utf8) {
            let provider = marker.trimmingCharacters(in: .whitespacesAndNewlines)
            return provider.isEmpty ? "claude" : provider
        }
        if environment["PLAYHOUSE_RUN_LIVE_INTEGRATION"] == "1" { return environment["PLAYHOUSE_LIVE_PROVIDER"] ?? "claude" }
        if environment["PLAYHOUSE_RUN_CODEX_INTEGRATION"] == "1" { return "codex" }
        return nil
    }

    private var isLiveIntegration: Bool { liveProvider != nil }

    /// Live Codex cases use the guest's signed-in Codex home.
    private var isLiveCodexIntegration: Bool { liveProvider == "codex" }

    /// Each provider runs the case's fixture, or nothing: without a fixture the
    /// provider reads as not installed, so no default case reaches a real CLI
    /// that happens to be on the machine. Live cases keep the real CLIs.
    private var providerExecutableEnvironment: [String: String] {
        var environment: [String: String] = [:]
        if let codexFixtureExecutable { environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = codexFixtureExecutable }
        else if !isLiveIntegration { environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = "none" }
        if let claudeFixtureExecutable { environment["PLAYHOUSE_E2E_CLAUDE_EXECUTABLE"] = claudeFixtureExecutable }
        else if !isLiveIntegration { environment["PLAYHOUSE_E2E_CLAUDE_EXECUTABLE"] = "none" }
        return environment
    }

    /// Points a live case's task at the selected real provider.
    private func useLiveProvider(taskID: String) throws {
        guard let liveProvider else { return }
        let switched = try XCTUnwrap(try runCLI(["conversation", "provider", taskID, "set", liveProvider])["result"] as? [String: Any])
        XCTAssertEqual(switched["conversationProvider"] as? String, liveProvider)
    }

    // case-contract: test_plugin_catalog_showcases_cover_every_component | The Plugins menu opens the Component Catalog, whose sidebar lists every bundled showcase section; each section page renders all of its showcases live through the real renderer with no unknown-component or error placeholders and lists its components' props reference. The progress-bar showcase's bar itself advances to 100% when Start is clicked, both in the Catalog and through playhouse-plugin-dev with no app running, where `tap` returns after the async action settles and `state` shows pct 100; the stage's Reset restarts it from initialState, Show Source shows its view.json and logic.js, and Show Node IDs overlays each element's number, matching the runner's numbering. Typing into the text-field showcase sends each edit's value to its action and shows it, removing the first row of the list showcase leaves the others in place with their element numbers, and an if shows its content only while its condition holds. `plugin components` lists every section and component spec with typed props and events and rejects an unknown component, and `plugin check-showcases` passes for the bundled showcases while a copy with a component used by no showcase, an empty section, an event-bearing component left without an interactive showcase, or an unknown component fails with issues naming them. `plugin components` also reports each event's value kind and which components are presentation components, and the catalog covers the app's atomic components: labels, badges, chips, status dots, images and avatars, icon buttons, copy buttons, fields, toggles, segmented controls, pickers, sliders, date pickers, cards, hints, empty states, scroll, menus, popovers, sheets, alerts and confirm dialogs.
    func test_plugin_catalog_showcases_cover_every_component() throws {
        // The sweep visits every catalog section and renders each showcase, which outlasts the default 3-minute allowance.
        executionTimeAllowance = 900
        launchApp(defaultParent: fixture.parent.path)
        clickPluginsMenuItem("Component Catalog…")
        XCTAssertTrue(element("catalog-sidebar").waitForExistence(timeout: 15), "Plugins ▸ Component Catalog… opens the Catalog window.")

        let catalog = try XCTUnwrap(try runCLI(["plugin", "components"])["result"] as? [String: Any])
        let catalogComponents = try XCTUnwrap(catalog["components"] as? [[String: Any]])
        let catalogTypes = Set(catalogComponents.compactMap { $0["type"] as? String })
        for type in ["label", "badge", "chip", "status-dot", "image", "avatar", "icon-button", "copy-button", "secure-field", "toggle", "segmented", "picker", "slider", "date-picker", "card", "hint", "empty-state", "scroll", "menu", "popover", "sheet", "alert", "confirm-dialog"] {
            XCTAssertTrue(catalogTypes.contains(type), "The catalog covers \(type).")
        }
        func changeKind(_ type: String) -> String? {
            let events = catalogComponents.first { $0["type"] as? String == type }?["events"] as? [[String: Any]]
            return events?.first { $0["name"] as? String == "onChange" }?["valueKind"] as? String
        }
        XCTAssertEqual([changeKind("toggle"), changeKind("slider"), changeKind("textfield")], ["bool", "number", "string"], "Events report the kind of value they carry.")
        let presentation = catalogComponents.filter { $0["presentation"] as? Bool == true }.compactMap { $0["type"] as? String }.sorted()
        XCTAssertEqual(presentation, ["alert", "confirm-dialog", "popover", "sheet"], "The presentation components are flagged.")

        let showcaseRoot = appBundle.appendingPathComponent("Contents/Resources/Showcase", isDirectory: true)
        let sections = try pluginSubdirectories(of: showcaseRoot)
        XCTAssertTrue(sections.contains("progress-status") && sections.contains("foundations"), "The app bundles the showcases: \(sections)")
        for section in sections {
            let row = element("catalog-section-\(section)")
            XCTAssertTrue(row.waitForExistence(timeout: 10), "The sidebar lists the \(section) section.")
            row.click()
            XCTAssertTrue(element("catalog-page-\(section)").waitForExistence(timeout: 10), "Selecting \(section) shows its page.")
            for showcase in try pluginSubdirectories(of: showcaseRoot.appendingPathComponent(section)) {
                let stage = element("catalog-stage-\(section)-\(showcase)")
                XCTAssertTrue(stage.waitForExistence(timeout: 10), "The \(section) page shows the \(showcase) showcase.")
                let rendered = stage.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH %@", "plugin-node-")).firstMatch
                XCTAssertTrue(rendered.waitForExistence(timeout: 10), "\(section)/\(showcase) renders live elements.")
            }
            // Scoped to the page: windows restored from an earlier launch may hold their own placeholders.
            let page = element("catalog-page-\(section)")
            XCTAssertFalse(page.descendants(matching: .any).matching(identifier: "plugin-unknown-component").firstMatch.exists, "Every component on the \(section) page has a renderer.")
            XCTAssertFalse(page.descendants(matching: .any).matching(identifier: "plugin-error").firstMatch.exists, "No showcase on the \(section) page fails to load or render.")
            attachScreenshot(named: "Component Catalog — \(section)")
        }

        element("catalog-section-text-input").click()
        let textStage = element("catalog-stage-text-input-01-textfield")
        XCTAssertTrue(textStage.waitForExistence(timeout: 10))
        let field = textStage.textFields.firstMatch
        XCTAssertTrue(field.waitForExistence(timeout: 10))
        typeIntoField(field, text: "hello")
        let echoed = textStage.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", "5 characters: \"hello\"", "5 characters: \"hello\"")).firstMatch
        XCTAssertTrue(echoed.waitForExistence(timeout: 10), "Typing sends each edit's value to the showcase's action.")
        textStage.buttons["Add"].click()
        XCTAssertTrue(textStage.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", "• hello", "• hello")).firstMatch.waitForExistence(timeout: 10))
        attachScreenshot(named: "Text field showcase after typing")

        element("catalog-section-structural").click()
        let listStage = element("catalog-stage-structural-02-list")
        XCTAssertTrue(listStage.waitForExistence(timeout: 10))
        func listText(_ value: String) -> XCUIElement {
            listStage.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        XCTAssertTrue(listText("First item").waitForExistence(timeout: 10))
        XCTAssertTrue(listText("row 1").exists, "Second item starts as row 1.")
        let secondID = listText("Second item").identifier
        XCTAssertTrue(secondID.hasPrefix("plugin-node-") && secondID.count > "plugin-node-".count, "Each row element carries its number: \(secondID)")
        listStage.buttons["Remove first"].click()
        XCTAssertTrue(listText("First item").waitForNonExistence(timeout: 10), "Removing the first row takes it out of the list.")
        XCTAssertTrue(listText("row 0").waitForExistence(timeout: 10), "The remaining row re-renders as row 0.")
        XCTAssertEqual(listText("Second item").identifier, secondID, "The remaining row keeps its element number.")
        let ifStage = element("catalog-stage-structural-01-if")
        func ifText(_ value: String) -> XCUIElement {
            ifStage.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        XCTAssertTrue(ifText("The details are hidden.").waitForExistence(timeout: 10))
        XCTAssertFalse(ifText("The details are visible.").exists, "An if leaves its content out while its condition is false.")
        ifStage.buttons["Show details"].click()
        XCTAssertTrue(ifText("The details are visible.").waitForExistence(timeout: 10), "An if shows its content once its condition holds.")
        XCTAssertTrue(ifText("The details are hidden.").waitForNonExistence(timeout: 10), "The negated if drops its content.")
        ifStage.buttons["Hide details"].click()
        XCTAssertTrue(ifText("The details are visible.").waitForNonExistence(timeout: 10), "Turning the condition off again removes the content.")
        XCTAssertTrue(ifText("The details are hidden.").waitForExistence(timeout: 10))
        attachScreenshot(named: "Structural showcases after interaction")

        element("catalog-section-progress-status").click()
        let stageID = "catalog-stage-progress-status-02-progress-simulate"
        let simulate = element(stageID)
        XCTAssertTrue(simulate.waitForExistence(timeout: 10))
        XCTAssertTrue(element("catalog-reference-progress-bar").exists, "The page lists the progress-bar props reference.")
        XCTAssertTrue(element("catalog-reference-spinner").exists, "The page lists the spinner props reference.")
        func stageText(_ value: String) -> XCUIElement {
            simulate.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        let bar = simulate.progressIndicators.firstMatch
        // The indicator reports its value as a number (0...100 here, or a 0...1 fraction) or as "N%".
        func barShows(_ percent: Double) -> Bool {
            guard bar.exists else { return false }
            if let text = bar.value as? String { return text == "\(Int(percent))%" || Double(text) == percent }
            guard let number = (bar.value as? NSNumber)?.doubleValue else { return false }
            return abs(number - percent) < 0.5 || abs(number - percent / 100) < 0.005
        }
        func waitForBar(_ value: String, timeout: TimeInterval) -> Bool {
            let percent = Double(value.dropLast()) ?? -1
            let deadline = Date().addingTimeInterval(timeout)
            while Date() < deadline {
                if barShows(percent) { return true }
                usleep(100_000)
            }
            return false
        }
        XCTAssertTrue(stageText("0% ready").waitForExistence(timeout: 10), "The simulated upload starts at 0%.")
        XCTAssertTrue(waitForBar("0%", timeout: 5), "The progress bar renders its bound value: \(String(describing: bar.value))")
        let start = simulate.buttons["Start"]
        XCTAssertTrue(start.waitForExistence(timeout: 5))
        start.click()
        XCTAssertTrue(waitForBar("100%", timeout: 15), "Clicking Start advances the progress bar itself to 100%: \(String(describing: bar.value))")
        XCTAssertTrue(stageText("100% done").exists)
        attachScreenshot(named: "Progress showcase after Start")

        element("\(stageID)-reset").click()
        XCTAssertTrue(stageText("0% ready").waitForExistence(timeout: 10), "The stage's Reset reloads the showcase from initialState.")
        XCTAssertTrue(waitForBar("0%", timeout: 5), "Reset returns the progress bar to 0%.")

        element("\(stageID)-source").click()
        let source = simulate.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", "\"action\": \"start\"", "\"action\": \"start\"")).firstMatch
        XCTAssertTrue(source.waitForExistence(timeout: 5), "Show Source shows the showcase's view.json.")
        let logic = simulate.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", "async start(state)", "async start(state)")).firstMatch
        XCTAssertTrue(logic.exists, "Show Source shows the showcase's logic.js.")
        attachScreenshot(named: "Progress showcase source")

        let badges = simulate.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH %@", "plugin-node-badge-"))
        XCTAssertEqual(badges.count, 0, "Element numbers are hidden until asked for.")
        element("\(stageID)-node-ids").click()
        let badge = badges.firstMatch
        XCTAssertTrue(badge.waitForExistence(timeout: 5), "Show Node IDs overlays each element's number.")
        let number = String(badge.identifier.dropFirst("plugin-node-badge-".count))
        XCTAssertEqual(badge.label.isEmpty ? (badge.value as? String ?? "") : badge.label, number, "Each badge shows the element's number, as playhouse-plugin-dev prints it.")
        XCTAssertTrue(simulate.descendants(matching: .any).matching(identifier: "plugin-node-\(number)").firstMatch.exists)
        attachScreenshot(named: "Progress showcase with node IDs")
    }

    // case-contract: test_plugin_controls_report_typed_values_and_present_overlays | The app's atomic components are available to plugins in the Component Catalog. The Notifications switch reports false and the checkbox true, each shown in the showcase text; choosing Board in the segmented control and High in the picker shows layout = board and priority = high; the stepped slider moves to its last step and shows effort = 4. The Sort menu opens with its items and choosing Date shows Sorted by date; a right-click on the context-menu card offers Delete and reports it. The popover opens from its anchor with its content and closes on Got it; the sheet opens with a name field, saves the typed name and closes; the delete confirmation is cancelled (Result: Cancelled), then confirmed (Result: Deleted), and the alert is dismissed. The icon and copy buttons report their press (Last pressed: edit, Copied 1 times); the secure field, search field and text editor report what is typed (secret length 3, the query, the note's characters); removing a chip drops it (2 tags, then 1 tags); the date pickers show their ISO dates and a runner `type` sets one; a scroll region's last row starts outside its frame and scrolls into it; and the display components show their content (labels, badges, chips, avatars, cards, hints, empty states, status labels and an image's description). Through playhouse-plugin-dev the same showcases refuse bad values: a toggle takes only true or false, a slider only a number, a segmented control or picker only one of its options, and an event a component doesn't have is refused; a closed confirm dialog, alert, popover or sheet can't be answered and has no content in the tree until it is opened, after which onCancel and onConfirm run their actions. `plugin validate` reports an image whose file is missing or outside the plugin folder, an icon without name or src, an alert without open, a menu with a non-menu child and a menu-item outside a menu, each with its file and JSON path.
    func test_plugin_controls_report_typed_values_and_present_overlays() throws {
        launchApp(defaultParent: fixture.parent.path)
        clickPluginsMenuItem("Component Catalog…")
        XCTAssertTrue(element("catalog-sidebar").waitForExistence(timeout: 15), "Plugins ▸ Component Catalog… opens the Catalog window.")

        func stage(_ section: String, _ showcase: String) -> XCUIElement {
            element("catalog-section-\(section)").click()
            let stage = element("catalog-stage-\(section)-\(showcase)")
            XCTAssertTrue(stage.waitForExistence(timeout: 10), "The \(section) page shows \(showcase).")
            return stage
        }
        func text(_ stage: XCUIElement, _ value: String) -> XCUIElement {
            stage.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        /// A control matched by its label, whichever accessibility type SwiftUI gives it.
        func control(_ stage: XCUIElement, _ label: String) -> XCUIElement {
            let match = stage.descendants(matching: .any).matching(NSPredicate(format: "label == %@", label)).firstMatch
            XCTAssertTrue(match.waitForExistence(timeout: 10), "The showcase has a control labelled \(label).")
            return match
        }

        // Selection controls report typed values.
        let toggles = stage("selection", "01-toggles")
        XCTAssertTrue(text(toggles, "notify = true, autosave = false").waitForExistence(timeout: 10))
        // A switch exposes no label of its own (its title is a separate static text), so it is found by type.
        let notifySwitch = toggles.switches.firstMatch
        XCTAssertTrue(notifySwitch.waitForExistence(timeout: 10), "The showcase has the Notifications switch.")
        notifySwitch.click()
        XCTAssertTrue(text(toggles, "notify = false, autosave = false").waitForExistence(timeout: 10), "The switch reports false.")
        control(toggles, "Save drafts automatically").click()
        XCTAssertTrue(text(toggles, "notify = false, autosave = true").waitForExistence(timeout: 10), "The checkbox reports true.")
        attachScreenshot(named: "Toggles after switching")

        let choices = stage("selection", "02-segmented-and-picker")
        XCTAssertTrue(text(choices, "layout = list, size = M, priority = normal").waitForExistence(timeout: 10))
        control(choices, "Board").click()
        XCTAssertTrue(text(choices, "layout = board, size = M, priority = normal").waitForExistence(timeout: 10), "Choosing a segment reports its value.")
        let picker = choices.popUpButtons.firstMatch
        XCTAssertTrue(picker.waitForExistence(timeout: 10), "The picker is a pop-up button.")
        picker.click()
        let high = app.menuItems["High"]
        XCTAssertTrue(high.waitForExistence(timeout: 5), "The picker lists its options.")
        attachScreenshot(named: "Picker open", fullScreen: true)
        high.click()
        XCTAssertTrue(text(choices, "layout = board, size = M, priority = high").waitForExistence(timeout: 10), "Choosing an option reports its value.")
        attachScreenshot(named: "Segmented control and picker after choosing")

        let sliders = stage("selection", "03-slider")
        XCTAssertTrue(text(sliders, "volume = 40, effort = 2").waitForExistence(timeout: 10))
        let effort = sliders.sliders.element(boundBy: 1)
        XCTAssertTrue(effort.waitForExistence(timeout: 10), "The stepped slider is exposed as a slider.")
        // The stepped track snaps to the nearest step wherever it is pressed, and its accessibility slider has no orientation to adjust.
        effort.coordinate(withNormalizedOffset: CGVector(dx: 0.98, dy: 0.5)).click()
        XCTAssertTrue(text(sliders, "volume = 40, effort = 4").waitForExistence(timeout: 10), "Moving the stepped slider to its end reports its last step.")
        attachScreenshot(named: "Sliders after adjusting")

        // Menus.
        let menus = stage("overlays", "01-menus")
        XCTAssertTrue(text(menus, "Last action: none").waitForExistence(timeout: 10))
        control(menus, "Sort").click()
        let date = app.menuItems["Date"]
        XCTAssertTrue(date.waitForExistence(timeout: 5), "The Sort menu lists its items.")
        XCTAssertTrue(app.menuItems["Delete all"].exists && app.menuItems["Reverse order"].exists)
        attachScreenshot(named: "Sort menu open", fullScreen: true)
        date.click()
        XCTAssertTrue(text(menus, "Last action: Sorted by date").waitForExistence(timeout: 10), "Choosing a menu item runs its action.")

        let context = stage("overlays", "02-context-menu")
        let card = text(context, "Right-click this card")
        XCTAssertTrue(card.waitForExistence(timeout: 10))
        card.rightClick()
        // The Edit menu in the menu bar also has a Delete item; only the context menu's is on screen.
        let deleteItems = app.menuItems.matching(identifier: "Delete")
        XCTAssertTrue(deleteItems.firstMatch.waitForExistence(timeout: 5), "A right-click opens the context menu.")
        let delete = try XCTUnwrap(deleteItems.allElementsBoundByIndex.first { $0.isHittable }, "The context menu offers Delete.")
        attachScreenshot(named: "Context menu open", fullScreen: true)
        delete.click()
        XCTAssertTrue(text(context, "Chosen: Delete").waitForExistence(timeout: 10), "Choosing a context menu item runs its action.")

        // Overlays open and close from plugin state.
        let popover = stage("overlays", "03-popover")
        XCTAssertTrue(text(popover, "Popover is false").waitForExistence(timeout: 10))
        popover.buttons["Show details"].click()
        let popoverContent = app.popovers.firstMatch
        XCTAssertTrue(popoverContent.waitForExistence(timeout: 10), "The popover opens from its anchor.")
        XCTAssertTrue(popoverContent.staticTexts["Popovers close when you click away."].exists, "The popover shows its content.")
        XCTAssertTrue(text(popover, "Popover is true").exists)
        attachScreenshot(named: "Popover open")
        popoverContent.buttons["Got it"].click()
        XCTAssertTrue(popoverContent.waitForNonExistence(timeout: 10), "Got it closes the popover.")
        XCTAssertTrue(text(popover, "Popover is false").waitForExistence(timeout: 10))

        let sheetStage = stage("overlays", "04-sheet")
        XCTAssertTrue(text(sheetStage, "Name: Untitled").waitForExistence(timeout: 10))
        sheetStage.buttons["Rename project…"].click()
        let sheet = app.sheets.firstMatch
        XCTAssertTrue(sheet.waitForExistence(timeout: 10), "The sheet opens over the window.")
        let nameField = sheet.textFields.firstMatch
        XCTAssertTrue(nameField.waitForExistence(timeout: 5))
        nameField.click()
        // Each keystroke round-trips through the plugin's state, so a fast burst can lose a character under load; retype until the field holds the whole name.
        for _ in 0..<3 {
            nameField.typeKey("a", modifierFlags: .command)
            nameField.typeText("Roadmap")
            if waitUntil({ nameField.value as? String == "Roadmap" }, timeout: 2) { break }
        }
        XCTAssertEqual(nameField.value as? String, "Roadmap", "The sheet's field holds the typed name.")
        attachScreenshot(named: "Sheet open")
        sheet.buttons["Save"].click()
        XCTAssertTrue(sheet.waitForNonExistence(timeout: 10), "Save closes the sheet.")
        XCTAssertTrue(text(sheetStage, "Name: Roadmap").waitForExistence(timeout: 10), "The sheet saved the typed name.")

        let dialogs = stage("overlays", "05-dialogs")
        XCTAssertTrue(text(dialogs, "Result: nothing yet").waitForExistence(timeout: 10))
        dialogs.buttons["Delete project…"].click()
        let question = app.staticTexts["Delete this project?"]
        XCTAssertTrue(question.waitForExistence(timeout: 10), "The confirmation asks its question.")
        // The Touch Bar also lists a Cancel button, so the dialog's buttons are taken from its sheet.
        attachScreenshot(named: "Confirmation open")
        app.sheets.firstMatch.buttons["Cancel"].click()
        XCTAssertTrue(text(dialogs, "Result: Cancelled").waitForExistence(timeout: 10), "Cancel reports the cancellation only.")
        dialogs.buttons["Delete project…"].click()
        XCTAssertTrue(question.waitForExistence(timeout: 10))
        app.sheets.firstMatch.buttons["Delete"].click()
        XCTAssertTrue(text(dialogs, "Result: Deleted").waitForExistence(timeout: 10), "Confirm runs the confirmation action.")
        dialogs.buttons["Show alert"].click()
        let alertTitle = app.staticTexts["Heads up"]
        XCTAssertTrue(alertTitle.waitForExistence(timeout: 10), "The alert shows its title.")
        attachScreenshot(named: "Alert open")
        app.sheets.firstMatch.buttons["OK"].click()
        XCTAssertTrue(text(dialogs, "Result: Alert dismissed").waitForExistence(timeout: 10), "Dismissing the alert runs its action.")

        // Buttons and fields report what the user does.
        let iconButtons = stage("buttons", "03-icon-buttons")
        XCTAssertTrue(text(iconButtons, "Last pressed: nothing yet").waitForExistence(timeout: 10))
        control(iconButtons, "Edit").click()
        XCTAssertTrue(text(iconButtons, "Last pressed: edit").waitForExistence(timeout: 10), "An icon button reports its press.")
        attachScreenshot(named: "Icon buttons after a press")
        let copyStage = stage("buttons", "04-copy-button")
        XCTAssertTrue(text(copyStage, "Copied 0 times").waitForExistence(timeout: 10))
        control(copyStage, "Copy all").click()
        XCTAssertTrue(text(copyStage, "Copied 1 times").waitForExistence(timeout: 10), "A copy button reports the copy.")

        let fieldStage = stage("text-input", "02-fields")
        let secure = fieldStage.secureTextFields.firstMatch
        typeIntoField(secure, text: "abc")
        func caption(_ stage: XCUIElement, containing part: String) -> XCUIElement {
            stage.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", part, part)).firstMatch
        }
        XCTAssertTrue(caption(fieldStage, containing: "secret length 3").waitForExistence(timeout: 10), "The secure field reports what is typed.")
        typeIntoField(fieldStage.textFields["Search tasks"], text: "plugin")
        XCTAssertTrue(caption(fieldStage, containing: "query: “plugin”").waitForExistence(timeout: 10), "The search field reports its query.")
        typeIntoField(fieldStage.textViews.firstMatch, text: "hello")
        XCTAssertTrue(caption(fieldStage, containing: "5 note characters").waitForExistence(timeout: 10), "The text editor reports its text.")
        attachScreenshot(named: "Fields after typing")

        let chipStage = stage("data", "02-chips")
        XCTAssertTrue(text(chipStage, "2 tags").waitForExistence(timeout: 10))
        control(chipStage, "Remove swift").click()
        XCTAssertTrue(text(chipStage, "1 tags").waitForExistence(timeout: 10), "Removing a chip drops it.")
        attachScreenshot(named: "Chips after removing one")

        let dateStage = stage("pickers", "01-date-picker")
        XCTAssertTrue(text(dateStage, "day = 2026-11-07T09:30:00Z").waitForExistence(timeout: 10), "The date picker shows its ISO date.")
        XCTAssertTrue(dateStage.datePickers.firstMatch.waitForExistence(timeout: 10), "The date picker is drawn.")

        let scrollStage = stage("layout", "04-scroll")
        let region = scrollStage.scrollViews.firstMatch
        XCTAssertTrue(region.waitForExistence(timeout: 10), "The scroll component draws a scroll region.")
        let lastRow = text(scrollStage, "Row 12")
        XCTAssertTrue(lastRow.waitForExistence(timeout: 10))
        XCTAssertGreaterThan(lastRow.frame.minY, region.frame.maxY, "The last row starts below the scroll region.")
        // The region can sit below the window's fold; scroll the page until it can be reached.
        for _ in 0..<5 where !region.isHittable {
            element("catalog-page-layout").scroll(byDeltaX: 0, deltaY: -300)
        }
        XCTAssertTrue(region.isHittable, "The scroll region is on screen.")
        region.scroll(byDeltaX: 0, deltaY: -400)
        XCTAssertTrue(waitUntil({ lastRow.frame.maxY <= region.frame.maxY + 1 }, timeout: 5), "Scrolling brings the last row into the region.")
        attachScreenshot(named: "Scroll after scrolling down")

        // Display components show their content.
        let display: [(String, String, [String])] = [
            ("typography", "03-labels-code-kbd", ["Pull request merged", "scripts/test-e2e.sh"]),
            ("data", "01-badges", ["Ready", "success"]),
            ("data", "03-cards", ["Panel", "Reviewing 3 pull requests"]),
            ("feedback", "01-empty-states", ["No tasks yet", "Create a task to get started."]),
            ("feedback", "02-hints", ["Add comment", "Merge conflict"]),
            ("progress-status", "04-status-dots", ["In progress", "Blocked"]),
        ]
        for (section, showcase, texts) in display {
            let target = stage(section, showcase)
            for value in texts {
                // Combined elements (an empty state's icon, title and message) carry all their text in one label.
                let shown = target.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", value, value)).firstMatch
                XCTAssertTrue(shown.waitForExistence(timeout: 10), "\(section)/\(showcase) shows \(value).")
            }
        }
        let media = stage("media", "02-images-avatars")
        XCTAssertTrue(control(media, "Logo").exists, "The image carries its description.")
        XCTAssertTrue(control(media, "Ada Lovelace").exists, "The avatar carries its name.")
        attachScreenshot(named: "Images and avatars")

        // Through playhouse-plugin-dev the same showcases refuse bad values and closed overlays.
        let bundledShowcases = appBundle.appendingPathComponent("Contents/Resources/Showcase", isDirectory: true)
        func runner(_ section: String, _ showcase: String, _ commands: [String]) throws -> [[String: Any]] {
            try runPluginRunner(bundledShowcases.appendingPathComponent("\(section)/\(showcase)"), commands)
        }
        func error(_ reply: [String: Any]) -> String { reply["error"] as? String ?? "" }
        let toggleView = try XCTUnwrap(try runner("selection", "01-toggles", ["view"]).first)
        let switchID = try runnerNodeID(runnerNodes(toggleView), type: "toggle", props: ["label": "Notifications"])
        let toggleReplies = try runner("selection", "01-toggles", ["type \(switchID) false", "state", "type \(switchID) maybe", "fire \(switchID) onChange 5", "fire \(switchID) onTap"])
        XCTAssertEqual(toggleReplies[0]["ok"] as? Bool, true, "A toggle accepts false.")
        XCTAssertEqual(((toggleReplies[1]["state"] as? [String: Any])?["notify"] as? Bool), false, "A toggle reports a real boolean.")
        XCTAssertTrue(error(toggleReplies[2]).contains("true or false"), "A toggle refuses other text.")
        XCTAssertTrue(error(toggleReplies[3]).contains("expected true or false"), "A toggle refuses a number.")
        XCTAssertTrue(error(toggleReplies[4]).contains("has no onTap action"), "An event the component doesn't have is refused.")

        let sliderView = try XCTUnwrap(try runner("selection", "03-slider", ["view"]).first)
        let effortID = try runnerNodeID(runnerNodes(sliderView), type: "slider", props: ["label": "Effort"])
        let sliderReplies = try runner("selection", "03-slider", ["type \(effortID) 3", "state", "type \(effortID) lots"])
        XCTAssertEqual((sliderReplies[1]["state"] as? [String: Any])?["effort"] as? Int, 3, "A slider reports a number.")
        XCTAssertTrue(error(sliderReplies[2]).contains("takes a number"), "A slider refuses text.")

        let choiceView = try XCTUnwrap(try runner("selection", "02-segmented-and-picker", ["view"]).first)
        let pickerID = try runnerNodeID(runnerNodes(choiceView), type: "picker")
        let choiceReplies = try runner("selection", "02-segmented-and-picker", ["type \(pickerID) high", "state", "type \(pickerID) urgent"])
        XCTAssertEqual((choiceReplies[1]["state"] as? [String: Any])?["priority"] as? String, "high")
        XCTAssertTrue(error(choiceReplies[2]).contains("isn't one of the options"), "A picker refuses a value outside its options.")

        let dialogView = try XCTUnwrap(try runner("overlays", "05-dialogs", ["view"]).first)
        let dialogNodes = runnerNodes(dialogView)
        let confirmID = try runnerNodeID(dialogNodes, type: "confirm-dialog")
        let deleteID = try runnerNodeID(dialogNodes, type: "button", props: ["title": "Delete project…"])
        let dialogReplies = try runner("overlays", "05-dialogs", ["fire \(confirmID) onConfirm", "tap \(deleteID)", "fire \(confirmID) onCancel", "state"])
        XCTAssertTrue(error(dialogReplies[0]).contains("is closed"), "A closed confirmation can't be answered.")
        XCTAssertEqual(dialogReplies[2]["ok"] as? Bool, true, "An open confirmation can be cancelled.")
        XCTAssertEqual((dialogReplies[3]["state"] as? [String: Any])?["result"] as? String, "Cancelled")
        let dateView = try XCTUnwrap(try runner("pickers", "01-date-picker", ["view"]).first)
        let dateID = try runnerNodeID(runnerNodes(dateView), type: "date-picker", props: ["label": "Date"])
        let dateReplies = try runner("pickers", "01-date-picker", ["type \(dateID) 2026-12-01T08:00:00Z", "state"])
        XCTAssertEqual((dateReplies[1]["state"] as? [String: Any])?["day"] as? String, "2026-12-01T08:00:00Z", "A date picker reports an ISO date.")
        let sheetView = try XCTUnwrap(try runner("overlays", "04-sheet", ["view"]).first)
        XCTAssertEqual(runnerNodes(sheetView).filter { $0["type"] as? String == "heading" }.count, 0, "A closed sheet has no content in the tree.")

        // Validation rejects misuse of the new components.
        let bad = dataDirectory.appendingPathComponent("Plugins/bad-components", isDirectory: true)
        try FileManager.default.createDirectory(at: bad, withIntermediateDirectories: true)
        try #"{"id": "bad-components", "name": "Bad components", "version": "1.0.0", "contributes": {"views": [{"id": "main", "title": "Bad"}]}}"#
            .write(to: bad.appendingPathComponent("plugin.json"), atomically: true, encoding: .utf8)
        try #"{"main": {"type": "vstack", "children": [{"type": "image", "props": {"src": "missing.png"}}, {"type": "image", "props": {"src": "../escape.png"}}, {"type": "icon", "props": {}}, {"type": "alert", "props": {"title": "Hi"}}, {"type": "menu", "children": [{"type": "text", "props": {"text": "Not an entry"}}]}, {"type": "menu-item", "props": {"title": "Stray"}}, {"type": "popover", "props": {"open": false}, "children": [{"type": "text", "props": {"text": "Anchor only"}}]}]}}"#
            .write(to: bad.appendingPathComponent("view.json"), atomically: true, encoding: .utf8)
        let report = try XCTUnwrap(try runCLI(["plugin", "validate", "--path", bad.path], expectedStatus: 1)["result"] as? [String: Any])
        let issues = try XCTUnwrap(report["issues"] as? [[String: Any]])
        func issue(_ path: String) -> String {
            issues.first { $0["path"] as? String == path }?["message"] as? String ?? ""
        }
        XCTAssertTrue(issue("main.children[0].props.src").contains("no file \"missing.png\""), "A missing image file is reported.")
        XCTAssertTrue(issue("main.children[1].props.src").contains("inside the plugin folder"), "An image path outside the folder is reported.")
        XCTAssertTrue(issue("main.children[2].props").contains("needs one of the props name, src"), "An icon without a name or src is reported.")
        XCTAssertTrue(issue("main.children[3].props").contains("needs the prop \"open\""), "An alert without open is reported.")
        XCTAssertTrue(issue("main.children[4].children[0].type").contains("only takes menu-item and divider"), "A menu with a non-menu child is reported.")
        XCTAssertTrue(issue("main.children[5].type").contains("belongs directly inside menu or context-menu"), "A menu-item outside a menu is reported.")
        XCTAssertTrue(issue("main.children[6].children").contains("needs at least 2 children"), "A popover without content is reported.")
    }

    // case-contract: test_plugin_installed_plugin_loads_validates_and_runs | A plugin folder in the data directory's Plugins folder appears in the Plugins menu with one Open item per view, and each view opens in its own window; clicking its button runs the logic.js action and updates the bound text, an action's api.call reaches the real daemon and shows its result while a call to an unknown command rejects with the daemon's error, the plugin's Reload item restarts the open window from initialState, and editing view.json reloads it. A plugin with problems shows its first problem in its submenu; the menu and `plugin list` validate through the same manager. `plugin new` scaffolds a valid plugin there and refuses an existing id, `plugin list` reports each installed plugin with its views and validation issues, and `plugin validate` reports unknown components, missing actions and reserved button contributions with their file and JSON path and exits non-zero. A showcase scaffold needs a showcase root and lands in its section as NN-<id> with a section.json. Through playhouse-plugin-dev the same plugin's button updates state, its api.call actions resolve and reject the same way and appear in its log, a disabled button refuses taps, and editing view.json reloads it.
    func test_plugin_installed_plugin_loads_validates_and_runs() throws {
        let created = try XCTUnwrap(try runCLI(["plugin", "new", "--id", "hello-world"])["result"] as? [String: Any])
        XCTAssertEqual(created["valid"] as? Bool, true)
        let hello = URL(fileURLWithPath: try XCTUnwrap(created["directory"] as? String), isDirectory: true)
        try #"{"id": "hello-world", "name": "Hello World", "version": "0.1.0", "contributes": {"views": [{"id": "main", "title": "Hello World"}, {"id": "details", "title": "Details"}]}}"#
            .write(to: hello.appendingPathComponent("plugin.json"), atomically: true, encoding: .utf8)
        try #"{"main": {"type": "vstack", "props": {"spacing": 12, "padding": 16}, "children": [{"type": "heading", "props": {"text": "Hello World"}}, {"type": "text", "props": {"text": "Clicked {{count}} times"}}, {"type": "button", "props": {"title": "Click me", "onTap": {"action": "increment"}}}, {"type": "button", "props": {"title": "Check daemon", "onTap": {"action": "checkDaemon"}}}, {"type": "button", "props": {"title": "Call missing", "onTap": {"action": "callMissing"}}}, {"type": "text", "props": {"text": "Daemon: {{daemon}}"}}, {"type": "text", "props": {"text": "API error: {{apiError}}"}}]}, "details": {"type": "text", "props": {"text": "Details view: {{count}}"}}}"#
            .write(to: hello.appendingPathComponent("view.json"), atomically: true, encoding: .utf8)
        try Self.helloPluginLogic.write(to: hello.appendingPathComponent("logic.js"), atomically: true, encoding: .utf8)
        let broken = dataDirectory.appendingPathComponent("Plugins/broken", isDirectory: true)
        try FileManager.default.createDirectory(at: broken, withIntermediateDirectories: true)
        try #"{"id": "broken", "name": "Broken", "version": "1.0.0", "contributes": {"views": [{"id": "main", "title": "Broken"}], "buttons": [{"id": "x"}]}}"#
            .write(to: broken.appendingPathComponent("plugin.json"), atomically: true, encoding: .utf8)
        try #"{"main": {"type": "vstack", "children": [{"type": "fancy-widget"}]}}"#
            .write(to: broken.appendingPathComponent("view.json"), atomically: true, encoding: .utf8)
        let listed = try XCTUnwrap((try runCLI(["plugin", "list"])["result"] as? [String: Any])?["plugins"] as? [[String: Any]])
        XCTAssertEqual(listed.compactMap { $0["id"] as? String }.sorted(), ["broken", "hello-world"])

        launchApp(defaultParent: fixture.parent.path)
        let brokenMenu = openPluginsSubmenu("Broken")
        let problem = brokenMenu.menuItems.matching(NSPredicate(format: "title CONTAINS %@", "reserved")).firstMatch
        XCTAssertTrue(problem.waitForExistence(timeout: 5), "A plugin with problems shows its first problem in its submenu.")
        XCTAssertFalse(problem.isEnabled)
        attachScreenshot(named: "Plugins menu with a plugin problem", fullScreen: true)
        // Close the menu with the pointer; typed keys don't reach an open menu here.
        app.menuBars.menuBarItems["Plugins"].click()

        let helloMenu = openPluginsSubmenu("Hello World")
        XCTAssertTrue(helloMenu.menuItems["Open \"Hello World\""].waitForExistence(timeout: 5), "Each plugin view has an Open item.")
        XCTAssertTrue(helloMenu.menuItems["Open \"Details\""].exists, "The second view has its own Open item.")
        attachScreenshot(named: "Plugins menu for an installed plugin", fullScreen: true)
        clickMenuItem(helloMenu.menuItems["Open \"Hello World\""], in: helloMenu)
        let window = element("plugin-window-hello-world-main")
        XCTAssertTrue(window.waitForExistence(timeout: 15), "Open shows the plugin's view in its own window.")
        func text(_ value: String) -> XCUIElement {
            window.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        XCTAssertTrue(text("Clicked 0 times").waitForExistence(timeout: 10))
        let button = window.buttons["Click me"]
        XCTAssertTrue(button.waitForExistence(timeout: 5))
        button.click()
        XCTAssertTrue(text("Clicked 1 times").waitForExistence(timeout: 10), "Clicking the button runs the logic.js action and updates the bound text.")
        attachScreenshot(named: "Installed plugin after a click")

        window.buttons["Check daemon"].click()
        XCTAssertTrue(text("Daemon: bridge v1").waitForExistence(timeout: 15), "An action's api.call reaches the real daemon and shows its result.")
        window.buttons["Call missing"].click()
        let rejected = window.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", "Unknown command 'no.such.command'", "Unknown command 'no.such.command'")).firstMatch
        XCTAssertTrue(rejected.waitForExistence(timeout: 15), "A call to an unknown command rejects with the daemon's error.")
        attachScreenshot(named: "Installed plugin api.call results")

        choosePluginsSubmenuItem("Hello World", "Reload")
        XCTAssertTrue(text("Clicked 0 times").waitForExistence(timeout: 10), "The plugin's Reload item restarts its open window from initialState.")

        choosePluginsSubmenuItem("Hello World", "Open \"Details\"")
        let details = element("plugin-window-hello-world-details")
        XCTAssertTrue(details.waitForExistence(timeout: 15), "The second view opens in its own window.")
        XCTAssertTrue(details.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", "Details view: 0", "Details view: 0")).firstMatch.waitForExistence(timeout: 10))
        attachScreenshot(named: "Installed plugin second view")

        // Close Details (it covers the main view's button), then leave the count at 1 so
        // the edit's reload has state to reset.
        app.typeKey("w", modifierFlags: .command)
        XCTAssertTrue(details.waitForNonExistence(timeout: 10))
        button.click()
        XCTAssertTrue(text("Clicked 1 times").waitForExistence(timeout: 10))
        try #"{"main": {"type": "vstack", "props": {"spacing": 12, "padding": 16}, "children": [{"type": "heading", "props": {"text": "Edited live"}}, {"type": "text", "props": {"text": "Clicked {{count}} times"}}]}, "details": {"type": "text", "props": {"text": "Details view: {{count}}"}}}"#
            .write(to: hello.appendingPathComponent("view.json"), atomically: true, encoding: .utf8)
        // The edited view's heading carries the header trait, so match any element type.
        let editedHeading = window.descendants(matching: .any).matching(NSPredicate(format: "label == %@ OR value == %@", "Edited live", "Edited live")).firstMatch
        XCTAssertTrue(editedHeading.waitForExistence(timeout: 20), "Editing view.json reloads the open plugin window.")
        XCTAssertTrue(text("Clicked 0 times").waitForExistence(timeout: 10), "A reload starts again from initialState.")
        XCTAssertFalse(text("Clicked 1 times").exists)
        attachScreenshot(named: "Installed plugin after editing view.json")
    }

    // case-contract: test_plugin_failures_show_errors_and_recover | A plugin action that throws reports its error: playhouse-plugin-dev's tap fails with it and logs the exception, and the plugin window shows it inline until an action succeeds, with the plugin still usable. An action that runs for about 10 seconds without yielding marks the plugin hung: the runner emits a hung event and refuses later taps, the window shows the hang, and reloading starts a fresh working copy. A logic.js that fails to load shows its error in the window and in the runner's loaded event, `plugin validate` reports it, and a logic.js whose top level never finishes is reported after 5 seconds by a short-lived check process that is killed, leaving the daemon responsive.
    func test_plugin_failures_show_errors_and_recover() throws {
        func install(_ id: String, _ name: String, view: String, logic: String) throws {
            let directory = dataDirectory.appendingPathComponent("Plugins/\(id)", isDirectory: true)
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try #"{"id": "\#(id)", "name": "\#(name)", "version": "1.0.0", "contributes": {"views": [{"id": "main", "title": "\#(name)"}]}}"#
                .write(to: directory.appendingPathComponent("plugin.json"), atomically: true, encoding: .utf8)
            try view.write(to: directory.appendingPathComponent("view.json"), atomically: true, encoding: .utf8)
            try logic.write(to: directory.appendingPathComponent("logic.js"), atomically: true, encoding: .utf8)
        }
        try install("fragile", "Fragile", view: Self.fragilePluginView, logic: Self.fragilePluginLogic)
        try install("unparsable", "Unparsable", view: #"{"main": {"type": "text", "props": {"text": "Never shown"}}}"#, logic: "export const actions = {\n")

        launchApp(defaultParent: fixture.parent.path)
        choosePluginsSubmenuItem("Fragile", "Open \"Fragile\"")
        let window = element("plugin-window-fragile-main")
        XCTAssertTrue(window.waitForExistence(timeout: 15))
        func text(_ value: String) -> XCUIElement {
            window.staticTexts.matching(NSPredicate(format: "label == %@ OR value == %@", value, value)).firstMatch
        }
        XCTAssertTrue(text("Ready 0").waitForExistence(timeout: 10))

        window.buttons["Explode"].click()
        let actionError = window.descendants(matching: .any).matching(identifier: "plugin-action-error").firstMatch
        XCTAssertTrue(actionError.waitForExistence(timeout: 10), "A throwing action shows its error inline.")
        XCTAssertTrue(accessibilityText(actionError).contains("Kaboom"), accessibilityText(actionError))
        attachScreenshot(named: "Plugin action error")
        window.buttons["Increment"].click()
        XCTAssertTrue(text("Ready 1").waitForExistence(timeout: 10), "The plugin stays usable after a failed action.")
        XCTAssertTrue(actionError.waitForNonExistence(timeout: 10), "The inline error clears once an action succeeds.")

        window.buttons["Spin"].click()
        let hung = window.descendants(matching: .any).matching(identifier: "plugin-error").firstMatch
        XCTAssertTrue(hung.waitForExistence(timeout: 30), "An action that never yields marks the plugin hung.")
        XCTAssertTrue(accessibilityText(hung).contains("hung"), accessibilityText(hung))
        attachScreenshot(named: "Hung plugin")
        choosePluginsSubmenuItem("Fragile", "Reload")
        XCTAssertTrue(hung.waitForNonExistence(timeout: 15), "Reloading starts a fresh copy.")
        XCTAssertTrue(text("Ready 0").waitForExistence(timeout: 10))
        window.buttons["Increment"].click()
        XCTAssertTrue(text("Ready 1").waitForExistence(timeout: 10), "The reloaded copy works.")

        choosePluginsSubmenuItem("Unparsable", "Open \"Unparsable\"")
        let broken = element("plugin-window-unparsable-main")
        XCTAssertTrue(broken.waitForExistence(timeout: 15))
        let loadError = broken.descendants(matching: .any).matching(identifier: "plugin-error").firstMatch
        XCTAssertTrue(loadError.waitForExistence(timeout: 10), "A logic.js that fails to load shows its error.")
        XCTAssertTrue(accessibilityText(loadError).contains("logic.js failed to load"), accessibilityText(loadError))
        attachScreenshot(named: "Plugin load error")
    }

    private static let helloPluginLogic = """
    export const initialState = { count: 0, daemon: "unknown", apiError: "none" };

    export const actions = {
      increment(state) {
        state.count += 1;
      },
      async checkDaemon(state, payload, api) {
        const status = await api.call("status");
        state.daemon = "bridge v" + status.bridgeVersion;
      },
      async callMissing(state, payload, api) {
        try {
          await api.call("no.such.command");
          state.apiError = "none";
        } catch (error) {
          state.apiError = error.message;
        }
      }
    };

    """

    private static let fragilePluginLogic = """
    export const initialState = { count: 0 };

    export const actions = {
      increment(state) {
        state.count += 1;
      },
      explode() {
        throw new Error("Kaboom");
      },
      spin() {
        while (true) {}
      }
    };

    """

    private static let fragilePluginView = #"{"main": {"type": "vstack", "props": {"spacing": 10, "padding": 16}, "children": [{"type": "text", "props": {"text": "Ready {{count}}"}}, {"type": "button", "props": {"title": "Increment", "onTap": {"action": "increment"}}}, {"type": "button", "props": {"title": "Explode", "onTap": {"action": "explode"}}}, {"type": "button", "props": {"title": "Spin", "onTap": {"action": "spin"}}}]}}"#

    private func clickPluginsMenuItem(_ title: String) {
        let menu = app.menuBars.menuBarItems["Plugins"]
        XCTAssertTrue(menu.waitForExistence(timeout: 10), "The app menu has a Plugins menu.")
        menu.click()
        let item = app.menuItems[title]
        XCTAssertTrue(item.waitForExistence(timeout: 5), "The Plugins menu has \(title).")
        item.click()
    }

    /// Opens Plugins ▸ <plugin> and returns that plugin's submenu entry. The pointer
    /// ends on the entry's trailing edge, where its submenu begins, so the next move
    /// into the submenu never crosses another plugin's entry (which would switch to
    /// that plugin's submenu).
    @discardableResult
    private func openPluginsSubmenu(_ title: String) -> XCUIElement {
        let menu = app.menuBars.menuBarItems["Plugins"]
        XCTAssertTrue(menu.waitForExistence(timeout: 10), "The app menu has a Plugins menu.")
        menu.click()
        let submenu = menu.menuItems[title]
        XCTAssertTrue(submenu.waitForExistence(timeout: 5), "The Plugins menu lists the installed plugin \(title).")
        submenu.click()
        submenu.coordinate(withNormalizedOffset: CGVector(dx: 0.97, dy: 0.5)).hover()
        return submenu
    }

    /// Chooses Plugins ▸ <plugin> ▸ <item>, matched by title within that plugin's submenu.
    private func choosePluginsSubmenuItem(_ plugin: String, _ item: String) {
        let submenu = openPluginsSubmenu(plugin)
        let entry = submenu.menuItems.matching(NSPredicate(format: "title == %@", item)).firstMatch
        XCTAssertTrue(entry.waitForExistence(timeout: 5), "Plugins ▸ \(plugin) has \(item).")
        clickMenuItem(entry, in: submenu)
    }

    /// Chooses a submenu item at its on-screen position. XCUITest re-resolves a clicked
    /// element by accessibility identifier, and SwiftUI gives every menu button the
    /// same one ("menuAction:"), so a plain `click()` can land on an off-screen item.
    /// The submenu entry it belongs to resolves correctly, so the click is placed
    /// relative to that entry.
    private func clickMenuItem(_ item: XCUIElement, in submenu: XCUIElement) {
        let deadline = Date().addingTimeInterval(5)
        while Date() < deadline, !item.isHittable { usleep(100_000) }
        XCTAssertTrue(item.isHittable, "\(item.title) is on screen.")
        let target = item.frame
        let anchor = submenu.frame
        XCTAssertTrue(target.minX.isFinite && target.minY.isFinite && anchor.minX.isFinite, "\(item.title) has a position.")
        let point = submenu.coordinate(withNormalizedOffset: .zero)
            .withOffset(CGVector(dx: target.midX - anchor.minX, dy: target.midY - anchor.minY))
        // Hovering highlights the item (the screen recording shows it), but a following
        // synthesized click re-reads its anchor and lands elsewhere. Return chooses the
        // highlighted menu item, exactly as it does for a user.
        // Return chooses whatever is highlighted when it arrives, so wait for the hover to
        // highlight this item; a fixed pause let a loaded run press Return too early.
        point.hover()
        if !waitUntil({ item.isSelected }, timeout: 2) {
            point.hover()
        }
        XCTAssertTrue(waitUntil({ item.isSelected }, timeout: 2), "Hovering should highlight \(item.title) before Return chooses it.")
        app.typeKey(.return, modifierFlags: [])
    }

    /// A placeholder's message: SwiftUI exposes it as the label or, for a combined text, as the value.
    private func accessibilityText(_ element: XCUIElement) -> String {
        element.label.isEmpty ? (element.value as? String ?? "") : element.label
    }

    private func pluginSubdirectories(of directory: URL) throws -> [String] {
        try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: [.isDirectoryKey], options: [.skipsHiddenFiles])
            .filter { (try? $0.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true }
            .map(\.lastPathComponent)
            .sorted()
    }

    private func launchApp(defaultParent: String?, environmentOverrides: [String: String] = [:]) {
        clearSavedWindowFrames()
        launchDefaultParent = defaultParent
        let bundleIdentifier = Bundle(url: appBundle)?.bundleIdentifier ?? "com.playhouse.app.e2e"
        app = XCUIApplication(bundleIdentifier: bundleIdentifier)
        app.launchEnvironment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        let usesLiveCodex = isLiveCodexIntegration
        let liveCodexHome = ProcessInfo.processInfo.environment["CODEX_HOME"] ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(".codex").path
        app.launchEnvironment["CODEX_HOME"] = usesLiveCodex ? liveCodexHome : dataDirectory.appendingPathComponent("codex-home").path
        app.launchEnvironment["PLAYHOUSE_WORKTREE_LABEL"] = "Playhouse UI Test Worktree"
        app.launchEnvironment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        app.launchEnvironment["PLAYHOUSE_E2E_DEFAULT_PARENT_FOLDER"] = defaultParent ?? "__unset__"
        if let launchWindowTitle {
            app.launchEnvironment["PLAYHOUSE_WINDOW_TITLE"] = launchWindowTitle
        }
        app.launchEnvironment.merge(providerExecutableEnvironment, uniquingKeysWith: { _, new in new })
        if let codexFixtureStateDirectory {
            app.launchEnvironment["PLAYHOUSE_E2E_FIXTURE_STATE_DIRECTORY"] = codexFixtureStateDirectory.path
        }
        for (key, value) in environmentOverrides {
            app.launchEnvironment[key] = value
        }
        launchAppWithOpen(bundleIdentifier: bundleIdentifier, environmentOverrides: environmentOverrides)
        waitForBoardOrAbortSuite()
        let newTaskButton = element("new-task-button")
        if newTaskButton.exists && !newTaskButton.isHittable {
            let windowMenu = app.menuBars.menuBarItems["Window"]
            windowMenu.click()
            let zoom = app.menuItems["Zoom"]
            if zoom.waitForExistence(timeout: 2) {
                zoom.click()
            } else {
                app.typeKey("z", modifierFlags: [.command, .option])
            }
            app.activate()
        }
    }


    private func launchAppWithOpen(bundleIdentifier: String? = nil, environmentOverrides: [String: String] = [:]) {
        let targetBundleIdentifier = bundleIdentifier ?? Bundle(url: appBundle)?.bundleIdentifier ?? "com.playhouse.app.e2e"
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        let usesLiveCodex = isLiveCodexIntegration
        let liveCodexHome = ProcessInfo.processInfo.environment["CODEX_HOME"] ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(".codex").path
        let codexHome = usesLiveCodex ? liveCodexHome : dataDirectory.appendingPathComponent("codex-home").path
        environment["CODEX_HOME"] = codexHome
        environment["PLAYHOUSE_WORKTREE_LABEL"] = "Playhouse UI Test Worktree"
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_E2E_DEFAULT_PARENT_FOLDER"] = launchDefaultParent ?? "__unset__"
        if usesLiveCodex {
            environment["PLAYHOUSE_RUN_CODEX_INTEGRATION"] = "1"
        }
        if let launchWindowTitle {
            environment["PLAYHOUSE_WINDOW_TITLE"] = launchWindowTitle
        }
        environment.merge(providerExecutableEnvironment, uniquingKeysWith: { _, new in new })
        if let codexFixtureStateDirectory {
            environment["PLAYHOUSE_E2E_FIXTURE_STATE_DIRECTORY"] = codexFixtureStateDirectory.path
        }
        environment.merge(environmentOverrides, uniquingKeysWith: { _, new in new })
        app = XCUIApplication(bundleIdentifier: targetBundleIdentifier)
        app.launchEnvironment = environment
        // Every case starts from no restored windows. AppKit saves open windows on
        // quit and reopens them on the next launch; a plugin window left open by
        // an earlier case (or session) reopens against this case's data directory,
        // shows "has no plugin.json", and covers the board.
        app.launchArguments = ["-ApplePersistenceIgnoreState", "YES"]
        app.launch()
    }

    private func waitForBoardOrAbortSuite() {
        let boardTitle = element("board-title")
        if waitUntil({ self.isPlayhouseFrontmost }, timeout: 3),
           boardTitle.waitForExistence(timeout: 6) {
            return
        }

        let relaunchedAfterMissingWindow: Bool
        if terminateAppAndWait(app, timeout: 8) {
            launchAppWithOpen()
            relaunchedAfterMissingWindow = boardTitle.waitForExistence(timeout: 8)
        } else {
            relaunchedAfterMissingWindow = false
        }

        let expectedBundleID = Bundle(url: appBundle)?.bundleIdentifier ?? "unknown"
        let frontmostDescription = Self.frontmostApplicationDescription
        guard !relaunchedAfterMissingWindow else { return }
        let reason = "Playhouse UI startup failed after a process restart recovery attempt. Expected frontmost app \(expectedBundleID); actual frontmost app: \(frontmostDescription); app state: \(app.state.rawValue); board title not found."
        Self.suiteAbortReason = reason
        let screenshot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        screenshot.name = "Playhouse startup failure and frontmost app"
        screenshot.lifetime = .keepAlways
        add(screenshot)
        XCTFail(reason)
    }

    private var isPlayhouseFrontmost: Bool {
        guard let expectedBundleID = Bundle(url: appBundle)?.bundleIdentifier else { return false }
        return app.state == .runningForeground &&
            NSWorkspace.shared.frontmostApplication?.bundleIdentifier == expectedBundleID
    }

    private static var frontmostApplicationDescription: String {
        guard let frontmost = NSWorkspace.shared.frontmostApplication else { return "none" }
        return "\(frontmost.localizedName ?? "unknown") (\(frontmost.bundleIdentifier ?? "unknown"))"
    }

    private func clearSavedWindowFrames() {
        guard let bundleIdentifier = Bundle(url: appBundle)?.bundleIdentifier,
              bundleIdentifier == "com.playhouse.app.e2e" || bundleIdentifier.hasPrefix("com.playhouse.app.e2e.") ||
                (bundleIdentifier.hasPrefix("com.playhouse.app.worktree.") && bundleIdentifier.contains(".e2e.")),
              let appDefaults = UserDefaults(suiteName: bundleIdentifier) else {
            return
        }
        let windowFrameKeys = appDefaults.dictionaryRepresentation().keys.filter { $0.hasPrefix("NSWindow Frame ") }
        for key in windowFrameKeys {
            appDefaults.removeObject(forKey: key)
        }
        appDefaults.synchronize()
    }

    private func makeCodexFixture(emptyQuestions: Bool, nonblocking: Bool = false) throws -> URL {
        let executable = WorkspaceFixture.root
            .appendingPathComponent(emptyQuestions ? "codex-fixture-empty" : (nonblocking ? "codex-fixture-nonblocking" : "codex-fixture-ui"))
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: executable.path), "The prepared Codex fixture is missing or not executable.")
        // The shared fixture records turns beside itself; start each case from an empty
        // history, once, so a later call cannot remove a running turn's history.
        if codexFixtureHistoriesReset.insert(executable.path).inserted {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: executable.path + ".history"))
        }
        return executable
    }

    private func makeGitHubStateFixture() throws -> [String: String] {
        try makeGitHubStateFixture(expectedNumbers: [123, 456])
    }

    /// The board's PR-check cooldown for cases that wait it out (the app defaults to 20 s).
    private static let prCheckCooldown: TimeInterval = 3
    private static var prCheckCooldownEnvironment: [String: String] {
        ["PLAYHOUSE_E2E_PR_CHECK_COOLDOWN_SECONDS": String(Int(prCheckCooldown))]
    }

    /// PATH that resolves `git` to the staged hold wrapper first; see `GitHoldBarrier`.
    private func makeGitHoldEnvironment() throws -> [String: String] {
        let directory = GitHoldBarrier.directory
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: directory.appendingPathComponent("git").path), "The prepared git hold wrapper is missing or not executable.")
        let inheritedPath = ProcessInfo.processInfo.environment["PATH"] ?? "/usr/bin:/bin"
        return ["PATH": "\(directory.path):\(inheritedPath)"]
    }

    private func makeGitHubStateFixture(expectedNumbers: [Int]) throws -> [String: String] {
        let directory = dataDirectory.appendingPathComponent("gh-fixture", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let stateURL = directory.appendingPathComponent("state")
        let callLogURL = directory.appendingPathComponent("calls")
        let createLogURL = directory.appendingPathComponent("create-calls")
        let createFailureURL = directory.appendingPathComponent("fail-create-attempt")
        try expectedNumbers.map { "\($0)=unmerged" }.joined(separator: "\n").appending("\n")
            .write(to: stateURL, atomically: true, encoding: .utf8)
        let startedDirectory = directory.appendingPathComponent("started", isDirectory: true)
        try FileManager.default.createDirectory(at: startedDirectory, withIntermediateDirectories: true)
        let expectedIDs = expectedNumbers.map(String.init).joined(separator: " ")
        // The runner stages scripts/fixtures/gh-fixture.sh as an executable named gh; the sandboxed
        // test process cannot write one itself without quarantine.
        let ghDirectory = WorkspaceFixture.root.appendingPathComponent("gh-fixture", isDirectory: true)
        XCTAssertTrue(FileManager.default.isExecutableFile(atPath: ghDirectory.appendingPathComponent("gh").path), "The prepared gh fixture is missing or not executable.")
        let inheritedPath = ProcessInfo.processInfo.environment["PATH"] ?? "/usr/bin:/bin"
        return [
            "PATH": "\(ghDirectory.path):\(inheritedPath)",
            "PLAYHOUSE_E2E_GH_STATE_PATH": stateURL.path,
            "PLAYHOUSE_E2E_GH_CALL_LOG": callLogURL.path,
            "PLAYHOUSE_E2E_GH_CREATE_LOG": createLogURL.path,
            "PLAYHOUSE_E2E_GH_CREATE_FAILURE_PATH": createFailureURL.path,
            "PLAYHOUSE_E2E_GH_CREATE_FIRST_NUMBER": "501",
            "PLAYHOUSE_E2E_GH_STARTED_DIRECTORY": startedDirectory.path,
            "PLAYHOUSE_E2E_GH_EXPECTED_IDS": expectedIDs,
        ]
    }

    private func activateOtherAppThenReturn() {
        XCUIApplication(bundleIdentifier: "com.apple.finder").activate()
        app.activate()
    }

    private func relaunchApp() {
        XCTAssertTrue(terminateAppAndWait(app), "Playhouse must stop before the resume-path relaunch.")
        launchAppWithOpen()
        waitForBoardOrAbortSuite()
    }

    private func terminateAppAndWait(_ target: XCUIApplication, timeout: TimeInterval = 10) -> Bool {
        guard target.state != .notRunning else {
            return true
        }
        target.terminate()
        return waitUntil({ target.state == .notRunning }, timeout: timeout)
    }

    private func openNewTaskConversation() {
        app.activate()
        element("new-task-button").click()
        XCTAssertTrue(element("empty-conversation").waitForExistence(timeout: 10), "New Task should create and open an empty conversation.")
        XCTAssertFalse(element("conversation-repository-search").exists, "A new conversation should keep its repository picker closed.")
        let composer = element("message-composer")
        XCTAssertTrue(composer.waitForExistence(timeout: 10), "A new conversation should focus the chat composer.")
        app.typeKey("x", modifierFlags: [])
        XCTAssertEqual(composer.value as? String, "x", "The chat composer should receive keyboard input immediately.")
        app.typeKey(XCUIKeyboardKey.delete.rawValue, modifierFlags: [])
        XCTAssertEqual(composer.value as? String, "", "The focus check should leave the new composer empty.")
        XCTAssertFalse(element("create-task-button").exists, "Direct creation should not show the New Task sheet.")
    }

    private func closeConversationRepositoryPicker() {
        guard element("conversation-repository-search").exists else { return }
        element("add-conversation-repository-button").click()
        XCTAssertTrue(waitUntil({ !self.element("conversation-repository-search").exists }, timeout: 5), "The conversation repository picker should close.")
    }

    /// Waits until the element stops moving. The transcript appends messages
    /// and auto-scrolls as a turn settles, so a click issued the instant a
    /// Clicks a text field once it has settled, confirms it took keyboard focus
    /// (retrying the click once), then types. A click that lands while the
    /// form is still scrolling into place can leave the field unfocused, and
    /// typeText then fails with "Neither element nor any descendant has
    /// keyboard focus".
    private func typeIntoField(_ field: XCUIElement, text: String, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertTrue(field.waitForExistence(timeout: 5), "Text field is missing.", file: file, line: line)
        waitForStableFrame(field)
        field.click()
        if !waitUntil({ (field.value(forKey: "hasKeyboardFocus") as? Bool) == true }, timeout: 2) {
            field.click()
            XCTAssertTrue(waitUntil({ (field.value(forKey: "hasKeyboardFocus") as? Bool) == true }, timeout: 2), "Clicking the text field should focus it.", file: file, line: line)
        }
        field.typeText(text)
    }

    /// Selects a question option once the form has settled. The question form
    /// arrives with a transcript reload that scrolls it; a click issued the
    /// moment the title exists can land before the option is in place, leaving
    /// nothing selected and a Submit click that does nothing.
    private func selectQuestionOption(_ label: String, file: StaticString = #filePath, line: UInt = #line) {
        let option = app.buttons.matching(NSPredicate(format: "label == %@", label)).firstMatch
        XCTAssertTrue(option.waitForExistence(timeout: 5), "Question option is missing: \(label)", file: file, line: line)
        XCTAssertTrue(waitForStableFrame(option), "Question option should settle in place: \(label)", file: file, line: line)
        option.click()
        XCTAssertTrue(
            waitUntil({ option.value as? String == "selected" }, timeout: 3),
            "Clicking the question option should select it: \(label)", file: file, line: line
        )
    }

    /// control appears can land where the control was a frame earlier.
    @discardableResult
    private func waitForStableFrame(_ target: XCUIElement, timeout: TimeInterval = 5) -> Bool {
        var previous = CGRect.null
        var stableSince = Date()
        return waitUntil({
            let frame = target.frame
            if frame != previous { previous = frame; stableSince = Date() }
            return !frame.isEmpty && Date().timeIntervalSince(stableSince) >= 0.4
        }, timeout: timeout)
    }

    private func waitUntil(_ condition: () -> Bool, timeout: TimeInterval) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if condition() { return true }
            RunLoop.current.run(until: Date().addingTimeInterval(0.1))
        }
        return condition()
    }

    /// The file behind `preferencesSuiteName`; the runner reads it directly
    /// because its sandbox keeps it out of the app's preference domains.
    private var isolatedPreferencesFile: URL {
        URL(fileURLWithPath: preferencesSuiteName + ".plist")
    }

    private func isolatedPreferenceKeys() -> Set<String> {
        guard let data = try? Data(contentsOf: isolatedPreferencesFile),
              let values = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any] else {
            return []
        }
        return Set(values.keys)
    }

    private func createTaskFixture(title: String, roots: [String]) throws {
        var arguments = ["task", "create", "--title", title, "--prompt", "Fixture task description."]
        for root in roots { arguments += ["--root", root] }
        let result = try runCLI(arguments)["result"] as? [String: Any]
        XCTAssertEqual(result?["title"] as? String, title)
    }

    private func saveNewTaskPromptAndReturnToBoard(_ title: String, prompt: String? = nil) {
        let composer = element("message-composer")
        XCTAssertTrue(waitUntil({ composer.exists && composer.isHittable }, timeout: 15), "The direct-created task should expose its conversation composer.")
        composer.click()
        composer.typeText(prompt ?? title)
        element("back-to-board-button").click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 10), "Returning to the board should preserve the automatically saved prompt.")
        guard let task = try? tasksFromBoardList().first, let taskID = task["id"] as? String else {
            XCTFail("The created task should remain in Backlog after saving its prompt.")
            return
        }
        _ = try? runCLI(["task", "rename", taskID, "--title", title])
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: taskID)?["title"] as? String) == title
                && app.buttons[title].exists
        }, timeout: 10), "The created task should be visible with its deterministic test title.")
    }

    private func chooseRepositorySuggestion(_ name: String) {
        var searchField = element("conversation-repository-search")
        if !searchField.exists {
            element("add-conversation-repository-button").click()
            searchField = element("conversation-repository-search")
        }
        XCTAssertTrue(searchField.waitForExistence(timeout: 5), "The conversation picker should be open before choosing a repository.")
        searchField.click()
        replaceText(searchField, with: name)
        let suggestion = element("conversation-repository-suggestion-\(name)")
        XCTAssertTrue(suggestion.waitForExistence(timeout: 10), "No repository suggestion for \(name).")
        XCTAssertTrue(suggestion.isHittable, "Repository suggestion \(name) should be reachable in the scrolling picker.")
        suggestion.click()
        XCTAssertTrue(element("conversation-repository-badge-\(name)").waitForExistence(timeout: 10), "The selected repository should appear in the conversation header.")
    }

    private func setConversationRepositoryField(_ repositoryName: String, field: String, value: String) {
        let badge = element("conversation-repository-badge-\(repositoryName)")
        XCTAssertTrue(badge.waitForExistence(timeout: 5), "The conversation should show \(repositoryName) before editing its settings.")
        badge.click()
        let edit = element("conversation-repository-\(field)-edit")
        XCTAssertTrue(edit.waitForExistence(timeout: 5), "The conversation repository settings should expose the \(field) edit control.")
        edit.click()
        let fieldElement = element("conversation-repository-\(field)")
        XCTAssertTrue(fieldElement.waitForExistence(timeout: 5))
        replaceText(fieldElement, with: value)
        element("conversation-repository-\(field)-save").click()
        XCTAssertTrue(waitUntil({
            guard let task = try? self.tasksFromBoardList().first,
                  let records = task["repositoryWorktrees"] as? [[String: Any]],
                  let record = records.first(where: {
                      guard let path = $0["repositoryPath"] as? String else { return false }
                      return URL(fileURLWithPath: path).lastPathComponent == repositoryName
                  }) else {
                return false
            }
            let key = field == "branch" ? "branch" : (field == "branch-from" ? "branchFrom" : "mergeTarget")
            return record[key] as? String == value
        }, timeout: 10), "The conversation should persist the edited \(field) value.")

        // The settings popover stays open after a save, so close it before the next step.
        XCTAssertTrue(waitForDisappearance(fieldElement), "A saved value should leave edit mode.")
        app.typeKey(XCUIKeyboardKey.escape.rawValue, modifierFlags: [])
        XCTAssertTrue(waitForDisappearance(edit), "Escape should close the repository settings.")
    }

    private func pasteText(_ text: String, into field: XCUIElement) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(text, forType: .string)
        field.typeKey("v", modifierFlags: .command)
    }

    private func replaceText(_ field: XCUIElement, with value: String) {
        field.click()
        field.typeKey("a", modifierFlags: .command)
        field.typeText(value)
    }

    /// Leaves the open task for the board. Right after a turn ends the back
    /// button can be re-rendered and swallow a click, so wait for it to be
    /// hittable and confirm the board actually appeared.
    private func returnToBoard() {
        let backToBoard = element("back-to-board-button")
        XCTAssertTrue(waitUntil({ backToBoard.isHittable }, timeout: 5), "The back-to-board button never became clickable.")
        XCTAssertTrue(waitForStableFrame(backToBoard), "The back-to-board button kept moving.")
        backToBoard.click()
        XCTAssertTrue(element("board-title").waitForExistence(timeout: 5), "Clicking back-to-board should show the board.")
    }

    private func openTask(named title: String, horizontalRecovery: Bool = false) {
        // Task cards are only on the board; leave an open task first. The back
        // button can be briefly non-hittable right after a send (tooltip,
        // re-render), so wait for it instead of silently staying in the task.
        let backToBoard = element("back-to-board-button")
        let boardTitle = element("board-title")
        if backToBoard.exists || (!boardTitle.exists && backToBoard.waitForExistence(timeout: 2)) {
            // A caller may already be mid-transition to the board (it clicked
            // back itself); then the lingering button never becomes hittable
            // and the board arriving is the success case.
            XCTAssertTrue(waitUntil({ boardTitle.exists || backToBoard.isHittable }, timeout: 5), "Neither the board nor a clickable back-to-board button appeared.")
            if !boardTitle.exists {
                backToBoard.click()
                XCTAssertTrue(boardTitle.waitForExistence(timeout: 5))
            }
        }
        let card = app.buttons.matching(NSPredicate(format: "label == %@", title)).firstMatch
        XCTAssertTrue(card.waitForExistence(timeout: 10), "Task card is missing: \(title)")
        if !card.isHittable {
            let board = element("board-columns-scroll-view")
            if horizontalRecovery {
                for _ in 0..<6 where !card.isHittable {
                    board.swipeLeft()
                }
                for _ in 0..<6 where !card.isHittable {
                    board.swipeRight()
                }
            }
            for _ in 0..<12 where !card.isHittable {
                board.scroll(byDeltaX: 0, deltaY: -300)
                board.swipeUp()
            }
        }
        let useCoordinateFallback = horizontalRecovery && !card.isHittable
        if !useCoordinateFallback {
            XCTAssertTrue(card.isHittable, "Task card must be hittable after bounded board scrolling.")
        }
        clickTaskCardTitle(card)
        XCTAssertTrue(element("task-view-title").waitForExistence(timeout: 10), "Clicking the task card title should open the task.")
    }

    /// Scrolls the board's columns sideways until `target` lies fully inside the
    /// visible board. With the persistent sidebar, a narrow screen (the UI VM's is
    /// 1024 points) clips the Review column's trailing edge, where a card's PR
    /// controls sit: they stay in the hierarchy but take no hover or click.
    private func revealOnBoard(_ target: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let board = element("board-columns-scroll-view")
        XCTAssertTrue(target.waitForExistence(timeout: 5), "Board control is missing: \(target.identifier)", file: file, line: line)
        // A negative delta moves the columns left, revealing content on the right;
        // flip it once if a step moved the control the wrong way.
        var direction: CGFloat = -1
        for _ in 0..<8 {
            let visible = board.frame, frame = target.frame
            if visible.contains(frame) { break }
            let overflow = frame.maxX > visible.maxX ? frame.maxX - visible.maxX + 24 : frame.minX - visible.minX - 24
            board.scroll(byDeltaX: direction * overflow, deltaY: 0)
            waitForStableFrame(target, timeout: 2)
            let moved = target.frame.minX - frame.minX
            if moved == 0 || (moved > 0) == (overflow > 0) { direction = -direction }
        }
        XCTAssertTrue(board.frame.contains(target.frame), "\(target.identifier) should be scrolled into the visible board; control=\(target.frame), board=\(board.frame).", file: file, line: line)
    }

    /// Opens a board card through its title. The card's center can sit on one
    /// of its own controls (the token counter button opens Token stats), so a
    /// plain card.click() may open that control instead of the task.
    private func clickTaskCardTitle(_ card: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let cardTitle = element(card.identifier.replacingOccurrences(of: "task-card-", with: "task-title-"))
        XCTAssertTrue(cardTitle.waitForExistence(timeout: 5), "Task card title is missing: \(card.identifier)", file: file, line: line)
        let titleCenter = CGPoint(x: cardTitle.frame.midX, y: cardTitle.frame.midY)
        XCTAssertTrue(card.frame.contains(titleCenter), "Task card title must lie inside the visible card.", file: file, line: line)
        cardTitle.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).click()
    }

    private func completeCurrentTaskWithFixtureAnswers(
        taskTitle: String,
        prompt: String = "Complete this task.",
        reportCompletedOutcome: Bool = true,
        expectedFinalStatus: String? = nil,
        settleTimeout: TimeInterval = 10,
        whileTurnHeld: (() throws -> Void)? = nil
    ) throws {
        let taskID = try taskID(named: taskTitle)
        let executablePath = try XCTUnwrap(codexFixtureExecutable, "The task fixture has no Codex executable.")
        let hold = URL(fileURLWithPath: executablePath + ".outcome-hold")
        let active = URL(fileURLWithPath: executablePath + ".outcome-active")
        let release = URL(fileURLWithPath: executablePath + ".outcome-release")
        try? FileManager.default.removeItem(at: active)
        try? FileManager.default.removeItem(at: release)
        try Data().write(to: hold, options: .atomic)
        defer {
            try? "Release the answered fixture turn.\n".write(to: release, atomically: true, encoding: .utf8)
            _ = waitUntil({ !FileManager.default.fileExists(atPath: active.path) }, timeout: 10)
            try? FileManager.default.removeItem(at: hold)
            try? FileManager.default.removeItem(at: active)
            try? FileManager.default.removeItem(at: release)
        }
        element("message-composer").click()
        element("message-composer").typeText(prompt)
        element("send-message-button").click()
        XCTAssertTrue(element("ai-question-form-title").waitForExistence(timeout: 10))
        selectQuestionOption("Blue")
        typeIntoField(element("ai-question-answer-token"), text: "fixture-secret")
        element("submit-ai-answers-button").click()
        XCTAssertTrue(waitUntil({ FileManager.default.fileExists(atPath: active.path) }, timeout: 10), "The fixture should hold after receiving answers so the task outcome can be reported.")
        try whileTurnHeld?()
        if reportCompletedOutcome {
            XCTAssertTrue(waitUntil({
                (try? self.taskRecord(id: taskID)?["status"] as? String) == "In Progress"
            }, timeout: 10), "The task should be In Progress before reporting the fixture outcome.")
            let outcome = try runCLI(["task", "outcome", taskID, "completed"])
            XCTAssertEqual((outcome["result"] as? [String: Any])?["outcome"] as? String, "completed")
        }
        try "Release the answered fixture turn.\n".write(to: release, atomically: true, encoding: .utf8)
        let answer = app.descendants(matching: .any).matching(
            NSPredicate(
                format: "identifier BEGINSWITH %@ AND label == %@",
                "assistant-message-",
                "Answers received: Blue / fixture-secret."
            )
        ).firstMatch
        XCTAssertTrue(answer.waitForExistence(timeout: 10))
        let expectedStatus = expectedFinalStatus ?? (reportCompletedOutcome ? "Review" : "Waiting Response")
        XCTAssertTrue(waitUntil({
            (try? self.taskRecord(id: taskID)?["status"] as? String) == expectedStatus
        }, timeout: settleTimeout), "The completed turn should settle in \(expectedStatus).")
    }

    private func assertTaskVisible(_ title: String, inColumn status: String) {
        // Board columns are only on the board; leave an open task first.
        let backToBoard = element("back-to-board-button")
        if backToBoard.exists, backToBoard.isHittable {
            backToBoard.click()
            XCTAssertTrue(element("board-title").waitForExistence(timeout: 5))
        }
        let column = element("column-\(status.lowercased().replacingOccurrences(of: " ", with: "-"))")
        XCTAssertTrue(column.waitForExistence(timeout: 5), "Missing \(status) column.")
        XCTAssertTrue(column.buttons[title].waitForExistence(timeout: 8), "\(title) is not in \(status).")
    }

    private func assertTaskArchived(_ title: String) throws {
        let taskID = try taskID(named: title)
        element("done-archive-button").click()
        XCTAssertTrue(element("done-archive-task-\(taskID)").waitForExistence(timeout: 10), "\(title) should appear in the completed task archive.")
        element("close-done-archive-button").click()
    }

    private func moveTaskToDone(_ title: String) {
        let card = app.buttons[title].firstMatch
        XCTAssertTrue(card.waitForExistence(timeout: 5))
        dragTaskToDone(card)
        XCTAssertTrue(waitUntil({
            do { return try taskRecord(named: title)?["status"] as? String == "Done" }
            catch { return false }
        }, timeout: 15), "Dropping \(title) on the Done target should persist its Done status.")
    }

    private func moveTaskToDone(taskID: String) {
        let card = element("task-card-\(taskID)").firstMatch
        XCTAssertTrue(card.waitForExistence(timeout: 5), "The reviewed task card should remain available by its stable task identifier.")
        dragTaskToDone(card)
        XCTAssertTrue(waitUntil({
            do { return try taskRecord(id: taskID)?["status"] as? String == "Done" }
            catch { return false }
        }, timeout: 15), "Dropping task \(taskID) on the Done target should persist its Done status.")
    }

    private func dragTaskToDone(_ card: XCUIElement) {
        let board = element("board-columns-scroll-view")
        XCTAssertTrue(board.waitForExistence(timeout: 5), "The board columns should remain visible while moving a task to Done.")
        XCTAssertTrue(element("task-done-drop-target").waitForExistence(timeout: 5), "The Done drawer should always be present at the board edge.")
        let source = card.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
        // The drawer's tab slides open once the drag begins and is then centered 32 points
        // in from the window edge.
        let doneTarget = app.windows.firstMatch.coordinate(withNormalizedOffset: CGVector(dx: 1, dy: 0.5)).withOffset(CGVector(dx: -32, dy: 0))
        source.press(forDuration: 0.5, thenDragTo: doneTarget, withVelocity: .default, thenHoldForDuration: 1.5)
    }

    /// Starts a full-screen capture that fires while a following blocking gesture is still
    /// in progress, so a mid-drag state can be attached once the gesture returns.
    private func startDelayedScreenCapture(afterSeconds delay: Int) -> (process: Process, file: URL)? {
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("playhouse-capture-\(UUID().uuidString).png")
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
        process.arguments = ["-x", "-T", "\(delay)", file.path]
        do {
            try process.run()
            return (process, file)
        } catch {
            return nil
        }
    }

    private func attachScreenCapture(_ capture: (process: Process, file: URL)?, named name: String) {
        guard let capture else { return }
        capture.process.waitUntilExit()
        defer { try? FileManager.default.removeItem(at: capture.file) }
        guard FileManager.default.fileExists(atPath: capture.file.path) else { return }
        let attachment = XCTAttachment(contentsOfFile: capture.file)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    /// The Done drawer shows only a thin sliver beside the board while nothing is dragged.
    private func assertDoneDrawerResting(_ moment: String, file: StaticString = #filePath, line: UInt = #line) {
        let drawer = element("task-done-drop-target")
        let board = element("board-columns-scroll-view")
        let window = app.windows.firstMatch
        XCTAssertTrue(drawer.waitForExistence(timeout: 5), "The Done drawer should exist \(moment).", file: file, line: line)
        XCTAssertTrue(waitUntil({ drawer.frame.minX >= window.frame.maxX - 6 }, timeout: 3), "The Done drawer should rest as a sliver at the window edge \(moment).", file: file, line: line)
        XCTAssertGreaterThanOrEqual(drawer.frame.minX, board.frame.maxX - 1, "The Done drawer must sit beside the board columns, never over them \(moment).", file: file, line: line)
    }

    /// Installs the Claude Code protocol fixture for this case and returns the
    /// environment a CLI-driven turn needs. Must run before `launchApp` so the
    /// app's own turns use it too.
    private func installClaudeFixture(named name: String) throws -> [String: String] {
        let executable = dataDirectory.appendingPathComponent(name)
        try FileManager.default.copyItem(
            at: WorkspaceFixture.root.appendingPathComponent("claude-fixture-ui"),
            to: executable
        )
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: executable.path)
        try Data("Playhouse test owns this Claude Code protocol fixture (v1).\n".utf8).write(
            to: dataDirectory.appendingPathComponent(".playhouse-claude-fixture-owner")
        )
        claudeFixtureExecutable = executable.path
        return ["PLAYHOUSE_E2E_CLAUDE_EXECUTABLE": executable.path]
    }

    /// The usage dot is one flat hue, so the dominant channel says where on the
    /// green-to-red heatmap it currently sits. `leftEdgeFraction` restricts the
    /// sample to a left-hand slice of `element`'s screenshot — used to read the
    /// CPU bar's color off the stable task card instead of the thin animated
    /// bar sub-view itself, whose identity can transiently drop out of the
    /// accessibility tree between an existence check and a screenshot fetch.
    private func isGreenDominant(_ element: XCUIElement, leftEdgeFraction: CGFloat = 1.0) -> Bool {
        guard element.exists else { return false }
        let image = element.screenshot().image
        return pixelCount(in: image, maxXFraction: leftEdgeFraction) { $0.greenComponent > $0.redComponent + 0.15 } > 4
    }

    private func isRedDominant(_ element: XCUIElement, leftEdgeFraction: CGFloat = 1.0) -> Bool {
        guard element.exists else { return false }
        let image = element.screenshot().image
        return pixelCount(in: image, maxXFraction: leftEdgeFraction) { $0.redComponent > $0.greenComponent + 0.15 } > 4
    }

    private func assertPixel(_ image: NSImage, normalizedX: CGFloat, normalizedY: CGFloat, rgb expected: (Int, Int, Int), accuracy: Int = 8, file: StaticString = #filePath, line: UInt = #line) {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            XCTFail("Could not read workspace screenshot pixels.", file: file, line: line)
            return
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        let x = min(cgImage.width - 1, max(0, Int(CGFloat(cgImage.width) * normalizedX)))
        let y = min(cgImage.height - 1, max(0, Int(CGFloat(cgImage.height) * normalizedY)))
        guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else {
            XCTFail("Could not sample workspace background color.", file: file, line: line)
            return
        }
        XCTAssertEqual(Int((color.redComponent * 255).rounded()), expected.0, accuracy: accuracy, file: file, line: line)
        XCTAssertEqual(Int((color.greenComponent * 255).rounded()), expected.1, accuracy: accuracy, file: file, line: line)
        XCTAssertEqual(Int((color.blueComponent * 255).rounded()), expected.2, accuracy: accuracy, file: file, line: line)
    }

    private func assertConflictIndicatorArtwork(_ element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let image = element.screenshot().image
        let bluePixels = pixelCount(in: image) {
            $0.blueComponent > 0.55 && $0.blueComponent > $0.redComponent + 0.15 && $0.blueComponent > $0.greenComponent + 0.10
        }
        let orangePixels = pixelCount(in: image) {
            $0.redComponent > 0.75 && $0.greenComponent > 0.25 && $0.greenComponent < 0.75 && $0.blueComponent < 0.35
        }
        // The indicator is a single orange repair glyph; any blue would mean the old
        // two-tone branch artwork came back.
        XCTAssertGreaterThan(orangePixels, 2, "The conflict indicator should render its orange repair icon inside the action.", file: file, line: line)
        XCTAssertEqual(bluePixels, 0, "The conflict indicator should no longer render the old blue branch artwork.", file: file, line: line)
    }

    private func assertTrackThickness(_ image: NSImage, file: StaticString = #filePath, line: UInt = #line) {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            XCTFail("Could not read effort slider pixels.", file: file, line: line)
            return
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        let x = min(cgImage.width - 1, max(0, Int(CGFloat(cgImage.width) * 0.10)))
        var accentRows = 0
        for y in 0..<cgImage.height {
            guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
            if color.blueComponent > 0.55 && color.blueComponent > color.redComponent * 1.2 {
                accentRows += 1
            }
        }
        let fraction = Double(accentRows) / Double(cgImage.height)
        XCTAssertGreaterThanOrEqual(fraction, 0.23,
            "The 6-point effort track should remain visibly thicker than the previous 4-point track (blue-pixel fraction: \(fraction)).",
            file: file, line: line)
    }

    private func assertNoBlueFocusOutline(in image: NSImage, file: StaticString = #filePath, line: UInt = #line) {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            XCTFail("Could not read effort slider pixels.", file: file, line: line)
            return
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        // A focus border runs along every side; the filled track reaches the
        // left and right edges, so only the top and bottom edges are sampled.
        let edgePoints: [(CGFloat, CGFloat)] = (1...9).map { (CGFloat($0) / 10, 0.04) }
            + (1...9).map { (CGFloat($0) / 10, 0.96) }
        var bluePixels = 0
        for (normalizedX, normalizedY) in edgePoints {
            let x = min(cgImage.width - 1, max(0, Int(CGFloat(cgImage.width) * normalizedX)))
            let y = min(cgImage.height - 1, max(0, Int(CGFloat(cgImage.height) * normalizedY)))
            guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
            if color.blueComponent > 0.55 && color.blueComponent > color.redComponent * 1.4 {
                bluePixels += 1
            }
        }
        XCTAssertEqual(bluePixels, 0, "The focused effort slider should not draw a blue focus border.", file: file, line: line)
    }

    private func assertContainsRedForeground(in element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let redPixels = pixelCount(in: element.screenshot().image, step: 2) {
            $0.redComponent > 0.65 && $0.greenComponent < 0.4 && $0.blueComponent < 0.4
        }
        XCTAssertGreaterThan(redPixels, 3, "The missing-folder warning should render red foreground pixels.", file: file, line: line)
    }

    private func assertPlayhouseLogoArtwork(_ element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let logoImage = element.screenshot().image
        guard logoImage.cgImage(forProposedRect: nil, context: nil, hints: nil) != nil else {
            XCTFail("Could not read the Playhouse logo screenshot.", file: file, line: line)
            return
        }
        assertPixel(logoImage, normalizedX: 0.20, normalizedY: 0.50, rgb: (71, 176, 235), accuracy: 30, file: file, line: line)
        assertPixel(logoImage, normalizedX: 0.80, normalizedY: 0.50, rgb: (148, 41, 121), accuracy: 30, file: file, line: line)
        assertPixel(logoImage, normalizedX: 0.50, normalizedY: 0.35, rgb: (245, 179, 124), accuracy: 35, file: file, line: line)
        assertPixel(logoImage, normalizedX: 0.20, normalizedY: 0.80, rgb: (177, 54, 171), accuracy: 35, file: file, line: line)
        assertPixel(logoImage, normalizedX: 0.80, normalizedY: 0.80, rgb: (240, 82, 121), accuracy: 30, file: file, line: line)
    }

    /// The activity section renders open while a turn runs and collapses once it
    /// settles, so a test that needs the details open must expand only when the
    /// disclosure is actually collapsed; clicking blindly can close it instead.
    /// Reports whether the section ended up open, so a caller can assert that its
    /// own check really inspected an open section. The chevron is the anchor, not
    /// the details container: when every activity in flight renders outside the
    /// section, an open section has no children and does not resolve.
    @discardableResult
    private func expandActivityDetails(_ disclosure: XCUIElement? = nil, timeout: TimeInterval = 10) -> Bool {
        let control = disclosure ?? element("codex-activity-disclosure")
        guard control.exists else { return false }
        return waitUntil({
            let value = control.value as? String ?? ""
            if value.hasPrefix("Expanded") { return true }
            if value.hasPrefix("Collapsed") { control.click() }
            return (control.value as? String ?? "").hasPrefix("Expanded")
        }, timeout: timeout)
    }

    /// An agent row's metadata line, read from the row's button beside its icon.
    private func subagentRowMetadata(_ row: XCUIElement) -> String {
        [row.value as? String, row.buttons.firstMatch.label].compactMap { $0 }.joined(separator: "\n")
    }

    private func assertSubagentIconArtwork(_ element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        guard let cgImage = element.screenshot().image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            XCTFail("Could not read the subagent icon screenshot.", file: file, line: line)
            return
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        func colorAt(_ normalizedX: CGFloat, _ normalizedY: CGFloat) -> NSColor? {
            let x = min(cgImage.width - 1, max(0, Int(CGFloat(cgImage.width) * normalizedX)))
            let y = min(cgImage.height - 1, max(0, Int(CGFloat(cgImage.height) * normalizedY)))
            return bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB)
        }
        guard let topCyan = colorAt(0.5125, 0.2125),
              let leftEye = colorAt(0.3625, 0.4875),
              let face = colorAt(0.5125, 0.5125),
              let lowerLeftAccent = colorAt(0.2125, 0.7875) else {
            XCTFail("Could not sample the subagent icon artwork.", file: file, line: line)
            return
        }
        // The committed robot artwork: a white head and face, blue eyes, and a slate outline.
        for (part, color) in [("head", topCyan), ("face", face)] {
            XCTAssertGreaterThan(min(color.redComponent, color.greenComponent, color.blueComponent), 0.8, "The robot's \(part) should render white at its expected position.", file: file, line: line)
        }
        XCTAssertGreaterThan(leftEye.blueComponent, leftEye.redComponent * 1.4, "A blue eye should appear at the expected left-eye position.", file: file, line: line)
        XCTAssertGreaterThan(lowerLeftAccent.blueComponent, lowerLeftAccent.redComponent * 1.15, "The lower-left outline should retain the icon's slate color.", file: file, line: line)
        XCTAssertLessThan(max(lowerLeftAccent.redComponent, lowerLeftAccent.greenComponent, lowerLeftAccent.blueComponent), 0.6, "The lower-left outline should be dark.", file: file, line: line)
    }

    private func assertContainsGreenForeground(in element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        let greenPixels = pixelCount(in: element.screenshot().image) {
            $0.greenComponent > 0.35 && $0.redComponent < 0.65 && $0.blueComponent < 0.65
                && $0.greenComponent > $0.redComponent * 1.15 && $0.greenComponent > $0.blueComponent * 1.05
        }
        XCTAssertGreaterThan(greenPixels, 3, "The merged-PR completion checkmark should render green foreground pixels.", file: file, line: line)
    }

    private func repositoryTitleHasColor(_ element: XCUIElement, appearance: String) -> Bool {
        guard let cgImage = element.screenshot().image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            return false
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        var matchingPixels = 0
        for x in 0..<cgImage.width {
            for y in 0..<cgImage.height {
                guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
                let isMatch: Bool
                if appearance == "dark" {
                    isMatch = color.redComponent > 0.65
                        && color.greenComponent > 0.25
                        && color.redComponent > color.greenComponent * 1.3
                        && color.blueComponent < 0.25
                } else {
                    isMatch = color.blueComponent > color.redComponent * 1.5
                        && color.blueComponent > color.greenComponent * 1.2
                        && color.greenComponent > 0.18
                }
                if isMatch { matchingPixels += 1 }
            }
        }
        return matchingPixels > 3
    }

    private func repositoryTitle() -> XCUIElement {
        element("empty-conversation-repository-title")
    }

    /// Playhouse's own prompts render as muted automatic messages: the history entry that holds `text`
    /// is shown under the `playhouse-message-` identifier with its label, never as the user's bubble.
    private func assertAutomaticMessageBubble(taskID: String, containing text: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let history = try XCTUnwrap(try runCLI(["conversation", "history", taskID])["result"] as? [String: Any], file: file, line: line)
        let messages = try XCTUnwrap(history["messages"] as? [[String: Any]], file: file, line: line)
        let sent = try XCTUnwrap(
            messages.last { ($0["role"] as? String) == "user" && (($0["text"] as? String) ?? "").contains(text) },
            "History should hold the Playhouse-sent message containing: \(text)", file: file, line: line
        )
        let id = try XCTUnwrap(sent["id"] as? String, file: file, line: line)
        XCTAssertTrue(element("playhouse-message-\(id)").waitForExistence(timeout: 10), "The message renders as an automatic Playhouse message.", file: file, line: line)
        let label = element("playhouse-message-label-\(id)")
        XCTAssertTrue(label.waitForExistence(timeout: 5), "The automatic message carries its label.", file: file, line: line)
        XCTAssertTrue(label.label.contains("Automatic message from Playhouse") || ((label.value as? String) ?? "").contains("Automatic message from Playhouse"), "The label says the message is automatic: \(label.label)", file: file, line: line)
        XCTAssertFalse(element("user-message-\(id)").exists, "An automatic message is not rendered as the user's own bubble.", file: file, line: line)
    }

    /// The transcript's last row: the newest message, which can be the reply to a status nudge
    /// sent after the turn the test is watching.
    private func latestMessageRow(titled title: String) throws -> XCUIElement {
        let id = try taskID(named: title)
        let history = try XCTUnwrap(try runCLI(["conversation", "history", id])["result"] as? [String: Any])
        return try transcriptRow(for: try XCTUnwrap((history["messages"] as? [[String: Any]])?.last))
    }

    /// The transcript element a history message renders as.
    private func transcriptRow(for message: [String: Any]) throws -> XCUIElement {
        let isAutomatic = (message["role"] as? String) == "user"
            && ((message["text"] as? String) ?? "").contains("Playhouse internal outcome nudge:")
        let prefix = isAutomatic ? "playhouse-message-" : ((message["role"] as? String) == "assistant" ? "assistant-message-" : "user-message-")
        return element(prefix + (try XCTUnwrap(message["id"] as? String)))
    }

    /// History without the status nudges Playhouse sent and the agent's replies to them.
    private func ordinaryMessages(_ messages: [[String: Any]]) -> [[String: Any]] {
        var kept: [[String: Any]] = []
        var inNudge = false
        for message in messages {
            if (message["role"] as? String) == "user" {
                inNudge = ((message["text"] as? String) ?? "").contains("Playhouse internal outcome nudge:")
            }
            if !inNudge { kept.append(message) }
        }
        return kept
    }

    /// Whether a transcript message shows this text, as a message group's label
    /// or as a text view's value.
    private func transcriptContains(_ text: String) -> Bool {
        app.groups.matching(NSPredicate(format: "label CONTAINS %@", text)).firstMatch.exists
            || app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@ OR value CONTAINS %@", text, text)).firstMatch.exists
            || app.textViews.matching(NSPredicate(format: "value CONTAINS %@", text)).firstMatch.exists
            || app.otherElements.matching(NSPredicate(format: "label CONTAINS %@", text)).firstMatch.exists
    }

    /// Refreshes a standalone chat through its visible navigation controls. The board's
    /// Chat button moves off-screen while the 460-point sidebar and 980-point board coexist.
    private func refreshStandaloneChatSidebar() {
        let backButton = element("back-to-board-button")
        XCTAssertTrue(waitUntil({ backButton.exists && backButton.isHittable }, timeout: 5), "The sidebar should offer a visible way back to the board.")
        backButton.click()
        XCTAssertTrue(waitUntil({ !self.element("chat-sidebar").exists }, timeout: 5), "Returning to the board should slide the chat sidebar away.")
        let parent = launchDefaultParent
        XCTAssertTrue(terminateAppAndWait(app), "Playhouse must stop before restoring the test window frame.")
        clearSavedWindowFrames()
        launchApp(defaultParent: parent)
        let chatButton = element("chat-sidebar-button")
        XCTAssertTrue(waitUntil({ chatButton.exists && chatButton.isHittable }, timeout: 5), "The board's Chat button should be available again after leaving the sidebar.")
        chatButton.click()
        XCTAssertTrue(element("chat-sidebar").waitForExistence(timeout: 10), "The standalone chat should reopen from the board.")
    }

    /// Waits for transcript text, scrolling down on each miss: the lazy transcript
    /// only exposes rows near the viewport.
    private func transcriptShows(_ text: String, timeout: TimeInterval) -> Bool {
        waitUntil({
            if self.transcriptContains(text) { return true }
            self.element("conversation-scroll-view").scroll(byDeltaX: 0, deltaY: -300)
            return false
        }, timeout: timeout)
    }

    /// Runs `body` against the app's SQLite conversation store, which the app
    /// and its bridge daemon share in WAL mode.
    private func withConversationDatabase<T>(_ body: (OpaquePointer) throws -> T) throws -> T {
        var database: OpaquePointer?
        let path = dataDirectory.appendingPathComponent("Conversations-v1.sqlite").path
        guard sqlite3_open_v2(path, &database, SQLITE_OPEN_READWRITE, nil) == SQLITE_OK, let database else {
            sqlite3_close(database)
            throw NSError(domain: "PlayhouseUITests", code: 1, userInfo: [NSLocalizedDescriptionKey: "Could not open the conversation store at \(path)."])
        }
        defer { sqlite3_close(database) }
        sqlite3_busy_timeout(database, 30_000)
        return try body(database)
    }

    /// Rows of a query against the conversation store, as text columns.
    private func conversationRows(_ sql: String) throws -> [[String?]] {
        try withConversationDatabase { database in
            var statement: OpaquePointer?
            guard sqlite3_prepare_v2(database, sql, -1, &statement, nil) == SQLITE_OK else {
                throw NSError(domain: "PlayhouseUITests", code: 5, userInfo: [NSLocalizedDescriptionKey: String(cString: sqlite3_errmsg(database))])
            }
            defer { sqlite3_finalize(statement) }
            var rows: [[String?]] = []
            while sqlite3_step(statement) == SQLITE_ROW {
                rows.append((0..<sqlite3_column_count(statement)).map { column in
                    sqlite3_column_text(statement, column).map { String(cString: $0) }
                })
            }
            return rows
        }
    }

    private func conversationExecute(_ sql: String) throws {
        try withConversationDatabase { database in
            guard sqlite3_exec(database, sql, nil, nil, nil) == SQLITE_OK else {
                throw NSError(domain: "PlayhouseUITests", code: 6, userInfo: [NSLocalizedDescriptionKey: String(cString: sqlite3_errmsg(database))])
            }
        }
    }

    /// The task's stored conversation state, or nil before anything is recorded.
    private func conversationState(_ taskID: String) throws -> [String: Any]? {
        guard FileManager.default.fileExists(atPath: dataDirectory.appendingPathComponent("Conversations-v1.sqlite").path) else { return nil }
        return try withConversationDatabase { database in
            var statement: OpaquePointer?
            guard sqlite3_prepare_v2(database, "SELECT payload FROM conversation_state WHERE task_id = ?", -1, &statement, nil) == SQLITE_OK else {
                throw NSError(domain: "PlayhouseUITests", code: 2, userInfo: [NSLocalizedDescriptionKey: String(cString: sqlite3_errmsg(database))])
            }
            defer { sqlite3_finalize(statement) }
            sqlite3_bind_text(statement, 1, taskID.uppercased(), -1, unsafeBitCast(-1, to: sqlite3_destructor_type.self))
            guard sqlite3_step(statement) == SQLITE_ROW, let text = sqlite3_column_text(statement, 0) else { return nil }
            return try JSONSerialization.jsonObject(with: Data(String(cString: text).utf8)) as? [String: Any]
        }
    }

    private func writeConversationState(_ taskID: String, _ state: [String: Any]) throws {
        let payload = String(decoding: try JSONSerialization.data(withJSONObject: state), as: UTF8.self)
        try withConversationDatabase { database in
            var statement: OpaquePointer?
            let sql = "INSERT INTO conversation_state (task_id, payload) VALUES (?, ?) ON CONFLICT(task_id) DO UPDATE SET payload = excluded.payload"
            guard sqlite3_prepare_v2(database, sql, -1, &statement, nil) == SQLITE_OK else {
                throw NSError(domain: "PlayhouseUITests", code: 3, userInfo: [NSLocalizedDescriptionKey: String(cString: sqlite3_errmsg(database))])
            }
            defer { sqlite3_finalize(statement) }
            let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
            sqlite3_bind_text(statement, 1, taskID.uppercased(), -1, transient)
            sqlite3_bind_text(statement, 2, payload, -1, transient)
            guard sqlite3_step(statement) == SQLITE_DONE else {
                throw NSError(domain: "PlayhouseUITests", code: 4, userInfo: [NSLocalizedDescriptionKey: String(cString: sqlite3_errmsg(database))])
            }
        }
    }

    /// Scrolls `scrollView` until `element` sits fully inside it, or, for an element taller than
    /// the scroll view, until its top edge is at the scroll view's top. Custom accessibility
    /// elements, such as one paragraph of a reply's shared text, are not scrolled into view by a
    /// click.
    @discardableResult
    private func scrollFullyIntoView(_ element: XCUIElement, in scrollView: XCUIElement, margin: CGFloat = 8) -> Bool {
        for _ in 0..<40 {
            let viewport = scrollView.frame
            let frame = element.frame
            let delta: CGFloat
            if frame.height > viewport.height {
                let offset = frame.minY - viewport.minY
                if abs(offset) <= 4 { return true }
                delta = -offset
            } else {
                // An element nearly as tall as the viewport fits only with a smaller margin.
                let margin = min(margin, (viewport.height - frame.height) / 2)
                if frame.minY < viewport.minY + margin {
                    delta = viewport.minY + margin - frame.minY
                } else if frame.maxY > viewport.maxY - margin {
                    delta = viewport.maxY - margin - frame.maxY
                } else {
                    return true
                }
            }
            scrollView.scroll(byDeltaX: 0, deltaY: max(-100, min(100, delta)))
        }
        return false
    }

    /// Opening a conversation renders only its newest turn, and older batches load as the
    /// reader scrolls up. Scrolls up as a reader would until every message is rendered, so
    /// an earlier turn can be asserted. The scroll view reports "Showing latest N of M".
    @discardableResult
    private func revealWholeTranscript(timeout: TimeInterval = 20) -> Bool {
        let scrollView = element("conversation-scroll-view")
        func renderedCounts() -> [Int] {
            (scrollView.value as? String ?? "").split(separator: " ").compactMap { Int($0) }
        }
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            let counts = renderedCounts()
            if counts.count == 2, counts[0] == counts[1] { return true }
            scrollView.scroll(byDeltaX: 0, deltaY: 400)
            // A revealed batch restores its anchor asynchronously; scrolling again
            // before it lands would carry past it.
            _ = waitUntil({ renderedCounts() != counts }, timeout: 1)
        }
        let counts = renderedCounts()
        return counts.count == 2 && counts[0] == counts[1]
    }

    /// A user message in the transcript, which is exposed as a labeled group.
    private func transcriptMessage(_ text: String) -> XCUIElement {
