    /// Runs `playhouse-plugin-dev --json` on a plugin folder, sends the commands in order and
    /// returns each command's reply (events such as `loaded` are left out).
    private func runPluginRunner(_ directory: URL, _ commands: [String]) throws -> [[String: Any]] {
        let process = Process()
        process.executableURL = cliURL.deletingLastPathComponent().appendingPathComponent("playhouse-plugin-dev")
        process.arguments = [directory.path, "--json"]
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        process.environment = environment
        let input = Pipe()
        let output = Pipe()
        process.standardInput = input
        process.standardOutput = output
        process.standardError = FileHandle.nullDevice
        try process.run()
        input.fileHandleForWriting.write(Data(((commands + ["quit"]).joined(separator: "\n") + "\n").utf8))
        try input.fileHandleForWriting.close()
        let data = output.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        return String(decoding: data, as: UTF8.self).split(whereSeparator: \.isNewline).compactMap { line in
            guard let object = try? JSONSerialization.jsonObject(with: Data(line.utf8)) as? [String: Any], let command = object["command"] as? String, command != "loaded" else { return nil }
            return object
        }
    }

    /// The elements of a runner `view` reply's tree, depth first.
    private func runnerNodes(_ view: [String: Any]) -> [[String: Any]] {
        func walk(_ node: [String: Any]) -> [[String: Any]] {
            [node] + ((node["children"] as? [[String: Any]]) ?? []).flatMap(walk)
        }
        return (view["tree"] as? [String: Any]).map(walk) ?? []
    }

    /// The number of the first element of a type whose props include `props`.
    private func runnerNodeID(_ nodes: [[String: Any]], type: String, props: [String: String] = [:], file: StaticString = #filePath, line: UInt = #line) throws -> Int {
        let node = nodes.first { node in
            node["type"] as? String == type && props.allSatisfy { (node["props"] as? [String: Any])?[$0.key] as? String == $0.value }
        }
        return try XCTUnwrap(node?["id"] as? Int, "The runner's view has a \(type) \(props).", file: file, line: line)
    }

    private func runCLI(
        _ arguments: [String],
        expectedStatus: Int32 = 0,
        extraEnvironment: [String: String] = [:]
    ) throws -> [String: Any] {
        let process = Process()
        process.executableURL = cliURL
        process.arguments = arguments
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        let usesLiveCodex = isLiveCodexIntegration
        let liveCodexHome = ProcessInfo.processInfo.environment["CODEX_HOME"] ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(".codex").path
        environment["CODEX_HOME"] = usesLiveCodex ? liveCodexHome : dataDirectory.appendingPathComponent("codex-home").path
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        environment.merge(providerExecutableEnvironment, uniquingKeysWith: { _, new in new })
        if let codexFixtureStateDirectory {
            environment["PLAYHOUSE_E2E_FIXTURE_STATE_DIRECTORY"] = codexFixtureStateDirectory.path
        }
        environment.merge(extraEnvironment) { _, override in override }
        process.environment = environment
        let stdout = Pipe()
        let stderr = Pipe()
        process.standardOutput = stdout
        process.standardError = stderr
        try process.run()
        // Drain both pipes while the CLI runs: a reply larger than the pipe
        // buffer (a long history with images) would otherwise block its write
        // while this waits for it to exit.
        var errorData = Data()
        let errorDrained = DispatchSemaphore(value: 0)
        DispatchQueue.global().async {
            errorData = stderr.fileHandleForReading.readDataToEndOfFile()
            errorDrained.signal()
        }
        let output = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        errorDrained.wait()
        process.waitUntilExit()
        let errorOutput = String(data: errorData, encoding: .utf8) ?? ""
        XCTAssertEqual(process.terminationStatus, expectedStatus, "CLI \(arguments) exited unexpectedly: \(output) \(errorOutput)")
        let responseLine = try XCTUnwrap(output.split(whereSeparator: \.isNewline).last, "CLI returned no JSON for \(arguments)")
        let response = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(responseLine.utf8)) as? [String: Any],
            "CLI response was not a JSON object."
        )
        XCTAssertEqual(response["version"] as? Int, 1)
        // `task create` requires a prompt, but most UI cases open the task's conversation and
        // need an empty composer. Fixture creations carry a placeholder prompt that is cleared
        // right away; cases that exercise the saved prompt pass their own text instead.
        if expectedStatus == 0, arguments.starts(with: ["task", "create"]), arguments.contains(Self.fixtureTaskPrompt),
           let createdID = (response["result"] as? [String: Any])?["id"] as? String {
            _ = try runCLI(["task", "prompt", createdID, "--text", ""], extraEnvironment: extraEnvironment)
        }
        return response
    }

    private static let fixtureTaskPrompt = "Fixture task description."

    private func startCLIProcess(
        _ arguments: [String],
        extraEnvironment: [String: String] = [:]
    ) throws -> RunningCLIProcess {
        let process = Process()
        process.executableURL = cliURL
        process.arguments = arguments
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        environment.merge(providerExecutableEnvironment, uniquingKeysWith: { _, new in new })
        environment.merge(extraEnvironment) { _, override in override }
        process.environment = environment
        let stdout = Pipe()
        let stderr = Pipe()
        process.standardOutput = stdout
        process.standardError = stderr
        try process.run()
        return RunningCLIProcess(process: process, stdout: stdout, stderr: stderr)
    }

    private func finishCLIProcess(_ running: RunningCLIProcess, expectedStatus: Int32? = 0) throws -> [String: Any] {
        try finishCLIProcessCapturingEvents(running, expectedStatus: expectedStatus).response
    }

    /// The final response plus every streamed event line printed before it.
    private func finishCLIProcessCapturingEvents(
        _ running: RunningCLIProcess,
        expectedStatus: Int32? = 0
    ) throws -> (response: [String: Any], events: [[String: Any]]) {
        running.process.waitUntilExit()
        let output = String(data: running.stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        let errorOutput = String(data: running.stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        if let expectedStatus {
            XCTAssertEqual(running.process.terminationStatus, expectedStatus, "CLI exited unexpectedly: \(output) \(errorOutput)")
        }
        let responseLine = try XCTUnwrap(output.split(whereSeparator: \.isNewline).last, "CLI returned no JSON response: \(errorOutput)")
        let response = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(responseLine.utf8)) as? [String: Any],
            "CLI response was not a JSON object."
        )
        XCTAssertEqual(response["version"] as? Int, 1)
        let events = output.split(whereSeparator: \.isNewline).dropLast().compactMap {
            try? JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any]
        }
        return (response, events)
    }

    private func startProgressFixtureTurn(
        taskID: String,
        executable: URL
    ) throws -> (process: Process, stdout: Pipe, stderr: Pipe, activeMarker: URL, releaseMarker: URL) {
        let process = Process()
        process.executableURL = cliURL
        process.arguments = ["conversation", "send", taskID, "--message", "Work on this task."]
        var environment = ProcessInfo.processInfo.environment
        environment["PLAYHOUSE_DATA_DIRECTORY"] = dataDirectory.path
        environment["PLAYHOUSE_E2E_DEFAULTS_SUITE"] = preferencesSuiteName
        environment["PLAYHOUSE_BRIDGE_SERVICE_NAME"] = serviceName
        environment["PLAYHOUSE_E2E_CODEX_EXECUTABLE"] = executable.path
        process.environment = environment
        let stdout = Pipe()
        let stderr = Pipe()
        process.standardOutput = stdout
        process.standardError = stderr
        let activeMarker = URL(fileURLWithPath: executable.path + ".turn-active")
        let releaseMarker = URL(fileURLWithPath: executable.path + ".turn-release")
        try? FileManager.default.removeItem(at: activeMarker)
        try? FileManager.default.removeItem(at: releaseMarker)
        try process.run()
        return (
            process, stdout, stderr,
            activeMarker,
            releaseMarker
        )
    }

    private func runGit(_ repository: URL, _ arguments: String...) throws {
        _ = try runGitOutput(repository, arguments)
    }

    private func runGitOutput(_ repository: URL, _ arguments: String...) throws -> String {
        try runGitOutput(repository, arguments)
    }

    private func runGitOutput(_ repository: URL, _ arguments: [String], environment: [String: String] = [:]) throws -> String {
        let directGitPaths = [
            "/opt/homebrew/bin/git",
            "/usr/local/bin/git",
            "/Library/Developer/CommandLineTools/usr/bin/git",
            "/Applications/Xcode.app/Contents/Developer/usr/bin/git"
        ]
        let gitPath = try XCTUnwrap(
            directGitPaths.first { FileManager.default.isExecutableFile(atPath: $0) },
            "UI tests need a direct Git executable; /usr/bin/git uses xcrun and cannot run in the test sandbox."
        )
        let process = Process()
        process.executableURL = URL(fileURLWithPath: gitPath)
        process.arguments = ["-C", repository.path] + arguments
        if !environment.isEmpty {
            process.environment = ProcessInfo.processInfo.environment.merging(environment) { _, new in new }
        }
        let stdout = Pipe()
        let stderr = Pipe()
        process.standardOutput = stdout
        process.standardError = stderr
        try process.run()
        process.waitUntilExit()
        let output = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        let errorOutput = String(data: stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        XCTAssertEqual(process.terminationStatus, 0, "Git failed: \(errorOutput)")
        return output.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func assertCLIError(
        _ response: [String: Any],
        code: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(response["ok"] as? Bool, false, file: file, line: line)
        let error = response["error"] as? [String: Any]
        XCTAssertEqual(error?["code"] as? String, code, file: file, line: line)
    }

    private func chatPageSeparatorIsVisible(_ title: String) -> Bool {
        element("chat-sidebar")
            .descendants(matching: .scrollView)
            .matching(identifier: "conversation-scroll-view")
            .firstMatch
            .staticTexts
            .matching(identifier: "chat-page-separator")
            .allElementsBoundByIndex
            // A static text reports its string as its value.
            .contains { $0.label == title || $0.value as? String == title }
    }

    private func element(_ identifier: String) -> XCUIElement {
        app.descendants(matching: .any).matching(identifier: identifier).firstMatch
    }

    /// The comment popover opens on the Add comment hint, not elsewhere on the selected message:
    /// its field sits just above or below the hint and roughly centered on it. A popover anchored
    /// to the whole text block once opened at the block's top edge, far from a hint lower down.
    /// The popover's arrow shares the hint's "Add comment" label, so it is excluded by identifier.
    private func assertCommentFieldBesideHint(
        _ field: XCUIElement, file: StaticString = #filePath, line: UInt = #line
    ) {
        // An assistant hint takes its prose block's identifier, so it is found by label.
        let hint = app.buttons.matching(NSPredicate(
            format: "label == %@ AND identifier != %@", "Add comment", "add-comment-button"
        )).firstMatch
        XCTAssertTrue(hint.exists, "The Add comment hint should stay while its comment field is open.", file: file, line: line)
        let fieldFrame = field.frame
        let hintFrame = hint.frame
        let verticalGap = min(abs(fieldFrame.midY - hintFrame.minY), abs(fieldFrame.midY - hintFrame.maxY))
        XCTAssertLessThan(verticalGap, 60,
                          "The comment field should open just above or below the Add comment hint (field \(fieldFrame), hint \(hintFrame)).",
                          file: file, line: line)
        XCTAssertLessThan(abs(fieldFrame.midX - hintFrame.midX), 120,
                          "The comment field should open centered on the Add comment hint (field \(fieldFrame), hint \(hintFrame)).",
                          file: file, line: line)
    }

    private func element(withAccessibilityLabel label: String) -> XCUIElement {
        app.descendants(matching: .any)
            .matching(NSPredicate(format: "label == %@", label))
            .firstMatch
    }

    /// Whether a screenshot of `element` has a pixel within a small tolerance of an sRGB color.
    /// The expected color is converted into the screenshot's own color space (the Tart VM's
    /// display profile) and compared with raw pixels; converting each pixel to sRGB instead
    /// shifts it by more than the tolerance.
    private func screenshotContains(srgb expected: (Int, Int, Int), in element: XCUIElement, tolerance: Int = 10) -> Bool {
        let image = element.screenshot().image
        guard let bitmap = image.representations.compactMap({ $0 as? NSBitmapImageRep }).first
                ?? image.tiffRepresentation.flatMap(NSBitmapImageRep.init(data:)),
              let target = NSColor(
                  srgbRed: CGFloat(expected.0) / 255, green: CGFloat(expected.1) / 255,
                  blue: CGFloat(expected.2) / 255, alpha: 1
              ).usingColorSpace(bitmap.colorSpace) else { return false }
        let expected = (Int(round(target.redComponent * 255)), Int(round(target.greenComponent * 255)), Int(round(target.blueComponent * 255)))
        let step = max(1, min(bitmap.pixelsWide, bitmap.pixelsHigh) / 120)
        for y in stride(from: 0, to: bitmap.pixelsHigh, by: step) {
            for x in stride(from: 0, to: bitmap.pixelsWide, by: step) {
                guard let color = bitmap.colorAt(x: x, y: y) else { continue }
                let rgb = (Int(round(color.redComponent * 255)), Int(round(color.greenComponent * 255)), Int(round(color.blueComponent * 255)))
                if abs(rgb.0 - expected.0) <= tolerance, abs(rgb.1 - expected.1) <= tolerance, abs(rgb.2 - expected.2) <= tolerance {
                    return true
                }
            }
        }
        return false
    }

    /// The digits the shell printed between `marker` and a `;` in a terminal's text, latest first.
    /// Row breaks are ignored, since the shell's line editor can leave output on a row that
    /// continues the wrapped command. The echoed command holds `%s` there, never digits, and
    /// the `;` keeps a following prompt from running into the number.
    private func terminalNumber(after marker: String, in terminal: XCUIElement) -> String? {
        guard let text = (terminal.value as? String)?.replacingOccurrences(of: "\n", with: ""),
              let range = text.range(of: marker, options: .backwards) else { return nil }
        let digits = text[range.upperBound...].prefix(while: \.isNumber)
        guard !digits.isEmpty, text[digits.endIndex...].first == ";" else { return nil }
        return String(digits)
    }

    /// The diff header's report of which Monaco load rendered the open diff, and of which
    /// file it rendered, once the editor has finished presenting it.
    private func monacoEditorStatus(timeout: TimeInterval = 10) -> String {
        var status = ""
        _ = waitUntil({
            status = self.element("workspace-diff-editor-status").value as? String ?? ""
            return status.hasPrefix("Editor ")
        }, timeout: timeout)
        return status
    }

    /// The diff text Monaco has actually rendered, which lands after the editor applies it.
    private func renderedDiffValue(timeout: TimeInterval = 10) -> String {
        var value = ""
        _ = waitUntil({
            value = self.element("workspace-diff-editor").value as? String ?? ""
            return value.contains("Original:")
        }, timeout: timeout)
        return value
    }

    /// Hovers the control until its native tooltip becomes visible outside it. Retries with real
    /// mouse-moved events, because AppKit starts the tooltip delay from a move inside the control.
    private func assertNativeHelpText(for element: XCUIElement, equals expected: String) {
        for attempt in 0..<3 {
            // Tooltips only show for the active app's key window.
            app.activate()
            movePointerToHelpRunway(below: element)
            Thread.sleep(forTimeInterval: 1.5)
            // Enter the control, then keep moving inside it: AppKit starts its tooltip delay from
            // a mouse-move within the tracking area, and a single jump in does not always count.
            element.hover()
            for dx in [0.35, 0.65, 0.45, 0.55] {
                Thread.sleep(forTimeInterval: 0.15)
                element.coordinate(withNormalizedOffset: CGVector(dx: dx, dy: 0.5 + CGFloat(attempt) * 0.05)).hover()
            }
            // Real mouse-moved events at the control's position, the way a trackpad delivers them.
            let frame = element.frame
            for step in 0..<6 {
                let point = CGPoint(x: frame.midX - 4 + CGFloat(step % 3) * 4, y: frame.midY + CGFloat(step % 2) * 2)
                CGEvent(mouseEventSource: nil, mouseType: .mouseMoved, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                Thread.sleep(forTimeInterval: 0.1)
            }
            if waitUntil({ self.nativeHelpTextIsVisible(expected) }, timeout: 6) { return }
        }
        XCTFail("Hovering should present the native help text ‘\(expected)’ outside the PR control.")
    }

    /// The tooltip counts as shown only when its own text is on screen: as a help tag in the
    /// accessibility tree, or read off the screen. The control shows only "PR", so the help text
    /// cannot come from anywhere but the tooltip; a changed-pixels check would pass on any update.
    private func nativeHelpTextIsVisible(_ expected: String) -> Bool {
        helpTagIsShowing(expected) || screenTextContains(expected)
    }

    private func screenTextContains(_ expected: String) -> Bool {
        guard let image = XCUIScreen.main.screenshot().image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            return false
        }
        let request = VNRecognizeTextRequest()
        request.recognitionLevel = .accurate
        request.usesLanguageCorrection = false
        try? VNImageRequestHandler(cgImage: image).perform([request])
        // A tooltip wraps across lines, so compare word sequences without line breaks or punctuation.
        func words(_ text: String) -> String {
            text.lowercased()
                .components(separatedBy: CharacterSet.alphanumerics.inverted)
                .filter { !$0.isEmpty }
                .joined(separator: " ")
        }
        let onScreen = words((request.results ?? []).compactMap { $0.topCandidates(1).first?.string }.joined(separator: " "))
        return onScreen.contains(words(expected))
    }

    private func helpTagIsShowing(_ text: String) -> Bool {
        app.descendants(matching: .helpTag)
            .matching(Self.textPredicate(containing: text, caseInsensitive: false, includeTitle: true))
            .firstMatch.exists
    }

    /// Hovers the control with the same real mouse movement as `assertNativeHelpText` and asserts
    /// that no tooltip containing `text` ever appears.
    private func assertNoNativeHelpText(whileHovering element: XCUIElement, containing text: String) {
        app.activate()
        movePointerToHelpRunway(below: element)
        Thread.sleep(forTimeInterval: 1.5)
        element.hover()
        let frame = element.frame
        for step in 0..<6 {
            let point = CGPoint(x: frame.midX - 4 + CGFloat(step % 3) * 4, y: frame.midY + CGFloat(step % 2) * 2)
            CGEvent(mouseEventSource: nil, mouseType: .mouseMoved, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            Thread.sleep(forTimeInterval: 0.1)
        }
        Thread.sleep(forTimeInterval: 2.5)
        XCTAssertFalse(nativeHelpTextIsVisible(text), "Hovering the card should not present a ‘\(text)’ tooltip.")
    }

    private func dismissNativeHelpText(named expected: String) {
        let element = app.descendants(matching: .any)
            .matching(NSPredicate(format: "label CONTAINS %@", expected)).firstMatch
        movePointerToHelpRunway(below: element)
        // A single synthesized move can leave the system tooltip up until the next mouse
        // movement, so keep moving away before concluding that it did not dismiss.
        if !waitUntil({ !self.nativeHelpTextIsVisible(expected) }, timeout: 4) {
            movePointerToHelpRunway(below: element, horizontalShift: -60)
        }
        XCTAssertTrue(waitUntil({ !self.nativeHelpTextIsVisible(expected) }, timeout: 8), "Moving away should dismiss the native help text ‘\(expected)’ outside the PR control.")
    }

    private func movePointerToHelpRunway(below control: XCUIElement, horizontalShift: CGFloat = 0) {
        let window = app.windows.firstMatch
        let windowFrame = window.frame
        let controlFrame = control.frame
        let target = CGPoint(x: controlFrame.midX + horizontalShift, y: min(windowFrame.maxY - 10, controlFrame.maxY + 100))
        let offset = CGVector(
            dx: (target.x - windowFrame.minX) / windowFrame.width,
            dy: (target.y - windowFrame.minY) / windowFrame.height
        )
        window.coordinate(withNormalizedOffset: offset).hover()
    }

    private static func isOrangePixel(_ color: NSColor) -> Bool {
        color.redComponent > 0.45 && color.redComponent > color.greenComponent + 0.08 && color.greenComponent > color.blueComponent + 0.08
    }

    /// Counts pixels matching `matches`, sampling every `step` pixels; 0 when the image cannot be read.
    private func pixelCount(in image: NSImage, step: Int = 1, maxXFraction: CGFloat = 1.0, where matches: (NSColor) -> Bool) -> Int {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else { return 0 }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        var count = 0
        let maxX = Int(CGFloat(cgImage.width) * maxXFraction)
        for x in stride(from: 0, to: maxX, by: step) {
            for y in stride(from: 0, to: cgImage.height, by: step) {
                guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
                if matches(color) { count += 1 }
            }
        }
        return count
    }

    /// Sampled pixels whose summed RGB change exceeds `threshold`; nil when either image is unreadable or the sizes differ.
    private func changedPixelCount(before: NSImage, after: NSImage, step: Int, threshold: CGFloat) -> Int? {
        guard let beforeCG = before.cgImage(forProposedRect: nil, context: nil, hints: nil),
              let afterCG = after.cgImage(forProposedRect: nil, context: nil, hints: nil),
              beforeCG.width == afterCG.width, beforeCG.height == afterCG.height else { return nil }
        let beforeBitmap = NSBitmapImageRep(cgImage: beforeCG)
        let afterBitmap = NSBitmapImageRep(cgImage: afterCG)
        var changed = 0
        for x in stride(from: 0, to: beforeCG.width, by: step) {
            for y in stride(from: 0, to: beforeCG.height, by: step) {
                guard let beforeColor = beforeBitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB),
                      let afterColor = afterBitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
                let delta = abs(beforeColor.redComponent - afterColor.redComponent)
                    + abs(beforeColor.greenComponent - afterColor.greenComponent)
                    + abs(beforeColor.blueComponent - afterColor.blueComponent)
                if delta > threshold { changed += 1 }
            }
        }
        return changed
    }

    /// Checks the user bubble by comparing its colors with each other rather than with exact
    /// values, because an element screenshot's color conversion shifts absolute gray levels.
    /// The fill is the dominant neutral gray and is lighter than the transcript background (read
    /// from the bottom-left timestamp row). The text is much lighter, the left and right edges
    /// carry a lighter stroke, and no blue accent remains.
    private func assertGrayBorderedUserBubble(_ image: NSImage, file: StaticString = #filePath, line: UInt = #line) {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            XCTFail("Could not read user bubble pixels.", file: file, line: line)
            return
        }
        let bitmap = NSBitmapImageRep(cgImage: cgImage)
        func color(_ x: Int, _ y: Int) -> NSColor? { bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) }
        func neutralLuminance(_ color: NSColor) -> CGFloat? {
            let components = [color.redComponent, color.greenComponent, color.blueComponent]
            guard components.max()! - components.min()! < 0.04 else { return nil }
            return components.reduce(0, +) / 3
        }
        var buckets: [Int: Int] = [:]
        var sampled = 0
        var bluePixels = 0
        for x in stride(from: 0, to: cgImage.width, by: 2) {
            for y in stride(from: 0, to: cgImage.height, by: 2) {
                guard let pixel = color(x, y) else { continue }
                sampled += 1
                if pixel.blueComponent > pixel.redComponent + 0.25 && pixel.blueComponent > pixel.greenComponent + 0.1 { bluePixels += 1 }
                if let luminance = neutralLuminance(pixel), luminance < 0.5 { buckets[Int(luminance * 50), default: 0] += 1 }
            }
        }
        XCTAssertEqual(bluePixels, 0, "User messages should no longer render a blue accent bubble.", file: file, line: line)
        guard let (fillBucket, fillCount) = buckets.max(by: { $0.value < $1.value }),
              let background = color(2, cgImage.height - 2).flatMap(neutralLuminance) else {
            XCTFail("The user bubble should have a neutral gray fill over a neutral background.", file: file, line: line)
            return
        }
        let fill = (CGFloat(fillBucket) + 0.5) / 50
        XCTAssertGreaterThan(Double(fillCount) / Double(max(sampled, 1)), 0.3,
                             "The gray fill should dominate the user bubble.", file: file, line: line)
        XCTAssertGreaterThan(fill, background + 0.05,
                             "The bubble fill (\(fill)) should be a lighter gray than the transcript background (\(background)).",
                             file: file, line: line)
        let lightText = pixelCount(in: image, step: 2) { neutralLuminance($0).map { $0 > fill + 0.4 } ?? false }
        XCTAssertGreaterThan(lightText, 20, "User message text should stay light on the gray bubble.", file: file, line: line)
        func edgeIsStroked(_ y: Int, _ xs: [Int]) -> Bool {
            xs.contains { x in color(x, y).flatMap(neutralLuminance).map { $0 > fill + 0.05 && $0 < fill + 0.3 } ?? false }
        }
        let rows = stride(from: cgImage.height * 15 / 100, to: cgImage.height * 65 / 100, by: max(1, cgImage.height / 20))
        let edge = 0..<min(6, cgImage.width)
        XCTAssertTrue(rows.contains { edgeIsStroked($0, Array(edge)) && edgeIsStroked($0, edge.map { cgImage.width - 1 - $0 }) },
                      "The user bubble should have a thin light border on both sides of its gray fill.", file: file, line: line)
    }

    private func orangePixelCount(in screenshot: XCUIScreenshot) -> Int {
        pixelCount(in: screenshot.image, where: Self.isOrangePixel)
    }

    private func darkPixelCount(in element: XCUIElement) -> Int {
        pixelCount(in: element.screenshot().image) { $0.redComponent < 0.3 && $0.greenComponent < 0.3 && $0.blueComponent < 0.3 }
    }

    private func lightPixelCount(in element: XCUIElement) -> Int {
        pixelCount(in: element.screenshot().image) { $0.redComponent > 0.68 && $0.greenComponent > 0.68 && $0.blueComponent > 0.68 }
    }

    private func orangePixelFillRatio(in screenshot: XCUIScreenshot) -> Double {
        guard let image = screenshot.image.cgImage(forProposedRect: nil, context: nil, hints: nil) else { return 0 }
        let bitmap = NSBitmapImageRep(cgImage: image)
        var count = 0
        var minX = bitmap.pixelsWide
        var maxX = 0
        var minY = bitmap.pixelsHigh
        var maxY = 0
        for x in 0..<bitmap.pixelsWide {
            for y in 0..<bitmap.pixelsHigh {
                guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB) else { continue }
                if Self.isOrangePixel(color) {
                    count += 1
                    minX = min(minX, x); maxX = max(maxX, x)
                    minY = min(minY, y); maxY = max(maxY, y)
                }
            }
        }
        guard count > 0 else { return 0 }
        let area = max(1, (maxX - minX + 1) * (maxY - minY + 1))
        return Double(count) / Double(area)
    }

    private func assertHoverEmphasis(for element: XCUIElement, file: StaticString = #filePath, line: UInt = #line) {
        // The pointer may already rest on this control from an earlier step (a relaunch keeps the
        // pointer still while the card re-renders under it), so park it elsewhere before sampling.
        app.windows.firstMatch.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.97)).hover()
        Thread.sleep(forTimeInterval: 0.3)
        let before = element.screenshot().image
        // XCTest cannot read NSCursor.current from the app process; hover inside the padded edge to verify that region receives hover events.
        element.coordinate(withNormalizedOffset: CGVector(dx: 0.05, dy: 0.5)).hover()
        Thread.sleep(forTimeInterval: 0.2)
        let after = element.screenshot().image
        guard let changedPixels = changedPixelCount(before: before, after: after, step: max(1, Int(before.size.width) / 40), threshold: 0.08) else {
            XCTFail("Could not read control screenshots to verify hover emphasis.", file: file, line: line)
            return
        }
        XCTAssertGreaterThan(changedPixels, 5, "Hovering the control should visibly change its appearance.", file: file, line: line)
    }

    private func element(containingAccessibilityText text: String) -> XCUIElement {
        app.descendants(matching: .any)
            .matching(Self.textPredicate(containing: text, caseInsensitive: true))
            .firstMatch
    }

    /// Element types whose accessibility value is a number, not text.
    private static let numericValueElementTypes: [UInt] = ([
        .scrollBar, .valueIndicator, .slider, .progressIndicator, .activityIndicator, .levelIndicator,
        .ratingIndicator, .checkBox, .radioButton, .switch, .toggle, .stepper, .incrementArrow, .disclosureTriangle, .splitter,
    ] as [XCUIElement.ElementType]).map(\.rawValue)

    /// Matches an element whose label, text value, or (optionally) title contains `text`.
    /// `value CONTAINS` raises inside the app on a numeric value, such as the board's
    /// horizontal scroll bar, and that aborts the whole query until it times out, so a
    /// value is compared only on element types whose value is text.
    private static func textPredicate(containing text: String, caseInsensitive: Bool, includeTitle: Bool = false) -> NSPredicate {
        let contains = caseInsensitive ? "CONTAINS[c]" : "CONTAINS"
        let format = "label \(contains) %@ OR (NOT (elementType IN %@) AND value \(contains) %@)" + (includeTitle ? " OR title \(contains) %@" : "")
        let arguments: [Any] = includeTitle ? [text, numericValueElementTypes, text, text] : [text, numericValueElementTypes, text]
        return NSPredicate(format: format, argumentArray: arguments)
    }

    private func accessibleLabelOrValue(of element: XCUIElement) -> String {
        if !element.label.isEmpty { return element.label }
        return element.value as? String ?? ""
    }

    private func waitForDisappearance(_ element: XCUIElement, timeout: TimeInterval = 5) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if !element.exists { return true }
            Thread.sleep(forTimeInterval: 0.05)
        }
        return !element.exists
    }

    private func attachScreenshot(named name: String, fullScreen: Bool = false) {
        let screenshot = fullScreen ? XCUIScreen.main.screenshot() : app.screenshot()
        let attachment = XCTAttachment(screenshot: screenshot)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    private func assertScreenshotIfVisible(named name: String) {
        attachScreenshot(named: name)
    }

    private static func findAppBundle() throws -> URL {
        var directory = Bundle(for: PlayhouseUITests.self).bundleURL
        for _ in 0..<8 {
            let candidate = directory.appendingPathComponent("Playhouse.app", isDirectory: true)
            if FileManager.default.fileExists(atPath: candidate.path) {
                return candidate
            }
            directory.deleteLastPathComponent()
        }
        throw NSError(domain: "PlayhouseUITests", code: 1, userInfo: [
            NSLocalizedDescriptionKey: "Couldn't locate the app bundle beside the UI test runner."
        ])
    }
}

private struct WorkspaceFixture {
    static let root = URL(fileURLWithPath: "/tmp/playhouse-ui-test-fixtures", isDirectory: true)
    static let ownerMarker = ".playhouse-bridge-fixture"
    static let ownerContents = "Playhouse bridge tests own this deterministic fixture (v1).\n"

    let parent: URL
    let primary: URL
    let secondary: URL
    let alternate: URL
    let alternateParent: URL
    let custom: URL
    let changes: URL
    let missing: URL
    let nested: URL
    let linkedOutside: URL
    let existingWorktree: URL
    let emptyGitRepository: URL

    static func load() throws -> WorkspaceFixture {
        let marker = root.appendingPathComponent(ownerMarker)
        guard let contents = try? String(contentsOf: marker, encoding: .utf8), contents == ownerContents else {
            throw NSError(domain: "PlayhouseUITests", code: 2, userInfo: [
                NSLocalizedDescriptionKey: "The deterministic Git fixtures are missing or not owned by Playhouse. Run scripts/test-ui.sh first."
            ])
        }
        let parent = root.appendingPathComponent("suggested-parent", isDirectory: true)
        let locations: [String: URL] = [
            "parent": parent,
            "primary": parent.appendingPathComponent("primary", isDirectory: true),
            "secondary": parent.appendingPathComponent("group/secondary", isDirectory: true),
            "alternateParent": parent.appendingPathComponent("alternate-parent", isDirectory: true),
            "alternate": parent.appendingPathComponent("alternate-parent/alternate", isDirectory: true),
            "custom": parent.appendingPathComponent("custom-folder", isDirectory: true),
            "changes": parent.appendingPathComponent("changes", isDirectory: true),
            "emptyGitRepository": root.appendingPathComponent("empty-git-repo", isDirectory: true),
            "nested": parent.appendingPathComponent("primary/nested", isDirectory: true),
            "linkedOutside": parent.appendingPathComponent("linked-outside", isDirectory: true)
        ]
        for (name, url) in locations where name != "linkedOutside" {
            guard FileManager.default.fileExists(atPath: url.path) else {
                throw NSError(domain: "PlayhouseUITests", code: 3, userInfo: [
                    NSLocalizedDescriptionKey: "Missing \(name) fixture folder at \(url.path)."
                ])
            }
        }
        return WorkspaceFixture(
            parent: parent,
            primary: locations["primary"]!,
            secondary: locations["secondary"]!,
            alternate: locations["alternate"]!,
            alternateParent: locations["alternateParent"]!,
            custom: locations["custom"]!,
            changes: locations["changes"]!,
            missing: parent.appendingPathComponent("missing", isDirectory: true),
            nested: locations["nested"]!,
            linkedOutside: locations["linkedOutside"]!,
            existingWorktree: root.appendingPathComponent("existing-worktree", isDirectory: true),
            emptyGitRepository: locations["emptyGitRepository"]!
        )
    }

}
